window.CPE_LEARN.ta = {"intro":"முதலில் காகிதம் / டெமோவுடன் பயிற்சி செய்யுங்கள். மெழுகுவர்த்திகள், விளக்கப்படங்கள், BB/RSI/Fib, பணம், உளவியல் — பிறகு சிக்னல்கள் (வாங்க/விற்க/பிடிப்பது என்றால் + என்ன செய்வது) மற்றும் அந்நிய செலாவணி சமிக்ஞைகளைப் படிக்கவும். நேரலைக்கு சரியான இயங்குதள API விசை தேவை (திரும்பப் பெறுதல்கள் முடக்கம்).","candles":[{"shape":"doji","name":"டோஜி","color":"#94a3b8","bias":"நடுநிலை / காத்திரு","tip":"திற ≈ மூடு - குறுக்கு அல்லது மெல்லிய உடல். ஒரு நகர்வுக்குப் பிறகு சந்தை உறுதியற்ற தன்மை.","also":"மேலும் கற்பிக்கிறது: FOMO வேண்டாம். அடுத்த மெழுகுவர்த்திக்காக காத்திருங்கள். BB தீவிரம் + டோஜிக்கு அருகில் = கருத்துகளின் சுருக்கம்; திசையை யூகிக்கும் முன் RSI சாய்வைச் சரிபார்க்கவும்."},{"shape":"hammer","name":"சுத்தி","color":"#22c55e","bias":"சார்பு வாங்கு","tip":"மேலே சிறிய உடல், ஒரு துளி பிறகு நீண்ட கீழ் விக் (≈2× உடல்) - வாங்குபவர்கள் குறைந்த விலையை நிராகரித்தனர்.","also":"மேலும்: விக் லோவின் கீழ் SL பயிற்சியை வைக்கவும். குறைந்த பிபி + ஆர்எஸ்ஐ அதிகமாக விற்கப்பட்டதில் இருந்து உயர்கிறது. உளவியல்: விக் முடிப்பதற்கு பொறுமை - நடுவில் விக்கினை வாங்க வேண்டாம்."},{"shape":"invhammer","name":"தலைகீழ் சுத்தியல்","color":"#22c55e","bias":"வாங்க (பலவீனமான)","tip":"கீழே நீண்ட மேல் விக். வாங்குபவர்கள் அதிகமாக ஆய்வு செய்தனர் ஆனால் திறந்த நிலையில் மூடப்பட்டனர் - அடுத்த பச்சை நிறத்தை உறுதிப்படுத்த வேண்டும்.","also":"மேலும்: சுத்தியலை விட பலவீனமானது. எச்சரிக்கையாகப் பயன்படுத்தவும், நுழைவு அல்ல. ஃபிப் 61.8 பவுன்ஸ் + தலைகீழ் சுத்தியல் = மெழுகுவர்த்தியை உறுதிப்படுத்தும் வரை மட்டுமே ஆய்வு மண்டலம்."},{"shape":"shooting","name":"ஷூட்டிங் ஸ்டார்","color":"#ef4444","bias":"சார்பு விற்பனை","tip":"சிறிய உடல் கீழே, ஒரு உயர்வு பிறகு நீண்ட மேல் விக் - விற்பனையாளர்கள் உயர்வை நிராகரித்தனர்.","also":"மேலும்: விக் ஹைக்கு மேல் எஸ்.எல். மேல் BB / Fib நீட்டிப்பு / RSI ஓவர்பாட் அருகில் வலுவானது. கற்பிக்கிறது: நிலவு மெழுகுவர்த்திகள் தோல்வியடையும் - கடைசி பச்சை நிறத்தை துரத்த வேண்டாம்."},{"shape":"hanging","name":"தொங்கும் மனிதன்","color":"#f59e0b","bias":"எச்சரிக்கையுடன் விற்கவும்","tip":"சுத்தியல் போல் தெரிகிறது ஆனால் ஒரு எழுச்சிக்குப் பிறகு தோன்றும் — சாத்தியமான மேல் சோர்வு.","also":"மேலும்: சூழல் என்பது எல்லாமே (ஒரே வடிவம் ≠ அதே வர்த்தகம்). பத்திரிகை இருப்பிடம்: மேல் மற்றும் கீழ். உளவியல்: வடிவம் பொருந்துகிறது என்பதற்காக தலைகீழாக மாறாதீர்கள் - அடுத்த மெழுகுவர்த்தி + RSI மூலம் உறுதிப்படுத்தவும்."},{"shape":"engulf_bull","name":"புல்லிஷ் என்கல்ஃபிங்","color":"#22c55e","bias":"வாங்க","tip":"பச்சை நிற உடல் முந்தைய சிவப்பு உடலை முழுமையாக உள்ளடக்கியது - வாங்குபவர்கள் ஒரு பட்டியில் கட்டுப்பாட்டை எடுத்தனர்.","also":"மேலும்: ஆதரவு / குறைந்த BB / Fib 50–61.8 இல் வலுவானது. SL ஆக குறைந்த அளவிலிருந்து அளவு. பண உதவிக்குறிப்பு: பரந்த engulfing உடல் → பரந்த SL → சிறிய அளவு."},{"shape":"engulf_bear","name":"கரடி இங்கல்ஃபிங்","color":"#ef4444","bias":"விற்கவும்","tip":"சிவப்பு உடல் முழுவதும் முந்தைய பச்சை நிறத்தை உள்ளடக்கியது - விற்பனையாளர்கள் ஆதிக்கம் செலுத்தினர்.","also":"மேலும்: திறந்த நீளங்களில் எச்சரிக்கை. அருகில் மேல் BB + RSI>70 = உயர் படிப்பு தரம். ஆபத்தை கற்பிக்கிறது: ஏற்கனவே நீண்டதாக இருந்தால், நம்பிக்கைக்கு பதிலாக பகுதி TP / trail."},{"shape":"morning","name":"காலை நட்சத்திரம்","color":"#22c55e","bias":"வாங்க","tip":"3 மெழுகுவர்த்திகள்: பெரிய சிவப்பு → சிறிய நட்சத்திரம் → பெரிய பச்சை. கீழே தலைகீழ் கதை.","also":"மேலும்: பல மெழுகுவர்த்தி பொறுமை. 3வது மூடிய பிறகு உள்ளிடவும்; SL குறைந்த நட்சத்திரம். BB லோயர் + புல்லிஷ் RSI வேறுபாட்டுடன் நன்றாக இணைகிறது."},{"shape":"evening","name":"மாலை நட்சத்திரம்","color":"#ef4444","bias":"விற்கவும்","tip":"3 மெழுகுவர்த்திகள்: பெரிய பச்சை → சிறிய நட்சத்திரம் → பெரிய சிவப்பு. சிறந்த தலைகீழ் கதை.","also":"மேலும்: நடு நட்சத்திரத்தை மட்டும் சுருக்க வேண்டாம். 3வது நெருக்கமாக காத்திருங்கள். மேல் BB / Fib நீட்டிப்பு சங்கமம். உளவியல்: முதல் பச்சை ஓட்டத்தின் FOMO ஐ புறக்கணிக்கவும்."},{"shape":"maru_bull","name":"காளை மருபோசு","color":"#22c55e","bias":"வலுவான வாங்க அழுத்தம்","tip":"நீண்ட பச்சை உடல், கிட்டத்தட்ட விக்ஸ் இல்லை - வாங்குபவர்கள் திறந்த-மூட கட்டுப்பாட்டில்.","also":"மேலும்: போக்கு தொடர்ச்சி குறிப்பு, எப்போதும் கீழே வாங்க முடியாது. வாக்-தி-பேண்ட் சாத்தியம். ஆபத்து: பிபி மிட் / ஃபைபிற்கு இழுக்காமல் தாமதமாக மருபோசுவைத் துரத்துவது."},{"shape":"maru_bear","name":"கரடி மருபோசு","color":"#ef4444","bias":"வலுவான விற்பனை அழுத்தம்","tip":"நீண்ட சிவப்பு உடல், கிட்டத்தட்ட விக்ஸ் இல்லை - விற்பனையாளர்கள் கட்டுப்பாட்டில்.","also":"மேலும்: விழும் கத்திகளைப் பிடிக்காதீர்கள். BB/Fib பவுன்ஸ் + சுத்தியல் பிறகு காத்திருக்கவும். கற்பிக்கிறது: வலுவான அழுத்தம் = சிறிய அளவு அல்லது ஒதுங்கி நிற்கவும்."},{"shape":"spin","name":"ஸ்பின்னிங் டாப்","color":"#94a3b8","bias":"தீர்மானமின்மை","tip":"சிறிய உடல், மேல் + கீழ் விக்ஸ் - இரு தரப்பினரும் சண்டையிட்டனர், யாரும் தெளிவாக வெற்றி பெறவில்லை.","also":"மேலும்: உள்ளே BB அடிக்கடி அழுத்தவும். வர்த்தகத்தை இடைநிறுத்துதல்; காத்திரு இடைவேளை + திசை மெழுகுவர்த்தி. உளவியல் பாடம்: சந்தை \"எதுவும் செய்ய முடியாது\" - பிளாட் என்பது சரியான தேர்வாகும்."},{"shape":"pierce","name":"துளையிடும் வரி","color":"#22c55e","bias":"வாங்க","tip":"சிவப்பு பின்னர் பச்சை, அது கீழே திறக்கும் ஆனால் முந்தைய சிவப்பு நிறத்தின் நடுப்புள்ளிக்கு மேல் மூடப்படும்.","also":"மேலும்: Engulfing விட மென்மையானது. RSI திருப்பத்துடன் உறுதிப்படுத்தவும். பகுதி வலிமை வாசிப்புக்கு நல்ல காகித பயிற்சி — எல்லா கீரைகளும் சமமாக இருக்காது."},{"shape":"darkcloud","name":"டார்க் மேகக் கவர்","color":"#ef4444","bias":"விற்கவும்","tip":"பச்சை பின்னர் சிவப்பு, அது மேலே திறக்கும் ஆனால் முந்தைய பச்சையின் நடுப்பகுதிக்கு கீழே மூடப்படும்.","also":"மேலும்: கரடி முழுவதுமாக மூழ்கும் முன் எச்சரிக்கை. பாதை நீண்டது / TP1 ஐ எடுத்துக் கொள்ளுங்கள். முழு தலைகீழ் அச்சுக்கு முன் அளவிடுதல் கற்றுக்கொடுக்கிறது."},{"shape":"soldiers","name":"மூன்று வெள்ளை வீரர்கள்","color":"#22c55e","bias":"வாங்கும் போக்கு","tip":"அதிக மூடுதல்களுடன் மூன்று உயரும் கீரைகள் - நிலையான வாங்குதல்.","also":"மேலும்: வலுவான அப்டிரெண்ட் குறி; Fib 38–50 அல்லது BB mid க்கு இழுப்பது நடைமுறையில் சேர்க்கிறது. 3 கீரைகளுக்குப் பிறகு அதிக நம்பிக்கை ஆபத்து - அபாயத்தை% சரிசெய்து கொள்ளுங்கள்."},{"shape":"crows","name":"மூன்று கருப்பு காகங்கள்","color":"#ef4444","bias":"விற்பனை போக்கு","tip":"லோயர் க்ளோஸுடன் மூன்று வீழ்ச்சி சிவப்பு - நிலையான விற்பனை.","also":"மேலும்: சராசரியை குறைக்க வேண்டாம். காத்திருப்பு அமைப்பு. ஆர்எஸ்ஐ ஓவர்செல்ட் அதிகமாக விற்பனையாகி இருக்கலாம் — பண விதி: இழப்பு வரம்பு > நம்பிக்கை."},{"shape":"harami_bull","name":"புல்லிஷ் ஹராமி","color":"#22c55e","bias":"வாங்கு (மென்மையானது)","tip":"பெரிய சிவப்பு, பின்னர் முன் உடல் உள்ளே சிறிய பச்சை - விற்பனை அழுத்தம் சுருங்குகிறது.","also":"மேலும்: ஆரம்ப இடைநிறுத்த சமிக்ஞை. உறுதிப்படுத்த வேண்டும். RSI புல்லிஷ் டைவர்ஜென்ஸ் படிப்புடன் இணைகிறது. தலைகீழாக மட்டுமல்லாமல் \"வலிமை மங்குவதை\" படிக்க கற்றுக்கொடுக்கிறது."},{"shape":"harami_bear","name":"கரடி ஹராமி","color":"#ef4444","bias":"விற்க (மென்மையான)","tip":"பெரிய பச்சை, பின்னர் சிறிய சிவப்பு - வாங்கும் அழுத்தம் சுருங்குகிறது.","also":"மேலும்: நீளங்களில் பகுதிகளை எடுத்துக் கொள்ளுங்கள். தானாக குறுகியது அல்ல. உளவியல்: பெரிய பச்சைக்குப் பிறகு பேராசை பெரும்பாலும் ஹராமி எச்சரிக்கையை புறக்கணிக்கிறது."},{"shape":"tweezer_bot","name":"ட்வீசர் பாட்டம்","color":"#22c55e","bias":"வாங்க","tip":"பொருந்தக்கூடிய தாழ்வுடன் இரண்டு மெழுகுவர்த்திகள் - ஆதரவின் இரட்டை சோதனை.","also":"மேலும்: குறைந்த கட்டமைப்பைக் குறிக்கவும். எஸ்.எல். Fib/BB சீரமைப்பு உதவுகிறது. டபுள் பாட்டமின் சார்ட் பேட்டர்ன் கசின் — அதே ஆதரவு பாடம்."},{"shape":"tweezer_top","name":"சாமணம் மேல்","color":"#ef4444","bias":"விற்கவும்","tip":"பொருந்தக்கூடிய அதிகபட்சத்துடன் இரண்டு மெழுகுவர்த்திகள் - எதிர்ப்பின் இரட்டை சோதனை.","also":"மேலும்: குறி எதிர்ப்பு. டபுள் டாப்பின் உறவினர். உயர்மட்டத்தில் RSI தோல்வி = சங்கமம். கற்பிக்கிறது: ஒரே விலை இரண்டு முறை நிராகரிக்கப்பட்டது = அளவை மதிக்கவும்."},{"shape":"longlegged","name":"நீண்ட கால் டோஜி","color":"#94a3b8","bias":"தீர்மானமின்மை","tip":"மிக நீளமான மேல் மற்றும் கீழ் விக்ஸ் சிறிய உடலுடன் — வன்முறையான இருவழிச் சண்டை, அது தொடங்கிய இடத்திலேயே முடிந்தது.","also":"மேலும்: ஒரு பெரிய நகர்வு அடிக்கடி பின்தொடர்கிறது, ஆனால் திசை தெரியவில்லை - இடைவேளை மெழுகுவர்த்திக்காக காத்திருங்கள். கற்பிக்கிறது: அதிக ஏற்ற இறக்கம் அதிக உறுதி இல்லை."},{"shape":"dragonfly","name":"டிராகன்ஃபிளை டோஜி","color":"#22c55e","bias":"சார்பு வாங்கு","tip":"திறந்த = நெருங்கிய = உயர், ஒரு நீண்ட கீழ் விக் கொண்டு - விற்பனையாளர்கள் கீழே தள்ளப்பட்டது மற்றும் வாங்குபவர்கள் அதை நேராக மீண்டும் மேலே அறைந்தனர்.","also":"மேலும்: ஆதரவில் வலுவானது / ஒரு துளிக்குப் பிறகு குறைந்த பிபி. விக் டெயிலின் கீழ் எஸ்.எல். கற்பிக்கிறது: நிராகரிப்பு ஒரு கதை, உத்தரவாதம் அல்ல - அடுத்த மெழுகுவர்த்தியை உறுதிப்படுத்தவும்."},{"shape":"gravestone","name":"கல்லறை டோஜி","color":"#ef4444","bias":"சார்பு விற்பனை","tip":"திறந்த = நெருங்கிய = தாழ்வான, நீண்ட மேல் திரியுடன் - வாங்குபவர்கள் மேலே தள்ளப்பட்டனர் மற்றும் விற்பனையாளர்கள் அதை மீண்டும் கீழே இழுத்தனர்.","also":"மேலும்: எதிர்ப்பில் வலுவானது / மேல் BB / RSI overbought. டிராகன்ஃபிளையின் கண்ணாடி. கற்பிக்கிறது: ஒரு ஸ்பைக் உயர் குறைந்த நிலையில் மூடுவது தோல்வியடைந்த பிரேக்அவுட் ஆகும்."},{"shape":"inside_bar","name":"உள்ளே பார்","color":"#94a3b8","bias":"சுருள் / காத்திரு","tip":"இரண்டாவது மெழுகுவர்த்தி முதலில் உள்ளே முழுமையாக அமர்ந்திருக்கிறது - வரம்பு அழுத்துகிறது மற்றும் சந்தை அதன் மூச்சை வைத்திருக்கிறது.","also":"மேலும்: மதர் பட்டியின் முறிவு தூண்டுதலாகும் - இடைவேளையின் திசையில் வர்த்தகம். பிபி அழுத்தத்துடன் இணைகிறது. கற்பிக்கிறது: சுருக்கம் விரிவாக்கத்திற்கு முன் வருகிறது."},{"shape":"outside_bar","name":"வெளியே பார்","color":"#22c55e","bias":"பிரேக்அவுட் / தலைகீழ்","tip":"இரண்டாவது மெழுகுவர்த்தியானது முதல் மெழுகுவர்த்தியை உயர்விலிருந்து தாழ்வாகச் சூழ்ந்து கொள்கிறது - ஒரு பட்டியின் உள்ளே ஒரு வன்முறையான கையகப்படுத்தல்.","also":"மேலும்: திசை = வெளிப்புறப் பட்டை மூடும் இடம். பெரிய பட்டை என்றால் பெரிய எஸ்எல் என்று பொருள், அதனால் அளவு சிறியது. கற்பிக்கிறது: ஒரு பட்டியில் கடைசி மூன்றை அழிக்க முடியும்."},{"shape":"belt_bull","name":"புல்லிஷ் பெல்ட் ஹோல்ட்","color":"#22c55e","bias":"வாங்க","tip":"குறைந்த விக் இல்லாமல் குறைந்த அளவில் திறந்து பச்சை நிறத்தில் இயங்குகிறது - வாங்குபவர்கள் முதல் டிக் இருந்தே கட்டுப்பாட்டை எடுத்துக்கொண்டனர்.","also":"மேலும்: ஒரு இடைவெளிக்குப் பிறகு வலுவாக அல்லது நேராக ஆதரவாக. திறந்த கீழ் எஸ்.எல். கற்பிக்கிறது: ஒரு தொடக்க இயக்கி உண்மையான நோக்கத்தைக் காட்டுகிறது."},{"shape":"belt_bear","name":"பேரிஷ் பெல்ட் பிடி","color":"#ef4444","bias":"விற்கவும்","tip":"மேல் விக் இல்லாமல் உயரத்தில் திறந்து சிவப்பு நிறத்தில் ஓடுகிறது - விற்பனையாளர்கள் அதை திறந்த நிலையில் இருந்து கட்டுப்படுத்தினர்.","also":"மேலும்: ஒரு இடைவெளிக்குப் பிறகு அல்லது எதிர்ப்பின் போது வலிமையானது. பாதை நீண்டது. கற்பிக்கிறது: முதல் நகர்வு முழு நாளையும் அமைக்கலாம்."},{"shape":"kick_bull","name":"புல்லிஷ் கிக்கர்","color":"#22c55e","bias":"வலுவான வாங்குதல்","tip":"ஒரு சிவப்பு மெழுகுவர்த்தி, பின்னர் ஒரு பச்சை மெழுகுவர்த்தியில் ஒரு இடைவெளி - மூடப்படுவதற்கு இடையே மனநிலை புரட்டப்பட்டது.","also":"மேலும்: அரிதான மற்றும் சக்திவாய்ந்த; இடைவெளி தேவை, ஒன்றுடன் ஒன்று அனுமதிக்கப்படாது. கற்பிக்கிறது: சந்தை தூங்கும்போது உணர்வு புரட்டலாம்."},{"shape":"kick_bear","name":"பேரிஷ் கிக்கர்","color":"#ef4444","bias":"வலுவான விற்பனை","tip":"ஒரு பச்சை மெழுகுவர்த்தி, பின்னர் ஒரு சிவப்பு மெழுகுவர்த்தியில் ஒரு இடைவெளி - வாங்குபவர்கள் மூடுவதற்கு இடையில் மறைந்தனர்.","also":"மேலும்: வெளியேறு வேகமாக உள்ளது — உதைப்பவர்கள் உங்களுக்காக காத்திருக்க மாட்டார்கள். கற்பிக்கிறது: நீங்கள் தொலைவில் இருக்கும்போது ஒரு இடைவெளி என்பது சந்தையை மறுபரிசீலனை செய்கிறது."},{"shape":"abandoned","name":"புல்லிஷ் கைவிடப்பட்ட குழந்தை","color":"#22c55e","bias":"வலுவான வாங்குதல்","tip":"ஒரு சிவப்பு மெழுகுவர்த்தி, ஒரு இடைவெளி-கீழே டோஜி, பின்னர் ஒரு இடைவெளியில் பச்சை மெழுகுவர்த்தி - சந்தேகத்திற்கு இடமில்லாத ஒரு தனிமையான தீவு.","also":"மேலும்: டோஜி இருபுறமும் இடைவெளி விட்டு இருக்க வேண்டும். அரிதான ஆனால் அடிப்பகுதியில் உயர் தரம். கற்றுக்கொடுக்கிறது: எல்லோரும் விட்டுக்கொடுக்கும் இடத்தில் தலைகீழ் மாற்றங்கள் தொடங்கும்."},{"shape":"three_inside_up","name":"மூன்று உள்ளே மேலே","color":"#22c55e","bias":"வாங்க","tip":"புல்லிஷ் ஹராமி மற்றும் மூன்றாவது பச்சை நிற மெழுகுவர்த்தி முதல் மேலே மூடப்பட்டது - உள்ளே உள்ள பட்டை இறுதியாக உடைந்தது.","also":"மேலும்: உறுதிப்படுத்தப்பட்ட ஹராமி வெற்று ஒன்றை விட மிகவும் வலிமையானது. ஹராமி குறைந்த கீழ் எஸ்.எல். கற்பிக்கிறது: உறுதிப்படுத்தல் கணிப்பை துடிக்கிறது."},{"shape":"three_inside_down","name":"மூன்று உள்ளே கீழே","color":"#ef4444","bias":"விற்கவும்","tip":"கரடி ஹராமி மற்றும் மூன்றாவது சிவப்பு மெழுகுவர்த்தி முதல் கீழே மூடியது - உள் பட்டை உடைந்தது.","also":"மேலும்: மூன்றாவது மூடியவுடன் நீளங்களை வெட்டுங்கள். கற்பிக்கிறது: தோல்வியுற்ற இடைநிறுத்தம் பழைய போக்கை மீண்டும் தொடரலாம்."},{"shape":"three_methods_bull","name":"ரைசிங் மூன்று முறைகள்","color":"#22c55e","bias":"வாங்கும் போக்கு","tip":"ஒரு நீண்ட பச்சை மெழுகுவர்த்தி, அதன் உள்ளே மூன்று சிறிய சிவப்பு, பின்னர் மற்றொரு நீண்ட பச்சை - ஒரு எழுச்சி உள்ளே ஓய்வு.","also":"மேலும்: இடைநிறுத்தம் முதல் மெழுகுவர்த்தி வரம்பை விட்டு வெளியேறாது, எனவே போக்கு அமைதியாக உள்ளது. கடைசி மெழுகுவர்த்தியின் உடைப்பை வர்த்தகம் செய்யுங்கள். கற்பிக்கிறது: போக்குகள் உடைக்காமல் ஓய்வெடுக்கின்றன."},{"shape":"three_methods_bear","name":"வீழ்ச்சி மூன்று முறைகள்","color":"#ef4444","bias":"விற்பனை போக்கு","tip":"ஒரு நீண்ட சிவப்பு மெழுகுவர்த்தி, அதன் உள்ளே மூன்று சிறிய கீரைகள், பின்னர் மற்றொரு நீண்ட சிவப்பு - ஒரு வீழ்ச்சி உள்ளே ஓய்வு.","also":"மேலும்: ரைசிங் மூன்று முறைகளின் கண்ணாடி. சிறிய கீரைகள் வாங்க வேண்டாம் - அவர்கள் சத்தம். கற்பிக்கிறது: ஒரு வரம்பிற்குள் இழுப்பது தலைகீழாக இல்லை."},{"shape":"tower_bot","name":"டவர் பாட்டம்","color":"#22c55e","bias":"தலைகீழ் வாங்கு","tip":"ஒரு நீண்ட சிவப்பு மெழுகுவர்த்தி, சிறிய மெழுகுவர்த்திகளின் கொத்து, பின்னர் ஒரு நீண்ட பச்சை - மனநிலை ஒரு தட்டையான அடித்தளத்தில் மாறுகிறது.","also":"மேலும்: பிளாட் நடுத்தர போர் மற்றும் கடைசி மெழுகுவர்த்தி வெற்றியை அறிவிக்கிறது. கற்பிக்கிறது: அடிப்படைகள் நேரம் எடுக்கும்."},{"shape":"tower_top","name":"டவர் டாப்","color":"#ef4444","bias":"தலைகீழ் விற்பனை","tip":"ஒரு நீண்ட பச்சை மெழுகுவர்த்தி, சிறிய மெழுகுவர்த்திகளின் கொத்து, பின்னர் ஒரு நீண்ட சிவப்பு - வாங்குபவர்கள் தீர்ந்துவிடும் மற்றும் விற்பனையாளர்கள் எடுத்துக்கொள்கிறார்கள்.","also":"மேலும்: டவர் பாட்டம் கண்ணாடி. அடிப்படை உருவாகும்போது பகுதிகளை எடுத்துக் கொள்ளுங்கள். கற்பிக்கிறது: டாப்ஸ் ஒரு செயல்முறை, ஒரு கணம் அல்ல."}],"chartPatterns":[{"shape":"double_bot","name":"டபுள் பாட்டம் (W)","color":"#22c55e","bias":"சார்பு வாங்கு","tip":"அதே விலைக்கு அருகில் இரண்டு தாழ்வுகள், பின்னர் நடுத்தர உச்சத்தின் முறிவு - W வடிவம்.","also":"மேலும்: neckline break = பயிற்சி தூண்டுதல். TP யோசனைக்கான உயரத்தை அளவிடவும். உச்சம்→குறைவிலிருந்து ட்வீசர் பாட்டம் + ஃபைபுக்கான இணைப்புகள். ஆபத்து: தவறான முறிவு - நெக்லைனுக்கு அப்பால் காத்திருங்கள்."},{"shape":"double_top","name":"டபுள் டாப் (எம்)","color":"#ef4444","bias":"சார்பு விற்பனை","tip":"அதே விலைக்கு அருகில் இரண்டு அதிகபட்சம், பின்னர் நடுத்தர தொட்டியின் முறிவு - M வடிவம்.","also":"மேலும்: பெரிய அளவில் ட்வீசர் டாப் போலவே. நெக்லைன் இடைவெளிக்கு முன் நீண்ட பாதை. உளவியல்: இரண்டாவது சிறந்த FOMO விலை உயர்ந்தது - திட்டம் ஏற்கனவே இருந்தது."},{"shape":"hs_top","name":"தலை & தோள்கள்","color":"#ef4444","bias":"சார்பு விற்பனை","tip":"இடது தோள், மேல் தலை, வலது தோள்; கழுத்தை உடைக்கவும்.","also":"மேலும்: கிளாசிக் விநியோகம். இலக்கு ≈ தலை உயரம் நெக்லைனுக்குக் கீழே. RSI அடிக்கடி தலையில் வேறுபடுகிறது. மல்டி-ஸ்விங் பொறுமையைக் கற்றுக்கொடுக்கிறது - ஒரு மெழுகுவர்த்தி வர்த்தகம் அல்ல."},{"shape":"ihs","name":"தலைகீழ் எச்&எஸ்","color":"#22c55e","bias":"சார்பு வாங்கு","tip":"கீழே தலைகீழாக எச்&எஸ் - நெக்லைன் முறிவு.","also":"மேலும்: குவிப்பு கதை. வால்யூம்/வேகம் இருந்தால் உறுதிப்படுத்தவும். சங்கம ஆய்வுக்காக வலது தோள்பட்டை மண்டலத்தில் மார்னிங் ஸ்டார் உடன் இணைக்கவும்."},{"shape":"triangle","name":"முக்கோணம் (அழுத்தம்)","color":"#f0b429","bias":"பிரேக்அவுட் காத்திருப்பு","tip":"குறைந்த அதிகபட்சம் + அதிக தாழ்வுகள் அழுத்துதல் - ஆற்றல் உருவாக்கம்.","also":"மேலும்: BB அழுத்தும் அதே பாடம். உள்ளே இருக்கும் திசையை யூகிக்க வேண்டாம். வர்த்தக இடைவேளை + மெழுகுவர்த்தி மூடல். பணம்: அறியப்பட்ட திசைக்குப் பின் அளவு."},{"shape":"flag","name":"காளைக் கொடி","color":"#22c55e","bias":"தொடர்ந்து வாங்கவும்.","tip":"கூர்மையான உயர்வு (துருவம்) பின்னர் சிறிய கீழ்நோக்கி / பக்கவாட்டு சேனல் - பின்னர் தொடர்ச்சி.","also":"மேலும்: Fib கொடி ஆழம் பெரும்பாலும் ஆழமற்றது (38%). மருபோசு கம்பம் + கொடி = போக்கு நடைமுறை. இழுக்காமல் முழு நீட்டிப்புக்குப் பிறகு தாமதமாக வாங்க வேண்டாம்."},{"shape":"channel","name":"போக்கு சேனல்","color":"#38bdf8","bias":"போக்குடன்","tip":"உயரும் (அல்லது வீழ்ச்சி) இணையான கோடுகளுக்கு இடையிலான விலை — ஸ்விங் வர்த்தக கருவிகள்.","also":"மேலும்: குறைந்த சேனல் + சுத்தியலை ஏற்றத்தில் வாங்கவும்; மேல் விற்க + படப்பிடிப்பு நட்சத்திரம். BB மிட் அடிக்கடி சேனலைக் கண்காணிக்கும். \"என்ன மெழுகுவர்த்தி\" மட்டுமல்ல \"எங்கே\" கற்றுக்கொடுக்கிறது."},{"shape":"support_res","name":"ஆதரவு மற்றும் எதிர்ப்பு","color":"#a78bfa","bias":"முதலில் சூழல்","tip":"விலை மீண்டும் மீண்டும் வினைபுரியும் கிடைமட்ட மண்டலங்கள் — ஒவ்வொரு மெழுகுவர்த்தியின் கீழும் வரைபடம்.","also":"மேலும்: ஒவ்வொரு வடிவமும் S/R இல் வலுவாக உள்ளது. BB/RSIக்கு முன் விளக்கப்பட ஆய்வகத்தில் மண்டலங்களை வரையவும். உளவியல்: நிலைகள் > குறிப்புகள்; நுழைவதற்கு முன் அவற்றை எழுதுங்கள்."},{"shape":"triple_top","name":"டிரிபிள் டாப்","color":"#ef4444","bias":"சார்பு விற்பனை","tip":"ஏறக்குறைய ஒரே விலையில் மூன்று அதிகபட்சம் - வாங்குபவர்கள் ஒரு சுவரில் மூன்று முறை தோல்வியடைகிறார்கள்.","also":"மேலும்: டபுள் டாப்பை விட வலிமையானது (மூன்று நிராகரிப்புகள் = பிடிவாதமான வழங்கல்). நெக்லைன் முறிவு தூண்டுதலாகும்; இலக்கு ≈ மாதிரி உயரம். கற்பிக்கிறது: நிலை, மெழுகுவர்த்தி அல்ல, முதலாளி."},{"shape":"triple_bot","name":"டிரிபிள் பாட்டம்","color":"#22c55e","bias":"சார்பு வாங்கு","tip":"ஏறக்குறைய ஒரே விலையில் மூன்று குறைவு - விற்பனையாளர்கள் ஒரு தளத்தில் மூன்று முறை தோல்வியடைந்தனர்.","also":"மேலும்: டிரிபிள் டாப் கண்ணாடி. ஒவ்வொரு தொடுதலும் ஒரு சுத்தியல் / ட்வீசர் ஆய்வாக இருக்கலாம். நெக்லைன் உடைப்புக்காக காத்திருங்கள் + மூடவும். பல ஊசலாட்டங்களில் பொறுமையைக் கற்றுக்கொடுக்கிறது."},{"shape":"cup_handle","name":"கோப்பை & கைப்பிடி","color":"#22c55e","bias":"தொடர்ந்து வாங்கவும்.","tip":"ஒரு வட்டமான \"U\" (கப்) பின்னர் ஒரு சிறிய இழுத்தல் (கைப்பிடி) - ஓய்வுக்குப் பிறகு தொடர்ச்சி.","also":"மேலும்: பிரேக்அவுட் வர்த்தகர்களிடையே பிரபலமானது. கைப்பிடி ஆழமற்றதாகவும் குறுகியதாகவும் இருக்க வேண்டும் - ஆழமான கைப்பிடி என்றால் பலவீனமான கைகள். மெழுகுவர்த்தி உறுதிப்படுத்தலுடன் கைப்பிடி இடைவெளியில் உள்ளிடவும்."},{"shape":"rounding_bot","name":"ரவுண்டிங் பாட்டம்","color":"#22c55e","bias":"தலைகீழ் வாங்கு","tip":"ஒரு மெதுவான, மென்மையான \"சாசர்\" குறைந்த - விற்பனை படிப்படியாக மங்குகிறது, பின்னர் வாங்குபவர்கள் எடுத்துக்கொள்கிறார்கள்.","also":"மேலும்: ஒரு ஸ்லோ-மோஷன் டபுள் பாட்டம். விற்பனையாளர்களின் ஆற்றல் தீர்ந்து விட்டது, ஒரு ஸ்பைக் கூட இல்லை - முழு பொறுமை தேவை."},{"shape":"rounding_top","name":"ரவுண்டிங் டாப்","color":"#ef4444","bias":"தலைகீழ் விற்பனை","tip":"ஒரு மென்மையான \"குவிமாடம்\" உயர் - விலை உருளும் முன் படிப்படியாக மங்குகிறது.","also":"மேலும்: ரவுண்டிங் பாட்டம் கண்ணாடி. வேகம் இறக்கும் போது முன்கூட்டியே பகுதிகளை எடுத்துக் கொள்ளுங்கள். கற்பிக்கிறது: டாப்ஸ் ஒரு செயல்முறை, ஒரு மெழுகுவர்த்தி அல்ல."},{"shape":"rising_wedge","name":"ரைசிங் ஆப்பு","color":"#ef4444","bias":"சார்பு விற்பனை","tip":"இரண்டு தண்டவாளங்களும் உயரும், ஆனால் அவை மேல்நோக்கி ஒன்றிணைகின்றன - வரம்பைக் கிள்ளும்போது வாங்குபவர்கள் சோர்வடைகிறார்கள்.","also":"மேலும்: விலை இன்னும் உயர்கிறது ஏனெனில் தவறான; குறுகுவது உண்மையான துப்பு. அடிக்கடி உடைந்து விடும். கடைசி உந்துதலை துரத்த வேண்டாம்."},{"shape":"falling_wedge","name":"ஃபாலிங் ஆப்பு","color":"#22c55e","bias":"சார்பு வாங்கு","tip":"இரண்டு தண்டவாளங்களும் விழுகின்றன, ஆனால் அவை கீழ்நோக்கிச் செல்கின்றன - வரம்பு கிள்ளும்போது விற்பனையாளர்கள் சோர்வடைகிறார்கள்.","also":"மேலும்: ரைசிங் ஆப்பு கண்ணாடி. அடிக்கடி UP உடைகிறது. ஆப்பு வாலில் ஒரு சுத்தியல் ஒரு உன்னதமான ஆய்வு. இடைவேளைக்கு காத்திருங்கள் + மூடவும்."},{"shape":"asc_triangle","name":"ஏறும் முக்கோணம்","color":"#f0b429","bias":"சார்பு வாங்கு","tip":"ஒரு தட்டையான உச்சவரம்பு + உயரும் தளம் - வாங்குபவர்கள் நிலையான எதிர்ப்பில் முன்னேறிக்கொண்டே இருக்கிறார்கள்.","also":"மேலும்: ஒரு விலைக்கு எதிராக அழுத்தம் உருவாகிறது; முறிவு பொதுவானது. உச்சவரம்புக்கு மேலே உள்ளிடவும். கற்றுக்கொடுக்கிறது: வாங்குபவர்கள் பொறுமையிழந்து விடுகிறார்கள்."},{"shape":"desc_triangle","name":"இறங்கு முக்கோணம்","color":"#f0b429","bias":"சார்பு விற்பனை","tip":"ஒரு தட்டையான தளம் + விழும் உச்சவரம்பு - விற்பனையாளர்கள் நிலையான ஆதரவில் தள்ளப்படுகிறார்கள்.","also":"மேலும்: ஏறும் முக்கோணத்தின் கண்ணாடி. முறிவு பொதுவானது. தரைக்குக் கீழே நெருங்கி நுழையவும். கற்பிக்கிறது: விற்பனையாளர்கள் கட்டுப்பாட்டைப் பெறுகிறார்கள்."},{"shape":"pennant","name":"பென்னண்ட்","color":"#22c55e","bias":"தொடர்ச்சி","tip":"ஒரு கூர்மையான துருவம் பின்னர் ஒரு சிறிய, இறுக்கமான முக்கோணம் - போக்கு மீண்டும் தொடங்கும் முன் மிகக் குறுகிய ஓய்வு.","also":"மேலும்: கொடி போன்றது ஆனால் குறுகிய மற்றும் முக்கோணமானது. இலக்கு யோசனைக்கு துருவத்தை அளவிடவும். சிறிய சுருளின் உள்ளே ஒருபோதும் யூகிக்க வேண்டாம்."},{"shape":"flag_bear","name":"கரடி கொடி","color":"#ef4444","bias":"தொடர்ந்து விற்கவும்.","tip":"ஒரு கூர்மையான துளி (துருவம்) பின்னர் ஒரு சிறிய மேல்நோக்கி / பக்கவாட்டு சேனல் - பின் தொடர்ச்சி கீழே.","also":"மேலும்: காளைக் கொடியின் கண்ணாடி. சிறிய துள்ளல் ஒரு இடைநிறுத்தம், ஒரு தலைகீழ் அல்ல. கொடியைத் துரத்தி, மிக மோசமான விலைக்கு வாங்குங்கள் - இடைவேளைக்காக காத்திருங்கள்."},{"shape":"rectangle","name":"செவ்வகம் (வரம்பு)","color":"#f0b429","bias":"வரம்பு வர்த்தகம்","tip":"ஒரு தட்டையான கூரை மற்றும் தரைக்கு இடையே விலை துள்ளுகிறது - ஒரு பக்கவாட்டு பெட்டி.","also":"மேலும்: உள்ளே விளிம்புகளை மங்கச் செய்யவும், இடைவெளியை வெளியே வர்த்தகம் செய்யவும். BB சுருக்கம் பொதுவாக ஒரு செவ்வகத்திற்குள் இருக்கும். கற்பிக்கிறது: நிலை முதல் நிலை ஒழுக்கம்."},{"shape":"broadening","name":"விரிவடைதல் உருவாக்கம்","color":"#f0b429","bias":"எச்சரிக்கை","tip":"அதிக உயர்வும் குறைந்த தாழ்வும் — கிள்ளுவதற்குப் பதிலாக வரம்பு விசிறிகள் வெளியேறுகின்றன.","also":"மேலும்: குழப்பமான, உணர்ச்சிகரமான சந்தை. நிறுத்தங்கள் இரண்டு வழிகளிலும் தாக்கப்படும். சிறிய அளவு அல்லது ஒதுங்கி நிற்கவும்; அது பெரும்பாலும் வன்முறை ஒரு வழி நகர்வில் முடிவடைகிறது."},{"shape":"diamond","name":"வைரம்","color":"#f0b429","bias":"தலைகீழ்","tip":"நடுவில் அகலமானது, இரு முனைகளிலும் குறுகியது — ஒரு உன்னதமான டாப்பிங் / பாட்டம்மிங் உருவாக்கம்.","also":"மேலும்: ஒரு முக்கோணம் உருமாற்றம் செய்து பின்னர் அன்-மார்ப்ஸ். பிரேக்அவுட் திசை தீர்மானிக்கிறது. அரிதான மற்றும் மெதுவாக, அதனால் பெரும்பாலான வரிசைகள் சத்தம் போல் உணர்கின்றன - பொறுமையாக இருங்கள்."},{"shape":"island_rev","name":"தீவு திரும்புதல்","color":"#ef4444","bias":"தலைகீழ்","tip":"விலை இடைவெளிகள் விலகி, தனிமையான கிளஸ்டரில் வர்த்தகம், பின்னர் இடைவெளிகள் - ஒரு \"தீவு\".","also":"மேலும்: உண்மையான இடைவெளிகள் தேவை (பங்குகள்/FX இல் மிகவும் பொதுவானது). தீவு வாங்குவோர் அல்லது விற்பவர்களிடம் சிக்கியுள்ளது. தீவு மெழுகுவர்த்திகள் அல்ல, இடைவெளிகளை சமிக்ஞையாகக் கருதுங்கள்."},{"shape":"breakaway_gap","name":"பிரேக்அவே இடைவெளி","color":"#22c55e","bias":"போக்கு ஆரம்பம்","tip":"ஒரு வரம்பு அல்லது அடித்தளத்திற்கு வெளியே ஒரு இடைவெளி - நகர்வு சக்தியுடன் தொடங்குகிறது, அழுத்தினால் அல்ல.","also":"மேலும்: சோர்வு இடைவெளி போலல்லாமல், இது ஒரு நகர்வின் ஆரம்பத்தில் தோன்றும். இடைவெளிகள் பெரும்பாலும் ஆதரவு/எதிர்ப்பாக பின்னர் செயல்படும். கற்பிக்கிறது: வேகம் மற்றும் மதிப்பு இடைவெளிகள்."},{"shape":"v_reversal","name":"வி-தலைகீழ்","color":"#22c55e","bias":"தலைகீழ்","tip":"எந்த அடிப்படையும் இல்லாமல் உடனடியாக மாறும் ஒரு கூர்மையான இலவச வீழ்ச்சி - ஒரு \"V\".","also":"மேலும்: வேகமான மற்றும் பயங்கரமான; அடிக்கடி செய்தி உந்துதல். பிடிப்பது கடினம், துரத்துவது எளிது. ஸ்பைக்கை வாங்குவதற்குப் பதிலாக ஒரு சிறிய இழுப்பு + மெழுகுவர்த்திக்காக காத்திருங்கள்."},{"shape":"harmonic","name":"ஹார்மோனிக் பேட்டர்ன்","color":"#f0b429","bias":"தலைகீழ் மண்டலங்கள்","tip":"ஒரு அளவிடப்பட்ட ஜிக்-ஜாக் (X-A-B-C-D) அங்கு ஒவ்வொரு காலும் ஃபிபோனச்சி விகிதத்தைக் கொண்டுள்ளது - ஒரு \"கார்ட்லி/பேட்\" பாணி வரைபடம்.","also":"மேலும்: மேம்பட்டது. D புள்ளி என்பது நுழைவு மண்டலம், விகிதங்களால் வரையறுக்கப்படுகிறது, உணர்வுகள் அல்ல. மாஸ்டர் ப்ளைன் ஃபைப் முதலில்; இது ஒரு நிலை ஆழமாக எடுக்கப்பட்ட Fib ஆகும்."}],"modules":[{"id":"bb","title":"1 · பொலிங்கர் பட்டைகள் (BB)","summary":"நகரும் சராசரியைச் சுற்றியுள்ள நிலையற்ற பட்டைகள். முக்கிய CPE பயிற்சி அமைப்பு - அழுத்துதல், வாக்-தி-பேண்ட், கீழ்/மேல் தொடுதல் + மெழுகுவர்த்தி உறுதிப்படுத்தல் ஆகியவற்றைக் கற்றுக்கொள்ளுங்கள்.","lessons":[{"h":"பிபி என்றால் என்ன","t":"பொலிங்கர் பட்டைகள் = நடுத்தர SMA (பெரும்பாலும் 20) + மேல்/கீழ் பட்டைகள் N நிலையான விலகல்களில் (பெரும்பாலும் 2). ஏற்ற இறக்கம் அதிகரிக்கும் போது பட்டைகள் விரிவடையும் மற்றும் சந்தை அமைதியாக இருக்கும்போது அழுத்தும்."},{"h":"நடுத்தர இசைக்குழு","t":"நடுக் கோடு என்பது சராசரி. நடுத்தரத்திற்கு மேல் விலை அடிக்கடி ஏற்ற அழுத்தத்தைக் காட்டுகிறது; கீழே கரடுமுரடான அழுத்தம் காட்டுகிறது. அதை ஒரு மாறும் சார்பு வரியாகப் பயன்படுத்தவும், ஒரு மேஜிக் வாங்க/விற்க அல்ல."},{"h":"லோயர் பேண்ட் (பயிற்சியை வாங்கவும்)","t":"ஒரு வீழ்ச்சிக்குப் பிறகு குறைந்த இசைக்குழுவைக் குறிக்கும் விலையானது \"கீழே நீட்டப்பட்டது\" என்று பொருள்படும். ஒவ்வொரு தொடுதலையும் வாங்க வேண்டாம். ஒரு நேர்த்தியான மெழுகுவர்த்திக்காக காத்திருங்கள் (சுத்தி, என்கல்ஃபிங்) மற்றும் சிறந்த RSI திரும்பும்."},{"h":"அப்பர் பேண்ட் (விற்க / எச்சரிக்கை)","t":"மேல் பட்டையின் விலையைக் குறிப்பது \"நீட்டப்பட்டது\" என்று பொருள்படும். ஒரு ஏற்றத்தில், விலையானது மேல் இசைக்குழுவில் (வாக்-தி-பேண்ட்) சவாரி செய்யலாம். கரடுமுரடான மெழுகுவர்த்தி + உயர்-TF பலவீனத்துடன் மட்டுமே யோசனைகளை விற்கவும்."},{"h":"பிழி","t":"குறுகிய பட்டைகள் = குறைந்த ஏற்ற இறக்கம் → ஒரு பிரேக்அவுட் அடிக்கடி பின்தொடர்கிறது. இறுக்கமான அழுத்தத்தின் உள்ளே திசையை யூகிக்க வேண்டாம்; பிரேக்அவுட்டைக் குறிக்கவும் மற்றும் மெழுகுவர்த்தி + வால்யூம் இருந்தால் உறுதிப்படுத்தவும்."},{"h":"இசைக்குழு நடக்கவும்","t":"ஒரு வலுவான போக்கில், பல மெழுகுவர்த்திகளுக்கு மேல் (அல்லது கீழ்) பேண்டை விலை அணைக்கிறது. சராசரி-தலைகீழ் மங்கலுடன் போராடுவது ஒரு பொதுவான தொடக்க தவறு."},{"h":"BB + விளக்கப்பட ஆய்வகம்","t":"CPE விளக்கப்பட ஆய்வகம் / மேசைகளில், டெமோவில் மெழுகுவர்த்திகளுடன் BB படிக்கவும். பயிற்சி: லோயர் பேண்ட் + சுத்தியல் → விக் கீழே SL உடன் காகித வர்த்தகம், நடுத்தர பட்டைக்கு அருகில் TP1."},{"h":"BB + RSI சேர்க்கை","t":"வலுவான நடைமுறை வடிகட்டி: குறைந்த BB + RSI அதிகமாக விற்கப்பட்டது (அல்லது அதிக விற்பனையில் இருந்து உயரும்) + நேர்த்தியான மெழுகுவர்த்தி. அப்பர் பிபி + ஆர்எஸ்ஐ ஓவர்போட் + குறுகிய பயிற்சிக்கான கரடி மெழுகுவர்த்தி."},{"h":"இடத்தை நிறுத்து","t":"நீண்ட பயிற்சி: SL கீழ் ஸ்விங் லோ / லோயர் பேண்ட் விக். குறுகிய பயிற்சி: SL மேலே ஸ்விங் ஹை. எழுதப்பட்ட SL இல்லாமல் BB வர்த்தகத்தில் நுழைய வேண்டாம்."},{"h":"இலக்குகள்","t":"பொதுவான பாதை: நடுத்தர இசைக்குழுவில் TP1, எதிர் பட்டை அல்லது பாதையை நோக்கி TP2. அளவிடுதல் - முழு நகர்வும் தேவையில்லை."},{"h":"காலகட்டங்கள்","t":"அதிக TF (4H/1D) இல் சார்புநிலையை முடிவு செய்யுங்கள். 15m/30m BB + மெழுகுவர்த்தியில் உள்ளிடவும். சீரற்ற TFகளை கலப்பது முரண்பட்ட சமிக்ஞைகளை ஏற்படுத்துகிறது."},{"h":"தவிர்க்க வேண்டிய தவறுகள்","t":"செயலிழக்கும் சந்தையில் ஒவ்வொரு லோயர்-பேண்ட் டச் வாங்குதல்; நிலவு ஓட்டத்தில் ஒவ்வொரு மேல் தொடுதலையும் விற்பது; இல்லை SL; பட்டைகளை வன்முறையில் விரிவுபடுத்தும் செய்தி ஸ்பைக்குகளைப் புறக்கணித்தல்."},{"h":"பயிற்சி பட்டியல்","t":"① அதிக TF சார்பு ② BB தொடுதல் அல்லது அழுத்துதல் முறிவு ③ மெழுகுவர்த்தி உறுதிப்படுத்தல் ④ RSI ஒப்புக்கொள்கிறது ⑤ இடர் % செட் ⑥ தாள் முதலில் ⑦ ஜர்னல் முடிவு."}]},{"id":"rsi","title":"2 · RSI (உறவினர் வலிமை குறியீடு)","summary":"உந்த ஆஸிலேட்டர் 0–100. இயல்புநிலை 14 காலம். BB மற்றும் மெழுகுவர்த்திகளுடன் பயன்படுத்தவும் - RSI மட்டும் முழு அமைப்பாக இல்லை.","lessons":[{"h":"என்ன RSI நடவடிக்கைகள்","t":"RSI சராசரி ஆதாயங்கள் மற்றும் N பார்களை விட இழப்புகளை ஒப்பிடுகிறது. உயர் RSI = சமீபத்திய புல்லிஷ் வேகம்; குறைந்த ஆர்எஸ்ஐ = சமீபத்திய கரடுமுரடான வேகம். இது ஒவ்வொரு முறையும் \"அதிகமாக வாங்கப்பட்டது = விற்க வேண்டும்\" அல்ல."},{"h":"கிளாசிக் மண்டலங்கள்","t":"பெரும்பாலும்: 70க்கு மேல் = அதிகமாக வாங்கப்பட்ட மண்டலம், 30க்குக் கீழே = அதிகமாக விற்கப்பட்ட மண்டலம். வலுவான போக்குகளில், RSI நீண்ட காலத்திற்கு அதிகமாக வாங்கப்பட்ட/அதிகமாக விற்கப்படும் - அது இயல்பானது."},{"h":"மிட்லைன் 50","t":"RSI 50 க்கு மேல் கடக்கும்போது நேர்மறை சார்புகளை ஆதரிக்கலாம்; 50 க்குக் கீழே கரடுமுரடான சார்பு. பல வர்த்தகர்கள் BB மிடில் பேண்டுடன் 50 ஐ போக்கு-வடிப்பானாகப் பயன்படுத்துகின்றனர்."},{"h":"வேறுபாடு - நேர்மறை","t":"விலை குறைவாக உள்ளது, ஆர்எஸ்ஐ உயர்வை குறைந்ததாக ஆக்குகிறது → உந்தம் குறையும்போது பலவீனமடைகிறது. காகித நுழைவதற்கு முன் மெழுகுவர்த்தி + கட்டமைப்பு உடைப்புக்காக இன்னும் காத்திருக்கவும்."},{"h":"வேற்றுமை - கரடி","t":"விலை அதிகம், RSI குறைந்த உயர் → தலைகீழ் வேகம் மறைதல். ஷூட்டிங் ஸ்டார் / என்கல்ஃபிங் அருகில் ரெசிஸ்டன்ஸ் அல்லது அப்பர் பிபி மூலம் உறுதிப்படுத்தவும்."},{"h":"தோல்வி ஊசலாடுகிறது","t":"RSI முந்தைய தீவிரத்தை மறுபரிசீலனை செய்யத் தவறியது, பின்னர் 50 - ஆரம்ப உந்தம் மாற்றக் குறிப்பைக் கடக்கிறது. விளக்கப்பட ஆய்வக அமைப்புடன் இணைக்கவும்."},{"h":"RSI + BB (CPE பாணி)","t":"நீண்ட நேரம் பயிற்சி செய்யுங்கள்: குறைந்த BB, RSI ≤ 35 (அல்லது ≤ 30 இலிருந்து உயர்வு), நேர்த்தியான மெழுகுவர்த்திக்கு அருகில் விலை. குறுகிய பயிற்சி: மேல் BB, RSI ≥ 65–70, கரடி மெழுகுவர்த்தி."},{"h":"மறைக்கப்பட்ட வேறுபாடு","t":"டிரெண்ட் தொடர்ச்சி க்ளூ (எ.கா. விலை அதிகம் குறைவு, ஆர்எஸ்ஐ குறைந்த உயர்வு). மேம்பட்ட — மாஸ்டர் கிளாசிக் டைவர்ஜென்ஸ் முதலில் டெமோவில்."},{"h":"அமைப்புகள்","t":"RSI(14) என்பது பொதுவான இயல்புநிலை. குறுகிய RSI = அதிக சத்தம். சிக்னலை கட்டாயப்படுத்த, அமைப்புகளை மாற்ற வேண்டாம்."},{"h":"RSI உடன் வெளியேறுகிறது","t":"நீங்கள் அதிகமாக விற்கப்பட்டிருந்தால், RSI நடுத்தர/மேல் மண்டலத்தை அடையும் போது ஓரளவு லாபம் பெறுவது நியாயமானது. மீதியை அமைப்பு அல்லது BB மிடில் மூலம் பின்தொடரவும்."},{"h":"செய்தி & RSI","t":"பெரிய செய்திகள் RSIயை உடனடியாக அதிகரிக்கலாம். RSI உச்சநிலையில் செயல்படும் முன் முதல் வன்முறை மெழுகுவர்த்தி முடிவடையும் வரை காத்திருக்க விரும்பவும்."},{"h":"தவறுகள்","t":"ஒரு காளை சந்தையில் ஒவ்வொரு RSI>70ஐ சுருக்கவும்; கரடி விபத்தில் ஒவ்வொரு RSI<30க்கும் ஏங்குதல்; சங்கமம் இல்லை; RSI \"நன்றாக இருக்கும் போது\" பழிவாங்கும் மறு நுழைவு."},{"h":"பயிற்சி பட்டியல்","t":"① குறிப்பு RSI மதிப்பு + சாய்வு ② BB இருப்பிடத்தை சரிபார்க்கவும் ③ மெழுகுவர்த்தி உறுதிப்படுத்தவும் ④ உயர் TF ⑤ காகிதம் + பத்திரிகை ⑥ ஒரு நேரத்தில் ஒரு யோசனை."}]},{"id":"fib","title":"3 · Fibonacci (மீண்டும் பெறுதல் & நீட்டிப்பு)","summary":"தெளிவான ஸ்விங் ஹை → ஸ்விங் லோ (அல்லது ரிவர்ஸ்) இலிருந்து புல்பேக்குகள் மற்றும் இலக்குகளை அளவிடவும். BB/RSI சங்கமத்துடன் 38.2 · 50 · 61.8 இல் கவனம் செலுத்துங்கள்.","lessons":[{"h":"Fib ஏன் பயன்படுத்தப்படுகிறது","t":"பல வர்த்தகர்கள் அதே விகிதங்களைப் பார்க்கிறார்கள், எனவே பணப்புழக்கம் பெரும்பாலும் அவர்களுக்கு அருகில் வினைபுரிகிறது. Fib என்பது சாத்தியமான மண்டலங்களின் வரைபடம் — உத்தரவாதம் அல்ல."},{"h":"ஸ்விங் புள்ளிகள்","t":"எப்போதும் தெளிவான ஊஞ்சலில் இருந்து உயரமாக (மேலே நகர்த்த) அல்லது உயரத்திலிருந்து தாழ்வாக (கீழே நகர்த்த) ஆடுங்கள். மோசமான ஊசலாட்டம் = பயனற்ற நிலைகள். சார்ட் லேப் டெமோவில் ஊசலாடுவதைப் பயிற்சி செய்யுங்கள்."},{"h":"முக்கிய மறுபரிசீலனைகள்","t":"பொதுவானது: 23.6% (மேலோட்டமானது), 38.2%, 50% (தூய ஃபைப் அல்ல, ஆனால் பரவலாகப் பயன்படுத்தப்படுகிறது), 61.8% (தங்கம்), 78.6% (ஆழமானது). ஆழ்ந்த பின்னடைவுகள் போக்கு பலவீனத்தைக் குறிக்கலாம்."},{"h":"பின்வாங்கல் வாங்குதல்கள் (அதிகரிப்பு)","t":"தூண்டுதலுக்குப் பிறகு, 38.2–61.8 மண்டலத்திற்கு இழுக்க காத்திருக்கவும் + புல்லிஷ் மெழுகுவர்த்தி + முன்னுரிமை BB மிட்/லோயர் சப்போர்ட் அல்லது RSI ஹோல்டிங் >40–45."},{"h":"புல்பேக் விற்பனைகள் (கீழ்நிலை)","t":"உத்வேகத்தை குறைத்த பிறகு, 38.2–61.8 + பேரிஷ் மெழுகுவர்த்தி + RSI 55-60 க்கு கீழ் தோல்வியடையும்."},{"h":"நீட்டிப்புகள் / இலக்குகள்","t":"பொதுவான நீட்டிப்புகள்: 127.2%, TP2 யோசனைகளுக்கான ஊசலாட்டத்திற்கு அப்பால் 161.8%. பாதையுடன் பயன்படுத்தவும் - துல்லியமான உண்ணிகளை கட்டாயப்படுத்த வேண்டாம்."},{"h":"சங்கமம் = சக்தி","t":"சிறந்த பயிற்சி மண்டலங்கள்: Fib 50/61.8 + BB நடுத்தர/கீழ் + முன் அமைப்பு + RSI திருப்பம். ஒரு Fib வரி மட்டும் பலவீனமாக உள்ளது."},{"h":"Fib + BB","t":"61.8% பேர் குறைந்த BBக்கு அருகில் உயர்நிலையில் அமர்ந்தால், அந்த ஒன்றுடன் ஒன்று உயர்தர காகித ஆய்வு மண்டலமாகும். மெழுகுவர்த்தி உறுதியுடன் மட்டும் உள்ளிடவும்."},{"h":"பல இழைகள்","t":"தொடக்கநிலையாளர்கள் ஒரு சுத்தமான ஊஞ்சலைப் பயன்படுத்த வேண்டும். 5 ஃபைப்களை அடுக்கி வைப்பது விளக்கப்பட சத்தம் மற்றும் FOMO உள்ளீடுகளை உருவாக்குகிறது."},{"h":"செல்லாததாக்குதல்","t":"உங்கள் சார்புக்கு எதிராக விலை 78.6%க்கு மேல் தெளிவாக மூடப்பட்டால், திரும்பப் பெறுதல் ஆய்வறிக்கை பெரும்பாலும் தோல்வியடையும் - வெளியேறவும் அல்லது ஒதுங்கி நிற்கவும்."},{"h":"அந்நிய செலாவணி vs கிரிப்டோ","t":"அதே விகிதங்கள். அந்நிய செலாவணி மேஜர்கள் பெரும்பாலும் திரவ அமர்வுகளில் நிலைகளை மிகவும் சுத்தமாக மதிக்கிறார்கள்; க்ரிப்டோ அதன் பிறகு தலைகீழாகச் செல்லலாம் - அளவு சிறியது."},{"h":"தவறுகள்","t":"சிறிய இரைச்சல் ஊசலாட்டங்களில் Fib ஐ வரைதல்; மெழுகுவர்த்தி இல்லாமல் நடுவானில் நுழைவது; Fib \"கிட்டத்தட்ட\" வைத்திருக்கும் போது SL ஐ வெகுதூரம் நகர்த்துகிறது; அதிக TF ஐ புறக்கணித்தல்."},{"h":"பயிற்சி பட்டியல்","t":"① மார்க் ஸ்விங் ② குறிப்பு 38.2/50/61.8 ③ விலை வரும் வரை காத்திருங்கள் ④ மெழுகுவர்த்தி + RSI/BB ⑤ இடர் தொகுப்பு ⑥ காகிதம் → இதழ்."}]},{"id":"money","title":"4 · பண மேலாண்மை","summary":"முறை உண்மையில் எவ்வாறு பயன்படுத்தப்படுகிறது: ஒரு நிலையான சதவீதம் ஆபத்து, நிறுத்தத்தில் இருந்து அளவு, இலாபத்தின் வங்கி பகுதி, மற்றும் இழப்பு வரம்புக்கு பிறகு நாள் நிறுத்த. CPE இதை கைமுறை மற்றும் ஆட்டோ வர்த்தகத்தில் பயன்படுத்தலாம்.","lessons":[{"h":"பண மேலாண்மையின் குறிக்கோள்","t":"விளையாட்டில் இருங்கள். ஒரு மோசமான வர்த்தகம் ஒருபோதும் கணக்கை அழிக்கக்கூடாது. நிலைத்தன்மை லாட்டரி அளவைக் குறைக்கிறது."},{"h":"வர்த்தகர்கள் உண்மையில் அதை எவ்வாறு பயன்படுத்துகிறார்கள்","t":"பொதுவான நடைமுறை நிலையான-பிரிவு ஆபத்து. நீங்கள் முதலில் நாணயத் தொகையைத் தேர்ந்தெடுக்க வேண்டாம். நீங்கள் முதலில் நிறுத்தத்தை எழுதுங்கள், இந்த யோசனை கணக்கின் 1% ஐ இழக்கக்கூடும் என்று முடிவு செய்யுங்கள், பின்னர் அளவு அதிலிருந்து வெளியேறும். ஒரு பரந்த நிறுத்தம் ஒரு சிறிய நிலையைப் பெறுகிறது. ஒரு இறுக்கமான நிறுத்தம் ஒரு பெரிய நிலையைப் பெறுகிறது, மேலும் டாலர் ஆபத்து ஒரே மாதிரியாக இருக்கும். பண மேலாண்மை டிக் இயக்கத்தில் இருக்கும்போது CPE பயன்படுத்தும் முறை இதுவாகும்."},{"h":"வேலை செய்த உதாரணம் ($1000 நடைமுறைக் கணக்கு)","t":"கணக்கு $1000. ஆபத்து 1% = $10. நுழைவு 100, நிறுத்தம் 98. தூரம் = 2%. அளவு = 10 ÷ 0.02 = $500 கற்பனையானது. நிறுத்தம் ஏற்பட்டால், இழப்பு $10 ஆகும், $500 அல்ல. விலை 103ஐ அடைந்தால் (1.5 மடங்கு அபாயம்), ஆதாயம் சுமார் $15 ஆகும். ஒவ்வொரு ஜோடியிலும் ஒரே யோசனை: ஆபத்தில் உள்ள டாலர்கள் 1%க்கு அருகில் இருக்கும், நாணயத்தின் அளவு மாறுகிறது."},{"h":"டிக் மூலம் CPE என்ன செய்கிறது","t":"இப்போது வர்த்தகம் செய் → ஆட்டோ: “பண நிர்வாகத்தைப் பயன்படுத்து” என்பதைத் தேர்வு செய்யவும். தானியங்கு கட்டமைப்பைச் சேமிக்கவும். ஒவ்வொரு புதிய வாகன வர்த்தகமும் $1000 நடைமுறைக் கணக்கின் 1% மற்றும் அந்த சமிக்ஞையின் நுழைவு மற்றும் SL ஆகியவற்றிலிருந்து அளவுள்ள மூடிய முடிவுகளைப் பயன்படுத்துகிறது. ஸ்பாட் மற்றும் ஃப்யூச்சர்ஸ் குறைந்தபட்சம் மதிக்கப்படுகிறது: பரிமாற்ற குறைந்தபட்சம் 1% க்கும் அதிகமாக ஆபத்து ஏற்பட்டால், அந்த வர்த்தகம் தவிர்க்கப்படும். காலண்டர் நாளில் சுமார் −2%க்குப் பிறகு, அடுத்த நாள் வரை புதிய ஆட்டோக்கள் நிறுத்தப்படும். திறந்த வர்த்தகத்தில் அதிகபட்சம் 3% ஆபத்தில் உள்ளது. மேனுவல் டிரேடிலும் இதே டிக் உள்ளது. சிக்னல் வரலாறு இன்னும் சமமான $10 சோதனையைக் காட்டுகிறது, மேலும் அதன் கீழ் $1000 கணக்கிற்கான 1% திட்ட அளவைக் காட்டுகிறது, எனவே நீங்கள் இரண்டையும் பார்க்கலாம்."},{"h":"பகுதி லாபம் மற்றும் பாதை","t":"பயிற்சி என்பது முதல் இலக்கில் (பெரும்பாலும் பாதி) பங்கெடுத்து, மீதமுள்ளவற்றைப் பின்தொடர்வது. நிறுத்தம் மேலே நகரும் போது, ​​இலக்கும் நகர முடியும், எனவே வெற்றியாளர் முதல் இலக்கை விட அதிகமாக செலுத்த முடியும். அசல் யோசனையின் ஆபத்து அதிகரிக்காது. ஒரு வலுவான சமிக்ஞை 5% அபாயத்திற்கு ஒரு காரணம் அல்ல. அதே 1% பயன்படுத்தப்படுகிறது. பாதை ஒரு வலுவான வெற்றியாளரை வளர அனுமதிக்கிறது."},{"h":"தினசரி நிறுத்தம் மற்றும் திறந்த வெப்பம்","t":"பயன்படுத்திய விதி: நாள் கணக்கின் 2% குறைந்தால், வர்த்தகத்தைத் திறப்பதை நிறுத்துங்கள். 1% மூன்று திறந்த யோசனைகள் ஒவ்வொன்றும் சுமார் 3% வெப்பம். ஐந்து தொடர்புள்ள நாணயங்கள் ஒரு பந்தயம், ஐந்து அல்ல. அவற்றை ஒன்றாக எண்ணுங்கள்."},{"h":"இந்த முறை என்ன மறுக்கிறது","t":"மார்டிங்கேல் (இழப்புக்குப் பிறகு இரட்டிப்பாகும்) பயன்படுத்தப்படுவதில்லை. நுழைந்த பிறகு \"அதற்கு இடம் கொடுங்கள்\" என்று நிறுத்தத்தை நகர்த்துவது பயன்படுத்தப்படாது. \"நிச்சயம்\" சிக்னலில் ஆல்-இன் பயன்படுத்தப்படாது. சரியான நிறுத்தம் இல்லை என்றால், அளவு இல்லை, எனவே வர்த்தகம் இல்லை."},{"h":"ஒரு வர்த்தகத்திற்கு ஆபத்து","t":"பொதுவான விதி: ஒரே யோசனையில் கணக்கு ஈக்விட்டியில் ~0.5–1% மட்டுமே ஆபத்து. டெமோவில், லைவ் போன்ற அதே சதவீத பழக்கத்தைப் பயிற்சி செய்யவும்."},{"h":"நிலை அளவு சூத்திரம்","t":"அளவு ≈ (கணக்கு × ஆபத்து%) ÷ (நுழைவு − நிறுத்த தூரம்). பரந்த SL → சிறிய அளவு. அளவை முதலில் மற்றும் SL இரண்டாவதாக ஒருபோதும் தேர்ந்தெடுக்க வேண்டாம்."},{"h":"ஆபத்து: வெகுமதி","t":"கற்கும் போது சாத்தியமான வெகுமதி ≥ ஆபத்து (எ.கா. 1:1.5 அல்லது சிறந்தது) உள்ள யோசனைகளை விரும்பவும். TP1 இல் அளவிடவும், எனவே ஓட்டப்பந்தய வீரர்கள் \"இலவச ஆபத்து\"."},{"h":"பகுதியளவு லாபம்","t":"CPE பாணி: TP1 சில லாபத்தைப் பூட்டுகிறது, மீதமுள்ளவற்றுக்கு TP2 / பாதை. வங்கிப் பகுதிகள் உணர்ச்சி பீதியைக் குறைக்கிறது."},{"h":"TP + SL பின்தொடர்கிறது","t":"வாங்கவும்: விலை உயரும் போது நிலைகள் அதிகரிக்கும். விற்க: கீழே. சரியான வெளியேறும் அழைப்பு தேவையில்லாமல் டிரெயிலிங் லாபத்தைத் திறக்கும்."},{"h":"தினசரி / வாராந்திர இழப்பு வரம்பு","t":"எடுத்துக்காட்டு விதி: −2% கணக்கிற்கு அடுத்த நாளுக்கான வர்த்தகத்தை நிறுத்துங்கள். இழப்பு வரம்புக்குப் பிறகு பழிவாங்கும் அமர்வுகள் கணக்கு கொலையாளிகள்."},{"h":"ஸ்பாட் அளவு","t":"ஸ்பாட் நிமிட கருத்துக்கள் முக்கியமானவை (எ.கா. பரிமாற்ற நிமிடங்கள்). இன்னும் ஆபத்து% பயன்படுத்தவும்: உங்கள் SL க்கு எதிராக குறைந்தபட்ச அளவு அபாயங்கள் அதிகமாக இருந்தால், வர்த்தகத்தைத் தவிர்க்கவும்."},{"h":"எதிர்காலம் / அந்நியச் செலாவணி","t":"அந்நிய லாபம் மற்றும் நஷ்டம் இரண்டையும் பெருக்குகிறது. உயர் லெவரேஜ் + பரந்த SL = ஊதப்பட்ட கணக்கு. கற்கும் போது குறைந்த அந்நியச் செலாவணியை விரும்பு; தனிமைப்படுத்தப்பட்டால், ஒவ்வொரு நிலைக்கும் இழப்பைக் கட்டுப்படுத்தலாம்."},{"h":"தொடர்பு","t":"5 தொடர்புள்ள BTC ஆல்ட்களைத் திறப்பது = ஒரு பெரிய பந்தயம், ஐந்து அல்ல. ஒரு குழுவாக ஆபத்தை எண்ணுங்கள்."},{"h":"கட்டணம் & சறுக்கல்","t":"இறுக்கமான உச்சந்தலைகள் அட்டவணையில் நன்றாக இருக்கும் ஆனால் கட்டணம் R:R ஐ சாப்பிடும். நீங்கள் செலவுகளை அறியும் வரை டெமோவில் கிளீனர் ஸ்விங்கை விரும்புங்கள்."},{"h":"டெமோ → லைவ் பாலம்","t":"CPE டெமோ பயிற்சி (~3 மாத மனநிலை): அதே பத்திரிகை விதிகள், அதே%. நேரலையில், முதல் வாரங்களில் பாதி டெமோ அளவைத் தொடங்கவும்."},{"h":"API பண பாதுகாப்பு","t":"ஒவ்வொரு விசையிலும் திரும்பப் பெறுதல்கள் முடக்கப்பட்டுள்ளன. மேட்சிங் பிளாட்ஃபார்மில் டெஸ்ட் கணக்கு சரி செய்த பிறகுதான் நேரலை. தவறான இயங்குதள ரகசியம் = தோல்வியுற்ற அல்லது ஆபத்தான ஆப்ஸ்."},{"h":"தவறுகள்","t":"மார்டிங்கேல் (இழப்புக்குப் பிறகு இரட்டிப்பு); SL நகரும் தூரம்; \"நிச்சயமாக\" அமைப்புகளில் அனைத்தும்; குறைந்தபட்ச அளவு மற்றும் ஆபத்து% புறக்கணித்தல்; தினசரி நிறுத்தம் இல்லாமல் வர்த்தகம்."},{"h":"பயிற்சி பட்டியல்","t":"① இடர் % எழுதப்பட்டது ② SL தூரத்திலிருந்து அளவு ③ TP1/TP2/டிரெயில் திட்டமிடப்பட்டுள்ளது ④ அதிகபட்ச தினசரி இழப்பு அறியப்படுகிறது ⑤ காகிதம் முதல் ⑥ ஜர்னல் PnL நேர்மையாக."}]},{"id":"psych","title":"5 · வர்த்தகத்திற்கான உளவியல்","summary":"BB/RSI/Fib திறன்கள் உண்மையான திரைகளில் நிலைத்திருக்குமா என்பதை மைண்ட்செட் தீர்மானிக்கிறது. FOMO, பழிவாங்குதல், அதீத நம்பிக்கை, பயம் - குறிகாட்டிகள் போன்ற டெமோவில் இவற்றைப் பயிற்றுவிக்கவும்.","lessons":[{"h":"உளவியல் ஏன் முக்கியமானது","t":"நீங்கள் முன்கூட்டியே நுழைந்தால், SLஐத் தவிர்த்தால் அல்லது பழிவாங்கும் வர்த்தகத்தில் சரியான BB+RSI திட்டம் தோல்வியடையும். திறன் = அமைப்பு × ஒழுக்கம்."},{"h":"கணிப்புக்கு மேல் செயல்முறை","t":"நீங்கள் எதிர்காலத்தை கணிக்க தேவையில்லை. நீங்கள் விதிகளை செயல்படுத்த வேண்டும்: அமைவு → ஆபத்து → மேலாண்மை → இதழ். முடிவுகள் மாறுபடும்; செயல்முறை கட்டுப்படுத்தக்கூடியது."},{"h":"ஃபோமோ","t":"தவறிவிடுவோமோ என்ற பயம் = ஏற்கனவே BB/Fib மண்டலத்திலிருந்து வெகு தொலைவில் உள்ள பச்சை மெழுகுவர்த்திகளைத் துரத்துவது. விதி: நீங்கள் நுழைவைத் தவறவிட்டால், அடுத்த அமைப்பிற்காக காத்திருக்கவும். சார்ட் லேப்பில் எப்போதும் மற்றொரு மெழுகுவர்த்தி இருக்கும்."},{"h":"பழிவாங்கும் வர்த்தகம்","t":"ஒரு தோல்விக்குப் பிறகு, \"இப்போதே அதை மீண்டும் வெல்ல வேண்டும்\" என்ற வெறி கணக்குகளை அழிக்கிறது. கட்டாய கூல்-டவுன்: விலகிச் செல்லுங்கள், நஷ்டத்தைப் பதிவு செய்யுங்கள், சரிபார்ப்புப் பட்டியல் சுத்தமாக இருந்தால் மட்டுமே அடுத்த வர்த்தகம்."},{"h":"வெற்றிக்குப் பிறகு அதீத நம்பிக்கை","t":"ஒரு வரிசையில் 3 வெற்றிகள் ≠ அளவை 5× அதிகரிக்கவும். ஆபத்தை% நிலையாக வைத்திருங்கள். பெரும்பாலான மக்கள் பண விதிகளை மீறும் போது வெற்றி கோடுகள் இருக்கும்."},{"h":"இழப்புகளுக்குப் பின் பயம்","t":"சிவப்பு நாளுக்குப் பிறகு ஒவ்வொரு செல்லுபடியாகும் அமைப்பைத் தவிர்ப்பதும் ஒரு சார்பு. எழுதப்பட்ட திட்டத்தை நம்புங்கள்; தேவைப்பட்டால், அளவை தற்காலிகமாக குறைக்கவும், செயல்முறையை கைவிட வேண்டாம்."},{"h":"பகுப்பாய்வு முடக்கம்","t":"10 குறிகாட்டிகள் உடன்படவில்லை → முடக்கம். CPE மையத்தில் ஒட்டிக்கொள்க: மெழுகுவர்த்திகள் + BB + RSI (+ Fib மண்டலம்). கருவிகளின் அளவை விட தரம்."},{"h":"சாய்வு & செய்தி","t":"செய்தி ஸ்பைக் அட்ரினலின் மீது பெரிய சிவப்பு மெழுகுவர்த்திகள். கட்டமைப்பு சீர்திருத்தங்கள் வரை பெரிய தெரியாத போது பிளாட் விரும்புகின்றனர் - ஈகோ நடவடிக்கை விரும்புகிறது; திட்டம் பொறுமையை விரும்புகிறது."},{"h":"ஜர்னல் = சிகிச்சை + தரவு","t":"CPE ஜர்னலில் உணர்ச்சிக் குறிச்சொற்களை (FOMO, அவசரம், அமைதி) எழுதவும். உணர்வுகளில் உள்ள வடிவங்கள் PnL ஐ விட வேகமாக கசிவை வெளிப்படுத்துகின்றன."},{"h":"எழுதப்பட்ட விதிகள்","t":"அது எழுதப்படவில்லை என்றால், அது ஒரு விதி அல்ல. எடுத்துக்காட்டு: \"BB+candle+RSI மட்டும்; ஆபத்து 1%; −2% நாளுக்குப் பிறகு வர்த்தகம் இல்லை; சரிபார்ப்புப் பட்டியல் 20 தாள்கள் வரை டெமோ.\""},{"h":"சுற்றுச்சூழல்","t":"தூக்கம், பசி, அலைபேசியின் கவனச்சிதறல் முடிவுகளை மாற்றும். தீர்ந்துவிட்டால் அளவை அதிகரிக்க வேண்டாம். வர்த்தகம் விளையாட்டு - மூளையைப் பாதுகாக்கும்."},{"h":"சமூக சத்தம்","t":"டெலிகிராம் \"சிக்னல்கள்\" மற்றும் ஹைப் உங்கள் திட்டத்தை உடைக்கிறது. CPE கற்றல் வகுப்பு + உங்கள் பத்திரிகை > சீரற்ற குறிப்புகள். செய்திகள் & தந்திரங்களை சூழலாக வடிகட்டவும், ஆர்டர்கள் அல்ல."},{"h":"அடையாள மாற்றம்","t":"\"நான் எனது சரிபார்ப்புப் பட்டியலைப் பின்தொடர்கிறேன்\" என்று நினைக்க வேண்டாம், \"நான் சரியாக இருக்க வேண்டும்.\" சிறிய ஆபத்தில் தவறாக இருப்பது இயல்பானது; பெரிய ஆபத்துடன் பிடிவாதமாக இருப்பது விருப்பமானது."},{"h":"உடற்பயிற்சி கூடமாக டெமோ","t":"உணர்ச்சிகளைப் பாதுகாப்பாக ஒத்திகை பார்க்க டெமோ/பேப்பரைப் பயன்படுத்தவும். டெமோவில் நீங்கள் விதிகளைப் பின்பற்ற முடியாவிட்டால், LIVE மாயமாக ஒழுக்கத்தை சரிசெய்யாது."},{"h":"பயிற்சி பட்டியல்","t":"① நான் அமைதியாக இருக்கிறேனா? ② சரிபார்ப்பு பட்டியல் முடிந்ததா? ③ ஆபத்து% மாறவில்லையா? ④ பழிவாங்கவில்லையா? ⑤ நான் நேர்மையாகப் பத்திரிகை செய்வேன்? ஏதேனும் இல்லை என்றால் → வர்த்தகம் இல்லை."}]},{"id":"signals","title":"6 · CPE சிக்னல்கள் — பொருள் & என்ன செய்ய வேண்டும்","summary":"ஸ்பாட் / ஃபியூச்சர்ஸ் / ஃபாரெக்ஸ் டெஸ்க்களில் வாங்கு · விற்க · ஹோல்ட் + ஸ்கோர். ஒவ்வொரு பிளாட்ஃபார்மிலும் ஒரே என்ஜின் யோசனை — ஆனால் நீங்கள் சேமித்த API விசையின் தளத்தில் மட்டுமே வர்த்தகம் செய்கிறீர்கள். ஒவ்வொரு சிக்னலுக்கும் என்ன அர்த்தம் மற்றும் அது தோன்றிய பிறகு சரியான படிகள் இங்கே.","lessons":[{"h":"சமிக்ஞைகள் எங்கிருந்து வருகின்றன","t":"CPE மதிப்பெண்கள் BB, RSI, Fibonacci, candle stick, EMA cross, SMA50, MACD மற்றும் வேகம். மதிப்பெண் ≥ +3 → வாங்கவும். மதிப்பெண் ≤ −3 → விற்கவும். இடையில் → HOLD. இது ஒரு உதவி மதிப்பீடு - லாபத்திற்கான வாக்குறுதி அல்ல."},{"h":"சிக்னல் வாங்கு - பொருள்","t":"புல்லிஷ் சங்கமம் இப்போது வலுவாக உள்ளது (எடுத்துக்காட்டுகள்: குறைந்த பிபி பவுன்ஸ், ஆர்எஸ்ஐ ஓவர்சோல்ட் டர்ன், புல்லிஷ் மெழுகுவர்த்தி, கோல்டன் கிராஸ், ஃபிப் சப்போர்ட்). பரிந்துரைக்கப்பட்ட TP1 / TP2 / SL வரிசையில் தோன்றும் / விளக்கப்படம் ஆய்வகம் / இப்போது வர்த்தகம்."},{"h":"SELL சமிக்ஞை - பொருள்","t":"கரடி சங்கமம் வலுவானது (மேல் BB / overbought RSI / கரடி மெழுகுவர்த்தி / மரண குறுக்கு / Fib எதிர்ப்பு). ஸ்பாட்டில், SELL என்பது பொதுவாக உங்கள் சந்தை குறும்படங்களை அனுமதித்தால் மட்டுமே வெளியேறுதல்/நீண்ட அல்லது குறுகியதாக இருக்கும் (எதிர்காலம்/அந்நிய செலாவணி)."},{"h":"HOLD signal — பொருள்","t":"கலப்பு அல்லது பலவீனமான மதிப்பெண். வர்த்தகத்தை கட்டாயப்படுத்த வேண்டாம். பிளாட் சரிதான். கண்காணிப்பு பட்டியல் ★ மற்றும் தெளிவான வாங்குதல்/விற்பனை அல்லது BB லோயர் வேட்பாளருக்கு காத்திருக்கவும்."},{"h":"மதிப்பெண் எண்","t":"அதிக |மதிப்பெண்| = கருவிகளுக்கு இடையே அதிக உடன்பாடு. BUY +5 ஆனது BUY +3 ஐ விட வலிமையானது - இன்னும் சார்ட் லேப் மெழுகுவர்த்திகளை அளவு முன் உறுதிப்படுத்தவும்."},{"h":"பிபி கீழ் பலகை","t":"பொலிங்கர் லோயர் பேண்டைக் குறிக்கும் ஜோடிகளின் தனிப் பட்டியல் - நீண்ட விண்ணப்பதாரர்களைப் பயிற்சி செய்யுங்கள். இன்னும் மெழுகுவர்த்தி தேவை + RSI உறுதிப்படுத்தல்; ஒவ்வொரு குறைந்த தொடுதலும் ஒரு நுழைவு அல்ல."},{"h":"பிளாட்ஃபார்ம் vs சிக்னல் (முக்கியம்)","t":"Binance, Bybit, OKX, KuCoin, Bitget, Gate, MEXC, Kraken, Coinbase, OANDA, FXCM, MT5, Forex Demo ஆகியவற்றில் சிக்னல் கணிதம் அதே யோசனையாகும். நீங்கள் ஆர்டரை எங்கு அனுப்புகிறீர்கள் என்றால் என்ன மாற்றங்கள்: API விசைகள் / இப்போது வர்த்தகத்தில் தேர்ந்தெடுக்கப்பட்ட தளம் மட்டுமே. பைபிட்டில் பைனான்ஸ் வாங்குதல் திறக்கப்படாது."},{"h":"கிரிப்டோ ஸ்பாட் இயங்குதளங்கள்","t":"பைனன்ஸ் ஸ்பாட், காயின்பேஸ் போன்றவை: வாங்கு = மேற்கோளுடன் நாணயத்தை வாங்கவும் (எ.கா. USDT). விற்பனை = பங்குகளை விற்பது / லாபம் எடுப்பது. குறைந்தபட்ச அளவு (எ.கா. ~$11) முக்கியமானது. அந்நியச் செலாவணி இல்லை."},{"h":"கிரிப்டோ ஃபியூச்சர்ஸ் இயங்குதளங்கள்","t":"பைனான்ஸ் ஃபியூச்சர்ஸ், பைபிட், ஓகேஎக்ஸ், பிட்ஜெட்...: வாங்கு = நீண்டது; விற்க = குறுகிய. குறுக்கு/தனிமைப்படுத்தப்பட்ட + லீவரேஜ் கவனமாக தேர்ந்தெடுக்கவும். பாதை: TP+SL வரை செல்லும் பாதைகளை வாங்கவும்; தடங்களை கீழே விற்கவும்."},{"h":"அந்நிய செலாவணி தளங்கள்","t":"OANDA / FXCM / MT5 / அந்நிய செலாவணி டெமோ: FX ஜோடிகளில் (EURUSD...) அதே வாங்குதல்/விற்பனை/பிடித்தல் லேபிள்கள். வாங்க = அடிப்படை நாணயத்தை வாங்கவும்; விற்பனை = விற்பனை அடிப்படை. காயின் க்யூட்டிக்கு பதிலாக நிறைய (எ.கா. 0.01). அமர்வுகள் மற்றும் செய்திகள் அதிகம்."},{"h":"வாங்குதல் தோன்றும் போது - இதைச் செய்யுங்கள்","t":"① வரிசையைத் திறக்கவும் → ஏன் / மெழுகுவர்த்தி / RSI என்பதைப் படிக்கவும். ② விளக்கப்பட ஆய்வகம் உறுதிப்படுத்துகிறது (15m–1H). ③ முதலில் டெமோ: இப்போது வர்த்தகம் செய் → TP1/TP2/SL/trail ஐ அமைக்கவும் → டெமோ/பேப்பரைத் தொடங்கவும். ④ API சோதனைக்குப் பிறகுதான் அந்த பிளாட்ஃபார்மில் சரி → சிறிய நேரலை. ⑤ இதழ் முடிவு."},{"h":"ஒரு விற்பனை தோன்றும் போது - இதைச் செய்யுங்கள்","t":"① நீங்கள் லாங் ஸ்பாட் என்றால்: TP / பகுதி மூடல் / பாதை - புறக்கணிக்க வேண்டாம். ② எதிர்காலம்/அந்நிய செலாவணி மற்றும் திட்டம் குறுகியதாக அனுமதித்தால்: விளக்கப்பட ஆய்வகத்தை உறுதிப்படுத்தவும், பின்னர் பேப்பர்/லைவ் ஷார்ட் SL உடன். ③ நேற்று HOLD சிறப்பாக இருந்திருந்தால், ஃபிளிப் அளவைப் பழிவாங்க வேண்டாம்."},{"h":"HOLD தோன்றும் போது - இதைச் செய்யுங்கள்","t":"புதிய கையேடு நுழைவு இல்லை. ஸ்கேன் செய்து கொண்டே இருங்கள். ★ கவனிப்புப் பட்டியலைச் சேர்க்கவும். படிப்பு கற்றல் வகுப்பு / விளக்கப்படம் ஆய்வகம். ஏற்கனவே வர்த்தகத்தில் இருந்தால் மட்டுமே திறந்த நிலைகளை பாதையுடன் பாதுகாக்கவும்."},{"h":"ஆட்டோ டிரேட் + சிக்னல்","t":"BB லோயர் + ஸ்ட்ராங்கான ஸ்கோர் விதிகள் நீங்கள் சேமித்த தானியங்கு கட்டமைப்புக்கு பொருந்தும்போது ஆட்டோ வாங்குதல் திறக்கப்படும். இன்னும் டெமோ-சோதனை ஆட்டோவை முதலில். லைவ் ஆட்டோ = உண்மையான ஆபத்து - திரும்பப் பெறுதல்கள் ஆஃப், சிறிய அளவு."},{"h":"அறிவிப்புகள்","t":"உங்கள் மொழியைப் பின்பற்றும் சிக்னல் டோஸ்ட்களை வாங்கவும். மேசையைத் திறப்பதற்கான விழிப்பூட்டல்களாக அவற்றைக் கருதுங்கள் - சந்தை ஆர்டர்களாக அல்ல."},{"h":"என்ன செய்யக்கூடாது","t":"விளக்கப்படம் இல்லாமல் ஒவ்வொரு வாங்குதலையும் வாங்க வேண்டாம். பைபிட்டில் பைனன்ஸ் விசையைப் பயன்படுத்த வேண்டாம். SL ஐத் தவிர்க்க வேண்டாம். ஒரு பச்சை சமிக்ஞைக்குப் பிறகு அளவை உயர்த்த வேண்டாம். HOLD ஐ \"கிட்டத்தட்ட வாங்கு\" என்று வர்த்தகம் செய்ய வேண்டாம்."},{"h":"விரைவான செயல் அட்டை","t":"சிக்னல் → சார்ட் லேப் → ரிஸ்க் % → TP1/TP2/SL → டெமோ பேப்பர் → ஜர்னல் → (பின்னர்) பொருந்தும் இயங்குதள விசையில் நேரலை."}]},{"id":"forex_sig","title":"7 · அந்நிய செலாவணி சமிக்ஞைகள் - பொருள் & என்ன செய்ய வேண்டும்","summary":"ஃபாரெக்ஸ் டெஸ்க் FX ஜோடிகளில் அதே வாங்க / விற்க / பிடி மதிப்பீட்டைப் பயன்படுத்துகிறது. அந்நிய செலாவணி சிக்னல்கள் கிரிப்டோவிலிருந்து எவ்வாறு வேறுபடுகின்றன என்பதையும், சிக்னல் → பேப்பர் → லைவ் புரோக்கரிடமிருந்து சரியான படிகளையும் அறிக.","lessons":[{"h":"அந்நிய செலாவணி மேசை சமிக்ஞைகள்","t":"EURUSD, GBPUSD, USDJPY... கிரிப்டோ போன்ற ஸ்கோரை வாங்கவும் / விற்கவும் / வைத்திருக்கவும். விளக்கப்படம், உளவியல் உரை மற்றும் பரிந்துரைக்கப்பட்ட நிலைகளுக்கு ஒரு வரிசையைக் கிளிக் செய்யவும்."},{"h":"அந்நிய செலாவணியில் வாங்கவும் - பொருள்","t":"அடிப்படை நாணயத்தை வாங்கவும் (எ.கா. வாங்க EURUSD = வாங்க EUR vs USD). விலையை எதிர்பார்க்கலாம். நீங்கள் பயிற்சி செய்யும் Chart Lab Forex இடைவெளியைப் பயன்படுத்தவும் (15m/30m/1H)."},{"h":"அந்நிய செலாவணி மீது விற்க - பொருள்","t":"அடித்தளத்தை விற்கவும் (ஜோடியை சுருக்கவும்). விலை குறையும் என எதிர்பார்க்கலாம். எப்பொழுதும் SL ஐ அமைப்பு / மேல் இசைக்குழு யோசனைக்கு மேலே அமைக்கவும்."},{"h":"அந்நிய செலாவணியை வைத்திருங்கள்","t":"தெளிவான விளிம்பு இல்லை - தவிர்க்கவும். குறிப்பாக பெரிய செய்திகளுக்கு முன் (NFP, CPI, central bank) HOLD / flat என்பதை விரும்புகிறது."},{"h":"அந்நிய செலாவணி டெமோ விகிதங்கள் தளம்","t":"API விசை இல்லை. பயிற்சி விளக்கப்படங்கள் + காகிதம் மட்டும். OANDA/FXCM/MT5 நேரலைக்கு முன் வகுப்பு பயிற்சிகளை கற்றுக்கொள்வதற்கு ஏற்றது."},{"h":"OANDA சமிக்ஞை → நடவடிக்கை","t":"① அந்நிய செலாவணி மேசை வாங்க / விற்க. ② விளக்கப்பட ஆய்வகம் உறுதிப்படுத்துகிறது. ③ API விசைகள் → OANDA டோக்கன் + கணக்கு ஐடி → சோதனை. ④ முதலில் CPE இல் டெமோ பேப்பர். ⑤ TP/SL/trail உடன் சிறிய நேரடி இடங்கள் (0.01 மனநிலை)."},{"h":"FXCM / MT5","t":"அதே சமிக்ஞை வாசிப்பு. API விசைகளின் கீழ் அந்த தரகரின் நற்சான்றிதழ்களை இணைக்கவும். விசைகள்/பிரிட்ஜ் அமைக்கப்படும் வரை சிக்னல் உங்களுக்காக MT5 ஐ தானாக உள்நுழையாது - சோதனை சரி வரை காகிதத்தை பயிற்சி செய்யுங்கள்."},{"h":"அமர்வுகள்","t":"லண்டன்-NY ஒன்றுடன் ஒன்று பெரும்பாலும் மேஜர்களை அதிகமாக நகர்த்துகிறது. ஆசியா அமைதியாக இருக்கலாம் - ஹோல்ட் பொதுவானது மற்றும் ஆரோக்கியமானது."},{"h":"பரவல் & செய்தி","t":"செய்திகளைச் சுற்றி, பரவல்கள் விரிவடைகின்றன - ஒரு நல்ல தொழில்நுட்ப வாங்குதல் இன்னும் மோசமான நிரப்பலாக இருக்கலாம். செய்திகள் & தந்திரங்களைச் சரிபார்க்கவும்; ஸ்பைக்கிற்குப் பிறகு மெழுகுவர்த்தியை மூடுவதற்கு காத்திருக்கவும்."},{"h":"நிறைய vs கிரிப்டோ க்யூடி","t":"அந்நிய செலாவணி அளவு = நிறைய, அதே வழியில் USDT கற்பனையானது அல்ல. ஆபத்து% இன்னும் விதிகள்: பரந்த SL → சிறிய நிறைய."},{"h":"அந்நிய செலாவணியில் பிபி லோயர்","t":"அதே யோசனை: லோயர் பேண்ட் அருகே ஜோடி + சுத்தி + RSI ரைசிங் = நீண்ட ஆய்வு பயிற்சி. அதிக TF சார்பு (4H/தினமும்) உறுதிப்படுத்தவும்."},{"h":"அந்நிய செலாவணி வாங்கும்போது தீ - படிகள்","t":"① ஏன் என்று படிக்கவும். ② அதிக TF சார்பு சரியா? ③ விக்/கட்டமைப்புக்கு அப்பால் SL ஐக் குறிக்கவும். ④ காகித வர்த்தகம். ⑤ நேரலை தரகர் தயாராக இருந்தால் → சிறிய அளவு + பாதை. ⑥ ஜர்னல் அமர்வு (லண்டன்/NY) + உணர்ச்சி."},{"h":"அந்நிய செலாவணி விற்கும் போது - படிகள்","t":"① நடு செய்தி ஸ்பைக் அல்ல என்பதை உறுதிப்படுத்தவும். ② விளக்கப்பட ஆய்வகம் தாங்கும் மெழுகுவர்த்தி. ③ காகிதம் குறுகிய அல்லது நெருக்கமான நீளம். ④ குறுகியதாக இருந்தால் கீழே செல்லவும். ⑤ தவறிய பிறகு இரட்டிப்பாக்க வேண்டாம்."},{"h":"அந்நிய செலாவணி vs கிரிப்டோ வேறுபாடு","t":"கிரிப்டோ 24/7; அந்நிய செலாவணி அமர்வுகள் உள்ளன. கிரிப்டோ நிமிடம் $ அடிக்கடி; அந்நிய செலாவணி நிறைய + பிப் மதிப்பு. கிரிப்டோ பல மாற்றுகள் தொடர்புள்ளவை; கற்றலுக்கான ஃபாரெக்ஸ் மேஜர்கள் கிளீனர்."},{"h":"பயிற்சி சரிபார்ப்பு பட்டியல் (FX)","t":"① ஜோடி முக்கியமா? ② அமர்வு சரியா? ③ செய்தி தெளிவாக இருக்கிறதா? ④ சிக்னல் வாங்க/விற்கவில்லையா? ⑤ விளக்கப்படம் உறுதிப்படுத்தப்படுகிறதா? ⑥ ஆபத்து %? ⑦ தாள் → ஜர்னல் → நேரலை தரகர் விசை தயாராக இருக்கும் போது மட்டுமே."}]},{"id":"fomo","title":"8 · FOMO & உணர்ச்சி ஒழுக்கம்","summary":"FOMO, பழிவாங்குதல், பேராசை மற்றும் பயம் ஆகியவை உண்மையான கணக்கு கொலையாளிகள் - குறிகாட்டிகள் அல்ல. தூண்டுதல்கள், உடல் அறிகுறிகள் மற்றும் உந்துவிசை வர்த்தகங்களை உங்கள் கணக்கிற்கு வெளியே வைத்திருக்கும் சரியான விதிகளை அறிந்து கொள்ளுங்கள்.","lessons":[{"h":"FOMO உண்மையில் என்ன","t":"FOMO = உங்கள் மண்டலத்திலிருந்து ஏற்கனவே தொலைவில் உள்ள ஒரு நகர்வைக் காணவில்லை என்ற பயம். மோசமான விலை மற்றும் சரியான SL இல்லாமையுடன் தாமதமாக நுழையச் செய்கிறது. நீங்கள் \"தவறவிட்ட\" மெழுகுவர்த்தி தகவல், இழப்பு அல்ல."},{"h":"மூன்று FOMO தூண்டுதல்கள்","t":"① விளக்கப்படத்தில் ஒரு பெரிய பச்சை அல்லது சிவப்பு மெழுகுவர்த்தி. ② லாபத்தைக் காட்டும் நண்பர் அல்லது டெலிகிராம் இடுகை. ③ ஒரு செய்தி தலைப்பு. நுழைவைக் கவனிப்பதற்கு முன் தூண்டுதலைக் கவனியுங்கள்."},{"h":"உடல் அறிகுறிகள்","t":"வேகமாக இதயத்துடிப்பு, திரையில் சாய்ந்து, சந்தை வாங்க-இப்போது கிளிக் செய்யவும், உங்கள் சரிபார்ப்புப் பட்டியலைத் தவிர்க்கவும். இதை நீங்கள் உணர்ந்தால், தாவலை மூடிவிட்டு ஒரு மெழுகுவர்த்தியை காத்திருக்கவும்."},{"h":"\"ஏற்கனவே இயங்கியது\" விதி","t":"நீங்கள் திட்டமிட்ட நுழைவைத் தாண்டி விலை ஏறக்குறைய 1 ATR ஐ விட அதிகமாக நகர்ந்திருந்தால், வர்த்தகம் இல்லாமல் போய்விடும். BB மிட் / ஃபைபிற்கு திரும்பும் வரை காத்திருக்கவும் அல்லது தவிர்க்கவும். எப்போதும் மற்றொரு அமைப்பு உள்ளது."},{"h":"பச்சை மெழுகுவர்த்தி பொறி","t":"நீங்கள் திட்டமிடாத ஒரு மருபோசு ஒரு துரத்தல், ஒரு நுழைவு அல்ல. தாமதமான பதிவுகளுக்கு மிக மோசமான வெகுமதி: ஆபத்து, ஏனெனில் நிறுத்தம் வெகு தொலைவில் முடிவடைகிறது."},{"h":"பழிவாங்கும் வர்த்தகம்","t":"ஒரு தோல்விக்குப் பிறகு மூளை இப்போது அதை மீண்டும் வெல்ல விரும்புகிறது. விதி: இழப்புக்குப் பிறகு 15-30 நிமிடங்களுக்கு புதிய நுழைவு இல்லை, சரிபார்ப்புப் பட்டியல் சுத்தமாக இருந்தால் மட்டுமே. சந்தை உங்களுக்கு எதுவும் கடன்பட்டிருக்காது."},{"h":"தூண்டிலை இழுக்க பயம்","t":"எதிர் சிக்கல்: ஒரு சரியான அமைப்பு தோன்றும் மற்றும் நீங்கள் உறைந்துவிடும். செயல்முறையை நிரூபிக்க ஒரு சிறிய டெமோ அளவைப் பயன்படுத்தவும், மேலும் மெழுகுவர்த்தி தோன்றும் முன் உங்கள் அளவைத் தீர்மானிக்கவும், எனவே முடிவு ஏற்கனவே எடுக்கப்பட்டுள்ளது."},{"h":"வெற்றிக்குப் பின் பேராசை","t":"இரண்டு பச்சை வர்த்தகங்கள் உங்களை வெல்ல முடியாததாக உணரவைக்கும், பின்னர் நீங்கள் இரட்டிப்பாகும். குறைந்தபட்சம் 20 வர்த்தகங்களுக்கு ஆபத்து% நிலையானது; வெற்றி கோடுகள் அர்த்தம்-திரும்புதல்."},{"h":"சலிப்பு வர்த்தகம்","t":"பிளாட் என்பது ஒரு நிலை. A+ அமைப்பு இல்லை என்றால், ஏதாவது நடக்க வேண்டாம். சலிப்பு வர்த்தகங்கள் மாறுவேடத்தில் FOMO உள்ளன."},{"h":"திரை நேர ஒழுக்கம்","t":"விளக்கப்படங்களைப் பார்ப்பதற்குப் பதிலாக ஒரு நாளைக்கு இரண்டு அல்லது மூன்று ஸ்கேன் சாளரங்களை அமைக்கவும். குறைவான முடிவுகள் என்பது குறைவான உந்துவிசை முடிவுகளைக் குறிக்கிறது."},{"h":"உணர்ச்சி இதழ்","t":"ஒவ்வொரு வர்த்தக அமைதி / அவசரம் / FOMO / பழிவாங்குதல் ஆகியவற்றைக் குறிக்கவும். 20 வர்த்தகங்களுக்குப் பிறகு உங்கள் கசிவுகளின் வடிவம் தெளிவாகிறது."},{"h":"சடங்குகளை மீட்டமைக்கவும்","t":"இழப்பு அல்லது ஒரு FOMO ஸ்லிப்புக்குப் பிறகு: எழுந்து நின்று, 10 மெதுவாக சுவாசிக்கவும், என்ன நடந்தது என்பதைப் பற்றி ஒரு வாக்கியத்தை எழுதவும், பின்னர் ஒரு மணிநேரம் நிறுத்தவும் அல்லது சாதாரண ஆபத்தில் பாதியில் தொடரவும்."},{"h":"பயிற்சி பட்டியல்","t":"① அமைதியான உடலா? ② தூண்டுதல் கவனிக்கப்பட்டதா? ③ எனது மண்டலத்தில் அமைக்கவா? ④ SL முதலில் எழுதப்பட்டதா? ⑤ ஆபத்து% மாறவில்லையா? ⑥ பழிவாங்கவில்லையா? எந்த NO → வர்த்தகம் இல்லை."}]},{"id":"risk_deep","title":"9 · இடர் மற்றும் பண மேலாண்மை - ஆழமான","summary":"கணக்கை உயிர்ப்புடன் வைத்திருக்கும் கணிதம்: நிலையான-பிரிவு அளவு, R-பெருக்கங்கள், டிராடவுன் கணிதம், தொடர்பு வெப்பம் மற்றும் தினசரி நிறுத்தம். வர்த்தகத்தை எண்களால் நடத்தப்படும் வணிகமாக மாற்றவும்.","lessons":[{"h":"நிலையான பகுதி ஆபத்து","t":"ஒரு யோசனைக்கு ஒரு நிலையான % (0.5–1%) சமபங்கு அபாயம். அளவு என்பது நிறுத்த தூரத்தின் விளைவாகும், முதலில் தேர்ந்தெடுக்கப்படவில்லை. பரந்த SL → சிறிய அளவு; இறுக்கமான SL → பெரிய அளவு; டாலர் ஆபத்து அப்படியே இருக்கும்."},{"h":"அளவு சூத்திரம்","t":"அளவு = (ஈக்விட்டி × ரிஸ்க்%) ÷ |நுழைவு - நிறுத்து|. எடுத்துக்காட்டு: $1000 × 1% = $10 ஆபத்து. நுழைவு 100, நிறுத்தம் 98 → தூரம் 2% → அளவு 10 ÷ 0.02 = $500 கற்பனையானது."},{"h":"R-பன்மடங்குகளில் சிந்தியுங்கள்","t":"ஒரு வர்த்தகத்திற்கு ஆபத்து 1R. 2R வெற்றியாளர் இரண்டு இழப்புகளுக்கு பணம் செலுத்துகிறார். 20 வர்த்தகங்களுக்கு மேல் உங்கள் சராசரி R ஐக் கண்காணிக்கவும் - இது உங்கள் உண்மையான விளிம்பு, வெற்றி விகிதம் அல்ல."},{"h":"வெகுமதி: ஆபத்து","t":"நுழைவதற்கு முன் குறைந்தபட்சம் 1.5R திறனைக் குறிக்கவும். அதற்குக் கீழே, உங்கள் வெற்றி விகிதம் மிக அதிகமாக இருந்தால் தவிர, அதைத் தவிர்க்கவும்."},{"h":"வரைதல் கணிதம்","t":"ஒரு −50% டிராடவுனை மீட்டெடுக்க +100% தேவை. தோல்விகள் இயல்பானவை: 60% வெற்றி-விகித அமைப்பில் கூட 5+ இழப்புகள் உள்ளன. சிறிய ஆபத்து ஸ்ட்ரீக்கை உயிர்வாழ வைக்கிறது."},{"h":"தினசரி நிறுத்தம்","t":"கடினமான விதி: ஒரு நாளில் ஈக்விட்டியின் −2%க்குப் பிறகு (அல்லது ஒரு வரிசையில் 2–3 இழப்புகள்) வர்த்தகத்தைத் திறப்பதை நிறுத்துங்கள். வரம்புக்கு பிறகு பழிவாங்கும் அமர்வுகள் கணக்கு கொலையாளிகள்."},{"h":"வாராந்திர மற்றும் மாதாந்திர வரம்புகள்","t":"வாரத்தையும் (உதாரணமாக −5%) மாதத்தையும் வரம்பிடவும். அடிக்கும்போது, ​​டெமோவுக்குச் சென்று, ஜர்னலை மதிப்பாய்வு செய்து, சுத்தமான ஓட்டத்திற்குப் பிறகு மட்டுமே அளவை மீண்டும் எடுக்கவும்."},{"h":"திறந்த வெப்பம்","t":"அனைத்து திறந்த வர்த்தகங்களிலும் மொத்த ஆபத்து 3% அல்லது குறைவாக இருக்க வேண்டும். ஐந்து தொடர்புள்ள மாற்றுகள் ஒரு பந்தயம், ஐந்து அல்ல - ஒன்றோடொன்று தொடர்புடைய வெளிப்பாட்டைக் கணக்கிடுங்கள்."},{"h":"ஸ்பாட் அளவு","t":"ஸ்பாட்டுக்கு குறைந்தபட்ச கருத்து உள்ளது. பரிவர்த்தனை குறைந்தபட்சம் உங்கள் 1% ஐ விட அதிகமாக ஆபத்தை ஏற்படுத்தினால், வர்த்தகத்தைத் தவிர்க்கவும் - ஒருபோதும் ஆபத்தை அதிகரிக்க வேண்டாம்."},{"h":"எதிர்கால அளவு","t":"அந்நியச் செலாவணி மாற்றங்கள் விளிம்பு, ஆபத்து அல்ல. ஆபத்து இன்னும் நுழைவு - நிறுத்தம் × அளவு. கற்கும் போது குறைந்த அந்நியச் செலாவணியைப் பயன்படுத்தவும் மற்றும் தனிமைப்படுத்தப்பட்ட விளிம்பை விரும்பவும்."},{"h":"அந்நிய செலாவணி அளவு","t":"ஆபத்து = நிறைய × பிப்-மதிப்பு × ஸ்டாப்-பிப்ஸ். நிறைய தீர்க்கவும். தோராயமான வழிகாட்டி: 0.01 நிறைய ≈ $0.10 ஒரு பைப்; $1000 ($10) → 10 ÷ 0.10 ÷ 20 = 0.05 நிறையில் 1% ஆபத்துள்ள 20-பிப் நிறுத்தம்."},{"h":"அளவிடுதல்","t":"TP1 இல் 50% தள்ளுபடியைப் பெறுங்கள், மீதமுள்ளவற்றை ரிஸ்க் இல்லாததாக மாற்றவும், பின் தொடரவும். இது ஒரு நல்ல வர்த்தகத்தை குறைந்த அழுத்த ரன்னராக மாற்றுகிறது."},{"h":"கலவை எதிராக நிலையானது","t":"தற்போதைய ஈக்விட்டியின் நிலையான % (கலவை) ஆபத்து. உங்கள் ஆபத்தை எல்லா நேரத்திலும் உயர்ந்த கணக்கு அளவில் சரிசெய்ய வேண்டாம்."},{"h":"R இல் கட்டணம் மற்றும் சறுக்கல்","t":"R. 0.2% கட்டணத்தை R. 0.5% உச்சந்தலையில் இருந்து கழித்தால் விளிம்பைத் துடைக்க முடியும் - தூய்மையான ஊசலாட்டங்களை விரும்புங்கள்."},{"h":"\"நிறுத்தம் இல்லை, வர்த்தகம் இல்லை\" சட்டம்","t":"நீங்கள் ஒரு தர்க்கரீதியான நிறுத்தத்தை வரையறுக்க முடியாவிட்டால், உங்கள் ஆபத்து உங்களுக்குத் தெரியாது, எனவே அளவு இல்லை, எனவே வர்த்தகம் இல்லை."},{"h":"மார்டிங்கேல் எதிர்ப்பு","t":"தோல்விக்குப் பிறகு இரட்டிப்பாக்க வேண்டாம். நிரூபிக்கப்பட்ட செயல்முறையின் பல லாபகரமான, ஒழுக்கமான வாரங்களுக்குப் பிறகு மட்டுமே அளவை அதிகரிக்கவும் - பின்னர் மெதுவாகவும்."},{"h":"பயிற்சி பட்டியல்","t":"① ஈக்விட்டி அறியப்பட்டது ② ஆபத்து % எழுதப்பட்டது ③ நிறுத்தம் வரையறுக்கப்பட்டது ④ நிறுத்தத்தில் இருந்து அளவு ⑤ வெகுமதி ≥ 1.5R ⑥ தினசரி நிறுத்தம் அறியப்படுகிறது ⑦ தொடர்புடைய வெப்பம் கணக்கிடப்பட்டது."}]},{"id":"sl_tp","title":"10 · இழப்பை நிறுத்துங்கள் & லாபத்தில் தேர்ச்சி பெறுங்கள்","summary":"சந்தை நீங்கள் தவறு என்று நிரூபிக்கும் இடத்தில் SL ஐ வைக்கவும், படிகளில் லாபம் எடுங்கள் மற்றும் ஒரு வெற்றியாளர் ஓடக்கூடிய நிறுத்தத்தை பின்தொடரவும் - CPE ஆனது மல்டி-டிபி மற்றும் பின்தங்கிய SL உடன் என்ன செய்கிறது.","lessons":[{"h":"SL என்பது ஒரு முடிவு, எண் அல்ல","t":"யோசனை செல்லுபடியாகாத இடத்தில் நிறுத்தத்தை (ஸ்விங் லோ, விக் அல்லது கட்டமைப்பின் கீழே) ரேண்டம் டாலர் தூரத்தில் வைக்கவும். நீங்கள் தகவலை வாங்குகிறீர்கள்: விலை இங்கு சென்றால், எனது காரணம் தவறு."},{"h":"கட்டமைப்பு நிறுத்தப்படும்","t":"நீளம்: ஸ்விங் லோ அல்லது லோயர்-பேண்ட் விக்கிற்குக் கீழே SL. குட்டை: ஊஞ்சலுக்கு சற்று மேலே. 0.1–0.3% பரவல் மற்றும் விக் இரைச்சலுக்கு சிறிய இடையகத்தைக் கொடுங்கள்."},{"h":"நிலையற்ற தன்மை நிறுத்தப்படும்","t":"பரந்த சந்தைகளுக்கு பரந்த நிறுத்தங்கள் தேவை. நிறுத்தத்தை அளவிட ATR அல்லது விக் நீளத்தைப் பயன்படுத்தவும், பின்னர் நிலையை சுருக்கவும், இதனால் டாலர் ஆபத்து அப்படியே இருக்கும்."},{"h":"ஒரு நிலையான டாலர் SL ஏன் தோல்வியடைகிறது","t":"BTC இல் $10 நிறுத்தமும் EURUSD இல் $10 நிறுத்தமும் முற்றிலும் வேறுபட்ட ஆபத்து. தூரத்தை % இல் அளவிட வேண்டும், டாலர்களில் அல்ல."},{"h":"எதிர்ப்பு-வேட்டை இடையக","t":"CPE ஒற்றை விக் தொடுதலைப் புறக்கணிக்கிறது: மூடுவதற்கு முன் அதற்கு இரண்டு தொடர்ச்சியான மீறல்கள் மற்றும் ஒரு சிறிய இடையக (0.15%) தேவை. அது உங்கள் நிறுத்தத்தை வேட்டையாடுவதை சத்தம் நிறுத்துகிறது."},{"h":"படிகளில் லாபம் எடுங்கள்","t":"ஒரு விலையில் 100% மூட வேண்டாம். அளவிடவும்: TP1 புத்தகங்களின் பகுதி, பின்னர் TP2 / ட்ரெயில் மீதமுள்ளவற்றைச் செலுத்துகிறது, இதனால் பல தோல்வியாளர்களுக்கு ஒரு பெரிய நகர்வு செலுத்த முடியும்."},{"h":"பல TP நிலைகள்","t":"CPE உங்களுக்குத் தேவையான பல TP நிலைகளைச் சேர்க்க உதவுகிறது, ஒவ்வொன்றும் அதன் சொந்த நெருக்கமான%. எடுத்துக்காட்டு: TP1 40%, TP2 30%, TP3 30% — அல்லது TP1 ஐ எடுத்து மீதமுள்ளவற்றைப் பின்தொடரவும்."},{"h":"நிறுத்தத்தை பின்தொடர்கிறது","t":"TP1 க்குப் பிறகு நிறுத்தத்தை பிரேக்வெனுக்கு நகர்த்தவும்; TP2 க்குப் பிறகு அதை TP1 க்கு நகர்த்தவும். நிறுத்தம் விலையைப் பின்தொடரட்டும், இதனால் ரன்னர் தொடரும் போது திறந்த லாபம் பாதுகாக்கப்படும்."},{"h":"பாதையைத் தேர்ந்தெடுப்பது %","t":"ஒரு இறுக்கமான பாதை லாபத்தை வேகமாகப் பூட்டுகிறது ஆனால் முன்கூட்டியே வெளியேறுகிறது; ஒரு பரந்த பாதை சுவாசிக்கிறது ஆனால் சில திரும்ப கொடுக்கிறது. கிரிப்டோவிற்கு சுமார் 1-2% தொடங்கி, அதை நிலைகள் திருத்த மாதிரியில் டியூன் செய்யவும்."},{"h":"ஓடுபவர்கள்","t":"விலை ஒரு வலுவான போக்கில் இசைக்குழுவை நடத்தும் போது, எல்லாவற்றையும் TP2 இல் எடுப்பதற்குப் பதிலாக இலக்கையும் பாதையையும் விரிவுபடுத்துங்கள். ஒரு வர்த்தகம் ஒரு வாரம் முழுவதும் இப்படித்தான் செலுத்துகிறது."},{"h":"பகுதி-மூடு பொத்தான்கள்","t":"கைமுறைக் கட்டுப்பாட்டிற்காக நிலைகளில் உள்ள 50% / 100% மூடு பொத்தான்களைப் பயன்படுத்தவும் அல்லது திட்டத்தின் மூலம் TP / SL ஐ தானாக மூடுவதை நிர்வகிக்க அனுமதிக்கவும்."},{"h":"பிரேக்ஈவன் பொறி","t":"TP1 க்கு முன், SLஐ பிரேக்ஈவெனுக்கு மிக விரைவாக நகர்த்த வேண்டாம் - சாதாரண இழுத்தல்கள் உங்களை நல்ல வர்த்தகத்தில் இருந்து வெளியேற்றும்."},{"h":"இழந்த நிறுத்தத்தை ஒருபோதும் விரிவுபடுத்தாதீர்கள்","t":"SLஐ அதிக தூரம் நகர்த்தி அதற்கு இடம் கொடுப்பது எப்படி சிறிய இழப்புகள் கணக்கு கொலைகாரர்களாக மாறுகிறது. நுழைவதற்கு முன் நீங்கள் அமைத்த நிறுத்தம் நிறுத்தமாகும்."},{"h":"நேரம் நிறுத்தம்","t":"ஒரு வர்த்தகம் பல மெழுகுவர்த்திகளுக்கு எதுவும் செய்யவில்லை என்றால், ஒரு தெளிவான சிறந்த அமைப்பு உருவாகிறது, பிளாட் மூடுவது மற்றும் ஆபத்தை மறுபகிர்வு செய்வது சரியான வெளியேற்றமாகும்."},{"h":"பயிற்சி பட்டியல்","t":"① SL செல்லாத நிலையில் உள்ளது, சீரற்றது அல்ல ② விக்குகளுக்கான இடையகம் ③ TP1 பகுதி திட்டமிடப்பட்டது ④ TP1 க்குப் பிறகு ட்ரெயில் ⑤ SL ஐ விரிவுபடுத்த வேண்டாம் ⑥ வெற்றியாளர் ஓடட்டும்."}]},{"id":"plan_journal","title":"11 · வர்த்தகத் திட்டம் & ஜர்னலிங்","summary":"எழுதப்பட்ட திட்டம் சூதாட்டத்திலிருந்து வர்த்தகத்தை ஒரு செயல்முறையாக மாற்றுகிறது. ஒரு பக்கத் திட்டம், வர்த்தகத்திற்கு முந்தைய சரிபார்ப்புப் பட்டியல் மற்றும் உங்கள் கசிவுகள் தெரியும் வகையில் எப்படி ஜர்னல் செய்வது என்பதை அறியவும்.","lessons":[{"h":"ஏன் ஒரு திட்டத்தை எழுத வேண்டும்","t":"எழுதவில்லை என்றால் அது விதி அல்ல. ஒரு திட்டம் மன அழுத்தத்தின் கீழ் நேரடி முடிவெடுப்பதை நீக்குகிறது மற்றும் உங்கள் முடிவுகளை அளவிடக்கூடியதாக ஆக்குகிறது."},{"h":"ஒரு பக்க திட்டம்","t":"ஜோடி, சந்தை, அமைவு (BB + RSI + மெழுகுவர்த்தி + Fib மண்டலம்), திசை, நுழைவு, SL, TP1 / TP2, அளவு (SL இலிருந்து) மற்றும் அதிகபட்ச தினசரி இழப்பு. எந்த வரியும் காலியாக இருந்தால் → வர்த்தகம் இல்லை."},{"h":"வர்த்தகத்திற்கு முந்தைய சரிபார்ப்பு பட்டியல்","t":"உயர்-TF சார்பு? · எனது மண்டலத்தில் அமைக்கவா? · மெழுகுவர்த்தி உறுதிப்படுத்தவா? · RSI ஒப்புக்கொள்கிறதா? · SL எழுதப்பட்டதா? · ஆபத்து %? · வெகுமதி ≥ 1.5R? · அமைதியா? அனைத்தும் ஆம் → வர்த்தகம்."},{"h":"அமர்வுக்கு முந்தைய வழக்கம்","t":"அதிக காலக்கெடு, முக்கிய நிலைகள் மற்றும் செய்திகளை சரிபார்க்கவும். இன்றைய இரண்டு அல்லது மூன்று வாட்ச் ஜோடிகளை அமர்வுக்கு முன் எழுதுங்கள் - மெழுகுவர்த்தி வெடித்த பிறகு அல்ல."},{"h":"என்ன பத்திரிகை செய்ய வேண்டும்","t":"சின்னம், பக்கம், நுழைவு, வெளியேறு, அளவு, R, காரணம், காலக்கெடு, அமர்வு மற்றும் ஒரு உணர்ச்சிக் குறிச்சொல். CPE ஜர்னல் P/L மற்றும் காரணங்களை தானாகவே சேமிக்கிறது; உங்கள் சொந்த குறிப்புகளைச் சேர்க்கவும்."},{"h":"ஏன் ஜர்னல்","t":"நீங்கள் பார்த்ததை (அமைவு) மற்றும் நீங்கள் உணர்ந்ததை (அமைதி / FOMO / அவசரம்) பதிவு செய்யுங்கள். சூழல் இல்லாத முடிவு எதையும் கற்பிக்காது."},{"h":"ட்ராக் ஆர், வெற்றிகள் அல்ல","t":"ஒரே வெற்றி விகிதத்தைக் கொண்ட இரண்டு வர்த்தகர்கள் எதிர் முடிவுகளைப் பெறலாம். சராசரி R மற்றும் அதிகபட்ச டிராடவுன் வெற்றி% ஐ விட அதிகம்."},{"h":"ஸ்கிரீன்ஷாட் பழக்கம்","t":"ஒவ்வொரு வர்த்தகத்திற்கும் முன்னும் பின்னும் விளக்கப்படத்தை சேமிக்கவும். 20 ஸ்கிரீன் ஷாட்களை மதிப்பாய்வு செய்வது உங்கள் விளிம்பையும் உங்கள் கசிவுகளையும் எந்த குறிகாட்டியையும் விட வேகமாக காட்டுகிறது."},{"h":"வாராந்திர ஆய்வு","t":"வாரத்திற்கு ஒருமுறை உங்கள் வர்த்தகம், சராசரி R, சிறந்த மற்றும் மோசமான அமைப்பு மற்றும் விதி முறிவுகளை எண்ணுங்கள். அடுத்த வாரம் சரி செய்ய ஒரு கசிவைத் தேர்ந்தெடுக்கவும்."},{"h":"கசிவுகளைக் குறிக்கவும்","t":"பொதுவான குறிச்சொற்கள்: தாமதமான நுழைவு, SL இல்லை, பெரிதாக்கப்பட்டது, நகர்த்தப்பட்டது SL, பழிவாங்குதல், சலிப்பு. ஒரு டேக் மீண்டும் நிகழும்போது, ​​அதை கடினமான விதியாக மாற்றவும்."},{"h":"எதை பதிவு செய்யக்கூடாது","t":"வெற்றியாளர்களை மட்டும் பதிவு செய்யாதீர்கள். இழப்புகள் தரவு. வெற்றிகளை மட்டுமே கொண்ட ஒரு பத்திரிகை ஒரு சிற்றேடு, ஒரு பத்திரிகை அல்ல."},{"h":"டெமோ → லைவ் படியை திட்டமிடுங்கள்","t":"உண்மையான பணத்தை ஆபத்தில் வைப்பதற்கு முன் நேர்மறை சராசரி R உடன் வர்த்தகங்களின் தொகுப்பு எண்ணிக்கையை டெமோவில் நிரூபிக்கவும் - பின்னர் பாதி அளவில் தொடங்கவும்."},{"h":"பயிற்சி பட்டியல்","t":"① நுழைவதற்கு முன் எழுதப்பட்ட திட்டம் ② சரிபார்ப்பு பட்டியல் நிறைவேற்றப்பட்டது ③ ஜர்னல் நுழைவு + உணர்ச்சி ④ வாராந்திர மதிப்பாய்வு ⑤ ஒரு கசிவு சரி செய்யப்பட்டது."}]},{"id":"leverage","title":"12 · அந்நியச் செலாவணி, விளிம்பு & கலைத்தல்","summary":"அந்நியச் செலாவணி லாபத்தைப் போலவே இழப்பையும் வேகமாகப் பெருக்குகிறது. மார்ஜின், லிக்விடேஷன், தனிமைப்படுத்தப்பட்ட மற்றும் குறுக்கு விளிம்பு மற்றும் கணக்கைத் துடைப்பதைத் தடுக்கும் பாதுகாப்பு விதிகள் ஆகியவற்றைக் கற்றுக்கொள்ளுங்கள்.","lessons":[{"h":"அந்நியச் செலாவணி என்றால் என்ன","t":"அந்நியச் செலாவணியானது குறைந்த விளிம்புடன் பெரிய நிலையைக் கட்டுப்படுத்த உங்களை அனுமதிக்கிறது. இது லாபம் மற்றும் இழப்பு இரண்டையும் அதிகரிக்கிறது - அது உங்கள் விளிம்பை அதிகரிக்காது."},{"h":"விளிம்பு vs ஆபத்து","t":"விளிம்பு என்பது பரிமாற்ற பூட்டுகளின் வைப்பு ஆகும். ஆபத்து என்பது நுழைவு - நிறுத்தம் × அளவு. அந்நியச் செலாவணி மாறுபாடுகள், உங்கள் டாலர் ஆபத்து இல்லை."},{"h":"கலைத்தல்","t":"இழப்புகள் உங்கள் மார்ஜினைச் சாப்பிட்டால், பரிமாற்ற விசையானது, பெரும்பாலும் மோசமான நேரத்தில் நிலையை (கலைப்பு) மூடுகிறது. கலைப்பு விலையிலிருந்து உங்கள் நிறுத்தத்தை வெகு தொலைவில் வைத்திருங்கள்."},{"h":"தனிமைப்படுத்தப்பட்ட vs கிராஸ்","t":"தனிமைப்படுத்தப்பட்டால், அந்த ஒரு நிலையின் விளிம்பிற்கு ஏற்படும் இழப்பைக் கட்டுப்படுத்துகிறது. கிராஸ் முழு வாலட் இருப்பையும் பயன்படுத்துகிறது - ஆரம்பநிலைக்கு மிகவும் ஆபத்தானது. கற்கும் போது தனிமைப்படுத்தப்படுவதை விரும்புங்கள்."},{"h":"பாதுகாப்பான அந்நியச் செலாவணி","t":"குறைந்த லெவரேஜ் (2–5x) மற்றும் சரியான நிறுத்தம் நிறுத்தம் இல்லாமல் 50x விட பாதுகாப்பானது. நிறுத்தம், அந்நிய எண் அல்ல, உங்கள் பாதுகாப்பு."},{"h":"கலைப்பு-தூர விதி","t":"கலைப்பு விலையில் உங்கள் SL நன்றாக உள்ளதா எனச் சரிபார்க்கவும். அவர்கள் நெருக்கமாக இருந்தால், வசதியான இடம் இருக்கும் வரை அளவைக் குறைக்கவும்."},{"h":"அந்நியச் செலாவணி ஒரு மோசமான நுழைவை சரிசெய்யாது","t":"மோசமான நுழைவுக்கான உயர் லெவரேஜ் வேகமாக இழக்கிறது. முதலில் அமைப்பைச் சரிசெய்து, பின்னர் அதை அளவிடவும்."},{"h":"நிதி மற்றும் கட்டணங்கள்","t":"நிரந்தர எதிர்காலங்கள் காலப்போக்கில் நிதி வசூலிக்கின்றன. லெவரேஜ்டு பெர்ப்ஸ் ப்ளீட் ஃபண்டிங் மீது நீண்ட நேரம் வைத்திருப்பது - அளவு மற்றும் நேரத்தை கவனமாக இருப்பதற்கு மற்றொரு காரணம்."},{"h":"ஸ்பாட் vs எதிர்காலம்","t":"ஸ்பாட் கலைக்க முடியாது (நாணயம் உங்களிடம் உள்ளது). எதிர்காலங்கள் பூஜ்ஜியத்திற்கு செல்லலாம் மற்றும் செல்லலாம். எழுதப்பட்ட திட்டம் மற்றும் தனிமைப்படுத்தப்பட்ட விளிம்புடன் மட்டுமே எதிர்காலத்தைப் பயன்படுத்தவும்."},{"h":"அந்நியச் செலாவணியின் கீழ் அளவு","t":"நிறுத்த தூரத்திலிருந்து அளவைக் கணக்கிடுங்கள், அதன் விளைவாக வரும் விளிம்பு மலிவு என்பதைச் சரிபார்க்கவும். முதலில் அந்நியச் செலாவணியைத் தேர்ந்தெடுக்க வேண்டாம்."},{"h":"\"ஒரு வர்த்தகம்\" சோதனை","t":"நுழைவதற்கு முன் கேளுங்கள்: இது நிறுத்தத்தைத் தாக்கினால், அது தோள்பட்டை அல்லது பேரழிவா? அது ஒரு தோள் இல்லை என்றால், அளவு மிகவும் பெரியது."},{"h":"பயிற்சி பட்டியல்","t":"① தனிமைப்படுத்தப்பட்ட தொகுப்பு ② குறைந்த அந்நியச் செலாவணி ③ கலைப்பு விலையின் உள்ளே SL ④ நிறுத்தத்தில் இருந்து அளவு ⑤ நான் இங்கு முழு இழப்பைத் தாங்க முடியுமா? ஆம் → வர்த்தகம்."}]},{"id":"practice","title":"13 · வழக்கமான & பேக்டெஸ்டிங்கைப் பயிற்சி செய்யுங்கள்","summary":"நேரலைக்கு முன் டெமோவில் திறன் கட்டமைக்கப்படுகிறது. மீண்டும் மீண்டும் செய்யக்கூடிய பயிற்சி வளையம், விளக்கப்படங்களை ஸ்க்ரோலிங் செய்வதன் மூலம் \"பேக்டெஸ்ட்\" செய்வது மற்றும் உண்மையான பணத்தைப் பாதுகாப்பாகப் பெறுவது எப்படி என்பதை அறிக.","lessons":[{"h":"DEMO என்பது உடற்பயிற்சி கூடம்","t":"செயல்முறை மற்றும் உங்கள் உணர்ச்சிகளை பூஜ்ஜிய அபாயத்துடன் ஒத்திகை பார்க்க காகிதம் / டெமோ உள்ளது. டெமோவில் உள்ள விதிகளை உங்களால் பின்பற்ற முடியாவிட்டால், LIVE அதை மாயமாக சரிசெய்யாது."},{"h":"பயிற்சி வளையம்","t":"ஒரு அமைப்பைத் தேர்வு செய்யவும் (உதாரணமாக BB லோயர் + சுத்தி + RSI டர்ன்). விளக்கப்படத்தில் 20 வரலாற்று எடுத்துக்காட்டுகளைக் குறிக்கவும். நுழைவு / SL / TP ஐ வரையறுக்கவும். முடிவை பதிவு செய்யவும். மீண்டும் செய்யவும்."},{"h":"கைமுறை பின்பரிசோதனை","t":"விளக்கப்பட ஆய்வகத்தில் மீண்டும் உருட்டவும், எதிர்காலத்தை மறைத்து, ஒவ்வொரு சிக்னலையும் கையால் குறிக்கவும். இது வடிவ அங்கீகாரத்தைப் பயிற்றுவிக்கிறது மற்றும் உங்களை நீங்களே ஏமாற்றுவதை நிறுத்துகிறது."},{"h":"மாதிரி அளவு","t":"பத்து வர்த்தகங்கள் எதுவும் இல்லை. ஒரு அமைப்பைத் தீர்மானிக்கும் முன் அதன் 30-50 பதிவுசெய்யப்பட்ட வர்த்தகங்களைக் குறிக்கவும்."},{"h":"டெமோவில் முன்னோக்கி சோதனை","t":"கையால் குறிக்கப்பட்ட பிறகு, டெமோவில் அதே அமைப்பை இரண்டு முதல் நான்கு வாரங்களுக்கு மென்பொருளின் சிக்னல்களுடன் நேரடியாக இயக்கவும். உண்மையான நிரப்புதல்களையும் உணர்ச்சிகளையும் பின்னோட்டத்துடன் ஒப்பிடுக."},{"h":"ஒரு நேரத்தில் ஒரு அமைப்பு","t":"ஒரே நேரத்தில் ஐந்து அமைப்புகளை சோதிக்க வேண்டாம். ஒரு விளிம்பில் மாஸ்டர், பின்னர் இரண்டாவது சேர்க்கவும்."},{"h":"வழக்கத்தை சிறியதாக வைத்திருங்கள்","t":"20 நிமிட தினசரி வழக்கம் (ஸ்கேன், மார்க், ஜர்னல், ரிவியூ) ஆறு மணிநேரம் சீரற்ற சார்ட்-ஸ்டேரிங்கைத் தாக்கும்."},{"h":"LIVE இல் பட்டம் பெறுதல்","t":"அளவுகோல்: நேர்மறை சராசரி R 30+ டெமோ வர்த்தகங்கள், பின்பற்றப்படும் விதிகள், பழிவாங்கும் அத்தியாயங்கள் இல்லை. பின் பாதி அளவில் லைவ் தொடங்கி மெதுவாக அளவிடவும்."},{"h":"அளவுகோல் விதி","t":"ஒரு குறிப்பிட்ட எண்ணிக்கையிலான லாபகரமான, ஒழுக்கமான வாரங்களுக்குப் பிறகு மட்டுமே அளவை அதிகரிக்கவும் - ஒரு பெரிய வெற்றிக்குப் பிறகு."},{"h":"எப்போது பின்வாங்குவது","t":"தினசரி அல்லது வாராந்திர இழப்பு வரம்பை எட்டவும் அல்லது மீண்டும் மீண்டும் விதி முறிவுகளைக் கவனிக்கவும் → டெமோவுக்குத் திரும்பி, தொடர்வதற்கு முன் ஒழுக்கத்தை மீண்டும் உருவாக்கவும்."},{"h":"செயல்முறை அளவீடுகளைக் கண்காணிக்கவும்","t":"பதிவு சரிபார்ப்புப் பட்டியல் தேர்ச்சி விகிதம், ஒரு வாரத்திற்கான விதி முறிவுகள் மற்றும் சராசரி R. இவை ஒரு P/L எண்ணை விட வளர்ச்சியை சிறப்பாகக் கணிக்கின்றன."},{"h":"CPE பயிற்சி பாதை","t":"கற்றல் வகுப்பு → விளக்கப்பட ஆய்வகம் (குறியீடு அமைப்புகள்) → காகித வர்த்தகம் → இதழ் மதிப்பாய்வு → டெமோவில் சிக்னல் மேசைகள் → பொருந்தும் இயங்குதள விசையில் சிறிய லைவ்."},{"h":"பயிற்சி பட்டியல்","t":"① ஒரு அமைப்பு தேர்ந்தெடுக்கப்பட்டது ② 30 எடுத்துக்காட்டுகள் குறிக்கப்பட்டன ③ டெமோ முன்னோக்கி சோதனை ④ இதழ் + மதிப்பாய்வு ⑤ நேர்மறை R → அரை அளவு லைவ்."}]},{"id":"volatility","title":"14 · நிலையற்ற தன்மை & மார்டிங்கேல்","summary":"சந்தை ஏற்ற இறக்கத்தை எவ்வாறு படிப்பது (ஏன் விலை மாறுகிறது), ஒவ்வொரு சிக்னலிலும் அது ஒரு காரணக் கோட்டாக எவ்வாறு சேர்க்கப்படுகிறது மற்றும் விருப்பமான மார்டிங்கேல் ஏணி எவ்வாறு செயல்படுகிறது - மேலும் கவனக்குறைவாகப் பயன்படுத்தும்போது கணக்கை இழப்பதற்கான விரைவான வழி இதுவாகும்.","lessons":[{"h":"ஏற்ற இறக்கம் என்றால் என்ன","t":"ஏற்ற இறக்கம் என்பது விலை எவ்வளவு நகர்கிறது - எந்த வழியில் அல்ல. அதிக ஏற்ற இறக்கம் = பரந்த மெழுகுவர்த்திகள் மற்றும் வேகமான ஊசலாட்டங்கள். குறைந்த ஏற்ற இறக்கம் = ஒரு அமைதியான, குறுகிய வரம்பு. ஒரே அமைப்பு ஒவ்வொன்றிலும் மிகவும் வேறுபட்ட நம்பகத்தன்மை உள்ளது."},{"h":"CPE ஏற்ற இறக்க வாசிப்பு","t":"ஒவ்வொரு சிக்னலும் இப்போது சராசரி மெழுகுவர்த்தி வரம்பு மற்றும் பொலிங்கர் பேண்ட் அகலத்தை அளவிடுகிறது, பின்னர் அவற்றை அந்த ஜோடியின் சொந்த சமீபத்திய இயல்புடன் ஒப்பிடுகிறது. சிக்னலுடன் காட்டப்படும் சந்தை மாற்றத்திற்கான \"ஏன்\" - குறைந்த/இயல்பான/உயர்ந்த/அதிகமான மற்றும் ஒரு எளிய மொழி காரணக் கோடு கிடைக்கும்."},{"h":"EXTREME volatility = தரமிறக்கம்","t":"டேப் எக்ஸ்ட்ரீமாக இருக்கும்போது, ஒரு புதிய STRONG சமிக்ஞை எச்சரிக்கைக்கு தரமிறக்கப்படும் (காரணம் காட்டப்பட்டுள்ளது). ஒரு விப்சா சந்தையில் இதே முறை அடிக்கடி தோல்வியடைகிறது - போலி முறிவுகள் மற்றும் ஸ்டாப்-ஹண்ட் விக்ஸ் ஆகியவை வழக்கமாகும்."},{"h":"HIGH / EXTREME இல் என்ன செய்ய வேண்டும்","t":"சிறிய அளவு. பரந்த நிறுத்தம். குறைவான வர்த்தகம். மிட் மெழுகுவர்த்தி ஸ்பைக்கிற்கு பதிலாக நிறைவு செய்யப்பட்ட மெழுகுவர்த்திக்காக காத்திருங்கள். வாசிப்பு EXTREME எனக் கூறினால், அமைப்பை ஒரு ஆய்வு மண்டலமாகக் கருதுங்கள், ஒரு நுழைவு அல்ல."},{"h":"மார்டிங்கேல் என்றால் என்ன","t":"சராசரி உள்ளீட்டைக் குறைக்க மார்டிங்கேல் இழக்கும் நிலையைச் சேர்க்கிறது: ஒவ்வொரு பாதகமான நகர்வுக்குப் பிறகு நீங்கள் மற்றொரு ஆர்டரைச் சேர்க்கிறீர்கள், பொதுவாக பெரியது (1x, 2x, 4x ...). அது அடிக்கடி வெற்றி பெறுகிறது, பின்னர் ஒரு மோசமான ஓட்டத்தில் எல்லாவற்றையும் இழக்கிறது."},{"h":"CPE மார்டிங்கேல் விதி","t":"இரண்டும் உண்மையாக இருக்கும்போது மட்டுமே CPE கூடுதல் ஆர்டரைச் சேர்க்கிறது: (1) வர்த்தகத்திற்கு எதிராக குறைந்தபட்சம் படி × ரன் % ஆக விலை நகர்ந்துள்ளது, மேலும் (2) அதே பக்க சமிக்ஞை இன்னும் அந்த ஜோடிக்கு உள்ளது. விலை குறைந்ததால் அது ஒருபோதும் சேர்க்காது."},{"h":"நான்கு எண்கள்","t":"படி % = ஒவ்வொரு சேர்க்கும் முன் பாதகமான நகர்வு தேவை. பெருக்கி = ஒவ்வொரு சேர்க்கையின் அளவும் அடிப்படை (1 = பிளாட், 2 = இரட்டை). அதிகபட்சம் சேர்க்கிறது = கூடுதல் ஆர்டர்களில் கடினமான வரம்பு. ஏணி ரிஸ்க் கேப் % = முழு ஏணியின் ஆபத்து பங்குகளின் %. நான்கும் உங்களுடையது."},{"h":"கடினமான தொப்பி உங்களைப் பாதுகாக்கிறது","t":"ஒரு பெரிய பெருக்கி மற்றும் பல சேர்க்கைகள் இருந்தாலும் கூட, ஏணியின் மொத்த ஆபத்து உங்கள் பங்குத்தொகையின் % ஐ கடந்தால், CPE ஆர்டரை மறுக்கிறது. இது பரிமாற்ற குறைந்தபட்ச அளவு மற்றும் தினசரி −2% நிறுத்தத்தையும் மதிக்கிறது."},{"h":"எங்கே ஓடுகிறது","t":"அந்த ஒரு வர்த்தகத்தை நிர்வகிக்க கையேட்டில் அல்லது அதன் தானியங்கு வர்த்தகத்தை நிர்வகிக்க ஒரு ஆட்டோ அமர்வில் அதை டிக் செய்யவும். டெமோ மற்றும் லைவ் இரண்டும். கையேட்டில், ஜோடி ஸ்கேன் பட்டியலில் இருக்க வேண்டும், எனவே புதிய அதே பக்க சமிக்ஞையைப் படிக்க முடியும்."},{"h":"தொப்பி ஏன் முக்கியமானது (எடுத்துக்காட்டு)","t":"படி 1%, பெருக்கி 2, மூன்று 1%-ஆபத்து அடிப்படையில் சேர்க்கிறது: ஆபத்து 1% → 2% → 4% → 8%. கடைசி வரிசையில் ஒரு முழு நிறுத்தம் பல வெற்றியாளர்களை அழிக்கிறது. அதனால்தான் தொப்பி உள்ளது மற்றும் இயல்புநிலை எண்கள் ஏன் சிறியதாக உள்ளன."},{"h":"எதிர்ப்பு மார்டிங்கேல் மாற்று","t":"பல சாதகர்கள் இதற்கு நேர்மாறாக செய்கிறார்கள்: வெற்றியாளர்களை மட்டும் சேர்க்கவும் மற்றும் தோல்வியுற்றவர்களை வேகமாக குறைக்கவும். இது மோசமாக உணர்கிறது (அதிக சிறிய இழப்புகள்) ஆனால் அது உங்களுக்கு எதிரான ஒரே போக்கில் கணக்கை அழிக்க முடியாது."},{"h":"ஆபத்து அகற்றப்படவில்லை","t":"சராசரியைக் குறைப்பது ஆபத்தை அகற்றாது - இது \"பல சிறிய இழப்புகளில்\" இருந்து \"ஒரு பெரிய இழப்பு\" ஆபத்தை நகர்த்துகிறது. நீங்கள் இழக்க முடியாத பணத்துடன் ஒருபோதும் சேர்க்காதீர்கள், மற்றும் இழந்த வர்த்தகத்தை \"மீட்பதற்கு\" ஒருபோதும் தொப்பியை அணைக்காதீர்கள்."},{"h":"பயிற்சி பாதை","t":"முதலில் டெமோவில் ஏற்ற இறக்கத்தை படிக்கவும். 30+ வர்த்தகங்களுக்கு டெமோவில் அதிகபட்சம் 1-2 மற்றும் சிறிய பெருக்கியுடன் மார்டிங்கேலை முயற்சிக்கவும். ஒவ்வொரு ஏணியையும் பத்திரிக்கை செய்து, பின்னர் முடிவு செய்யுங்கள் - பெரும்பாலான வர்த்தகர்கள் பிளாட் / ஆண்டி மார்டிங்கேல் முறையை பாதுகாப்பானதாகக் கருதுகின்றனர்."},{"h":"நிலையற்ற தன்மை + மார்டிங்கேல் சரிபார்ப்பு பட்டியல்","t":"① ஏற்ற இறக்க நிலையை முதலில் படிக்கவும் ② EXTREME ③ மார்டிங்கேலில் தவிர்க்கவும் அல்லது சுருங்கவும் ஒரே பக்க சமிக்ஞையுடன் மட்டுமே ④ படி × ரேங்கை அடைந்தது ⑤ ஆபத்து தொப்பியின் கீழ் → சேர். எந்த \"இல்லை\" → சேர் இல்லை."}]},{"id":"lab_indicators","title":"15 · விளக்கப்பட ஆய்வக குறிகாட்டிகள் (ஸ்டோச் · ADX · இச்சிமோகு · VWAP)","summary":"விளக்கப்பட ஆய்வகத்தில் இப்போது முழு இண்டிகேட்டர் பட்டி உள்ளது - ஒவ்வொரு பொத்தானும் ஆன்/ஆஃப் டிக் ஆகும், இது விளக்கப்படத்தை உடனடியாக மீண்டும் வரையலாம். BB / RSI / MACD / EMA / SMA50 / வால்யூம் தவிர, நீங்கள் இப்போது ஸ்டோகாஸ்டிக், ADX/DMI, Ichimoku மற்றும் VWAP ஆகியவற்றைப் பெறுகிறீர்கள், மேலும் சிக்னல் எஞ்சின் அவற்றையும் படிக்கிறது - விளக்கப்படம் மட்டுமல்ல.","lessons":[{"h":"பார் எங்கே","t":"விளக்கப்பட ஆய்வகம் → விளக்கப்படத்தின் கீழ் உள்ள பொத்தான்களின் \"குறிகாட்டிகள்\" வரிசை. ஒரு கிளிக் ஒரு குறிகாட்டியை இயக்குகிறது, அடுத்த கிளிக் அதை அணைக்கிறது; விளக்கப்படம் உடனடியாக மீண்டும் வரையப்படும். உண்ணி காட்சியளிக்கிறது மற்றும் அவை சமிக்ஞை இயந்திரத்திற்கு உணவளிக்கின்றன."},{"h":"ஸ்டோகாஸ்டிக் (14,3,3)","t":"மெழுகுவர்த்திகளின் கீழ் வரையப்பட்ட %K / %D ஆஸிலேட்டர், அளவு 0–100. ~80க்கு மேல் = அதிகமாக வாங்கிய மண்டலம், ~20க்குக் கீழே = அதிகமாக விற்கப்பட்ட மண்டலம். அதிகமாக விற்கப்பட்ட மண்டலத்தில் %D வழியாக %K கடப்பது ஒரு நல்ல ஆய்வு; மேலே ஒரு குறுக்கு கீழே கரடி. ஒரு வலுவான போக்கில் அது நீண்ட நேரம் ஒரு முனையில் பொருத்தப்பட்டிருக்கும் - எப்போதும் BB மற்றும் மெழுகுவர்த்தியுடன் இணைக்கவும்."},{"h":"ADX / DMI (14)","t":"ADX ஆனது போக்கு வலிமையை அளவிடுகிறது, திசையை அல்ல. ~25க்கு மேல் = உண்மையான போக்கு இயங்குகிறது; கீழே ~20 = ஒரு தொய்வு வரம்பு. +DI மேலே −DI = பொறுப்பான வாங்குபவர்கள்; −DI +DIக்கு மேல் = விற்பனையாளர்கள் பொறுப்பு. டிரெண்ட்-டிரேட் செய்ய வேண்டுமா அல்லது சமமாக இருக்க வேண்டுமா என்பதை தீர்மானிக்க ADX ஐப் பயன்படுத்தவும்."},{"h":"இச்சிமோகு கிளவுட் (9,26,52)","t":"தென்கன் (வேகக் கோடு), கிஜுன் (மெதுவான கோடு) மற்றும் சென்கோ மேகம். உயரும் மேகத்திற்கு மேல் விலை = நேர்மறை பின்னணி; கீழே விழும் மேகம் = கரடி. மேகத்தின் உள்ளே ஒரு தென்கன்/கிஜுன் குறுக்கு பலவீனமாக உள்ளது; மேகத்தை விட்டு வெளியேறும் விலை கொண்ட குறுக்கு வலிமையானது. கிளவுட் எட்ஜ் பெரும்பாலும் ஆதரவு / எதிர்ப்பாக செயல்படுகிறது."},{"h":"VWAP","t":"வால்யூம் வெயிட்டட் ஆவரேஜ் விலை — வால்யூம் மூலம் கணக்கிடப்பட்ட சராசரி விலை, ஒவ்வொரு அமர்வையும் மீட்டமைக்கவும். பெரிய நிறுவனங்கள் அதன் நிரப்புதலை அளவுகோலாகக் குறிக்கின்றன. விலை உயரும் VWAP = கட்டுப்பாட்டில் வாங்குபவர்கள்; வீழ்ச்சியின் போது VWAP இல் ஒரு சுத்தமான நிராகரிப்பு ஒரு குறுகிய ஆய்வு. 24/7 கிரிப்டோவில் அது FX இல் இருந்து வித்தியாசமாக மீட்டமைக்கப்படுகிறது - அதை ஒரு வழிகாட்டி வரியாகக் கருதுங்கள், ஒரு சட்டம் அல்ல."},{"h":"இயந்திரம் அவற்றை எவ்வாறு பயன்படுத்துகிறது","t":"ஒவ்வொரு புதிய குறிகாட்டியும் அது சுட்டிக்காட்டும் அதே பக்கத்தில் மதிப்பெண்ணுக்கு ஒரு சிறிய உறுதிப்படுத்தலைச் சேர்க்கிறது (ஸ்டோகாஸ்டிக், இச்சிமோகு, VWAP, ADX அது திசையுடன் ஒத்துப்போகும் போது மற்றும் எலியட்). அவை உறுதிப்படுத்தல்கள், தூண்டுதல்கள் அல்ல - அவர்கள் BB / RSI / மெழுகுவர்த்தியுடன் உடன்படவில்லை என்றால், மதிப்பெண் மிகவும் கலவையாக வளரும், மேலும் நீங்கள் அதிகப் பிடித்தம் பெறுவீர்கள்."},{"h":"ஏன் CAUTION கடுமையாக்கப்பட்டது","t":"குளத்தில் இப்போது அதிகமான காசோலைகள் இருப்பதால், எச்சரிக்கைப் பட்டி இறுக்கப்பட்டது: இதற்கு மதிப்பெண் ≥ 4 மற்றும் குறைந்தது 3 சரிபார்ப்புகள் தேவை. அதிகமான கருவிகள் இயக்கப்பட்டிருப்பதால், செயலிழந்த சிக்னல்களை உங்களுக்கு வழங்குவதிலிருந்து இது தடுக்கிறது."},{"h":"வேலை செய்யும் ஒரு வாசிப்பு ஒழுங்கு","t":"① உயர்-TF திசை (இச்சிமோகு கிளவுட் + ADX). ② விலை எங்கே (BB / Fib / VWAP). ③ உந்தம் (RSI + ஸ்டோகாஸ்டிக்). ④ மெழுகுவர்த்தி உறுதிப்படுத்தல். ⑤ ஆபத்து% மற்றும் நிலைகள் எழுதப்பட்டது → முதலில் காகிதம்."},{"h":"தவிர்க்க வேண்டிய தவறுகள்","t":"ஒவ்வொரு இண்டிகேட்டரையும் ஆன் செய்து வானவில்லை வெறித்துப் பார்த்தல்; ADX ஐ ஒரு திசையாகப் பயன்படுத்துதல் (இது வலிமை மட்டுமே); ஒரு காளை ஓட்டத்திற்குள் ஸ்டோகாஸ்டிக்>80 ஆக இருப்பதால் மட்டுமே சுருக்கம்; VWAP என்பது கிரிப்டோ vs FX இல் வெவ்வேறு விஷயங்களைக் குறிக்கிறது என்பதை புறக்கணித்தல்."},{"h":"பயிற்சி பட்டியல்","t":"மேகக்கணியிலிருந்து ① சார்பு + ADX ② BB / Fib / VWAP இலிருந்து இருப்பிடம் ③ RSI + Stoch ③ மெழுகுவர்த்தி உறுதிப்படுத்தல் ⑤ SL / TP எழுதப்பட்ட ⑥ காகிதம், பின்னர் பத்திரிகை."}]},{"id":"elliott","title":"16 · எலியட் அலை (ஒளி எண்ணிக்கை)","summary":"CPE ஒரு இலகுரக எலியட் வேவ் கவுண்டரை உள்ளடக்கியது. விளக்கப்பட ஆய்வகக் காட்டிப் பட்டியில் \"எலியட்\" என்பதைத் தேர்வுசெய்து, அது மெழுகுவர்த்திகளில் கடைசி 0-1-2-3-4-5 உந்துவிசையை லேபிள் செய்து, அலை-5 ஃபைபோனச்சி இலக்கை முன்னிறுத்துகிறது. இது ஒரு ஆய்வுக் கருவி - ஒரு படிக பந்து அல்ல.","lessons":[{"h":"ஒரே வரியில் யோசனை","t":"சந்தைகள் அலைகளில் நகர்கின்றன: தூண்டுதல்கள் (போக்கு திசையில் 5 கால்கள்) மற்றும் திருத்தங்கள் (அதற்கு எதிராக 3 கால்கள்). CPE உந்துவிசையை மட்டுமே கணக்கிடுகிறது, இது போக்கைக் கொண்டு செல்லும் பகுதியாகும்."},{"h":"CPE அதை எவ்வாறு கணக்கிடுகிறது","t":"இது கடைசி ஸ்விங் பிவோட்களை (3-பார் ஃப்ராக்டல்கள்) கண்டறிந்து, உயர்/குறைவாக மாறி மாறி, எலியட் விதிகளுக்கு எதிராக கடைசி 5-6 ஸ்விங்குகளை சோதிக்கிறது. வடிவம் பொருந்தினால், அது 0→5 லேபிள்களையும் (மஞ்சள் நிறத்தில் இன்னும் இயங்கும் அலை) மற்றும் அலை 4-ல் இருந்து அளவிடப்பட்ட அலை-1 நீளம் × 1.618 இலிருந்து கட்டப்பட்ட W5 இலக்குக் கோட்டையும் வரைகிறது."},{"h":"அது சரிபார்க்கும் விதிகள்","t":"அலை 2 அலை 1 இன் தொடக்கத்தை கடக்காது; அலை 4 அலை 1 இன் பிரதேசத்தை ஒன்றுடன் ஒன்று சேர்க்காது; அலை 3 1 / 3 / 5 இல் மிகக் குறுகியது அல்ல. ஒரு விதி தோல்வியுற்றால் அது எதையும் காட்டாது - கட்டாய எண்ணிக்கை இல்லை."},{"h":"புல்லிஷ் vs பேரிஷ்","t":"ஒரு எழுச்சி 0-1-2-3-4-5 ஒரு நேர்மறை தூண்டுதலாகும்; கீழே செல்லும் வழியில் கண்ணாடி படம் கரடியாக உள்ளது. இயந்திரம் அலையின் பக்கத்தில் மதிப்பெண்ணுக்கு ஒரு சிறிய உறுதிப்படுத்தலைச் சேர்க்கிறது."},{"h":"நேரடி vs முழுமையானது","t":"ஒரு லைவ் அலை 5 (இன்னும் இயங்குகிறது) போக்கின் தொடர்ச்சியாகப் படிக்கிறது. ஒரு முழுமையான தூண்டுதல் (0-5 முடிந்தது) போக்கு சோர்வாக இருக்கலாம் என்று எச்சரிக்கிறது - ஒரு திருத்தம் அடிக்கடி பின்பற்றப்படுகிறது."},{"h":"W5 இலக்கு கோடு","t":"அலை-4 குறைந்த / உயர்விலிருந்து அலை 1 இன் ஃபைபோனச்சி நீட்டிப்பு. இது ஒரு இலக்கு யோசனை, ஒரு காந்தம் அல்ல - விலை அதை நிறுத்தலாம் அல்லது அதை மிகைப்படுத்தலாம்."},{"h":"அதை எப்படி பயன்படுத்துவது","t":"எண்ணிக்கையை சங்கமமாகக் கருதுங்கள்: ஒரு மெழுகுவர்த்தி மற்றும் RSI கொண்ட தெளிவான BB / Fib மண்டலத்தில், ஒரு மனக்கிளர்ச்சி எண்ணிக்கை நம்பிக்கையை சேர்க்கிறது. சொந்தமாக அது ஒரு ஓவியம் மட்டுமே."},{"h":"தவிர்க்க வேண்டிய தவறுகள்","t":"அலைகள் உங்கள் நிலைக்கு பொருந்தும் வரை மீண்டும் எண்ணுதல் (கிளாசிக் எலியட் பாவம்); சிறிய அசைவுகளை எண்ணுதல்; அதிக காலக்கெடு எண்ணிக்கையை புறக்கணித்தல்; ஒவ்வொரு முறையும் புதிய பட்டை அச்சிடும்போது எண்ணிக்கை மாறுவதை மறந்துவிடுகிறது."},{"h":"பயிற்சி பட்டியல்","t":"① தெளிவான ஊசலாட்டம் தேர்ந்தெடுக்கப்பட்டது ② விதிகள் பாஸ் ③ ஜிக்-ஜாக் BB / Fib உடன் உடன்படுகிறது ④ மெழுகுவர்த்தி உறுதிப்படுத்துகிறது ⑤ SL அலை-4 செல்லாததாக்கும் புள்ளிக்கு அப்பால்."}]},{"id":"forecast","title":"17 · 3-மாத முன்னறிவிப்பு (முன்கணிப்பு 3M டிக்)","summary":"நீண்ட அடிவான ப்ரொஜெக்டர்: சிக்னலின் சொந்த போக்கு, இலக்குகள் மற்றும் நிலையற்ற தன்மை ஆகியவற்றிலிருந்து கட்டமைக்கப்பட்ட இந்த விளக்கப்படம் அடுத்த ~3 மாதங்களில் எவ்வாறு உருவாகலாம். விளக்கப்பட ஆய்வகத்தில் \"முன்கணிப்பு 3M\" டிக் மூலம் அதை ஆன் அல்லது ஆஃப் செய்யவும்.","lessons":[{"h":"அது என்ன வரைகிறது","t":"பகுப்பாய்வு செய்யப்பட்ட நுழைவிலிருந்து இயந்திரம் ஏற்கனவே அறிந்த சிறந்த இலக்கை நோக்கிச் செல்லும் ஒரு கோடு மையப் பாதை (எலியட் இலக்கு → tp2 → tp1), நம்பத்தகுந்த விலைகளின் பரவலைக் காட்டும் விரிவடையும் \"கூம்பு\" மூலம் மூடப்பட்டிருக்கும். மாத குறிப்பான்கள் M+1 / M+2 / M+3 அடிவானத்தை பிரிக்கிறது."},{"h":"ஏன் ஒரு கூம்பு மற்றும் ஒரு கோடு இல்லை","t":"ஒரு சரியான எதிர்கால விலையை யாரும் அறிய முடியாது. காலத்தின் வர்க்கமூலம் மற்றும் ஜோடியின் சொந்த ஏற்ற இறக்கத்துடன் கூம்பு விரிவடைகிறது, எனவே ஒரு அமைதியான எஃப்எக்ஸ் ஜோடி ஒரு குறுகிய கூம்பு மற்றும் ஒரு காட்டு ஆல்ட்காயின் மிகவும் பரந்த ஒன்றைப் பெறுகிறது. அந்த அகலம் செய்தி: நீங்கள் மேலும் பார்க்க, விலை குறைவாக இருக்கும்."},{"h":"எண்கள் எங்கிருந்து வருகின்றன","t":"சறுக்கல் தற்போதைய சமிக்ஞை இலக்கிலிருந்து வருகிறது; தினசரி ஏற்ற இறக்கம் ஒரு நாளுக்கு அளவிடப்பட்ட சிக்னலின் ATR% இலிருந்து வருகிறது, எனவே கூம்பு என்பது 5m அல்லது 1d விளக்கப்படத்தில் ஒரே மாதிரியாக இருக்கும்; எக்ஸ்ட்ரீம் / உயர் ஏற்ற இறக்கம் அதை மேலும் விரிவுபடுத்துகிறது."},{"h":"அதை எப்படி படிப்பது","t":"SLOPE (பாதை எந்த வழியில் சாய்கிறது) மற்றும் அகலம் (எவ்வளவு சந்தேகம்) ஆகியவற்றைப் பாருங்கள். ஒரு குறுகிய கூம்பு கொண்ட உயரும் பாதை = ஒரு நிலையான போக்கு யோசனை; ஒரு பெரிய கூம்பு கொண்ட ஒரு தட்டையான பாதை = \"இங்கே விளிம்பு இல்லை, சத்தத்தை எதிர்பார்க்கலாம்\"."},{"h":"அதை ஆன் மற்றும் ஆஃப் செய்தல்","t":"\"முன்கணிப்பு 3M\" பொத்தான் \"எதிர்கால விண்வெளி\" க்கு அடுத்ததாக உள்ளது. இதற்கு ஃபியூச்சர் ஸ்பேஸ் ஆன் (வலதுபுறத்தில் உள்ள வெற்றுப் பகுதி) தேவை. சிக்னல் HOLD ஆக இருந்தால் எந்த திசையும் இல்லை, அதனால் எதுவும் வரையப்படவில்லை."},{"h":"இது போக்கு, வர்த்தகம் அல்ல","t":"முன்னறிவிப்பு ஒரு பெரிய பட வரைபடம். உண்மையான வர்த்தக நிலைகள் - நுழைவு, TP1 / TP2, SL மற்றும் குறுகிய கால ப்ராஜெக்ஷன் - இன்னும் நீங்கள் வர்த்தகம் செய்வதுதான்."},{"h":"நேர்மையான வரம்புகள்","t":"செய்திகள், பட்டியல்கள், நீக்குதல்கள் மற்றும் மேக்ரோ மாற்றங்கள் மாதிரியில் இல்லை; பாதை ஒரு மென்மையான சறுக்கல், எனவே உண்மையான விலைகள் இன்னும் அதிகமாக அசையும்; 3-மாத கூம்பு என்பது ஒரு ஆய்வு உதவி, ஒருபோதும் வாக்குறுதி அல்ல."},{"h":"அடிக்கடி மீண்டும் பகுப்பாய்வு செய்யுங்கள்","t":"புதிய மெழுகுவர்த்திகள் அச்சிடும்போது, ​​இலக்கு, ஏற்ற இறக்கம் மற்றும் முழு கூம்பு புதுப்பிப்பு. முன்னறிவிப்பு என்பது ஒரு ஸ்னாப்ஷாட், ஒரு ஒப்பந்தம் அல்ல."},{"h":"பயிற்சி பட்டியல்","t":"① பாதையின் திசையைப் படிக்கவும் ② கூம்பு அகலத்தைச் சரிபார்க்கவும் ③ உயர்-TF அமைப்புடன் ஒப்பிடவும் ④ உண்மையான SL இலிருந்து அளவை அளவிடவும், கூம்பிலிருந்து இல்லை."}]}],"platforms":{"BINANCE":{"title":"பைனான்ஸ் வர்த்தகம் A → Z","steps":["கணக்கை உருவாக்கவும் → 2FA ஐ இயக்கவும்.","API மேலாண்மை → விசையை உருவாக்கு → ஸ்பாட் &/அல்லது எதிர்கால வர்த்தகம் ஆன், திரும்பப் பெறுதல்கள் ஆஃப்.","CPE → API விசைகள் → Binance → Save → Test Account இல் விசை + ரகசியத்தை ஒட்டவும்.","ஸ்பாட் டெஸ்க் / ஃபியூச்சர்ஸ் டெஸ்க் ஸ்கேன் பயன்படுத்தவும் (பொது விளக்கப்படங்கள் விசைகளுக்கு முன்பே வேலை செய்யும்).","பயிற்சி: கைமுறை வர்த்தகம் → காகித வர்த்தகத்தைத் தொடங்கவும் (நேரடி பணம் இல்லை).","நேரலை: TP1/TP2/SL + ட்ரெய்லிங் → நேரடி வர்த்தகத்தைத் தொடங்கவும் (API தேவை).","நிலைகளில் நிர்வகிக்கவும்: நிலைகளைத் திருத்தவும், பகுதி மூடவும், தானாக ரத்து செய்யவும்.","உரிமம்: சோதனை 7d → 3-மாதம் அல்லது வாழ்நாள் (பயன்பாட்டில் உரிமையாளர் விலைகள்)."]},"BYBIT":{"title":"பைபிட் டிரேடிங் A → Z","steps":["கணக்கு + 2FA.","API மேலாண்மை → வர்த்தகம் மட்டும், திரும்பப் பெறுதல் முடக்கம்.","CPE → API விசைகள் → பைபிட் → சேமி.","பெர்ப்ஸ் மனநிலைக்கான ஃபியூச்சர்ஸ் டெஸ்க்; மெழுகுவர்த்திகளைப் படிக்க விளக்கப்பட ஆய்வகம்.","முதலில் காகித வர்த்தகம்; விசைகள் வேலை செய்த பிறகு வாழ்க.","டிரெயில் TP+SL: வாங்கு↑ / விற்க↓."]},"OKX":{"title":"OKX வர்த்தகம் A → Z","steps":["API விசை + ரகசியம் + கடவுச்சொற்றொடர் தேவை.","திரும்பப் பெறுதல் எப்போதும் முடக்கப்படும்.","மூன்று புலங்களையும் CPE விசைகளில் சேமிக்கவும்.","காகித பயிற்சி → சிறிய நேரடி அளவு.","கடவுச்சொற்றொடர் எழுத்துப் பிழைகள் #1 தோல்வி - கவனமாக நகலெடுக்கவும்."]},"KUCOIN":{"title":"குகோயின் வர்த்தகம் A → Z","steps":["விசை + ரகசியம் + கடவுச்சொற்றொடர்.","வர்த்தக அனுமதி மட்டுமே.","CPE இல் காகிதம் → பின்னர் சிறியதாக வாழ.","சிக்னல்களுக்கு ஸ்பாட்/ஃப்யூச்சர்ஸ் மேசைகளைப் பயன்படுத்தவும்."]},"BITGET":{"title":"பிட்ஜெட் வர்த்தகம் A → Z","steps":["வர்த்தகத்துடன் மட்டுமே API.","காகிதம் பின்னர் வாழ.","எதிர்காலம்: கையேடு வர்த்தகத்தில் குறுக்கு அல்லது தனிமைப்படுத்தப்பட்டதைத் தேர்ந்தெடுக்கவும்.","லாபத்தைப் பெற TP+SLஐப் பின்தொடரவும்."]},"GATE":{"title":"Gate.io வர்த்தகம் A → Z","steps":["API v4 விசைகளை உருவாக்கவும் (வர்த்தகம்).","திரும்பப் பெறுதல் முடக்கப்பட்டுள்ளது.","CPE → பயிற்சி தாளில் சேமிக்கவும்.","நேரலைக்கு முன் உள்ளீடுகளுக்கு ஸ்கேன் + சார்ட் லேப்."]},"MEXC":{"title":"MEXC வர்த்தகம் A → Z","steps":["ஸ்டார்ட் ஸ்பாட் மனநிலை.","CPE API விசைகளில் உள்ள விசைகள்.","தாள் → நேரலை.","திறந்த லாபத்தைப் பூட்ட, பாதையைப் பயன்படுத்தவும்."]},"KRAKEN":{"title":"கிராகன் வர்த்தகம் A → Z","steps":["வர்த்தக அனுமதியுடன் மட்டுமே விசையை உருவாக்கவும்.","திரும்பப் பெறுதல்/நிதி உரிமைகள் இல்லை.","CPE இல் காகித பயிற்சி.","கிராக்கனில் உள்ள ஒவ்வொரு லைவ் ஆர்டரையும் சரிபார்க்கவும்."]},"COINBASE":{"title":"Coinbase மேம்பட்ட A → Z","steps":["மேம்பட்ட வர்த்தக API விசைகள்.","CPE இல் ஸ்பாட்-ஃபோகஸ்டு டெஸ்க்.","காகிதம் பின்னர் வாழ.","திரும்பப் பெறுதல்களை முடக்கி வைக்கவும்."]},"FOREX_OANDA":{"title":"அந்நிய செலாவணி (OANDA) A → Z","steps":["OANDA டெமோவைத் திறக்கவும் → ஆபத்து ~1%.","CPE விசைகளில் தனிப்பட்ட அணுகல் டோக்கன் + கணக்கு ஐடி.","Forex Desk scan + Chart Lab (EURUSD...).","கையேடு வர்த்தகம் → அந்நிய செலாவணி தளத்துடன் காகிதம்.","டெமோ நம்பிக்கைக்குப் பிறகுதான் வாழ்க."]},"FOREX_FXCM":{"title":"FXCM Forex A → Z","steps":["தரகர் API நற்சான்றிதழ்கள்.","முதலில் CPE இல் காகிதம்.","லண்டன்/NY அமர்வுகள் & செய்திகளின் கூர்மைகளைப் பாருங்கள்.","பயிற்சிக்குப் பிறகு நேரலை இதழ் சுத்தமாகத் தெரிகிறது."]},"FOREX_MT5":{"title":"MetaTrader 5 A → Z","steps":["CPE விசைகளில் உள்நுழைவு + சர்வர் + கடவுச்சொல்.","முடிந்தவரை முதலீட்டாளர் (படிக்க) கடவுச்சொல்லை விரும்பவும்.","பயிற்சி நிறைய 0.01.","CPE இல் காகிதம்; தயாராக இருக்கும் போது தரகர் மூலம் நேரலை."]},"FOREX_DEMO":{"title":"அந்நிய செலாவணி டெமோ விகிதங்கள் A → Z","steps":["API விசை தேவையில்லை.","Forex Desk + Chart Lab for free charts.","காகித வர்த்தகம் மட்டுமே (நடைமுறை).","உண்மையான தரகருக்குத் தயாராக இருக்கும்போது, ​​நேரலைக்கு OANDA / FXCM / MT5 விசைகளைச் சேர்க்கவும்."]}},"forexAz":{"title":"அந்நிய செலாவணி வர்த்தகம் A → Z (முழு வகுப்பு)","lessons":[{"h":"A — கணக்கு & ஆபத்து","t":"முதலில் டெமோ. ஒரு யோசனைக்கு ஆபத்து ~0.5–1%. எப்போதும் பழிவாங்கும் வர்த்தகம்."},{"h":"பி - ஜோடிகள்","t":"exoticsக்கு முன் மேஜர்கள் (EURUSD, GBPUSD, USDJPY)."},{"h":"சி - மெழுகுவர்த்திகள்","t":"Chart Lab Forex இல் Doji, Hammer, Engulfing ஆகியவற்றைக் கற்றுக்கொள்ளுங்கள்."},{"h":"டி - தினசரி சார்பு","t":"15m/30m உள்ளீடுகளுக்கு முன் அதிக கால அளவை சரிபார்க்கவும்."},{"h":"இ - உள்ளீடுகள்","t":"BB லோயர் பவுன்ஸ் + மெழுகுவர்த்தி உறுதிப்படுத்தல் என்பது ஒரு பொதுவான நடைமுறை அமைப்பாகும்."},{"h":"எஃப் - ஃபைப்","t":"50% / 61.8% புல்பேக்குகள் பெரும்பாலும் பயிற்சி மண்டலங்களாகப் பயன்படுத்தப்படுகின்றன."},{"h":"ஜி - இலக்குகள் (TP)","t":"TP1 ஸ்கேல் அவுட், TP2 ரன்னர், டிரெயில் SL."},{"h":"எச் - மணிநேரம்","t":"லண்டன்-NY ஒன்றுடன் ஒன்று = அதிக இயக்கம்."},{"h":"நான் - குறிகாட்டிகள்","t":"RSI + MACD + BB ஒன்றாக; காட்டி அதிக சுமைகளைத் தவிர்க்கவும்."},{"h":"ஜே - ஜர்னல்","t":"CPE ஜர்னலில் ஒவ்வொரு காகிதம்/நேரடி வர்த்தகத்தையும் பதிவு செய்யவும்."},{"h":"கே - விசைகள்","t":"நேரடி அந்நிய செலாவணி தரகர் API / டோக்கன் தேவை; டெமோ கட்டணங்கள் எதுவும் தேவையில்லை."},{"h":"எல் - நிறைய","t":"நடைமுறை மனநிலையில் 0.01 நிறைய தொடங்கவும்."},{"h":"எம் - மனநிலை","t":"கணிப்புக்கு மேல் செயல்முறை. மோசமான நாட்களைத் தவிர்க்கவும்."},{"h":"N - செய்தி","t":"பெரிய நிகழ்வுகளுக்கு முன் செய்திகள் & தந்திரங்களைச் சரிபார்க்கவும்."},{"h":"ஓ - ஆர்டர்கள்","t":"எப்போதும் SL ஐ அமைக்கவும். டிரேலிங் திறந்த லாபத்தைப் பாதுகாக்கிறது."},{"h":"பி - பயிற்சி","t":"காகித வர்த்தக பொத்தான் = நேரடி API இல்லாமல் பயிற்சி."},{"h":"கே - தரம்","t":"குறைவான உயர்தர அமைப்புகள் அதிக வர்த்தகத்தை முறியடிக்கும்."},{"h":"ஆர் - ஆபத்து: வெகுமதி","t":"முடிந்தவரை வெகுமதி ≥ ஆபத்து உள்ள அமைப்புகளை நோக்குங்கள்."},{"h":"எஸ் - அமர்வுகள்","t":"ஆசியா அமைதியானது; லண்டன்/NY மேலும் செயலில் உள்ளது."},{"h":"டி - போக்குகள்","t":"கற்கும் போது உயர்-TF போக்குடன் வர்த்தகம் செய்யுங்கள்."},{"h":"U - புதுப்பிப்புகள்","t":"CPE புதுப்பிப்பு பேனர் + நேரடி உதவியைப் பார்க்கவும்."},{"h":"வி - நிலையற்ற தன்மை","t":"ஏடிஆர் அதிகரிக்கும் போது பொறுமையை விரிவுபடுத்துங்கள்."},{"h":"W — வித்ட்ரா ஏபிஐ","t":"எந்த API விசையிலும் திரும்பப் பெறுவதை ஒருபோதும் இயக்க வேண்டாம்."},{"h":"X - வெளியேறுகிறது","t":"பகுதி TP + டிரெயில் பீட்ஸ் நம்பிக்கை."},{"h":"ஒய் - உங்கள் திட்டம்","t":"விதிகளை எழுதுங்கள்; கையேடு/ஆட்டோவில் அவற்றைப் பின்தொடரவும்."},{"h":"Z - ஜீரோ ரஷ்","t":"FOMO இல்லை. பயிற்சி → பின்னர் நேரடி API."}]}};

window.CPE_LEARN.hi = {"intro":"पहले पेपर/डेमो के साथ अभ्यास करें। मोमबत्तियाँ, चार्ट, बीबी/आरएसआई/फाइब, पैसा, मनोविज्ञान का अध्ययन करें - फिर सिग्नल (खरीदें/बेचें/होल्ड करने का क्या मतलब है + क्या करें) और विदेशी मुद्रा सिग्नल। लाइव को सही प्लेटफ़ॉर्म एपीआई कुंजी (निकासी बंद) की आवश्यकता है।","candles":[{"shape":"doji","name":"दोजी","color":"#94a3b8","bias":"तटस्थ / प्रतीक्षा करें","tip":"खुला ≈ बंद - क्रॉस या पतला शरीर। एक कदम के बाद बाजार अनिर्णय.","also":"यह भी सिखाता है: FOMO मत करो। अगली मोमबत्ती की प्रतीक्षा करें. बीबी चरम के पास + दोजी = विचारों का निचोड़; दिशा का अनुमान लगाने से पहले आरएसआई ढलान की जांच करें।"},{"shape":"hammer","name":"हथौड़ा","color":"#22c55e","bias":"पूर्वाग्रह खरीदें","tip":"शीर्ष पर छोटी बॉडी, गिरावट के बाद लंबी निचली बाती (≈2× बॉडी) - खरीदारों ने कम कीमतों को अस्वीकार कर दिया।","also":"इसके अलावा: प्रैक्टिस एसएल को बाती के नीचे रखें। ओवरसोल्ड से कम बीबी + आरएसआई बढ़ने के साथ सर्वश्रेष्ठ। मनोविज्ञान: बाती ख़त्म होने तक धैर्य रखें - बीच वाली बाती न खरीदें।"},{"shape":"invhammer","name":"उलटा हथौड़ा","color":"#22c55e","bias":"खरीदें (कमजोर)","tip":"नीचे की ओर लंबी ऊपरी बाती। खरीदारों ने बहुत अधिक जांच की लेकिन खुले के करीब बंद हुआ - अगली हरी पुष्टि की आवश्यकता है।","also":"इसके अलावा: अकेले हैमर से भी कमज़ोर। चेतावनी के रूप में उपयोग करें, प्रवेश के रूप में नहीं। फाइब 61.8 उछाल + उलटा हथौड़ा = अध्ययन क्षेत्र केवल मोमबत्ती की पुष्टि तक।"},{"shape":"shooting","name":"शूटिंग स्टार","color":"#ef4444","bias":"पूर्वाग्रह बेचें","tip":"छोटी बॉडी बॉटम, वृद्धि के बाद लंबी ऊपरी बाती - विक्रेताओं ने ऊंचे को अस्वीकार कर दिया।","also":"इसके अलावा: बाती के ऊपर एसएल उच्च। ऊपरी बीबी / फाइब एक्सटेंशन / आरएसआई के पास अधिक मजबूत। सिखाता है: चंद्रमा की मोमबत्तियाँ विफल हो सकती हैं - अंतिम हरे रंग का पीछा न करें।"},{"shape":"hanging","name":"लटकता हुआ आदमी","color":"#f59e0b","bias":"सावधानी से बेचें","tip":"हैमर जैसा दिखता है लेकिन ऊपर उठने के बाद दिखाई देता है - संभव शीर्ष थकावट।","also":"इसके अलावा: संदर्भ ही सब कुछ है (समान आकार ≠ समान व्यापार)। जर्नल स्थान: ऊपर बनाम नीचे। मनोविज्ञान: सिर्फ इसलिए कि आकार मेल खाता है, इसे उल्टा न करें - अगली मोमबत्ती + आरएसआई से पुष्टि करें।"},{"shape":"engulf_bull","name":"बुलिश एनगल्फिंग","color":"#22c55e","bias":"खरीदें","tip":"ग्रीन बॉडी पूरी तरह से पूर्व लाल बॉडी को कवर करती है - खरीदारों ने एक बार में नियंत्रण ले लिया।","also":"इसके अलावा: समर्थन पर मजबूत/कम बीबी/फाइब 50-61.8। निगलने से आकार एसएल जितना कम। मनी टिप: चौड़ा घेरने वाला शरीर → चौड़ा SL → छोटा आकार।"},{"shape":"engulf_bear","name":"मंदी का दौर","color":"#ef4444","bias":"बेचो","tip":"लाल बॉडी पूरी तरह से पहले वाले हरे रंग को कवर करती है - विक्रेताओं का बोलबाला है।","also":"इसके अलावा: खुले लांगों पर सावधानी। ऊपरी बीबी के पास + आरएसआई>70 = उच्च अध्ययन गुणवत्ता। जोखिम सिखाता है: यदि पहले से ही लंबा है, तो आशा के बजाय आंशिक टीपी/ट्रेल।"},{"shape":"morning","name":"सुबह का तारा","color":"#22c55e","bias":"खरीदें","tip":"3 मोमबत्तियाँ: बड़ी लाल → छोटा सितारा → बड़ी हरी। निचली उलट कहानी.","also":"इसके अलावा: बहु-मोमबत्ती धैर्य. तीसरा बंद होने के बाद प्रवेश करें; एसएल अंडर स्टार लो। बीबी लोअर + बुलिश आरएसआई डाइवर्जेंस के साथ अच्छी तरह से मेल खाता है।"},{"shape":"evening","name":"शाम का सितारा","color":"#ef4444","bias":"बेचो","tip":"3 मोमबत्तियाँ: बड़ी हरी → छोटा सितारा → बड़ी लाल। शीर्ष उलट कहानी.","also":"इसके अलावा: अकेले मध्य तारे को छोटा न करें। तीसरी समाप्ति तक प्रतीक्षा करें। अपर बीबी/फाइब विस्तार संगम। मनोविज्ञान: पहले ग्रीन रन के FOMO को अनदेखा करें।"},{"shape":"maru_bull","name":"बुल मारुबोज़ू","color":"#22c55e","bias":"खरीदारी का मजबूत दबाव","tip":"लंबा हरा शरीर, लगभग कोई बाती नहीं - खरीदारों ने खुले → बंद को नियंत्रित किया।","also":"इसके अलावा: प्रवृत्ति निरंतरता सुराग, हमेशा निचले स्तर पर खरीदारी नहीं। वॉक-द-बैंड संभव। जोखिम: बी.बी. मध्य/फाइब पर पुलबैक के बिना देर से मारुबोज़ू का पीछा करना।"},{"shape":"maru_bear","name":"भालू मारुबोज़ू","color":"#ef4444","bias":"बेचने का मजबूत दबाव","tip":"लंबा लाल शरीर, लगभग कोई बाती नहीं - विक्रेता नियंत्रण में।","also":"इसके अलावा: गिरते चाकूओं को न पकड़ें। प्रतीक्षा करें बीबी/फाइब बाउंस + हैमर बाद में। सिखाता है: मजबूत दबाव = छोटा आकार या एक तरफ खड़ा होना।"},{"shape":"spin","name":"घूमता हुआ शीर्ष","color":"#94a3b8","bias":"अनिर्णय","tip":"छोटा शरीर, ऊपरी + निचली बत्ती - दोनों पक्ष लड़े, कोई भी स्पष्ट रूप से नहीं जीता।","also":"इसके अलावा: बीबी के अंदर अक्सर निचोड़ होता है। व्यापार रोकें; प्रतीक्षा विराम + दिशा मोमबत्ती। मनोविज्ञान पाठ: बाज़ार \"कुछ नहीं कर सकता\" - फ्लैट एक वैध विकल्प है।"},{"shape":"pierce","name":"छेदने वाली रेखा","color":"#22c55e","bias":"खरीदें","tip":"लाल फिर हरा जो नीचे खुलता है लेकिन पूर्व लाल के मध्यबिंदु के ऊपर बंद होता है।","also":"इसके अलावा: एनगल्फिंग से नरम। आरएसआई टर्न से पुष्टि करें। आंशिक ताकत पढ़ने के लिए अच्छा पेपर ड्रिल - सभी हरे रंग समान नहीं हैं।"},{"shape":"darkcloud","name":"काले बादलों का आवरण","color":"#ef4444","bias":"बेचो","tip":"हरा फिर लाल जो ऊपर खुलता है लेकिन पहले हरे रंग के मध्य बिंदु से नीचे बंद होता है।","also":"इसके अलावा: भालू के पूरी तरह से घिर जाने से पहले प्रारंभिक चेतावनी। पगडंडी लंबी है / टीपी1 लें। पूर्ण उलट प्रिंट से पहले स्केलिंग करना सिखाता है।"},{"shape":"soldiers","name":"तीन श्वेत सैनिक","color":"#22c55e","bias":"खरीदने का चलन","tip":"ऊंचे समापन के साथ तीन उभरते हुए हरे रंग - स्थिर खरीदारी।","also":"इसके अलावा: मजबूत अपट्रेंड संकेत; फाइब 38-50 या बीबी मध्य में पुलबैक अभ्यास जोड़ हैं। 3 ग्रीन्स के बाद अति आत्मविश्वास का जोखिम - जोखिम % निश्चित रखें।"},{"shape":"crows","name":"तीन काले कौवे","color":"#ef4444","bias":"बेचने की प्रवृत्ति","tip":"निचले समापन के साथ तीन गिरते लाल - स्थिर बिक्री।","also":"इसके अलावा: औसत कम न करें। प्रतीक्षा संरचना. आरएसआई ओवरसोल्ड ओवरसोल्ड रह सकता है - धन नियम: हानि सीमा > आशा।"},{"shape":"harami_bull","name":"बुलिश हरामी","color":"#22c55e","bias":"खरीदें (मुलायम)","tip":"बड़ा लाल, फिर पूर्व शरीर के अंदर छोटा हरा - बिकवाली का दबाव सिकुड़ रहा है।","also":"इसके अलावा: शीघ्र विराम संकेत. पुष्टि की आवश्यकता है. आरएसआई बुलिश डाइवर्जेंस अध्ययन के साथ युग्म। \"शक्ति लुप्त होती\" पढ़ना सिखाता है न कि केवल उलटाव।"},{"shape":"harami_bear","name":"मंदी हरामी","color":"#ef4444","bias":"बेचें (मुलायम)","tip":"बड़ा हरा, फिर अंदर छोटा लाल - खरीदने का दबाव सिकुड़ रहा है।","also":"इसके अलावा: दीर्घों पर आंशिक भाग लें। स्वचालित लघु नहीं. मनोविज्ञान: बड़े हरे रंग के बाद लालच अक्सर हरामी चेतावनी को नजरअंदाज कर देता है।"},{"shape":"tweezer_bot","name":"चिमटी से नोचना नीचे","color":"#22c55e","bias":"खरीदें","tip":"मेल खाते न्यूनतम स्तर वाली दो मोमबत्तियाँ - समर्थन का दोहरा परीक्षण।","also":"इसके अलावा: उस निम्न को संरचना के रूप में चिह्नित करें। एसएल ठीक नीचे। फाइब/बीबी संरेखण मदद करता है। डबल बॉटम का चार्ट पैटर्न चचेरा भाई - समान समर्थन पाठ।"},{"shape":"tweezer_top","name":"चिमटी से नोचना शीर्ष","color":"#ef4444","bias":"बेचो","tip":"मेल खाती ऊँचाई वाली दो मोमबत्तियाँ - प्रतिरोध का दोहरा परीक्षण।","also":"इसके अलावा: प्रतिरोध को चिह्नित करें। डबल टॉप का चचेरा भाई। उच्च स्तर पर आरएसआई विफलता = संगम। सिखाता है: एक ही कीमत दो बार अस्वीकृत = स्तर का सम्मान करें।"},{"shape":"longlegged","name":"लंबी टांगों वाली दोजी","color":"#94a3b8","bias":"अनिर्णय","tip":"एक छोटे से शरीर के साथ बहुत लंबी ऊपरी और निचली विक्स - एक हिंसक दो-तरफा लड़ाई जो जहां शुरू हुई वहीं समाप्त हो गई।","also":"इसके अलावा: अक्सर एक बड़ा कदम उठाया जाता है, लेकिन दिशा अज्ञात होती है - मोमबत्ती टूटने की प्रतीक्षा करें। सिखाता है: उच्च अस्थिरता उच्च निश्चितता नहीं है।"},{"shape":"dragonfly","name":"ड्रैगनफ्लाई दोजी","color":"#22c55e","bias":"पूर्वाग्रह खरीदें","tip":"खुला = बंद = ऊंचा, एक लंबी निचली बाती के साथ - विक्रेताओं ने इसे नीचे धकेल दिया और खरीदारों ने इसे सीधे वापस ऊपर पटक दिया।","also":"इसके अलावा: समर्थन पर सबसे मजबूत/गिरावट के बाद बीबी कम। बाती की पूंछ के नीचे एसएल। सिखाता है: अस्वीकृति एक कहानी है, गारंटी नहीं - अगली मोमबत्ती की पुष्टि करें।"},{"shape":"gravestone","name":"ग्रेवस्टोन दोजी","color":"#ef4444","bias":"पूर्वाग्रह बेचें","tip":"खुला = बंद = नीचा, एक लंबी ऊपरी बाती के साथ - खरीदार ऊपर की ओर धकेले गए और विक्रेताओं ने इसे वापस निचले स्तर पर खींच लिया।","also":"इसके अलावा: प्रतिरोध पर सबसे मजबूत/ऊपरी बीबी/आरएसआई ओवरबॉट। ड्रैगनफ्लाई का दर्पण. सिखाता है: एक स्पाइक हाई जो निचले स्तर पर बंद होता है वह एक असफल ब्रेकआउट है।"},{"shape":"inside_bar","name":"बार के अंदर","color":"#94a3b8","bias":"कुंडलित होना/प्रतीक्षा करना","tip":"दूसरी मोमबत्ती पूरी तरह से पहले के अंदर बैठती है - सीमा संकुचित हो जाती है और बाजार अपनी सांस रोक लेता है।","also":"इसके अलावा: मदर बार का टूटना ट्रिगर है - ब्रेक दिशा में व्यापार करें। बीबी स्क्वीज़ के साथ जोड़ा गया। सिखाता है: विस्तार से पहले संकुचन आता है।"},{"shape":"outside_bar","name":"बार के बाहर","color":"#22c55e","bias":"ब्रेकआउट/रिवर्सल","tip":"दूसरी मोमबत्ती पहले को ऊपर से नीचे तक घेरती है - एक बार के अंदर एक हिंसक कब्ज़ा।","also":"इसके अलावा: दिशा = जहां बाहरी पट्टी बंद होती है। एक बड़ी पट्टी का मतलब एक बड़ा एसएल है, इसलिए आकार छोटा है। सिखाता है: एक बार अंतिम तीन को मिटा सकता है।"},{"shape":"belt_bull","name":"बुलिश बेल्ट होल्ड","color":"#22c55e","bias":"खरीदें","tip":"बिना किसी निचली बाती के निचले स्तर पर खुलता है और हरे रंग में चलता है - खरीदारों ने पहले टिक से ही नियंत्रण ले लिया।","also":"इसके अलावा: एक अंतराल के बाद सबसे मजबूत नीचे या सीधे समर्थन में। खुले के नीचे एसएल. सिखाता है: एक शुरुआती ड्राइव वास्तविक इरादे को दर्शाती है।"},{"shape":"belt_bear","name":"बेयरिश बेल्ट होल्ड","color":"#ef4444","bias":"बेचो","tip":"बिना किसी ऊपरी बाती के ऊंचाई पर खुलता है और लाल रंग में चलता है - विक्रेताओं ने इसे खुले से नियंत्रित किया।","also":"इसके अलावा: अंतराल के बाद या प्रतिरोध पर सबसे मजबूत। राह लंबी है. सिखाता है: पहली चाल में पूरा दिन लग सकता है।"},{"shape":"kick_bull","name":"बुलिश किकर","color":"#22c55e","bias":"जोरदार खरीदारी","tip":"एक लाल मोमबत्ती, फिर एक हरे मोमबत्ती में एक अंतराल - मूड बिना किसी ओवरलैप के बंद होने के बीच फ़्लिप हो गया।","also":"इसके अलावा: दुर्लभ और शक्तिशाली; अंतराल आवश्यक है, ओवरलैप की अनुमति नहीं है। सिखाता है: जब बाजार सोता है तो भावना पलट सकती है।"},{"shape":"kick_bear","name":"बेयरिश किकर","color":"#ef4444","bias":"मजबूत बिक्री","tip":"एक हरी मोमबत्ती, फिर एक लाल मोमबत्ती में एक अंतराल - समापन के बीच खरीदार गायब हो गए।","also":"इसके अलावा: जल्दी से बाहर निकलें - किकर्स आपका इंतजार नहीं करते। सिखाता है: जब आप दूर होते हैं तो एक अंतर बाजार का पुनर्मूल्यांकन होता है।"},{"shape":"abandoned","name":"बुलिश परित्यक्त बच्चा","color":"#22c55e","bias":"जोरदार खरीदारी","tip":"एक लाल मोमबत्ती, एक गैप-डाउन दोजी, फिर एक गैप-अप हरी मोमबत्ती - अनिर्णय का एक अकेला द्वीप।","also":"इसके अलावा: डोजी को दोनों तरफ दूर रहना चाहिए। दुर्लभ लेकिन तली में उच्च गुणवत्ता। सिखाता है: उलटफेर वहीं से शुरू होता है जहां हर कोई हार मान लेता है।"},{"shape":"three_inside_up","name":"तीन अंदर ऊपर","color":"#22c55e","bias":"खरीदें","tip":"बुलिश हरामी और एक तीसरी हरी मोमबत्ती जो पहली के ऊपर बंद होती है - अंदर की पट्टी अंततः टूट गई।","also":"इसके अलावा: एक पक्का हरामी नंगे हरामी से कहीं अधिक मजबूत होता है। हरामी लो के तहत एसएल। सिखाता है: पुष्टि भविष्यवाणी को मात देती है।"},{"shape":"three_inside_down","name":"तीन अंदर नीचे","color":"#ef4444","bias":"बेचो","tip":"बेयरिश हरामी और तीसरी लाल मोमबत्ती पहली के नीचे बंद हो रही है - अंदर की पट्टी टूट गई।","also":"इसके अलावा: जैसे ही तीसरा बंद हो जाए, लॉन्ग काट लें। सिखाता है: एक असफल विराम पुरानी प्रवृत्ति को फिर से शुरू कर सकता है।"},{"shape":"three_methods_bull","name":"बढ़ती तीन विधियाँ","color":"#22c55e","bias":"खरीदने का चलन","tip":"एक लंबी हरी मोमबत्ती, उसके अंदर तीन छोटे लाल, फिर एक और लंबी हरी - बाकी एक उभार के अंदर।","also":"इसके अलावा: विराम पहली मोमबत्ती सीमा को कभी नहीं छोड़ता है, इसलिए प्रवृत्ति शांत है। आखिरी मोमबत्ती के टूटने का व्यापार करें। सिखाता है: रुझान बिना टूटे आराम करते हैं।"},{"shape":"three_methods_bear","name":"गिरने की तीन विधियाँ","color":"#ef4444","bias":"बेचने की प्रवृत्ति","tip":"एक लंबी लाल मोमबत्ती, उसके अंदर तीन छोटे हरे रंग, फिर एक और लंबी लाल - पतझड़ के अंदर बाकी।","also":"इसके अलावा: राइजिंग थ्री मेथड्स का दर्पण। छोटी हरी सब्जियाँ न खरीदें - वे शोर करती हैं। सिखाता है: एक सीमा के अंदर पुलबैक रिवर्सल नहीं हैं।"},{"shape":"tower_bot","name":"टावर तल","color":"#22c55e","bias":"उलटा खरीदें","tip":"एक लंबी लाल मोमबत्ती, छोटी मोमबत्तियों का समूह, फिर एक लंबी हरी - मूड एक सपाट आधार पर बदल जाता है।","also":"इसके अलावा: सपाट मध्य लड़ाई है और आखिरी मोमबत्ती विजेता की घोषणा करती है। सिखाता है: आधार बनाने में समय लगता है।"},{"shape":"tower_top","name":"टावर टॉप","color":"#ef4444","bias":"उलटा बेचें","tip":"एक लंबी हरी मोमबत्ती, छोटी मोमबत्तियों का एक समूह, फिर एक लंबी लाल मोमबत्ती - खरीदार ख़त्म हो जाते हैं और विक्रेता उनकी जगह ले लेते हैं।","also":"इसके अलावा: टावर बॉटम का दर्पण। आधार बनते समय आंशिक भाग लें। सिखाता है: शीर्ष एक प्रक्रिया है, एक क्षण नहीं।"}],"chartPatterns":[{"shape":"double_bot","name":"डबल बॉटम (डब्ल्यू)","color":"#22c55e","bias":"पूर्वाग्रह खरीदें","tip":"एक ही कीमत के करीब दो निम्नतम, फिर मध्य शिखर का टूटना - डब्ल्यू आकार।","also":"इसके अलावा: नेकलाइन ब्रेक = अभ्यास ट्रिगर। टीपी विचार के लिए ऊंचाई मापें। पीक → लो से ट्वीजर बॉटम + फाइब के लिंक। जोखिम: गलत ब्रेक - नेकलाइन से परे करीब प्रतीक्षा करें।"},{"shape":"double_top","name":"डबल टॉप (एम)","color":"#ef4444","bias":"पूर्वाग्रह बेचें","tip":"एक ही कीमत के करीब दो उच्च, फिर मध्य गर्त का टूटना - एम आकार।","also":"इसके अलावा: बड़े पैमाने पर ट्वीजर टॉप के समान। नेकलाइन टूटने से बहुत पहले निशान। मनोविज्ञान: दूसरा शीर्ष FOMO महंगा है - योजना पहले से ही थी।"},{"shape":"hs_top","name":"सिर और कंधे","color":"#ef4444","bias":"पूर्वाग्रह बेचें","tip":"बायां कंधा, ऊंचा सिर, दायां कंधा; नेकलाइन को नीचे तोड़ें।","also":"इसके अलावा: क्लासिक वितरण. लक्ष्य ≈ नेकलाइन के नीचे सिर की ऊंचाई। आरएसआई अक्सर सिर पर विचलन करता है। मल्टी-स्विंग धैर्य सिखाता है - एक-मोमबत्ती व्यापार नहीं।"},{"shape":"ihs","name":"उलटा एच एंड एस","color":"#22c55e","bias":"पूर्वाग्रह खरीदें","tip":"नीचे की ओर उल्टा एच एंड एस - नेकलाइन टूट गई।","also":"इसके अलावा: संचय कहानी. यदि उपलब्ध हो तो मात्रा/गति की पुष्टि करें। संगम अध्ययन के लिए दाहिने कंधे के क्षेत्र में मॉर्निंग स्टार के साथ जोड़ी बनाएं।"},{"shape":"triangle","name":"त्रिकोण (निचोड़ें)","color":"#f0b429","bias":"ब्रेकआउट प्रतीक्षा करें","tip":"निम्न ऊँचाई + उच्चतर निम्न संपीड़न - ऊर्जा निर्माण।","also":"इसके अलावा: बीबी स्क्वीज़ जैसा ही पाठ। अंदर दिशा का अनुमान न लगाएं. व्यापार विराम + मोमबत्ती बंद। धन: दिशा के अनुसार आकार ज्ञात।"},{"shape":"flag","name":"बैल का झंडा","color":"#22c55e","bias":"जारी रखें खरीदें.","tip":"तीव्र वृद्धि (ध्रुव) फिर छोटा नीचे/बग़ल में चैनल - फिर निरंतरता।","also":"इसके अलावा: फाइब ध्वज की गहराई अक्सर उथली (38%) होती है। मारुबोज़ू पोल + ध्वज = प्रवृत्ति अभ्यास। बिना पुलबैक के पूर्ण विस्तार के बाद देर से खरीदारी न करें।"},{"shape":"channel","name":"ट्रेंड चैनल","color":"#38bdf8","bias":"ट्रेंड के साथ","tip":"बढ़ती (या गिरती) समानांतर रेखाओं के बीच मूल्य - स्विंग ट्रेड टूल।","also":"इसके अलावा: अपट्रेंड में निचला चैनल + हैमर खरीदें; अपर + शूटिंग स्टार बेचें। बीबी मिड अक्सर चैनल ट्रैक करता है। \"कहाँ\" सिखाता है न कि केवल \"कैसी मोमबत्ती\"।"},{"shape":"support_res","name":"समर्थन और प्रतिरोध","color":"#a78bfa","bias":"प्रसंग पहले","tip":"क्षैतिज क्षेत्र जहां कीमत बार-बार प्रतिक्रिया करती है - प्रत्येक मोमबत्ती के नीचे का नक्शा।","also":"इसके अलावा: प्रत्येक पैटर्न एस/आर पर मजबूत है। बीबी/आरएसआई से पहले चार्ट लैब पर जोन बनाएं। मनोविज्ञान: स्तर > युक्तियाँ; प्रवेश से पहले उन्हें लिखें."},{"shape":"triple_top","name":"ट्रिपल टॉप","color":"#ef4444","bias":"पूर्वाग्रह बेचें","tip":"लगभग एक ही कीमत पर तीन उच्चतम - खरीदार एक ही दीवार पर तीन बार असफल होते हैं।","also":"इसके अलावा: डबल टॉप से ​​अधिक मजबूत (तीन अस्वीकार = जिद्दी आपूर्ति)। नेकलाइन का टूटना ट्रिगर है; लक्ष्य ≈ पैटर्न ऊंचाई। सिखाता है: स्तर, मोमबत्ती नहीं, मालिक है।"},{"shape":"triple_bot","name":"ट्रिपल बॉटम","color":"#22c55e","bias":"पूर्वाग्रह खरीदें","tip":"लगभग एक ही कीमत पर तीन निचले स्तर - विक्रेता एक मंजिल पर तीन बार विफल होते हैं।","also":"इसके अलावा: ट्रिपल टॉप का दर्पण. प्रत्येक स्पर्श एक हथौड़ा/ट्वीज़र अध्ययन हो सकता है। नेकलाइन टूटने + बंद होने की प्रतीक्षा करें। अनेक उतार-चढ़ावों में धैर्य रखना सिखाता है।"},{"shape":"cup_handle","name":"कप और हैंडल","color":"#22c55e","bias":"जारी रखें खरीदें.","tip":"एक गोलाकार \"यू\" (कप) फिर एक छोटा पुलबैक (हैंडल) - आराम के बाद निरंतरता।","also":"इसके अलावा: ब्रेकआउट व्यापारियों के बीच लोकप्रिय। हैंडल उथला और छोटा होना चाहिए - गहरे हैंडल का मतलब है कमजोर हाथ। मोमबत्ती की पुष्टि के साथ हैंडल-ब्रेक पर प्रवेश करें।"},{"shape":"rounding_bot","name":"गोलाकार तल","color":"#22c55e","bias":"उलटा खरीदें","tip":"एक धीमी, चिकनी \"तश्तरी\" कम - बिक्री धीरे-धीरे फीकी पड़ जाती है, फिर खरीदार हावी हो जाते हैं।","also":"इसके अलावा: एक धीमी गति वाला डबल बॉटम। संदेश यह है कि विक्रेताओं की ऊर्जा खत्म हो गई है, एक भी उछाल नहीं आया - पूर्ण धैर्य की आवश्यकता है।"},{"shape":"rounding_top","name":"गोलाकार शीर्ष","color":"#ef4444","bias":"उलटा बेचें","tip":"एक चिकनी \"गुंबद\" ऊंचाई - कीमत बढ़ने से पहले खरीदारी धीरे-धीरे फीकी पड़ जाती है।","also":"इसके अलावा: राउंडिंग बॉटम का दर्पण। आंशिक भाग जल्दी लें जबकि गति समाप्त हो जाती है। सिखाता है: शीर्ष एक प्रक्रिया है, एक मोमबत्ती नहीं।"},{"shape":"rising_wedge","name":"बढ़ती कील","color":"#ef4444","bias":"पूर्वाग्रह बेचें","tip":"दोनों रेलें ऊपर उठती हैं, लेकिन वे ऊपर की ओर एकत्रित हो जाती हैं - जैसे-जैसे रेंज घटती है, खरीदार थक जाते हैं।","also":"इसके अलावा: भ्रामक क्योंकि कीमत अभी भी बढ़ रही है; संकुचन ही वास्तविक सुराग है। अक्सर टूट जाता है. आखिरी धक्के का पीछा मत करो."},{"shape":"falling_wedge","name":"गिरती हुई कील","color":"#22c55e","bias":"पूर्वाग्रह खरीदें","tip":"दोनों पटरियाँ गिरती हैं, लेकिन वे नीचे की ओर मिलती हैं - रेंज कम होने पर विक्रेता थक जाते हैं।","also":"इसके अलावा: राइजिंग वेज का दर्पण। अक्सर यूपी टूट जाता है. वेज टेल में एक हथौड़ा एक क्लासिक अध्ययन है। ब्रेक + बंद होने की प्रतीक्षा करें।"},{"shape":"asc_triangle","name":"आरोही त्रिभुज","color":"#f0b429","bias":"पूर्वाग्रह खरीदें","tip":"एक सपाट छत + बढ़ती मंजिल - खरीदार एक निश्चित प्रतिरोध में कदम बढ़ाते रहते हैं।","also":"इसके अलावा: एक कीमत के विरुद्ध दबाव बनता है; ब्रेकआउट होना आम बात है. छत के करीब से प्रवेश करें। सिखाता है: खरीदार अधीर हो रहे हैं।"},{"shape":"desc_triangle","name":"उतरता हुआ त्रिभुज","color":"#f0b429","bias":"पूर्वाग्रह बेचें","tip":"एक सपाट फर्श + गिरती छत - विक्रेता एक निश्चित समर्थन पर जोर देते रहते हैं।","also":"इसके अलावा: आरोही त्रिभुज का दर्पण। ब्रेकआउट डाउन होना आम बात है. फर्श के नीचे करीब से प्रवेश करें। सिखाता है: विक्रेता नियंत्रण प्राप्त कर रहे हैं।"},{"shape":"pennant","name":"पताका","color":"#22c55e","bias":"निरंतरता","tip":"एक तेज़ खंभा, फिर एक छोटा, तंग त्रिकोण - प्रवृत्ति फिर से शुरू होने से पहले एक बहुत ही छोटा आराम।","also":"इसके अलावा: एक झंडे की तरह लेकिन छोटा और त्रिकोणीय। लक्ष्य विचार के लिए ध्रुव को मापें। छोटे कुंडल के अंदर कभी अनुमान न लगाएं।"},{"shape":"flag_bear","name":"भालू झंडा","color":"#ef4444","bias":"बिक्री जारी रखें.","tip":"एक तेज़ गिरावट (ध्रुव) फिर एक छोटा ऊपर/बग़ल में चैनल - फिर नीचे की ओर जारी रहना।","also":"इसके अलावा: बुल फ्लैग का दर्पण. थोड़ा सा उछाल एक विराम है, उलटाव नहीं। झंडे का पीछा करें और आप सबसे खराब कीमत पर खरीदें - ब्रेक की प्रतीक्षा करें।"},{"shape":"rectangle","name":"आयत (रेंज)","color":"#f0b429","bias":"रेंज व्यापार","tip":"कीमत एक सपाट छत और फर्श के बीच उछलती है - एक बग़ल में बॉक्स।","also":"इसके अलावा: किनारों को अंदर से फीका करें, ब्रेक को बाहर से ट्रेड करें। बीबी निचोड़ आमतौर पर एक आयत के अंदर बैठता है। सिखाता है: स्तर-दर-स्तर अनुशासन।"},{"shape":"broadening","name":"चौड़ीकरण संरचना","color":"#f0b429","bias":"सावधानी","tip":"उच्चतर ऊँचाई और निचली निम्नता - सीमा सिकुड़ने के बजाय फ़ैन हो जाती है।","also":"इसके अलावा: एक अराजक, भावनात्मक बाज़ार। स्टॉप दोनों तरफ से प्रभावित होते हैं। छोटे आकार या एक तरफ खड़े हो जाओ; यह अक्सर एक हिंसक एकतरफा कदम में समाप्त होता है।"},{"shape":"diamond","name":"हीरा","color":"#f0b429","bias":"उलटा","tip":"बीच में चौड़ा, दोनों सिरों पर संकीर्ण - एक क्लासिक टॉपिंग/बॉटिंग संरचना।","also":"इसके अलावा: एक त्रिभुज जो रूपांतरित होता है और फिर अरूपित होता है। ब्रेकआउट दिशा तय करती है. दुर्लभ और धीमा, इसलिए अधिकांश पंक्तियाँ शोर जैसी महसूस होती हैं - धैर्य रखें।"},{"shape":"island_rev","name":"द्वीप उत्क्रमण","color":"#ef4444","bias":"उलटा","tip":"मूल्य अंतर दूर हो जाता है, एक अकेले समूह में व्यापार होता है, फिर अंतराल वापस आता है - एक \"द्वीप\"।","also":"इसके अलावा: वास्तविक अंतराल की आवश्यकता है (स्टॉक/एफएक्स में अधिक सामान्य)। द्वीप में खरीदार या विक्रेता फंस गए हैं। अंतरालों को संकेत मानें, द्वीप मोमबत्तियाँ नहीं।"},{"shape":"breakaway_gap","name":"ब्रेकअवे गैप","color":"#22c55e","bias":"रुझान शुरू","tip":"किसी सीमा या आधार से बाहर का अंतर - चाल बल से शुरू होती है, दबाव से नहीं।","also":"इसके अलावा: एक थकावट अंतराल के विपरीत यह एक चाल में जल्दी दिखाई देता है। अंतराल अक्सर बाद में समर्थन/प्रतिरोध के रूप में कार्य करते हैं। सिखाता है: गति बनाम मूल्य अंतराल।"},{"shape":"v_reversal","name":"वी-रिवर्सल","color":"#22c55e","bias":"उलटा","tip":"एक तेज फ्री-फ़ॉल जो बिना किसी आधार के तुरंत बदल जाता है - एक \"वी\"।","also":"इसके अलावा: तेज़ और डरावना; अक्सर समाचार-संचालित। पकड़ना कठिन, पीछा करना आसान। स्पाइक खरीदने के बजाय एक छोटे पुलबैक + कैंडल की प्रतीक्षा करें।"},{"shape":"harmonic","name":"हार्मोनिक पैटर्न","color":"#f0b429","bias":"उलटा क्षेत्र","tip":"एक मापा ज़िग-ज़ैग (एक्स-ए-बी-सी-डी) जहां प्रत्येक पैर में फाइबोनैचि अनुपात होता है - एक \"गार्टली/बैट\" शैली मानचित्र।","also":"इसके अलावा: उन्नत. डी बिंदु प्रवेश क्षेत्र है, जिसे अनुपात द्वारा परिभाषित किया गया है, भावनाओं से नहीं। पहले मास्टर सादा फाइब; यह फाइब एक स्तर अधिक गहराई से लिया गया है।"}],"modules":[{"id":"bb","title":"1 · बोलिंगर बैंड (बीबी)","summary":"अस्थिरता एक चलती औसत के आसपास होती है। स्क्वीज़, वॉक-द-बैंड, निचला/ऊपरी स्पर्श + कैंडल कन्फ़र्म सीखें - मुख्य सीपीई अभ्यास सेटअप।","lessons":[{"h":"बीबी क्या है","t":"बोलिंगर बैंड = मध्य एसएमए (अक्सर 20) + एन मानक विचलन पर ऊपरी/निचले बैंड (अक्सर 2)। जब अस्थिरता बढ़ती है तो बैंड चौड़ा हो जाता है और जब बाजार शांत होता है तो सिकुड़ जाता है।"},{"h":"मध्य बैंड","t":"मध्य रेखा माध्य है. मध्य से ऊपर की कीमत अक्सर तेजी का दबाव दिखाती है; नीचे मंदी का दबाव दिखाया गया है। इसे एक गतिशील पूर्वाग्रह रेखा के रूप में उपयोग करें, जादुई खरीद/बिक्री के रूप में नहीं।"},{"h":"निचला बैंड (अभ्यास खरीदें)","t":"कीमत में गिरावट के बाद निचले बैंड को टैग करने का मतलब \"बढ़ा हुआ\" हो सकता है। हर स्पर्श न खरीदें. एक बुलिश कैंडल (हैमर, एनगल्फिंग) और आदर्श रूप से आरएसआई के बढ़ने की प्रतीक्षा करें।"},{"h":"ऊपरी बैंड (बेचें/सावधानी)","t":"ऊपरी बैंड पर मूल्य टैग करने का अर्थ \"विस्तारित\" हो सकता है। एक अपट्रेंड में, कीमत ऊपरी बैंड (वॉक-द-बैंड) पर चढ़ सकती है। केवल मंदी वाली कैंडल + उच्च-टीएफ कमजोरी के साथ बेचने के विचारों को प्राथमिकता दें।"},{"h":"निचोड़","t":"संकीर्ण बैंड = कम अस्थिरता → एक ब्रेकआउट अक्सर होता है। एक तंग निचोड़ के अंदर दिशा का अनुमान न लगाएं; ब्रेकआउट को चिह्नित करें और यदि उपलब्ध हो तो कैंडल + वॉल्यूम से पुष्टि करें।"},{"h":"बैंड चलो","t":"एक मजबूत प्रवृत्ति में, कीमत कई मोमबत्तियों के लिए ऊपरी (या निचले) बैंड को गले लगा लेती है। माध्य-प्रत्यावर्तन फीके से लड़ना एक सामान्य शुरुआती गलती है।"},{"h":"बीबी + चार्ट लैब","t":"सीपीई चार्ट लैब/डेस्क में, डेमो पर मोमबत्तियों के साथ बीबी का अध्ययन करें। अभ्यास: निचला बैंड + हैमर → बाती के नीचे एसएल के साथ पेपर ट्रेड, मध्य बैंड के पास टीपी1।"},{"h":"बीबी + आरएसआई कॉम्बो","t":"मजबूत अभ्यास फ़िल्टर: निचला बीबी + आरएसआई ओवरसोल्ड (या ओवरसोल्ड से बढ़ना) + बुलिश कैंडल। अपर बीबी + आरएसआई ओवरबॉट + लघु अभ्यास के लिए मंदी मोमबत्ती।"},{"h":"प्लेसमेंट रोकें","t":"लंबा अभ्यास: एसएल स्विंग लो के नीचे/निचले बैंड विक के नीचे। लघु अभ्यास: एसएल ऊपर स्विंग उच्च। लिखित एसएल के बिना कभी भी बीबी ट्रेड में प्रवेश न करें।"},{"h":"लक्ष्य","t":"सामान्य पथ: मध्य बैंड पर टीपी1, विपरीत बैंड या निशान की ओर टीपी2। स्केल आउट - पूरे कदम की जरूरत नहीं है।"},{"h":"समयसीमा","t":"उच्च TF (4H/1D) पर पूर्वाग्रह तय करें। 15m/30m BB + कैंडल पर दर्ज करें। यादृच्छिक TFs को मिलाने से परस्पर विरोधी संकेत उत्पन्न होते हैं।"},{"h":"गलतियों से बचना चाहिए","t":"गिरते बाजार में हर लोअर-बैंड टच खरीदना; मून-रन में हर ऊपरी स्पर्श को बेचना; कोई एसएल नहीं; उन समाचार स्पाइक्स को नज़रअंदाज़ करना जो बैंड को हिंसक रूप से विस्तारित करते हैं।"},{"h":"अभ्यास चेकलिस्ट","t":"① उच्च टीएफ पूर्वाग्रह ② बीबी स्पर्श या निचोड़ ब्रेक ③ मोमबत्ती पुष्टि ④ आरएसआई सहमत ⑤ जोखिम% सेट ⑥ पहला पेपर ⑦ जर्नल परिणाम।"}]},{"id":"rsi","title":"2 · आरएसआई (सापेक्ष शक्ति सूचकांक)","summary":"मोमेंटम ऑसिलेटर 0-100। डिफ़ॉल्ट 14 अवधि. बीबी और मोमबत्तियों के साथ प्रयोग करें - पूर्ण प्रणाली के रूप में कभी भी अकेले आरएसआई न करें।","lessons":[{"h":"आरएसआई क्या मापता है","t":"आरएसआई एन बार पर औसत लाभ बनाम हानि की तुलना करता है। उच्च आरएसआई = हालिया तेजी की गति; कम आरएसआई = हालिया मंदी की गति। यह हर बार \"अधिक खरीदा = बेचना ही चाहिए\" नहीं है।"},{"h":"क्लासिक जोन","t":"अक्सर: 70 से ऊपर = अधिक खरीददार क्षेत्र, 30 से नीचे = अधिक बिक्री क्षेत्र। मजबूत रुझानों में, आरएसआई लंबे समय तक अधिक खरीदा/अधिक बेचा जा सकता है - यह सामान्य है।"},{"h":"मध्य रेखा 50","t":"50 से ऊपर आरएसआई को पार करना तेजी के पूर्वाग्रह का समर्थन कर सकता है; 50 मंदी पूर्वाग्रह से नीचे। कई व्यापारी बीबी मिडिल बैंड के साथ ट्रेंड-फ़िल्टर के रूप में 50 का उपयोग करते हैं।"},{"h":"विचलन - तेजी","t":"कीमत निम्न को निम्न बनाती है, आरएसआई उच्चतर को निम्न बनाती है → नीचे की ओर गति कमजोर होती है। अभी भी पेपर प्रविष्टि से पहले मोमबत्ती + संरचना टूटने की प्रतीक्षा करें।"},{"h":"विचलन - मंदी","t":"कीमत अधिक ऊंची, आरएसआई निचली ऊंचाई → ऊपर की ओर गति कम होती जा रही है। प्रतिरोध या ऊपरी बीबी के निकट शूटिंग स्टार/एनगल्फिंग से पुष्टि करें।"},{"h":"असफलता झूलती है","t":"आरएसआई पिछले चरम को फिर से परखने में विफल रहता है और फिर 50 - प्रारंभिक गति बदलाव सुराग के माध्यम से वापस चला जाता है। चार्ट लैब संरचना के साथ संयोजन करें।"},{"h":"आरएसआई + बीबी (सीपीई शैली)","t":"लंबे समय तक अभ्यास करें: कीमत कम बीबी के पास, आरएसआई ≤ 35 (या ≤ 30 से बढ़ रही है), तेजी वाली मोमबत्ती। संक्षिप्त अभ्यास करें: ऊपरी बीबी, आरएसआई ≥ 65-70, मंदी मोमबत्ती।"},{"h":"छिपा हुआ विचलन","t":"रुझान निरंतरता सुराग (उदाहरण के लिए कीमत अधिक कम, अपट्रेंड में आरएसआई कम कम)। उन्नत - डेमो पर सबसे पहले मास्टर क्लासिक डाइवर्जेंस।"},{"h":"सेटिंग्स","t":"आरएसआई(14) सामान्य डिफ़ॉल्ट है। छोटा आरएसआई = अधिक शोर। सिग्नल को बाध्य करने के लिए सेटिंग्स बदलते न रहें।"},{"h":"आरएसआई के साथ बाहर निकलें","t":"यदि आपने ओवरसोल्ड खरीदारी की है, तो आरएसआई मध्य/ऊपरी क्षेत्र तक पहुंचने पर आंशिक लाभ लेना उचित है। संरचना या बीबी मध्य के साथ बाकी को ट्रेल करें।"},{"h":"समाचार और आरएसआई","t":"बड़ी खबर आरएसआई को तुरंत बढ़ा सकती है। आरएसआई चरम पर कार्रवाई करने से पहले पहली हिंसक मोमबत्ती के खत्म होने की प्रतीक्षा करना पसंद करें।"},{"h":"गलतियाँ","t":"तेजी के बाजार में प्रत्येक आरएसआई>70 को शॉर्ट करना; एक भालू दुर्घटना में प्रत्येक आरएसआई <30 की लालसा; कोई संगम नहीं; जब आरएसआई \"बेहतर दिखता है\" तो बदला पुनः प्रवेश।"},{"h":"अभ्यास चेकलिस्ट","t":"① नोट आरएसआई मूल्य + ढलान ② बीबी स्थान की जांच करें ③ मोमबत्ती पुष्टि ④ उच्च टीएफ ⑤ पेपर + जर्नल ⑥ एक समय में एक विचार।"}]},{"id":"fib","title":"3 · फाइबोनैचि (रिट्रेसमेंट और एक्सटेंशन)","summary":"स्पष्ट स्विंग हाई → स्विंग लो (या रिवर्स) से पुलबैक और लक्ष्य को मापें। बीबी/आरएसआई संगम के साथ 38.2 · 50 · 61.8 पर ध्यान दें।","lessons":[{"h":"फाइब का उपयोग क्यों किया जाता है","t":"कई व्यापारी समान अनुपात देखते हैं, इसलिए तरलता अक्सर उनके पास प्रतिक्रिया करती है। फाइब संभावित क्षेत्रों का एक नक्शा है - कोई गारंटी नहीं।"},{"h":"स्विंग पॉइंट","t":"हमेशा स्पष्ट स्विंग लो से स्विंग हाई (ऊपर की ओर) या हाई से लो (डाउन मूव) की ओर आकर्षित करें। ख़राब उतार-चढ़ाव = बेकार स्तर। चार्ट लैब डेमो पर झूले चुनने का अभ्यास करें।"},{"h":"मुख्य रिट्रेसमेंट","t":"सामान्य: 23.6% (उथला), 38.2%, 50% (शुद्ध फ़िब नहीं लेकिन व्यापक रूप से उपयोग किया जाता है), 61.8% (सुनहरा), 78.6% (गहरा)। गहरे रिट्रेस प्रवृत्ति की कमजोरी का संकेत दे सकते हैं।"},{"h":"पुलबैक खरीदारी (अपट्रेंड)","t":"आवेग बढ़ने के बाद, 38.2-61.8 ज़ोन + बुलिश कैंडल + अधिमानतः बीबी मध्य/निचला समर्थन या आरएसआई होल्डिंग >40-45 में पुलबैक की प्रतीक्षा करें।"},{"h":"पुलबैक बिकता है (डाउनट्रेंड)","t":"आवेग में गिरावट के बाद, 38.2-61.8 + मंदी मोमबत्ती + आरएसआई 55-60 के नीचे विफल होने पर पलटाव।"},{"h":"विस्तार/लक्ष्य","t":"सामान्य एक्सटेंशन: 127.2%, टीपी2 विचारों के लिए 161.8% स्विंग से परे। ट्रेल के साथ प्रयोग करें - सटीक टिकों को बाध्य न करें।"},{"h":"संगम = शक्ति","t":"सर्वोत्तम अभ्यास क्षेत्र: फाइब 50/61.8 + बीबी मध्य/निचला + पूर्व संरचना + आरएसआई मोड़। केवल एक फाइब रेखा ही कमजोर होती है।"},{"h":"फाइब + बी.बी","t":"यदि 61.8% अपट्रेंड में निचले बीबी के पास बैठता है, तो वह ओवरलैप एक उच्च गुणवत्ता वाला पेपर अध्ययन क्षेत्र है। मोमबत्ती की पुष्टि के साथ ही प्रवेश करें।"},{"h":"मल्टीपल फाइब","t":"शुरुआती लोगों को वन क्लीन स्विंग का उपयोग करना चाहिए। 5 फाइब को स्टैक करने से चार्ट शोर और FOMO प्रविष्टियाँ उत्पन्न होती हैं।"},{"h":"अमान्यकरण","t":"यदि कीमत आपके पूर्वाग्रह के विपरीत स्पष्ट रूप से 78.6% से अधिक बंद हो जाती है, तो पुलबैक थीसिस अक्सर विफल हो जाती है - बाहर निकलें या एक तरफ खड़े रहें।"},{"h":"विदेशी मुद्रा बनाम क्रिप्टो","t":"समान अनुपात. विदेशी मुद्रा की बड़ी कंपनियां अक्सर तरल सत्रों में स्तरों का अधिक स्पष्टता से सम्मान करती हैं; क्रिप्टो फिर से उल्टा हो सकता है - आकार छोटा।"},{"h":"गलतियाँ","t":"छोटे शोर वाले झूलों पर फाइब खींचना; बिना मोमबत्ती के मध्य हवा में प्रवेश करना; जब फाइब \"लगभग\" पकड़ में आता है तो SL को और आगे ले जाना; उच्च टीएफ को नजरअंदाज करना।"},{"h":"अभ्यास चेकलिस्ट","t":"① मार्क स्विंग ② नोट 38.2/50/61.8 ③ कीमत आने की प्रतीक्षा करें ④ कैंडल + आरएसआई/बीबी ⑤ जोखिम सेट ⑥ पेपर → जर्नल।"}]},{"id":"money","title":"4 · धन प्रबंधन","summary":"विधि का वास्तव में उपयोग कैसे किया जाता है: एक निश्चित प्रतिशत का जोखिम, स्टॉप से ​​आकार, लाभ का बैंक हिस्सा, और हानि सीमा के बाद दिन के लिए रुकें। सीपीई इसे मैनुअल और ऑटो ट्रेडों पर लागू कर सकता है।","lessons":[{"h":"धन प्रबंधन का लक्ष्य","t":"खेल में बने रहो. एक ख़राब व्यापार से खाता कभी ख़त्म नहीं होना चाहिए। संगति लॉटरी आकार को मात देती है।"},{"h":"व्यापारी वास्तव में इसका उपयोग कैसे करते हैं","t":"सामान्य अभ्यास निश्चित-आंशिक जोखिम है। आप पहले सिक्के की राशि नहीं चुनते. आप पहले स्टॉप लिखें, तय करें कि इस विचार से खाते का लगभग 1% खो सकता है, फिर आकार उससे बाहर हो जाता है। चौड़े स्टॉप को छोटा स्थान मिलता है। एक सख्त स्टॉप को बड़ा स्थान मिलता है, और डॉलर का जोखिम लगभग समान रहता है। यह वह विधि है जिसका उपयोग सीपीई तब करता है जब धन-प्रबंधन टिक चालू होता है।"},{"h":"कार्यान्वित उदाहरण ($1000 अभ्यास खाता)","t":"खाता $1000. जोखिम 1% = $10. प्रवेश 100, रुकें 98। दूरी = 2%। आकार = 10 ÷ 0.02 = $500 अनुमानित। यदि स्टॉप हिट हो जाता है, तो नुकसान लगभग $10 का होता है, $500 का नहीं। यदि कीमत 103 (जोखिम का 1.5 गुना) तक पहुंच जाती है, तो लाभ लगभग $15 है। प्रत्येक जोड़ी पर एक ही विचार: जोखिम में डॉलर 1% के करीब रहता है, सिक्के की मात्रा बदल जाती है।"},{"h":"सीपीई टिक के साथ क्या करता है","t":"अभी ट्रेड करें → ऑटो: \"धन प्रबंधन का उपयोग करें\" पर टिक करें। ऑटो कॉन्फ़िग सहेजें. प्रत्येक नया ऑटो व्यापार तब $1000 अभ्यास खाते का लगभग 1% और बंद परिणाम का उपयोग करता है, जो उस सिग्नल की प्रविष्टि और एसएल से आकार होता है। स्पॉट और वायदा न्यूनतम का सम्मान किया जाता है: यदि एक्सचेंज न्यूनतम 1% से अधिक जोखिम रखता है, तो उस व्यापार को छोड़ दिया जाता है। कैलेंडर दिवस पर लगभग -2% के बाद, नए ऑटो अगले दिन तक रुक जाते हैं। खुले ट्रेडों में अधिकतम लगभग 3% जोखिम है। मैनुअल ट्रेड में एक ही टिक है। सिग्नल इतिहास अभी भी समान $10 परीक्षण दिखाता है, और इसके अंतर्गत $1000 खाते के लिए 1% योजना आकार दिखाता है, ताकि आप दोनों देख सकें।"},{"h":"आंशिक लाभ और राह","t":"अभ्यास यह है कि पहले लक्ष्य (अक्सर लगभग आधे) पर भाग लें और बाकी को पीछे छोड़ दें। जब स्टॉप ऊपर बढ़ता है, तो लक्ष्य भी आगे बढ़ सकता है, इसलिए विजेता पहले लक्ष्य से अधिक भुगतान कर सकता है। मूल विचार पर जोखिम नहीं बढ़ता. एक मजबूत सिग्नल 5% जोखिम का कारण नहीं है। वही 1% उपयोग किया जाता है. राह ही एक मजबूत विजेता को आगे बढ़ने देती है।"},{"h":"दैनिक रुकें और खुली गर्मी","t":"एक प्रयुक्त नियम: यदि दिन में खाते में लगभग 2% की गिरावट आती है, तो ट्रेड खोलना बंद कर दें। 1% पर तीन खुले विचार लगभग 3% ऊष्मा हैं। पाँच सहसंबद्ध सिक्के एक दांव हैं, पाँच नहीं। उन्हें एक साथ गिनें."},{"h":"यह विधि क्या मना करती है","t":"मार्टिंगेल (नुकसान के बाद दोगुना होना) का उपयोग नहीं किया जाता है। प्रवेश के बाद \"इसे जगह देने\" के लिए स्टॉप को आगे ले जाना उपयोग में नहीं है। ऑल-इन पर \"सुनिश्चित\" सिग्नल का उपयोग नहीं किया जाता है। यदि कोई वैध रोक नहीं है, कोई आकार नहीं है, तो कोई व्यापार नहीं है।"},{"h":"प्रति व्यापार जोखिम","t":"सामान्य नियम: एक विचार पर खाता इक्विटी का केवल ~0.5-1% जोखिम। डेमो पर, लाइव जैसी ही प्रतिशत आदत का अभ्यास करें।"},{"h":"स्थिति आकार सूत्र","t":"आकार ≈ (खाता × जोखिम%) ÷ (प्रवेश - रुकने की दूरी)। व्यापक एसएल → छोटा आकार। कभी भी आकार पहले और एसएल दूसरा न चुनें।"},{"h":"जोखिम: इनाम","t":"सीखते समय उन विचारों को प्राथमिकता दें जहां संभावित पुरस्कार ≥ जोखिम हो (जैसे 1:1.5 या बेहतर)। टीपी1 पर स्केल आउट करें ताकि धावक \"मुक्त जोखिम\" हों।"},{"h":"आंशिक लाभ-लाभ","t":"सीपीई शैली: टीपी1 कुछ लाभ को लॉक करता है, बाकी को टीपी2/ट्रेल। बैंकिंग आंशिकता भावनात्मक घबराहट को कम करती है।"},{"h":"अनुगामी टीपी + एसएल","t":"खरीदें: जैसे-जैसे कीमत बढ़ती है, निशान का स्तर बढ़ता है। बेचें: नीचे निशान। बिना किसी सटीक निकास कॉल की आवश्यकता के, ट्रेलिंग से लाभ खुलता है।"},{"h":"दैनिक/साप्ताहिक हानि सीमा","t":"उदाहरण नियम: -2% खाते के बाद अगले दिन के लिए ट्रेडिंग बंद कर दें। हानि सीमा के बाद बदला लेने के सत्र खाते के हत्यारे हैं।"},{"h":"स्थान का आकार निर्धारण","t":"स्पॉट न्यूनतम अनुमानित मामला (उदाहरण के लिए विनिमय मिनट)। फिर भी जोखिम% लागू करें: यदि आपके एसएल की तुलना में न्यूनतम आकार का जोखिम बहुत अधिक है, तो व्यापार छोड़ दें।"},{"h":"वायदा / उत्तोलन","t":"उत्तोलन लाभ और हानि दोनों को कई गुना बढ़ा देता है। उच्च उत्तोलन + विस्तृत एसएल = उड़ा हुआ खाता। सीखते समय कम उत्तोलन को प्राथमिकता दें; पृथक प्रति स्थिति हानि को सीमित कर सकता है।"},{"h":"सहसंबंध","t":"5 सहसंबद्ध बीटीसी विकल्प खोलना = एक बड़ा दांव, पाँच नहीं। जोखिम को एक समूह के रूप में गिनें।"},{"h":"फीस और फिसलन","t":"टाइट स्कैलप्स चार्ट पर अच्छे दिखते हैं लेकिन फीस R:R को खा जाती है। जब तक आपको लागत का पता न चल जाए, तब तक डेमो पर साफ़-सुथरे झूलों को प्राथमिकता दें।"},{"h":"डेमो → लाइव ब्रिज","t":"सीपीई डेमो अभ्यास (~3 महीने की मानसिकता): वही जर्नल नियम, वही %। लाइव होने पर, पहले सप्ताहों के लिए आधा डेमो आकार शुरू करें।"},{"h":"एपीआई धन सुरक्षा","t":"प्रत्येक कुंजी पर निकासी बंद। मैचिंग प्लेटफॉर्म पर टेस्ट अकाउंट ओके होने के बाद ही लाइव करें। गलत प्लेटफ़ॉर्म रहस्य = विफल या खतरनाक ऑप्स।"},{"h":"गलतियाँ","t":"मार्टिंगेल (नुकसान के बाद दोगुना); SL को और आगे ले जाना; ऑल-इन \"सुनिश्चित\" सेटअप; न्यूनतम आकार बनाम जोखिम% की अनदेखी; दैनिक रोक के बिना व्यापार।"},{"h":"अभ्यास चेकलिस्ट","t":"① जोखिम% लिखा हुआ ② एसएल दूरी से आकार ③ टीपी1/टीपी2/ट्रेल की योजना बनाई गई ④ अधिकतम दैनिक हानि ज्ञात ⑤ पहला पेपर ⑥ जर्नल पीएनएल ईमानदारी से।"}]},{"id":"psych","title":"5 · ट्रेडिंग के लिए मनोविज्ञान","summary":"मानसिकता तय करती है कि बीबी/आरएसआई/फाइब कौशल वास्तविक स्क्रीन पर जीवित रहेंगे या नहीं। FOMO, बदला, अति आत्मविश्वास, भय - इन्हें डेमो जैसे संकेतकों पर प्रशिक्षित करें।","lessons":[{"h":"मनोविज्ञान क्यों मायने रखता है","t":"यदि आप जल्दी प्रवेश करते हैं, एसएल छोड़ते हैं, या बदला लेने वाला व्यापार करते हैं तो एक आदर्श बीबी+आरएसआई योजना विफल हो जाती है। कौशल = व्यवस्था × अनुशासन."},{"h":"भविष्यवाणी पर प्रक्रिया","t":"आपको भविष्य की भविष्यवाणी करने की आवश्यकता नहीं है। आपको नियमों को निष्पादित करने की आवश्यकता है: सेटअप → जोखिम → प्रबंधन → जर्नल। परिणाम अलग-अलग होते हैं; प्रक्रिया नियंत्रणीय है."},{"h":"फोमो","t":"छूट जाने का डर = बीबी/फाइब क्षेत्र से पहले से ही दूर हरी मोमबत्तियों का पीछा करना। नियम: यदि आप प्रविष्टि से चूक गए हैं, तो अगले सेटअप की प्रतीक्षा करें। चार्ट लैब में हमेशा एक और मोमबत्ती होती है।"},{"h":"बदला लेने का व्यापार","t":"हार के बाद, \"अभी इसे वापस जीतने\" की चाहत खातों को नष्ट कर देती है। अनिवार्य कूल-डाउन: चले जाएं, नुकसान का ब्यौरा दें, अगला व्यापार केवल तभी करें जब चेकलिस्ट साफ़ हो।"},{"h":"जीत के बाद अति आत्मविश्वास","t":"लगातार 3 जीतें ≠ आकार 5× बढ़ाएं। जोखिम% निश्चित रखें. जीत की लय तब होती है जब अधिकांश लोग धन संबंधी नियम तोड़ते हैं।"},{"h":"नुकसान के बाद डर","t":"एक लाल दिन के बाद हर वैध सेटअप को छोड़ना भी पूर्वाग्रह है। लिखित योजना पर भरोसा करें; यदि आवश्यक हो तो अस्थायी रूप से आकार कम करें, प्रक्रिया को न छोड़ें।"},{"h":"विश्लेषण पक्षाघात","t":"10 संकेतक असहमत → फ्रीज। सीपीई कोर पर टिके रहें: मोमबत्तियाँ + बीबी + आरएसआई (+ फाइब जोन)। उपकरणों की मात्रा से अधिक गुणवत्ता।"},{"h":"झुकाव और समाचार","t":"समाचार स्पाइक एड्रेनालाईन पर बड़ी लाल मोमबत्तियाँ। संरचना में सुधार होने तक प्रमुख अज्ञात के दौरान फ्लैट को प्राथमिकता दें - अहंकार कार्रवाई चाहता है; योजना धैर्य चाहती है."},{"h":"जर्नल = थेरेपी + डेटा","t":"सीपीई जर्नल में भावना टैग (एफओएमओ, रश, शांत) लिखें। भावनाओं के पैटर्न अकेले पीएनएल की तुलना में तेजी से लीक का खुलासा करते हैं।"},{"h":"लिखित नियम","t":"यदि यह नहीं लिखा है, तो यह कोई नियम नहीं है। उदाहरण: \"केवल बीबी+कैंडल+आरएसआई; जोखिम 1%; -2% दिन के बाद कोई व्यापार नहीं; चेकलिस्ट 20 पेपर तक डेमो।\""},{"h":"पर्यावरण","t":"नींद, भूख और फोन का ध्यान भटकाने से फैसले बदल जाते हैं। थक जाने पर आकार न बढ़ाएं. ट्रेडिंग पुष्ट है - मस्तिष्क की रक्षा करें।"},{"h":"सामाजिक शोर","t":"टेलीग्राम \"सिग्नल\" और प्रचार आपकी योजना को तोड़ देते हैं। सीपीई लर्निंग क्लास + आपका जर्नल > यादृच्छिक युक्तियाँ। समाचार और युक्तियों को संदर्भ के रूप में फ़िल्टर करें, आदेश के रूप में नहीं।"},{"h":"पहचान में बदलाव","t":"यह सोचें कि \"मैं अपनी चेकलिस्ट का पालन करता हूं\" न कि \"मुझे सही होना चाहिए।\" छोटे जोखिम के साथ गलत होना सामान्य है; बड़े जोखिम के प्रति जिद्दी होना वैकल्पिक है।"},{"h":"जिम के रूप में डेमो","t":"भावनाओं का सुरक्षित अभ्यास करने के लिए डेमो/पेपर का उपयोग करें। यदि आप डेमो पर नियमों का पालन नहीं कर सकते हैं, तो लाइव जादुई ढंग से अनुशासन को ठीक नहीं करेगा।"},{"h":"अभ्यास चेकलिस्ट","t":"① क्या मैं शांत हूं? ②चेकलिस्ट पूरी हो गई? ③ जोखिम% अपरिवर्तित? ④ बदला नहीं? ⑤ क्या मैं ईमानदारी से जर्नल करूंगा? यदि कोई नहीं → कोई व्यापार नहीं।"}]},{"id":"signals","title":"6 · सीपीई सिग्नल - अर्थ और क्या करना है","summary":"स्पॉट/फ्यूचर्स/फॉरेक्स डेस्क खरीदें · बेचें · होल्ड + स्कोर दिखाएं। हर प्लेटफ़ॉर्म पर समान इंजन विचार - लेकिन आप केवल उसी प्लेटफ़ॉर्म पर व्यापार करते हैं जिसकी एपीआई कुंजी आपने सहेजी है। यहां बताया गया है कि प्रत्येक सिग्नल का क्या मतलब है और उसके प्रकट होने के बाद सटीक चरण क्या हैं।","lessons":[{"h":"सिग्नल कहां से आते हैं","t":"सीपीई स्कोर बीबी, आरएसआई, फाइबोनैचि, कैंडल स्टिक, ईएमए क्रॉस, एसएमए50, एमएसीडी और गति। स्कोर ≥ +3 → खरीदें। स्कोर ≤ −3 → बेचें। बीच में → पकड़ें। यह एक सहायक रेटिंग है - लाभ का वादा नहीं।"},{"h":"खरीदें संकेत - अर्थ","t":"तेजी का संगम अभी मजबूत है (उदाहरण: कम बीबी उछाल, आरएसआई ओवरसोल्ड टर्न, तेजी मोमबत्ती, गोल्डन क्रॉस, फाइबोनैचि समर्थन)। सुझाए गए टीपी1/टीपी2/एसएल पंक्ति/चार्ट लैब/ट्रेड नाउ पर दिखाई देते हैं।"},{"h":"बेचने का संकेत - मतलब","t":"मंदी का संगम अधिक मजबूत है (ऊपरी बीबी / ओवरबॉट आरएसआई / मंदी की मोमबत्ती / डेथ क्रॉस / फाइब प्रतिरोध)। ऑन स्पॉट, सेल का आमतौर पर मतलब होता है बाहर निकलना/लंबे या छोटे को कम करना, केवल तभी जब आपका बाजार शॉर्ट्स (वायदा/विदेशी मुद्रा) की अनुमति देता है।"},{"h":"होल्ड सिग्नल - मतलब","t":"मिश्रित या कमजोर स्कोर. किसी व्यापार के लिए बाध्य न करें. फ़्लैट सही है. वॉचलिस्ट ★ और स्पष्ट खरीद/बिक्री या बीबी लोअर उम्मीदवार की प्रतीक्षा करें।"},{"h":"स्कोर संख्या","t":"उच्चतर |स्कोर| = उपकरणों के बीच अधिक सहमति. BUY +5, BUY +3 से अधिक मजबूत है - फिर भी आकार से पहले चार्ट लैब मोमबत्तियों पर पुष्टि करें।"},{"h":"बी बी लोअर बोर्ड","t":"बोलिंगर लोअर बैंड को टैग करने वाली जोड़ियों की अलग सूची - लंबे उम्मीदवारों का अभ्यास करें। अभी भी मोमबत्ती + आरएसआई पुष्टि की आवश्यकता है; प्रत्येक निचला स्पर्श एक प्रविष्टि नहीं है।"},{"h":"प्लेटफ़ॉर्म बनाम सिग्नल (महत्वपूर्ण)","t":"बिनेंस, बायबिट, ओकेएक्स, कूकॉइन, बिटगेट, गेट, एमईएक्ससी, क्रैकेन, कॉइनबेस, ओंडा, एफएक्ससीएम, एमटी5, फॉरेक्स डेमो पर सिग्नल गणित एक ही विचार है। आप ऑर्डर कहां भेजते हैं, इसमें क्या परिवर्तन होता है: केवल एपीआई कुंजी/ट्रेड नाउ में चयनित प्लेटफ़ॉर्म। बायबिट पर बायनेन्स BUY नहीं खुलता है।"},{"h":"क्रिप्टो स्पॉट प्लेटफॉर्म","t":"बिनेंस स्पॉट, कॉइनबेस, आदि: खरीदें = उद्धरण के साथ सिक्का खरीदें (उदाहरण के लिए यूएसडीटी)। बेचना = होल्डिंग्स बेचना / लाभ कमाना। न्यूनतम आकार (जैसे ~$11) मायने रखता है। कोई उत्तोलन नहीं."},{"h":"क्रिप्टो फ्यूचर्स प्लेटफॉर्म","t":"बिनेंस फ्यूचर्स, बायबिट, ओकेएक्स, बिटगेट...: खरीदें = लंबी अवधि; बेचना = कम. क्रॉस/आइसोलेटेड + लीवरेज का चयन सावधानी से करें। ट्रेल: टीपी+एसएल ऊपर ट्रेल्स खरीदें; ट्रेल्स नीचे बेचें।"},{"h":"विदेशी मुद्रा प्लेटफार्म","t":"OANDA / FXCM / MT5 / फॉरेक्स डेमो: FX जोड़े (EURUSD…) पर समान खरीदें/बेचें/होल्ड करें लेबल। खरीदें = आधार मुद्रा खरीदें; बेचना = आधार बेचना। सिक्के की मात्रा के बजाय लॉट (जैसे 0.01)। सत्र और समाचार अधिक मायने रखते हैं।"},{"h":"जब कोई खरीदारी दिखाई दे तो यह करें","t":"① पंक्ति खोलें → क्यों / मोमबत्ती / आरएसआई पढ़ें। ② चार्ट लैब पुष्टि (15मी-1एच)। ③ पहले डेमो: अभी ट्रेड करें → टीपी1/टीपी2/एसएल/ट्रेल सेट करें → डेमो/पेपर शुरू करें। ④ एपीआई टेस्ट के बाद ही उस प्लेटफॉर्म पर ओके → छोटा लाइव। ⑤ जर्नल परिणाम."},{"h":"जब कोई विक्रय प्रकट हो - ऐसा करें","t":"① यदि आप लंबे समय तक स्पॉट हैं: टीपी/आंशिक समापन/ट्रेल पर विचार करें - अनदेखा न करें। ② यदि फ्यूचर्स/फॉरेक्स और प्लान शॉर्ट की अनुमति देता है: चार्ट लैब की पुष्टि करें, फिर एसएल के साथ पेपर/लाइव शॉर्ट की पुष्टि करें। ③ यदि कल होल्ड बेहतर था, तो फ्लिप आकार का बदला न लें।"},{"h":"जब होल्ड प्रकट हो - ऐसा करें","t":"कोई नई मैन्युअल प्रविष्टि नहीं. स्कैन करते रहें. ★ वॉचलिस्ट जोड़ें. स्टडी लर्निंग क्लास/चार्ट लैब। यदि पहले से ही कोई व्यापार चल रहा हो तो खुली पोजीशन को ट्रेल के साथ सुरक्षित रखें।"},{"h":"ऑटो ट्रेड + सिग्नल","t":"ऑटो बाय तभी खुल सकता है जब बीबी लोअर + मजबूत स्कोर नियम आपके सहेजे गए ऑटो कॉन्फिगरेशन से मेल खाते हों। फिर भी पहले डेमो-टेस्ट ऑटो। लाइव ऑटो = वास्तविक जोखिम - निकासी बंद, छोटा आकार।"},{"h":"सूचनाएं","t":"सिग्नल टोस्ट खरीदें जो आपकी भाषा का पालन करें। उन्हें डेस्क खोलने के लिए अलर्ट के रूप में मानें - न कि बाज़ार के आदेशों के रूप में।"},{"h":"क्या नहीं करना है","t":"प्रत्येक खरीदारी बिना चार्ट के न करें। बायबिट पर बिनेंस कुंजी का उपयोग न करें। एसएल को न छोड़ें। एक हरी झंडी के बाद आकार न बढ़ाएं। होल्ड को \"लगभग खरीदें\" के रूप में व्यापार न करें।"},{"h":"त्वरित कार्रवाई कार्ड","t":"सिग्नल → चार्ट लैब → जोखिम % → TP1/TP2/SL → डेमो पेपर → जर्नल → (बाद में) मिलान प्लेटफ़ॉर्म कुंजी पर लाइव।"}]},{"id":"forex_sig","title":"7 · विदेशी मुद्रा संकेत - अर्थ और क्या करें","summary":"फॉरेक्स डेस्क एफएक्स जोड़ियों पर समान खरीदें/बेचें/होल्ड रेटिंग का उपयोग करता है। जानें कि विदेशी मुद्रा सिग्नल क्रिप्टो से कैसे भिन्न हैं, और सिग्नल → पेपर → लाइव ब्रोकर से सटीक चरण।","lessons":[{"h":"विदेशी मुद्रा डेस्क संकेत","t":"EURUSD, GBPUSD, USDJPY... क्रिप्टो की तरह खरीदें/बेचें/होल्ड करें + स्कोर प्राप्त करें। चार्ट, मनोविज्ञान पाठ और सुझाए गए स्तरों के लिए एक पंक्ति पर क्लिक करें।"},{"h":"विदेशी मुद्रा पर खरीदें - अर्थ","t":"आधार मुद्रा खरीदें (उदाहरण के लिए EURUSD खरीदें = EUR बनाम USD खरीदें)। कीमत बढ़ने की उम्मीद है. चार्ट लैब फॉरेक्स अंतराल का उपयोग करें जिसका आप अभ्यास करते हैं (15मी/30मी/1एच)।"},{"h":"विदेशी मुद्रा पर बेचें - मतलब","t":"आधार बेचें (जोड़ी छोटी करें)। कीमत कम होने की उम्मीद है. एसएल को हमेशा संरचना/ऊपरी बैंड विचार के ऊपर सेट करें।"},{"h":"विदेशी मुद्रा पर पकड़ बनाए रखें","t":"कोई स्पष्ट किनारा नहीं - छोड़ें। विशेष रूप से बड़ी खबरों (एनएफपी, सीपीआई, केंद्रीय बैंक) से पहले होल्ड/फ्लैट को प्राथमिकता दें।"},{"h":"विदेशी मुद्रा डेमो दरें मंच","t":"कोई एपीआई कुंजी नहीं. अभ्यास चार्ट + केवल पेपर। OANDA/FXCM/MT5 लाइव से पहले लर्निंग क्लास अभ्यास के लिए बिल्कुल सही।"},{"h":"OANDA सिग्नल → क्रिया","t":"① विदेशी मुद्रा डेस्क खरीदें/बेचें। ② चार्ट लैब पुष्टि करें। ③ एपीआई कुंजी → ओंडा टोकन + खाता आईडी → परीक्षण। ④ पहले सीपीई में डेमो पेपर। ⑤ टीपी/एसएल/ट्रेल के साथ छोटे लाइव लॉट (0.01 मानसिकता)।"},{"h":"एफएक्ससीएम/एमटी5","t":"वही सिग्नल रीडिंग. एपीआई कुंजी के अंतर्गत उस ब्रोकर के क्रेडेंशियल को कनेक्ट करें। कुंजी/ब्रिज सेट होने तक सिग्नल आपके लिए MT5 को ऑटो-लॉगिन नहीं करता है - टेस्ट ओके होने तक पेपर का अभ्यास करें।"},{"h":"सत्र","t":"लंदन-एनवाई ओवरलैप अक्सर बड़ी कंपनियों को अधिक प्रभावित करता है। एशिया शांत हो सकता है - होल्ड सामान्य और स्वस्थ है।"},{"h":"प्रसार एवं समाचार","t":"समाचारों के इर्द-गिर्द प्रसार व्यापक हो जाता है - एक अच्छी तकनीकी खरीदारी अभी भी खराब हो सकती है। समाचार और युक्तियाँ जांचें; स्पाइक के बाद मोमबत्ती बंद होने की प्रतीक्षा करें।"},{"h":"बहुत सारे बनाम क्रिप्टो मात्रा","t":"विदेशी मुद्रा आकार = लॉट, उसी तरह यूएसडीटी काल्पनिक नहीं। जोखिम % अभी भी नियम: व्यापक एसएल → छोटे लॉट।"},{"h":"फॉरेक्स पर बीबी लोअर","t":"समान विचार: निचले बैंड के पास जोड़ी + हैमर + आरएसआई बढ़ना = लंबे समय तक अध्ययन का अभ्यास करना। उच्च टीएफ पूर्वाग्रह (4एच/दैनिक) की पुष्टि करें।"},{"h":"जब विदेशी मुद्रा खरीदें सक्रिय होती है - चरण","t":"①क्यों पढ़ें. ② उच्च TF पूर्वाग्रह ठीक है? ③ बाती/संरचना से परे एसएल को चिह्नित करें। ④ कागज का व्यापार। ⑤ यदि लाइव ब्रोकर तैयार है → छोटा आकार + निशान। ⑥ जर्नल सत्र (लंदन/एनवाई) + भावना।"},{"h":"जब विदेशी मुद्रा बिक्री सक्रिय होती है - चरण","t":"① मध्य-समाचार स्पाइक की पुष्टि न करें। ② चार्ट लैब मंदी मोमबत्ती। ③ पेपर छोटा या लंबा बंद करें। ④ यदि छोटा हो तो नीचे जाएँ। ⑤ चूक के बाद लॉट दोगुना न करें।"},{"h":"विदेशी मुद्रा बनाम क्रिप्टो अंतर","t":"क्रिप्टो 24/7; फॉरेक्स में सत्र होते हैं। क्रिप्टो न्यूनतम $ अक्सर; विदेशी मुद्रा लॉट + पिप मूल्य। क्रिप्टो कई विकल्प सहसंबद्ध; सीखने के लिए विदेशी मुद्रा प्रमुख क्लीनर।"},{"h":"अभ्यास चेकलिस्ट (एफएक्स)","t":"① जोड़ी प्रमुख? ② सत्र ठीक है? ③ समाचार स्पष्ट? ④ सिग्नल खरीदने/बेचने पर रोक नहीं? ⑤ चार्ट पुष्टि करें? ⑥ जोखिम %? ⑦ पेपर → जर्नल → लाइव ब्रोकर कुंजी केवल तैयार होने पर।"}]},{"id":"fomo","title":"8 · FOMO और भावनात्मक अनुशासन","summary":"FOMO, बदला, लालच और भय वास्तविक खाते के हत्यारे हैं - संकेतक नहीं। ट्रिगर्स, शारीरिक संकेतों और सटीक नियमों को जानें जो आवेग ट्रेडों को आपके खाते से बाहर रखते हैं।","lessons":[{"h":"FOMO वास्तव में क्या है?","t":"FOMO = एक चाल छूट जाने का डर जो पहले से ही आपके क्षेत्र से बहुत दूर है। यह आपको खराब कीमत और उचित एसएल के बिना देर से प्रवेश करने को मजबूर करता है। जिस मोमबत्ती को आपने \"छूटा\" वह सूचना है, हानि नहीं।"},{"h":"तीन FOMO ट्रिगर","t":"① चार्ट पर एक बड़ी हरी या लाल मोमबत्ती। ② लाभ दर्शाने वाला कोई मित्र या टेलीग्राम पोस्ट। ③ एक समाचार शीर्षक. प्रविष्टि पर ध्यान देने से पहले ट्रिगर पर ध्यान दें।"},{"h":"शरीर के लक्षण","t":"तेज़ दिल की धड़कन, स्क्रीन की ओर झुकना, अपनी चेकलिस्ट को छोड़कर बाजार-अभी खरीदें पर क्लिक करने की इच्छा। यदि आप इन्हें महसूस करते हैं, तो टैब बंद करें और एक मोमबत्ती तक प्रतीक्षा करें।"},{"h":"\"पहले से ही चल रहा है\" नियम","t":"यदि कीमत आपकी नियोजित प्रविष्टि से लगभग 1 एटीआर से अधिक बढ़ गई है, तो व्यापार समाप्त हो गया है। बीबी मिड/फाइब पर पुलबैक की प्रतीक्षा करें या इसे छोड़ दें। हमेशा एक और सेटअप होता है."},{"h":"हरी मोमबत्ती का जाल","t":"जिस मारुबोज़ू की आपने योजना नहीं बनाई थी वह एक पीछा है, प्रवेश नहीं। देर से प्रविष्टियों का सबसे बुरा प्रतिफल होता है: जोखिम क्योंकि स्टॉप बहुत दूर समाप्त होता है।"},{"h":"बदला लेने का व्यापार","t":"हार के बाद दिमाग अब उसे वापस जीतना चाहता है। नियम: नुकसान के बाद 15-30 मिनट तक कोई नई प्रविष्टि नहीं, और केवल तभी जब चेकलिस्ट साफ़ हो। बाज़ार का आप पर कुछ भी बकाया नहीं है।"},{"h":"ट्रिगर खींचने का डर","t":"विपरीत समस्या: एक आदर्श सेटअप प्रकट होता है और आप रुक जाते हैं। प्रक्रिया को साबित करने के लिए एक छोटे डेमो आकार का उपयोग करें, और मोमबत्ती प्रकट होने से पहले अपना आकार तय करें ताकि निर्णय पहले ही हो जाए।"},{"h":"जीत के बाद लालच","t":"दो हरे व्यापार आपको अजेय महसूस कराते हैं, फिर आपका आकार दोगुना हो जाता है। कम से कम 20 ट्रेडों के लिए जोखिम% निश्चित रखें; जीत की धारियाँ मतलब-वापसी।"},{"h":"बोरियत व्यापार","t":"फ़्लैट एक स्थिति है. यदि कोई A+ सेटअप मौजूद नहीं है, तो कुछ न करें। बोरियत का व्यापार छद्म रूप से FOMO है।"},{"h":"स्क्रीन-टाइम अनुशासन","t":"चार्ट को घूरने के बजाय एक दिन में दो या तीन स्कैन विंडो सेट करें। कम निर्णयों का अर्थ है कम आवेगपूर्ण निर्णय।"},{"h":"भावनात्मक पत्रिका","t":"प्रत्येक व्यापार को शांत/जल्दी/FOMO/बदला के रूप में टैग करें। 20 ट्रेडों के बाद आपके लीक का पैटर्न स्पष्ट हो जाता है।"},{"h":"अनुष्ठान रीसेट करें","t":"हानि या FOMO स्लिप के बाद: खड़े हो जाएं, 10 धीमी सांसें लें, जो हुआ उसके बारे में एक वाक्य लिखें, फिर एक घंटे के लिए रुकें या सामान्य जोखिम के आधे पर जारी रखें।"},{"h":"अभ्यास चेकलिस्ट","t":"① शांत शरीर? ② ट्रिगर पर ध्यान दिया गया? ③ मेरे क्षेत्र में सेटअप? ④ SL पहले लिखा गया? ⑤ जोखिम % अपरिवर्तित? ⑥ बदला नहीं? कोई नहीं → कोई व्यापार नहीं।"}]},{"id":"risk_deep","title":"9 · जोखिम और धन प्रबंधन - गहरा","summary":"वह गणित जो किसी खाते को जीवित रखता है: निश्चित-आंशिक आकार, आर-गुणक, ड्रॉडाउन गणित, सहसंबंध गर्मी, और दैनिक स्टॉप। ट्रेडिंग को संख्याओं द्वारा संचालित व्यवसाय में बदलें।","lessons":[{"h":"निश्चित-आंशिक जोखिम","t":"प्रति विचार इक्विटी का एक निश्चित % (0.5-1%) जोखिम उठाएं। आकार स्टॉप दूरी का परिणाम है, पहले कभी नहीं चुना गया। वाइड एसएल → छोटा आकार; तंग एसएल → बड़ा आकार; डॉलर का जोखिम वही रहता है।"},{"h":"आकार देने का सूत्र","t":"आकार = (इक्विटी × जोखिम%) ÷ |प्रवेश - रुकें| उदाहरण: $1000 × 1% = $10 जोखिम। प्रवेश 100, स्टॉप 98 → दूरी 2% → आकार 10 ÷ 0.02 = अनुमानित $500।"},{"h":"आर-गुणकों में सोचो","t":"प्रति ट्रेड जोखिम 1R। एक 2R विजेता दो हार के लिए भुगतान करता है। 20 से अधिक ट्रेडों में अपने औसत आर को ट्रैक करें - यह आपकी वास्तविक बढ़त है, जीत की दर नहीं।"},{"h":"इनाम : जोखिम","t":"प्रवेश से पहले कम से कम 1.5R क्षमता का लक्ष्य रखें। उससे नीचे, इसे छोड़ दें जब तक कि आपकी जीत की दर बहुत अधिक न हो।"},{"h":"ड्राडाउन गणित","t":"-50% गिरावट को पुनर्प्राप्त करने के लिए +100% की आवश्यकता होती है। हार का सिलसिला सामान्य है: यहां तक ​​कि 60% जीत-दर प्रणाली में भी 5+ हार का दौर होता है। छोटा सा जोखिम स्ट्रीक को बचाए रखता है।"},{"h":"दैनिक पड़ाव","t":"कठिन नियम: एक दिन में -2% इक्विटी (या लगातार 2-3 हानि) के बाद ट्रेड खोलना बंद कर दें। सीमा के बाद बदला सत्र खाते के हत्यारे हैं।"},{"h":"साप्ताहिक और मासिक सीमा","t":"सप्ताह (उदाहरण के लिए −5%) और महीने को भी सीमित करें। हिट होने पर, डेमो पर छोड़ें, जर्नल की समीक्षा करें, फिर क्लीन रन के बाद ही आकार वापस लें।"},{"h":"खुला ताप","t":"सभी खुले ट्रेडों में कुल जोखिम लगभग 3% या उससे कम रहना चाहिए। पाँच सहसंबद्ध विकल्प एक शर्त हैं, पाँच नहीं - सहसंबद्ध एक्सपोज़र को एक साथ गिनें।"},{"h":"स्थान का आकार निर्धारण","t":"स्पॉट में न्यूनतम अनुमानित है। यदि एक्सचेंज न्यूनतम आपके 1% से अधिक जोखिम उठाएगा, तो व्यापार छोड़ दें - जोखिम को कभी भी बढ़ाएँ नहीं।"},{"h":"वायदा आकार","t":"उत्तोलन से मार्जिन बदलता है, जोखिम नहीं। जोखिम अभी भी प्रवेश है - स्टॉप × आकार। सीखते समय कम उत्तोलन का उपयोग करें और पृथक मार्जिन को प्राथमिकता दें।"},{"h":"विदेशी मुद्रा का आकार","t":"जोखिम = लॉट × पिप-वैल्यू × स्टॉप-पिप्स। बहुत सारे के लिए हल करें. रफ गाइड: 0.01 लॉट ≈ $0.10 प्रति पिप; 20-पिप स्टॉप में $1000 ($10) का 1% जोखिम होता है → 10 ÷ 0.10 ÷ 20 = 0.05 लॉट।"},{"h":"स्केलिंग आउट","t":"बाकी को जोखिम मुक्त बनाने के लिए टीपी1 पर लगभग 50% की छूट लें, फिर आगे बढ़ें। यह एक अच्छे व्यापार को कम तनाव वाले धावक में बदल देता है।"},{"h":"कंपाउंडिंग बनाम फिक्स्ड","t":"वर्तमान इक्विटी (कंपाउंडिंग) का एक निश्चित % जोखिम में डालें। अपने जोखिम को सर्वकालिक उच्च खाता आकार पर निर्धारित न करें।"},{"h":"आर में फीस और फिसलन","t":"आर से शुल्क घटाएं। 0.5% स्कैल्प के मुकाबले 0.2% शुल्क किनारे को मिटा सकता है - क्लीनर स्विंग को प्राथमिकता दें।"},{"h":"\"कोई रोक नहीं, कोई व्यापार नहीं\" कानून","t":"यदि आप तार्किक स्टॉप को परिभाषित नहीं कर सकते हैं, तो आप अपने जोखिम को नहीं जानते हैं, इसलिए कोई आकार नहीं है, इसलिए कोई व्यापार नहीं है।"},{"h":"मार्टिंगेल विरोधी","t":"हानि के बाद कभी भी दोगुना न करें। किसी सिद्ध प्रक्रिया के कई लाभदायक, अनुशासित सप्ताहों के बाद ही आकार बढ़ाएं - और तब भी धीरे-धीरे।"},{"h":"अभ्यास चेकलिस्ट","t":"① इक्विटी ज्ञात ② जोखिम % लिखा ③ स्टॉप परिभाषित ④ स्टॉप से ​​आकार ⑤ इनाम ≥ 1.5आर ⑥ दैनिक स्टॉप ज्ञात ⑦ सहसंबद्ध गर्मी की गणना।"}]},{"id":"sl_tp","title":"10 · स्टॉप लॉस और टेक प्रॉफिट में महारत","summary":"एसएल को वहां रखें जहां बाजार आपको गलत साबित करता है, चरणों में लाभ लें, और स्टॉप को ट्रेल करें ताकि विजेता दौड़ सके - बिल्कुल वही जो सीपीई मल्टी-टीपी और ट्रेलिंग एसएल के साथ करता है।","lessons":[{"h":"SL एक निर्णय है, संख्या नहीं","t":"जहां विचार अमान्य है वहां रुकें (स्विंग लो, बाती या संरचना के नीचे), यादृच्छिक डॉलर दूरी पर नहीं। आप जानकारी खरीद रहे हैं: यदि कीमत यहां जाती है, तो मेरा कारण गलत है।"},{"h":"संरचना रुक जाती है","t":"लंबा: एसएल स्विंग लो या लोअर-बैंड बाती के ठीक नीचे। लघु: ऊंचे झूले के ठीक ऊपर। फैलाव और बाती के शोर के लिए एक छोटा बफर दें, लगभग 0.1-0.3%।"},{"h":"अस्थिरता रुक जाती है","t":"व्यापक बाज़ारों को व्यापक स्टॉप की आवश्यकता है। स्टॉप को आकार देने के लिए एटीआर या बाती की लंबाई का उपयोग करें, फिर स्थिति को छोटा करें ताकि डॉलर का जोखिम समान रहे।"},{"h":"एक निश्चित-डॉलर एसएल विफल क्यों होता है?","t":"बीटीसी पर $10 का स्टॉप और EURUSD पर $10 का स्टॉप पूरी तरह से अलग जोखिम हैं। दूरी को % में मापा जाना चाहिए, डॉलर में नहीं।"},{"h":"एंटी स्टॉप-हंट बफर","t":"सीपीई एक बाती स्पर्श को नजरअंदाज करता है: इसे बंद करने से पहले लगातार दो उल्लंघनों और एक छोटे बफर (0.15%) की आवश्यकता होती है। यह आपके स्टॉप का शिकार करने से आने वाले शोर को रोकता है।"},{"h":"चरणों में लाभ उठाएं","t":"कभी भी एक कीमत पर 100% बंद न करें। स्केल आउट: टीपी1 किताबें भाग, फिर टीपी2/ट्रेल बाकी हिस्से की सवारी करता है इसलिए एक बड़ा कदम कई हारे हुए लोगों के लिए भुगतान कर सकता है।"},{"h":"मल्टी-टीपी स्तर","t":"सीपीई आपको जितनी जरूरत हो उतने टीपी स्तर जोड़ने की सुविधा देता है, प्रत्येक का अपना करीबी% होता है। उदाहरण: टीपी1 40%, टीपी2 30%, टीपी3 30% - या टीपी1 लें और बाकी का पता लगाएं।"},{"h":"स्टॉप का पीछा करना","t":"टीपी1 के बाद स्टॉप को ब्रेकइवेन पर ले जाएं; टीपी2 के बाद इसे टीपी1 पर ले जाएं। स्टॉप को कीमत का अनुसरण करने दें ताकि धावक के जारी रहने तक खुला लाभ सुरक्षित रहे।"},{"h":"पथ का चयन %","t":"एक तंग राह लाभ को तेजी से बंद कर देती है लेकिन जल्दी निकल जाती है; एक चौड़ा रास्ता सांस लेता है लेकिन कुछ वापस देता है। क्रिप्टो के लिए लगभग 1-2% प्रारंभ करें और इसे स्थिति संपादन मोडल में ट्यून करें।"},{"h":"धावक","t":"जब कीमत एक मजबूत प्रवृत्ति में बैंड पर चलती है, तो टीपी 2 पर सब कुछ लेने के बजाय लक्ष्य और निशान का विस्तार करें। इस प्रकार एक व्यापार पूरे सप्ताह के लिए भुगतान करता है।"},{"h":"आंशिक-बंद बटन","t":"मैन्युअल नियंत्रण के लिए पोजीशन में 50% / 100% क्लोज बटन का उपयोग करें, या ऑटो क्लोज को योजना के अनुसार टीपी / एसएल को प्रबंधित करने दें।"},{"h":"बराबरी का जाल","t":"टीपी1 से पहले, एसएल को बहुत जल्दी ब्रेक ईवन में न ले जाएं - सामान्य पुलबैक आपको अच्छे ट्रेडों से बाहर कर देगा।"},{"h":"हार के पड़ाव को कभी भी चौड़ा न करें","t":"एसएल को जगह देने के लिए उसे और दूर ले जाना इस प्रकार है कि कैसे छोटे-छोटे नुकसान अकाउंट किलर बन जाते हैं। प्रवेश से पहले आपने जो स्टॉप निर्धारित किया है वह स्टॉप है।"},{"h":"समय रुक गया","t":"यदि कोई व्यापार कई मोमबत्तियों के लिए कुछ नहीं करता है जबकि स्पष्ट रूप से बेहतर सेटअप बनता है, तो फ्लैट को बंद करना और जोखिम को फिर से तैनात करना एक वैध निकास है।"},{"h":"अभ्यास चेकलिस्ट","t":"① अमान्य होने पर SL, यादृच्छिक नहीं ② विक्स के लिए बफर ③ TP1 आंशिक रूप से नियोजित ④ TP1 के बाद ट्रेल ⑤ SL को कभी चौड़ा न करें ⑥ विजेता को चलने दें।"}]},{"id":"plan_journal","title":"11 · व्यापार योजना एवं जर्नलिंग","summary":"एक लिखित योजना व्यापार को जुए से एक प्रक्रिया में बदल देती है। एक पेज की योजना, प्री-ट्रेड चेकलिस्ट और जर्नल कैसे बनाएं ताकि आपकी लीक दिखाई दे सके, सीखें।","lessons":[{"h":"योजना क्यों लिखें?","t":"यदि यह नहीं लिखा है तो यह कोई नियम नहीं है। एक योजना तनाव के तहत लाइव निर्णय लेने को हटा देती है और आपके परिणामों को मापने योग्य बनाती है।"},{"h":"एक पेज की योजना","t":"जोड़ी, बाजार, सेटअप (बीबी + आरएसआई + कैंडल + फाइब जोन), दिशा, प्रवेश, एसएल, टीपी1/टीपी2, आकार (एसएल से) और अधिकतम दैनिक हानि। यदि कोई पंक्ति रिक्त है → कोई व्यापार नहीं।"},{"h":"प्री-ट्रेड चेकलिस्ट","t":"उच्च-TF पूर्वाग्रह? · मेरे क्षेत्र में सेटअप? · मोमबत्ती की पुष्टि? · आरएसआई सहमत हैं? · एसएल लिखा है? · जोखिम %? · इनाम ≥ 1.5R? · शांत? सभी हाँ → व्यापार।"},{"h":"सत्र पूर्व दिनचर्या","t":"उच्च समय-सीमा, प्रमुख स्तरों और समाचारों की जाँच करें। सत्र से पहले आज की दो या तीन घड़ी जोड़ी लिखें - मोमबत्ती फूटने के बाद नहीं।"},{"h":"क्या जर्नल करें","t":"प्रतीक, पक्ष, प्रवेश, निकास, आकार, आर, कारण, समय सीमा, सत्र और एक भावना टैग। सीपीई जर्नल पी/एल और कारणों को स्वचालित रूप से बचाता है; अपने स्वयं के नोट्स जोड़ें."},{"h":"क्यों जर्नल करें","t":"आपने जो देखा (सेटअप) और जो महसूस किया उसे रिकॉर्ड करें (शांत/FOMO/जल्दी)। संदर्भ के बिना परिणाम कुछ नहीं सिखाता।"},{"h":"ट्रैक आर, जीत नहीं","t":"समान जीत दर वाले दो व्यापारियों के विपरीत परिणाम हो सकते हैं। औसत आर और अधिकतम ड्रॉडाउन जीत% से अधिक मायने रखता है।"},{"h":"स्क्रीनशॉट की आदत","t":"प्रत्येक व्यापार से पहले और बाद में चार्ट सहेजें। 20 स्क्रीनशॉट की समीक्षा करने से आपकी बढ़त और आपकी लीक किसी भी संकेतक से अधिक तेज दिखाई देती है।"},{"h":"साप्ताहिक समीक्षा","t":"सप्ताह में एक बार अपने ट्रेडों, औसत आर, सर्वोत्तम और सबसे खराब सेटअप और नियम तोड़ने की गणना करें। अगले सप्ताह ठीक करने के लिए एक रिसाव चुनें।"},{"h":"लीक को टैग करें","t":"सामान्य टैग: देर से प्रवेश, कोई एसएल नहीं, बड़ा आकार, स्थानांतरित एसएल, बदला, बोरियत। जब कोई टैग दोहराया जाता है, तो उसे एक कठिन नियम में बदल दें।"},{"h":"क्या लॉग नहीं करना है","t":"केवल विजेताओं को लॉग न करें. घाटा ही डेटा है. केवल जीत का जर्नल एक ब्रोशर है, जर्नल नहीं।"},{"h":"डेमो की योजना बनाएं → लाइव चरण","t":"वास्तविक धन को जोखिम में डालने से पहले सकारात्मक औसत आर के साथ ट्रेडों की एक निर्धारित संख्या के लिए डेमो पर योजना को साबित करें - फिर आधे आकार से शुरू करें।"},{"h":"अभ्यास चेकलिस्ट","t":"① प्रविष्टि से पहले लिखी गई योजना ② चेकलिस्ट उत्तीर्ण ③ जर्नल प्रविष्टि + भावना ④ साप्ताहिक समीक्षा ⑤ एक लीक ठीक किया गया।"}]},{"id":"leverage","title":"12 · उत्तोलन, मार्जिन और परिसमापन","summary":"उत्तोलन लाभ जितनी तेजी से हानि को कई गुना बढ़ा देता है। मार्जिन, परिसमापन, पृथक बनाम क्रॉस मार्जिन और सुरक्षा नियमों को जानें जो एक व्यापार को खाते को ख़त्म करने से रोकते हैं।","lessons":[{"h":"उत्तोलन क्या है","t":"उत्तोलन आपको कम मार्जिन के साथ बड़ी स्थिति को नियंत्रित करने देता है। यह लाभ और हानि दोनों को बढ़ाता है - यह आपकी बढ़त को नहीं बढ़ाता है।"},{"h":"मार्जिन बनाम जोखिम","t":"मार्जिन वह जमा राशि है जिसे एक्सचेंज लॉक करता है। जोखिम प्रवेश है - स्टॉप × आकार। उत्तोलन मार्जिन बदलता है, आपका डॉलर जोखिम कभी नहीं।"},{"h":"परिसमापन","t":"यदि नुकसान आपके मार्जिन को खा जाता है, तो एक्सचेंज स्थिति को बलपूर्वक बंद कर देता है (परिसमापन), अक्सर सबसे खराब समय पर। अपने स्टॉप को परिसमापन मूल्य से दूर रखें।"},{"h":"पृथक बनाम क्रॉस","t":"पृथक उस एक स्थिति के मार्जिन के नुकसान को सीमित करता है। क्रॉस पूरे वॉलेट बैलेंस का उपयोग करता है - शुरुआती लोगों के लिए अधिक खतरनाक। सीखते समय पृथक रहना पसंद करें।"},{"h":"सुरक्षित उत्तोलन","t":"कम उत्तोलन (2-5x) और उचित स्टॉप, बिना रुके 50x की तुलना में कहीं अधिक सुरक्षित है। स्टॉप, लीवरेज नंबर नहीं, आपकी सुरक्षा है।"},{"h":"परिसमापन-दूरी नियम","t":"जांचें कि आपका एसएल परिसमापन मूल्य के ठीक अंदर बैठता है। यदि वे करीब हैं, तो आरामदायक जगह होने तक आकार कम करें।"},{"h":"उत्तोलन खराब प्रविष्टि को ठीक नहीं करता है","t":"खराब प्रविष्टि पर उच्च उत्तोलन तेजी से कम हो जाता है। पहले सेटअप ठीक करें, फिर उसका आकार बदलें."},{"h":"फंडिंग और फीस","t":"सतत वायदा समय के साथ फंडिंग चार्ज करता है। लीवरेज्ड पर्पस ब्लीड फंडिंग पर लंबे समय तक टिके रहना - आकार और समय को ध्यान से देखने का एक और कारण।"},{"h":"स्पॉट बनाम फ्यूचर्स","t":"स्पॉट को खत्म नहीं किया जा सकता (सिक्के का मालिक आपका है)। वायदा शून्य तक जा सकता है और जा सकता है। फ़्यूचर्स का उपयोग केवल लिखित योजना और पृथक मार्जिन के साथ करें।"},{"h":"उत्तोलन के तहत आकार देना","t":"स्टॉप दूरी से आकार की गणना करें, फिर जांचें कि परिणामी मार्जिन किफायती है। पहले कभी भी उत्तोलन न चुनें।"},{"h":"\"एक व्यापार\" परीक्षण","t":"प्रवेश करने से पहले पूछें: यदि यह रुक जाता है, तो क्या यह कंधे उचकाने की क्रिया है या आपदा? यदि यह श्रग नहीं है, तो इसका आकार बहुत बड़ा है।"},{"h":"अभ्यास चेकलिस्ट","t":"① पृथक सेट ② कम उत्तोलन ③ परिसमापन मूल्य के अंदर एसएल ④ स्टॉप से ​​आकार ⑤ क्या मैं यहां पूर्ण नुकसान से बच सकता हूं? हाँ → व्यापार।"}]},{"id":"practice","title":"13 · नियमित एवं बैकटेस्टिंग का अभ्यास करें","summary":"लाइव से पहले डेमो पर कौशल का निर्माण होता है। दोहराने योग्य अभ्यास लूप सीखें, चार्ट को स्क्रॉल करके \"बैकटेस्ट\" कैसे करें, और सुरक्षित रूप से वास्तविक धन की ओर कैसे बढ़ें।","lessons":[{"h":"डेमो जिम है","t":"शून्य जोखिम के साथ प्रक्रिया और आपकी भावनाओं का पूर्वाभ्यास करने के लिए पेपर/डेमो मौजूद है। यदि आप डेमो पर नियमों का पालन नहीं कर सकते हैं, तो लाइव इसे जादुई तरीके से ठीक नहीं करेगा।"},{"h":"अभ्यास पाश","t":"एक सेटअप चुनें (उदाहरण के लिए बीबी लोअर + हैमर + आरएसआई टर्न)। चार्ट पर 20 ऐतिहासिक उदाहरण अंकित करें। प्रविष्टि/एसएल/टीपी को परिभाषित करें। परिणाम रिकॉर्ड करें. दोहराना।"},{"h":"मैनुअल बैकटेस्टिंग","t":"चार्ट लैब में पीछे स्क्रॉल करें, भविष्य छुपाएं और प्रत्येक सिग्नल को हाथ से चिह्नित करें। यह पैटर्न पहचान को प्रशिक्षित करता है और आपको स्वयं को मूर्ख बनाने से रोकता है।"},{"h":"नमूना आकार","t":"दस ट्रेडों का कोई मतलब नहीं है। किसी सेटअप का मूल्यांकन करने से पहले उसके 30-50 रिकॉर्ड किए गए ट्रेडों का लक्ष्य रखें।"},{"h":"डेमो पर अग्रेषित परीक्षण","t":"हाथ से मार्किंग करने के बाद, उसी सेटअप को दो से चार सप्ताह तक सॉफ्टवेयर के सिग्नल के साथ डेमो पर लाइव चलाएं। वास्तविक भरावों और भावनाओं की तुलना बैकटेस्ट से करें।"},{"h":"एक समय में एक सेटअप","t":"एक साथ पांच प्रणालियों का परीक्षण न करें. एक किनारे पर महारत हासिल करें, फिर दूसरा जोड़ें।"},{"h":"दिनचर्या छोटी रखें","t":"20 मिनट की दैनिक दिनचर्या (स्कैन, मार्क, जर्नल, समीक्षा) छह घंटे के यादृच्छिक चार्ट-घूरने को मात देती है।"},{"h":"जीने के लिए स्नातक","t":"मानदंड: 30+ से अधिक डेमो ट्रेडों पर सकारात्मक औसत आर, नियमों का पालन, कोई बदला लेने वाला एपिसोड नहीं। फिर आधे आकार में लाइव शुरू करें और धीरे-धीरे स्केल करें।"},{"h":"स्केल-अप नियम","t":"लाभदायक, अनुशासित सप्ताहों की एक निश्चित संख्या के बाद ही आकार बढ़ाएं - एक बड़ी जीत के बाद कभी नहीं।"},{"h":"कब पीछे हटना है","t":"दैनिक या साप्ताहिक हानि सीमा तक पहुंचें, या बार-बार नियम तोड़ने पर ध्यान दें → डेमो पर वापस लौटें और जारी रखने से पहले अनुशासन का पुनर्निर्माण करें।"},{"h":"ट्रैक प्रक्रिया मेट्रिक्स","t":"लॉग चेकलिस्ट पास-दर, प्रति सप्ताह नियम-विच्छेद और औसत आर। ये एकल पी/एल संख्या से बेहतर वृद्धि की भविष्यवाणी करते हैं।"},{"h":"सीपीई अभ्यास पथ","t":"लर्निंग क्लास → चार्ट लैब (मार्क सेटअप) → पेपर ट्रेड → जर्नल समीक्षा → डेमो पर सिग्नल डेस्क → मिलान प्लेटफ़ॉर्म कुंजी पर छोटा लाइव।"},{"h":"अभ्यास चेकलिस्ट","t":"① एक सेटअप चुना गया ② 30 उदाहरण चिह्नित ③ डेमो फॉरवर्ड टेस्ट ④ जर्नल + समीक्षा ⑤ सकारात्मक आर → आधा आकार लाइव।"}]},{"id":"volatility","title":"14 · अस्थिरता और मार्टिंगेल","summary":"बाजार की अस्थिरता को कैसे पढ़ा जाए (कीमत क्यों बदल रही है), इसे प्रत्येक सिग्नल में कारण रेखा के रूप में कैसे जोड़ा जाता है, और वैकल्पिक मार्टिंगेल सीढ़ी कैसे काम करती है - साथ ही यह लापरवाही से उपयोग किए जाने पर खाता खोने का सबसे तेज़ तरीका क्यों है।","lessons":[{"h":"अस्थिरता का क्या मतलब है","t":"अस्थिरता यह है कि कीमत कितनी बढ़ रही है - किस दिशा में नहीं। उच्च अस्थिरता = चौड़ी मोमबत्तियाँ और तेज़ उतार-चढ़ाव। कम अस्थिरता = एक शांत, संकीर्ण सीमा। एक ही सेटअप में प्रत्येक में बहुत अलग विश्वसनीयता होती है।"},{"h":"सीपीई अस्थिरता पढ़ना","t":"प्रत्येक सिग्नल अब औसत कैंडल रेंज और बोलिंगर बैंड की चौड़ाई को मापता है, फिर उनकी तुलना उस जोड़ी के अपने हालिया सामान्य से करता है। आपको निम्न/सामान्य/उच्च/अत्यधिक प्लस एक सामान्य भाषा में कारण पंक्ति मिलती है - बाजार परिवर्तन के लिए \"क्यों\", संकेत के साथ दिखाया गया है।"},{"h":"अत्यधिक अस्थिरता = डाउनग्रेड","t":"जब टेप अत्यधिक होता है, तो एक ताजा मजबूत सिग्नल को चेतावनी में डाउनग्रेड कर दिया जाता है (कारण दिखाया गया है)। व्हिपसॉ बाज़ार में एक ही पैटर्न अक्सर विफल रहता है - नकली ब्रेक और स्टॉप-हंट विक्स आदर्श हैं।"},{"h":"हाई/एक्सट्रीम में क्या करें?","t":"छोटा आकार. व्यापक रोक. कम व्यापार. मध्य-मोमबत्ती स्पाइक के बजाय पूर्ण मोमबत्ती की प्रतीक्षा करें। यदि रीडिंग चरम कहती है, तो सेटअप को एक अध्ययन क्षेत्र के रूप में मानें, प्रविष्टि के रूप में नहीं।"},{"h":"मार्टिंगेल क्या है","t":"मार्टिंगेल औसत प्रविष्टि को कम करने के लिए खोने की स्थिति में जोड़ता है: प्रत्येक प्रतिकूल कदम के बाद आप एक और ऑर्डर जोड़ते हैं, आमतौर पर बड़ा (1x, 2x, 4x…)। यह अक्सर जीतता है, फिर एक बुरे दौर में सब कुछ खो देता है।"},{"h":"सीपीई मार्टिंगेल नियम","t":"सीपीई केवल तभी अतिरिक्त ऑर्डर जोड़ता है जब दोनों सत्य हों: (1) कीमत व्यापार के मुकाबले कम से कम कदम × पायदान% बढ़ गई है, और (2) एक ताजा समान-पक्ष संकेत अभी भी उस जोड़ी के लिए खड़ा है। यह कभी भी सिर्फ इसलिए नहीं जुड़ता क्योंकि कीमत गिर गई है।"},{"h":"चार नंबर","t":"चरण % = प्रत्येक जोड़ने से पहले प्रतिकूल कदम की आवश्यकता। गुणक = प्रत्येक जोड़ का आकार बनाम आधार (1 = सपाट, 2 = दोगुना)। अधिकतम जोड़ता है = अतिरिक्त ऑर्डर पर कठोर सीमा। सीढ़ी जोखिम सीमा % = इक्विटी के % के रूप में पूरी सीढ़ी का जोखिम। ये चारों आपको चुनने हैं।"},{"h":"कठोर टोपी आपकी रक्षा करती है","t":"यहां तक कि एक बड़े गुणक और कई अतिरिक्त के साथ, सीपीई ऑर्डर को अस्वीकार कर देता है जब सीढ़ी का कुल जोखिम आपकी इक्विटी के कैप% को पार कर जाएगा। यह एक्सचेंज के न्यूनतम आकार और दैनिक -2% स्टॉप का भी सम्मान करता है।"},{"h":"यह कहां चलता है","t":"उस एक ट्रेड को प्रबंधित करने के लिए मैन्युअल पर, या उसके ऑटो ट्रेडों को प्रबंधित करने के लिए एक ऑटो सत्र पर टिक करें। डेमो और लाइव दोनों। मैनुअल पर जोड़ी को स्कैन सूची में होना चाहिए ताकि एक ताजा समान-पक्षीय सिग्नल पढ़ा जा सके।"},{"h":"टोपी क्यों मायने रखती है (उदाहरण)","t":"चरण 1%, गुणक 2, तीन 1%-जोखिम आधार पर जुड़ते हैं: जोखिम 1% → 2% → 4% → 8% हो जाता है। अंतिम पायदान पर एक पूर्ण विराम कई विजेताओं को मिटा देता है। इसीलिए सीमा मौजूद है और डिफ़ॉल्ट संख्याएँ छोटी क्यों हैं।"},{"h":"एंटी-मार्टिंगेल विकल्प","t":"कई पेशेवर इसके विपरीत करते हैं: केवल विजेताओं को जोड़ें और हारने वालों को तेजी से कम करें। यह बुरा लगता है (अधिक छोटे नुकसान) लेकिन यह आपके खिलाफ एक ही प्रवृत्ति में खाता नहीं उड़ा सकता।"},{"h":"जोखिम दूर नहीं हुआ है","t":"औसत घटाने से जोखिम दूर नहीं होता है - यह जोखिम को \"कई छोटे नुकसान\" से \"एक बड़े नुकसान\" में बदल देता है। कभी भी ऐसे पैसे न जोड़ें जिसे आप खो न सकें, और किसी घाटे वाले व्यापार को \"ठीक\" करने के लिए कभी भी सीमा को बंद न करें।"},{"h":"अभ्यास पथ","t":"पहले डेमो पर अस्थिरता रीडिंग सीखें। 30+ ट्रेडों के लिए डेमो पर अधिकतम 1-2 ऐड और एक छोटे गुणक के साथ मार्टिंगेल आज़माएं। प्रत्येक सीढ़ी का जर्नल बनाएं, फिर निर्णय लें - अधिकांश व्यापारियों को फ्लैट/एंटी-मार्टिंगेल विधि अधिक सुरक्षित लगती है।"},{"h":"अस्थिरता + मार्टिंगेल चेकलिस्ट","t":"① पहले अस्थिरता स्तर पढ़ें ② चरम में छोड़ें या सिकुड़ें ③ मार्टिंगेल केवल एक ताजा समान-पक्ष संकेत के साथ ④ चरण × पायदान पर पहुंच गया ⑤ जोखिम सीमा के तहत → जोड़ें। कोई भी \"नहीं\" → कोई जोड़ नहीं।"}]},{"id":"lab_indicators","title":"15 · चार्ट लैब संकेतक (स्टोच · एडीएक्स · इचिमोकू · वीडब्ल्यूएपी)","summary":"चार्ट लैब में अब एक पूर्ण संकेतक बार है - प्रत्येक बटन एक ऑन/ऑफ टिक है जो चार्ट को तुरंत फिर से बनाता है। बीबी/आरएसआई/एमएसीडी/ईएमए/एसएमए50/वॉल्यूम के अलावा अब आपको स्टोचैस्टिक, एडीएक्स/डीएमआई, इचिमोकू और वीडब्ल्यूएपी मिलते हैं, और सिग्नल इंजन उन्हें भी पढ़ता है - केवल चार्ट नहीं।","lessons":[{"h":"बार कहाँ है","t":"चार्ट लैब → चार्ट के नीचे बटनों की \"संकेतक\" पंक्ति। एक क्लिक से संकेतक चालू हो जाता है, अगले क्लिक से वह बंद हो जाता है; चार्ट तुरंत पुनः तैयार हो जाता है। टिक दृश्यमान होते हैं और वे सिग्नल इंजन को फीड करते हैं।"},{"h":"स्टोकेस्टिक (14,3,3)","t":"%K / %D थरथरानवाला मोमबत्तियों के नीचे खींचा गया, स्केल 0-100। ~80 से ऊपर = अधिक खरीददारी क्षेत्र, ~20 से नीचे = अधिक बिक्री क्षेत्र। %K ओवरसोल्ड जोन में %D को पार करना एक तेजी से अध्ययन है; शीर्ष पर नीचे की ओर एक क्रॉस मंदी है। एक मजबूत प्रवृत्ति में यह लंबे समय तक एक छोर पर टिका रह सकता है - हमेशा बीबी और मोमबत्ती के साथ संयोजित होता है।"},{"h":"एडीएक्स/डीएमआई (14)","t":"एडीएक्स प्रवृत्ति की ताकत को मापता है, दिशा को नहीं। ~25 से ऊपर = एक वास्तविक प्रवृत्ति चल रही है; नीचे ~20 = एक तड़का हुआ रेंज। +DI ऊपर −DI = प्रभारी खरीदार; −DI ऊपर +DI = प्रभारी विक्रेता। ADX का उपयोग यह तय करने के लिए करें कि क्या ट्रेंड-ट्रेड करना है या स्थिर रहना है।"},{"h":"इचिमोकू बादल (9,26,52)","t":"तेनकन (तेज़ रेखा), किजुन (धीमी रेखा) और सेनकोउ बादल। बढ़ते बादल के ऊपर कीमत = तेजी की पृष्ठभूमि; गिरते बादल के नीचे = मंदी। बादल के अंदर एक तेनकन/किजुन क्रॉस कमजोर है; बादल छोड़ने की कीमत के साथ एक क्रॉस मजबूत है। क्लाउड एज स्वयं अक्सर समर्थन/प्रतिरोध के रूप में कार्य करता है।"},{"h":"वीडब्ल्यूएपी","t":"वॉल्यूम-भारित औसत मूल्य - वॉल्यूम द्वारा भारित औसत मूल्य, प्रत्येक सत्र को रीसेट करें। बड़े संस्थान इसे अपने भरण-पोषण के लिए बेंचमार्क करते हैं। बढ़ती वीडब्ल्यूएपी से ऊपर कीमत = खरीदारों का नियंत्रण; डाउनट्रेंड के दौरान VWAP पर स्पष्ट अस्वीकृति एक संक्षिप्त अध्ययन है। 24/7 क्रिप्टो पर यह एफएक्स की तुलना में अलग तरह से रीसेट होता है - इसे एक गाइड लाइन के रूप में मानें, कानून के रूप में नहीं।"},{"h":"इंजन उनका उपयोग कैसे करता है","t":"प्रत्येक नया संकेतक उसी तरफ स्कोर में एक छोटी सी पुष्टि जोड़ता है जिस तरफ वह इंगित करता है (स्टोकेस्टिक, इचिमोकू, वीडब्ल्यूएपी, एडीएक्स जब वह दिशा से सहमत होता है, और इलियट)। वे पुष्टिकरण हैं, ट्रिगर नहीं - यदि वे बीबी/आरएसआई/कैंडल से असहमत हैं, तो स्कोर अधिक मिश्रित हो जाता है और आपको अधिक होल्ड मिलता है।"},{"h":"सावधानी क्यों कड़ी की गई?","t":"चूँकि अब पूल में अधिक जाँचें हैं, सावधानी पट्टी कड़ी कर दी गई है: इसके लिए स्कोर ≥ 4 और कम से कम 3 सहमत जाँचें आवश्यक हैं। यह ऐप को आपको कमजोर सिग्नलों से भरने से रोकता है, सिर्फ इसलिए कि अधिक टूल चालू हैं।"},{"h":"एक पढ़ने का क्रम जो काम करता है","t":"① उच्च-टीएफ दिशा (इचिमोकू क्लाउड + एडीएक्स)। ② कीमत कहां है (बीबी / फाइब / वीडब्ल्यूएपी)। ③ मोमेंटम (आरएसआई + स्टोकेस्टिक)। ④ मोमबत्ती की पुष्टि। ⑤ जोखिम % और लिखित स्तर → पेपर पहले।"},{"h":"गलतियों से बचना चाहिए","t":"प्रत्येक संकेतक को चालू करना और इंद्रधनुष को घूरना; एक दिशा के रूप में एडीएक्स का उपयोग करना (यह केवल ताकत है); शॉर्टिंग केवल इसलिए क्योंकि स्टोकेस्टिक बुल रन के अंदर 80 से अधिक है; इस बात को नज़रअंदाज़ करना कि क्रिप्टो बनाम एफएक्स पर वीडब्ल्यूएपी का मतलब अलग-अलग है।"},{"h":"अभ्यास चेकलिस्ट","t":"① क्लाउड से पूर्वाग्रह + ADX ② BB / Fib / VWAP से स्थान ③ RSI + स्टोच से गति ④ कैंडल पुष्टि ⑤ SL / TP लिखा ⑥ पेपर, फिर जर्नल।"}]},{"id":"elliott","title":"16 · इलियट वेव (प्रकाश गिनती)","summary":"सीपीई में एक हल्का इलियट वेव काउंटर शामिल है। चार्ट लैब संकेतक बार में \"इलियट\" पर निशान लगाएं और यह मोमबत्तियों पर अंतिम 0-1-2-3-4-5 आवेग को लेबल करता है और एक तरंग -5 फाइबोनैचि लक्ष्य पेश करता है। यह एक अध्ययन उपकरण है - कोई क्रिस्टल बॉल नहीं।","lessons":[{"h":"विचार एक पंक्ति में","t":"बाजार लहरों में चलते हैं: आवेग (प्रवृत्ति दिशा में 5 पैर) और सुधार (इसके विपरीत 3 पैर)। सीपीई केवल आवेग को गिनता है, जो कि वह हिस्सा है जो प्रवृत्ति को वहन करता है।"},{"h":"सीपीई इसे कैसे गिनता है","t":"यह अंतिम स्विंग पिवोट्स (3-बार फ्रैक्टल्स) ढूंढता है, उच्च/निम्न का विकल्प देता है, और इलियट नियमों के विरुद्ध अंतिम 5-6 स्विंग का परीक्षण करता है। यदि आकार फिट बैठता है, तो यह 0→5 लेबल (पीले रंग में अभी भी चलने वाली तरंग) और तरंग 4 से मापी गई तरंग-1 लंबाई × 1.618 से निर्मित W5 लक्ष्य रेखा खींचता है।"},{"h":"यह जिन नियमों की जांच करता है","t":"तरंग 2 तरंग 1 की शुरुआत को पार नहीं करती; वेव 4, वेव 1 के क्षेत्र को ओवरलैप नहीं करता है; तरंग 3, 1/3/5 में से सबसे छोटी नहीं है। जब कोई नियम विफल हो जाता है तो यह कुछ भी नहीं दिखाता है - कोई मजबूर गिनती नहीं।"},{"h":"तेजी बनाम मंदी","t":"0-1-2-3-4-5 का बढ़ना एक तेजी का आवेग है; नीचे जाते समय दर्पण की छवि मंदी की है। इंजन तरंग के किनारे के स्कोर में एक छोटी सी पुष्टि जोड़ता है।"},{"h":"सजीव बनाम पूर्ण","t":"एक लाइव वेव 5 (अभी भी चल रहा है) को प्रवृत्ति निरंतरता के रूप में पढ़ा जाता है। एक पूर्ण आवेग (0-5 समाप्त) चेतावनी देता है कि प्रवृत्ति थका देने वाली हो सकती है - एक सुधार अक्सर होता है।"},{"h":"W5 लक्ष्य रेखा","t":"तरंग-4 निम्न/उच्च से तरंग 1 का फाइबोनैचि विस्तार। यह एक लक्ष्य विचार है, कोई चुंबक नहीं - कीमत इससे कम या अधिक हो सकती है।"},{"h":"इसका उपयोग कैसे करें","t":"गिनती को संगम के रूप में मानें: एक मोमबत्ती और आरएसआई के साथ एक स्पष्ट बीबी / फाइब क्षेत्र में, एक आवेगपूर्ण गिनती दृढ़ विश्वास जोड़ती है। अपने आप में यह केवल एक रेखाचित्र है।"},{"h":"गलतियों से बचना चाहिए","t":"लहरों को तब तक दोबारा गिनना जब तक वे आपकी स्थिति में फिट न हो जाएं (क्लासिक इलियट पाप); छोटी-छोटी लड़ियाँ गिनना; उच्च-समय-सीमा गणना की अनदेखी करना; यह भूल जाना कि हर बार नया बार प्रिंट होने पर गिनती बदल जाती है।"},{"h":"अभ्यास चेकलिस्ट","t":"① साफ़ स्विंग चुने गए ② नियम पास ③ ज़िग-ज़ैग बीबी / फाइब से सहमत है ④ कैंडल पुष्टि ⑤ वेव -4 अमान्यकरण बिंदु से परे एसएल।"}]},{"id":"forecast","title":"17 · 3-माह का पूर्वानुमान (पूर्वानुमान 3एम टिक)","summary":"दीर्घ-क्षितिज प्रोजेक्टर: यह चार्ट अगले ~3 महीनों में कैसे बनने की संभावना है, यह सिग्नल की अपनी प्रवृत्ति, लक्ष्य और अस्थिरता से निर्मित है। चार्ट लैब में \"पूर्वानुमान 3M\" टिक के साथ इसे चालू या बंद करें।","lessons":[{"h":"यह क्या खींचता है","t":"विश्लेषण की गई प्रविष्टि से इंजन द्वारा पहले से ज्ञात सर्वोत्तम लक्ष्य (इलियट लक्ष्य → tp2 → tp1) की ओर चलने वाला एक धराशायी केंद्र पथ, एक चौड़े \"शंकु\" में लिपटा हुआ है जो प्रशंसनीय कीमतों के प्रसार को दर्शाता है। माह मार्कर M+1 / M+2 / M+3 क्षितिज को विभाजित करते हैं।"},{"h":"शंकु और रेखा क्यों नहीं?","t":"कोई भी भविष्य की सटीक कीमत नहीं जान सकता। शंकु समय के वर्गमूल और जोड़ी की अपनी अस्थिरता के साथ चौड़ा होता है, इसलिए एक शांत एफएक्स जोड़ी को एक संकीर्ण शंकु मिलता है और एक जंगली altcoin को बहुत चौड़ा शंकु मिलता है। वह चौड़ाई संदेश है: आप जितना दूर देखेंगे, कीमत उतनी ही कम निश्चित होगी।"},{"h":"नंबर कहां से आते हैं","t":"बहाव वर्तमान सिग्नल लक्ष्य से आता है; दैनिक अस्थिरता सिग्नल के एटीआर% से एक दिन तक स्केल की गई है, इसलिए शंकु का मतलब 5 मी या 1 डी चार्ट पर समान है; अत्यधिक/उच्च अस्थिरता इसे और अधिक विस्तृत कर देती है।"},{"h":"इसे कैसे पढ़ें","t":"ढलान (रास्ता किस ओर झुकता है) और चौड़ाई (कितना संदेह है) को देखें। एक संकीर्ण शंकु के साथ एक उभरता हुआ पथ = एक स्थिर प्रवृत्ति विचार; एक विशाल शंकु के साथ एक सपाट रास्ता = \"यहाँ कोई किनारा नहीं है, शोर की उम्मीद है\"।"},{"h":"इसे चालू और बंद करना","t":"\"पूर्वानुमान 3एम\" बटन \"फ्यूचर स्पेस\" के बगल में स्थित है। इसे फ्यूचर स्पेस ऑन (दाईं ओर का खाली क्षेत्र जिसमें प्रक्षेपण खींचा गया है) की आवश्यकता है। यदि सिग्नल होल्ड है तो कोई दिशा नहीं है, इसलिए कुछ भी नहीं खींचा गया है।"},{"h":"यह चलन है, व्यापार नहीं","t":"पूर्वानुमान एक बड़े चित्र वाला मानचित्र है. वास्तविक व्यापार स्तर - प्रवेश, टीपी1/टीपी2, एसएल और अल्पकालिक प्रक्षेपण - वही हैं जो आप व्यापार करते हैं।"},{"h":"ईमानदार सीमाएँ","t":"समाचार, लिस्टिंग, डीलिस्टिंग और मैक्रो शिफ्ट मॉडल में नहीं हैं; रास्ता एक सहज बहाव है, इसलिए वास्तविक कीमतें कहीं अधिक ऊपर-नीचे होंगी; 3 महीने का कोन एक अध्ययन सहायता है, कोई वादा नहीं।"},{"h":"बार-बार पुनः विश्लेषण करें","t":"जैसे ही नई मोमबत्तियाँ छपती हैं, लक्ष्य, अस्थिरता और इसलिए पूरा शंकु अपडेट हो जाता है। पूर्वानुमान एक स्नैपशॉट है, अनुबंध नहीं।"},{"h":"अभ्यास चेकलिस्ट","t":"① पथ दिशा पढ़ें ② शंकु की चौड़ाई जांचें ③ उच्च-टीएफ संरचना के साथ तुलना करें ④ वास्तविक एसएल से स्थिति का आकार लें, शंकु से कभी नहीं।"}]}],"platforms":{"BINANCE":{"title":"बिनेंस ट्रेडिंग ए → जेड","steps":["खाता बनाएं → 2FA सक्षम करें।","एपीआई प्रबंधन → कुंजी बनाएं → स्पॉट और/या वायदा व्यापार चालू, निकासी बंद।","सीपीई → एपीआई कुंजी → बिनेंस → सेव → टेस्ट अकाउंट में कुंजी + गुप्त चिपकाएँ।","स्पॉट डेस्क/फ्यूचर्स डेस्क स्कैन का उपयोग करें (सार्वजनिक चार्ट कुंजियों से पहले भी काम करते हैं)।","अभ्यास: मैनुअल ट्रेड → पेपर ट्रेड शुरू करें (कोई लाइव पैसा नहीं)।","लाइव: टीपी1/टीपी2/एसएल + ट्रेलिंग सेट करें → लाइव ट्रेड शुरू करें (एपीआई की आवश्यकता है)।","पदों में प्रबंधन करें: स्तर संपादित करें, आंशिक रूप से बंद करें, स्वचालित रूप से रद्द करें।","लाइसेंस: परीक्षण 7डी → 3-माह या आजीवन (ऐप में मालिक की कीमतें)।"]},"BYBIT":{"title":"बायबिट ट्रेडिंग ए → जेड","steps":["खाता + 2FA.","एपीआई प्रबंधन → केवल व्यापार, निकासी बंद।","सीपीई → एपीआई कुंजी → बायबिट → सहेजें।","विकृत मानसिकता के लिए फ़्यूचर्स डेस्क; मोमबत्तियों का अध्ययन करने के लिए चार्ट लैब।","कागज व्यापार पहले; चाबियाँ काम करने के बाद जियो.","ट्रेल टीपी+एसएल: खरीदें↑ / बेचें↓।"]},"OKX":{"title":"ओकेएक्स ट्रेडिंग ए → जेड","steps":["एपीआई कुंजी + गुप्त + पासफ़्रेज़ आवश्यक।","निकासी हमेशा बंद.","CPE कुंजी में सभी तीन फ़ील्ड सहेजें।","पेपर अभ्यास → छोटा लाइव आकार।","पासफ़्रेज़ टाइपो त्रुटियां #1 विफल हैं - ध्यान से कॉपी करें।"]},"KUCOIN":{"title":"कूकॉइन ट्रेडिंग ए → जेड","steps":["कुंजी + गुप्त + पासफ़्रेज़।","केवल व्यापार की अनुमति.","सीपीई में पेपर → फिर छोटे रहो।","संकेतों के लिए स्पॉट/फ्यूचर्स डेस्क का उपयोग करें।"]},"BITGET":{"title":"बिटगेट ट्रेडिंग ए → जेड","steps":["एपीआई केवल व्यापार के साथ।","कागज तो जीना.","वायदा: मैनुअल ट्रेड में क्रॉस या आइसोलेटेड चुनें।","मुनाफ़ा लॉक करने के लिए टीपी+एसएल का अनुसरण करें।"]},"GATE":{"title":"गेट.आईओ ट्रेडिंग ए → जेड","steps":["API v4 कुंजी (व्यापार) बनाएं।","निकासी बंद.","सीपीई → अभ्यास पेपर में सहेजें।","लाइव से पहले प्रविष्टियों के लिए स्कैन + चार्ट लैब।"]},"MEXC":{"title":"एमईएक्ससी ट्रेडिंग ए → जेड","steps":["स्पॉट मानसिकता प्रारंभ करें.","सीपीई एपीआई कुंजी में कुंजी।","पेपर → लाइव।","खुले लाभ को लॉक करने के लिए ट्रेल का उपयोग करें।"]},"KRAKEN":{"title":"क्रैकन ट्रेडिंग ए → जेड","steps":["केवल व्यापार अनुमति के साथ कुंजी उत्पन्न करें।","कोई निकासी/धन अधिकार नहीं.","सीपीई में पेपर अभ्यास।","क्रैकन पर भी प्रत्येक लाइव ऑर्डर को सत्यापित करें।"]},"COINBASE":{"title":"कॉइनबेस एडवांस्ड ए → जेड","steps":["उन्नत व्यापार एपीआई कुंजियाँ।","सीपीई में स्पॉट-केंद्रित डेस्क।","कागज तो जीना.","निकासी बंद रखें."]},"FOREX_OANDA":{"title":"विदेशी मुद्रा (ओंडा) ए → जेड","steps":["OANDA डेमो खोलें → जोखिम ~1%।","सीपीई कुंजी में व्यक्तिगत पहुंच टोकन + खाता आईडी।","विदेशी मुद्रा डेस्क स्कैन + चार्ट लैब (EURUSD…)।","मैनुअल ट्रेड → फॉरेक्स प्लेटफॉर्म के साथ पेपर।","डेमो आत्मविश्वास के बाद ही जियें।"]},"FOREX_FXCM":{"title":"एफएक्ससीएम फॉरेक्स ए → जेड","steps":["ब्रोकर एपीआई क्रेडेंशियल.","सीपीई में पेपर पहले।","लंदन/एनवाई सत्र और समाचार स्पाइक्स देखें।","अभ्यास के बाद का लाइव जर्नल साफ़ दिखता है।"]},"FOREX_MT5":{"title":"MetaTrader 5 ए → जेड","steps":["सीपीई कुंजी में लॉगिन + सर्वर + पासवर्ड।","जहां संभव हो निवेशक (पढ़ें) पासवर्ड को प्राथमिकता दें।","अभ्यास लॉट 0.01.","सीपीई में पेपर; तैयार होने पर ब्रोकर के माध्यम से लाइव।"]},"FOREX_DEMO":{"title":"विदेशी मुद्रा डेमो दरें ए → जेड","steps":["किसी API कुंजी की आवश्यकता नहीं है.","निःशुल्क चार्ट के लिए फॉरेक्स डेस्क + चार्ट लैब।","कागज केवल व्यापार करता है (अभ्यास)।","वास्तविक ब्रोकर के लिए तैयार होने पर, लाइव के लिए OANDA / FXCM / MT5 कुंजी जोड़ें।"]}},"forexAz":{"title":"विदेशी मुद्रा व्यापार ए → जेड (पूर्ण श्रेणी)","lessons":[{"h":"ए - खाता और जोखिम","t":"पहले डेमो. प्रति विचार जोखिम ~0.5-1%। कभी भी बदला लेने का व्यापार न करें।"},{"h":"बी - जोड़े","t":"एक्सोटिक्स से पहले मेजर्स (EURUSD, GBPUSD, USDJPY)।"},{"h":"सी - मोमबत्तियाँ","t":"चार्ट लैब फॉरेक्स पर डोजी, हैमर, एनगल्फिंग सीखें।"},{"h":"डी - दैनिक पूर्वाग्रह","t":"15 मी/30 मी प्रविष्टियों से पहले उच्च समय सीमा की जाँच करें।"},{"h":"ई - प्रविष्टियाँ","t":"बीबी लोअर बाउंस + कैंडल कन्फर्म एक सामान्य अभ्यास सेटअप है।"},{"h":"एफ - फ़िब","t":"50% / 61.8% पुलबैक अक्सर अभ्यास क्षेत्र के रूप में उपयोग किए जाते हैं।"},{"h":"जी - लक्ष्य (टीपी)","t":"टीपी1 स्केल आउट, टीपी2 रनर, ट्रेल एसएल।"},{"h":"एच - घंटे","t":"लंदन-एनवाई ओवरलैप = अधिक हलचल।"},{"h":"मैं - संकेतक","t":"आरएसआई + एमएसीडी + बीबी एक साथ; सूचक अधिभार से बचें."},{"h":"जे - जर्नल","t":"सीपीई जर्नल में प्रत्येक पेपर/लाइव ट्रेड को लॉग इन करें।"},{"h":"के - कुंजी","t":"लाइव फॉरेक्स ब्रोकर को एपीआई/टोकन की आवश्यकता है; डेमो दरों की कोई आवश्यकता नहीं है।"},{"h":"एल - बहुत सारे","t":"अभ्यास मानसिकता में 0.01 लॉट प्रारंभ करें।"},{"h":"एम - मानसिकता","t":"भविष्यवाणी पर प्रक्रिया. बुरे दिन छोड़ें."},{"h":"एन - समाचार","t":"बड़ी घटनाओं से पहले समाचार और युक्तियाँ जांचें।"},{"h":"ओ - आदेश","t":"हमेशा SL सेट करें. ट्रेलिंग खुले लाभ की सुरक्षा करती है।"},{"h":"पी - अभ्यास","t":"पेपर ट्रेड बटन = लाइव एपीआई के बिना अभ्यास।"},{"h":"प्रश्न - गुणवत्ता","t":"कम उच्च गुणवत्ता वाले सेटअप ओवरट्रेडिंग को मात देते हैं।"},{"h":"आर - जोखिम: इनाम","t":"ऐसे सेटअप का लक्ष्य रखें जहां संभव होने पर इनाम ≥ जोखिम हो।"},{"h":"एस - सत्र","t":"एशिया शांत; लंदन/एनवाई अधिक सक्रिय।"},{"h":"टी - रुझान","t":"सीखते समय उच्च-टीएफ प्रवृत्ति के साथ व्यापार करें।"},{"h":"यू - अपडेट","t":"सीपीई अपडेट बैनर + लाइव सहायता देखें।"},{"h":"वी - अस्थिरता","t":"एटीआर बढ़ने पर धैर्य बढ़ाएं।"},{"h":"डब्ल्यू - एपीआई वापस लें","t":"किसी भी एपीआई कुंजी पर कभी भी निकासी सक्षम न करें।"},{"h":"एक्स - बाहर निकलता है","t":"आंशिक टीपी + ट्रेल आशा को मात देता है।"},{"h":"Y - आपकी योजना","t":"नियम लिखें; मैनुअल/ऑटो में उनका पालन करें।"},{"h":"Z - शून्य भीड़","t":"कोई फोमो नहीं. अभ्यास → फिर लाइव एपीआई।"}]}};

window.CPE_LEARN.zh = {"intro":"首先使用 Paper / DEMO 进行练习。研究蜡烛、图表、BB/RSI/Fib、货币、心理学——然后研究信号（买入/卖出/持有意味着什么+做什么）和外汇信号。 Live 需要正确的平台 API 密钥（提款关闭）。","candles":[{"shape":"doji","name":"十字星","color":"#94a3b8","bias":"中立/等待","tip":"开盘 ≈ 收盘 — 十字形或薄形实体。市场在行动后犹豫不决。","also":"还教导：不要 FOMO。等待下一支蜡烛。接近 BB 极端 + 十字星 = 意见挤压；在猜测方向之前检查 RSI 斜率。"},{"shape":"hammer","name":"锤子","color":"#22c55e","bias":"买入偏好","tip":"顶部实体较小，下跌后下影线较长（约 2 倍实体）——买家拒绝接受更低的价格。","also":"另外：将练习 SL 置于灯芯下方。最佳时机是 BB + RSI 因超卖而上升。心理学：耐心等待灯芯完成——不要购买中灯芯。"},{"shape":"invhammer","name":"倒锤","color":"#22c55e","bias":"买入（弱）","tip":"底部有长的上灯芯。买家探高，但收盘接近开盘——需要下一个绿色确认。","also":"另外：比单独的锤子弱。用作警报，而不是入口。 Fib 61.8 反弹 + 倒转锤子 = 仅研究区域，直至确认蜡烛。"},{"shape":"shooting","name":"流星","color":"#ef4444","bias":"卖出偏见","tip":"底部较小，上涨后上影线较长——卖家拒绝高点。","also":"另外：SL 高于灯芯高位。在 BB 上方/Fib 延伸/RSI 超买附近走强。教导：月光蜡烛可能会失败——不要追逐最后的绿色。"},{"shape":"hanging","name":"吊人","color":"#f59e0b","bias":"卖出谨慎","tip":"看起来像锤子，但出现在上涨之后——可能是顶部疲惫。","also":"另外：背景就是一切（相同的形状≠相同的交易）。日记位置：顶部与底部。心理学：不要仅仅因为形状匹配而反转——用下一根蜡烛 + RSI 进行确认。"},{"shape":"engulf_bull","name":"看涨吞没","color":"#22c55e","bias":"买入","tip":"绿色主体完全覆盖了之前的红色主体——买家在一根柱中控制了一切。","also":"另外：支撑位更强/BB/Fib 50-61.8 更低。尺寸从吞没低至SL。金钱提示：宽吞没体→更宽的SL→更小的尺寸。"},{"shape":"engulf_bear","name":"看跌吞没","color":"#ef4444","bias":"卖出","tip":"红色主体完全覆盖了之前的绿色主体——卖家占主导地位。","also":"另外：谨慎持有多头头寸。接近上BB + RSI>70 = 高研究质量。教导风险：如果已经做多，则部分 TP/Trail 而不是希望。"},{"shape":"morning","name":"晨星","color":"#22c55e","bias":"买入","tip":"3根蜡烛：大红色→小星星→大绿色。底部反转的故事。","also":"另外：多蜡烛耐心。 3号关门后入场； SL 星下低。与 BB 较低 + 看涨 RSI 背离完美结合。"},{"shape":"evening","name":"晚星","color":"#ef4444","bias":"卖出","tip":"3根蜡烛：大绿色→小星星→大红色。顶级反转故事。","also":"另外：不要单独做空中间的星星。等待第三关。上 BB/Fib 延伸汇合。心理学：忽略第一次绿色跑步的 FOMO。"},{"shape":"maru_bull","name":"牛丸坊主","color":"#22c55e","bias":"强劲的买入压力","tip":"长生坯，几乎没有灯芯——买家控制开→关。","also":"另外：趋势延续线索，并不总是底部买入。可以随乐队走动。风险：追逐后期 Marubozu，而不回调至 BB 中/Fib。"},{"shape":"maru_bear","name":"熊丸坊主","color":"#ef4444","bias":"强劲的卖出压力","tip":"长长的红色主体，几乎没有灯芯——卖家处于控制之中。","also":"另外：不要接住掉落的刀子。稍后等待 BB/Fib 反弹 + 锤子。教导：强大的压力=较小的尺寸或靠边站。"},{"shape":"spin","name":"陀螺","color":"#94a3b8","bias":"优柔寡断","tip":"身躯小，上灯芯+下灯芯，双方交手，谁也没有分出胜负。","also":"另外：经常挤压内部BB。暂停交易；等待突破+方向蜡烛。心理学教训：市场可以“无能为力”——持平是一个有效的选择。"},{"shape":"pierce","name":"穿孔线","color":"#22c55e","bias":"买入","tip":"红色然后绿色，开盘价较低，但收盘价高于先前红色的中点。","also":"另外：比吞噬更柔和。通过 RSI 转向确认。适合部分强度阅读的良好纸钻——并非所有果岭都是平等的。"},{"shape":"darkcloud","name":"乌云盖顶","color":"#ef4444","bias":"卖出","tip":"绿色然后红色，开盘价较高，但收盘价低于先前绿色的中点。","also":"另外：全面熊吞没之前的预警。追踪多头/采取 TP1。教导在完全反转打印之前进行缩放。"},{"shape":"soldiers","name":"三个白人士兵","color":"#22c55e","bias":"买入趋势","tip":"三个绿色上涨，收盘价较高——稳定买盘。","also":"另外：强劲的上升趋势线索；回调至斐波那契 38-50 或 BB 中线是练习加法。 3 个果岭后的过度自信风险 - 保持风险百分比固定。"},{"shape":"crows","name":"三只黑乌鸦","color":"#ef4444","bias":"卖出趋势","tip":"三只下跌的红色收盘价较低——稳定抛售。","also":"另外：不要平均下来。等等结构。 RSI 超卖可以保持超卖——金钱规则：损失限额 > 希望。"},{"shape":"harami_bull","name":"看涨孕育","color":"#22c55e","bias":"买入（软）","tip":"先前的实体内先是大红色，然后是小绿色——卖压正在缩小。","also":"另外：提前暂停信号。需要确认。与 RSI 看涨背离研究配对。教导人们阅读“力量衰退”而不仅仅是逆转。"},{"shape":"harami_bear","name":"看跌孕妇","color":"#ef4444","bias":"卖出（软）","tip":"大绿色，然后里面是小红色——购买压力正在缩小。","also":"另外：对多头进行部分处理。不是自动短路。心理学：大绿后的贪婪常常忽视孕育的警告。"},{"shape":"tweezer_bot","name":"镊子底部","color":"#22c55e","bias":"买入","tip":"两根蜡烛具有匹配的低点 — 双重支撑测试。","also":"另外：将其标记为结构。 SL就在下面。 Fib/BB 对齐有帮助。双底图表形态的表亲 — 同样的支持课程。"},{"shape":"tweezer_top","name":"镊子顶部","color":"#ef4444","bias":"卖出","tip":"两根蜡烛具有相同的高点——双重阻力测试。","also":"另外：标记电阻。双顶的表弟。 RSI 在高点失败 = 汇合。教导：同样的价格两次拒绝=尊重水平。"},{"shape":"longlegged","name":"长腿十字星","color":"#94a3b8","bias":"优柔寡断","tip":"上下灯芯很长，身体很小——一场激烈的双向战斗，从开始的地方就结束了。","also":"另外：通常会出现大幅波动，但方向未知——等待突破蜡烛。教导：高波动性并不意味着高确定性。"},{"shape":"dragonfly","name":"蜻蜓十字星","color":"#22c55e","bias":"买入偏好","tip":"开盘=收盘=高位，具有较长的下影线——卖方将其推低，而买方则将其直接推高。","also":"另外：最强支撑位/下跌后 BB 线下方。 SL 位于灯芯尾部下方。教导：拒绝是一个故事，而不是一个保证——确认下一根蜡烛。"},{"shape":"gravestone","name":"墓碑十字线","color":"#ef4444","bias":"卖出偏见","tip":"开盘=收盘=低点，上影线很长——买家推高价格，卖家将其拉回低点。","also":"另外：最强阻力位/上方 BB/RSI 超买。蜻蜓之镜。教导：在低点收盘的峰值是失败的突破。"},{"shape":"inside_bar","name":"内部酒吧","color":"#94a3b8","bias":"卷绕/等待","tip":"第二根蜡烛完全位于第一根蜡烛内部——区间缩小，市场屏住呼吸。","also":"另外：母柱的突破是触发因素——在突破方向进行交易。与 BB 挤压配对。教导：收缩先于扩张。"},{"shape":"outside_bar","name":"室外酒吧","color":"#22c55e","bias":"突破/逆转","tip":"第二根蜡烛从高点到低点吞没了第一根蜡烛——一根蜡烛线内的剧烈接管。","also":"另外：方向 = 外部柱线关闭的位置。大条意味着大 SL，因此尺寸较小。教导：一根小节可以擦除最后三节。"},{"shape":"belt_bull","name":"看涨腰带持有","color":"#22c55e","bias":"买入","tip":"在低位开盘，没有更低的影线，呈绿色运行——买家从第一个价格变动时就控制了局面。","also":"另外：在向下跳空或直接进入支撑位后最强。 SL开下。教导：开场驱动显示出真正的意图。"},{"shape":"belt_bear","name":"看跌腰带持有","color":"#ef4444","bias":"卖出","tip":"开盘价高，没有上影线，呈红色——卖家从开盘时就控制了它。","also":"另外：跳空缺口或阻力位后最强。踪迹长。教：一招可定全日。"},{"shape":"kick_bull","name":"看涨踢球者","color":"#22c55e","bias":"强力买入","tip":"一根红色蜡烛，然后是一根向上跳空的绿色蜡烛——情绪在收盘之间翻转，没有重叠。","also":"还有：稀有而强大；间隙是必需的，不允许重叠。教训是：当市场沉睡时，情绪可能会发生转变。"},{"shape":"kick_bear","name":"看跌踢球者","color":"#ef4444","bias":"强力卖出","tip":"一根绿色蜡烛，然后跳空跳空变成一根红色蜡烛——买家在收盘之间消失了。","also":"另外：快速退出多头——踢脚者不会等你。教导：差距是当你离开时市场的重新定价。"},{"shape":"abandoned","name":"看涨弃婴","color":"#22c55e","bias":"强力买入","tip":"一根红色蜡烛，一根向下缺口的十字星，然后一根向上缺口的绿色蜡烛——一座犹豫不决的孤岛。","also":"另外：十字星必须在两侧跳空。底部稀有但品质高。教导：逆转从每个人都放弃的地方开始。"},{"shape":"three_inside_up","name":"三内朝上","color":"#22c55e","bias":"买入","tip":"看涨孕育形态加上第三根绿色蜡烛收盘价高于第一根蜡烛——内线柱最终突破。","also":"另外：经过确认的孕育者比裸露的孕育者强得多。 SL 位于孕育低点下方。教导：确认胜于预测。"},{"shape":"three_inside_down","name":"三内朝下","color":"#ef4444","bias":"卖出","tip":"看跌孕妇加上第三根红色蜡烛收盘价低于第一根蜡烛——内线突破。","also":"另外：第三个收盘后立即削减多头。教导：失败的暂停可以简单地恢复旧趋势。"},{"shape":"three_methods_bull","name":"上升三法","color":"#22c55e","bias":"买入趋势","tip":"一根长长的绿色蜡烛，里面有三个小红色蜡烛，然后是另一个长长的绿色蜡烛——上升中的休息。","also":"另外：暂停永远不会离开第一个蜡烛范围，因此趋势是平静的。在最后一根蜡烛的突破点进行交易。教导：趋势静止而不打破。"},{"shape":"three_methods_bear","name":"跌倒三法","color":"#ef4444","bias":"卖出趋势","tip":"一根长长的红色蜡烛，里面有三个小绿色蜡烛，然后是另一个长长的红色蜡烛——在秋天里休息。","also":"又：升三法之镜。不要购买小果岭——它们是噪音。教导：区间内的回调不是反转。"},{"shape":"tower_bot","name":"塔底","color":"#22c55e","bias":"买入反转","tip":"一根长长的红色蜡烛，一簇小蜡烛，然后是一根长长的绿色蜡烛——情绪在平坦的底座上变化。","also":"另外：平坦的中间是战斗，最后一根蜡烛宣布胜利者。教导：基础需要时间。"},{"shape":"tower_top","name":"塔顶","color":"#ef4444","bias":"卖出反转","tip":"一根长长的绿色蜡烛，一簇小蜡烛，然后是一根长长的红色蜡烛——买家耗尽，卖家接管。","also":"还有：塔底的镜子。在基本形式的同时采取部分形式。教导：顶部是一个过程，而不是一个时刻。"}],"chartPatterns":[{"shape":"double_bot","name":"双层底（宽）","color":"#22c55e","bias":"买入偏好","tip":"两个低点接近同一价格，然后突破中峰——W 形。","also":"另外：颈线突破=练习触发。测量 TP 想法的高度。从峰值→低点到镊子底部 + 斐波那契的链接。风险：假突破——等待接近颈线。"},{"shape":"double_top","name":"双顶 (M)","color":"#ef4444","bias":"卖出偏见","tip":"两个高点接近同一价格，然后突破中间低谷——M 形。","also":"另外：与更大尺寸的镊子顶部相同。在颈线突破之前，踪迹会做多。心理学：第二大的 FOMO 代价高昂——计划已经存在。"},{"shape":"hs_top","name":"头肩顶","color":"#ef4444","bias":"卖出偏见","tip":"左肩、高头、右肩；打破领口。","also":"另外：经典发行版。目标 ≈ 颈线以下的头部高度。 RSI 经常在头部出现背离。教导多重波动的耐心——而不是一根蜡烛的交易。"},{"shape":"ihs","name":"逆H&S","color":"#22c55e","bias":"买入偏好","tip":"H&S 底部反转——颈线向上突破。","also":"还有：积累故事。如果有的话，请确认交易量/动量。与右肩区域的晨星配对进行汇合研究。"},{"shape":"triangle","name":"三角形（挤压）","color":"#f0b429","bias":"突破等待","tip":"较低的高点+较高的低点压缩——能量积累。","also":"另外：与 BB 挤压相同的课程。不要猜测里面的方向。交易中断 + 蜡烛收盘。金钱：已知方向后的大小。"},{"shape":"flag","name":"牛旗","color":"#22c55e","bias":"购买续","tip":"急剧上升（极点），然后小幅下行/横向通道 - 然后持续。","also":"另外：纤维旗形深度通常较浅 (38%)。丸坊主杆+旗帜=潮流实践。完全延伸且没有回调后不要买入。"},{"shape":"channel","name":"趋势频道","color":"#38bdf8","bias":"随潮流","tip":"上升（或下降）平行线之间的价格——波段交易工具。","also":"另外：在上升趋势中买入较低通道+锤子线；卖上层+流星。 BB 中频经常跟踪通道。不仅教“什么蜡烛”，还教“哪里”。"},{"shape":"support_res","name":"支撑与阻力","color":"#a78bfa","bias":"上下文优先","tip":"价格反复反应的水平区域——每根蜡烛下方的地图。","also":"另外：每种模式在 S/R 上都更强。在图表实验室上绘制 BB/RSI 之前的区域。心理学：水平>技巧；在输入之前写下它们。"},{"shape":"triple_top","name":"三重顶","color":"#ef4444","bias":"卖出偏见","tip":"价格几乎相同的三个高点——买家在一堵墙上失败了三次。","also":"另外：强于双顶（三个拒绝=顽固的供应）。颈线突破是触发因素；目标 ≈ 图案高度。教导：水平，而不是蜡烛，才是老大。"},{"shape":"triple_bot","name":"三重底","color":"#22c55e","bias":"买入偏好","tip":"价格几乎相同的三个低点——卖家在一层楼失败了三次。","also":"还有：三重顶的镜子。每次触摸都可以是锤子/镊子研究。等待颈线突破+收盘。教会我们在许多波动中保持耐心。"},{"shape":"cup_handle","name":"杯子&手柄","color":"#22c55e","bias":"购买续","tip":"一个圆形的“U”（杯），然后一个小拉回（手柄）——休息后继续。","also":"另外：受到突破交易者的欢迎。手柄应该又浅又短——手柄深意味着手力弱。在蜡烛确认的句柄中断处输入。"},{"shape":"rounding_bot","name":"圆底","color":"#22c55e","bias":"买入反转","tip":"缓慢、平稳的“碟形”低点——抛售逐渐消退，然后买家接管。","also":"另外：慢动作双底。传达的信息是，卖家已经耗尽了精力，而不是一次峰值——需要充分的耐心。"},{"shape":"rounding_top","name":"圆顶","color":"#ef4444","bias":"卖出反转","tip":"平稳的“穹顶”高点——买盘在价格回落之前逐渐消退。","also":"另外：圆底的镜子。在动力消失时尽早采取部分措施。教导：顶部是一个过程，而不是一根蜡烛。"},{"shape":"rising_wedge","name":"上升楔形","color":"#ef4444","bias":"卖出偏见","tip":"两条轨道都上升，但它们向上收敛——随着区间缩小，买家感到疲倦。","also":"另外：由于价格仍在上涨而具有误导性；缩小范围才是真正的线索。经常崩溃。不要追赶最后的推动。"},{"shape":"falling_wedge","name":"下降楔形","color":"#22c55e","bias":"买入偏好","tip":"两条轨道均下跌，但它们向下收敛——随着区间缩小，卖家感到疲倦。","also":"还有：上升楔形镜子。经常分手。楔尾中的锤子是一项经典研究。等待突破+收盘。"},{"shape":"asc_triangle","name":"上升三角形","color":"#f0b429","bias":"买入偏好","tip":"平坦的天花板+上升的地板——买家不断增加，形成固定阻力。","also":"另外：针对单一价格的压力增大；突破是常见的。进入天花板上方附近。教训：买家变得不耐烦。"},{"shape":"desc_triangle","name":"下降三角形","color":"#f0b429","bias":"卖出偏见","tip":"平坦的地板+下降的天花板——卖家不断推向固定支撑位。","also":"另外：上升三角形的镜子。突破下跌是常有的事。从接近地板下方进入。教导：卖家获得控制权。"},{"shape":"pennant","name":"三角旗","color":"#22c55e","bias":"延续","tip":"一个尖锐的柱子，然后是一个微小的、紧密的三角形——在趋势恢复之前有一个非常短暂的休息。","also":"另外：像旗帜，但更短且呈三角形。测量目标想法的杆子。永远不要猜测微小线圈的内部。"},{"shape":"flag_bear","name":"熊旗","color":"#ef4444","bias":"卖出（续）","tip":"急剧下跌（极点），然后是一个小的向上/横向通道 - 然后继续向下。","also":"还有：牛旗镜子。小小的反弹只是暂停，而不是逆转。追逐旗帜，你会以最差的价格买入——等待突破。"},{"shape":"rectangle","name":"矩形（范围）","color":"#f0b429","bias":"范围交易","tip":"价格在平坦的天花板和地板之间反弹——一个横向的盒子。","also":"另外：淡化内侧边缘，交易外侧突破。 BB 挤压通常位于矩形内。教学：逐级纪律。"},{"shape":"broadening","name":"加宽阵型","color":"#f0b429","bias":"注意事项","tip":"更高的高点和更低的低点——范围呈扇形展开而不是收缩。","also":"还有：混乱、情绪化的市场。止损受到双向打击。尺寸较小或靠边放置；它常常以暴力的单向行动结束。"},{"shape":"diamond","name":"钻石","color":"#f0b429","bias":"逆转","tip":"中间宽，两端窄——经典的顶部/底部形态。","also":"另外：一个变形然后不变形的三角形。突破方向决定。很少发生而且速度很慢，所以大多数行感觉就像噪音——要有耐心。"},{"shape":"island_rev","name":"岛形反转","color":"#ef4444","bias":"逆转","tip":"价格跳空，在一个孤独的集群中交易，然后跳空回来——形成一个“岛屿”。","also":"另外：需要真正的缺口（在股票/外汇中更常见）。岛上有被困的买家或卖家。将缺口视为信号，而不是岛屿蜡烛。"},{"shape":"breakaway_gap","name":"突破缺口","color":"#22c55e","bias":"趋势开始","tip":"超出范围或底部的缺口——移动始于力量，而不是挤压。","also":"另外：与疲惫缺口不同的是，它出现在行动的早期。缺口通常会在稍后充当支撑/阻力。教导：动量与价值差距。"},{"shape":"v_reversal","name":"V型反转","color":"#22c55e","bias":"逆转","tip":"突然出现的急剧自由落体，没有底座——“V”。","also":"还有：速度快而且吓人；往往是新闻驱动的。追之难，追之易。等待小幅回调+蜡烛，而不是在峰值时买入。"},{"shape":"harmonic","name":"谐波模式","color":"#f0b429","bias":"反转区","tip":"测量的之字形 (X-A-B-C-D)，其中每条腿都有斐波那契比率 - “加特利/蝙蝠”风格的地图。","also":"还有：高级。 D点是入口区，由比率而不是感觉定义。首先掌握普通斐波那契；这是更深入一层的斐波那契。"}],"modules":[{"id":"bb","title":"1 · 布林线 (BB)","summary":"移动平均线周围的波动带。学习挤压、走带、下/上触摸 + 蜡烛确认——核心 CPE 练习设置。","lessons":[{"h":"BB是什么","t":"布林带 = 中 SMA（通常为 20）+ N 个标准差处的上/下带（通常为 2）。当波动性上升时，波动幅度会扩大；当市场平静时，波动幅度会缩小。"},{"h":"中带","t":"中间的线是平均值。价格高于中间往往显示看涨压力；下面显示看跌压力。将其用作动态偏差线，而不是魔术买/卖。"},{"h":"较低波段（买入练习）","t":"价格下跌后标记下限可能意味着“向下延伸”。不要每次接触都买。等待看涨蜡烛（锤子线、吞没线）并且理想情况下 RSI 出现。"},{"h":"上限（卖出/谨慎）","t":"价格上限可能意味着“拉长”。在上升趋势中，价格可能会沿着上轨线移动（walk-the band）。仅在看跌蜡烛 + 较高 TF 疲软时更倾向于卖出想法。"},{"h":"挤","t":"窄带 = 低波动性 → 通常会出现突破。不要在紧逼中猜测方向；标记突破并用蜡烛 + 成交量（如果有）进行确认。"},{"h":"跟着乐队走","t":"在强劲趋势中，价格紧贴许多蜡烛的上限（或下限）。用均值回归淡入淡出来对抗这个问题是初学者常见的错误。"},{"h":"BB+图表实验室","t":"在 CPE 图表实验室/办公桌中，在 DEMO 上研究带有蜡烛的 BB。练习：较低的波段 + 锤子 → SL 低于灯芯，TP1 接近中波段的模拟交易。"},{"h":"BB + RSI 组合","t":"更强的练习过滤器：较低的 BB + RSI 超卖（或从超卖上升）+ 看涨蜡烛。上方BB+RSI超买+看跌蜡烛做空练习。"},{"h":"停止放置","t":"多头练习：止损在摆动低点/下方波段影线下方。空头练习：止损高于摆动高点。切勿在没有书面止损的情况下进入 BB 交易。"},{"h":"目标","t":"共同路径：TP1位于中带，TP2朝向相反带或尾迹。横向扩展——不需要整个迁移。"},{"h":"时间表","t":"决定较高 TF (4H/1D) 的偏差。在 15m/30m BB + 蜡烛入场。混合随机 TF 会导致信号冲突。"},{"h":"要避免的错误","t":"在崩溃的市场中买入每一个较低的波段；卖掉月球跑中的每一次上手触感；无 SL；忽略剧烈拉宽区间的新闻峰值。"},{"h":"练习清单","t":"① 较高的 TF 偏差 ② BB 触碰或挤压突破 ③ 蜡烛确认 ④ RSI 一致 ⑤ 风险百分比设定 ⑥ 论文优先 ⑦ 日志结果。"}]},{"id":"rsi","title":"2·RSI（相对强弱指数）","summary":"动量振荡器 0–100。默认 14 期。与 BB 线和蜡烛一起使用 — 切勿将 RSI 单独作为一个完整的系统。","lessons":[{"h":"RSI 衡量什么","t":"RSI 比较 N 个柱的平均收益与损失。高 RSI = 近期看涨势头；低 RSI = 近期看跌势头。并不是每次都是“超买=必须卖出”。"},{"h":"经典区","t":"通常：高于 70 = 超买区，低于 30 = 超卖区。在强劲趋势中，RSI 可能会长时间保持超买/超卖——这是正常的。"},{"h":"中线50","t":"RSI 突破 50 可以支持看涨倾向；低于50看跌偏见。许多交易者使用 50 作为 BB 中带的趋势过滤器。"},{"h":"背离——看涨","t":"价格走低，RSI 走高 → 下行动能减弱。入场前仍需等待蜡烛+结构突破。"},{"h":"背离——看跌","t":"价格走高，RSI 走低 → 上行动能减弱。用流星/吞没附近阻力位或上方BB线进行确认。"},{"h":"失败波动","t":"RSI 未能重新测试先前的极端值，然后回穿 50——早期动量转变的线索。结合图表实验室结构。"},{"h":"RSI + BB（CPE 风格）","t":"练习多头：价格接近下BB，RSI≤35（或从≤30上涨），看涨蜡烛。练习做空：BB上方，RSI≥65-70，看跌蜡烛。"},{"h":"隐藏的背离","t":"趋势延续线索（例如，价格走低，RSI 在上升趋势中走低）。高级 - 首先在 DEMO 上掌握经典分歧。"},{"h":"设置","t":"RSI(14) 是常见的默认值。 RSI 越短 = 噪音越大。不要不断改变设置来强制发出信号。"},{"h":"以 RSI 退出","t":"如果您超卖买入，当 RSI 到达中/上部区域时获利了结是合理的。用结构或 BB 中线追踪其余部分。"},{"h":"新闻与相对强弱指数","t":"大新闻可以立即飙升 RSI。在对 RSI 极端值采取行动之前，最好等待第一根剧烈蜡烛结束。"},{"h":"错误","t":"在牛市中每逢 RSI>70 就做空；渴望在熊市崩盘时每一次 RSI<30；没有汇合；当 RSI“看起来更好”时，复仇重新进入。"},{"h":"练习清单","t":"① 记下 RSI 值 + 斜率 ② 检查 BB 位置 ③ 蜡烛确认 ④ 较高的 TF ⑤ 论文 + 日志 ⑥ 一次一个想法。"}]},{"id":"fib","title":"3·斐波那契（回调和扩展）","summary":"测量从明显的波动高点 → 波动低点（或反向）的回调和目标。关注 38.2 · 50 · 61.8 与 BB/RSI 汇合。","lessons":[{"h":"为什么使用斐波那契","t":"许多交易者都会关注相同的比率，因此流动性通常会在这些比率附近做出反应。 Fib 是可能区域的地图，但不是保证。"},{"h":"摆动点","t":"始终从明确的波动低点绘制到波动高点（向上移动）或从高点绘制到低点（向下移动）。糟糕的波动=无用的水平。在图表实验室演示中练习挑选波动。"},{"h":"关键回调","t":"常见：23.6%（浅层）、38.2%、50%（不是纯斐波那契，但广泛使用）、61.8%（黄金）、78.6%（深层）。深度回调可能预示着趋势疲软。"},{"h":"回调买入（上升趋势）","t":"冲高后，等待回调至38.2-61.8区域+看涨蜡烛+最好是BB中/下支撑或RSI保持>40-45。"},{"h":"回调卖出（下降趋势）","t":"冲量下跌后，反弹至 38.2-61.8 + 看跌蜡烛 + RSI 跌破 55-60。"},{"h":"扩展/目标","t":"常见扩展：TP2 想法超出摆动范围 127.2%、161.8%。与 Trail 一起使用——不要强制精确的刻度。"},{"h":"融合=力量","t":"最佳实践区域：Fib 50/61.8 + BB 中/下 + 先前结构 + RSI 转向。仅一条斐波那契线很弱。"},{"h":"斐波那契 + BB","t":"如果 61.8% 位于上升趋势中的下 BB 附近，则该重叠区域就是高质量的论文研究区域。仅通过蜡烛确认进入。"},{"h":"多个小纤维","t":"初学者应该使用一次干净的挥杆。堆叠 5 个斐波那契会产生图表噪音和 FOMO 条目。"},{"h":"无效","t":"如果价格收盘明显超过 78.6%，与你的偏见相反，回调论点通常会失败——退出或袖手旁观。"},{"h":"外汇与加密货币","t":"相同的比率。外汇专业人士通常在流动性交易中更清楚地尊重水平；加密货币可以通过毛细作用然后反转——尺寸更小。"},{"h":"错误","t":"在微小的噪声波动上绘制 Fib；进入半空中，没有蜡烛；当 Fib“几乎”成立时，将 SL 移动得更远；忽略较高的 TF。"},{"h":"练习清单","t":"① 标记波动 ② 票据 38.2/50/61.8 ③ 等待价格到达 ④ 蜡烛 + RSI/BB ⑤ 风险设置 ⑥ 纸 → 日记帐。"}]},{"id":"money","title":"4·资金管理","summary":"该方法的实际使用方式是：承担固定百分比的风险、止损规模、将部分利润存入银行，并在损失限制后的当天止损。 CPE 可以将此应用于手动和自动交易。","lessons":[{"h":"资金管理目标","t":"留在游戏中。一笔糟糕的交易永远不应该抹掉账户。一致性胜过彩票大小。"},{"h":"交易者如何实际使用它","t":"常见的做法是固定分数风险。您无需先选择硬币数量。你先写下止损，确定这个想法可能会损失大约 1% 的账户，然后规模就会下降。较宽的止损可以获得较小的位置。严格止损可以获得更大的头寸，而美元风险保持不变。这是 CPE 在资金管理开启时使用的方法。"},{"h":"工作示例（1000 美元练习账户）","t":"账户1000美元。风险 1% = 10 美元。入口 100，停止 98。距离 = 2%。规模 = 10 ÷ 0.02 = 名义金额 500 美元。如果触及止损，损失约为 10 美元，而不是 500 美元。如果价格达到 103（风险的 1.5 倍），收益约为 15 美元。每对货币的想法都是一样的：风险美元保持在 1% 附近，代币数量发生变化。"},{"h":"CPE 对蜱虫做什么","t":"立即交易 → 自动：勾选“使用资金管理”。保存自动配置。然后，每笔新的汽车交易都会使用 1000 美元模拟账户的大约 1% 加上已平仓结果，其大小取决于该信号的入场点和止损。尊重现货和期货最低限额：如果交易所最低限额的风险超过 1%，则该交易将被跳过。在日历日约-2%之后，新车将停止行驶直至第二天。在未平仓交易中，最多有 3% 左右的人面临风险。手动交易具有相同的刻度。信号历史记录仍然显示相同的 10 美元测试，其下方是 1000 美元账户的 1% 计划规模，因此您可以看到两者。"},{"h":"部分利润和轨迹","t":"练习是在第一个目标（通常约为一半）处开始，然后让其余的目标跟随。当止损向上移动时，目标也会移动，因此获胜者可以支付比第一个目标更多的费用。最初想法的风险并没有增加。强烈的信号并不是冒险 5% 的理由。同样使用 1%。道路是让强者成长的动力。"},{"h":"每日停开热","t":"一条常用规则：如果当天账户下跌约 2%，则停止开仓交易。三个开放想法各占 1%，热度约为 3%。五枚相关硬币是一注，而不是五枚。将它们一起数一下。"},{"h":"该方法拒绝什么","t":"不使用 Martingale（亏损后加倍）。不使用在进入后将停靠点进一步移动以“给它空间”。不使用“确定”信号的全押。如果没有有效止损，就没有规模，因此也就没有交易。"},{"h":"每笔交易的风险","t":"共同规则：仅针对单一想法承担约 0.5-1% 账户净值的风险。在 DEMO 中，练习与 LIVE 相同的百分比习惯。"},{"h":"头寸大小公式","t":"规模 ≈ (账户 × 风险%) ÷ (进场 − 止损距离)。更宽的 SL → 更小的尺寸。切勿先选尺码，再选 SL。"},{"h":"风险：回报","t":"学习时更喜欢潜在回报≥风险（例如 1:1.5 或更好）的想法。在 TP1 上进行扩展，这样跑步者就“无风险”。"},{"h":"部分止盈","t":"CPE风格：TP1锁定部分利润，TP2/追踪其余利润。银行部分减少了情绪恐慌。"},{"h":"追踪止盈+止损","t":"买入：随着价格上涨，跟踪水平也随之上升。卖出：下跌。跟踪锁定未平仓利润，无需完美的退出通知。"},{"h":"每日/每周损失限额","t":"规则示例：-2% 账户后的第二天停止交易。损失限额后的报复活动是账户杀手。"},{"h":"现货尺寸","t":"现货分钟概念很重要（例如交易所分钟）。仍然应用风险%：如果最小规模相对于您的止损风险太大，请跳过交易。"},{"h":"期货/杠杆","t":"杠杆会使利润和损失成倍增加。高杠杆+宽止损=账户爆仓。学习时喜欢低杠杆；孤立可以限制每个头寸的损失。"},{"h":"相关性","t":"开仓 5 个相关 BTC alts = 一大赌注，而不是五个。将风险作为一个整体进行计算。"},{"h":"费用和滑点","t":"紧缩的头皮在图表上看起来不错，但费用会吃掉 R:R。在了解成本之前，更喜欢在 DEMO 上进行更干净的挥杆。"},{"h":"演示 → 现场桥","t":"CPE DEMO 练习（约 3 个月的心态）：相同的期刊规则，相同的百分比。上线后，前几周开始使用一半的 DEMO 大小。"},{"h":"API资金安全","t":"每个按键都关闭提款功能。仅在匹配平台上测试账户OK后才能上线。错误的平台秘密 = 失败或危险的操作。"},{"h":"错误","t":"Martingale（损失后加倍）；将 SL 移得更远；全力以赴“确定”设置；忽略最小规模与风险百分比；交易无每日止损。"},{"h":"练习清单","t":"① 写入的风险百分比 ② SL 距离的大小 ③ 计划的 TP1/TP2/轨迹 ④ 已知的最大日损失 ⑤ 纸质优先 ⑥ 诚实地记录盈亏。"}]},{"id":"psych","title":"5 · 交易心理学","summary":"心态决定 BB/RSI/Fib 技能是否能够在真实屏幕中幸存。 FOMO、报复、过度自信、恐惧——用类似 DEMO 的指标来训练这些。","lessons":[{"h":"为什么心理学很重要","t":"如果您提前进入、跳过止损或报复性交易，那么完美的 BB+RSI 计划就会失败。技能=制度×纪律。"},{"h":"过程过度预测","t":"你不需要预测未来。您需要执行规则：设置→风险→管理→日志。结果各不相同；过程可控。"},{"h":"错失恐惧症","t":"害怕错过=追逐已经远离 BB/Fib 区域的绿色蜡烛。规则：如果您错过了入场，请等待下一次设置。图表实验室总是有另一根蜡烛。"},{"h":"报复性交易","t":"亏损后，“现在赢回来”的冲动会毁掉账户。强制冷却：走开，记录损失，只有在清单干净的情况下才能进行下一次交易。"},{"h":"胜利后过度自信","t":"连胜 3 场≠增加尺寸 5 倍。保持风险百分比固定。连胜是大多数人违反金钱规则的时候。"},{"h":"损失后的恐惧","t":"在红日之后跳过每一个有效的设置也是偏见。相信书面计划；如果需要，暂时缩小尺寸，不要放弃流程。"},{"h":"分析瘫痪","t":"10个指标不一致→冻结。坚持 CPE 核心：蜡烛 + BB + RSI（+ Fib 区域）。工具的质量胜于数量。"},{"h":"倾斜与新闻","t":"新闻上的大红蜡烛会刺激肾上腺素。在结构改革之前，在重大未知数期间倾向于保持平稳——自我想要采取行动；计划需要耐心。"},{"h":"期刊=治疗+数据","t":"在 CPE 日记中写下情绪标签（FOMO、匆忙、冷静）。情感模式比单独的损益表更能更快地揭示漏洞。"},{"h":"书面规则","t":"如果没有写下来，那就不是规则。示例：“仅 BB+蜡烛+RSI；风险 1%；-2% 天后不进行交易；DEMO 直至清单 20 份文件。”"},{"h":"环境","t":"睡眠、饥饿和电话干扰会改变决策。精疲力尽时不要夸大尺寸。交易是一项运动——保护大脑。"},{"h":"社交噪音","t":"电报“信号”和炒作打破了你的计划。 CPE学习课程+你的日记>随机提示。根据上下文而不是订单来过滤新闻和技巧。"},{"h":"身份转变","t":"认为“我遵循我的清单”而不是“我一定是对的”。小风险犯错是正常的；固执并承担巨大风险是可选的。"},{"h":"DEMO 作为健身房","t":"使用 DEMO/Paper 安全地排练情绪。如果你不能遵守 DEMO 上的规则，LIVE 也不会神奇地修复纪律。"},{"h":"练习清单","t":"① 我冷静吗？ ② 检查清单是否齐全？ ③ 风险百分比不变？ ④ 不报复？ ⑤ 我会诚实地写日记吗？如果有的话 → 没有交易。"}]},{"id":"signals","title":"6 · CPE 信号 — 含义和做什么","summary":"现货/期货/外汇交易台显示买入·卖出·持有+分数。每个平台上都有相同的引擎理念 - 但您只能在您保存了 API 密钥的平台上进行交易。以下是每个信号的含义以及出现后的具体步骤。","lessons":[{"h":"信号从哪里来","t":"CPE 得分 BB、RSI、斐波那契、烛台、EMA 交叉、SMA50、MACD 和动量。得分 ≥ +3 → 买入。分数 ≤ -3 → ​​卖出。介于两者之间 → 保持。这是一个辅助评级，而不是利润承诺。"},{"h":"买入信号——含义","t":"看涨汇合现在更强（例如：较低的 BB 反弹、RSI 超卖转向、看涨蜡烛、金叉、斐波那契支撑）。建议的 TP1 / TP2 / SL 出现在行/图表实验室/立即交易中。"},{"h":"卖出信号 — 含义","t":"看跌汇合更强（上方 BB/超买 RSI/看跌蜡烛/死亡交叉/斐波那契阻力）。在现货上，卖出通常意味着仅当您的市场允许空头（期货/外汇）时退出/减少多头或空头。"},{"h":"HOLD信号——含义","t":"混合或弱分数。不要强迫交易。平是正确的。观察列表 ★ 并等待更明确的买入/卖出或 BB 较低的候选者。"},{"h":"分数数","t":"更高|分数| = 工具之间更加一致。买入 +5 强于买入 +3 — 仍然在图表实验室蜡烛尺寸之前确认。"},{"h":"BB下板","t":"标记布林线下轨线的单独货币对列表 — 练习多头候选者。仍需蜡烛 + RSI 确认；并非每一次较低的触碰都是一次入场。"},{"h":"平台与信号（重要）","t":"Binance、Bybit、OKX、KuCoin、Bitget、Gate、MEXC、Kraken、Coinbase、OANDA、FXCM、MT5、Forex Demo 上的信号数学原理相同。发生变化的是您发送订单的位置：仅在 API 密钥/立即交易中选择的平台。 Binance BUY 不会在 Bybit 上打开。"},{"h":"加密货币现货平台","t":"Binance Spot、Coinbase 等：BUY = 以报价购买代币（例如 USDT）。 SELL = 卖出持股 / 获利。最小尺寸（例如~11 美元）很重要。没有杠杆。"},{"h":"加密货币期货平台","t":"币安期货、Bybit、OKX、Bitget…：买入=多头；卖出=做空。谨慎选择交叉/隔离+杠杆。追踪：买入追踪 TP+SL 向上；卖出下跌。"},{"h":"外汇平台","t":"OANDA / FXCM / MT5 / 外汇演示：外汇对（EURUSD…）上有相同的买入/卖出/持有标签。 BUY=买入基础货币； SELL = 卖出基地。手数（例如 0.01）而不是硬币数量。会议和新闻更重要。"},{"h":"当出现“买入”时——执行此操作","t":"① 打开行 → 阅读原因/蜡烛/RSI。 ② 图表实验室确认（15m–1H）。 ③ 先DEMO：立即交易→设置TP1/TP2/SL/trail→开始Demo/Paper。 ④ 只有在该平台上API测试OK后→小LIVE。 ⑤ 日记结果。"},{"h":"当出现卖出时——执行此操作","t":"① 如果您做多现货：考虑 TP/部分平仓/追踪 — 不要忽视。 ② 如果期货/外汇和计划允许做空：确认图表实验室，然后使用止损纸/实时做空。 ③如果昨天HOLD比较好，就不要报复翻转尺寸。"},{"h":"当 HOLD 出现时 — 执行此操作","t":"没有新的手动条目。继续扫描。添加★关注列表。研究学习课程/图表实验室。仅当已在交易中时才通过跟踪保护未平仓头寸。"},{"h":"自动交易+信号","t":"当 BB 较低 + 强分数规则与您保存的自动配置匹配时，自动购买即可打开。还是先DEMO测试Auto。 LIVE Auto = 真实风险 — 提款关闭，小额。"},{"h":"通知","t":"购买 信号祝酒词遵循您的语言。将它们视为打开交易台的警报，而不是本身的市场订单。"},{"h":"不该做什么","t":"不要在没有图表的情况下每次买入都买入。不要在 Bybit 上使用 Binance 密钥。不要跳过 SL。出现绿色信号后不要增大尺寸。不要将持有视为“几乎买入”。"},{"h":"快速行动卡","t":"信号 → 图表实验室 → 风险百分比 → TP1/TP2/SL → 演示论文 → 期刊 →（稍后）在匹配的平台密钥上实时发布。"}]},{"id":"forex_sig","title":"7 · 外汇信号 — 含义和操作","summary":"外汇柜台对外汇对使用相同的买入/卖出/持有评级。了解外汇信号与加密信号有何不同，以及信号 → 纸质 → 实时经纪商的具体步骤。","lessons":[{"h":"外汇柜台信号","t":"欧元兑美元、英镑兑美元、美元兑日元……像加密货币一样获得买入/卖出/持有+分数。单击一行查看图表、心理学文本和建议水平。"},{"h":"在外汇上买入 — 含义","t":"买入基础货币（例如买入 EURUSD = 买入欧元兑美元）。预计涨价。使用您练习的图表实验室外汇间隔 (15m/30m/1H)。"},{"h":"外汇卖出 — 含义","t":"卖出基础货币（做空该货币对）。预计价格下跌。始终将 SL 设置为高于结构/上带理念。"},{"h":"持有外汇","t":"没有清晰的边缘——跳过。尤其是在重大消息（NFP、CPI、央行）之前更倾向于持有/持平。"},{"h":"外汇模拟汇率平台","t":"没有 API 密钥。仅练习图表+纸。非常适合 OANDA/FXCM/MT5 上线前的学习课程练习。"},{"h":"OANDA 信号 → 行动","t":"① 外汇柜台买入/卖出。 ②图表实验室确认。 ③ API 密钥 → OANDA 代币 + 账户 ID → 测试。 ④ 首先是CPE中的DEMO Paper。 ⑤ 小现场地段（0.01 心态），带有 TP/SL/trail。"},{"h":"福汇/MT5","t":"相同的信号读数。在 API 密钥下连接该经纪人的凭据。在设置按键/桥之前，Signal 不会自动登录 MT5 — 练习纸上练习，直到测试正常。"},{"h":"会议","t":"伦敦和纽约的重叠往往会导致专业的变化更大。亚洲可能比较安静——持有是常见且健康的。"},{"h":"传播与新闻","t":"围绕新闻，利差扩大——良好的技术性买入仍然可能是一个糟糕的补仓。查看新闻和技巧；等待峰值后蜡烛收盘。"},{"h":"手数与加密数量","t":"外汇规模=手数，而不是名义上的USDT。风险百分比仍然占主导地位：更宽的止损 → 更小的手数。"},{"h":"外汇 BB 走低","t":"同样的想法：货币对接近下轨线 + 锤子线 + RSI 上升 = 练习长期学习。确认较高的 TF 偏差（4 小时/每日）。"},{"h":"当外汇买入触发时 — 步骤","t":"① 阅读原因。 ② 较高的 TF 偏差可以吗？ ③ 在灯芯/结构之外标记 SL。 ④ 纸品贸易。 ⑤ 如果现场经纪商准备就绪 → 小尺寸 + 踪迹。 ⑥ 日记会议（伦敦/纽约）+情感。"},{"h":"当外汇卖出触发时——步骤","t":"① 确认不是中间新闻高峰。 ② 图表实验室看跌蜡烛。 ③纸短或合长。 ④ 如果短则向下追踪。 ⑤ 错过后请勿重复抽签。"},{"h":"外汇与加密货币的区别","t":"加密货币 24/7；外汇有交易时段。加密货币经常最低$；外汇手数+点值。加密许多替代品相关；外汇专业清洁工学习。"},{"h":"练习清单（FX）","t":"① 双专业？ ② 会议还好吗？ ③消息清楚吗？ ④ 买入/卖出信号不持有？ ⑤ 图表确认？ ⑥ 风险%？ ⑦ 纸质 → 期刊 → 现场经纪人密钥仅在准备好时。"}]},{"id":"fomo","title":"8· FOMO 与情绪纪律","summary":"FOMO、报复、贪婪和恐惧才是真正的账户杀手，而不是指标。了解触发因素、身体迹象以及阻止冲动交易的确切规则。","lessons":[{"h":"FOMO 到底是什么","t":"FOMO = 害怕错过已经远离你的区域的举动。它会让您以更差的价格进入较晚且没有适当的止损。您“错过”的蜡烛是信息，而不是损失。"},{"h":"FOMO 的三个触发因素","t":"① 图表上的大绿色或红色蜡烛。 ② 显示盈利的朋友或 Telegram 帖子。 ③ 新闻标题。在注意到条目之前先注意触发器。"},{"h":"身体体征","t":"心跳加快，靠在屏幕上，有一种点击市场立即购买的冲动，跳过你的清单。如果您有这种感觉，请关闭标签并等待一根蜡烛。"},{"h":"“已经运行”规则","t":"如果价格的变动超过您计划的入场点的大约 1 ATR，交易就会消失。等待回调至 BB 中线 / Fib 或跳过它。总是有另一种设置。"},{"h":"绿色蜡烛陷阱","t":"你没有计划的丸坊主是一次追逐，而不是一次进入。迟到的回报最差：风险，因为终点站距离很远。"},{"h":"报复性交易","t":"失去之后，大脑现在想要赢回来。规则：丢失后 15 至 30 分钟内不得添加新条目，且仅限检查清单干净的情况下。市场不欠你什么。"},{"h":"害怕扣动扳机","t":"相反的问题：完美的设置出现，但你却冻结了。使用微小的演示尺寸来证明该过程，并在蜡烛出现之前决定尺寸，以便已经做出决定。"},{"h":"胜利后的贪婪","t":"两次绿色交易让你感觉所向披靡，然后你的体型就翻倍了。至少 20 笔交易的风险百分比保持固定；连胜意味着回归。"},{"h":"无聊交易","t":"平是一种立场。如果不存在 A+ 设置，请不要发生任何事情。无聊交易是变相的 FOMO。"},{"h":"屏幕时间纪律","t":"每天设置两个或三个扫描窗口，而不是盯着图表。更少的决定意味着更少的冲动决定。"},{"h":"情感日记","t":"标记每笔交易冷静/仓促/FOMO/报复。 20 次交易后，您的泄漏模式就会变得明显。"},{"h":"重置仪式","t":"遭受损失或 FOMO 失误后：站起来，缓慢呼吸 10 次，写下一句话描述发生的事情，然后停下来一小时，或者以正常风险的一半继续。"},{"h":"练习清单","t":"① 身体平静？ ② 触发注意到了吗？ ③ 在我的区域中设置？ ④ SL先写吗？ ⑤ 风险百分比不变？ ⑥ 不报仇？任何“否”→ 禁止交易。"}]},{"id":"risk_deep","title":"9 · 风险与资金管理 — 深入","summary":"保持账户活力的数学原理：固定分数规模、R 倍数、回撤数学、相关热度和每日止损。将交易变成一项靠数字运作的生意。","lessons":[{"h":"固定部分风险","t":"每个想法的固定百分比 (0.5–1%) 的权益都存在风险。尺寸是停止距离的结果，而不是首先选择的。宽SL→小尺寸；紧SL → 较大尺寸；美元风险保持不变。"},{"h":"尺码计算公式","t":"规模 = (权益 × 风险%) ÷ |入场 − 止损|。示例：1000 美元 × 1% = 10 美元风险。入场 100，止损 98 → 距离 2% → 规模 10 ÷ 0.02 = 名义金额 500 美元。"},{"h":"用 R 倍数思考","t":"每笔交易的风险为 1R。 2R 获胜者要为两次失败付出代价。跟踪您超过 20 笔交易的平均 R — 这是您的真正优势，而不是胜率。"},{"h":"奖励：风险","t":"进入之前目标是至少 1.5R 的潜力。低于此，请跳过它，除非您的胜率非常高。"},{"h":"回撤数学","t":"−50% 的亏损需要 +100% 才能恢复。连败是正常的：即使是 60% 的胜率系统也会有 5 次以上的损失。小风险可以让连胜得以延续。"},{"h":"每日停止","t":"硬性规则：一天内净值达到−2%（或连续 2-3 次亏损）后停止开仓交易。超过限制后的报复会话是帐户杀手。"},{"h":"每周和每月限额","t":"还要限制周（例如 -5%）和月。当击中时，下降到演示，查看日志，然后仅在干净运行后恢复大小。"},{"h":"开热","t":"所有未平仓交易的总风险应保持在 3% 左右或更低。五个相关替代品是一个赌注，而不是五个 - 将相关暴露一起计算。"},{"h":"现货尺寸","t":"现货有最低名义金额。如果交易所最低风险超过 1%，请跳过交易 — 切勿将风险四舍五入。"},{"h":"期货规模","t":"杠杆改变保证金，而不是风险。风险仍然是入场-止损×规模。在学习时使用低杠杆，并且更喜欢逐仓保证金。"},{"h":"外汇规模","t":"风险 = 手数 × 点值 × 止损点。解决很多。粗略指南：0.01 手 ≈ 每点 0.10 美元； 20 点止损，风险为 1000 美元 ($10) 的 1% → 10 ÷ 0.10 ÷ 20 = 0.05 手。"},{"h":"横向扩展","t":"在 TP1 处采取约 50% 的折扣，使其余部分无风险，然后进行跟踪。这将良好的交易变成了低压力的跑步者。"},{"h":"复利与固定","t":"以当前权益的固定百分比承担风险（复利）。不要以历史最高的账户规模来解决您的风险。"},{"h":"R 中的费用和滑点","t":"从 R 中减去费用。相对于 0.5% 的头皮，0.2% 的费用可以消除边缘——更喜欢更干净的波动。"},{"h":"“不停止，不贸易”法","t":"如果您无法定义逻辑止损，您就不知道自己的风险，因此没有规模，也就没有交易。"},{"h":"反鞅","t":"亏损后切勿加倍。只有在经过数周的盈利、严格的、经过验证的流程后才能扩大规模——而且即使如此也要缓慢。"},{"h":"练习清单","t":"① 已知权益 ② 写入风险百分比 ③ 定义止损 ④ 距止损的大小 ⑤ 奖励 ≥ 1.5R ⑥ 已知每日止损 ⑦ 计算相关热度。"}]},{"id":"sl_tp","title":"10 · 止损和止盈掌握","summary":"将止损放在市场证明您错误的地方，逐步获利，并跟踪止损，以便赢家可以运行 - 这正是 CPE 对多重止盈和跟踪止损所做的操作。","lessons":[{"h":"SL 是一个决定，而不是一个数字","t":"将止损放置在想法无效的地方（低于摆动低点、烛线或结构），而不是随机的美元距离。您正在购买信息：如果价格达到这里，我的理由就是错误的。"},{"h":"结构停止","t":"多头：止损位于摆动低点或下轨影线下方。空头：就在摆动高点之上。为传播和灯芯噪音提供一个小的缓冲，大约 0.1-0.3%。"},{"h":"波动停止","t":"更广阔的市场需要更广泛的止损。使用 ATR 或灯芯长度来确定止损大小，然后缩小头寸，使美元风险保持不变。"},{"h":"为什么固定美元止损会失败","t":"BTC 的 10 美元止损和 EURUSD 的 10 美元止损是完全不同的风险。距离必须以百分比而非美元来衡量。"},{"h":"防停止搜索缓冲区","t":"CPE 忽略单个灯芯接触：它需要两次连续突破加上一个小缓冲 (0.15%) 才能关闭。这样可以防止噪音干扰您的止损。"},{"h":"逐步获利","t":"永远不要以一个价格 100% 平仓。横向扩展：TP1 预订部分，然后 TP2/trail 乘坐其余部分，因此大的变动可以为许多失败者付出代价。"},{"h":"多TP级别","t":"CPE 允许您根据需要添加任意数量的 TP 水平，每个水平都有自己的收盘百分比。示例：TP1 40%、TP2 30%、TP3 30% — 或采用 TP1 并跟踪其余部分。"},{"h":"尾随停靠站","t":"TP1后将止损移至盈亏平衡点； TP2之后将其移至TP1。让止损跟随价格，这样在跑动继续的同时，未平仓利润也能得到保护。"},{"h":"选择路径 %","t":"紧逼的轨迹可以快速锁定利润，但会提早退出；一条宽阔的小路呼吸着，但也带来了一些回馈。从加密货币的 1-2% 左右开始，然后在“位置”编辑模式中对其进行调整。"},{"h":"跑步者","t":"当价格在强势趋势中运行时，扩大目标并追踪，而不是在 TP2 处采取一切措施。这就是一笔交易一整周的支付方式。"},{"h":"部分关闭按钮","t":"使用持仓中的 50% / 100% 平仓按钮进行手动控制，或让自动平仓按计划管理 TP / SL。"},{"h":"盈亏平衡陷阱","t":"不要在 TP1 之前过早地将止损移动到盈亏平衡点——正常的回调会让你失去良好的交易。"},{"h":"切勿扩大亏损止损","t":"将止损移得更远，为其留出空间，这就是小损失如何成为账户杀手的原因。您在入场前设定的停靠站即为停靠站。"},{"h":"时间停止","t":"如果一笔交易对许多蜡烛没有任何作用，而明显更好的设置形成，平仓并重新部署风险是有效的退出。"},{"h":"练习清单","t":"① 无效时的 SL，不是随机的 ② 灯芯缓冲区 ③ TP1 部分计划 ④ TP1 后的跟踪 ⑤ 切勿扩大 SL ⑥ 让赢家运行。"}]},{"id":"plan_journal","title":"11 · 贸易计划和日记","summary":"书面计划将交易从赌博变成了一个过程。了解一页计划、交易前清单以及如何记录日志，以便让您的漏洞变得可见。","lessons":[{"h":"为什么要写计划","t":"如果没有写出来，那就不是规则。计划可以消除压力下的实时决策，并使您的结果可衡量。"},{"h":"一页计划","t":"货币对、市场、设置（BB + RSI + 蜡烛 + Fib 区域）、方向、入场、止损、TP1 / TP2、规模（从止损开始）和最大每日损失。如果任何行为空白 → 没有交易。"},{"h":"交易前清单","t":"更高的 TF 偏差？ · 在我的区域中设置？ · 蜡烛确认？ · RSI 同意吗？ · SL 写好了吗？ · 风险 ％？ · 奖励≥1.5R？ · 冷静的？全部是 → 贸易。"},{"h":"会前例行公事","t":"查看更高的时间范围、关键水平和新闻。在会议之前写下今天的两到三对手表，而不是在蜡烛爆炸之后。"},{"h":"写什么日记","t":"符号、侧面、进入、退出、大小、R、原因、时间范围、会话和情感标签。 CPE日志自动保存损益及原因；添加您自己的注释。"},{"h":"记录原因","t":"记录你所看到的（设置）和你所感受到的（冷静/害怕错过/匆忙）。没有背景的结果没有任何意义。"},{"h":"赛道R，不是胜利","t":"具有相同胜率的两个交易者可能会得到相反的结果。平均 R 和最大回撤比获胜百分比更重要。"},{"h":"截图习惯","t":"在每次交易之前和之后保存图表。查看 20 张屏幕截图可以比任何指标更快地显示您的优势和漏洞。"},{"h":"每周回顾","t":"每周统计一次您的交易、平均 R、最佳和最差设置以及违反规则的情况。选择下周修复的一个泄漏点。"},{"h":"标记泄漏","t":"常见标签：迟到、无SL、超大、感动SL、复仇、无聊。当标签重复时，将其变成硬性规则。"},{"h":"不应该记录什么","t":"不要只记录获胜者。损失就是数据。一本只有胜利的杂志是一本小册子，而不是一本杂志。"},{"h":"规划 DEMO → LIVE 步骤","t":"在用真钱冒险之前，在 DEMO 上证明一定数量的平均 R 为正的交易计划 - 然后从一半的规模开始。"},{"h":"练习清单","t":"① 入职前写好计划 ② 通过检查表 ③ 日记+情感 ④ 每周回顾 ⑤ 修复一处漏洞。"}]},{"id":"leverage","title":"12 · 杠杆、保证金和清算","summary":"杠杆倍增损失的速度与倍增利润的速度一样快。了解保证金、清算、逐仓保证金与全仓保证金，以及阻止一笔交易抹去账户的安全规则。","lessons":[{"h":"什么是杠杆","t":"杠杆可以让您以更少的保证金控制更大的头寸。它会增加利润和损失——但不会增加你的优势。"},{"h":"保证金与风险","t":"保证金是交易所锁定的保证金。风险是入场-止损×规模。杠杆改变保证金，而不改变您的美元风险。"},{"h":"清算","t":"如果损失耗尽了您的保证金，交易所通常会在最糟糕的时间强制平仓（清算）。让你的止损远离强平价格。"},{"h":"孤立与交叉","t":"孤立将损失限制在该头寸的保证金范围内。 Cross 使用整个钱包余额——对于初学者来说更危险。学习时更喜欢孤立。"},{"h":"更安全的杠杆","t":"低杠杆（2-5 倍）加上适当的止损比不设止损的 50 倍安全得多。止损，而不是杠杆数字，才是您的保护。"},{"h":"清算距离规则","t":"检查您的止损是否位于强平价格以内。如果它们很近，请减小尺寸，直到有舒适的空间。"},{"h":"杠杆并不能修复错误的入场点","t":"错误入场的高杠杆只会损失得更快。首先修复设置，然后调整大小。"},{"h":"资金和费用","t":"永续期货随着时间的推移收取资金费用。长期持有杠杆永续经营者会导致资金流失——这​​是谨慎调整规模和时间的另一个原因。"},{"h":"现货与期货","t":"现货无法清算（您拥有代币）。期货可以而且可以归零。仅在有书面计划和逐仓保证金的情况下使用期货。"},{"h":"杠杆下的规模调整","t":"根据停止距离计算尺寸，然后检查所得的余量是否可以承受。永远不要先选择杠杆。"},{"h":"“一次交易”测试","t":"进入之前先问一下：如果这停下来，是耸肩还是一场灾难？如果不是耸肩，那就是尺寸太大了。"},{"h":"练习清单","t":"① 孤立设置 ② 低杠杆 ③ 强平价格内的止损 ④ 止损尺寸 ⑤ 我能承受这里的全部损失吗？是→贸易。"}]},{"id":"practice","title":"13 · 日常练习和回测","summary":"技能是在 LIVE 之前建立在 DEMO 上的。学习可重复的练习循环，如何通过滚动图表进行“回测”，以及如何安全地升级到真钱。","lessons":[{"h":"DEMO是健身房","t":"纸/演示的存在是为了以零风险排练流程和您的情绪。如果你不能遵守DEMO上的规则，LIVE不会神奇地解决它。"},{"h":"练习循环","t":"选择一种设置（例如 BB 降低 + Hammer + RSI 转向）。在图表上标记 20 个历史例子。定义入场/止损/止盈。记录结果。重复。"},{"h":"手动回测","t":"在图表实验室中向后滚动，隐藏未来，并手动标记每个信号。它训练模式识别并阻止你欺骗自己。"},{"h":"样本量","t":"十笔交易毫无意义。在判断一种设置之前，目标是记录 30-50 笔交易。"},{"h":"DEMO 前向测试","t":"手工标记后，使用软件信号在 DEMO 上实时运行相同的设置两到四个星期。将真实的填充和情绪与回测进行比较。"},{"h":"一次设置一个","t":"不要同时测试五个系统。掌握一个边缘，然后添加第二个边缘。"},{"h":"保持例行小事","t":"20 分钟的日常工作（扫描、标记、日记、回顾）胜过 6 小时的随机查看图表。"},{"h":"毕业进入直播","t":"标准：超过 30 笔演示交易的平均 R 值为正，遵守规则，没有报复事件。然后以一半大小开始 LIVE，并慢慢缩放。"},{"h":"放大规则","t":"只有在一定数量的盈利、有纪律的几周后才能扩大规模，而不是在取得一场大胜利之后。"},{"h":"何时退一步","t":"达到每日或每周损失限制，或注意到反复违反规则 → 返回 DEMO 并在继续之前重建纪律。"},{"h":"跟踪流程指标","t":"记录检查表通过率、每周违规情况和平均 R。这些比单个损益数字更好地预测增长。"},{"h":"CPE实践路径","t":"学习课程→图表实验室（标记设置）→纸质交易→期刊评论→DEMO上的信号台→匹配平台密钥上的小LIVE。"},{"h":"练习清单","t":"① 选择一种设置 ② 标记 30 个示例 ③ DEMO 前向测试 ④ 期刊 + 评论 ⑤ Positive R → half-size LIVE。"}]},{"id":"volatility","title":"14 · 波动性和鞅","summary":"如何解读市场波动性（价格为何变化）、如何将其作为原因线添加到每个信号中，以及可选的 Martingale 阶梯如何工作 - 以及为什么它是在不小心使用时失去账户的最快方式。","lessons":[{"h":"波动性意味着什么","t":"波动性是指价格变动的幅度，而不是向哪个方向变动。高波动性=宽蜡烛线和快速波动。低波动性=安静、窄幅波动。相同的设置在每个设置中具有非常不同的可靠性。"},{"h":"CPE 波动率读数","t":"现在，每个信号都会测量平均蜡烛范围和布林带宽度，然后将它们与该货币对最近的正常值进行比较。您会得到低/正常/高/极端加上一条简单语言的原因线——市场变化的“原因”，与信号一起显示。"},{"h":"极度波动=降级","t":"当磁带处于“极端”状态时，新的“强”信号会降级为“小心”（已显示原因）。在洗盘市场中，同样的模式失败的次数要多得多——假突破和止损寻找影线是常态。"},{"h":"HIGH / EXTREME 可以做什么","t":"尺寸较小。更宽的停止。交易量减少。等待一根完整的蜡烛而不是中间的蜡烛尖峰。如果读数显示“极端”，请将设置视为研究区域，而不是入口。"},{"h":"什么是马丁格尔","t":"Martingale 会增加亏损头寸以降低平均入场额：在每次不利走势后，您会添加另一个订单，通常更大（1 倍、2 倍、4 倍……）。它经常获胜，然后在一次糟糕的比赛中失去一切。"},{"h":"CPE 鞅规则","t":"仅当两者都为真时，CPE 才会添加额外订单：(1) 价格已向交易方向变动至少步长 × 梯级 %，并且 (2) 新的同侧信号仍代表该货币对。它永远不会仅仅因为价格下降而增加。"},{"h":"四个数字","t":"步骤 % = 每次添加之前需要的反向移动。乘数 = 每个加法的大小与基数的比较（1 = 平，2 = 双）。最大添加量 = 额外订单的硬性限制。阶梯风险上限% = 整个阶梯的风险占权益的百分比。所有四个都由您选择。"},{"h":"硬顶保护你","t":"即使有很大的乘数和很多加法，一旦阶梯的总风险超过你的净值百分比上限，CPE 就会拒绝订单。它还尊重交易所的最小规模和每日 -2% 的止损。"},{"h":"它运行在哪里","t":"在手动上勾选它以管理该一笔交易，或在自动会话上勾选它以管理其自动交易。演示版和现场版都有。在手动模式下，该对必须位于扫描列表中，以便可以读取新的同侧信号。"},{"h":"为什么上限很重要（示例）","t":"步骤 1%，乘数 2，在 1% 风险基础上加三：风险为 1% → 2% → 4% → 8%。最后一级的一次完全止损会抹掉许多赢家。这就是为什么存在上限以及默认数字很小的原因。"},{"h":"反鞅替代方案","t":"许多专业人士的做法恰恰相反：只增加盈利的股票，快速减少亏损的股票。感觉更糟（更多的小损失），但它不能在对你不利的单一趋势中炸毁账户。"},{"h":"风险并未消除","t":"平均下跌并不能消除风险——它将风险从“许多小损失”转移到“一个大损失”。切勿添加您不会损失的资金，也切勿关闭上限以“恢复”亏损的交易。"},{"h":"实践路径","t":"首先学习 DEMO 上的波动率读数。尝试在 DEMO 上使用 Martingale 最大加法 1-2 和小乘数进行 30 笔以上的交易。记录每个阶梯，然后做出决定——大多数交易者发现持平/反鞅方法更安全。"},{"h":"波动性+马丁格尔清单","t":"① 首先读取波动水平 ② 在 EXTREME 中跳过或收缩 ③ 仅使用新的同侧信号进行马丁格尔 ④ 达到步骤 × 梯级 ⑤ 在风险上限下 → 添加。任何“否”→不添加。"}]},{"id":"lab_indicators","title":"15 · 图表实验室指标（Stoch · ADX · Ichimoku · VWAP）","summary":"图表实验室现在有一个完整的指示栏 - 每个按钮都是一个开/关勾，可以立即重新绘制图表。除了 BB / RSI / MACD / EMA / SMA50 / Volume 之外，您现在还可以获得随机指标、ADX/DMI、Ichimoku 和 VWAP，并且信号引擎也会读取它们 - 不仅仅是图表。","lessons":[{"h":"酒吧在哪里","t":"图表实验室 → 图表下方的“指标”按钮行。单击一下可打开指示灯，再单击一下可将其关闭；图表立即重新绘制。蜱虫是可见的，它们为信号引擎提供信号。"},{"h":"随机 (14,3,3)","t":"%K / %D 震荡指标绘制在蜡烛下方，刻度范围 0–100。高于 ~80 = 超买区，低于 ~20 = 超卖区。 %K 在超卖区域穿越 %D 是一项看涨研究；顶部向下的十字是看跌的。在强劲趋势中，它可以长期固定在一端——始终与 BB 线和蜡烛相结合。"},{"h":"ADX/DMI (14)","t":"ADX 衡量的是趋势强度，而不是方向。高于 ~25 = 真正的趋势正在运行；低于 ~20 = 波动范围。 +DI 以上 -DI = 负责买家； −DI 以上 +DI = 负责卖家。使用 ADX 来决定是进行趋势交易还是保持平稳。"},{"h":"一目均衡表云 (9,26,52)","t":"Tenkan（快线）、Kijun（慢线）和 Senkou 云。价格高于上升云=看涨背景；低于乌云=看跌。云内的 Tenkan/Kijun 交叉较弱；价格离开云的交叉更强。云边缘本身通常充当支撑/阻力。"},{"h":"车辆加权平均价格","t":"成交量加权平均价格 — 按成交量加权的平均价格，每个时段重置。大型机构以此为基准。价格高于上涨的成交量加权平均价格=买家掌控；在下降趋势期间明确拒绝 VWAP 是一项简短的研究。在 24/7 加密货币上，它的重置方式与 FX 上的不同——将其视为指导方针，而不是法律。"},{"h":"引擎如何使用它们","t":"每个新指标都会对其指向的同一侧的分数添加一个小确认（随机指标、Ichimoku、VWAP、ADX（当其与方向一致时）以及艾略特指标）。它们是确认，而不是触发因素——如果它们与 BB / RSI / 蜡烛不一致，分数就会变得更加复杂，你会得到更多的持有。"},{"h":"为什么 CAUTION 变得更加严格","t":"由于池中现在有更多检查，因此收紧了“注意”栏：需要得分 ≥ 4 并且至少有 3 个同意检查。这可以防止应用程序仅仅因为打开了更多工具而向您发送较弱的信号。"},{"h":"有效的阅读顺序","t":"① 较高 TF 方向（一目均衡表云 + ADX）。 ② 价格为（BB / Fib / VWAP）。 ③ 动量（RSI + 随机指标）。 ④ 蜡烛确认。 ⑤ 所写的风险百分比和级别 → 首先是论文。"},{"h":"要避免的错误","t":"打开每一个指示灯，凝视彩虹；使用 ADX 作为方向（它只是强度）；仅因为牛市内随机指标 >80 才做空；忽略 VWAP 对加密货币和外汇而言意味着不同的东西。"},{"h":"练习清单","t":"① 来自云端的偏差 + ADX ② 来自 BB / Fib / VWAP 的位置 ③ 来自 RSI + Stoch 的动能 ④ 蜡烛确认 ⑤ SL / TP 写入 ⑥ 论文，然后是日记。"}]},{"id":"elliott","title":"16·艾略特波浪（光计数）","summary":"CPE 包括一个轻量级艾略特波浪计数器。在图表实验室指标栏中勾选“艾略特”，它会标记蜡烛上的最后一个 0-1-2-3-4-5 脉冲，并预测第 5 波斐波那契目标。它是一个学习工具，而不是一个水晶球。","lessons":[{"h":"一行的想法","t":"市场波动：推动（5 个趋势方向）和修正（3 个趋势方向）。 CPE只计算冲动，也就是承载趋势的部分。"},{"h":"CPE是如何计算的","t":"它找到最后的波动枢轴（3 条形分形），交替高/低，并根据艾略特规则测试最后 5-6 个波动。如果形状合适，它会绘制 0→5 标签（仍在运行的黄色波浪）和根据第 4 波测量的第 1 波长度 × 1.618 构建的 W5 目标线。"},{"h":"它检查的规则","t":"第 2 波未经过第 1 波的起点；第 4 波与第 1 波的领土不重叠；第 3 波不是 1 / 3 / 5 中最短的一个。当规则失败时，它不会显示任何内容 - 没有强制计数。"},{"h":"看涨与看跌","t":"上升的 0-1-2-3-4-5 是看涨冲动；下跌过程中的镜像是看跌的。引擎对波浪一侧的分数添加了一个小确认。"},{"h":"实时与完整","t":"实时波浪 5（仍在运行）被解读为趋势延续。完整的冲动（0-5 结束）警告趋势可能令人疲倦——随后通常会出现修正。"},{"h":"W5目标线","t":"波 1 从波 4 低点/高点的斐波那契延伸。它是一个目标想法，而不是一块磁铁——价格可能会低于它或超过它。"},{"h":"如何使用","t":"将计数视为汇合：在带有蜡烛和 RSI 的清晰 BB / Fib 区域，冲动计数会增加信念。它本身只是一个草图。"},{"h":"要避免的错误","t":"重新计算波浪，直到它们适合您的位置（经典的艾略特罪恶）；计算微小的摆动；忽略较高的时间范围计数；忘记每次打印新条时计数都会改变。"},{"h":"练习清单","t":"① 明确的波动选择 ② 规则通过 ③ Zig-zag 与 BB / Fib 一致 ④ 蜡烛确认 ⑤ SL 超出第 4 波无效点。"}]},{"id":"forecast","title":"17 · 3 个月预测（预测 3M 刻度线）","summary":"长期投影仪：根据信号自身的趋势、目标和波动性构建该图表在未来约 3 个月内可能如何形成。通过图表实验室中的“Forecast 3M”勾选来打开或关闭它。","lessons":[{"h":"它画什么","t":"一条虚线中心路径，从分析的入场点走向引擎已知的最佳目标（艾略特目标 → tp2 → tp1），包裹在一个不断扩大的“圆锥体”中，显示合理价格的价差。月份标记 M+1 / M+2 / M+3 划分地平线。"},{"h":"为什么是圆锥而不是直线","t":"没有人能知道确切的未来价格。圆锥体随着时间的平方根和货币对自身的波动性而变宽，因此安静的外汇货币对会得到一个狭窄的圆锥体，而狂野的山寨币则会得到一个非常宽的圆锥体。这个宽度就是这样的信息：你看得越远，价格就越不确定。"},{"h":"数字从何而来","t":"漂移来自当前信号目标；每日波动率来自信号的 ATR% 缩放至一天，因此锥体在 5m 或 1d 图表上的含义相同；极端/高波动性进一步扩大了其范围。"},{"h":"如何阅读","t":"查看坡度（路径倾斜的方向）和宽度（有多少疑问）。窄锥体的上升路径 = 更稳定的趋势理念；带有巨大锥体的平坦路径=“这里没有边缘，预计会有噪音”。"},{"h":"打开和关闭它","t":"“预测 3M”按钮位于“未来空间”旁边。它需要Future space ON（右侧绘制投影的空白区域）。如果信号为 HOLD，则没有方向，因此不会绘制任何内容。"},{"h":"这是趋势，而不是贸易","t":"预测是一张大图。实际交易水平——入场价、TP1/TP2、止损和短期预测——仍然是您交易的内容。"},{"h":"诚实的限度","t":"新闻、上市、退市和宏观转变不在模型中；该路径是平滑的漂移，因此实际价格会波动更大； 3个月的锥体是一种学习帮助，而不是一个承诺。"},{"h":"经常重新分析","t":"随着新蜡烛的出现，目标、波动性以及整个锥体都会更新。预测只是一个快照，而不是合同。"},{"h":"练习清单","t":"① 读取路径方向 ② 检查锥体宽度 ③ 与更高 TF 结构进行比较 ④ 从实际 SL 确定位置尺寸，切勿从锥体确定位置尺寸。"}]}],"platforms":{"BINANCE":{"title":"币安交易 A → Z","steps":["创建帐户 → 启用 2FA。","API管理→创建密钥→现货和/或期货交易开启，提款关闭。","在 CPE → API 密钥 → Binance → 保存 → 测试帐户中粘贴密钥 + 密钥。","使用现货柜台/期货柜台扫描（公共图表甚至可以在密钥之前使用）。","做法：手动交易→开始模拟交易（无活钱）。","实时：设置TP1/TP2/SL +追踪→开始实时交易（需要API）。","仓位管理：编辑级别、部分平仓、取消自动。","许可证：试用 7 天 → 3 个月或终身（应用程序中的所有者价格）。"]},"BYBIT":{"title":"Bybit交易A → Z","steps":["帐户+2FA。","API 管理 → 仅交易，提款关闭。","CPE → API 密钥 → Bybit → 保存。","面向犯罪分子心态的期货柜台；研究蜡烛的图表实验室。","纸品贸易第一；钥匙工作后生活。","追踪 TP+SL：买入↑ / 卖出↓。"]},"OKX":{"title":"OKX 交易 A → Z","steps":["需要 API 密钥 + 秘密 + 密码。","提款始终关闭。","将所有三个字段保存在 CPE 密钥中。","纸张练习 → 小尺寸。","密码拼写错误是第一大失败——仔细复制。"]},"KUCOIN":{"title":"库币交易 A → Z","steps":["密钥+秘密+密码。","仅贸易许可。","纸在CPE→然后住小。","使用现货/期货交易台获取信号。"]},"BITGET":{"title":"Bitget交易A→Z","steps":["仅包含贸易的 API。","纸则活。","期货：手动交易中选择交叉或逐仓。","追踪TP+SL以锁定利润。"]},"GATE":{"title":"Gate.io交易A→Z","steps":["创建 API v4 密钥（交易）。","提款关闭。","保存在CPE→练习纸中。","直播前扫描+图表实验室查看参赛作品。"]},"MEXC":{"title":"MEXC 交易 A → Z","steps":["开始现货心态。","CPE API 密钥中的密钥。","纸→活。","使用追踪来锁定未平仓利润。"]},"KRAKEN":{"title":"海妖交易 A → Z","steps":["仅在具有交易许可的情况下生成密钥。","没有提款/资金权利。","CPE 论文练习。","还验证 Kraken 上的每个实时订单。"]},"COINBASE":{"title":"Coinbase 高级 A → Z","steps":["高级贸易 API 密钥。","CPE 中的聚焦办公桌。","纸则活。","关闭提款。"]},"FOREX_OANDA":{"title":"外汇 (OANDA) A → Z","steps":["打开 OANDA 演示 → 风险约 1%。","CPE 密钥中的个人访问令牌 + 帐户 ID。","外汇柜台扫描 + 图表实验室（欧元兑美元……）。","手动交易 → 外汇平台纸质交易。","只有在演示信心之后才能生活。"]},"FOREX_FXCM":{"title":"福汇外汇 A → Z","steps":["经纪商 API 凭证。","首先是 CPE 论文。","观看伦敦/纽约会议和新闻高峰。","练习后的生活日记看起来很干净。"]},"FOREX_MT5":{"title":"0A→Z","steps":["CPE 密钥中的登录名 + 服务器 + 密码。","尽可能选择投资者（读取）密码。","练习手数 0.01。","CPE纸；准备好后通过经纪人进行直播。"]},"FOREX_DEMO":{"title":"外汇模拟汇率 A → Z","steps":["无需 API 密钥。","外汇服务台 + 图表实验室提供免费图表。","仅进行模拟交易（练习）。","当准备好使用真正的经纪商时，请添加 OANDA / FXCM / MT5 密钥进行实时操作。"]}},"forexAz":{"title":"外汇交易 A → Z（全班）","lessons":[{"h":"A — 账户和风险","t":"先演示一下。每个想法的风险约为 0.5–1%。绝不进行报复性贸易。"},{"h":"B——对","t":"主要货币（欧元兑美元、英镑兑美元、美元日元）先于外来货币。"},{"h":"C——蜡烛","t":"在图表实验室外汇上学习十字星、锤子、吞噬。"},{"h":"D——每日偏差","t":"在 15m/30m 进入之前检查更高的时间范围。"},{"h":"E——条目","t":"BB 下方反弹 + 蜡烛确认是常见的做法设置。"},{"h":"F——斐波那契","t":"50% / 61.8% 回调通常用作练习区域。"},{"h":"G——目标（TP）","t":"TP1 横向扩展、TP2 运行器、跟踪 SL。"},{"h":"H——小时","t":"伦敦-纽约重叠=更多移动。"},{"h":"I——指标","t":"RSI + MACD + BB 一起；避免指示器过载。"},{"h":"J——日记","t":"在 CPE Journal 中记录每笔纸质/实时交易。"},{"h":"K——按键","t":"实时外汇经纪商需要 API/代币；演示率不需要。"},{"h":"L——很多","t":"从 0.01 手开始练习心态。"},{"h":"M——心态","t":"过程超过预测。跳过糟糕的日子。"},{"h":"N——新闻","t":"在大型活动之前查看新闻和技巧。"},{"h":"O——订单","t":"始终设置 SL。追踪可以保护未平仓利润。"},{"h":"P——练习","t":"模拟交易按钮 = 没有实时 API 的练习。"},{"h":"Q——质量","t":"更少的高质量设置胜过过度交易。"},{"h":"R——风险：回报","t":"尽可能将设置目标设定为回报≥风险。"},{"h":"S——会话","t":"亚洲较为安静；伦敦/纽约更加活跃。"},{"h":"T——趋势","t":"学习时以更高 TF 的趋势进行交易。"},{"h":"U——更新","t":"观看 CPE 更新横幅 + 实时帮助。"},{"h":"V——波动性","t":"当 ATR 飙升时，请保持耐心。"},{"h":"W — 提款 API","t":"切勿对任何 API 密钥启用提款。"},{"h":"X — 退出","t":"部分 TP + 线索击败希望。"},{"h":"Y——你的计划","t":"编写规则；在手动/自动中遵循它们。"},{"h":"Z——零冲","t":"没有 FOMO。练习 → 然后使用 API。"}]}};

window.CPE_LEARN.ja = {"intro":"まずは紙/デモで練習してください。ローソク足、チャート、BB/RSI/Fib、お金、心理学を学び、次にシグナル (買い/売り/ホールドの意味 + 何をすべきか) と外国為替シグナルを学びます。 Live には、正しいプラットフォーム API キー (引き出しオフ) が必要です。","candles":[{"shape":"doji","name":"童子","color":"#94a3b8","bias":"中立 / 待つ","tip":"オープン ≈ クローズ - クロスまたはシンボディ。動き後の市場の優柔不断。","also":"また、FOMOをしないことも教えます。次のキャンドルを待ちます。 BB極近＋童子＝意見の絞り出し。方向を推測する前に RSI の傾きを確認してください。"},{"shape":"hammer","name":"ハンマー","color":"#22c55e","bias":"購入バイアス","tip":"上部のボディは小さく、下落後の下部の芯は長くなります (ボディの 2 倍)。買い手は値下げを拒否しました。","also":"また、練習用 SL を芯の下の低い位置に置きます。売られすぎから上昇するBB + RSIが低い場合に最適です。心理学: 芯が終わるまでの忍耐 — 芯の途中までは買わないでください。"},{"shape":"invhammer","name":"逆ハンマー","color":"#22c55e","bias":"買う（弱い）","tip":"底部に長い上芯。買い手は高値を探ったが、ほぼオープンで取引を終えた - 次の緑の確認が必要。","also":"また、ハンマー単体よりも弱いです。エントリーではなく、アラートとして使用します。 Fib 61.8 バウンス + 逆ハンマー = キャンドルを確認するまでのスタディ ゾーンのみ。"},{"shape":"shooting","name":"シューティングスター","color":"#ef4444","bias":"売りバイアス","tip":"実体底は小さく、上昇後の上芯は長い — 売り手は高値を拒否した。","also":"また、SL は芯が高くなります。上部 BB / フィブエクステンション / RSI の買われ過ぎ付近が強くなります。教えます：ムーンキャンドルは失敗する可能性があります - 最後の緑を追いかけてはいけません。"},{"shape":"hanging","name":"ぶら下がっている男","color":"#f59e0b","bias":"売り注意","tip":"見た目はハンマーに似ていますが、上昇後に出現します。トップが枯渇する可能性があります。","also":"また、コンテキストがすべてです (同じ形状 ≠ 同じ取引)。ジャーナルの場所: 上部と下部。心理学: 形状が一致したからといって反転しないでください。次のローソク足 + RSI で確認してください。"},{"shape":"engulf_bull","name":"強気の巻き込み","color":"#22c55e","bias":"買う","tip":"緑色のボディが以前の赤色のボディを完全にカバーします。購入者は 1 つのバーで主導権を握りました。","also":"また、サポートが強化されます / BB が低くなります / Fib 50 ～ 61.8。 SLほどの低めからのサイズ。お金のヒント：ワイドな巻き込みボディ→ワイドなSL→小型サイズ。"},{"shape":"engulf_bear","name":"弱気の巻き込み","color":"#ef4444","bias":"売る","tip":"赤いボディが前の緑を完全に覆い、売り手が優勢です。","also":"また、オープンロングにも注意してください。ほぼ上限 BB + RSI>70 = 高い研究の質。リスクを教えます: すでに長い場合は、希望の代わりに部分的な TP / トレイル。"},{"shape":"morning","name":"モーニングスター","color":"#22c55e","bias":"買う","tip":"3本のキャンドル：大きな赤→小さな星→大きな緑。最下位逆転物語。","also":"また、複数のキャンドルの忍耐力。 3rdクローズ後に入場してください。スターローの下のSL。 BB下限+強気RSIダイバージェンスとうまく組み合わせます。"},{"shape":"evening","name":"イブニングスター","color":"#ef4444","bias":"売る","tip":"3本のキャンドル：大きな緑→小さな星→大きな赤。最高の逆転物語。","also":"また、真ん中の星だけをショートさせないでください。 3番目のクローズを待ちます。上部 BB / Fib Extension 合流部。心理学: 最初のグリーンランの FOMO を無視します。"},{"shape":"maru_bull","name":"ブル丸坊主","color":"#22c55e","bias":"強い買い圧力","tip":"緑色の長いボディ、芯はほとんどありません - バイヤーがオープン→クローズを制御します。","also":"また、トレンド継続の手がかり、必ずしも底値買いとは限りません。ウォーク・ザ・バンド可能。リスク：BBミッド/Fibまで引き戻さずに遅れた丸坊主を追いかける。"},{"shape":"maru_bear","name":"くま丸坊主","color":"#ef4444","bias":"強い売り圧力","tip":"長く赤いボディ、芯はほとんどなく、売り手は主導権を握っています。","also":"また、落ちてくるナイフを捕まえないでください。後でBB/Fibバウンス+ハンマーを待ちます。教えます：強い圧力 = サイズを小さくするか、脇に置いてください。"},{"shape":"spin","name":"こま","color":"#94a3b8","bias":"優柔不断","tip":"小さな体、上部 + 下部の芯 — 双方が戦いましたが、明らかに勝者はいませんでした。","also":"また、BB の内側を頻繁に絞ってください。取引を一時停止します。待機休憩 + 方向キャンドル。心理学の教訓: 市場は「何もしない」ことはできません。フラットは有効な選択です。"},{"shape":"pierce","name":"ピアスライン","color":"#22c55e","bias":"買う","tip":"赤、次に緑。下方で開きますが、前の赤の中間点より上で閉じます。","also":"また、Engulfing よりも柔らかいです。 RSIターンで確認。部分的な強度を読み取るのに適した紙のドリルです。すべてのグリーンが同じというわけではありません。"},{"shape":"darkcloud","name":"暗い雲に覆われた","color":"#ef4444","bias":"売る","tip":"緑、次に赤が上昇し、前の緑の中間点より下で開きますが、閉じます。","also":"また、クマが完全に飲み込まれる前の早期警告も必要です。トレイルロング/TP1を取る。完全反転印刷の前にスケールアウトする方法を教えます。"},{"shape":"soldiers","name":"3人の白い兵士","color":"#22c55e","bias":"購入トレンド","tip":"終値が高くなった 3 つの緑が上昇 - 安定した買い。","also":"また、強い上昇トレンドの手がかり。 Fib 38–50 または BB Mid へのプルバックは追加の練習です。 3 グリーン後の過信リスク — リスク % を固定に保ちます。"},{"shape":"crows","name":"三羽の黒いカラス","color":"#ef4444","bias":"売りトレンド","tip":"終値が低く、3 つの下落赤 — 安定した売り。","also":"また、平均を下回らないでください。待機構造。 RSI は売られすぎても売られすぎのままになる可能性があります — マネールール: 損失限度額 > 希望。"},{"shape":"harami_bull","name":"強気のハラミ","color":"#22c55e","bias":"購入（ソフト）","tip":"前のボディの内側に大きな赤、次に小さな緑が表示され、圧力が縮小しています。","also":"また、早期の一時停止信号。確認が必要です。 RSI強気ダイバージェンス研究と組み合わせます。逆転だけではない「力の衰え」の読み方を教える。"},{"shape":"harami_bear","name":"弱気ハラミ","color":"#ef4444","bias":"販売（ソフト）","tip":"大きな緑、その後内側が小さな赤 – 買い圧力が縮小。","also":"また、ロングの部分音も取得します。自動ショートではありません。心理学: ビッググリーン後の貪欲さはハラミの警告を無視することがよくあります。"},{"shape":"tweezer_bot","name":"ピンセット底","color":"#22c55e","bias":"買う","tip":"安値が一致する 2 つのローソク足 — サポートの二重テスト。","also":"また、その下位を構造としてマークします。 SL直下。 Fib/BB のアライメントが役立ちます。ダブルボトムのチャートパターンのいとこ — 同じサポートレッスン。"},{"shape":"tweezer_top","name":"ピンセットトップ","color":"#ef4444","bias":"売る","tip":"高値が一致する 2 つのローソク足 — 抵抗の二重テスト。","also":"また、マーク耐性。ダブルトップのいとこ。 RSI の高値での失敗 = 合流。教えます: 同じ価格を 2 回拒否 = レベルを尊重します。"},{"shape":"longlegged","name":"足長童子","color":"#94a3b8","bias":"優柔不断","tip":"小さな体に非常に長い上部と下部の芯 - 激しい双方向の戦いは、始まった場所で終わりました。","also":"また、大きな動きが続くことはよくありますが、方向性は不明です。ブレイクローソクを待ちます。教えられるのは、ボラティリティが高いことは確実性が高いことではないということです。"},{"shape":"dragonfly","name":"蜻蛉童子","color":"#22c55e","bias":"購入バイアス","tip":"オープン = クローズ = 高、下に長い芯があり、売り手は押し下げ、買い手はまっすぐに押し上げました。","also":"また、サポート時に最も強い/ドロップ後のBBが低くなります。ウィックテールの下のSL。教えます：拒否は物語であり、保証ではありません - 次のローソクを確認します。"},{"shape":"gravestone","name":"墓石童子","color":"#ef4444","bias":"売りバイアス","tip":"始値 = 終値 = 安値、長い上芯があり、買い手は押し上げ、売り手は安値まで引き戻しました。","also":"また、レジスタンス/BB上部/RSIの買われ過ぎで最も強い。トンボの鏡。教えます：安値で閉じる急上昇はブレイクアウトの失敗です。"},{"shape":"inside_bar","name":"インサイドバー","color":"#94a3b8","bias":"巻き上げ・待機","tip":"2 番目のローソク足は最初のローソク足の内側に完全に収まります。レンジは縮小し、市場は息を呑みます。","also":"また、マザーバーのブレイクがトリガーとなり、ブレイク方向にトレードします。 BBスクイーズと組み合わせます。教えます：収縮は拡張の前に起こります。"},{"shape":"outside_bar","name":"アウトサイドバー","color":"#22c55e","bias":"ブレイクアウト/リバーサル","tip":"2 番目のローソクが最初のローソクを高値から安値に飲み込みます。これは 1 つのバー内での激しい乗っ取りです。","also":"また、方向 = 外側のバーが閉じる場所。大きなバーは大きなSLを意味するため、サイズは小さくなります。教えられるのは、1 つのバーで最後の 3 つを消去できるということです。"},{"shape":"belt_bull","name":"強気のベルトホールド","color":"#22c55e","bias":"買う","tip":"下芯なしで安値で開き、緑色で動作します。買い手は最初のティックから主導権を握りました。","also":"また、ギャップダウンまたはサポートにまっすぐ入った後が最も強力です。オープン下のSL。教え：冒頭のドライブには本当の意図が表れます。"},{"shape":"belt_bear","name":"弱気のベルトホールド","color":"#ef4444","bias":"売る","tip":"上部の芯がなく高値で開き、赤くなります。売り手はオープンからそれを制御しました。","also":"また、ギャップアップ後または抵抗時に最も強力です。トレイルロング。教え：最初の行動がその日のすべてを決める可能性があります。"},{"shape":"kick_bull","name":"強気キッカー","color":"#22c55e","bias":"強い買い","tip":"赤いキャンドル、そして緑のキャンドルへとギャップが生まれ、重なり合うことなく雰囲気が終局と終局の間で反転しました。","also":"また、希少かつ強力です。ギャップは必須であり、重複は許可されません。教え：市場が眠っている間にセンチメントは反転する可能性があります。"},{"shape":"kick_bear","name":"弱気キッカー","color":"#ef4444","bias":"強い売り","tip":"緑のローソク足から、赤いローソク足へとギャップが生じ、買い手は取引終了までの間に姿を消しました。","also":"また、素早く退出してください。キッカーはあなたを待っていません。教え：ギャップとは、あなたが離れているときに市場で価格が変更されることです。"},{"shape":"abandoned","name":"強気な捨て子","color":"#22c55e","bias":"強い買い","tip":"赤いろうそく、隙間のある童子、そして隙間のある緑のろうそく、優柔不断の孤島。","also":"また、童子は両側から離れていなければなりません。希少ですが高品質なボトムスです。教え：逆転は誰もが諦めたところから始まる。"},{"shape":"three_inside_up","name":"スリー・インサイド・アップ","color":"#22c55e","bias":"買う","tip":"強気のハラミに加えて、最初のローソク足の上で閉じる 3 番目の緑のローソク足 — インサイドバーはついに崩壊しました。","also":"また、確認済みのハラミは素のハラミよりもはるかに強力です。ハラミローの下にSL。教えます：確認は予測に勝ります。"},{"shape":"three_inside_down","name":"スリー・インサイド・ダウン","color":"#ef4444","bias":"売る","tip":"弱気のハラミと 3 番目の赤いローソク足が最初のローソク足の下で閉じ、内側のバーが崩れました。","also":"また、サードが閉じたらすぐにロングをカットしてください。教え：一時停止に失敗すると、単に古い傾向が再開される可能性があります。"},{"shape":"three_methods_bull","name":"ライジング 3 メソッド","color":"#22c55e","bias":"購入トレンド","tip":"長い緑のろうそく、その中に 3 つの小さな赤、そしてもう 1 つの長い緑 - 上昇の中で休息します。","also":"また、一時停止が最初のローソク足の範囲を離れることはないため、トレンドは穏やかです。最後のローソク足のブレイクをトレードします。教えます：トレンドは崩れずに残ります。"},{"shape":"three_methods_bear","name":"該当する 3 つの方法","color":"#ef4444","bias":"売りトレンド","tip":"長い赤いろうそく、その中に 3 つの小さな緑、そしてもう 1 つの長い赤いろうそく - 滝の中で休息します。","also":"また: Rising Three Methods の鏡。小さな野菜は買わないでください。それらは騒音です。教えます：範囲内でのプルバックは反転ではありません。"},{"shape":"tower_bot","name":"タワー下部","color":"#22c55e","bias":"反転買い","tip":"長い赤いキャンドル、小さなキャンドルの集まり、そして長い緑のキャンドル - 平らなベース全体で雰囲気が変化します。","also":"また、平らな中央が戦いで、最後のローソクが勝者を宣言します。教えます：基地には時間がかかります。"},{"shape":"tower_top","name":"タワートップ","color":"#ef4444","bias":"売り反転","tip":"長い緑のろうそく、小さなろうそくの集まり、そして長い赤のろうそく、買い手が使い果たし、売り手が引き継ぎます。","also":"また、塔底の鏡。ベースが形成されている間に部分音を取得します。教えます：トップは瞬間ではなくプロセスです。"}],"chartPatterns":[{"shape":"double_bot","name":"ダブルボトム(W)","color":"#22c55e","bias":"購入バイアス","tip":"同じ価格付近で 2 つの安値があり、その後中間ピークをブレイク — W 字型。","also":"また、ネックラインブレイク = 練習トリガーです。 TPアイデアの高さを測定します。ピーク→ローのピンセットボトム+フィブにリンクします。リスク: 誤ったブレイク — ネックラインを超えた近くで待ちます。"},{"shape":"double_top","name":"ダブルトップ(M)","color":"#ef4444","bias":"売りバイアス","tip":"同価格付近で 2 つの高値を更新し、その後中間の底値をブレイク — M 字型。","also":"また、より大きなスケールではピンセットトップと同じです。ネックラインブレイク前にロングトレイル。心理学: 2 番目に上位の FOMO は高価です。計画はすでに存在していました。"},{"shape":"hs_top","name":"ヘッド＆ショルダー","color":"#ef4444","bias":"売りバイアス","tip":"左肩、頭が高く、右肩。ネックラインを崩します。","also":"また: クラシック ディストリビューション。ターゲット ≈ ネックラインより下の頭の高さ。 RSI は頭で発散することがよくあります。 1本のキャンドル取引ではなく、マルチスイングの忍耐力を教えます。"},{"shape":"ihs","name":"逆H&S","color":"#22c55e","bias":"購入バイアス","tip":"ボトムでは逆さまの H&S — ネックラインが崩れる。","also":"また、蓄積の話。可能であれば、量/勢いを確認してください。合流研究には右肩ゾーンのモーニングスターと組み合わせてください。"},{"shape":"triangle","name":"三角（スクイーズ）","color":"#f0b429","bias":"ブレークアウト待機","tip":"より低い高音 + より高い低音の圧縮 — エネルギーを構築します。","also":"また、BB スクイズと同じレッスンです。内部の方向を推測しないでください。トレードブレイク + ローソク足クローズ。お金: 方向がわかった後のサイズ。"},{"shape":"flag","name":"雄牛の旗","color":"#22c55e","bias":"続きを購入","tip":"急激な上昇（ポール）、その後小さな下向き/横向きのチャネル、そして継続。","also":"また、Fib フラグの深さは浅い場合が多い (38%)。丸坊主ポール＋フラッグ＝トレンド練習。引き戻しなしで完全に伸びた後は遅れて購入しないでください。"},{"shape":"channel","name":"トレンドチャンネル","color":"#38bdf8","bias":"トレンドあり","tip":"上昇（または下降）平行線間の価格 - スイングトレードツール。","also":"また、上昇トレンドでは下位チャネル + ハンマーを購入します。アッパー+シューティングスターを販売します。 BB Mid はチャンネルを追跡することがよくあります。 「どのキャンドル」だけでなく「どこで」も教えます。"},{"shape":"support_res","name":"サポートとレジスタンス","color":"#a78bfa","bias":"コンテキストを優先","tip":"価格が繰り返し反応する水平ゾーン、つまりすべてのローソク足の下のマップ。","also":"また、どのパターンもS/Rが強力です。 BB/RSIの前にチャートラボでゾーンを描きます。心理学: レベル > ヒント;エントリーする前に書いてください。"},{"shape":"triple_top","name":"トリプルトップ","color":"#ef4444","bias":"売りバイアス","tip":"ほぼ同じ価格で 3 回の高値 – 買い手は 1 つの壁で 3 回失敗します。","also":"また、ダブルトップよりも強力です (3 つのリジェクト = 頑固な供給)。ネックラインブレイクがトリガーです。ターゲット ≈ パターン高さ。教えます：ロウソクではなくレベルがボスです。"},{"shape":"triple_bot","name":"トリプルボトム","color":"#22c55e","bias":"購入バイアス","tip":"ほぼ同じ価格で 3 回の安値が発生します。売り手は 1 つのフロアで 3 回失敗します。","also":"こちらもトリプルトップのミラー。それぞれのタッチはハンマー/ピンセットの研究になります。ネックラインブレイク+クローズを待ちます。多くのスイングで忍耐力を教えます。"},{"shape":"cup_handle","name":"カップ＆ハンドル","color":"#22c55e","bias":"続きを購入","tip":"丸い「U」（カップ）、次に小さなプルバック（ハンドル） – 休憩後の継続。","also":"また、ブレイクアウトトレーダーにも人気があります。ハンドルは浅く短くする必要があります。ハンドルが深いと手が弱いことを意味します。ハンドルブレイクでローソク確定でエントリー。"},{"shape":"rounding_bot","name":"丸い底","color":"#22c55e","bias":"反転買い","tip":"ゆっくりとした滑らかな「円盤」安値 – 売りが徐々に消え、その後買い手が引き継ぎます。","also":"また、スローモーションのダブルボトム。メッセージは、売り手がエネルギーを使い果たしたということであり、スパイクは一度もありませんでした。十分な忍耐が必要です。"},{"shape":"rounding_top","name":"ラウンドトップ","color":"#ef4444","bias":"売り反転","tip":"滑らかな「ドーム」高値 – 価格が反転する前に買いは徐々に消えていきます。","also":"また、Round Bottom のミラー。勢いが衰えるうちに早めにパーシャルを獲得しましょう。教えます：トップは単一のキャンドルではなくプロセスです。"},{"shape":"rising_wedge","name":"ライジングウェッジ","color":"#ef4444","bias":"売りバイアス","tip":"どちらのレールも上昇しますが、上向きに収束します。レンジが狭くなると買い手は疲れます。","also":"また、価格が依然として上昇しているため誤解を招きます。狭くなっていることが本当の手がかりです。故障することもよくあります。最後の一押しを追わないでください。"},{"shape":"falling_wedge","name":"フォーリングウェッジ","color":"#22c55e","bias":"購入バイアス","tip":"両方のレールは下がりますが、下向きに収束します。レンジが狭まると売り手は疲れます。","also":"ライジングウェッジのミラーも。 UPが頻繁に壊れます。ウェッジテールのハンマーは古典的な研究です。休憩+終了を待ちます。"},{"shape":"asc_triangle","name":"アセンディングトライアングル","color":"#f0b429","bias":"購入バイアス","tip":"平らな天井 + 上昇する床 — 買い手は固定抵抗線にステップアップし続けます。","also":"また、ある価格に対して圧力が高まります。ブレイクアウトは一般的です。天井近くから入ります。教え：購入者はせっかちになっている。"},{"shape":"desc_triangle","name":"下降三角形","color":"#f0b429","bias":"売りバイアス","tip":"平らな床と下がり続ける天井 — 売り手は固定サポートに押し込み続けています。","also":"また、アセンディングトライアングルの鏡。ブレークアウトダウンはよくあることです。床下近くから入ります。教え：売り手が主導権を握る。"},{"shape":"pennant","name":"ペナント","color":"#22c55e","bias":"続き","tip":"鋭いポール、そして小さくタイトなトライアングル、つまりトレンドが再開する前の非常に短い休息です。","also":"また、旗に似ていますが、短くて三角形です。ターゲットのアイデアのポールを測定します。小さなコイルの内部を決して推測しないでください。"},{"shape":"flag_bear","name":"ベアフラッグ","color":"#ef4444","bias":"販売の続き","tip":"急激な下落（ポール）、その後小さな上向き/横向きのチャネルがあり、その後下降が続きます。","also":"また、雄牛の旗の鏡。小さな反発は一時停止であり、反転ではありません。旗を追いかければ、最悪の価格を買うことになります - 休憩を待ちます。"},{"shape":"rectangle","name":"長方形(範囲)","color":"#f0b429","bias":"レンジトレード","tip":"価格は平らな天井と床、つまり横向きのボックスの間で跳ね返ります。","also":"また、内側のエッジをフェードし、外側のブレークを交換します。 BB スクイーズは通常、長方形の中に収まります。教えます: レベル間の規律。"},{"shape":"broadening","name":"フォーメーションの広がり","color":"#f0b429","bias":"注意","tip":"高値が高く、安値が低くなると、範囲が狭まるのではなく扇状に広がります。","also":"また、混沌とした感情的な市場。ストップは双方向でヒットします。サイズを小さくするか、脇に置きます。多くの場合、暴力的な一方通行で終わります。"},{"shape":"diamond","name":"ダイヤモンド","color":"#f0b429","bias":"反転","tip":"中央が広く、両端が狭い、典型的なトッピング/ボトム構成です。","also":"また、変形してから変形を解除する三角形。ブレイクアウトの方向性が決まります。まれで遅いため、ほとんどの行がノイズのように感じられますが、辛抱強くお待ちください。"},{"shape":"island_rev","name":"アイランドリバーサル","color":"#ef4444","bias":"反転","tip":"価格差が離れ、孤立したクラスターで取引され、その後ギャップが戻り、「島」が形成されます。","also":"また、実際のギャップが必要です (株式/FX ではより一般的です)。島には買い手か売り手が閉じ込められています。島のろうそくではなく、ギャップを信号として扱います。"},{"shape":"breakaway_gap","name":"ブレークアウェイギャップ","color":"#22c55e","bias":"トレンドスタート","tip":"範囲またはベースからのギャップ - 動きは絞るのではなく力で始まります。","also":"また、消耗ギャップとは異なり、動きの早い段階で現れます。ギャップは多くの場合、後でサポート/レジスタンスとして機能します。教えます: 勢いと価値のギャップ。"},{"shape":"v_reversal","name":"Vリバーサル","color":"#22c55e","bias":"反転","tip":"ベースなしで瞬時に上に上がる鋭いフリーフォール、つまり「V」の字。","also":"また、速くて怖い。多くの場合、ニュース主導で行われます。捕まえるのは難しく、追いかけるのは簡単です。スパイクを買うのではなく、小さな引き戻しとローソク足を待ちます。"},{"shape":"harmonic","name":"ハーモニックパターン","color":"#f0b429","bias":"反転ゾーン","tip":"各レッグがフィボナッチ比を持つ、測定されたジグザグ (X-A-B-C-D)、つまり「ガートレー/バット」スタイルのマップ。","also":"また、高度な。 D ポイントはエントリー ゾーンであり、感情ではなく比率によって定義されます。まずはプレーンFibをマスターしてください。これは Fib をさらに 1 レベル深くしたものです。"}],"modules":[{"id":"bb","title":"1 · ボリンジャーバンド (BB)","summary":"ボラティリティは移動平均の周囲にあります。スクイズ、ウォーク・ザ・バンド、ロワー/アッパー・タッチ + キャンドル・コンファーム - CPE 練習の中心となるセットアップを学びます。","lessons":[{"h":"BBとは","t":"ボリンジャー バンド = 中央の SMA (多くの場合 20) + N 標準偏差 (多くの場合 2) の上部/下部バンド。ボラティリティが上昇するとバンドは拡大し、市場が静かな場合は縮小します。"},{"h":"ミドルバンド","t":"中央の線は平均値です。中間を超える価格は強気の圧力を示すことがよくあります。以下は弱気圧力を示しています。魔法の売買ではなく、動的なバイアスラインとして使用してください。"},{"h":"ローバンド（購入練習）","t":"下落後に下位バンドに価格タグを付けることは、「縮小」を意味する可能性があります。すべてのタッチを購入しないでください。強気のローソク足（ハンマー、エングルフィング）と理想的にはRSIが上昇するのを待ちます。"},{"h":"アッパーバンド（売り・注意）","t":"上部のバンドに値札を付けることは、「拡大」を意味する場合があります。上昇トレンドでは、価格が上部バンドに乗ることができます (ウォーク・ザ・バンド)。弱気のローソク足 + より高い TF の弱さでのみ売りのアイデアを優先します。"},{"h":"絞る","t":"バンドが狭い = ボラティリティが低い → ブレイクアウトが続くことが多い。きつい締め付けの中で方向を推測しないでください。ブレイクアウトをマークし、可能な場合はローソク足 + ボリュームで確認します。"},{"h":"バンドを歩む","t":"強いトレンドでは、価格は多くのローソク足の上部（または下部）バンドに近づきます。平均回帰フェードでこれに対抗するのは、初心者にありがちな間違いです。"},{"h":"BB+チャートラボ","t":"CPE Chart Lab / デスクでは、DEMO でキャンドルを使用して BB を研究します。練習：下バンド+ハンマー→紙芯下SL、中バンド付近TP1でペーパートレード。"},{"h":"BB+RSIコンボ","t":"より強力な実践フィルター: BB の低下 + RSI の売られ過ぎ (または売られ過ぎからの上昇) + 強気のローソク足。 BB上部+RSI買われ過ぎ+短期練習用の弱気のローソク足。"},{"h":"停止位置","t":"ロングプラクティス: SL はスイングローの下/ローバンドウィックの下にあります。ショート練習：スイングハイ以上のSL。書面による SL なしで BB 取引に参加しないでください。"},{"h":"ターゲット","t":"共通パス: 中間バンドの TP1、反対側のバンドまたはトレイルに向かう TP2。スケールアウト – 全体的な移行は必要ありません。"},{"h":"時間枠","t":"より高い TF (4H/1D) のバイアスを決定します。 15m/30m BB+キャンドルでエントリー。ランダムな TF を混合すると、信号の競合が発生します。"},{"h":"避けるべき間違い","t":"暴落する市場で低帯域のあらゆるタッチを購入する。ムーンランであらゆる上質感を売り込む。 SLはありません。バンドを激しく広げるニューススパイクを無視します。"},{"h":"練習チェックリスト","t":"① より高い TF バイアス ② BB タッチまたはスクイズブレイク ③ キャンドル確認 ④ RSI 一致 ⑤ リスク％設定 ⑥ ペーパーファースト ⑦ ジャーナル結果。"}]},{"id":"rsi","title":"2・RSI（相対強度指数）","summary":"モーメンタムオシレーター 0 ～ 100。デフォルトの 14 期間。 BB およびキャンドルと併用してください。完全なシステムとして RSI を単独で使用しないでください。","lessons":[{"h":"RSI の測定内容","t":"RSI は、N バーにわたる平均利益と損失を比較します。高い RSI = 最近の強気の勢い。低い RSI = 最近の弱気の勢い。毎回「買われすぎ＝売らなければならない」わけではありません。"},{"h":"クラシックゾーン","t":"多くの場合、70 以上 = 買われ過ぎゾーン、30 以下 = 売られ過ぎゾーンです。強いトレンドでは、RSI は長期間にわたって買われすぎ/売られすぎになる可能性があります。これは正常なことです。"},{"h":"正中線 50","t":"RSI が 50 を超えると強気バイアスがサポートされる可能性があります。 50未満は弱気バイアス。多くのトレーダーは、BB ミドルバンドのトレンドフィルターとして 50 を使用します。"},{"h":"ダイバージェンス — 強気","t":"価格は安値を形成し、RSI は高値を安値にします → 下値の勢いが弱まる。ペーパーエントリーの前に、キャンドル+ストラクチャーブレイクを待ちます。"},{"h":"ダイバージェンス — 弱気","t":"価格は高値、RSIは高値を下げる→上昇勢いが弱まる。耐性付近やBB上部にシューティングスター・巻き込みで確定。"},{"h":"失敗のスイング","t":"RSIは前の極端な再テストに失敗し、その後50を超えて戻りました - 初期の勢い変化の手がかり。 Chart Lab 構造と組み合わせます。"},{"h":"RSI + BB (CPE スタイル)","t":"ロング練習: 価格はBBの下限付近、RSI ≤ 35 (または≤ 30からの上昇)、強気のローソク足。ショートの練習: アッパー BB、RSI ≥ 65–70、弱気のローソク足。"},{"h":"隠れた発散","t":"トレンド継続の手がかり (例: 上昇トレンドにおける価格の高値安値、RSI の安値)。上級 — 最初にデモで古典的な分岐をマスターします。"},{"h":"設定","t":"RSI(14) が一般的なデフォルトです。 RSI が短い = ノイズが多くなります。信号を強制的に送信するために設定を変更し続けないでください。"},{"h":"RSIで終了","t":"売られすぎた場合は、RSI が中値/上限ゾーンに達したときに部分利益を確定するのが合理的です。ストラクチャーまたはBBミドルで残りを追跡します。"},{"h":"ニュースとRSI","t":"大きなニュースがあれば、即座に RSI が急上昇する可能性があります。 RSI の極端な値に基づいて行動する前に、最初の激しいローソク足が終わるのを待つことをお勧めします。"},{"h":"間違い","t":"強気市場ではすべての RSI > 70 を空売りする。 RSI<30未満のクマの衝突を待ち望んでいます。合流点がない。 RSIが「良くなったように見える」ときにリベンジリエントリー。"},{"h":"練習チェックリスト","t":"① RSI 値 + 傾きに注意する ② BB の位置を確認する ③ ローソク足を確認する ④ より高い TF ⑤ 論文 + ジャーナル ⑥ アイデアを 1 つずつ。"}]},{"id":"fib","title":"3 · フィボナッチ (リトレースメントとエクステンション)","summary":"明確なスイングハイ→スイングロー（またはリバース）からのプルバックとターゲットを測定します。 BB/RSI合流点の38.2・50・61.8に注目。","lessons":[{"h":"Fibが使用される理由","t":"多くのトレーダーは同じ比率を監視しているため、流動性はそれらの比率に近い値で反応することがよくあります。 Fib は可能なゾーンのマップであり、保証するものではありません。"},{"h":"スイングポイント","t":"常に明確なスイングから低いスイングから高いスイング (上への動き) または高いから低い (下の動き) からドローします。悪いスイング = 役に立たないレベル。 Chart Lab DEMO でピッキング スイングを練習してください。"},{"h":"主要なリトレースメント","t":"一般: 23.6% (浅い)、38.2%、50% (純粋な Fib ではないが広く使用されている)、61.8% (黄金色)、78.6% (深い)。深いリトレースはトレンドの弱さを示す可能性があります。"},{"h":"戻り買い（上昇トレンド）","t":"インパルスが上昇した後、38.2〜61.8ゾーン+強気ローソク足+できればBB中/下サポート、またはRSIが40〜45を超える水準に戻るのを待ちます。"},{"h":"戻り売り（下降トレンド）","t":"インパルスダウン後、38.2–61.8 + 弱気のローソク足 + RSI が 55–60 未満に失敗します。"},{"h":"拡張子/ターゲット","t":"一般的な拡張: 127.2%、TP2 アイデアのスイングを超える 161.8%。トレイルで使用します。正確なティックを強制しないでください。"},{"h":"合流 = パワー","t":"ベストプラクティスゾーン: Fib 50/61.8 + BB ミドル/ロアー + プリアーストラクチャー + RSI ターン。 1 本の Fib ラインだけでは弱いです。"},{"h":"フィブ+BB","t":"61.8% が上昇トレンドの下位 BB 付近にある場合、その重複部分は高品質の論文調査ゾーンです。キャンドル確認のみでエントリーしてください。"},{"h":"複数の線維","t":"初心者はクリーンなスイングを 1 つ使用する必要があります。 5 Fibs を積み重ねると、チャートノイズと FOMO エントリーが作成されます。"},{"h":"無効化","t":"価格がバイアスに反して明らかに 78.6% を超えて終了した場合、反発理論は失敗することが多く、撤退するか脇に置くかです。"},{"h":"外国為替 vs 仮想通貨","t":"同じ比率です。外国為替メジャーは、流動的なセッションではレベルをより明確に尊重することがよくあります。暗号通貨は浸透してから逆転する可能性があり、サイズが小さくなります。"},{"h":"間違い","t":"小さなノイズスイングでFibを描画します。ろうそくを持たずに空中に入る。 Fib が「ほぼ」保持されているときに SL をさらに遠くに移動します。より高いTFを無視します。"},{"h":"練習チェックリスト","t":"①マークスイング ②ノート38.2/50/61.8 ③価格が到着するのを待つ ④ローソク+RSI/BB ⑤リスクセット ⑥紙→ジャーナル。"}]},{"id":"money","title":"4 · お金の管理","summary":"この方法が実際にどのように使用されるか: 固定パーセントのリスク、ストップからのサイズ、利益の一部を銀行に預ける、損失制限後の翌日のストップ。 CPE はこれを手動取引と自動取引に適用できます。","lessons":[{"h":"資金管理の目標","t":"ゲームに留まろう。 1 つの悪い取引でアカウントが消去されることはありません。一貫性は宝くじのサイズ設定に勝ります。"},{"h":"トレーダーが実際にどのように使用するか","t":"一般的な手法は固定端数リスクです。最初にコインの金額を選択する必要はありません。最初にストップを書き、このアイデアがアカウントの約 1% を失う可能性があると判断し、その後、サイズがその範囲から外れます。広いストップの位置は小さくなります。タイトストップはより大きなポジションを獲得し、ドルリスクはほぼ同じままです。これは、資金管理チェックがオンの場合に CPE が使用する方法です。"},{"h":"動作例 ($1000 の練習用アカウント)","t":"アカウントは 1000 ドルです。リスク 1% = 10 ドル。エントリー 100、ストップ 98。距離 = 2%。サイズ = 10 ÷ 0.02 = 想定元本 500 ドル。ストップに達した場合の損失は 500 ドルではなく、約 10 ドルです。価格が 103 (リスクの 1.5 倍) に達すると、利益は約 15 ドルになります。すべてのペアで同じ考えです。リスクのあるドルは 1% 近くに留まり、コインの量は変化します。"},{"h":"CPE がダニに対して行うこと","t":"今すぐ取引 → 自動: 「資金管理を使用する」にチェックを入れます。自動設定を保存します。新しい自動取引はそれぞれ、1000 ドルの練習口座と、シグナルのエントリーと SL からサイズ設定されたクローズされた結果の約 1% を使用します。スポットと先物の最小値が尊重されます。取引所の最小値のリスクが 1% を超える場合、その取引はスキップされます。暦日で約 -2% になると、新車は翌日まで停止します。オープン取引全体で最大約 3% がリスクにさらされています。手動取引にも同じティックがあります。 Signal History には引き続き、等しい $10 テストが表示され、その下に $1000 アカウントの 1% プラン サイズが表示されるため、両方を確認できます。"},{"h":"部分的な利益と軌跡","t":"練習としては、最初のターゲット (多くの場合約半分) で一部を離れ、残りを追跡することです。ストップが上がるとターゲットも移動する可能性があるため、勝者は最初のターゲットよりも多く支払うことができます。元のアイデアのリスクは増加しません。強いシグナルは 5% のリスクを負う理由にはなりません。同じ 1% が使用されます。トレイルは、強い勝者を成長させるものです。"},{"h":"毎日の停止とオープンヒート","t":"よく使用されるルール: その日の口座の約 2% が下落した場合は、取引を開始するのを停止します。それぞれ 1% の 3 つの未解決のアイデアは、約 3% の熱量になります。 5 つの相関コインは 5 枚ではなく 1 回のベットになります。それらを一緒に数えてください。"},{"h":"このメソッドが拒否するもの","t":"マーチンゲール法（負けた後の倍増）は使用しません。入場後に「スペースを与える」ためにストップをさらに移動することは使用されません。 「確実」シグナルでのオールインは使用されません。有効なストップがない場合、サイズがないため、取引は行われません。"},{"h":"取引ごとのリスク","t":"共通ルール: 1 つのアイデアに対してリスクを負うのはアカウント資産の約 0.5 ～ 1% のみです。 DEMO では、LIVE と同じパーセンテージの習慣を練習します。"},{"h":"ポジションサイズの計算式","t":"サイズ ≈ (アカウント × リスク%) ÷ (エントリー − ストップ距離)。幅広のSL→小さいサイズ。サイズを最初に選択し、次に SL を選択しないでください。"},{"h":"リスク：報酬","t":"学習する際には、潜在的な報酬 ≥ リスク (例: 1:1.5 以上) のアイデアを優先します。 TP1 でスケールアウトすると、ランナーは「フリーリスク」になります。"},{"h":"部分的なテイクプロフィット","t":"CPE スタイル: TP1 で一部の利益を確保し、残りは TP2 / トレイル。銀行取引の一部は感情的なパニックを軽減します。"},{"h":"トレーリングTP+SL","t":"買い：価格が上昇するとトレイルのレベルが上がります。売り：トレイルダウン。トレーリングロックは完璧なエグジットコールを必要とせずに利益をオープンします。"},{"h":"日次/週次の損失限度額","t":"ルールの例: -2% 口座の翌日の取引を停止します。損失制限後のリベンジセッションはアカウントキラーです。"},{"h":"スポットサイジング","t":"スポット最小の想定元本は重要です (例: 取引所の最小単位)。それでもリスク%を適用します: 最小サイズのリスクが SL に対して大きすぎる場合は、取引をスキップします。"},{"h":"先物/レバレッジ","t":"レバレッジは利益と損失の両方を倍増します。高レバレッジ + ワイド SL = 吹き飛ばされた口座。学習中は低いレバレッジを好みます。分離すると、ポジションごとに損失を制限できます。"},{"h":"相関関係","t":"5 つの相関 BTC アルトを開く = 5 つではなく、1 つの大きな賭けになります。リスクをグループとしてカウントします。"},{"h":"手数料とスリッページ","t":"タイトな頭皮はチャートでは良く見えますが、手数料はR:Rを食い込みます。コストがわかるまでは、デモでよりクリーンなスイングを優先してください。"},{"h":"デモ→ライブブリッジ","t":"CPE デモの実践 (約 3 か月の考え方): 同じジャーナル ルール、同じ %。ライブの場合は、最初の数週間は半分のデモ サイズから開始します。"},{"h":"API マネーの安全性","t":"すべてのキーで引き出しがオフになります。一致するプラットフォームでテスト アカウント OK になった場合にのみ有効になります。間違ったプラットフォーム シークレット = 失敗した操作または危険な操作。"},{"h":"間違い","t":"マーチンゲール法（敗戦後2倍）。 SLをさらに遠くに移動する。 「確実な」セットアップに全力を尽くします。最小サイズ対リスク%は無視します。毎日ストップすることなく取引します。"},{"h":"練習チェックリスト","t":"① 書き込まれたリスク % ② SL 距離からのサイズ ③ 計画された TP1/TP2/トレイル ④ 既知の最大日次損失 ⑤ 論文が最初 ⑥ 仕訳損益は正直に。"}]},{"id":"psych","title":"5 · トレーディングのための心理学","summary":"BB/RSI/Fib スキルが実際の画面に耐えられるかどうかは、考え方によって決まります。 FOMO、復讐、自信過剰、恐怖 — これらをデモのような指標でトレーニングします。","lessons":[{"h":"なぜ心理学が重要なのか","t":"完璧な BB+RSI プランは、早めにエントリーしたり、SL をスキップしたり、リベンジトレードをしたりすると失敗します。スキル＝システム×規律。"},{"h":"予測よりプロセス","t":"未来を予測する必要はありません。ルールを実行する必要があります: 設定 → リスク → 管理 → ジャーナル。結果はさまざまです。プロセスは制御可能です。"},{"h":"FOMO","t":"逃すことへの恐怖 = すでに BB/Fib ゾーンから遠く離れた緑色のキャンドルを追いかけます。ルール: エントリを見逃した場合は、次のセットアップを待ちます。 Chart Lab には常に別のローソク足があります。"},{"h":"復讐取引","t":"負けた後は、「今すぐ取り戻したい」という衝動がアカウントを破壊します。強制的なクールダウン: 立ち去り、損失を仕訳し、チェックリストに問題がない場合にのみ次の取引を行います。"},{"h":"勝った後の自信過剰","t":"3連勝≠サイズが5倍に増加します。リスク%を固定してください。連勝しているときは、ほとんどの人がお金のルールを破っているときです。"},{"h":"喪失後の恐怖","t":"赤の日の後に有効な設定をすべてスキップすることも偏見です。書かれた計画を信頼してください。必要に応じてサイズを一時的に縮小しますが、プロセスを放棄しないでください。"},{"h":"分析麻痺","t":"10 個の指標が一致しない → 凍結。 CPE コアに固執します: キャンドル + BB + RSI (+ Fib ゾーン)。ツールの量よりも質。"},{"h":"ティルト＆ニュース","t":"ニュースで大きな赤いろうそくがアドレナリンを急増させます。構造改革までの大きな未知数の間はフラットを好む — エゴは行動を望んでいる。計画には忍耐が必要です。"},{"h":"ジャーナル = 治療 + データ","t":"CPEジャーナルに感情タグ（FOMO、ラッシュ、冷静）を書き込みます。感情のパターンは、損益計算だけよりも早く漏れを明らかにします。"},{"h":"明文化されたルール","t":"書かれていない場合はルールではありません。例: 「BB + キャンドル + RSI のみ、リスク 1%、-2% 日以降は取引なし、チェックリスト 20 件の論文までデモ。」"},{"h":"環境","t":"睡眠、空腹、電話による気が散ると、意思決定が変わります。疲れているときはサイズアップしないでください。トレーディングは運動的なものであり、脳を守ります。"},{"h":"社会的ノイズ","t":"電報の「シグナル」や誇大宣伝は、あなたの計画を壊します。 CPE ラーニング クラス + 日記 > ランダムなヒント。ニュースとトリックを注文ではなくコンテキストとしてフィルターします。"},{"h":"アイデンティティの変化","t":"「私は正しいに違いない」ではなく、「チェックリストに従っている」と考えてください。小さなリスクで間違っているのは普通のことです。大きなリスクを伴う頑固になることは任意です。"},{"h":"ジムとしてのデモ","t":"感情を安全にリハーサルするには、デモ/ペーパーを使用してください。 DEMO でルールに従えない場合、LIVE では規律が魔法のように修正されるわけではありません。"},{"h":"練習チェックリスト","t":"①私は落ち着いていますか？ ②チェックリストは完成しましたか？ ③リスク％は変わらない？ ④復讐しない？ ⑤正直に日記を書きますか？ NOの場合→取引なし。"}]},{"id":"signals","title":"6 · CPE シグナル — 意味と対処方法","summary":"現物/先物/外国為替デスクでは、買い・売り・ホールド + スコアが表示されます。どのプラットフォームでも同じエンジンのアイデアですが、取引できるのは API キーを保存したプラットフォームでのみです。各信号の意味と、信号が表示された後の正確な手順は次のとおりです。","lessons":[{"h":"信号がどこから来るのか","t":"CPE スコアは BB、RSI、フィボナッチ、ローソク足、EMA クロス、SMA50、MACD、モメンタムです。スコア ≥ +3 → 購入。スコア ≤ −3 → 売ります。その間→HOLD。これはヘルパー評価であり、利益を約束するものではありません。"},{"h":"買いシグナル — 意味","t":"現在、強気の合流がより強いです（例: BB の下落、RSI の売られ過ぎターン、強気のローソク足、ゴールデンクロス、Fib サポート）。提案された TP1 / TP2 / SL が行 / Chart Lab / Trade Now に表示されます。"},{"h":"売りシグナル — 意味","t":"弱気の合流はより強力です (BB 上部 / 買われ過ぎ RSI / 弱気のローソク足 / デスクロス / ファイバー抵抗)。スポットでは、市場でショート (先物/外国為替) が許可されている場合にのみ、売りは通常、ロングまたはショートを手仕舞い/縮小することを意味します。"},{"h":"HOLD信号 — 意味","t":"混合または弱いスコア。取引を強制しないでください。フラットが正解です。ウォッチリスト★を選択し、より明確なBUY/SELLまたはBBの下位候補を待ちます。"},{"h":"スコア番号","t":"より高い |スコア| = ツール間でより多くの合意が得られます。 BUY +5 は BUY +3 よりも強力です。サイズを決定する前に、チャート ラボのローソク足で確認してください。"},{"h":"BB ロアボード","t":"ボリンジャーの下位バンドをタグ付けしたペアの別のリスト - ロング候補を練習します。まだローソク足+RSIの確認が必要です。すべての下部タッチがエントリーになるわけではありません。"},{"h":"プラットフォームと信号 (重要)","t":"シグナル計算は、Binance、Bybit、OKX、KuCoin、Bitget、Gate、MEXC、Kraken、Coinbase、OANDA、FXCM、MT5、Forex Demo と同じ考え方です。変更されるのは注文を送信する場所です。API キー / 今すぐ取引で選択したプラットフォームのみです。 Binance BUY は Bybit では開かれません。"},{"h":"クリプトスポットプラットフォーム","t":"Binance Spot、Coinbase など: BUY = クォート (USDT など) でコインを購入します。 SELL = 保有株を売却 / 利益確定。最小サイズ (例: ~11 ドル) が重要です。レバレッジはありません。"},{"h":"仮想通貨先物プラットフォーム","t":"Binance Futures、Bybit、OKX、Bitget…: 買い = ロング;売り = ショート。クロス/アイソレーション + レバレッジを慎重に選択してください。トレイル: トレイル TP+SL を購入。 SELLは下落。"},{"h":"外国為替プラットフォーム","t":"OANDA / FXCM / MT5 / 外国為替デモ: FX ペア (EURUSD…) に同じ BUY/SELL/HOLD ラベル。 BUY = 基本通貨を購入します。 SELL = ベースを売る。コイン数量の代わりにロット (例: 0.01)。セッションとニュースの方が重要です。"},{"h":"「BUY」が表示されたら、これを実行します","t":"①行を開く→Why/candle/RSIを読みます。 ② チャートラボ確認(15m-1H)。 ③最初のデモ: 今すぐトレード → TP1/TP2/SL/trail を設定 → デモ/ペーパーを開始します。 ④そのプラットフォームでAPIテスト後のみOK→小規模LIVE。 ⑤仕訳結果。"},{"h":"SELL が表示されたら、これを実行します","t":"① ロングスポットの場合: TP / 部分的なクローズ / トレイルを考慮します。無視しないでください。 ② 先物/外国為替とプランでショートが許可されている場合: Chart Lab を確認し、SL で Paper/Live ショートを確認します。 ③昨日HOLDが良かった場合は、フリップサイズをリベンジしないでください。"},{"h":"HOLD が表示されたら、これを実行します","t":"新しいマニュアルエントリはありません。スキャンを続けます。 ★ウォッチリストを追加します。スタディラーニングクラス / チャートラボすでに取引中の場合にのみ、オープンポジションをトレイルで保護してください。"},{"h":"自動取引 + シグナル","t":"自動購入は、BB 下限 + 強力なスコア ルールが保存された自動設定と一致する場合に開くことができます。まだ DEMO テスト Auto を最初に行います。 LIVE Auto = 実質リスク — 出金オフ、サイズは小さい。"},{"h":"通知","t":"購入 Signal トーストはあなたの言語に従います。それらを単独の成行注文としてではなく、デスクを開くためのアラートとして扱います。"},{"h":"してはいけないこと","t":"チャートなしですべての BUY を購入しないでください。 Bybit では Binance キーを使用しないでください。 SLをスキップしないでください。青信号の後はサイズを上げないでください。 HOLD を「ほぼ BUY」として取引しないでください。"},{"h":"クイックアクションカード","t":"シグナル → チャート ラボ → リスク % → TP1/TP2/SL → デモ ペーパー → ジャーナル → (後で) 一致するプラットフォーム キーでライブ。"}]},{"id":"forex_sig","title":"7 · 外国為替シグナル — 意味とすべきこと","summary":"Forex Desk は、FX ペアに対して同じ BUY / SELL / HOLD 評価を使用します。外国為替シグナルが暗号通貨とどう違うのか、そしてシグナル→ペーパー→ライブブローカーの正確な手順を学びましょう。","lessons":[{"h":"外国為替デスクシグナル","t":"EURUSD、GBPUSD、USDJPY…仮想通貨と同様に購入/販売/ホールド + スコアを取得します。行をクリックすると、チャート、心理学のテキスト、推奨レベルが表示されます。"},{"h":"外国為替で買う — 意味","t":"基本通貨を購入します (例: EURUSD を購入 = USD に対して EUR を購入)。値上がりが期待できます。練習する Chart Lab 外国為替インターバル (15 メートル/30 メートル/1 時間) を使用します。"},{"h":"外国為替で売る — 意味","t":"ベースを売ります（ペアをショートします）。値下げが期待できます。常に SL を構造/上部バンドのアイデアよりも上に設定します。"},{"h":"外国為替を保留","t":"明確なエッジがない - スキップします。特に大きなニュース（NFP、CPI、中央銀行）の前はホールド/フラットを好みます。"},{"h":"外国為替デモレートプラットフォーム","t":"APIキーがありません。練習用チャート+紙のみ。 OANDA/FXCM/MT5 ライブ前の学習クラスのドリルに最適です。"},{"h":"OANDAシグナル→アクション","t":"① 外国為替デスク BUY/SELL。 ②チャートラボ確認。 ③ APIキー→OANDAトークン+アカウントID→テスト。 ④ まずはCPEのデモペーパー。 ⑤ TP/SL/トレイルを備えた小さなライブロット（0.01マインドセット）。"},{"h":"FXCM/MT5","t":"同じ信号読み取り値。 API キーでそのブローカーの認証情報を接続します。 Signal はキー/ブリッジが設定されるまで MT5 に自動ログインしません。テストが OK になるまでペーパーを練習してください。"},{"h":"セッション","t":"ロンドンとニューヨーク州が重なると、メジャーがさらに移動することがよくあります。アジアは静かかもしれません。ホールドは一般的で健全です。"},{"h":"スプレッド＆ニュース","t":"ニュース関連ではスプレッドが拡大します。テクニカルで良い買いでも、依然として悪い約定になる可能性があります。ニュースと裏技をチェック;スパイク後にローソク足が閉じるのを待ちます。"},{"h":"ロットと暗号通貨の数量","t":"外国為替サイズ = ロット、同じようにUSDTの概念的なものではありません。リスク % は依然としてルールです: より広い SL → より小さなロット。"},{"h":"外国為替でBB安","t":"同じアイデア: 低いバンド付近のペア + ハンマー + RSI 上昇 = 長い研究を練習します。 TF バイアスが高いことを確認します (4 時間/毎日)。"},{"h":"Forex BUY が開始されるとき — ステップ","t":"①「なぜ」を読んでください。 ② TF バイアスを高くしても大丈夫ですか? ③ 芯/構造の向こう側に SL をマークします。 ④紙貿易。 ⑤ ライブブローカーの準備ができている場合 → 小さなサイズ + トレイル。 ⑥ジャーナルセッション（ロンドン/NY）+感情。"},{"h":"外国為替SELLが発動したとき — ステップ","t":"①ニューススパイクの最中ではないことを確認する。 ②チャートラボ弱気ローソク足。 ③ ペーパーが短いか、長く閉じます。 ④ 短い場合は下に進みます。 ⑤ 外れてからロットを倍増させないでください。"},{"h":"外国為替と仮想通貨の違い","t":"24時間年中無休の暗号化。 FXにはセッションがあります。暗号通貨の最小$は頻繁にあります。外国為替ロット + pip 値。暗号の多くの代替ファイルは相関関係にありました。学習のための外国為替メジャークリーナー。"},{"h":"練習チェックリスト（FX）","t":"①ペアメジャー？ ②セッションOK? ③ニュースクリア？ ④シグナル買い/売りはホールドではない？ ⑤チャート確認？ ⑥リスク％？ ⑦ 論文→ジャーナル→ライブブローカーキーは準備ができた場合のみ。"}]},{"id":"fomo","title":"8・FOMOと感情的規律","summary":"FOMO、復讐、貪欲、恐怖は、指標ではなく、実際のアカウントキラーです。衝動的な取引をアカウントから防ぐためのトリガー、ボディサイン、正確なルールを学びましょう。","lessons":[{"h":"FOMOとは実際何ですか","t":"FOMO = すでに自分のゾーンから遠く離れた動きを見逃すことへの恐怖。入場が遅れて料金が安くなり、適切な SL もありません。あなたが「見逃した」キャンドルは情報であり、損失ではありません。"},{"h":"3 つの FOMO トリガー","t":"① チャート上の大きな緑または赤のローソク足。 ② 利益を示す友人または電報の投稿。 ③ ニュースの見出し。エントリに気づく前にトリガーに注目してください。"},{"h":"ボディサイン","t":"心拍数が速く、画面にかがみ込み、「市場で今すぐ購入」をクリックしたくなる衝動に駆られ、チェックリストをスキップします。これらを感じた場合は、タブを閉じて 1 キャンドル待ってください。"},{"h":"「すでに実行されている」ルール","t":"価格が計画したエントリーを超えて約 1 ATR 以上変動した場合、取引は終了します。 BB ミッド/Fib への引き戻しを待つか、スキップします。常に別のセットアップがあります。"},{"h":"緑のキャンドルトラップ","t":"計画外の丸坊主はエントリーではなくチェイスです。遅れてエントリーすると、ストップが遠くに到達してしまうため、報酬とリスクが最悪になります。"},{"h":"復讐取引","t":"負けた後、脳は今度はそれを取り戻そうとします。ルール: 負けてから 15 ～ 30 分間は新たなエントリーを禁止し、チェックリストに問題がない場合に限ります。市場はあなたに何も負っていません。"},{"h":"引き金を引くのが怖い","t":"逆の問題: 完璧なセットアップが表示されてもフリーズしてしまいます。小さなデモ サイズを使用してプロセスを証明し、キャンドルが表示される前にサイズを決定して、すでに決定が行われているようにします。"},{"h":"勝利後の貪欲さ","t":"2 つのグリーントレードで無敵になったように感じられ、サイズも 2 倍になります。少なくとも 20 回の取引ではリスク % を固定します。連勝の意味が逆転します。"},{"h":"退屈な取引","t":"フラットはポジションです。 A+ 設定が存在しない場合は、何かを起こさないでください。退屈なトレードは FOMO を隠したものです。"},{"h":"スクリーンタイムの規律","t":"チャートを見つめるのではなく、1 日に 2 つまたは 3 つのスキャンウィンドウを設定します。決断が減れば、衝動的な決断も減ります。"},{"h":"感情日記","t":"各取引に冷静/急ぐ/FOMO/復讐のタグを付けます。 20回の取引を終えると、リークのパターンが明らかになります。"},{"h":"リセットの儀式","t":"損失またはFOMOスリップの後: 立ち上がって、ゆっくりと10回呼吸し、何が起こったかについて一文書き、その後1時間停止するか、通常の半分のリスクで継続します。"},{"h":"練習チェックリスト","t":"①体が穏やか？ ②トリガーは気づいた？ ③ 私のゾーンでセットアップしますか？ ④SLが先に書かれている？ ⑤リスク％は変わらない？ ⑥復讐しない？いかなる場合も NO → 取引はありません。"}]},{"id":"risk_deep","title":"9 · リスクと資金管理 — 詳細","summary":"アカウントを維持するための計算: 固定小数部サイジング、R 倍数、ドローダウン計算、相関熱、日次ストップ。トレーディングを数字で運営されるビジネスに変えましょう。","lessons":[{"h":"固定部分リスク","t":"アイデアごとに資本の固定 % (0.5 ～ 1%) のリスクを負います。サイズは停止距離の結果であり、最初に選択されることはありません。ワイドSL→小さいサイズ。タイトなSL→大きいサイズ。ドルリスクは変わらない。"},{"h":"サイズ計算式","t":"サイズ = (資本 × リスク%) ÷ |エントリー − ストップ|。例: 1000 ドル × 1% = 10 ドルのリスク。エントリー 100、ストップ 98 → 距離 2% → サイズ 10 ÷ 0.02 = 想定元本 500 ドル。"},{"h":"R倍数で考える","t":"取引ごとにリスク 1R。 2Rの勝者は2敗を支払う。 20 回の取引にわたる平均 R を追跡します。これが勝率ではなく、本当の強みです。"},{"h":"報酬：リスク","t":"エントリー前に少なくとも 1.5R のポテンシャルを目指してください。それ以下は、勝率がよほど高くない限りスキップしてください。"},{"h":"ドローダウンの計算","t":"-50% のドローダウンを回復するには +100% が必要です。連敗は普通のことです。勝率 60% のシステムでも、5 回以上の負けが続くことがあります。リスクが小さいため、連続記録を継続できます。"},{"h":"毎日のストップ","t":"厳格なルール: 1 日で資産が -2% になった後 (または 2 ～ 3 回連続で負けた場合)、取引を開始するのを停止します。制限後のリベンジセッションはアカウントキラーです。"},{"h":"毎週および毎月の制限","t":"また、週 (-5% など) と月の上限も設定します。ヒットしたら、デモにドロップし、ジャーナルを確認し、クリーンな実行後にのみサイズをバックアップします。"},{"h":"直火","t":"すべてのオープン取引の合計リスクは約 3% 以下にとどまるはずです。 5 つの相関する代替案は 5 つではなく 1 つのベットです。相関するエクスポージャを一緒にカウントします。"},{"h":"スポットサイジング","t":"スポットには最小の想定元本があります。最低取引所のリスクが 1% を超える場合は、取引をスキップしてください。リスクを切り上げないでください。"},{"h":"先物サイジング","t":"レバレッジはリスクではなくマージンを変更します。リスクは依然としてエントリー − ストップ × サイズです。学習中は低いレバレッジを使用し、分離マージンを優先します。"},{"h":"外国為替サイジング","t":"リスク = ロット × ピップ値 × ストップピップ。たくさん解決してください。大まかなガイド: 0.01 ロット ≈ 1 ピップあたり 0.10 ドル。 20 ピップストップのリスクは $1000 の 1% ($10) → 10 ÷ 0.10 ÷ 20 = 0.05 ロット。"},{"h":"スケールアウト","t":"TP1で約50％オフにして残りをフリーリスクにして、トレイルします。これにより、優れたトレードがストレスの少ないランナーに変わります。"},{"h":"複利と固定","t":"現在の株式の固定割合のリスクを負います (複利)。過去最高のアカウントサイズでリスクを修正しないでください。"},{"h":"Rの手数料とスリッページ","t":"R から手数料を差し引きます。0.5% の頭皮に対して 0.2% の手数料はエッジを拭くことができます。よりクリーンなスイングを好みます。"},{"h":"「ノーストップ・ノートレード」法","t":"論理的なストップを定義できない場合は、リスクがわからないため、サイズがなく、トレードができません。"},{"h":"反マーチンゲール法","t":"負けた後に倍増することはありません。サイズを拡大するには、数週間の収益性の高い、規律ある実証済みのプロセスを経た後にのみ、それもゆっくりと行ってください。"},{"h":"練習チェックリスト","t":"① 既知のエクイティ ② 書き込まれたリスク % ③ 定義されたストップ ④ ストップからのサイズ ⑤ 報酬 ≥ 1.5R ⑥ 毎日のストップが既知 ⑦ 相関ヒートのカウント。"}]},{"id":"sl_tp","title":"10 · ストップロスとテイクプロフィットの習得","summary":"市場があなたが間違っていると証明した場所に SL を配置し、段階的に利益を得て、勝者が実行できるようにストップを追跡します。これはまさに CPE がマルチ TP とトレーリング SL で行うことです。","lessons":[{"h":"SL は数値ではなく決定です","t":"ランダムな距離ではなく、アイデアが無効になる場所（スイングロー、ウィック、またはストラクチャーの下）にストップを置きます。あなたは情報を買っているのです。価格がここに行くなら、私の理由は間違っています。"},{"h":"ストラクチャーストップ","t":"ロング: スイングローまたはローバンドウィックのすぐ下の SL。ショート: スイングハイのすぐ上。スプレッドとウィックのノイズに対して小さなバッファ (約 0.1 ～ 0.3%) を与えます。"},{"h":"ボラティリティが止まる","t":"より広い市場にはより広い停留所が必要です。 ATR または芯の長さを使用してストップのサイズを設定し、ドルリスクが同じになるようにポジションを縮小します。"},{"h":"なぜ固定ドルSLは失敗するのか","t":"BTCの10ドルストップとEURUSDの10ドルストップは全く異なるリスクです。距離はドルではなく%で測定する必要があります。"},{"h":"アンチストップハントバッファ","t":"CPE は 1 回のウィック タッチを無視します。つまり、閉じる前に 2 回の連続した違反と少量のバッファ (0.15%) が必要です。これにより、停止場所を狙うノイズが止まります。"},{"h":"段階的に利益を得る","t":"決して 100% を 1 つの価格でクローズしないでください。スケールアウト: TP1 が一部を予約し、その後 TP2 / トレイルが残りをライドするため、大きな動きは多くの敗者に代償を払うことができます。"},{"h":"マルチTPレベル","t":"CPE を使用すると、TP レベルを必要なだけ追加でき、それぞれに独自のクローズ % が設定されます。例: TP1 40%、TP2 30%、TP3 30% — または TP1 を取得し、残りを追跡します。"},{"h":"ストップを追跡する","t":"TP1 の後、ストップを損益分岐点に移動します。 TP2 の後は TP1 に移動します。ストップが価格に従うようにして、ランナーが続行している間オープン利益が保護されるようにします。"},{"h":"トレイルの選択 %","t":"タイトなトレイルでは利益はすぐに確定しますが、早期に撤退します。広いトレイルは息を吹き返しますが、少しは戻ってきます。暗号通貨の場合は約 1 ～ 2% から始めて、ポジション編集モーダルで調整します。"},{"h":"ランナー","t":"価格が強いトレンドでバンド内を推移するときは、TP2 ですべてを取得するのではなく、ターゲットとトレイルを広げます。これが、1 回の取引で 1 週間分の利益を得る方法です。"},{"h":"途中で閉じるボタン","t":"ポジションの 50% / 100% クローズ ボタンを使用して手動で制御するか、オートクローズで計画に従って TP / SL を管理させます。"},{"h":"損益分岐点の罠","t":"TP1 よりも前に、SL を損益分岐点まで早めに移動させないでください。通常のプルバックでは、良い取引から外れてしまいます。"},{"h":"負けのストップを決して広げないでください","t":"スペースを与えるために SL をさらに遠くに移動すると、小さな損失がアカウントキラーになります。入場前に設定した停留所が停留所となります。"},{"h":"時間停止","t":"明らかにより良いセットアップが形成されているにもかかわらず、多くのローソク足で取引が何も起こらない場合は、フラットでクローズしてリスクを再配置することが有効な出口です。"},{"h":"練習チェックリスト","t":"① 無効化時の SL、ランダムではない ② ウィック用のバッファ ③ TP1 部分計画 ④ TP1 後のトレイル ⑤ SL を決して広げない ⑥ 勝者を走らせる。"}]},{"id":"plan_journal","title":"11 · 貿易計画とジャーナリング","summary":"書面による計画は、トレードをギャンブルからプロセスに変えます。 1 ページの計画、取引前チェックリスト、リークを可視化するための仕訳方法を学びましょう。","lessons":[{"h":"なぜ計画を書くのか","t":"書かれていない場合はルールではありません。計画を立てることで、ストレス下でのリアルタイムの意思決定が不要になり、結果が測定可能になります。"},{"h":"1ページのプラン","t":"ペア、市場、セットアップ（BB + RSI + ローソク足 + Fib ゾーン）、方向、エントリー、SL、TP1 / TP2、サイズ（SL から）、および 1 日の最大損失。いずれかの行が空白の場合 → トレードは行われません。"},{"h":"取引前チェックリスト","t":"高TFバイアス? · 私のゾーンでセットアップしますか?・キャンドル確定？ · RSI は同意しますか?・SLって書いてある？・リスク％？・報酬≧1.5R？・ 落ち着いた？すべてはい → 取引します。"},{"h":"セッション前のルーチン","t":"より高い時間枠、主要なレベル、ニュースを確認してください。ローソクが爆発した後ではなく、セッションの前に今日の 2 つまたは 3 つの時計ペアを書きます。"},{"h":"何を日記にするか","t":"シンボル、サイド、エントリー、イグジット、サイズ、R、理由、タイムフレーム、セッション、感情タグ。 CPE Journal は損益計算書と理由を自動的に保存します。自分のメモを追加します。"},{"h":"「なぜ」を記録する","t":"あなたが見たもの（セットアップ）とあなたが感じたもの（冷静/FOMO/急いでいる）を記録します。文脈のない結果は何も教えません。"},{"h":"勝利ではなくトラック R","t":"同じ勝率を持つ 2 人のトレーダーが逆の結果になる可能性があります。平均 R と最大ドローダウンは勝率よりも重要です。"},{"h":"スクリーンショットの習慣","t":"各取引の前後にチャートを保存します。 20 枚のスクリーンショットを確認すると、どの指標よりも早くエッジとリークがわかります。"},{"h":"週次レビュー","t":"週に 1 回、トレード、平均 R、最良および最悪のセットアップ、ルール違反を数えます。来週修正するリークを 1 つ選択してください。"},{"h":"リークにタグを付ける","t":"共通のタグ: 遅れて入場、SL なし、特大、移動した SL、復讐、退屈。タグが繰り返される場合は、それを厳格なルールに変えます。"},{"h":"ログに記録してはいけないもの","t":"勝者のみをログに記録しないでください。損失は​​データです。勝ちだけのジャーナルは、ジャーナルではなくパンフレットです。"},{"h":"デモ→ライブのステップを計画する","t":"リアルマネーを危険にさらす前に、プラスの平均 R で一定回数の取引のプランをデモで証明してください。その後、半分のサイズから始めてください。"},{"h":"練習チェックリスト","t":"① 入力前に計画を作成 ② チェックリストに合格 ③ 仕訳入力 + 感情 ④ 週次レビュー ⑤ 1 つの漏れを修正。"}]},{"id":"leverage","title":"12 · レバレッジ、マージン、清算","summary":"レバレッジは利益と同じくらいの速さで損失を倍増させます。マージン、清算、分離マージンとクロスマージン、および 1 つの取引でアカウントが消去されるのを防ぐ安全ルールについて学びます。","lessons":[{"h":"レバレッジとは何ですか","t":"レバレッジを利用すると、少ないマージンでより大きなポジションをコントロールできます。それは利益と損失の両方を増加させますが、あなたの優位性を増加させるわけではありません。"},{"h":"マージンとリスク","t":"証拠金は取引所にロックされる証拠金です。リスクはエントリー − ストップ × サイズです。レバレッジはマージンを変更しますので、ドルのリスクは決してありません。"},{"h":"清算","t":"損失が証拠金を食いつぶした場合、取引所はポジションを強制的に閉じます (清算) が、多くの場合最悪のタイミングで行われます。ストップを清算価格から遠く離れた場所に設定してください。"},{"h":"アイソレーション vs クロス","t":"孤立は、損失をその 1 つのポジションのマージンに制限します。クロスはウォレット残高全体を使用します。初心者にとってはより危険です。学習中は孤立することを好みます。"},{"h":"より安全なレバレッジ","t":"低レバレッジ (2 ～ 5 倍) に適切なストップを加えた方が、ストップなしの 50 倍よりもはるかに安全です。レバレッジの数値ではなく、ストップがあなたの保護です。"},{"h":"清算距離ルール","t":"SL が清算価格の範囲内に収まっていることを確認してください。近い場合は、快適なスペースが確保できるまでサイズを縮小します。"},{"h":"レバレッジをかけても悪いエントリーは修正されない","t":"間違ったエントリーでレバレッジを高くすると、損失が早くなるだけです。まずセットアップを修正してから、サイズを調整します。"},{"h":"資金と手数料","t":"無期限先物では、時間の経過とともに資金が請求されます。レバレッジを利かせた犯罪組織の長期保有は資金を流出させるが、これも慎重に規模と時間を設定する理由のひとつだ。"},{"h":"スポット vs 先物","t":"スポットは清算できません (コインの所有者はあなたです)。先物はゼロになる可能性がありますし、ゼロになる可能性もあります。先物取引は、書面による計画と分離証拠金がある場合にのみ使用してください。"},{"h":"レバレッジを活用したサイジング","t":"停止距離からサイズを計算し、結果として得られるマージンが手頃であることを確認します。最初にレバレッジを選択しないでください。"},{"h":"「ワントレード」テスト","t":"入る前に尋ねてください：これが停止に達した場合、それは肩をすくめるのでしょうか、それとも大惨事ですか？肩をすくめないとサイズが大きすぎます。"},{"h":"練習チェックリスト","t":"①孤立セット ②低レバレッジ ③清算価格内のSL ④ストップからのサイズ ⑤ここで全額損失しても耐えられるか？はい→取引します。"}]},{"id":"practice","title":"13 · ルーチンの練習とバックテスト","summary":"スキルはLIVEの前にDEMOで構築されます。反復可能な練習ループ、チャートをスクロールして「バックテスト」する方法、安全にリアルマネーを卒業する方法を学びましょう。","lessons":[{"h":"DEMOはジムです","t":"Paper / DEMO は、リスクゼロでプロセスと感情をリハーサルするために存在します。 DEMO でルールに従えない場合、LIVE では魔法のようにそれを修正することはできません。"},{"h":"練習ループ","t":"セットアップを 1 つ選択します (例: BB ロワー + ハンマー + RSI ターン)。チャート上の 20 の歴史的な例にマークを付けます。エントリー/SL/TPを定義します。結果を記録します。繰り返す。"},{"h":"手動バックテスト","t":"Chart Lab をスクロールして戻り、将来を非表示にし、各シグナルを手動でマークします。パターン認識を訓練し、自分自身をだますのを防ぎます。"},{"h":"サンプルサイズ","t":"10回の取引では何の意味もありません。判断する前に、1 つのセットアップで 30 ～ 50 件の取引を記録することを目指します。"},{"h":"DEMOでのフォワードテスト","t":"手動でマーキングした後、同じセットアップをソフトウェアの信号を使用してデモで 2 ～ 4 週間ライブで実行します。実際のフィルと感情をバックテストと比較します。"},{"h":"一度に 1 つのセットアップ","t":"一度に 5 つのシステムをテストしないでください。 1 つのエッジをマスターしてから、2 つ目のエッジを追加します。"},{"h":"ルーチンを小さく保つ","t":"20 分間の日課 (スキャン、マーク、日記、レビュー) は、ランダムなチャートを見つめる 6 時間に勝ります。"},{"h":"LIVEへの卒業","t":"基準: 30 回以上のデモ取引で平均 R がプラス、ルールに従い、復讐エピソードなし。次に、半分のサイズで LIVE を開始し、ゆっくりと拡大します。"},{"h":"スケールアップルール","t":"サイズを拡大するのは、一定の数の収益性の高い規律ある週を経た後のみであり、一度大きな勝利を収めた後では決して行わないでください。"},{"h":"いつ退くべきか","t":"日次または週次の損失制限に達した場合、または繰り返しのルール違反に気付いた場合は、続行する前にデモに戻り規律を再構築してください。"},{"h":"プロセスメトリクスを追跡する","t":"チェックリストの合格率、週ごとのルール違反数、平均 R をログに記録します。これらは、単一の損益計算書よりも成長を正確に予測します。"},{"h":"CPE 実践パス","t":"学習クラス → チャート ラボ (マーク セットアップ) → ペーパー トレード → ジャーナル レビュー → デモ上のシグナル デスク → 一致するプラットフォーム キー上の小規模なライブ。"},{"h":"練習チェックリスト","t":"① 1 つのセットアップを選択 ② マークされた 30 個の例 ③ デモフォワードテスト ④ ジャーナル + レビュー ⑤ ポジティブ R → 半角 LIVE。"}]},{"id":"volatility","title":"14 · ボラティリティとマーチンゲール法","summary":"市場のボラティリティ (価格が変化する理由) を読み取る方法、それが理由線としてすべてのシグナルに追加される方法、オプションのマーチンゲール ラダーがどのように機能するか、さらに、不注意に使用すると口座を失う最も早い方法である理由も説明します。","lessons":[{"h":"ボラティリティとは","t":"ボラティリティとは、価格がどの方向に動くかということではなく、どちらに動くかということです。ボラティリティが高い = ローソク足の幅が広く、スイングが速い。低いボラティリティ = 静かで狭いレンジ。同じ設定であっても、それぞれの信頼性は大きく異なります。"},{"h":"CPE ボラティリティ測定値","t":"各シグナルは平均ローソク足レンジとボリンジャーバンド幅を測定し、それらをそのペア自身の最近の通常値と比較します。 LOW / NORMAL / HIGH / EXTREME に加えて、わかりやすい言語の理由行、つまり市場変化の「理由」がシグナルとともに表示されます。"},{"h":"極端なボラティリティ = 格下げ","t":"テープが EXTREME の場合、新しい STRONG 信号は CAUTION に格下げされます (理由が表示されます)。ホイップソー市場では、同じパターンがはるかに頻繁に失敗します。偽のブレイクやストップハントの芯が標準的です。"},{"h":"HIGH / EXTREMEでやるべきこと","t":"小さめのサイズ。より広い停留所。取引が少なくなります。キャンドルの途中のスパイクではなく、キャンドルが完成するまで待ちます。読み取り値が「EXTREME」の場合は、セットアップをエントリーではなく研究ゾーンとして扱います。"},{"h":"マーチンゲールとは","t":"マーチンゲール法は、負けポジションを追加して平均エントリーを下げます。不利な動きをするたびに、通常より大きな注文を追加します (1x、2x、4x ...)。頻繁に勝ちますが、一度の失敗ですべてを失います。"},{"h":"CPEマーチンゲール則","t":"CPE は、両方が true の場合にのみ追加注文を追加します。(1) 価格が少なくともステップ × ラング % 取引に対して変動し、(2) 新しい同側シグナルがまだそのペアに存在します。価格が下がったからといって追加されることはありません。"},{"h":"4つの数字","t":"ステップ % = 各追加の前に必要な逆方向の移動。乗数 = ベースに対する各加算のサイズ (1 = フラット、2 = ダブル)。最大追加 = 追加注文のハードリミット。ラダー リスク キャップ % = 資本の % で表したラダー全体のリスク。 4 つすべてを選択できます。"},{"h":"ハードキャップがあなたを守ります","t":"大きな乗数と多くの追加を使用しても、ラダーの合計リスクが資本の上限 % を超えると、CPE は注文を拒否します。また、取引所の最小サイズと毎日の -2% ストップも尊重されます。"},{"h":"どこで実行されるか","t":"その 1 つの取引を管理するには手動にチェックを入れ、自動取引を管理するには自動セッションにチェックを入れます。デモもライブも両方あります。手動では、新しい同側信号を読み取ることができるように、ペアがスキャン リストに含まれている必要があります。"},{"h":"キャップが重要な理由 (例)","t":"1% のリスクをベースにステップ 1%、乗数 2、3 を加算すると、リスクは 1% → 2% → 4% → 8% となります。最終段での完全なストップアウトが 1 つあれば、多くの勝者が消えてしまいます。これが、上限が存在し、デフォルトの数値が小さい理由です。"},{"h":"反マーチンゲール法の代替案","t":"多くのプロはその逆を行い、勝者のみを追加し、敗者を迅速に切り捨てます。気分は悪くなりますが（小さな損失が増えます）、あなたに対する単一のトレンドでアカウントが爆破されることはありません。"},{"h":"リスクは除去されない","t":"平均値を下げることはリスクを除去するものではなく、リスクを「多数の小さな損失」から「1 つの大きな損失」に移動させます。決して失うことができない金額を追加したり、負けた取引を「取り戻す」ためにキャップをオフにしたりしないでください。"},{"h":"練習パス","t":"まずはデモでボラティリティの読み取り値を学びましょう。 30 以上の取引のデモで、最大加算 1 ～ 2 と小さな乗数を使用してマーチンゲール法を試してください。すべてのラダーを記録してから決定します。ほとんどのトレーダーはフラット/アンチマーチンゲール法の方が安全であると考えています。"},{"h":"ボラティリティ + マーチンゲール チェックリスト","t":"①最初にボラティリティレベルを読み取ります。 ②EXTREMEでスキップまたは縮小します。 ③新しい同サイドシグナルでのみマーチンゲールを行います。 ④ステップ×ランに到達します。 ⑤リスクキャップを下回る→追加します。任意の「いいえ」 → 追加しません。"}]},{"id":"lab_indicators","title":"15・チャートラボインジケーター（Stoch・ADX・一目均衡表・VWAP）","summary":"Chart Lab には完全なインジケーター バーが追加されました。すべてのボタンは、チャートを瞬時に再描画するオン/オフのチェックマークです。 BB / RSI / MACD / EMA / SMA50 / Volume に加えて、Stochastic、ADX/DMI、一目、VWAP も利用できるようになり、シグナル エンジンはチャートだけでなくそれらも読み取ります。","lessons":[{"h":"バーがある場所","t":"チャートラボ → チャートの下のボタンの「インジケーター」行。 1 回クリックするとインジケーターがオンになり、次のクリックでインジケーターがオフになります。チャートはすぐに再描画されます。目盛りは視覚的であり、信号エンジンに供給されます。"},{"h":"確率的 (14,3,3)","t":"ローソク足の下に描かれた %K / %D オシレーター、スケール 0 ～ 100。 ~80 以上 = 買われ過ぎゾーン、~20 以下 = 売られ過ぎゾーン。売られ過ぎゾーンで %K が %D までクロスアップするのは強気の研究です。上にクロスがあれば弱気です。強いトレンドでは、長期間一方の端に固定されたままになる可能性があります。常に BB とローソク足と組み合わせてください。"},{"h":"ADX/DMI (14)","t":"ADX は方向ではなくトレンドの強さを測定します。 ~25 を超える = 実際のトレンドが進行中です。 ~20 未満 = 途切れ途切れの範囲。 −DIを上回る+DI = 担当バイヤー。 +DIの上の−DI = 担当販売者。 ADX を使用して、トレンド取引をまったく行うか、それとも横ばいを続けるかを決定します。"},{"h":"一目雲 (9,26,52)","t":"テンカン（速い線）、キジュン（遅い線）、そしてセンコウ雲。上昇雲を上回る価格 = 強気の背景。落ちてくる雲の下 = 弱気。雲の中のテンカン/キジュンクロスは弱いです。価格が雲から離れるクロスはより強力です。多くの場合、クラウド エッジ自体がサポート/レジスタンスとして機能します。"},{"h":"VWAP","t":"出来高加重平均価格 — 出来高で加重された平均価格。セッションごとにリセットされます。大手機関はこれをベンチマークとしています。上昇する VWAP を上回る価格 = 買い手が主導権を握っている。下降トレンド中のVWAPでの明確な拒否は、短い調査です。年中無休の暗号通貨では、FX とは異なる方法でリセットされます。法律ではなくガイドラインとして扱います。"},{"h":"エンジンがそれらをどのように使用するか","t":"新しいインジケーターはそれぞれ、それが指すのと同じ側のスコアに小さな確認を追加します (ストキャスティクス、一目、VWAP、方向と一致する場合の ADX、およびエリオット)。これらはトリガーではなく確認です。BB / RSI / ローソク足と一致しない場合、スコアは単純にさらに複雑になり、より多くの HOLD が得られます。"},{"h":"CAUTIONが厳しくなった理由","t":"プール内にさらに多くのチェックがあるため、注意バーが強化されました。スコア ≥ 4 および少なくとも 3 つの一致するチェックが必要です。これにより、より多くのツールがオンになったからといって、アプリが弱い信号を大量に送信することがなくなります。"},{"h":"効果的な読み上げ順序","t":"①上位TF方向（一目雲+ADX）。 ② 価格は (BB / Fib / VWAP) です。 ③ モメンタム（RSI + ストキャスティクス）。 ④キャンドル確認。 ⑤リスク％とレベルが書かれている→最初に紙。"},{"h":"避けるべき間違い","t":"すべてのインジケーターをオンにして虹を見つめます。 ADX を方向として使用します (これは単なる強さです)。ストキャスティクスが強気相場の範囲内で >80 である場合にのみ空売りする。 VWAPは仮想通貨とFXでは意味が異なることを無視しています。"},{"h":"練習チェックリスト","t":"①クラウド+ADXからのバイアス ②BB/Fib/VWAPからの位置 ③RSI+Stochからのモメンタム ④ローソク確認 ⑤SL/TP書き込み ⑥論文、そしてジャーナル。"}]},{"id":"elliott","title":"16・エリオット波動（ライトカウント）","summary":"CPE には軽量のエリオット波動カウンターが含まれています。 Chart Lab インジケーター バーの「Elliott」にチェックを入れると、ローソク足の最後の 0-1-2-3-4-5 インパルスにラベルが付けられ、波動 5 のフィボナッチ ターゲットが投影されます。これは水晶玉ではなく、学習ツールです。","lessons":[{"h":"アイデアを一行で","t":"市場は波状に動きます。インパルス (トレンド方向の 5 つの足) と調整 (トレンド方向に向かう 3 つの足) です。 CPE は、トレンドを伝える部分であるインパルスのみをカウントします。"},{"h":"CPE のカウント方法","t":"最後のスイング ピボット (3 バー フラクタル) を見つけ、高値と低値を交互に切り替え、最後の 5 ～ 6 つのスイングをエリオット ルールに照らしてテストします。形状が適合する場合、0→5 ラベル (黄色のまだ続いている波) と、波 4 から測定された波 1 の長さ × 1.618 から構築された W5 ターゲット ラインが描画されます。"},{"h":"チェックするルール","t":"ウェーブ 2 はウェーブ 1 の開始点を通過しません。ウェーブ 4 はウェーブ 1 の領域と重なりません。 wave 3 は 1 / 3 / 5 の中で最も短いものではありません。ルールが失敗しても何も表示されず、強制的なカウントも行われません。"},{"h":"強気派 vs 弱気派","t":"0-1-2-3-4-5 の上昇は強気の衝動です。下落途中の鏡像は弱気だ。エンジンは波側のスコアに小さな確認を加えます。"},{"h":"ライブと完了","t":"ライブ ウェーブ 5 (まだ継続中) はトレンド継続と見なされます。 COMPLETE インパルス (0 ～ 5 が終了) は、傾向が疲れている可能性があることを警告します。多くの場合、調整が続きます。"},{"h":"W5ターゲットライン","t":"波動4の安値/高値からの波動1のフィボナッチエクステンション。それはターゲットのアイデアであり、磁石ではありません。価格はそれに達しないで止まることも、オーバーシュートすることもあります。"},{"h":"使い方","t":"カウントを合流点として扱います。キャンドルと RSI を備えた明確な BB / Fib ゾーンでは、衝動的なカウントが確信を与えます。それ自体は単なるスケッチにすぎません。"},{"h":"避けるべき間違い","t":"自分の位置に合うまで波を数え直す（典型的なエリオットの罪）。小さな揺れを数えます。より高いタイムフレーム数を無視します。新しいバーが印刷されるたびにカウントが変化することを忘れてください。"},{"h":"練習チェックリスト","t":"①クリアスイングピック ②ルールパス ③ジグザグがBB/Fibに一致 ④キャンドル確認 ⑤ウェーブ4無効点を超えたSL。"}]},{"id":"forecast","title":"17 · 3 か月予測 (予測 3M ティック)","summary":"長期予測: シグナル自体のトレンド、ターゲット、ボラティリティから構築された、このチャートが今後 3 か月以内にどのように形成される可能性があるかを示します。 Chart Lab の「Forecast 3M」チェックをオンまたはオフに切り替えます。","lessons":[{"h":"それが描くもの","t":"分析されたエントリから、エンジンがすでに知っている最適なターゲット (エリオット ターゲット → tp2 → tp1) に向かう破線の中心パス。妥当な価格の広がりを示す拡大する「円錐」に包まれています。月マーカー M+1 / M+2 / M+3 が地平線を分割します。"},{"h":"なぜ線ではなく円錐なのか","t":"将来の正確な価格を知ることは誰にもできません。円錐は時間の平方根とペア自体のボラティリティに応じて広がります。そのため、静かな FX ペアは狭い円錐となり、ワイルドなアルトコインは非常に広い円錐になります。この幅は、遠くに目を向けるほど、価格の不確実性が薄れるというメッセージです。"},{"h":"数字の出所","t":"ドリフトは現在の信号ターゲットから生じます。日次ボラティリティは、1 日にスケーリングされたシグナルの ATR% から得られるため、円錐形は 5 メートルまたは 1 日チャートで同じ意味になります。極端な/高いボラティリティはさらに幅を広げます。"},{"h":"読み方","t":"SLOPE (道がどの方向に傾いているか) と WIDTH (どの程度疑わしいか) を見てください。狭い円錐を持つ上昇パス = より安定したトレンドのアイデア。巨大な円錐のある平らなパス = 「ここにエッジはありません。ノイズが予想されます」。"},{"h":"オンとオフを切り替える","t":"「Forecast 3M」ボタンは「Future space」の隣にあります。 Future space (投影が描画される右側の空白領域) をオンにする必要があります。信号が HOLD の場合は方向がないため、何も描画されません。"},{"h":"それはトレンドであって貿易ではない","t":"予報は大局的な地図です。実際の取引レベル (エントリー、TP1 / TP2、SL、短期予測) が取引の対象となります。"},{"h":"正直な限界","t":"ニュース、上場、上場廃止、マクロシフトはモデルに含まれていません。この道は滑らかに推移するため、実際の価格はさらに大きく変動するでしょう。 3 か月コーンは学習の補助であり、決して約束するものではありません。"},{"h":"頻繁に再分析する","t":"新しいローソク足が印刷されると、ターゲット、ボラティリティ、したがってコーン全体が更新されます。予測はスナップショットであり、契約ではありません。"},{"h":"練習チェックリスト","t":"① パスの方向を読み取る ② コーンの幅を確認する ③ より高い TF 構造と比較する ④ 決してコーンからではなく、実際の SL から位置のサイズを決定します。"}]}],"platforms":{"BINANCE":{"title":"バイナンス取引 A → Z","steps":["アカウントを作成 → 2FA を有効にします。","API管理 → キーの作成 → 現物取引および/または先物取引がオン、出金がオフ。","CPE → API Keys → Binance → Save → Test Account にキーとシークレットを貼り付けます。","スポットデスク/先物デスクスキャンを使用します (公開チャートはキーの前でも機能します)。","練習: 手動トレード → ペーパートレードを開始します (ライブマネーなし)。","ライブ: TP1/TP2/SL + トレーリングを設定 → ライブトレードを開始します (API が必要です)。","ポジションで管理: レベルの編集、部分クローズ、自動キャンセル。","ライセンス: トライアル 7d → 3 か月または生涯 (アプリ内の所有者価格)。"]},"BYBIT":{"title":"Bybit取引A→Z","steps":["アカウント + 2FA。","API管理→取引のみ、出金OFF。","CPE → API キー → Bybit → 保存。","当事者の考え方のための先物デスク。キャンドルを研究するチャートラボ。","まずは紙貿易。キーが機能した後にライブします。","トレイル TP+SL: 買い↑ / 売り↓。"]},"OKX":{"title":"OKXトレーディングA→Z","steps":["API キー + シークレット + パスフレーズが必要です。","引き出しは常にオフです。","3 つのフィールドすべてを CPE キーに保存します。","ペーパー練習→小さいライブサイズ。","パスフレーズのタイプミスは最大の失敗です。慎重にコピーしてください。"]},"KUCOIN":{"title":"KuCoin取引A→Z","steps":["キー + シークレット + パスフレーズ。","貿易許可のみ。","CPEで紙→その後小さく生きる。","シグナルにはスポット/先物デスクを使用します。"]},"BITGET":{"title":"Bitget トレーディング A → Z","steps":["取引のみのAPI。","紙ならライブ。","先物: 手動取引でクロスまたは孤立を選択します。","TP+SLを追跡して利益を確定させます。"]},"GATE":{"title":"Gate.io トレーディング A → Z","steps":["API v4 キーを作成します (トレード)。","引き出しはオフです。","CPEに保存→紙の練習。","ライブ前にエントリをスキャン + チャート ラボで確認します。"]},"MEXC":{"title":"MEXCトレーディングA→Z","steps":["スポット思考を始めましょう。","CPE API キーのキー。","紙→ライブ。","トレイルを使用してオープン利益を確定します。"]},"KRAKEN":{"title":"クラーケントレーディングA→Z","steps":["取引許可のみを使用してキーを生成します。","出金/資金調達の権利はありません。","CPEでのペーパー実習。","Kraken 上のすべてのライブ注文も確認します。"]},"COINBASE":{"title":"Coinbase Advanced A → Z","steps":["高度な取引 API キー。","CPE のスポット集中型デスク。","紙ならライブ。","引き出しをオフにしておきます。"]},"FOREX_OANDA":{"title":"外国為替 (OANDA) A → Z","steps":["OANDA デモを開く → リスクは最大 1%。","CPE キー内の個人アクセス トークン + アカウント ID。","外国為替デスクスキャン + チャートラボ (EURUSD…)。","マニュアルトレード → 外国為替プラットフォームを使用したペーパー。","デモで自信を持って初めて生きてください。"]},"FOREX_FXCM":{"title":"FXCM 外国為替 A → Z","steps":["ブローカー API 認証情報。","最初に CPE に紙を入れます。","ロンドン/ニューヨークのセッションやニュースの急上昇をご覧ください。","ライブ後の練習日記はきれいに見えます。"]},"FOREX_MT5":{"title":"MetaTrader 5 A→Z","steps":["CPE キーのログイン + サーバー + パスワード。","可能な場合は、投資家 (読み取り) パスワードを使用してください。","練習ロット0.01。","CPE の紙。準備ができたらブローカー経由でライブします。"]},"FOREX_DEMO":{"title":"外国為替デモレート A → Z","steps":["API キーは必要ありません。","無料チャートのForex Desk + Chart Lab。","紙取引のみ（練習）。","実際のブローカーの準備ができたら、ライブ用の OANDA / FXCM / MT5 キーを追加します。"]}},"forexAz":{"title":"外国為替取引 A → Z (フルクラス)","lessons":[{"h":"A — アカウントとリスク","t":"まずはデモ。リスクはアイデアあたり約 0.5 ～ 1%。決して復讐取引をしないでください。"},{"h":"B — ペア","t":"エキゾチックの前にメジャー（EURUSD、GBPUSD、USDJPY）。"},{"h":"C — キャンドル","t":"Chart Lab Forex で童子、ハンマー、巻き込みを学びましょう。"},{"h":"D — 毎日のバイアス","t":"15分/30分エントリーの前に、より高いタイムフレームを確認してください。"},{"h":"E — エントリ","t":"BB 下部バウンス + キャンドル確認が一般的な設定です。"},{"h":"F — フィブ","t":"練習ゾーンとしてよく使用される50％/61.8％の引き戻し。"},{"h":"G — ゴール (TP)","t":"TP1 スケールアウト、TP2 ランナー、トレイル SL。"},{"h":"H — 時間","t":"ロンドンとニューヨークが重なる = 動きが増える。"},{"h":"I — 指標","t":"RSI + MACD + BB を組み合わせたもの。インジケーターの過負荷を避けてください。"},{"h":"J — ジャーナル","t":"すべての論文/ライブ取引を CPE Journal に記録します。"},{"h":"K — キー","t":"ライブ外国為替ブローカーには API/トークンが必要です。デモレートには何も必要ありません。"},{"h":"L — たくさん","t":"実践的な考え方で 0.01 ロットから始めてください。"},{"h":"M — 考え方","t":"予測よりもプロセス。悪い日はスキップしましょう。"},{"h":"N — ニュース","t":"大きなイベントの前にニュースと裏技をチェックしてください。"},{"h":"O — 注文","t":"必ずSLを設定してください。トレーリングはオープン利益を保護します。"},{"h":"P — 練習","t":"ペーパートレードボタン = ライブ API なしで練習します。"},{"h":"Q — 品質","t":"過剰取引に勝る高品質の設定はほとんどありません。"},{"h":"R — リスク:報酬","t":"可能であれば、報酬 ≥ リスクとなる設定を目指します。"},{"h":"S — セッション","t":"アジアは静かになる。ロンドン/NYをよりアクティブに。"},{"h":"T — トレンド","t":"学習時には、より高い TF トレンドでトレードします。"},{"h":"U — アップデート","t":"CPE アップデート バナー + ライブ ヘルプをご覧ください。"},{"h":"V — ボラティリティ","t":"ATRが急増した場合は忍耐力を広げてください。"},{"h":"W — API の引き出し","t":"API キーで引き出しを有効にしないでください。"},{"h":"X — 終了","t":"部分的なTP + トレイルは希望を上回ります。"},{"h":"Y — あなたの計画","t":"ルールを書きます。手動/自動でそれらに従ってください。"},{"h":"Z - ゼロラッシュ","t":"FOMOはありません。練習→その後、API をライブします。"}]}};

window.CPE_LEARN.ko = {"intro":"먼저 Paper/DEMO로 연습해 보세요. 양초, 차트, BB/RSI/Fib, 돈, 심리학을 연구한 다음 신호(매수/매도/보류의 의미 + 해야 할 일) 및 외환 신호를 연구합니다. Live에는 올바른 플랫폼 API 키가 필요합니다(출금 끄기).","candles":[{"shape":"doji","name":"도지","color":"#94a3b8","bias":"중립 / 기다려","tip":"열림 ≒ 닫힘 — 십자가 또는 얇은 몸체. 이동 후 시장의 우유부단함.","also":"또한 가르칩니다: FOMO를 하지 마십시오. 다음 촛불을 기다리세요. BB급 극단+도지=의견 압박; 방향을 추측하기 전에 RSI 기울기를 확인하세요."},{"shape":"hammer","name":"망치","color":"#22c55e","bias":"바이어스 구매","tip":"상단의 작은 몸체, 낙하 후 긴 하단 심지(2× 몸체) — 구매자는 낮은 가격을 거부했습니다.","also":"또한, 심지 아래에 연습용 SL을 배치하세요. 과매도에서 상승하는 낮은 BB + RSI에 가장 적합합니다. 심리학: 심지가 끝날 때까지 인내심을 갖고 심지 중간에 구매하지 마세요."},{"shape":"invhammer","name":"거꾸로 된 망치","color":"#22c55e","bias":"매수(약세)","tip":"바닥에 긴 위쪽 심지가 있습니다. 구매자는 높은 수준을 조사했지만 개장 근처에 마감했습니다. 다음 녹색 확인이 필요합니다.","also":"또한: 해머 단독보다 약합니다. 진입이 아닌 경고로 사용하십시오. Fib 61.8 바운스 + 인버티드 해머 = 확인 캔들까지만 연구 영역입니다."},{"shape":"shooting","name":"슈팅스타","color":"#ef4444","bias":"매도 편견","tip":"작은 몸체 바닥, 상승 후 긴 위쪽 심지 — 판매자는 최고점을 거부했습니다.","also":"또한: SL은 심지 높이보다 높습니다. 상단 BB 근처 / Fib 확장 / RSI 과매수 근처에서 더 강함. 가르칩니다: 달 양초는 실패할 수 있습니다. 마지막 그린을 쫓지 마십시오."},{"shape":"hanging","name":"교수형 남자","color":"#f59e0b","bias":"매도 주의","tip":"해머처럼 보이지만 상승 후에 나타납니다. 최고 피로가 발생할 수 있습니다.","also":"또한: 맥락이 ​​모든 것입니다(동일한 형태 ≠ 동일한 거래). 저널 위치: 상단 및 하단. 심리학: 모양이 일치한다고 해서 반전하지 마세요. 다음 캔들 + RSI로 확인하세요."},{"shape":"engulf_bull","name":"완고한 Engulfing","color":"#22c55e","bias":"구매","tip":"녹색 몸체는 이전 빨간색 몸체를 완전히 덮습니다. 구매자는 하나의 막대에서 제어권을 가졌습니다.","also":"또한: 지지력이 더 강함 / 낮은 BB / Fib 50–61.8. SL만큼 낮은 크기입니다. 머니팁: 넓은 감싸는 몸체 → 넓은 SL → 더 작은 크기."},{"shape":"engulf_bear","name":"약세를 휩싸는","color":"#ef4444","bias":"판매","tip":"빨간색 몸체가 이전 녹색을 완전히 덮고 있으며 판매자가 지배합니다.","also":"또한: 오픈 매수에 주의하세요. 상위 BB 근처 + RSI>70 = 높은 연구 품질. 위험을 가르칩니다. 이미 길다면 희망 대신 부분적인 TP/트레일을 하세요."},{"shape":"morning","name":"모닝스타","color":"#22c55e","bias":"구매","tip":"양초 3개: 큰 빨간색 → 작은 별 → 큰 녹색. 하단 반전 스토리.","also":"또한: 다중 촛불 인내심. 3차 마감 후 입장; SL 언더스타 로우. BB 하한 + 강세 RSI 발산과 잘 결합됩니다."},{"shape":"evening","name":"이브닝 스타","color":"#ef4444","bias":"판매","tip":"양초 3개: 큰 녹색 → 작은 별 → 큰 빨간색. 최고의 반전 스토리.","also":"또한: 중간 별만 단락시키지 마십시오. 3차 마감을 기다려주세요. 상부 BB/Fib 확장 합류점. 심리학: 첫 번째 그린런의 FOMO를 무시합니다."},{"shape":"maru_bull","name":"황소 마루보즈","color":"#22c55e","bias":"강한 매수 압력","tip":"긴 녹색 몸체, 심지 거의 없음 — 구매자가 열림→닫힘을 제어합니다.","also":"또한: 추세 지속 단서는 항상 바닥 매수가 아닙니다. 밴드 활동이 가능합니다. 위험 : BB mid / Fib로 풀백없이 후반 마루보즈를 쫓는다."},{"shape":"maru_bear","name":"곰 마루보즈","color":"#ef4444","bias":"강한 매도 압력","tip":"길고 빨간 몸체, 심지가 거의 없음 — 판매자가 통제합니다.","also":"또한, 떨어지는 칼을 잡지 마십시오. BB/Fib 바운스 + 해머는 나중에 기다리세요. 가르칩니다: 강한 압력 = 더 작은 크기 또는 옆으로 서십시오."},{"shape":"spin","name":"팽이","color":"#94a3b8","bias":"우유부단함","tip":"작은 몸집, 위쪽 + 아래쪽 심지 — 양쪽이 싸웠고 누구도 확실히 승리하지 못했습니다.","also":"또한: 내부 BB를 자주 짜내십시오. 거래를 일시 중지합니다. 휴식 시간 + 방향 촛불을 기다립니다. 심리학 교훈: 시장은 \"아무것도 할 수 없습니다\". 플랫이 유효한 선택입니다."},{"shape":"pierce","name":"피어싱 라인","color":"#22c55e","bias":"구매","tip":"빨간색과 녹색은 더 낮게 열리지만 이전 빨간색의 중간점 위에서 닫힙니다.","also":"또한 Engulfing보다 부드럽습니다. RSI 턴으로 확인하세요. 부분 강도 판독에 적합한 종이 드릴 - 모든 그린이 동일한 것은 아닙니다."},{"shape":"darkcloud","name":"어두운 구름 덮개","color":"#ef4444","bias":"판매","tip":"녹색, 빨간색 순으로 더 높게 열리지만 이전 녹색의 중간점 아래에서 닫힙니다.","also":"또한: Bear Engulfing이 완전히 발생하기 전 조기 경고. 트레일 롱/TP1을 선택하세요. 전체 반전 인쇄 전에 스케일 아웃을 학습합니다."},{"shape":"soldiers","name":"세 명의 백인 병사","color":"#22c55e","bias":"매수 추세","tip":"종가가 더 높은 세 가지 상승 그린 – 꾸준한 매수.","also":"또한: 강한 상승 추세 신호; Fib 38-50 또는 BB mid로의 풀백은 연습 추가입니다. 3번의 그린 이후에는 과신 위험이 있습니다. 위험 %를 고정 상태로 유지하세요."},{"shape":"crows","name":"검은 까마귀 세 마리","color":"#ef4444","bias":"매도 추세","tip":"종가가 낮은 세 개의 빨간색 하락 — 꾸준한 매도.","also":"또한 평균을 낮추지 마십시오. 대기 구조. RSI 과매도는 과매도 상태를 유지할 수 있습니다 — 돈의 법칙: 손실 한도 > 희망."},{"shape":"harami_bull","name":"완고한 하라미","color":"#22c55e","bias":"매수(소프트)","tip":"큰 빨간색, 이전 몸체 내부의 작은 녹색 - 판매 압력이 줄어들고 있습니다.","also":"또한: 조기 일시 정지 신호. 확인이 필요합니다. RSI 강세 발산 연구와 짝을 이룹니다. 반전뿐만 아니라 \"강도 페이딩\"을 읽는 방법도 가르칩니다."},{"shape":"harami_bear","name":"약세 하라미","color":"#ef4444","bias":"매도(소프트)","tip":"큰 녹색, 그 다음 작은 빨간색 내부 - 구매 압력이 줄어들고 있습니다.","also":"또한: 롱 포지션에서 부분적인 부분을 취하세요. 자동 단축이 아닙니다. 심리학: 빅 그린에 대한 탐욕은 종종 하라미 경고를 무시합니다."},{"shape":"tweezer_bot","name":"핀셋 바닥","color":"#22c55e","bias":"구매","tip":"저점이 일치하는 두 개의 양초 — 이중 지원 테스트.","also":"또한: 낮은 것을 구조로 표시하십시오. SL 바로 아래. Fib/BB 정렬이 도움이 됩니다. Double Bottom의 차트 패턴 사촌 — 동일한 지원 교훈."},{"shape":"tweezer_top","name":"핀셋 탑","color":"#ef4444","bias":"판매","tip":"최고점이 일치하는 두 개의 캔들 — 이중 저항 테스트.","also":"또한: 마크 저항. 더블탑의 사촌. 최고치에서의 RSI 실패 = 합류. 가르칩니다: 동일한 가격이 두 번 거부됨 = 수준을 존중합니다."},{"shape":"longlegged","name":"긴다리 도지","color":"#94a3b8","bias":"우유부단함","tip":"매우 긴 상부 심지와 하부 심지, 작은 몸체 — 격렬한 양방향 싸움이 시작된 곳에서 끝났습니다.","also":"또한: 큰 움직임이 자주 뒤따르지만 방향은 알 수 없습니다. 촛불이 깨질 때까지 기다리십시오. 가르칩니다: 높은 변동성은 높은 확실성이 아닙니다."},{"shape":"dragonfly","name":"잠자리 도지","color":"#22c55e","bias":"바이어스 구매","tip":"시가 = 종가 = 높음, 긴 아래쪽 심지 포함 - 판매자는 아래로 밀고 구매자는 다시 똑바로 세웠습니다.","also":"또한: 지지력이 가장 강하고 하락 후 BB가 낮아집니다. 심지 꼬리 아래에 SL이 있습니다. 가르칩니다: 거절은 보장이 아니라 이야기입니다. 다음 촛불을 확인하세요."},{"shape":"gravestone","name":"묘비 도지","color":"#ef4444","bias":"매도 편견","tip":"시가 = 종가 = 저점, 긴 상단 심지 — 구매자는 위로 밀고 판매자는 다시 저점으로 끌어냈습니다.","also":"또한: 저항이 가장 강함/상위 BB/RSI 과매수. 잠자리의 거울. 가르친다: 스파이크 고점은 저점에서 마감되며 이는 실패한 돌파입니다."},{"shape":"inside_bar","name":"바 내부","color":"#94a3b8","bias":"코일링 / 대기","tip":"두 번째 캔들이 첫 번째 캔들 안에 완전히 자리잡고 있습니다. 범위가 압축되고 시장이 숨을 멈춥니다.","also":"또한: 마더 바의 브레이크가 트리거입니다. 브레이크 방향으로 거래합니다. BB 스퀴즈와 짝을 이룹니다. 가르칩니다: 수축은 팽창보다 먼저 옵니다."},{"shape":"outside_bar","name":"외부 바","color":"#22c55e","bias":"돌파/반전","tip":"두 번째 캔들은 첫 번째 캔들을 높은 곳에서 낮은 곳으로 집어삼킵니다. 즉, 한 바 내부를 격렬하게 장악하는 것입니다.","also":"또한: 방향 = 외부 바가 닫히는 곳. 막대가 크다는 것은 SL이 크다는 것을 의미하므로 크기가 더 작습니다. 가르칩니다: 막대 하나가 마지막 세 개를 지울 수 있습니다."},{"shape":"belt_bull","name":"완고한 벨트 홀드","color":"#22c55e","bias":"구매","tip":"낮은 심지 없이 낮게 열리고 녹색으로 실행됩니다. 구매자가 첫 번째 틱부터 제어권을 가졌습니다.","also":"또한: 격차가 하락하거나 곧바로 지지를 받은 후에 가장 강력합니다. 오픈된 SL. 가르칩니다: 오프닝 드라이브는 실제 의도를 보여줍니다."},{"shape":"belt_bear","name":"약세 벨트 홀드","color":"#ef4444","bias":"판매","tip":"위쪽 심지 없이 높은 곳에서 열리고 빨간색으로 표시됩니다. 판매자가 열린 상태에서 이를 제어했습니다.","also":"또한: 갭 상승 후나 저항 상태에서 가장 강력합니다. 트레일이 길다. 가르칩니다: 첫 번째 움직임이 하루 전체를 정할 수 있습니다."},{"shape":"kick_bull","name":"완고한 키커","color":"#22c55e","bias":"적극 매수","tip":"빨간 양초에서 녹색 양초로 갭이 올라갔습니다. 분위기는 겹치지 않고 종가 사이에서 전환되었습니다.","also":"또한: 희귀하고 강력합니다. 간격은 필수이며 중복은 허용되지 않습니다. 교훈: 시장이 잠들어 있는 동안 정서는 뒤집힐 수 있습니다."},{"shape":"kick_bear","name":"약세 키커","color":"#ef4444","bias":"강한 매도","tip":"녹색 양초에서 빨간색 양초로 갭이 하락하여 종가 사이에 구매자가 사라졌습니다.","also":"또한: 롱을 빨리 종료하세요. 키커는 당신을 기다리지 않습니다. 가르칩니다: 격차는 귀하가 자리를 비울 때 시장이 다시 가격을 책정하는 것입니다."},{"shape":"abandoned","name":"완고한 버려진 아기","color":"#22c55e","bias":"적극 매수","tip":"빨간색 캔들, 갭이 있는 도지, 그리고 갭이 있는 녹색 캔들 — 우유부단함의 외로운 섬입니다.","also":"또한: 도지는 양쪽에서 떨어져 있어야 합니다. 드물지만 바닥의 품질이 높습니다. 가르친다: 모두가 포기하는 곳에서 반전이 시작됩니다."},{"shape":"three_inside_up","name":"세 개의 인사이드 업","color":"#22c55e","bias":"구매","tip":"강세 하라미와 첫 번째 캔들보다 종가가 높은 세 번째 녹색 캔들 - 내부 바가 마침내 돌파되었습니다.","also":"또한 확인된 하라미는 일반 하라미보다 훨씬 강합니다. SL은 하라미 로우 아래에 있습니다. 가르치다: 확인이 예측을 이긴다."},{"shape":"three_inside_down","name":"3개의 인사이드 다운","color":"#ef4444","bias":"판매","tip":"Bearish Harami와 세 번째 빨간색 캔들이 첫 번째 캔들 아래에서 마감되었습니다. 내부 바가 무너졌습니다.","also":"또한: 세 번째 거래가 마감되자마자 매수 포지션을 취하세요. 가르칩니다: 실패한 일시 중지는 단순히 이전 추세를 재개할 수 있습니다."},{"shape":"three_methods_bull","name":"라이징 세 가지 방법","color":"#22c55e","bias":"매수 추세","tip":"긴 녹색 양초, 그 안에 세 개의 작은 빨간색 양초, 그리고 또 다른 긴 녹색 양초 - 상승 안쪽에 나머지가 있습니다.","also":"또한 일시 정지가 첫 번째 캔들 범위를 벗어나지 않으므로 추세가 차분합니다. 마지막 캔들의 브레이크를 교환하세요. 가르칩니다: 추세는 깨지지 않고 유지됩니다."},{"shape":"three_methods_bear","name":"떨어지는 세 가지 방법","color":"#ef4444","bias":"매도 추세","tip":"긴 빨간 양초, 그 안에 세 개의 작은 녹색 양초, 그리고 또 다른 긴 빨간 양초 – 폭포 안에 있는 나머지.","also":"또한: Rising Three Methods의 거울입니다. 작은 채소를 사지 마십시오. 소음입니다. 교훈: 범위 내에서의 하락은 반전이 아닙니다."},{"shape":"tower_bot","name":"타워 바닥","color":"#22c55e","bias":"매수 반전","tip":"긴 빨간색 양초, 작은 양초 무리, 긴 녹색 양초 등 평평한 베이스를 따라 분위기가 전환됩니다.","also":"또한: 평평한 중앙이 전투이고 마지막 양초가 승자를 선언합니다. 가르칩니다: 기본에는 시간이 걸립니다."},{"shape":"tower_top","name":"타워탑","color":"#ef4444","bias":"매도 반전","tip":"긴 녹색 양초, 작은 양초 무리, 긴 빨간색 양초 - 구매자가 소진하고 판매자가 인수합니다.","also":"또한: 타워 바닥의 거울. 기본이 형성되는 동안 부분을 취하십시오. 가르칩니다: 탑은 순간이 아닌 과정입니다."}],"chartPatterns":[{"shape":"double_bot","name":"이중바닥(W)","color":"#22c55e","bias":"바이어스 구매","tip":"두 개의 저점이 같은 가격에 근접한 후 중간 고점을 돌파합니다 — W자 형태.","also":"또한: 네크라인 휴식 = 연습 트리거. TP 아이디어의 높이를 측정합니다. 피크→낮음에서 Tweezer Bottom + Fib로 연결됩니다. 위험: 잘못된 휴식 — 네크라인 너머로 가까이에서 기다리세요."},{"shape":"double_top","name":"더블탑(M)","color":"#ef4444","bias":"매도 편견","tip":"두 개의 고점이 같은 가격에 근접한 후 중간 저점을 돌파합니다 — M자 형태.","also":"또한 더 큰 규모에서는 Tweezer Top과 동일합니다. 트레일은 네크라인이 무너지기 오래 전부터 이어집니다. 심리학: 두 번째 상위 FOMO는 비용이 많이 듭니다. 계획은 이미 존재했습니다."},{"shape":"hs_top","name":"머리 & 어깨","color":"#ef4444","bias":"매도 편견","tip":"왼쪽 어깨, 높은 머리, 오른쪽 어깨; 네크라인을 무너뜨려라.","also":"또한: 고전적인 배포판. 목표는 목선 아래의 머리 높이입니다. RSI는 종종 머리에서 분기됩니다. 원캔들 거래가 아닌 다중 스윙 인내심을 가르칩니다."},{"shape":"ihs","name":"인버스H&S","color":"#22c55e","bias":"바이어스 구매","tip":"바닥에 거꾸로 된 H&S - 네크라인이 깨짐.","also":"또한: 축적 이야기. 가능한 경우 거래량/모멘텀으로 확인하세요. 합류 연구를 위해 오른쪽 어깨 부분에 Morning Star와 페어링합니다."},{"shape":"triangle","name":"삼각형(압착)","color":"#f0b429","bias":"브레이크아웃 대기","tip":"낮은 최고점 + 높은 최저점 압축 — 에너지 구축.","also":"또한: BB 스퀴즈와 동일한 레슨입니다. 내부 방향을 추측하지 마십시오. 거래 중단 + 캔들 청산. 돈: 알려진 방향 이후의 크기."},{"shape":"flag","name":"황소 깃발","color":"#22c55e","bias":"계속 구매하세요.","tip":"급격한 상승(극점) 이후 작은 하향/횡방향 채널 — 그 다음 계속됩니다.","also":"또한: Fib 플래그 깊이는 종종 얕습니다(38%). 마루보즈 극 + 깃발 = 추세 실천. 풀백 없이 풀 익스텐션 후 늦게 구매하지 마세요."},{"shape":"channel","name":"트렌드 채널","color":"#38bdf8","bias":"트렌드와 함께","tip":"상승(또는 하락) 평행선 사이의 가격 — 스윙 트레이딩 도구.","also":"또한: 낮은 채널을 구매하고 상승세를 유지합니다. 어퍼+슈팅스타 판매합니다. BB mid는 채널을 자주 추적합니다. “어떤 촛불”뿐만 아니라 “어디”를 가르칩니다."},{"shape":"support_res","name":"지지와 저항","color":"#a78bfa","bias":"맥락 우선","tip":"가격이 반복적으로 반응하는 수평 영역 — 모든 캔들 아래 지도.","also":"또한 모든 패턴은 S/R에서 더 강합니다. BB/RSI 이전에 Chart Lab에 영역을 그립니다. 심리학: 레벨 > 팁; 들어가기 전에 적어주세요."},{"shape":"triple_top","name":"트리플 탑","color":"#ef4444","bias":"매도 편견","tip":"거의 같은 가격에 세 번의 최고치 달성 - 구매자는 한 벽에서 세 번 실패합니다.","also":"또한: Double Top보다 강력합니다(3개의 거부 = 완고한 공급). 네크라인 붕괴가 유발 요인입니다. 목표 ≒ 패턴 높이. 가르칩니다: 양초가 아닌 수준이 보스입니다."},{"shape":"triple_bot","name":"삼중 바닥","color":"#22c55e","bias":"바이어스 구매","tip":"거의 같은 가격에 세 번의 최저점 — 판매자가 한 층에서 세 번 실패합니다.","also":"또한: 트리플 탑의 거울. 각 터치는 망치/집게 연구일 수 있습니다. 네크라인 브레이크 + 마감을 기다립니다. 여러 스윙에서 인내심을 가르칩니다."},{"shape":"cup_handle","name":"컵 & 손잡이","color":"#22c55e","bias":"계속 구매하세요.","tip":"둥근 \"U\"(컵), 작은 풀백(손잡이) - 휴식 후 계속됩니다.","also":"또한: 브레이크아웃 트레이더들에게 인기가 있습니다. 손잡이는 얕고 짧아야 합니다. 손잡이가 깊으면 손이 약하다는 의미입니다. 양초 확인을 통해 핸들 브레이크를 입력합니다."},{"shape":"rounding_bot","name":"둥근 바닥","color":"#22c55e","bias":"매수 반전","tip":"느리고 부드러운 \"접시\" 저점 — 판매가 점차 사라지고 구매자가 인수합니다.","also":"또한 슬로우모션 Double Bottom도 있습니다. 메시지는 판매자의 에너지가 고갈되었다는 것입니다. 단일 스파이크가 아니라 완전한 인내심이 필요하다는 것입니다."},{"shape":"rounding_top","name":"반올림 상단","color":"#ef4444","bias":"매도 반전","tip":"부드러운 \"돔\" 고점 - 가격이 상승하기 전에 매수세가 점차 사라집니다.","also":"또한: 둥근 바닥의 거울. 추진력이 사라지는 동안 초기에 부분적인 부분을 취하십시오. 가르칩니다: 상판은 하나의 양초가 아닌 과정입니다."},{"shape":"rising_wedge","name":"라이징 웨지","color":"#ef4444","bias":"매도 편견","tip":"두 레일 모두 올라가지만 위쪽으로 수렴됩니다. 범위가 좁아지면 구매자가 지치게 됩니다.","also":"또한: 가격이 여전히 상승하기 때문에 오해의 소지가 있습니다. 좁혀지는 것이 진짜 단서입니다. 종종 고장이 납니다. 마지막 추진력을 쫓지 마십시오."},{"shape":"falling_wedge","name":"떨어지는 쐐기","color":"#22c55e","bias":"바이어스 구매","tip":"두 레일 모두 떨어지지만 아래쪽으로 수렴됩니다. 범위가 좁아지면 판매자가 지치게 됩니다.","also":"또한: Rising Wedge의 거울. 종종 고장이 납니다. 웨지 테일의 해머는 고전적인 연구입니다. 휴식 시간 + 종료를 기다립니다."},{"shape":"asc_triangle","name":"상승삼각형","color":"#f0b429","bias":"바이어스 구매","tip":"평평한 천장 + 상승하는 바닥 — 구매자는 계속해서 고정된 저항으로 올라갑니다.","also":"또한 하나의 가격에 대한 압력이 형성됩니다. 브레이크아웃이 일반적입니다. 천장 위로 가까이 들어가세요. 가르칩니다: 구매자가 참을성이 없어집니다."},{"shape":"desc_triangle","name":"하강 삼각형","color":"#f0b429","bias":"매도 편견","tip":"평평한 바닥 + 떨어지는 천장 - 판매자는 고정된 지지대를 계속 밀어 넣습니다.","also":"또한: 상승삼각형의 거울. 브레이크 아웃이 일반적입니다. 바닥 아래로 가까이 들어가세요. 가르칩니다: 판매자가 통제권을 얻습니다."},{"shape":"pennant","name":"페넌트","color":"#22c55e","bias":"계속","tip":"날카로운 극과 작고 단단한 삼각형 - 추세가 다시 시작되기 전 매우 짧은 휴식 시간입니다.","also":"또한: 깃발과 비슷하지만 더 짧고 삼각형입니다. 목표 아이디어에 대한 극점을 측정합니다. 작은 코일 내부를 추측하지 마십시오."},{"shape":"flag_bear","name":"곰 깃발","color":"#ef4444","bias":"계속 판매","tip":"급격한 하락(극) 이후 작은 상향/측면 채널 — 그 다음 하향으로 지속됩니다.","also":"또한: Bull Flag의 거울. 작은 바운스는 반전이 아니라 일시 정지입니다. 깃발을 쫓아 최악의 가격에 구매하세요. 휴식을 기다리세요."},{"shape":"rectangle","name":"직사각형(범위)","color":"#f0b429","bias":"범위 거래","tip":"가격은 평평한 천장과 바닥 사이에서 움직입니다. 즉 측면 상자입니다.","also":"또한: 가장자리를 안쪽으로 페이드하고 바깥쪽으로 브레이크를 교환합니다. BB 스퀴즈는 일반적으로 직사각형 안에 위치합니다. 가르칩니다: 수준별 규율."},{"shape":"broadening","name":"확대 형성","color":"#f0b429","bias":"주의","tip":"더 높은 최고점과 더 낮은 최저점 - 범위가 꼬집는 대신 팬 아웃됩니다.","also":"또한: 혼란스럽고 감정적인 시장입니다. 중지는 양방향으로 모두 발생합니다. 더 작은 크기 또는 옆에 서십시오. 폭력적인 일방적인 움직임으로 끝나는 경우가 많습니다."},{"shape":"diamond","name":"다이아몬드","color":"#f0b429","bias":"반전","tip":"가운데는 넓고 양쪽 끝은 좁은 형태로 전형적인 토핑/바닥 구성입니다.","also":"또한: 변형된 다음 변형 해제되는 삼각형입니다. 브레이크 아웃 방향이 결정됩니다. 드물고 느리기 때문에 대부분의 행이 소음처럼 느껴집니다. 인내심을 가지십시오."},{"shape":"island_rev","name":"섬 반전","color":"#ef4444","bias":"반전","tip":"가격 격차가 사라지고 외로운 클러스터에서 거래된 다음 다시 격차가 발생하는 \"섬\"이 됩니다.","also":"또한 실제 격차가 필요합니다(주식/FX에서 더 일반적임). 섬에는 구매자 또는 판매자가 갇혀 있습니다. 섬의 양초가 아닌 간격을 신호로 취급하십시오."},{"shape":"breakaway_gap","name":"브레이크어웨이 갭","color":"#22c55e","bias":"추세 시작","tip":"범위나 베이스를 벗어난 간격 - 움직임은 쥐어짜는 것이 아니라 힘으로 시작됩니다.","also":"또한 탈진 공백과 달리 이동 초기에 나타납니다. 갭은 나중에 지지/저항으로 작용하는 경우가 많습니다. 가르친다: 모멘텀 대 가치 격차."},{"shape":"v_reversal","name":"V-반전","color":"#22c55e","bias":"반전","tip":"베이스 없이 즉각적으로 나타나는 급격한 자유낙하 — \"V\".","also":"또한 빠르고 무섭습니다. 종종 뉴스 중심입니다. 잡기 어렵고 추적하기 쉽습니다. 스파이크를 사는 대신 작은 풀백 + 캔들을 기다리십시오."},{"shape":"harmonic","name":"고조파 패턴","color":"#f0b429","bias":"반전 구역","tip":"각 다리에 피보나치 비율이 있는 측정된 지그재그(X-A-B-C-D) — \"Gartley/Bat\" 스타일 지도.","also":"또한: 고급. D 포인트는 감정이 아닌 비율로 정의되는 진입 영역입니다. 일반 Fib를 먼저 마스터하세요. 이것은 한 단계 더 깊이 취해진 Fib입니다."}],"modules":[{"id":"bb","title":"1 · 볼린저 밴드 (BB)","summary":"이동 평균 주위의 변동성 밴드. 스퀴즈, 밴드 걷기, 하단/상단 터치 + 캔들 확인 등 핵심 CPE 연습 설정을 알아보세요.","lessons":[{"h":"BB가 무엇인가요?","t":"볼린저 밴드 = 중간 SMA(종종 20) + N 표준 편차의 상한/하한 밴드(종종 2). 변동성이 높아지면 밴드가 넓어지고 시장이 조용해지면 밴드가 좁아집니다."},{"h":"중간 밴드","t":"가운데 선이 평균입니다. 중간 이상의 가격은 종종 강세 압력을 나타냅니다. 아래는 약세 압력을 보여줍니다. 마법의 매수/매도가 아닌 동적 바이어스 라인으로 사용하세요."},{"h":"낮은 밴드(구매 연습)","t":"하락 후 낮은 밴드에 가격표를 붙이는 것은 \"늘어났다\"는 의미일 수 있습니다. 모든 터치를 구매하지 마십시오. 강세 캔들(Hammer, Engulfing)과 이상적으로 RSI가 나타날 때까지 기다리십시오."},{"h":"상단밴드 (매도/주의)","t":"상단 밴드에 가격표를 붙이는 것은 \"확장\"을 의미할 수 있습니다. 상승 추세에서는 가격이 상단 밴드(밴드를 따라 이동)를 탈 수 있습니다. 약세 캔들 + 더 높은 TF 약점이 있는 SELL 아이디어를 선호합니다."},{"h":"짜내다","t":"좁은 밴드 = 낮은 변동성 → 종종 돌파가 뒤따릅니다. 꽉 쥐었을 때 방향을 추측하지 마십시오. 돌파를 표시하고 가능한 경우 캔들 + 거래량으로 확인합니다."},{"h":"밴드를 걷다","t":"강한 추세에서 가격은 많은 양초의 상단(또는 하단) 밴드를 맴돌고 있습니다. 평균 회귀 페이드와 싸우는 것은 초보자에게 흔히 발생하는 실수입니다."},{"h":"BB + 차트 연구실","t":"CPE Chart Lab/책상에서 DEMO의 양초를 들고 BB를 공부하세요. 연습: 하단 밴드 + 해머 → 심지 아래 SL, 중간 밴드 근처의 TP1로 Paper Trade."},{"h":"BB + RSI 콤보","t":"더 강력한 연습 필터: 낮은 BB + RSI 과매도(또는 과매도에서 상승) + 강세 캔들. 단기 연습을 위한 상위 BB + RSI 과매수 + 약세 캔들."},{"h":"배치 중지","t":"장기 연습: SL 언더 스윙 로우/하부 밴드 심지 아래. 단기 연습: SL이 스윙하이보다 높습니다. 서면 SL 없이는 BB 거래에 참여하지 마십시오."},{"h":"대상","t":"공통 경로: 중간 대역의 TP1, 반대 대역 또는 트레일 방향의 TP2. 확장 - 전체 이동이 필요하지 않습니다."},{"h":"기간","t":"더 높은 TF(4H/1D)에 대한 바이어스를 결정합니다. 15m/30m BB + 캔들에 입장하세요. 무작위 TF를 혼합하면 신호 충돌이 발생합니다."},{"h":"피해야 할 실수","t":"붕괴하는 시장에서 모든 저대역 터치를 구매합니다. 문런으로 모든 상위 터치를 판매합니다. SL 없음; 밴드를 폭력적으로 넓히는 뉴스 급증을 무시합니다."},{"h":"연습 체크리스트","t":"① 높은 TF 편향 ② BB 터치 또는 스퀴즈 브레이크 ③ 캔들 확인 ④ RSI 동의 ⑤ 위험 % 설정 ⑥ 문서 우선 ⑦ 저널 결과."}]},{"id":"rsi","title":"2 · RSI (상대 강도 지수)","summary":"모멘텀 발진기 0–100. 기본 14 기간. BB 및 캔들과 함께 사용하십시오. RSI만 전체 시스템으로 사용하지 마십시오.","lessons":[{"h":"RSI가 측정하는 것","t":"RSI는 N개 막대에 대한 평균 이익과 손실을 비교합니다. 높은 RSI = 최근 강세 모멘텀; 낮은 RSI = 최근 약세 모멘텀. 매번 “과매수=반드시 매도”하는 것은 아니다."},{"h":"클래식 존","t":"종종: 70 이상 = 과매수 영역, 30 미만 = 과매도 영역. 강한 추세에서는 RSI가 오랫동안 과매수/과매도 상태를 유지할 수 있습니다. 이는 정상적인 현상입니다."},{"h":"미드라인 50","t":"50을 넘는 RSI 교차점은 강세 편향을 뒷받침할 수 있습니다. 50 미만의 약세 편향. 많은 거래자들은 BB 중간 밴드가 있는 추세 필터로 50을 사용합니다."},{"h":"다이버전스 — 강세","t":"가격이 저점을 낮추고 RSI가 저점을 높임 → 하락 시 모멘텀 약화. 여전히 Paper 진입 전에 캔들 + 구조 브레이크를 기다립니다."},{"h":"다이버전스 - 약세","t":"가격 고점 상승, RSI 고점 하락 → 상승 모멘텀 약화. 저항 근처 또는 상위 BB 근처에서 슈팅 스타 / Engulfing으로 확인하십시오."},{"h":"실패 스윙","t":"RSI는 이전 극단을 다시 테스트하지 못한 후 50을 다시 통과합니다. 즉 초기 모멘텀 변화 단서입니다. Chart Lab 구조와 결합됩니다."},{"h":"RSI + BB(CPE 스타일)","t":"오랫동안 연습하세요: 낮은 BB 근처의 가격, RSI ≤ 35(또는 ≤ 30에서 상승), 강세 캔들. 짧게 연습하세요: 상단 BB, RSI ≥ 65–70, 약세 캔들."},{"h":"숨겨진 발산","t":"추세 지속 단서(예: 상승 추세에서 가격이 더 높고, RSI가 더 낮습니다). 고급 — DEMO에서 먼저 클래식 다이버전스를 마스터하세요."},{"h":"설정","t":"RSI(14)가 일반적인 기본값입니다. RSI가 짧을수록 소음이 커집니다. 신호를 강제하기 위해 설정을 계속 변경하지 마십시오."},{"h":"RSI로 종료","t":"과매도 매수했다면 RSI가 중상위권에 도달할 때 부분적인 이익을 취하는 것이 합리적입니다. 나머지는 구조나 BB 중간으로 추적합니다."},{"h":"뉴스 & RSI","t":"큰 뉴스는 RSI를 즉시 급등시킬 수 있습니다. RSI 극단에 조치를 취하기 전에 첫 번째 강렬한 촛불이 끝날 때까지 기다리는 것이 좋습니다."},{"h":"실수","t":"강세장에서 모든 RSI>70을 매도합니다. 하락장에서 모든 RSI<30을 갈망합니다. 합류 없음; RSI가 \"더 좋아 보일 때\" 복수 재진입."},{"h":"연습 체크리스트","t":"① RSI 값 + 기울기 참고 ② BB 위치 확인 ③ 양초 확인 ④ TF 높음 ⑤ 종이 + 저널 ⑥ 한 번에 하나의 아이디어."}]},{"id":"fib","title":"3 · 피보나치(되돌림 및 확장)","summary":"명확한 스윙 하이 → 스윙 로우(또는 리버스)에서 풀백과 목표를 측정합니다. BB/RSI 합류점인 38.2 · 50 · 61.8에 중점을 둡니다.","lessons":[{"h":"Fib를 사용하는 이유","t":"많은 거래자들이 동일한 비율을 관찰하므로 유동성은 종종 그 비율 근처에서 반응합니다. Fib는 가능한 영역의 지도이지만 보장되는 것은 아닙니다."},{"h":"스윙 포인트","t":"항상 명확한 스윙에서 낮은 스윙에서 높은 스윙(위로 이동) 또는 높은에서 낮은 스윙(아래로 이동)으로 그립니다. 나쁜 스윙 = 쓸모없는 수준. Chart Lab DEMO에서 스윙 피킹을 연습해보세요."},{"h":"주요 되돌림","t":"공통: 23.6%(얕은), 38.2%, 50%(순수한 Fib는 아니지만 널리 사용됨), 61.8%(황금), 78.6%(깊은). 깊은 되돌림은 추세 약세를 나타낼 수 있습니다."},{"h":"풀백 매수(상승 추세)","t":"임펄스 상승 후 38.2~61.8 영역 + 강세 캔들 + 바람직하게는 BB 중간/하단 지지 또는 RSI >40~45로 하락할 때까지 기다립니다."},{"h":"풀백 매도(하락 추세)","t":"임펄스 하락 후 38.2~61.8 + 약세 캔들 + RSI가 55~60 미만으로 하락합니다."},{"h":"확장/대상","t":"공통 확장: 127.2%, TP2 아이디어의 스윙을 넘어서는 161.8%. 트레일과 함께 사용 - 정확한 틱을 강요하지 마십시오."},{"h":"합류 = 힘","t":"모범 사례 영역: Fib 50/61.8 + BB 중간/낮음 + 이전 구조 + RSI 회전. 하나의 Fib 라인만으로는 약합니다."},{"h":"FIB + BB","t":"61.8%가 상승 추세에서 낮은 BB 근처에 있는 경우 해당 중복은 고품질 논문 연구 영역입니다. 캔들 확인으로만 입장하세요."},{"h":"다중 Fibs","t":"초보자는 한 번의 클린 스윙을 사용해야 합니다. 5개의 Fib를 쌓으면 차트 노이즈와 FOMO 항목이 생성됩니다."},{"h":"무효화","t":"가격이 귀하의 편견에 비해 확실히 78.6%를 넘어서 마감되면 철수 논제는 종종 실패합니다. 즉, 청산하거나 물러서십시오."},{"h":"외환 대 암호화폐","t":"같은 비율. 외환 전공자는 유동 세션에서 레벨을 더 명확하게 존중하는 경우가 많습니다. 암호화폐는 통과한 다음 반전할 수 있습니다. 크기는 더 작아집니다."},{"h":"실수","t":"작은 소음 스윙에 Fib 그리기; 촛불 없이 공중에 진입하는 것; Fib가 \"거의\" 유지되었을 때 SL을 더 멀리 이동합니다. 더 높은 TF를 무시합니다."},{"h":"연습 체크리스트","t":"① 마크스윙 ② Note 38.2/50/61.8 ③ 가격도착 대기 ④ 캔들 + RSI/BB ⑤ 리스크세트 ⑥ Paper → Journal."}]},{"id":"money","title":"4 · 자금관리","summary":"이 방법이 실제로 사용되는 방법: 고정된 비율, 중지 크기, 이익의 은행 부분 및 손실 한도 다음 날 중지의 위험을 감수합니다. CPE는 이를 수동 및 자동 거래에 적용할 수 있습니다.","lessons":[{"h":"자금관리의 목표","t":"게임에 계속 참여하세요. 한 번의 나쁜 거래로 인해 계정이 삭제되어서는 안 됩니다. 일관성이 복권 크기 결정을 능가합니다."},{"h":"거래자가 실제로 그것을 사용하는 방법","t":"일반적인 관행은 고정 부분 위험입니다. 코인 금액을 먼저 선택하지 마세요. 먼저 중지를 작성하고 이 아이디어가 계정의 약 1%를 잃을 수 있다고 결정한 다음 크기가 그 밖으로 떨어집니다. 넓은 스톱은 위치가 더 작아집니다. 타이트 스톱은 더 큰 포지션을 차지하고 달러 위험은 거의 동일하게 유지됩니다. 이는 자금 관리 체크가 켜져 있을 때 CPE가 사용하는 방법입니다."},{"h":"실제 사례($1000 연습 계정)","t":"계좌 $1000. 위험 1% = $10. 항목 100, 중지 98. 거리 = 2%. 규모 = 10 ¼ 0.02 = 명목상 $500. 정지에 도달하면 손실은 $500가 아니라 약 $10입니다. 가격이 103(위험의 1.5배)에 도달하면 이익은 약 $15입니다. 모든 쌍에 대해 동일한 아이디어: 위험에 처한 달러는 거의 1%에 머물며 코인 수량은 변경됩니다."},{"h":"CPE가 진드기로 하는 일","t":"지금 거래 → 자동: “자금 관리 사용”을 선택하세요. 자동 구성을 저장합니다. 각각의 새로운 자동 거래는 $1000 연습 계좌의 약 1%와 해당 신호 항목 및 SL의 크기로 마감된 결과를 사용합니다. 현물 및 선물 최소 금액은 존중됩니다. 교환 최소 금액의 위험이 1%를 초과하는 경우 해당 거래는 건너뜁니다. 해당 날짜에 약 -2%가 지나면 새 자동차는 다음 날까지 정지됩니다. 공개 거래에서 최대 약 3%가 위험에 처해 있습니다. 수동 거래에는 동일한 틱이 있습니다. Signal History에는 여전히 $10 테스트가 표시되고 그 아래에는 $1000 계정에 대한 1% 계획 크기가 표시되므로 두 가지를 모두 볼 수 있습니다."},{"h":"부분 이익과 흔적","t":"연습은 첫 번째 목표(종종 약 절반)에서 참여하고 나머지는 추적하는 것입니다. 정지점이 위로 이동하면 대상도 이동할 수 있으므로 승자는 첫 번째 대상보다 더 많은 금액을 지불할 수 있습니다. 원래 아이디어에 대한 위험은 증가하지 않습니다. 강한 신호는 5% 위험을 감수하는 이유가 아닙니다. 동일한 1%가 사용됩니다. 흔적은 강한 승자가 성장할 수 있게 해주는 것입니다."},{"h":"일일 정지 및 개방 열","t":"익숙한 규칙: 당일 계좌의 약 2% 하락한 경우 거래 개시를 중단하십시오. 각각 1%의 세 가지 개방형 아이디어는 약 3%의 열입니다. 상관관계가 있는 코인 5개는 5개가 아닌 1개의 베팅입니다. 함께 세어보세요."},{"h":"이 방법이 거부하는 것","t":"마틴게일(손실 후 두 배 증가)은 사용되지 않습니다. 진입 후 \"공간 확보\"를 위해 정지점을 더 멀리 이동하는 것은 사용되지 않습니다. \"확실한\" 신호에 대한 올인은 사용되지 않습니다. 유효한 중지가 없으면 크기가 없으므로 거래가 없습니다."},{"h":"거래당 위험","t":"일반적인 규칙: 단일 아이디어에 대해 계정 자산의 0.5~1%만 위험에 빠뜨립니다. DEMO에서는 LIVE와 같은 비율의 습관을 연습해보세요."},{"h":"위치 크기 공식","t":"크기 ≒ (계정 × 위험%) ¼ (진입 − 정지 거리). 더 넓은 SL → 더 작은 크기. 크기를 먼저 선택하고 SL을 두 번째로 선택하지 마십시오."},{"h":"위험 : 보상","t":"학습 시 잠재적 보상 ≥ 위험(예: 1:1.5 이상)인 아이디어를 선호하세요. TP1에서 확장하여 주자가 \"위험 없이\" 활동할 수 있도록 합니다."},{"h":"부분적 이익 실현","t":"CPE 스타일: TP1은 일부 이익을 잠그고, TP2/나머지는 추적합니다. 은행 부분은 감정적 공황을 줄여줍니다."},{"h":"후행 TP + SL","t":"구매: 가격이 상승함에 따라 트레일 수준이 올라갑니다. 판매: 아래로 내려가세요. 후행 잠금은 완벽한 종료 호출 없이도 이익을 얻습니다."},{"h":"일일/주간 손실 한도","t":"예제 규칙: -2% 계정 다음 날 거래를 중지합니다. 손실 한도 이후의 복수 세션은 계정 킬러입니다."},{"h":"스팟 크기 조정","t":"현물 최소 개념이 중요합니다(예: 교환 분). 여전히 위험%를 적용하십시오. 최소 크기가 SL에 비해 너무 많은 위험이 있는 경우 거래를 건너뛰십시오."},{"h":"선물/레버리지","t":"레버리지는 이익과 손실을 모두 증가시킵니다. 높은 레버리지 + 넓은 SL = 계좌 손실. 학습하는 동안 낮은 레버리지를 선호합니다. 절연은 포지션당 손실을 상한할 수 있습니다."},{"h":"상관관계","t":"5개의 상관 BTC 대체 상품 열기 = 5개가 아닌 하나의 큰 베팅입니다. 위험을 그룹으로 계산합니다."},{"h":"수수료 및 미끄러짐","t":"단단한 두피는 차트에서 좋아 보이지만 수수료는 R:R을 먹습니다. 비용을 알 때까지 DEMO에서 더 깔끔한 스윙을 선호하십시오."},{"h":"DEMO → 라이브 브릿지","t":"CPE DEMO 연습(~3개월 사고방식): 동일한 저널 규칙, 동일한 %. LIVE일 때 처음 몇 주 동안은 DEMO 크기의 절반을 시작하세요."},{"h":"API 자금 안전","t":"모든 키에서 출금이 OFF됩니다. 매칭 플랫폼에서 Test Account OK 이후에만 라이브가 가능합니다. 잘못된 플랫폼 비밀 = 실패했거나 위험한 작업입니다."},{"h":"실수","t":"마틴게일(패배 후 두 배); SL을 더 멀리 이동; \"확실한\" 설정에 올인; 최소 크기와 위험%를 무시합니다. 매일 멈추지 않고 거래합니다."},{"h":"연습 체크리스트","t":"① 기록된 위험 % ② SL 거리에 따른 크기 ③ 계획된 TP1/TP2/트레일 ④ 알려진 최대 일일 손실 ⑤ 종이 우선 ⑥ 저널 PnL을 솔직하게 기록합니다."}]},{"id":"psych","title":"5 · 거래 심리학","summary":"사고방식은 BB/RSI/Fib 기술이 실제 화면에서 살아남는지 여부를 결정합니다. FOMO, 복수, 과신, 두려움 — 이러한 지표를 DEMO와 같이 훈련하세요.","lessons":[{"h":"심리학이 중요한 이유","t":"완벽한 BB+RSI 계획은 일찍 진입하거나 SL을 건너뛰거나 복수 거래를 하면 실패합니다. 기술 = 시스템 × 규율."},{"h":"예측보다 과정","t":"미래를 예측할 필요는 없습니다. 규칙을 실행해야 합니다: 설정 → 위험 → 관리 → 저널. 결과는 다양합니다. 프로세스를 제어할 수 있습니다."},{"h":"포모","t":"놓칠 것에 대한 두려움 = 이미 BB/Fib 영역에서 멀리 떨어진 녹색 양초를 쫓는 것입니다. 규칙: 항목을 놓친 경우 다음 설정을 기다리십시오. Chart Lab에는 항상 또 다른 양초가 있습니다."},{"h":"복수거래","t":"손실을 입은 후에는 \"지금 다시 되찾고 싶다\"는 충동이 계정을 파괴합니다. 필수 쿨다운: 자리를 떠나고, 손실을 기록하고, 체크리스트가 깨끗한 경우에만 다음 거래를 하세요."},{"h":"승리 후 과신","t":"3연속 승리 ≠ 크기를 5배 늘립니다. 위험 %를 고정된 상태로 유지하세요. 연속 승리는 대부분의 사람들이 돈 규칙을 어길 때 발생합니다."},{"h":"손실 이후의 두려움","t":"빨간 날 이후에 모든 유효한 설정을 건너뛰는 것도 편향입니다. 서면 계획을 신뢰하십시오. 필요한 경우 일시적으로 크기를 줄이고 프로세스를 중단하지 마십시오."},{"h":"분석 마비","t":"10개 지표 불일치 → 동결. CPE 핵심을 고수하세요: 캔들 + BB + RSI(+ Fib 영역). 도구의 양보다 품질."},{"h":"틸트 & 뉴스","t":"뉴스 스파이크 아드레날린에 큰 빨간 촛불. 구조 개혁이 이루어질 때까지 주요 미지의 상황에서는 플랫을 선호합니다. 자아는 행동을 원합니다. 계획은 인내심을 원합니다."},{"h":"저널 = 치료 + 데이터","t":"CPE Journal에 감정 태그(FOMO, 서두르다, 차분함)를 적어보세요. 감정의 패턴은 손익 단독보다 더 빠르게 누출을 드러냅니다."},{"h":"서면 규칙","t":"쓰지 않으면 규칙이 아닙니다. 예: \"BB+캔들+RSI만, 위험 1%, 하루 −2% 이후에는 거래 불가, 체크리스트 20개 논문까지 데모.\""},{"h":"환경","t":"수면, 배고픔, 전화 방해로 인해 결정이 달라집니다. 지쳤을 때 크기를 늘리지 마십시오. 거래는 운동입니다. 두뇌를 보호하세요."},{"h":"사회적 소음","t":"전보의 \"신호\"와 과대광고는 당신의 계획을 깨뜨립니다. CPE 학습 수업 + 일기장 > 무작위 팁. 주문이 아닌 상황에 따라 뉴스와 요령을 필터링하세요."},{"h":"정체성 변화","t":"“내가 옳아야 한다”가 아니라 “나는 체크리스트를 따른다”라고 생각하십시오. 작은 위험으로 인해 잘못되는 것은 정상입니다. 큰 위험을 무릅쓰고 고집을 부리는 것은 선택 사항입니다."},{"h":"체육관으로서의 DEMO","t":"DEMO/Paper를 사용하여 감정을 안전하게 연습해보세요. DEMO에서 규칙을 따를 수 없다면 LIVE는 마법처럼 규율을 고치지 않습니다."},{"h":"연습 체크리스트","t":"① 나는 침착합니까? ② 체크리스트가 완료되었나요? ③ 위험%는 변하지 않았나요? ④ 복수가 아닌가? ⑤ 솔직하게 일기를 쓸 것인가? NO → 거래가 없는 경우."}]},{"id":"signals","title":"6 · CPE 신호 — 의미 및 수행할 작업","summary":"현물/선물/외환 데스크에는 BUY · SELL · HOLD + 점수가 표시됩니다. 모든 플랫폼에서 동일한 엔진 아이디어 — 그러나 API 키를 저장한 플랫폼에서만 거래합니다. 각 신호의 의미와 신호가 나타난 후의 정확한 단계는 다음과 같습니다.","lessons":[{"h":"신호가 어디서 오는지","t":"CPE는 BB, RSI, 피보나치, 캔들 스틱, EMA 크로스, SMA50, MACD 및 모멘텀을 평가합니다. 점수 ≥ +3 → 매수. 점수 ≤ −3 → 매도. → HOLD 사이. 이것은 도우미 등급이지 이익을 약속하는 것이 아닙니다."},{"h":"매수 신호 - 의미","t":"현재 강세 합류가 더 강합니다(예: 낮은 BB 바운스, RSI 과매도 턴, 강세 캔들, 골든 크로스, Fib 지원). 제안된 TP1 / TP2 / SL이 행 / 차트 랩 / 지금 거래에 나타납니다."},{"h":"매도 신호 - 의미","t":"약세 합류가 더 강합니다(상위 BB / 과매수 RSI / 약세 캔들 / 데스 크로스 / Fib 저항). 현물 매도(SELL)는 일반적으로 시장에서 매도(선물/외환)를 허용하는 경우에만 매수/매도 또는 매도를 의미합니다."},{"h":"HOLD 신호 — 의미","t":"혼합 또는 약한 점수. 거래를 강요하지 마십시오. 플랫이 맞습니다. ★ 관심 목록에 추가하고 더 명확한 매수/매도 또는 BB 하위 후보를 기다립니다."},{"h":"점수 번호","t":"더 높은 |점수| = 도구 간의 더 많은 합의. BUY +5는 BUY +3보다 강력합니다. 여전히 차트 랩 캔들에서 크기를 확인하세요."},{"h":"BB 하판","t":"볼린저 하한 밴드를 태그하는 별도의 쌍 목록 - 긴 후보자를 연습하십시오. 여전히 촛불 + RSI 확인이 필요합니다. 모든 낮은 터치가 항목은 아닙니다."},{"h":"플랫폼 대 신호(중요)","t":"신호 수학은 Binance, Bybit, OKX, KuCoin, Bitget, Gate, MEXC, Kraken, Coinbase, OANDA, FXCM, MT5, Forex Demo의 아이디어와 동일합니다. 주문을 보내는 위치는 어떻게 변경됩니까? API 키/지금 거래에서 선택한 플랫폼만 해당됩니다. 바이낸스 구매는 Bybit에서 열리지 않습니다."},{"h":"암호화폐 스팟 플랫폼","t":"Binance Spot, Coinbase 등: 구매 = 견적을 통해 코인을 구매합니다(예: USDT). SELL = 보유 자산을 매도 / 이익을 얻습니다. 최소 크기(예: ~$11)가 중요합니다. 레버리지가 없습니다."},{"h":"암호화폐 선물 플랫폼","t":"바이낸스 선물거래, Bybit, OKX, Bitget…: 매수 = 매수; 매도 = 매도. 교차/격리 + 레버리지를 신중하게 선택하세요. 트레일: 트레일 TP+SL 상승 매수; SELL이 하락했습니다."},{"h":"외환 플랫폼","t":"OANDA / FXCM / MT5 / Forex 데모: FX 쌍에 대한 동일한 구매/판매/보류 라벨(EURUSD...). 구매 = 기본 통화 구매; SELL = 기반을 판매합니다. 동전 수량 대신 랏(예: 0.01)입니다. 세션과 뉴스가 더 중요합니다."},{"h":"매수(BUY) 표시가 나타나면 이렇게 하세요","t":"① 행을 열고 → Why/캔들/RSI를 읽어보세요. ② 차트 랩 확인(15m~1H). ③ DEMO 먼저: 지금 거래 → TP1/TP2/SL/trail 설정 → 데모/Paper 시작. ④ 해당 플랫폼에서 API 테스트 후 OK → 소규모 LIVE만 가능합니다. ⑤ 저널 결과."},{"h":"SELL이 나타나면 이렇게 하십시오.","t":"① 현물 매수인 경우: TP/부분 청산/추적을 고려하세요. 무시하지 마세요. ② Futures/Forex 및 Plan이 매도를 허용하는 경우: Chart Lab을 확인한 다음 SL로 Paper/Live 매도를 확인합니다. ③ 어제 HOLD가 더 좋았다면 뒤집기 크기로 복수하지 마십시오."},{"h":"HOLD가 나타나면 다음을 수행하십시오.","t":"새로운 수동 입력이 없습니다. 계속 스캔하세요. ★ 관심목록을 추가하세요. 학습 학습 수업 / 차트 연구실 이미 거래 중인 경우에만 트레일로 오픈 포지션을 보호하세요."},{"h":"자동 거래 + 신호","t":"BB Lower + Strong Score 규칙이 저장된 자동 구성과 일치하면 자동 구매(Auto BUY)가 열릴 수 있습니다. 여전히 DEMO 테스트 자동 먼저. LIVE 자동 = 실제 위험 — 출금 꺼짐, 작은 크기."},{"h":"알림","t":"구매 신호 토스트는 귀하의 언어를 따릅니다. 이를 시장 주문 그 자체가 아니라 데스크를 열라는 경고로 취급하십시오."},{"h":"하지 말아야 할 것","t":"차트 없이 모든 구매를 구매하지 마세요. Bybit에서는 바이낸스 키를 사용하지 마세요. SL을 건너 뛰지 마십시오. 녹색 신호가 1번 표시된 후에는 크기를 늘리지 마세요. HOLD를 \"거의 구매\"로 거래하지 마십시오."},{"h":"빠른 행동 카드","t":"Signal → Chart Lab → Risk % → TP1/TP2/SL → DEMO Paper → Journal → (나중에) 일치하는 플랫폼 키에 대한 LIVE."}]},{"id":"forex_sig","title":"7 · 외환 신호 — 의미 및 해야 할 일","summary":"Forex Desk는 FX 쌍에 대해 동일한 BUY/SELL/HOLD 등급을 사용합니다. 외환 신호가 암호화폐와 어떻게 다른지, 신호 → 종이 → 라이브 브로커의 정확한 단계를 알아보세요.","lessons":[{"h":"외환 데스크 신호","t":"EURUSD, GBPUSD, USDJPY… 암호화폐처럼 구매/판매/보유 + 점수를 받으세요. 차트, 심리학 텍스트, 제안 수준을 보려면 행을 클릭하세요."},{"h":"Forex에서 구매 — 의미","t":"기본 통화를 구매하세요(예: EURUSD 구매 = USD 대비 EUR 구매). 가격 상승을 기대합니다. 연습하는 Chart Lab 외환 간격(15m/30m/1H)을 사용하세요."},{"h":"Forex에서 판매 — 의미","t":"베이스를 매도합니다(쌍 매도). 가격 인하를 기대합니다. 항상 SL을 구조/상위 대역 아이디어보다 높게 설정하십시오."},{"h":"외환 보유","t":"명확한 가장자리가 없습니다. 건너뜁니다. 특히 큰 뉴스(NFP, CPI, 중앙은행) 이전에는 HOLD/플랫을 선호합니다."},{"h":"외환 데모 환율 플랫폼","t":"API 키가 없습니다. 연습용 차트 + 종이만 가능합니다. OANDA/FXCM/MT5 라이브 이전의 학습 수업 훈련에 적합합니다."},{"h":"OANDA 신호 → 동작","t":"① 외환데스크 매수/매도. ② 차트랩 확인. ③ API Key → OANDA 토큰 + Account ID → Test. ④ 먼저 CPE의 DEMO Paper입니다. ⑤ TP/SL/트레일을 갖춘 소규모 라이브 부지(0.01 사고방식)."},{"h":"FXCM / MT5","t":"동일한 신호 판독. API 키 아래에 해당 브로커의 자격 증명을 연결합니다. 키/브리지가 설정될 때까지 Signal은 MT5에 자동 로그인하지 않습니다. 테스트가 OK될 때까지 Paper를 연습하세요."},{"h":"세션","t":"런던-뉴욕 중복은 종종 전공을 더 많이 이동시킵니다. 아시아는 더 조용할 수 있습니다. HOLD는 일반적이고 건전합니다."},{"h":"확산 및 뉴스","t":"뉴스 주변에서는 스프레드가 확대됩니다. 좋은 기술 구매는 여전히 나쁜 채우기일 수 있습니다. 뉴스와 요령을 확인하세요. 스파이크 후 캔들이 닫힐 때까지 기다립니다."},{"h":"랏 대 암호화폐 수량","t":"외환 규모 = 로트, 동일한 방식으로 USDT 개념이 아님. 위험 %는 여전히 규칙입니다: 더 넓은 SL → 더 작은 로트."},{"h":"외환시장에서 BB 하락","t":"같은 생각: 낮은 밴드 근처의 쌍 + 해머 + RSI 상승 = 오랜 연구 연습. 더 높은 TF 편향(4H/Daily)을 확인합니다."},{"h":"Forex BUY가 실행될 때 — 단계","t":"① 이유를 읽어보세요. ② 더 높은 TF 편향 괜찮나요? ③ 심지/구조물 너머에 SL을 표시합니다. ④ 종이무역. ⑤ 라이브 브로커가 준비된 경우 → 작은 크기 + 트레일. ⑥ 저널 세션(런던/뉴욕) + 감성."},{"h":"Forex SELL이 실행될 때 — 단계","t":"① 뉴스 중간 급등이 아닌지 확인합니다. ② 차트랩 약세 캔들. ③ 종이가 짧거나 길다. ④ 짧으면 아래로 내려간다. ⑤ 미스 후 이중 추첨을 하지 마십시오."},{"h":"외환과 암호화폐의 차이","t":"연중무휴 암호화폐; Forex에는 세션이 있습니다. 암호화폐 최소 $는 자주 발생합니다. 외환 랏 + 핍 가치. 많은 대체 암호화폐가 상호 연관되어 있습니다. Forex 전공은 학습을 위해 더 깨끗합니다."},{"h":"연습 체크리스트(FX)","t":"① 짝 전공? ② 세션 괜찮나요? ③ 뉴스가 깨끗해졌나요? ④ BUY/SELL 신호가 HOLD가 아닌 건가요? ⑤ 차트 확인? ⑥ 위험%? ⑦ 종이 → 저널 → 라이브 브로커 키는 준비된 경우에만 가능합니다."}]},{"id":"fomo","title":"8 · FOMO 및 정서적 규율","summary":"FOMO, 복수, 탐욕, 두려움은 지표가 아닌 실제 계정 킬러입니다. 귀하의 계정에서 충동 거래를 방지하는 트리거, 신체 신호 및 정확한 규칙을 배우십시오.","lessons":[{"h":"FOMO가 실제로 무엇인지","t":"FOMO = 이미 자신의 영역에서 멀리 떨어진 수를 놓치는 것에 대한 두려움. 이는 더 나쁜 가격과 적절한 SL 없이 늦게 입장하게 만듭니다. 당신이 \"놓친\" 양초는 손실이 아니라 정보입니다."},{"h":"세 가지 FOMO 트리거","t":"① 차트에 있는 큰 녹색 또는 빨간색 캔들. ② 수익을 내는 친구나 텔레그램 게시물. ③ 뉴스 헤드라인. 항목을 확인하기 전에 트리거를 확인하십시오."},{"h":"신체 징후","t":"빠른 심장박동, 화면을 향한 기대, 지금 시장 구매 클릭 충동, 체크리스트 건너뛰기. 이런 느낌이 들면 탭을 닫고 촛불 하나를 기다리십시오."},{"h":"\"이미 실행됨\" 규칙","t":"가격이 계획된 진입보다 약 1 ATR 이상 이동한 경우 거래가 종료됩니다. BB mid/Fib로 풀백을 기다리거나 건너뜁니다. 항상 또 다른 설정이 있습니다."},{"h":"녹색 캔들 트랩","t":"당신이 계획하지 않은 마루보즈는 진입이 아니라 추격입니다. 늦게 입장하면 최악의 보상을 받게 됩니다. 정류장이 멀리 떨어져 있기 때문에 위험이 따릅니다."},{"h":"복수거래","t":"패배 후에 두뇌는 이제 그것을 되찾고 싶어합니다. 규칙: 손실 후 15~30분 동안 새 항목을 입력할 수 없으며 체크리스트가 깨끗한 경우에만 가능합니다. 시장은 당신에게 빚진 것이 없습니다."},{"h":"방아쇠를 당기는 것에 대한 두려움","t":"반대 문제: 완벽한 설정이 나타나고 정지됩니다. 작은 DEMO 크기를 사용하여 프로세스를 증명하고 촛불이 나타나기 전에 크기를 결정하여 이미 결정이 내려지도록 하세요."},{"h":"승리 후의 탐욕","t":"두 번의 녹색 거래로 인해 무적이라는 느낌이 들고 크기가 두 배로 커집니다. 최소 20번의 거래에 대해 위험 %를 고정으로 유지하십시오. 연승 평균 회귀."},{"h":"지루함 거래","t":"플랫은 포지션이다. A+ 설정이 존재하지 않으면 어떤 일이 발생하지 않도록 하세요. 지루함 거래는 변장한 FOMO입니다."},{"h":"화면 시간 규율","t":"차트를 쳐다보는 대신 하루에 2~3개의 스캔 창을 설정하세요. 결정이 적다는 것은 충동적인 결정이 적다는 것을 의미합니다."},{"h":"감성일지","t":"각 거래에 침착함/급함/FOMO/복수를 태그하세요. 20번의 거래 후에는 누출 패턴이 분명해집니다."},{"h":"의식 재설정","t":"손실이나 FOMO 실수 후: 일어서서 천천히 10번 숨을 쉬고 일어난 일에 대해 한 문장을 쓴 다음 한 시간 동안 멈추거나 일반적인 위험의 절반으로 계속하십시오."},{"h":"연습 체크리스트","t":"① 차분한 몸? ② 트리거가 감지되었나요? ③ 내 영역에 설정하시겠습니까? ④ SL이 먼저 쓰여졌나요? ⑤ 위험%는 변하지 않았나요? ⑥ 복수가 아닌가? 모두 NO → 거래 불가."}]},{"id":"risk_deep","title":"9 · 위험 및 자금 관리 - 심층","summary":"계정을 유지하는 수학: 고정 분수 크기 조정, R-배수, 감소 수학, 상관 열 및 일일 정지. 거래를 숫자로 운영되는 비즈니스로 전환하세요.","lessons":[{"h":"고정 부분 위험","t":"아이디어당 고정된 %(0.5-1%)의 자산 위험을 감수하세요. 크기는 정지 거리의 결과이며 먼저 선택되지 않습니다. 넓은 SL → 작은 크기; 타이트한 SL → 더 큰 사이즈; 달러 위험은 동일하게 유지됩니다."},{"h":"크기 조정 공식","t":"크기 = (자본 × 위험%) ¼ |Entry − Stop|. 예: $1000 × 1% = 위험 $10. 항목 100, 중지 98 → 거리 2% → 크기 10 ¼ 0.02 = 명목상 $500."},{"h":"R 배수로 생각하기","t":"거래당 위험 1R. 2R 승자는 두 번의 손실에 대한 비용을 지불합니다. 20개 이상의 거래에 대한 평균 R을 추적하세요. 이것이 승률이 아니라 실제 우위입니다."},{"h":"보상 : 위험","t":"진입 전 최소 1.5R의 잠재력을 목표로 하세요. 그 아래에서는 승률이 매우 높지 않는 한 건너뛰세요."},{"h":"드로다운 수학","t":"−50% 하락률을 회복하려면 +100%가 필요합니다. 연속 패배는 정상적인 현상입니다. 승률이 60%인 시스템이라도 5회 이상의 패배가 발생합니다. 작은 위험으로 인해 연속 생존이 가능해집니다."},{"h":"일상의 정지","t":"엄격한 규칙: 하루에 자기자본이 −2%(또는 연속 2~3회 손실) 이후에는 거래 시작을 중지합니다. 한도 이후의 복수 세션은 계정 킬러입니다."},{"h":"주간 및 월간 한도","t":"또한 주(예: -5%)와 월의 상한선을 지정합니다. 히트가 발생하면 DEMO로 이동하여 저널을 검토한 다음 깨끗하게 실행한 후에만 크기를 다시 늘리십시오."},{"h":"열기 열기","t":"모든 공개 거래의 총 위험은 약 3% 이하로 유지되어야 합니다. 5개의 상관 대체는 5개가 아닌 1개의 베팅입니다. 상관된 노출을 함께 계산합니다."},{"h":"스팟 크기 조정","t":"스팟에는 최소 개념이 있습니다. 교환 최소 금액이 1%보다 더 많은 위험을 초래할 경우 거래를 건너뛰십시오. 위험을 반올림하지 마십시오."},{"h":"선물 규모","t":"위험이 아닌 변화 마진을 활용하십시오. 위험은 여전히 ​​Entry − Stop × 크기입니다. 학습 시 낮은 레버리지를 사용하고 격리 마진을 선호합니다."},{"h":"외환 규모","t":"위험 = 랏 × 핍 가치 × 스톱핍. 많은 문제를 해결하세요. 대략적인 가이드: 0.01랏 ≒ 핍당 $0.10; $1000($10)의 1% 위험을 감수하는 20핍 스톱 → 10 ¼ 0.10 ¼ 20 = 0.05랏."},{"h":"확장","t":"TP1에서 약 50% 할인을 받아 나머지는 무료로 만든 다음 트레일을 따라가세요. 이것은 좋은 거래를 스트레스가 적은 주자로 바꿉니다."},{"h":"복리 대 고정","t":"현재 자기자본의 고정된 %를 위험에 빠뜨립니다(복리). 사상 최대 규모의 계정 규모로 위험을 해결하지 마십시오."},{"h":"R의 수수료 및 미끄러짐","t":"R에서 수수료를 뺍니다. 0.5% 두피에 대해 0.2% 수수료로 가장자리를 닦을 수 있습니다. 더 깔끔한 스윙을 선호합니다."},{"h":"“멈추지 않고 거래하지 말라”는 법","t":"논리적 중지를 정의할 수 없으면 위험을 알 수 없으므로 크기가 없으므로 거래가 없습니다."},{"h":"안티 마틴게일","t":"손실 후 두 배로 늘리지 마십시오. 입증된 프로세스를 통해 몇 주 동안 수익성이 있고 규율이 잘 잡힌 프로세스를 거친 후에만 규모를 늘리십시오. 그 후에도 천천히 규모를 늘리십시오."},{"h":"연습 체크리스트","t":"① 알려진 자산 ② 작성된 위험 % ③ 정의된 중지 ④ 중지의 크기 ⑤ 보상 ≥ 1.5R ⑥ 알려진 일일 중지 7 상관 열 계산."}]},{"id":"sl_tp","title":"10 · 손절매 및 이익실현 숙달","summary":"시장이 틀렸다는 것을 증명하는 곳에 SL을 배치하고 단계적으로 이익을 얻고 승자가 달릴 수 있도록 정지를 추적하십시오. CPE가 다중 TP 및 후행 SL에서 수행하는 것과 정확히 같습니다.","lessons":[{"h":"SL은 숫자가 아니라 결정이다","t":"임의의 달러 거리가 아닌 아이디어가 무효화되는 지점(스윙 로우, 심지 또는 구조 아래)에 스톱을 배치합니다. 귀하는 정보를 구매하고 있습니다. 가격이 여기에 표시되면 제 이유가 잘못된 것입니다."},{"h":"구조 정지","t":"롱(Long): 스윙 로우 또는 로우밴드 심지 바로 아래의 SL. Short: 스윙하이 바로 위. 확산 및 심지 소음에 대해 약 0.1~0.3%의 작은 버퍼를 제공합니다."},{"h":"변동성은 멈춘다","t":"더 넓은 시장에는 더 넓은 정류장이 필요합니다. ATR 또는 심지 길이를 사용하여 정지 크기를 조정한 다음 달러 위험이 ​​동일하게 유지되도록 위치를 줄입니다."},{"h":"고정달러 SL이 실패하는 이유","t":"BTC의 10달러 정지와 EURUSD의 10달러 정지는 완전히 다른 위험입니다. 거리는 달러가 아닌 %로 측정되어야 합니다."},{"h":"안티 스톱헌트 버퍼","t":"CPE는 단일 윅 터치를 무시합니다. 닫히기 전에 두 번의 연속 위반과 작은 버퍼(0.15%)가 필요합니다. 그러면 정류장을 찾는 데 따른 소음이 발생하지 않습니다."},{"h":"단계적으로 이익을 얻으세요","t":"한 가격으로 절대 100% 청산하지 마세요. 확장: TP1 책 부분, TP2/트레일 부분이 나머지 부분을 담당하므로 큰 움직임으로 많은 패자를 보상할 수 있습니다."},{"h":"다중 TP 수준","t":"CPE를 사용하면 필요한 만큼 TP 수준을 추가할 수 있으며 각 수준에는 자체 마감%가 있습니다. 예: TP1 40%, TP2 30%, TP3 30% — 또는 TP1을 선택하고 나머지를 추적합니다."},{"h":"정류장 추적","t":"TP1 이후에는 손익분기점으로 정지를 이동합니다. TP2 이후에는 TP1로 이동합니다. 정지가 가격을 따르도록 하여 주자가 계속되는 동안 공개 이익이 보호되도록 하십시오."},{"h":"트레일 % 선택","t":"좁은 길은 이익을 빠르게 잠그지만 일찍 종료됩니다. 넓은 길은 숨을 쉬지만 약간의 회복을 제공합니다. 암호화폐의 경우 약 1~2%에서 시작하여 포지션 편집 모달에서 조정하세요."},{"h":"주자","t":"가격이 강한 추세로 밴드를 따라갈 때 TP2에서 모든 것을 가져가는 대신 목표와 트레일을 넓히십시오. 이것이 한 거래가 일주일 내내 지불하는 방법입니다."},{"h":"부분 닫기 버튼","t":"수동으로 제어하려면 포지션의 50% / 100% 청산 버튼을 사용하거나 계획에 따라 자동 청산으로 TP / SL을 관리하도록 하세요."},{"h":"손익분기 트랩","t":"TP1 이전에 SL을 너무 일찍 손익분기점으로 이동하지 마십시오. 정상적인 하락으로 인해 좋은 거래가 중단될 것입니다."},{"h":"절대 손실 정지점을 넓히지 마세요.","t":"공간을 확보하기 위해 SL을 더 멀리 옮기는 것은 작은 손실이 계정 킬러가 되는 방법입니다. 진입 전 설정한 정류장이 정류장입니다."},{"h":"시간 정지","t":"확실히 더 나은 설정이 형성되는 동안 많은 양초에 대해 거래가 아무 것도 하지 않는 경우, 평평하게 마감하고 위험을 재배치하는 것이 유효한 출구입니다."},{"h":"연습 체크리스트","t":"① 무작위가 아닌 무효화 시 SL ② 윅용 버퍼 ③ TP1 부분 계획됨 ④ TP1 이후 추적 ⑤ 절대 SL을 확대하지 않음 ⑥ 승자가 실행되도록 합니다."}]},{"id":"plan_journal","title":"11 · 무역 계획 및 저널링","summary":"서면 계획은 거래를 도박에서 과정으로 전환합니다. 한 페이지 분량의 계획, 거래 전 체크리스트, 일기를 작성하여 누출 내용을 눈에 띄게 만드는 방법을 알아보세요.","lessons":[{"h":"계획을 작성하는 이유","t":"쓰지 않으면 규칙이 아닙니다. 계획은 스트레스 상황에서 실시간 의사 결정을 없애고 결과를 측정 가능하게 만듭니다."},{"h":"한 페이지 계획","t":"페어, 시장, 설정(BB + RSI + 캔들 + Fib 영역), 방향, 진입, SL, TP1/TP2, 크기(SL에서) 및 최대 일일 손실. 빈 줄이 있으면 → 거래가 불가능합니다."},{"h":"거래 전 체크리스트","t":"더 높은 TF 편향? · 내 영역에 설정하시겠습니까? · 캔들 확인? · RSI는 동의합니까? · SL이 작성되었나요? · 위험 %? · 보상 ≥ 1.5R? · 침착한? 모두 예 → 거래합니다."},{"h":"세션 전 루틴","t":"더 높은 기간, 주요 수준 및 뉴스를 확인하세요. 촛불이 터진 후가 아니라 세션 전에 오늘의 두세 개의 시계 쌍을 작성하십시오."},{"h":"무엇을 일기로 적을 것인가","t":"기호, 측면, 항목, 종료, 크기, R, 이유, 기간, 세션 및 감정 태그입니다. CPE Journal은 P/L과 이유를 자동으로 저장합니다. 나만의 메모를 추가하세요."},{"h":"이유를 저널링하세요","t":"본 것(설정)과 느낀 것(침착함/FOMO/급함)을 기록하세요. 맥락이 없는 결과는 아무 것도 가르쳐주지 않습니다."},{"h":"트랙 R, 승리 아님","t":"동일한 승률을 가진 두 트레이더는 반대의 결과를 가질 수 있습니다. 평균 R과 최대 손실률은 승률보다 더 중요합니다."},{"h":"스크린샷 습관","t":"각 거래 전후에 차트를 저장하세요. 20개의 스크린샷을 검토하면 어떤 지표보다 더 빠르게 가장자리와 누출이 표시됩니다."},{"h":"주간 검토","t":"일주일에 한 번 거래, 평균 R, 최고 및 최악의 설정, 규칙 위반을 계산합니다. 다음 주에 수정할 누수 중 하나를 선택하세요."},{"h":"누출에 태그를 지정하세요.","t":"공통 태그: 늦게 입장, SL 없음, 대형, SL 이동, 복수, 지루함. 태그가 반복되면 이를 엄격한 규칙으로 바꾸세요."},{"h":"기록하지 말아야 할 것","t":"승자만 기록하지 마세요. 손실은 데이터입니다. 유일한 승리의 일기는 일기가 아니라 브로셔입니다."},{"h":"DEMO → LIVE 단계 계획","t":"실제 돈을 위험에 빠뜨리기 전에 양의 평균 R로 정해진 수의 거래에 대한 DEMO 계획을 증명한 다음 절반 크기로 시작하십시오."},{"h":"연습 체크리스트","t":"① 입사 전 작성한 계획서 ② 체크리스트 통과 ③ 일지 작성 + 감정 ④ 주간 검토 ⑤ 한 건의 유출이 수정되었습니다."}]},{"id":"leverage","title":"12 · 레버리지, 마진 및 청산","summary":"레버리지는 이익만큼 빠르게 손실을 배가시킵니다. 마진, 청산, 격리 마진과 교차 마진, 그리고 한 번의 거래로 계정이 삭제되는 것을 방지하는 안전 규칙에 대해 알아보세요.","lessons":[{"h":"레버리지란 무엇인가","t":"레버리지를 사용하면 더 적은 증거금으로 더 큰 포지션을 제어할 수 있습니다. 이익과 손실이 모두 증가하지만 우위는 증가하지 않습니다."},{"h":"마진 대 위험","t":"마진은 거래소가 잠그는 예금입니다. 위험은 진입 - 중지 × 크기입니다. 변경 마진을 활용하세요. 달러 위험은 절대 없습니다."},{"h":"청산","t":"손실이 마진을 잠식하는 경우 거래소는 강제로 포지션을 청산(청산)하는데, 이는 종종 최악의 시기에 발생합니다. 청산 가격에서 멀리 떨어진 곳에 정지하십시오."},{"h":"고립 vs 크로스","t":"격리는 손실을 해당 포지션의 마진으로 제한합니다. Cross는 전체 지갑 잔액을 사용하므로 초보자에게는 더 위험합니다. 학습하는 동안 격리를 선호합니다."},{"h":"더욱 안전한 레버리지","t":"낮은 레버리지(2~5x)와 적절한 정지는 정지하지 않는 50x보다 훨씬 안전합니다. 레버리지 수치가 아닌 정지가 귀하의 보호입니다."},{"h":"청산 거리 규칙","t":"귀하의 SL이 청산 가격 범위 내에 있는지 확인하세요. 가까이 있으면 편안한 공간이 생길 때까지 크기를 줄이세요."},{"h":"레버리지는 잘못된 항목을 수정하지 않습니다.","t":"잘못된 항목에 대한 높은 레버리지는 더 빨리 잃습니다. 먼저 설정을 수정한 다음 크기를 조정하세요."},{"h":"자금 및 수수료","t":"무기한 선물은 시간이 지남에 따라 자금을 청구합니다. 차입 범인에 대한 장기 보유로 인해 자금이 유출됩니다. 규모와 시간을 신중하게 결정해야 하는 또 다른 이유입니다."},{"h":"현물 대 선물","t":"현물은 청산될 수 없습니다(귀하가 코인을 소유하고 있습니다). 선물은 0이 될 수 있고, 0이 될 수도 있습니다. 서면 계획과 격리 마진이 있는 경우에만 선물을 사용하십시오."},{"h":"레버리지에 따른 규모 조정","t":"정지 거리에서 크기를 계산한 다음 결과 마진이 적절한지 확인합니다. 절대로 레버리지를 먼저 선택하지 마십시오."},{"h":"\"원 트레이드\" 테스트","t":"들어가기 전에 물어보십시오. 이것이 멈추면 어깨를 으쓱하는 것입니까 아니면 재앙입니까? 어깨를 으쓱하지 않으면 사이즈가 너무 크다."},{"h":"연습 체크리스트","t":"① 고립된 세트 ② 낮은 레버리지 ③ 청산 가격 내부의 SL ④ 중지부터의 크기 ⑤ 여기서 전액 손실을 면할 수 있습니까? 네 → 거래하세요."}]},{"id":"practice","title":"13 · 연습 루틴 및 백테스팅","summary":"스킬은 LIVE 이전의 DEMO를 통해 구축됩니다. 반복 가능한 연습 루프, 차트를 스크롤하여 \"백테스트\"하는 방법, 안전하게 실제 돈으로 졸업하는 방법을 알아보세요.","lessons":[{"h":"DEMO는 체육관이다","t":"종이/데모는 위험 없이 프로세스와 감정을 연습하기 위해 존재합니다. DEMO의 규칙을 따를 수 없다면 LIVE는 이를 마술처럼 고쳐주지 않습니다."},{"h":"연습 루프","t":"하나의 설정을 선택합니다(예: BB 로워 + 해머 + RSI 턴). 차트에 20개의 역사적 사례를 표시하세요. 항목/SL/TP를 정의합니다. 결과를 기록하십시오. 반복하다."},{"h":"수동 백테스팅","t":"Chart Lab에서 뒤로 스크롤하여 미래를 숨기고 각 신호를 손으로 표시하세요. 패턴 인식을 훈련하고 자신을 속이는 것을 중지합니다."},{"h":"샘플 크기","t":"10번의 거래는 아무 의미가 없습니다. 판단하기 전에 하나의 설정에 대해 30~50개의 기록된 거래를 목표로 하십시오."},{"h":"DEMO에서 순방향 테스트","t":"수동으로 마킹한 후 2~4주 동안 소프트웨어 신호를 사용하여 DEMO에서 동일한 설정을 실시간으로 실행합니다. 실제 채우기와 감정을 백테스트와 비교하세요."},{"h":"한 번에 하나의 설정","t":"한 번에 5개의 시스템을 테스트하지 마십시오. 한쪽 가장자리를 마스터한 다음 두 번째 가장자리를 추가하세요."},{"h":"루틴을 작게 유지하세요","t":"20분짜리 일일 루틴(스캔, 마크, 저널, 검토)이 6시간 동안 무작위로 차트를 쳐다보는 것보다 좋습니다."},{"h":"라이브로 졸업","t":"기준: 30개 이상의 DEMO 거래에 대한 양의 평균 R, 규칙 준수, 복수 에피소드 없음. 그런 다음 절반 크기로 LIVE를 시작하고 천천히 확장하세요."},{"h":"확장 규칙","t":"정해진 기간 동안 수익성이 있고 훈련된 주 후에만 규모를 늘리십시오. 단 한 번의 큰 승리 이후에는 절대로 규모를 늘리십시오."},{"h":"물러서야 할 때","t":"일일 또는 주간 손실 한도에 도달하거나 반복되는 규칙 위반을 확인하고 계속하기 전에 DEMO로 돌아가 규율을 다시 구축하세요."},{"h":"프로세스 지표 추적","t":"로그 체크리스트 합격률, 주당 규칙 위반 및 평균 R. 이는 단일 P/L 수치보다 성장을 더 잘 예측합니다."},{"h":"CPE 실습 경로","t":"학습 수업 → 차트 랩(마크 설정) → 페이퍼 트레이드 → 저널 검토 → DEMO의 시그널 데스크 → 매칭 플랫폼 키의 소규모 라이브."},{"h":"연습 체크리스트","t":"① 하나의 설정 선택 ② 표시된 30개 예시 ③ DEMO 포워드 테스트 ④ 저널 + 리뷰 ⑤ 포지티브 R → 하프 사이즈 LIVE."}]},{"id":"volatility","title":"14 · 변동성과 마틴게일","summary":"시장 변동성을 읽는 방법(가격이 변하는 이유), 이것이 이유 라인으로 모든 신호에 추가되는 방법, 옵션 Martingale 사다리가 작동하는 방법 및 부주의하게 사용할 때 계정을 잃는 가장 빠른 방법인 이유를 알아보세요.","lessons":[{"h":"변동성의 의미","t":"변동성은 가격이 어느 방향으로 움직이는지가 아니라 얼마나 많은 가격이 움직이는지를 나타냅니다. 높은 변동성 = 넓은 양초와 빠른 변동. 낮은 변동성 = 조용하고 좁은 범위. 동일한 설정이라도 각각의 신뢰성은 매우 다릅니다."},{"h":"CPE 변동성 판독값","t":"이제 각 신호는 평균 캔들 범위와 볼린저 밴드 폭을 측정한 다음 이를 해당 쌍의 최근 표준과 비교합니다. LOW / NORMAL / HIGH / EXTREME과 함께 일반 언어로 된 이유 라인, 즉 시장 변화의 \"이유\"가 신호와 함께 표시됩니다."},{"h":"극심한 변동성 = 다운그레이드","t":"테이프가 EXTREME 상태이면 새로운 STRONG 신호가 CAUTION으로 다운그레이드됩니다(이유가 표시됨). 채찍톱 시장에서는 동일한 패턴이 훨씬 더 자주 실패합니다. 가짜 브레이크와 정지 사냥 심지가 일반적입니다."},{"h":"HIGH/EXTREME에서 해야 할 일","t":"더 작은 크기. 더 넓은 정지. 거래 횟수가 적습니다. 캔들 중간 스파이크 대신 완성된 캔들을 기다립니다. 판독값이 EXTREME이라고 표시되면 설정을 입구가 아닌 연구 구역으로 취급하십시오."},{"h":"마틴게일이 무엇인가요?","t":"Martingale은 평균 진입을 낮추기 위해 손실 포지션을 추가합니다. 각각의 불리한 움직임 후에는 일반적으로 더 큰(1x, 2x, 4x…) 다른 주문을 추가합니다. 자주 승리하다가 한 번의 나쁜 실행으로 모든 것을 잃습니다."},{"h":"CPE 마틴게일 규칙","t":"CPE는 두 가지 모두가 참인 경우에만 추가 주문을 추가합니다. (1) 가격이 최소 단계 × 렁 %만큼 거래 반대 방향으로 움직였고 (2) 새로운 동일 측 신호가 여전히 해당 쌍을 나타냅니다. 가격이 하락했다고 해서 결코 추가되지 않습니다."},{"h":"네 개의 숫자","t":"단계 % = 각 추가 전에 역방향 이동이 필요합니다. 승수 = 각 추가의 크기 대 기본(1 = 플랫, 2 = 더블). 최대 추가 = 추가 주문에 대한 엄격한 제한. 사다리 위험 한도 % = 전체 사다리의 위험을 자기자본의 %로 나타낸 것입니다. 네 가지 모두 선택 가능합니다."},{"h":"하드캡이 당신을 보호합니다","t":"큰 승수와 많은 추가에도 불구하고 사다리의 총 위험이 자본의 한도 %를 초과하면 CPE는 주문을 거부합니다. 또한 교환 최소 규모와 일일 -2% 정지를 준수합니다."},{"h":"실행되는 곳","t":"해당 거래를 관리하려면 수동을 선택하고, 자동 거래를 관리하려면 자동 세션을 선택하세요. 데모와 라이브 모두. 수동에서는 새로운 동일한 쪽 신호를 읽을 수 있도록 쌍이 검색 목록에 있어야 합니다."},{"h":"캡이 중요한 이유(예)","t":"1% 위험 기준에 1% 단계, 승수 2, 3을 더하면 위험은 1% → 2% → 4% → 8%가 됩니다. 마지막 단계에서 한 번의 완전한 중지로 인해 많은 승자가 삭제됩니다. 이것이 바로 상한선이 존재하고 기본 숫자가 작은 이유입니다."},{"h":"마틴게일 반대 대안","t":"많은 전문가들은 그 반대의 행동을 합니다. 승자에게만 추가하고 패자를 빠르게 잘라내는 것입니다. 기분이 더 나쁘게 느껴지지만(손실이 더 적음) 단일 추세로 계정을 날려버릴 수는 없습니다."},{"h":"위험은 제거되지 않습니다","t":"평균을 낮추는 것은 위험을 제거하지 않습니다. 위험을 \"많은 작은 손실\"에서 \"하나의 큰 손실\"로 이동시킵니다. 결코 잃을 수 없는 돈을 추가하지 말고, 손실이 발생한 거래를 “복구”하기 위해 한도를 끄지 마십시오."},{"h":"실습 경로","t":"먼저 DEMO에서 변동성 판독값을 알아보세요. 30개 이상의 거래를 위해 DEMO에서 최대 추가 1-2와 작은 승수로 Martingale을 사용해 보세요. 모든 사다리를 기록하고 결정하십시오. 대부분의 거래자는 플랫/마틴게일 방지 방법이 더 안전하다고 생각합니다."},{"h":"변동성 + 마틴게일 체크리스트","t":"① 변동성 수준을 먼저 읽습니다. ② 극한으로 건너뛰거나 축소합니다. ③ 마틴게일은 새로운 동일한 쪽 신호에서만 ④ 단계 × 렁에 도달했습니다. ⑤ 위험 한도 미만 → 추가합니다. \"아니요\" → 추가하지 않음."}]},{"id":"lab_indicators","title":"15 · 차트 랩 지표(Stoch · ADX · Ichimoku · VWAP)","summary":"Chart Lab에는 이제 전체 표시 막대가 있습니다. 모든 버튼은 차트를 즉시 다시 그리는 켜기/끄기 틱입니다. BB / RSI / MACD / EMA / SMA50 / 볼륨 외에도 이제 Stochastic, ADX/DMI, Ichimoku 및 VWAP가 제공되며 신호 엔진은 차트뿐만 아니라 이를 읽습니다.","lessons":[{"h":"바가 있는 곳","t":"Chart Lab → 차트 아래 버튼의 \"지표\" 행. 한 번 클릭하면 표시기가 켜지고, 다음 번 클릭하면 꺼집니다. 차트가 즉시 다시 그려집니다. 진드기는 시각적이며 신호 엔진에 공급됩니다."},{"h":"확률론적 (14,3,3)","t":"양초 아래에 그려진 %K / %D 오실레이터, 스케일 0-100. ~80 이상 = 과매수 구간, ~20 이하 = 과매도 구간. 과매도 구간에서 %K가 %D를 통과하는 것은 강세 연구입니다. 상단의 십자가는 약세입니다. 강한 추세에서는 오랫동안 한쪽 끝에 고정되어 있을 수 있습니다. 항상 BB 및 캔들과 결합하세요."},{"h":"ADX/DMI (14)","t":"ADX는 방향이 아닌 추세 강도를 측정합니다. ~25 이상 = 실제 추세가 진행 중입니다. ~20 미만 = 고르지 못한 범위. +DI 초과 −DI = 담당 구매자; −DI +DI 이상 = 담당 판매자. ADX를 사용하여 추세 거래를 할 것인지, 아니면 그대로 유지할 것인지 결정하십시오."},{"h":"이치모쿠 클라우드(9,26,52)","t":"Tenkan(빠른 줄), Kijun(느린 줄) 및 Senkou 클라우드. 상승 구름 위의 가격 = 강세 배경; 떨어지는 구름 아래 = 약세. 구름 내부의 Tenkan/Kijun 교차는 약합니다. 가격이 구름을 벗어나는 십자가가 더 강합니다. 클라우드 엣지 자체가 지지/저항 역할을 하는 경우가 많습니다."},{"h":"VWAP","t":"거래량 가중 평균 가격 — 거래량에 따라 가중된 평균 가격으로 각 세션을 재설정합니다. 큰 기관들은 이를 벤치마킹합니다. 상승하는 VWAP 이상의 가격 = 구매자가 통제합니다. 하락세 동안 VWAP의 완전한 거부는 짧은 연구입니다. 연중무휴 암호화폐에서는 FX와 다르게 재설정됩니다. 이를 법률이 아닌 지침으로 취급합니다."},{"h":"엔진이 이를 사용하는 방법","t":"각각의 새로운 지표는 그것이 가리키는 것과 같은 쪽의 점수에 작은 확인을 추가합니다(방향에 동의할 경우 Stochastic, Ichimoku, VWAP, ADX 및 Elliott). 이는 촉발 요인이 아니라 확인입니다. BB/RSI/양초에 동의하지 않으면 점수가 더욱 혼합되고 더 많은 HOLD를 얻게 됩니다."},{"h":"CAUTION이 더욱 엄격해진 이유","t":"이제 풀에 더 많은 검사가 있으므로 주의 막대가 강화되었습니다. 점수 ≥ 4와 최소 3개의 동의 검사가 필요합니다. 이렇게 하면 더 많은 도구가 켜져 있기 때문에 앱에서 약한 신호가 넘쳐나는 것을 방지할 수 있습니다."},{"h":"효과적인 읽기 순서","t":"① 더 높은 TF 방향(Ichimoku cloud + ADX). ② 가격은 (BB / Fib / VWAP)입니다. ③ 모멘텀(RSI + 확률론적). ④ 캔들 확인. ⑤ 위험도(%) 및 수준 기재 → 종이 우선."},{"h":"피해야 할 실수","t":"모든 표시기를 켜고 무지개를 바라보세요. ADX를 방향으로 사용(단지 강도임) 강세장에서 스토캐스틱이 >80이기 때문에 매도하는 경우; VWAP가 암호화폐와 FX에서 서로 다른 의미를 갖는다는 점을 무시하는 것입니다."},{"h":"연습 체크리스트","t":"① 클라우드 + ADX의 바이어스 ② BB / Fib / VWAP의 위치 ③ RSI + Stoch의 모멘텀 ④ 캔들 확인 ⑤ SL / TP 작성 ⑥ 종이, 그 다음 저널."}]},{"id":"elliott","title":"16·엘리엇 웨이브(라이트 카운트)","summary":"CPE에는 경량 Elliott Wave 카운터가 포함되어 있습니다. Chart Lab 표시 막대에서 \"Elliott\"를 선택하면 양초의 마지막 0-1-2-3-4-5 임펄스에 레이블이 지정되고 웨이브 5 피보나치 목표가 투사됩니다. 그것은 수정구슬이 아닌 학습 도구입니다.","lessons":[{"h":"한 줄에 담긴 아이디어","t":"시장은 충동(추세 방향의 5개 다리)과 조정(추세 방향의 3개 다리)이라는 파동으로 움직입니다. CPE는 추세를 전달하는 부분인 충동만을 계산합니다."},{"h":"CPE가 이를 계산하는 방법","t":"마지막 스윙 피벗(3바 프랙탈)을 찾고, 높음/낮음을 번갈아 가며 엘리엇 규칙에 따라 마지막 5~6회 스윙을 테스트합니다. 모양이 맞으면 0→5 라벨(아직 진행 중인 노란색의 파동)과 파동 4에서 측정된 파동 1 길이 × 1.618로 구성된 W5 목표선을 그립니다."},{"h":"확인하는 규칙","t":"2파동은 1파동의 시작을 통과하지 않습니다. 4번 파동은 1번 파동의 영역과 겹치지 않습니다. 웨이브 3은 1/3/5 중 가장 짧지 않습니다. 규칙이 실패하면 아무것도 표시되지 않습니다. 즉, 강제 카운트가 없습니다."},{"h":"강세 대 약세","t":"0-1-2-3-4-5 상승은 강세 충동입니다. 내려가는 거울 이미지는 약세입니다. 엔진은 파도 측면의 점수에 작은 확인을 추가합니다."},{"h":"라이브 vs 완료","t":"LIVE 웨이브 5(아직 실행 중)는 추세 지속으로 읽힙니다. 완전한 자극(0~5 완료)은 추세가 지칠 수 있음을 경고하며 종종 수정이 뒤따릅니다."},{"h":"W5 목표선","t":"파동 4의 저점/고점에서 파동 1의 피보나치 확장입니다. 이는 자석이 아닌 목표 아이디어입니다. 가격이 이에 미치지 못하거나 초과할 수 있습니다."},{"h":"사용방법","t":"카운트를 합류로 간주합니다. 양초와 RSI가 있는 명확한 BB/Fib 영역에서 충동적인 카운트는 확신을 더합니다. 그 자체로는 단지 스케치일 뿐입니다."},{"h":"피해야 할 실수","t":"귀하의 입장에 맞을 때까지 파도를 다시 세어보세요(고전적인 엘리엇의 죄). 작은 흔들림을 세는 것; 더 높은 기간 수를 무시합니다. 새 막대가 인쇄될 때마다 카운트가 변경되는 것을 잊어버립니다."},{"h":"연습 체크리스트","t":"① 명확한 스윙 선택 ② 규칙 통과 ③ 지그재그가 BB/Fib에 동의함 ④ 캔들 확인 ⑤ 웨이브-4 무효 지점을 넘어선 SL."}]},{"id":"forecast","title":"17 · 3개월 예측(예측 3M 틱)","summary":"장거리 프로젝터: 신호 자체의 추세, 목표 및 변동성을 기반으로 구축된 이 차트가 향후 3개월 동안 어떻게 형성될지 보여줍니다. Chart Lab의 \"Forecast 3M\" 체크를 사용하여 켜거나 끌 수 있습니다.","lessons":[{"h":"그것이 그리는 것","t":"분석된 항목에서 엔진이 이미 알고 있는 최고의 목표(Elliott 목표 → tp2 → tp1)를 향해 이어지는 점선 중앙 경로는 그럴듯한 가격의 확산을 보여주는 확대된 \"원뿔\"로 둘러싸여 있습니다. 월 표시 M+1 / M+2 / M+3은 수평선을 나눕니다."},{"h":"왜 선이 아니고 원뿔인가?","t":"누구도 정확한 미래 가격을 알 수 없습니다. 원뿔은 시간의 제곱근과 쌍 자체의 변동성에 따라 넓어지므로 조용한 FX 쌍은 좁은 원뿔을 얻고 야생 알트코인은 매우 넓은 원뿔을 얻습니다. 그 너비가 메시지입니다. 더 멀리 볼수록 가격이 확실하지 않습니다."},{"h":"숫자의 출처","t":"드리프트는 현재 신호 대상에서 발생합니다. 일일 변동성은 하루 단위로 조정된 신호의 ATR%에서 나오므로 원뿔은 5m 또는 1d 차트에서 동일한 의미를 갖습니다. EXTREME/HIGH 변동성은 변동성을 더욱 확대합니다."},{"h":"읽는 방법","t":"SLOPE(경로가 어느 방향으로 기울어지는지)와 WIDTH(얼마나 의심스러운지)를 살펴보세요. 좁은 원뿔형 상승 경로 = 안정적인 추세 아이디어; 거대한 원뿔이 있는 평평한 경로 = \"여기에는 가장자리가 없습니다. 소음이 예상됩니다.\""},{"h":"켜고 끄기","t":"\"Forecast 3M\" 버튼은 \"미래 공간\" 옆에 있습니다. Future 공간이 켜져 있어야 합니다(투영이 그려지는 오른쪽의 빈 영역). 신호가 HOLD이면 방향이 없으므로 아무것도 그려지지 않습니다."},{"h":"매매가 아니라 추세다","t":"예측은 큰 그림의 지도입니다. 실제 거래 수준(진입, TP1/TP2, SL 및 단기 예측)은 여전히 ​​귀하가 거래하는 것입니다."},{"h":"정직한 한계","t":"뉴스, 상장, 상장 폐지 및 거시적 변화는 모델에 포함되지 않습니다. 그 경로는 순조롭게 진행되므로 실제 가격은 훨씬 더 많이 흔들릴 것입니다. 3개월 콘은 학습 보조 수단이지 결코 약속이 아닙니다."},{"h":"자주 재분석하라","t":"새로운 양초가 인쇄되면 목표, 변동성 및 전체 원뿔이 업데이트됩니다. 예측은 계약이 아니라 스냅샷입니다."},{"h":"연습 체크리스트","t":"① 경로 방향을 읽습니다. ② 원뿔 너비를 확인합니다. ③ 더 높은 TF 구조와 비교합니다. ④ 원뿔이 아닌 실제 SL에서 위치 크기를 조정합니다."}]}],"platforms":{"BINANCE":{"title":"바이낸스 트레이딩 A → Z","steps":["계정 생성 → 2FA를 활성화합니다.","API 관리 → 키 생성 → 현물 및/또는 선물 거래 ON, 출금 OFF.","CPE → API 키 → 바이낸스 → 저장 → 테스트 계정에 키 + 비밀을 붙여넣습니다.","Spot Desk / Futures Desk 스캔을 사용하십시오(공개 차트는 키 이전에도 작동함).","연습: 수동 거래 → 종이 거래 시작(라이브 머니 없음)","실시간: TP1/TP2/SL + 후행 설정 → 실시간 거래 시작(API 필요)","직위 관리: 수준 편집, 부분 마감, 자동 취소.","라이센스: 평가판 7d → 3개월 또는 평생(앱 내 소유자 가격)."]},"BYBIT":{"title":"바이비트 트레이딩 A → Z","steps":["계정 + 2FA.","API 관리 → 거래만 가능, 출금은 OFF됩니다.","CPE → API Keys → Bybit → 저장.","범인의 사고방식을 위한 Futures Desk; 양초를 연구하는 차트랩.","종이 거래가 먼저입니다. 열쇠 작업 후 생활하세요.","트레일 TP+SL: 매수↑ / 매도↓."]},"OKX":{"title":"OKX 트레이딩 A → Z","steps":["API Key + Secret + Passphrase가 필요합니다.","출금은 항상 OFF입니다.","CPE 키에 세 필드를 모두 저장합니다.","종이 연습 → 작은 라이브 크기.","암호 오타는 가장 큰 실패입니다. 주의해서 복사하세요."]},"KUCOIN":{"title":"KuCoin 트레이딩 A → Z","steps":["키 + 비밀 + 암호.","무역허가만 가능합니다.","CPE의 종이 → 그런 다음 작게 살아보세요.","신호를 위해서는 현물/선물 데스크를 사용하세요."]},"BITGET":{"title":"비트겟트레이딩 A → Z","steps":["거래 전용 API입니다.","그러면 종이가 살아납니다.","선물: 수동 거래에서 교차 또는 격리를 선택하세요.","TP+SL을 추적하여 이익을 고정합니다."]},"GATE":{"title":"Gate.io 트레이딩 A → Z","steps":["API v4 키를 생성합니다(거래).","출금 OFF.","CPE에 저장 → 연습용지.","라이브 전 항목을 스캔 + 차트 랩으로 확인하세요."]},"MEXC":{"title":"MEXC 트레이딩 A → Z","steps":["스팟 사고방식을 시작하세요.","CPE API 키의 키입니다.","종이 → 라이브.","트레일을 사용하여 미결제 이익을 고정하세요."]},"KRAKEN":{"title":"크라켄 트레이딩 A → Z","steps":["거래 허가로만 키를 생성합니다.","인출/자금 권리가 없습니다.","CPE의 종이 실습.","Kraken의 모든 실시간 주문도 확인하세요."]},"COINBASE":{"title":"코인베이스 고급 A → Z","steps":["고급 거래 API 키.","CPE의 스팟 중심 데스크.","그러면 종이가 살아납니다.","인출을 꺼두세요."]},"FOREX_OANDA":{"title":"외환(OANDA) A → Z","steps":["OANDA 데모 공개 → 위험 ~1%.","개인 액세스 토큰 + CPE 키의 계정 ID.","외환 데스크 스캔 + 차트 랩(EURUSD…).","수동 거래 → 외환 플랫폼을 사용한 종이.","데모 자신감 이후에만 생활하십시오."]},"FOREX_FXCM":{"title":"FXCM 외환 A → Z","steps":["브로커 API 자격 증명.","먼저 CPE로 종이를 작성하세요.","런던/뉴욕 세션 및 뉴스 급증을 시청하세요.","연습 후 라이브 일기가 깨끗해 보입니다."]},"FOREX_MT5":{"title":"MetaTrader 5 A → Z","steps":["CPE 키의 로그인 + 서버 + 비밀번호.","가능하다면 투자자(읽기) 비밀번호를 선호하세요.","연습장 0.01.","CPE의 종이; 준비되면 브로커를 통해 실시간으로 진행하세요."]},"FOREX_DEMO":{"title":"외환 데모 환율 A → Z","steps":["API 키가 필요하지 않습니다.","무료 차트를 위한 Forex Desk + Chart Lab.","종이 거래만 가능합니다(연습).","실제 브로커를 사용할 준비가 되면 라이브용 OANDA / FXCM / MT5 키를 추가하세요."]}},"forexAz":{"title":"외환 트레이딩 A → Z (풀 클래스)","lessons":[{"h":"A — 계정 및 위험","t":"먼저 데모를 해보세요. 위험은 아이디어당 ~0.5~1%입니다. 보복거래는 절대 하지 마세요."},{"h":"B — 쌍","t":"엑조틱 이전의 메이저(EURUSD, GBPUSD, USDJPY)."},{"h":"C — 양초","t":"Chart Lab Forex에서 Doji, Hammer, Engulfing에 대해 알아보세요."},{"h":"D — 일일 편향","t":"15m/30m 항목 이전에 더 높은 기간을 확인하세요."},{"h":"E — 항목","t":"BB 하단 바운스 + 캔들 확인은 일반적인 연습 설정입니다."},{"h":"F — 섬유","t":"50% / 61.8% 풀백은 연습존으로 자주 사용됩니다."},{"h":"G — 목표 (TP)","t":"TP1 스케일 아웃, TP2 러너, 트레일 SL."},{"h":"H — 시간","t":"런던-뉴욕 중첩 = 더 많은 움직임."},{"h":"I — 지표","t":"RSI + MACD + BB를 함께 사용합니다. 표시기 과부하를 피하십시오."},{"h":"J — 저널","t":"CPE Journal에 모든 논문/실시간 거래를 기록하세요."},{"h":"K - 키","t":"라이브 외환 브로커에는 API/토큰이 필요합니다. 데모 요금은 필요하지 않습니다."},{"h":"L — 많이","t":"0.01랏을 실천하는 마음가짐으로 시작해보세요."},{"h":"M — 사고방식","t":"예측보다는 과정. 나쁜 날은 건너 뛰세요."},{"h":"N — 뉴스","t":"대규모 이벤트 전에 뉴스와 요령을 확인하세요."},{"h":"O — 주문","t":"항상 SL을 설정하세요. 후행은 미결제 이익을 보호합니다."},{"h":"P — 연습","t":"Paper Trade 버튼 = 라이브 API 없이 연습."},{"h":"Q — 품질","t":"적은 수의 고품질 설정이 과잉 거래를 능가합니다."},{"h":"R — 위험:보상","t":"가능하다면 보상 ≥ 위험을 목표로 설정하세요."},{"h":"S — 세션","t":"아시아는 더 조용합니다. 런던/뉴욕이 더 활발해졌습니다."},{"h":"T — 추세","t":"학습할 때 더 높은 TF 추세로 거래하세요."},{"h":"U — 업데이트","t":"CPE 업데이트 배너 + 실시간 도움말을 시청하세요."},{"h":"V — 변동성","t":"ATR이 급등할 때 인내심을 넓혀보세요."},{"h":"W — API 출금","t":"API 키에 대해 철회를 활성화하지 마십시오."},{"h":"X — 종료","t":"부분 TP + 트레일이 희망을 능가합니다."},{"h":"Y — 귀하의 계획","t":"규칙을 작성하세요. 수동/자동으로 따라하세요."},{"h":"Z — 제로 러시","t":"FOMO가 없습니다. 연습 → 라이브 API."}]}};

window.CPE_LEARN.th = {"intro":"ฝึกฝนด้วยกระดาษ / DEMO ก่อน ศึกษากราฟแท่งเทียน แผนภูมิ BB/RSI/Fib เงิน จิตวิทยา — แล้วตามด้วยสัญญาณ (ซื้อ/ขาย/ถือ หมายถึงอะไร + จะทำอย่างไร) และสัญญาณฟอเร็กซ์ Live ต้องการคีย์ API ของแพลตฟอร์มที่ถูกต้อง (ปิดการถอนเงิน)","candles":[{"shape":"doji","name":"โดจิ","color":"#94a3b8","bias":"เป็นกลาง/รอ","tip":"เปิด µ ปิด — กากบาทหรือตัวบาง การตัดสินใจตลาดหลังการย้าย","also":"สอนด้วย: อย่า FOMO รอเทียนต่อไป ใกล้ BB extreme + Doji = บีบคั้นความคิดเห็น; ตรวจสอบความชัน RSI ก่อนคาดเดาทิศทาง"},{"shape":"hammer","name":"ค้อน","color":"#22c55e","bias":"ซื้ออคติ","tip":"แท่งเทียนด้านบนเล็ก ไส้เทียนด้านล่างยาว (ประมาณ 2× แท่งเทียน) หลังจากที่ราคาลดลง — ผู้ซื้อปฏิเสธราคาที่ต่ำกว่า","also":"นอกจากนี้: วางการฝึก SL ไว้ใต้ไส้ตะเกียงต่ำ ดีที่สุดด้วย BB + RSI ที่ต่ำกว่า เพิ่มขึ้นจากการขายมากเกินไป จิตวิทยา: ความอดทนเพื่อให้ไส้ตะเกียงหมด — อย่าซื้อไส้ตะเกียงตรงกลาง"},{"shape":"invhammer","name":"ค้อนคว่ำ","color":"#22c55e","bias":"ซื้อ (อ่อนแอ)","tip":"ไส้ตะเกียงยาวบนที่ด้านล่าง ผู้ซื้อสำรวจสูงแต่ปิดใกล้เปิด — ต้องการการยืนยันสีเขียวถัดไป","also":"นอกจากนี้: อ่อนแอกว่าค้อนเพียงอย่างเดียว ใช้เป็นการแจ้งเตือนไม่ใช่การเข้า Fib 61.8 เด้ง + Inverted Hammer = โซนศึกษาเท่านั้นจนกว่าจะยืนยันแท่งเทียน"},{"shape":"shooting","name":"ดาวตก","color":"#ef4444","bias":"ขายอคติ","tip":"ก้นแท่งเล็ก ไส้เทียนด้านบนยาวหลังจากเพิ่มขึ้น — ผู้ขายปฏิเสธจุดสูง","also":"นอกจากนี้: SL เหนือไส้ตะเกียงสูง แข็งแกร่งกว่าส่วนขยาย BB / Fib ตอนบน / RSI ที่ซื้อมากเกินไป สอน: เทียนพระจันทร์อาจล้มเหลวได้ — อย่าไล่ตามกรีนสุดท้าย"},{"shape":"hanging","name":"คนแขวนคอ","color":"#f59e0b","bias":"ขายอย่างระมัดระวัง","tip":"ดูเหมือน Hammer แต่จะปรากฏขึ้นหลังจากเพิ่มขึ้น — เป็นไปได้ว่ามีความเหนื่อยล้าสูงสุด","also":"นอกจากนี้: บริบทคือทุกสิ่ง (รูปร่างเดียวกัน ≠ การค้าเดียวกัน) ตำแหน่งบันทึกประจำวัน: บนและล่าง จิตวิทยา: อย่ากลับตัวเพียงเพราะรูปร่างตรงกัน — ยืนยันด้วยแท่งเทียนถัดไป + RSI"},{"shape":"engulf_bull","name":"รั้นกลืน","color":"#22c55e","bias":"ซื้อ","tip":"แท่งสีเขียวคลุมแท่งสีแดงก่อนหน้าทั้งหมด — ผู้ซื้อเข้าควบคุมในแท่งเดียว","also":"นอกจากนี้: แข็งแกร่งขึ้นที่แนวรับ / ลด BB / Fib 50–61.8 ขนาดตั้งแต่กลืนต่ำถึง SL เคล็ดลับเงิน: ลำตัวกว้าง → SL กว้าง → ขนาดเล็กกว่า"},{"shape":"engulf_bear","name":"หยาบคายกลืน","color":"#ef4444","bias":"ขาย","tip":"ตัวสีแดงครอบคลุมสีเขียวก่อนหน้าทั้งหมด — ผู้ขายครอบงำ","also":"นอกจากนี้: ข้อควรระวังในการเปิด longs ใกล้ BB ระดับบน + RSI>70 = คุณภาพการศึกษาสูง สอนความเสี่ยง: หากยาวอยู่แล้ว ให้ TP / เทรลบางส่วนแทนความหวัง"},{"shape":"morning","name":"ดาวรุ่ง","color":"#22c55e","bias":"ซื้อ","tip":"เทียน 3 เล่ม: สีแดงใหญ่ → ดาวเล็ก → สีเขียวใหญ่ เรื่องราวการกลับตัวด้านล่าง","also":"นอกจากนี้: ความอดทนหลายเทียน เข้าหลังจากปิดครั้งที่ 3; SL ใต้ดาวต่ำ ผสมผสานกันได้ดีกับ BB ที่ต่ำกว่า + RSI ที่เป็นขาขึ้น"},{"shape":"evening","name":"ค่ำดาว","color":"#ef4444","bias":"ขาย","tip":"เทียน 3 เล่ม: สีเขียวใหญ่ → ดาวเล็ก → สีแดงใหญ่ เรื่องราวการพลิกกลับยอดนิยม","also":"นอกจากนี้: อย่าทำให้ดาวกลางสั้นเพียงลำพัง รออันที่ 3 ปิดครับ จุดบรรจบกันของส่วนขยาย BB / Fib ตอนบน จิตวิทยา: มองข้าม FOMO ของกรีนรันครั้งแรก"},{"shape":"maru_bull","name":"บูล มารุโบสึ","color":"#22c55e","bias":"แรงกดดันให้ซื้อแข็งแกร่ง","tip":"แท่งสีเขียวยาว แทบไม่มีไส้ — ผู้ซื้อควบคุมการเปิด→ปิด","also":"นอกจากนี้: เบาะแสความต่อเนื่องของแนวโน้ม ไม่ใช่การซื้อที่ต่ำเสมอไป เดินแบบเดอะแบนด์ก็ได้ ความเสี่ยง: ไล่ Marubozu สายโดยไม่ดึง BB กลาง / Fib"},{"shape":"maru_bear","name":"แบร์ มารุโบสึ","color":"#ef4444","bias":"แรงกดดันขายที่แข็งแกร่ง","tip":"แท่งยาวสีแดง แทบไม่มีไส้ — ผู้ขายควบคุมได้","also":"นอกจากนี้: อย่าจับมีดที่ตกลงมา รอ BB/Fib เด้ง + Hammer ในภายหลัง สอน: ความกดดันสูง = ขนาดที่เล็กลงหรือยืนหยัด"},{"shape":"spin","name":"ลูกข่าง","color":"#94a3b8","bias":"ความไม่แน่ใจ","tip":"ตัวเล็กๆ ไส้เทียนบน+ล่าง — ทั้งสองฝ่ายสู้กันไม่มีใครชนะชัดเจน","also":"นอกจากนี้: ข้างในบีบีบีบบ่อยๆ หยุดการซื้อขายชั่วคราว รอพัก + เทียนทิศทาง บทเรียนจิตวิทยา: ตลาดไม่สามารถ “ทำอะไรได้เลย” — การพักตัวเป็นทางเลือกที่ถูกต้อง"},{"shape":"pierce","name":"สายเจาะ","color":"#22c55e","bias":"ซื้อ","tip":"สีแดงแล้วสีเขียวที่เปิดต่ำกว่าแต่ปิดเหนือจุดกึ่งกลางของสีแดงก่อนหน้า","also":"นอกจากนี้: นุ่มนวลกว่าการกลืน ยืนยันด้วยการเลี้ยว RSI การเจาะกระดาษที่ดีเพื่อการอ่านค่าความแรงบางส่วน — กรีนทั้งหมดไม่เท่ากัน"},{"shape":"darkcloud","name":"เมฆดำปกคลุม","color":"#ef4444","bias":"ขาย","tip":"สีเขียวต่อจากสีแดงที่เปิดสูงขึ้นแต่ปิดต่ำกว่าจุดกึ่งกลางของสีเขียวก่อนหน้า","also":"นอกจากนี้: เตือนภัยล่วงหน้าก่อนหมีกลืนเต็ม เส้นทางยาว / ใช้ TP1 สอนการปรับขนาดก่อนที่จะพิมพ์การกลับรายการแบบเต็ม"},{"shape":"soldiers","name":"ทหารขาวสามคน","color":"#22c55e","bias":"แนวโน้มการซื้อ","tip":"กรีนที่กำลังขึ้นสามอันพร้อมราคาปิดที่สูงกว่า — การเข้าซื้ออย่างต่อเนื่อง","also":"นอกจากนี้: สัญญาณแนวโน้มขาขึ้นที่แข็งแกร่ง; การดึงกลับเป็น Fib 38–50 หรือ BB mid เป็นการฝึกฝนเพิ่มเติม ความเสี่ยงที่มั่นใจมากเกินไปหลังจาก 3 กรีน – คง % ความเสี่ยงไว้คงที่"},{"shape":"crows","name":"อีกาดำสามตัว","color":"#ef4444","bias":"ขายแนวโน้ม","tip":"สีแดงที่ตกลงมาสามจุดโดยมีการปิดที่ต่ำกว่า — ขายอย่างต่อเนื่อง","also":"นอกจากนี้: อย่าเฉลี่ยลง รอโครงสร้าง. RSI ขายมากเกินไปสามารถคงขายมากเกินไปได้ — กฎเงิน: ขีดจำกัดการสูญเสีย > ความหวัง"},{"shape":"harami_bull","name":"ฮารามิรั้น","color":"#22c55e","bias":"ซื้อ (อ่อน)","tip":"สีแดงใหญ่ แล้วก็สีเขียวเล็กด้านในตัวก่อนหน้า — ขายแรงดันที่หดตัว","also":"นอกจากนี้: สัญญาณหยุดชั่วคราวก่อนกำหนด จำเป็นต้องยืนยัน จับคู่กับการศึกษาความแตกต่างรั้นของ RSI สอนการอ่าน \"ความเข้มแข็งที่จางหาย\" ไม่ใช่แค่การกลับตัวเท่านั้น"},{"shape":"harami_bear","name":"ฮารามิหยาบคาย","color":"#ef4444","bias":"ขาย (อ่อน)","tip":"สีเขียวใหญ่ ตามด้วยสีแดงเล็กด้านใน — แรงซื้อลดลง","also":"นอกจากนี้: ใช้เวลาบางส่วนในการลอง ไม่สั้นอัตโนมัติ จิตวิทยา: ความโลภหลังจากสีเขียวขนาดใหญ่มักจะเพิกเฉยต่อคำเตือนของฮารามิ"},{"shape":"tweezer_bot","name":"ปากคีบด้านล่าง","color":"#22c55e","bias":"ซื้อ","tip":"แท่งเทียนสองแท่งที่มีจุดต่ำสุดที่ตรงกัน — การทดสอบแนวรับสองครั้ง","also":"นอกจากนี้: ทำเครื่องหมายว่าต่ำเป็นโครงสร้าง SL อยู่ด้านล่าง การจัดตำแหน่ง Fib/BB ช่วยได้ รูปแบบแผนภูมิลูกพี่ลูกน้องของ Double Bottom — บทเรียนสนับสนุนเดียวกัน"},{"shape":"tweezer_top","name":"แหนบด้านบน","color":"#ef4444","bias":"ขาย","tip":"แท่งเทียนสองแท่งที่มีจุดสูงสุดที่ตรงกัน — การทดสอบแนวต้านสองครั้ง","also":"นอกจากนี้: ทำเครื่องหมายความต้านทาน ลูกพี่ลูกน้องของดับเบิ้ลท็อป ความล้มเหลวของ RSI ที่จุดสูงสุด = การบรรจบกัน สอน: ราคาเดียวกันถูกปฏิเสธสองครั้ง = เคารพระดับ"},{"shape":"longlegged","name":"โดจิขายาว","color":"#94a3b8","bias":"ความไม่แน่ใจ","tip":"ไส้เทียนบนและล่างที่ยาวมากและมีลำตัวเล็ก — การต่อสู้สองทางที่รุนแรงซึ่งจบลงที่จุดเริ่มต้น","also":"นอกจากนี้: การเคลื่อนไหวครั้งใหญ่มักจะตามมา แต่ไม่ทราบทิศทาง ให้รอจนแท่งเทียนทะลุ สอนว่าความผันผวนสูงไม่ใช่ความแน่นอนสูง"},{"shape":"dragonfly","name":"แมลงปอโดจิ","color":"#22c55e","bias":"ซื้ออคติ","tip":"เปิด = ปิด = สูง โดยมีไส้เทียนล่างยาว — ผู้ขายผลักลงและผู้ซื้อก็กระแทกกลับขึ้นไปตรงๆ","also":"นอกจากนี้: แข็งแกร่งที่สุดในแนวรับ / ลด BB หลังจากลดลง SL ใต้หางไส้ตะเกียง สอน: การปฏิเสธเป็นเพียงเรื่องราว ไม่ใช่การรับประกัน — ยืนยันเทียนเล่มถัดไป"},{"shape":"gravestone","name":"หลุมศพโดจิ","color":"#ef4444","bias":"ขายอคติ","tip":"เปิด = ปิด = ต่ำ โดยมีไส้เทียนด้านบนยาว — ผู้ซื้อดันขึ้นและผู้ขายลากมันกลับไปที่ต่ำ","also":"นอกจากนี้: แข็งแกร่งที่สุดที่แนวต้าน / BB บน / RSI ที่ซื้อมากเกินไป กระจกเงาของแมลงปอ สอน: จุดสูงสุดที่ปิดที่ระดับต่ำถือเป็นการฝ่าวงล้อมที่ล้มเหลว"},{"shape":"inside_bar","name":"อินไซด์บาร์","color":"#94a3b8","bias":"คอยม้วน/รอ","tip":"แท่งเทียนอันที่สองอยู่ภายในแท่งเทียนแท่งแรกพอดี — ช่วงถูกบีบอัดและตลาดกลั้นหายใจ","also":"นอกจากนี้: การทะลุของแถบแม่เป็นตัวกระตุ้น — ซื้อขายในทิศทางการทะลุ จับคู่กับบีบีบีบ สอน: การหดตัวเกิดขึ้นก่อนการขยายตัว"},{"shape":"outside_bar","name":"บาร์ด้านนอก","color":"#22c55e","bias":"ฝ่าวงล้อม / พลิกกลับ","tip":"แท่งเทียนอันที่สองกลืนแท่งเทียนอันแรกจากสูงไปต่ำ — การเข้าครอบครองอย่างรุนแรงภายในแท่งเดียว","also":"นอกจากนี้: ทิศทาง = ตำแหน่งที่แถบด้านนอกปิด แถบใหญ่หมายถึง SL ขนาดใหญ่ ดังนั้นขนาดที่เล็กลง สอน: หนึ่งแถบสามารถลบสามอันสุดท้ายได้"},{"shape":"belt_bull","name":"ถือเข็มขัดรั้น","color":"#22c55e","bias":"ซื้อ","tip":"เปิดที่จุดต่ำโดยไม่มีไส้ตะเกียงที่ต่ำกว่าและเป็นสีเขียว — ผู้ซื้อเข้าควบคุมตั้งแต่ขีดแรก","also":"นอกจากนี้: แข็งแกร่งที่สุดหลังจากช่องว่างลงหรือตรงเข้าสู่แนวรับ SL ภายใต้การเปิด สอน: แรงขับที่เปิดแสดงเจตนาที่แท้จริง"},{"shape":"belt_bear","name":"ถือเข็มขัดหยาบคาย","color":"#ef4444","bias":"ขาย","tip":"เปิดที่ราคาสูงโดยไม่มีไส้เทียนด้านบนและเป็นสีแดง — ผู้ขายควบคุมจากราคาเปิด","also":"นอกจากนี้: แข็งแกร่งที่สุดหลังจากช่องว่างขึ้นหรือแนวต้าน เส้นทางยาว สอน : ก้าวแรกสามารถกำหนดได้ทั้งวัน"},{"shape":"kick_bull","name":"นักเตะรั้น","color":"#22c55e","bias":"ซื้อแข็งแกร่ง","tip":"แท่งเทียนสีแดง จากนั้นช่องว่างขึ้นไปเป็นแท่งเทียนสีเขียว — อารมณ์พลิกไปมาระหว่างการปิดโดยไม่มีการทับซ้อนกัน","also":"นอกจากนี้: หายากและทรงพลัง; จำเป็นต้องมีช่องว่าง ไม่อนุญาตให้มีการทับซ้อนกัน สอน: ความรู้สึกสามารถพลิกผันได้ในขณะที่ตลาดหลับใหล"},{"shape":"kick_bear","name":"นักเตะหมี","color":"#ef4444","bias":"ขายแข็งแกร่ง","tip":"แท่งเทียนสีเขียว จากนั้นช่องว่างลงไปที่แท่งเทียนสีแดง — ผู้ซื้อหายไประหว่างการปิดตลาด","also":"นอกจากนี้: ออกยาวอย่างรวดเร็ว — นักเตะไม่รอคุณ สอน: ช่องว่างคือตลาดที่เปลี่ยนราคาเมื่อคุณไม่อยู่"},{"shape":"abandoned","name":"เด็กที่ถูกทอดทิ้งรั้น","color":"#22c55e","bias":"ซื้อแข็งแกร่ง","tip":"เทียนสีแดง โดจิช่องว่าง ตามด้วยเทียนสีเขียวช่องว่าง — เกาะแห่งความไม่แน่ใจที่โดดเดี่ยว","also":"นอกจากนี้: โดจิจะต้องเว้นระยะห่างทั้งสองข้าง หายาก แต่มีคุณภาพสูงที่ด้านล่าง สอน: การกลับตัวเริ่มต้นเมื่อทุกคนยอมแพ้"},{"shape":"three_inside_up","name":"สามอินไซด์อัพ","color":"#22c55e","bias":"ซื้อ","tip":"Harami รั้นบวกแท่งเทียนสีเขียวแท่งที่สามซึ่งปิดเหนือแท่งแรก — ในที่สุดแท่งด้านในก็แตกออก","also":"นอกจากนี้: Harami ที่ได้รับการยืนยันนั้นแข็งแกร่งกว่า Harami ที่เปลือยเปล่ามาก SL ภายใต้ฮารามิต่ำ สอน: การยืนยันเอาชนะการทำนาย"},{"shape":"three_inside_down","name":"สามข้างในลง","color":"#ef4444","bias":"ขาย","tip":"Bearish Harami บวกแท่งเทียนสีแดงแท่งที่สามปิดต่ำกว่าแท่งแรก — แท่งด้านในพังลง","also":"นอกจากนี้: ตัด longs ทันทีที่ปิดครั้งที่สาม สอน: การหยุดชั่วคราวที่ล้มเหลวสามารถกลับสู่แนวโน้มเดิมได้"},{"shape":"three_methods_bull","name":"เพิ่มขึ้นสามวิธี","color":"#22c55e","bias":"แนวโน้มการซื้อ","tip":"เทียนสีเขียวยาว มีสีแดงเล็กๆ สามแท่งอยู่ข้างใน และสีเขียวยาวอีกอัน — พักอยู่ในขาขึ้น","also":"นอกจากนี้: การหยุดชั่วคราวไม่เคยออกจากช่วงแท่งเทียนแรก ดังนั้นแนวโน้มจึงสงบ ซื้อขายจุดทะลุของแท่งเทียนสุดท้าย สอน: แนวโน้มพักตัวโดยไม่ทำลาย"},{"shape":"three_methods_bear","name":"ล้มสามวิธี","color":"#ef4444","bias":"ขายแนวโน้ม","tip":"เทียนยาวสีแดง มีสีเขียวเล็กๆ สามอันอยู่ข้างใน และสีแดงยาวอีกอันหนึ่ง — พักอยู่ในฤดูใบไม้ร่วง","also":"นอกจากนี้: กระจกเงาของ Rising Three Methods อย่าซื้อผักใบเล็กๆ เพราะมันจะส่งเสียงดัง สอน: การดึงกลับภายในช่วงจะไม่กลับตัว"},{"shape":"tower_bot","name":"ทาวเวอร์ด้านล่าง","color":"#22c55e","bias":"ซื้อการกลับรายการ","tip":"เทียนสีแดงยาว เทียนเล็กๆ กลุ่มหนึ่ง จากนั้นเป็นสีเขียวยาว อารมณ์จะเปลี่ยนไปบนฐานแบน","also":"นอกจากนี้: ตรงกลางแบนคือการต่อสู้ และเทียนเล่มสุดท้ายประกาศผู้ชนะ สอน: ฐานต้องใช้เวลา"},{"shape":"tower_top","name":"ทาวเวอร์ท็อป","color":"#ef4444","bias":"ขายการกลับรายการ","tip":"เทียนสีเขียวยาว กลุ่มเทียนเล็กๆ จากนั้นเป็นสีแดงยาว ผู้ซื้อหมดแรงและผู้ขายเข้าครอบครอง","also":"นอกจากนี้: กระจกของ Tower Bottom ใช้เวลาบางส่วนในขณะที่รูปแบบฐาน สอน: การท็อปส์ซูเป็นกระบวนการ ไม่ใช่ชั่วขณะหนึ่ง"}],"chartPatterns":[{"shape":"double_bot","name":"ก้นคู่ (W)","color":"#22c55e","bias":"ซื้ออคติ","tip":"จุดต่ำสุดสองจุดใกล้ราคาเดียวกัน จากนั้นทะลุจุดยอดกลาง — รูปทรง W","also":"นอกจากนี้: การแบ่งคอ = ทริกเกอร์ฝึก วัดส่วนสูงสำหรับแนวคิด TP ลิงก์ไปยัง Tweezer Bottom + Fib จากจุดสูงสุด→ต่ำ ความเสี่ยง: การพังที่ผิดพลาด — รอไว้ใกล้เกินคอเสื้อ"},{"shape":"double_top","name":"ดับเบิ้ลท็อป (M)","color":"#ef4444","bias":"ขายอคติ","tip":"สองจุดสูงใกล้ราคาเดียวกัน จากนั้นทะลุรางกลาง — รูปตัว M","also":"นอกจากนี้: เช่นเดียวกับ Tweezer Top ในขนาดที่ใหญ่กว่า เทรลยาวก่อนที่คอเสื้อจะหัก จิตวิทยา: FOMO อันดับสองมีราคาแพง — มีแผนอยู่แล้ว"},{"shape":"hs_top","name":"เฮดแอนด์โชว์เดอร์","color":"#ef4444","bias":"ขายอคติ","tip":"ไหล่ซ้าย, หัวสูงกว่า, ไหล่ขวา; หักคอลง","also":"นอกจากนี้: การกระจายแบบคลาสสิก ตั้งเป้าไว้ที่ความสูงศีรษะต่ำกว่าคอเสื้อ RSI มักจะแตกต่างที่ส่วนหัว สอนความอดทนแบบหลายแกว่ง — ไม่ใช่การซื้อขายแบบแท่งเทียนเดียว"},{"shape":"ihs","name":"ผกผัน H&S","color":"#22c55e","bias":"ซื้ออคติ","tip":"H&S แบบกลับหัวที่ท่อนล่าง — ช่วงคอแยกออก","also":"นอกจากนี้: เรื่องราวการสะสม ยืนยันด้วยปริมาตร/โมเมนตัม หากมี จับคู่กับ Morning Star บริเวณไหล่ขวาเพื่อศึกษาจุดบรรจบกัน"},{"shape":"triangle","name":"สามเหลี่ยม (บีบ)","color":"#f0b429","bias":"รอหลุดครับ","tip":"เสียงสูงต่ำ + เสียงสูงต่ำบีบอัด — การสร้างพลังงาน","also":"นอกจากนี้: บทเรียนเดียวกันกับ BB squeeze อย่าคาดเดาทิศทางภายใน พักการค้า + ปิดเทียน เงินตรา: ขนาดตามทิศทางที่ทราบ"},{"shape":"flag","name":"ธงกระทิง","color":"#22c55e","bias":"ซื้อต่อ","tip":"เพิ่มขึ้นอย่างรวดเร็ว (เสา) จากนั้นช่องลง / ด้านข้างเล็ก ๆ — จากนั้นต่อเนื่อง","also":"นอกจากนี้: ความลึกของธง Fib มักจะตื้น (38%) เสา Marubozu + ธง = การฝึกเทรนด์ อย่าซื้อช้าหลังจากขยายเต็มโดยไม่มีการดึงกลับ"},{"shape":"channel","name":"เทรนด์แชนแนล","color":"#38bdf8","bias":"ด้วยเทรนด์","tip":"ราคาระหว่างเส้นขนานที่เพิ่มขึ้น (หรือลดลง) — เครื่องมือการซื้อขายแบบสวิง","also":"นอกจากนี้: ซื้อช่องทางที่ต่ำกว่า + Hammer ในแนวโน้มขาขึ้น; ขายบน+ดาวตก. BB mid มักจะติดตามช่อง สอน \"ที่ไหน\" ไม่ใช่แค่ \"เทียนอะไร\""},{"shape":"support_res","name":"แนวรับและแนวต้าน","color":"#a78bfa","bias":"บริบทก่อน","tip":"โซนแนวนอนที่ราคาตอบสนองซ้ำๆ — แผนที่ใต้แท่งเทียนทุกอัน","also":"นอกจากนี้: ทุกรูปแบบจะแข็งแกร่งขึ้นที่ S/R วาดโซนบน Chart Lab ก่อน BB/RSI จิตวิทยา: ระดับ > เคล็ดลับ; เขียนไว้ก่อนเข้า"},{"shape":"triple_top","name":"ทริปเปิ้ลท็อป","color":"#ef4444","bias":"ขายอคติ","tip":"จุดสูงสุดสามจุดในราคาที่เกือบเท่ากัน — ผู้ซื้อล้มเหลวสามครั้งที่กำแพงด้านเดียว","also":"นอกจากนี้: แข็งแกร่งกว่า Double Top (การปฏิเสธสามครั้ง = อุปทานที่ดื้อรั้น) การหักของคอเสื้อเป็นตัวกระตุ้น เป้าหมาย ความสูงของรูปแบบ สอน: ระดับไม่ใช่เทียนคือเจ้านาย"},{"shape":"triple_bot","name":"สามล่าง","color":"#22c55e","bias":"ซื้ออคติ","tip":"ราคาต่ำสุดสามจุดในราคาที่เกือบเท่ากัน — ผู้ขายล้มเหลวสามครั้งในชั้นเดียว","also":"นอกจากนี้: กระจกของ Triple Top การสัมผัสแต่ละครั้งอาจเป็นการศึกษาแบบค้อน / แหนบ รอคอหัก+ปิด สอนความอดทนในการแกว่งหลายครั้ง"},{"shape":"cup_handle","name":"ถ้วยและที่จับ","color":"#22c55e","bias":"ซื้อต่อ","tip":"ตัว “U” ที่โค้งมน (ถ้วย) จากนั้นดึงกลับเล็กน้อย (ที่จับ) — ต่อเนื่องหลังจากพัก","also":"นอกจากนี้: เป็นที่นิยมในหมู่เทรดเดอร์ที่ฝ่าวงล้อม ด้ามจับควรตื้นและสั้น ด้ามจับลึกหมายถึงมือที่อ่อนแอ เข้าที่แฮนด์เบรกพร้อมยืนยันเทียน"},{"shape":"rounding_bot","name":"การปัดเศษด้านล่าง","color":"#22c55e","bias":"ซื้อการกลับรายการ","tip":"“จานรอง” ที่ช้าและราบรื่น — การขายค่อยๆ จางหายไป จากนั้นผู้ซื้อจะเข้ามาแทนที่","also":"นอกจากนี้: Double Bottom แบบสโลว์โมชั่น ข้อความก็คือผู้ขายหมดพลังงาน ไม่ใช่การเพิ่มขึ้นแม้แต่นิดเดียว — ต้องใช้ความอดทนเต็มที่"},{"shape":"rounding_top","name":"การปัดเศษด้านบน","color":"#ef4444","bias":"ขายการกลับรายการ","tip":"ระดับ “โดม” ที่ราบเรียบ — การซื้อค่อยๆ จางหายไปก่อนที่ราคาจะพลิกกลับ","also":"นอกจากนี้: กระจกเงาของ Rounding Bottom รับประทานบางส่วนแต่เนิ่นๆ ในขณะที่โมเมนตัมหมดลง สอน: ยอดเป็นกระบวนการ ไม่ใช่เทียนเล่มเดียว"},{"shape":"rising_wedge","name":"ลิ่มที่เพิ่มขึ้น","color":"#ef4444","bias":"ขายอคติ","tip":"รางทั้งสองสูงขึ้น แต่มาบรรจบกันขึ้น — ผู้ซื้อยางเมื่อช่วงบีบ","also":"นอกจากนี้: ทำให้เข้าใจผิดเนื่องจากราคายังคงเพิ่มขึ้น การแคบลงเป็นเบาะแสที่แท้จริง มักจะพังทลายลง อย่าไล่ตามการผลักดันครั้งสุดท้าย"},{"shape":"falling_wedge","name":"ล้มลิ่ม","color":"#22c55e","bias":"ซื้ออคติ","tip":"รางทั้งสองตกลงมา แต่พวกมันมาบรรจบกันลง — ผู้ขายยางเมื่อระยะบีบตัว","also":"นอกจากนี้: กระจกเงาของ Rising Wedge มักจะเลิกกัน ค้อนที่หางลิ่มเป็นการศึกษาแบบคลาสสิก รอพัก+ปิดครับ."},{"shape":"asc_triangle","name":"สามเหลี่ยมจากน้อยไปหามาก","color":"#f0b429","bias":"ซื้ออคติ","tip":"เพดานเรียบ + พื้นยกสูง — ผู้ซื้อก้าวขึ้นไปสู่แนวต้านคงที่","also":"นอกจากนี้: ความกดดันสร้างขึ้นต่อราคาเดียว การแตกหักเป็นเรื่องปกติ เข้ามาใกล้เหนือเพดาน สอน: ผู้ซื้อเริ่มใจร้อน"},{"shape":"desc_triangle","name":"สามเหลี่ยมขาลง","color":"#f0b429","bias":"ขายอคติ","tip":"พื้นเรียบ + เพดานล้ม — ผู้ขายพยายามผลักดันเข้าสู่แนวรับคงที่","also":"นอกจากนี้: กระจกเงาของสามเหลี่ยมจากน้อยไปมาก การฝ่าวงล้อมเป็นเรื่องปกติ เข้าไปใกล้ด้านล่างพื้น สอน: ผู้ขายได้รับการควบคุม"},{"shape":"pennant","name":"ชายธง","color":"#22c55e","bias":"ความต่อเนื่อง","tip":"เสาแหลมคมจากนั้นก็เป็นรูปสามเหลี่ยมเล็กๆ ที่แน่น — พักสั้นมากก่อนที่เทรนด์จะกลับมาอีกครั้ง","also":"นอกจากนี้: เหมือนธงแต่สั้นกว่าและเป็นสามเหลี่ยม วัดเสาเพื่อหาแนวคิดเป้าหมาย อย่าคาดเดาภายในขดลวดเล็กๆ"},{"shape":"flag_bear","name":"ธงหมี","color":"#ef4444","bias":"ขายต่อ","tip":"การตกลงอย่างรวดเร็ว (เสา) จากนั้นเป็นช่องขึ้นด้านบน/ด้านข้างเล็กๆ — จากนั้นต่อเนื่องลง","also":"นอกจากนี้: กระจกเงาธงกระทิง การตีกลับเล็กน้อยคือการหยุดชั่วคราว ไม่ใช่การกลับตัว ไล่ตามธงแล้วคุณจะซื้อราคาที่แย่ที่สุด — รอจนพัง"},{"shape":"rectangle","name":"สี่เหลี่ยมผืนผ้า (ช่วง)","color":"#f0b429","bias":"การค้าขายช่วง","tip":"ราคาเด้งระหว่างเพดานเรียบกับพื้น — กล่องด้านข้าง","also":"นอกจากนี้: ทำให้ขอบด้านในจางลง แลกส่วนแตกหักด้านนอก BB squeeze มักจะอยู่ในรูปสี่เหลี่ยมผืนผ้า สอน: มีระเบียบวินัยระดับต่อระดับ"},{"shape":"broadening","name":"การขยายรูปแบบ","color":"#f0b429","bias":"ข้อควรระวัง","tip":"เสียงสูงที่สูงกว่าและจุดต่ำสุดที่ต่ำกว่า — ช่วงจะกระจายออกแทนที่จะบีบ","also":"นอกจากนี้: ตลาดที่วุ่นวายและเต็มไปด้วยอารมณ์ หยุดโดนทั้งสองทาง ขนาดเล็กกว่าหรือยืนกัน มันมักจะจบลงด้วยการเคลื่อนไหวทางเดียวที่รุนแรง"},{"shape":"diamond","name":"เพชร","color":"#f0b429","bias":"การกลับรายการ","tip":"กว้างตรงกลาง แคบที่ปลายทั้งสองข้าง — รูปแบบการเติมหน้า/จุดต่ำสุดสุดคลาสสิก","also":"นอกจากนี้: สามเหลี่ยมที่ morphs แล้วไม่ morphs ทิศทางการฝ่าวงล้อมตัดสินใจ หายากและช้า ดังนั้นแถวส่วนใหญ่จึงรู้สึกเหมือนมีเสียงรบกวน — อดทนหน่อยนะ"},{"shape":"island_rev","name":"การกลับเกาะ","color":"#ef4444","bias":"การกลับรายการ","tip":"ราคาห่างหายไป ค้าขายในกลุ่มโดดเดี่ยว จากนั้นจึงแยกกลับ — กลายเป็น \"เกาะ\"","also":"นอกจากนี้: ต้องการช่องว่างที่แท้จริง (พบได้บ่อยในหุ้น/FX) เกาะติดกับดักผู้ซื้อหรือผู้ขาย ถือว่าช่องว่างเป็นสัญญาณ ไม่ใช่เทียนเกาะ"},{"shape":"breakaway_gap","name":"ช่องว่างที่แยกออก","color":"#22c55e","bias":"เทรนด์เริ่มต้น","tip":"ช่องว่างที่อยู่นอกขอบเขตหรือฐาน — การเคลื่อนไหวเริ่มต้นด้วยแรง ไม่ใช่การบีบ","also":"นอกจากนี้: ไม่เหมือนกับช่องว่างความเหนื่อยล้า มันจะปรากฏตั้งแต่เนิ่นๆ ของการเคลื่อนไหว Gap มักจะทำหน้าที่เป็นแนวรับ/แนวต้านในภายหลัง สอน: โมเมนตัมกับช่องว่างของมูลค่า"},{"shape":"v_reversal","name":"V-การกลับรายการ","color":"#22c55e","bias":"การกลับรายการ","tip":"การดิ่งลงอย่างอิสระที่พลิกกลับทันทีโดยไม่มีฐาน - “V”","also":"นอกจากนี้: รวดเร็วและน่ากลัว มักขับเคลื่อนด้วยข่าว จับยาก ไล่ล่าง่าย รอการกลับตัว + แท่งเทียนเล็กๆ แทนที่จะซื้อการพุ่งขึ้น"},{"shape":"harmonic","name":"รูปแบบฮาร์มอนิก","color":"#f0b429","bias":"โซนกลับตัว","tip":"ซิกแซกที่วัดได้ (X-A-B-C-D) โดยที่แต่ละขามีอัตราส่วน Fibonacci — แผนที่สไตล์ “Gartley/Bat”","also":"นอกจากนี้: ขั้นสูง จุด D คือโซนทางเข้า กำหนดโดยอัตราส่วน ไม่ใช่ความรู้สึก ฝึกพูดปดธรรมดาก่อน นี่คือ Fib ที่ลึกลงไปอีกระดับหนึ่ง"}],"modules":[{"id":"bb","title":"1 · โบลินเจอร์ แบนด์ (BB)","summary":"แถบความผันผวนรอบค่าเฉลี่ยเคลื่อนที่ เรียนรู้การบีบ วอล์คเดอะแบนด์ สัมผัสล่าง/บน + ยืนยันเทียน — การตั้งค่าการฝึก CPE หลัก","lessons":[{"h":"บีบีคืออะไร","t":"Bollinger Bands = SMA กลาง (มักจะ 20) + แถบบน/ล่างที่ค่าเบี่ยงเบนมาตรฐาน N (มักจะ 2) แถบจะกว้างขึ้นเมื่อความผันผวนเพิ่มขึ้นและบีบตัวเมื่อตลาดเงียบสงบ"},{"h":"วงกลาง","t":"เส้นกลางคือค่าเฉลี่ย ราคาที่อยู่เหนือระดับกลางมักจะแสดงถึงแรงกดดันแบบกระทิง ด้านล่างแสดงแรงกดดันขาลง ใช้มันเป็นเส้นอคติแบบไดนามิก ไม่ใช่การซื้อ/ขายแบบวิเศษ"},{"h":"วงล่าง (ซื้อแบบฝึกหัด)","t":"การติดแท็กราคาที่แถบด้านล่างหลังจากลดลงอาจหมายถึง “ยืดตัวลง” อย่าซื้อทุกสัมผัส รอแท่งเทียนขาขึ้น (Hammer, Engulfing) และ RSI จะกลับมาเป็นขาขึ้น"},{"h":"แถบบน (ขาย / เตือน)","t":"การติดแท็กราคาที่แถบด้านบนอาจหมายถึง \"ยืดออก\" ในแนวโน้มขาขึ้น ราคาสามารถขี่แถบบน (walk-the-band) ต้องการขายแนวคิดเฉพาะกับแท่งเทียนขาลง + จุดอ่อน TF ที่สูงขึ้น"},{"h":"บีบ","t":"แถบแคบ = ความผันผวนต่ำ → การทะลุมักจะตามมา อย่าคาดเดาทิศทางภายในการบีบแน่น ทำเครื่องหมายการฝ่าวงล้อมและยืนยันด้วยแท่งเทียน + ปริมาณ หากมี"},{"h":"เดินวงดนตรี","t":"ในแนวโน้มที่แข็งแกร่ง ราคาจะกอดแถบบน (หรือล่าง) ของแท่งเทียนหลายอัน การต่อสู้กับสิ่งนั้นด้วยการซีดจางแบบ Mean-Reversion ถือเป็นข้อผิดพลาดทั่วไปของผู้เริ่มต้น"},{"h":"BB + แผนภูมิแล็บ","t":"ใน CPE Chart Lab / โต๊ะ ศึกษา BB ด้วยเทียนบน DEMO แนวปฏิบัติ: แถบล่าง + ค้อน → ซื้อขายกระดาษกับ SL ด้านล่างไส้ตะเกียง TP1 ใกล้แถบกลาง"},{"h":"บีบี + RSI คอมโบ","t":"ตัวกรองแนวปฏิบัติที่แข็งแกร่งยิ่งขึ้น: BB ที่ต่ำกว่า + RSI ขายมากเกินไป (หรือเพิ่มขึ้นจากการขายมากเกินไป) + แท่งเทียนรั้น BB ระดับบน + RSI ซื้อมากเกินไป + เทียนหมีสำหรับการฝึกซ้อมระยะสั้น"},{"h":"หยุดตำแหน่ง","t":"การฝึกระยะไกล: SL ใต้ไส้เทียนวงสวิงต่ำ/ต่ำกว่าไส้เทียนวงล่าง การฝึกระยะสั้น: SL เหนือสวิงสูง อย่าเข้าสู่การค้า BB โดยไม่มี SL เป็นลายลักษณ์อักษร"},{"h":"เป้าหมาย","t":"เส้นทางทั่วไป: TP1 ที่แถบกลาง TP2 ไปทางแถบตรงข้ามหรือเส้นทาง ขยายขนาด — ไม่จำเป็นต้องย้ายทั้งหมด"},{"h":"กรอบเวลา","t":"ตัดสินใจมีอคติต่อ TF ที่สูงขึ้น (4H/1D) เข้าสู่ 15m/30m BB + เทียน การผสม TF แบบสุ่มทำให้เกิดสัญญาณที่ขัดแย้งกัน"},{"h":"ข้อผิดพลาดที่ควรหลีกเลี่ยง","t":"ซื้อทุกสัมผัสย่านความถี่ต่ำในตลาดที่ล่มสลาย ขายทุกการสัมผัสบนดวงจันทร์ ไม่มี SL; โดยไม่สนใจกระแสข่าวที่ทำให้วงดนตรีกว้างขึ้นอย่างรุนแรง"},{"h":"รายการตรวจสอบการปฏิบัติ","t":"1 อคติ TF ที่สูงขึ้น 2 สัมผัส BB หรือการบีบตัว 3 เทียนยืนยัน ④ RSI เห็นด้วย ⑤ % ความเสี่ยงที่ตั้งไว้ ⑥ กระดาษก่อน ⑦ ผลบันทึกประจำวัน"}]},{"id":"rsi","title":"2 · RSI (ดัชนีความแข็งแกร่งสัมพัทธ์)","summary":"โมเมนตัมออสซิลเลเตอร์ 0–100 งวด 14 เริ่มต้น ใช้กับ BB และแท่งเทียน — อย่าใช้ RSI เพียงอย่างเดียวเป็นระบบเต็มรูปแบบ","lessons":[{"h":"RSI ใช้มาตรการอะไร","t":"RSI เปรียบเทียบกำไรและขาดทุนโดยเฉลี่ยเหนือแท่ง N RSI สูง = โมเมนตัมขาขึ้นล่าสุด RSI ต่ำ = โมเมนตัมขาลงล่าสุด ไม่ใช่ “ซื้อเกิน = ต้องขาย” ทุกครั้ง"},{"h":"โซนคลาสสิค","t":"บ่อยครั้ง: สูงกว่า 70 = โซนซื้อมากเกินไป, ต่ำกว่า 30 = โซนขายมากเกินไป ในแนวโน้มที่แข็งแกร่ง RSI อาจมีการซื้อมากเกินไป/ขายมากเกินไปเป็นเวลานาน ซึ่งเป็นเรื่องปกติ"},{"h":"เส้นกลาง 50","t":"การข้าม RSI ที่สูงกว่า 50 สามารถรองรับอคติแบบกระทิงได้ ต่ำกว่า 50 อคติขาลง เทรดเดอร์หลายรายใช้ 50 เป็นตัวกรองเทรนด์โดยมีแถบกลาง BB"},{"h":"ความแตกต่าง — รั้น","t":"ราคาทำให้ต่ำลง RSI ทำให้สูงขึ้นต่ำ → โมเมนตัมอ่อนตัวลงในขาลง ยังคงรอการทะลุของแท่งเทียน + โครงสร้างก่อนเข้า Paper"},{"h":"ความแตกต่าง — ภาวะหมี","t":"ราคาสูงขึ้น สูง RSI สูงต่ำ → โมเมนตัมขาขึ้นจางลง ยืนยันด้วยดาวยิง / กลืนใกล้แนวต้านหรือ BB บน"},{"h":"ความล้มเหลวชิงช้า","t":"RSI ล้มเหลวในการทดสอบจุดสุดขั้วก่อนหน้าอีกครั้ง จากนั้นข้ามกลับไปผ่าน 50 ซึ่งเป็นเบาะแสการเปลี่ยนแปลงโมเมนตัมในช่วงต้น รวมกับโครงสร้าง Chart Lab"},{"h":"RSI + BB (แบบ CPE)","t":"ฝึกฝนระยะยาว: ราคาใกล้ BB ที่ต่ำกว่า, RSI ≤ 35 (หรือเพิ่มขึ้นจาก ≤ 30), แท่งเทียนรั้น ฝึกระยะสั้น: BB บน, RSI ≥ 65–70, แท่งเทียนหมี"},{"h":"ความแตกต่างที่ซ่อนอยู่","t":"เบาะแสความต่อเนื่องของเทรนด์ (เช่น ราคาสูงขึ้นต่ำ RSI ลดลงต่ำในแนวโน้มขาขึ้น) ขั้นสูง — เชี่ยวชาญ Divergence แบบคลาสสิกก่อนใครบน DEMO"},{"h":"การตั้งค่า","t":"RSI(14) เป็นค่าเริ่มต้นทั่วไป RSI สั้นลง = สัญญาณรบกวนมากขึ้น อย่าเปลี่ยนการตั้งค่าบ่อยๆ เพื่อบังคับสัญญาณ"},{"h":"ออกด้วย RSI","t":"หากคุณซื้อมากเกินไป การทำกำไรบางส่วนเมื่อ RSI ไปถึงโซนกลาง/บนนั้นสมเหตุสมผล เดินตามส่วนที่เหลือด้วยโครงสร้างหรือบีบีตรงกลาง"},{"h":"ข่าวและ RSI","t":"ข่าวใหญ่สามารถพุ่งขึ้น RSI ได้ทันที รอให้แท่งเทียนรุนแรงแท่งแรกจบก่อนที่จะดำเนินการกับ RSI สุดขั้ว"},{"h":"ความผิดพลาด","t":"ลัดวงจรทุกๆ RSI>70 ในตลาดกระทิง โหยหาทุกๆ RSI<30 ในการชนของหมี; ไม่มีการบรรจบกัน แก้แค้นกลับเข้ามาอีกครั้งเมื่อ RSI “ดูดีขึ้น”"},{"h":"รายการตรวจสอบการปฏิบัติ","t":"1 หมายเหตุ ค่า RSI + ความชัน 2 ตรวจสอบตำแหน่ง BB 3 เทียนยืนยัน ④ TF ที่สูงขึ้น ⑤ กระดาษ + บันทึกประจำวัน ⑥ ทีละแนวคิด"}]},{"id":"fib","title":"3 · ฟีโบนัชชี (การย้อนกลับและส่วนขยาย)","summary":"วัดการดึงกลับและเป้าหมายจากการสวิงสูงที่ชัดเจน → สวิงต่ำ (หรือย้อนกลับ) มุ่งเน้นไปที่ 38.2 · 50 · 61.8 โดยมีจุดบรรจบกันของ BB/RSI","lessons":[{"h":"เหตุใดจึงใช้ไฟเบอร์","t":"เทรดเดอร์หลายรายดูอัตราส่วนเดียวกัน ดังนั้นสภาพคล่องจึงมักจะตอบสนองเมื่ออยู่ใกล้พวกเขา Fib คือแผนที่ของโซนที่เป็นไปได้ — ไม่ใช่การรับประกัน"},{"h":"จุดสวิง","t":"ควรวาดจากการสวิงที่ชัดเจนจากต่ำไปแกว่งสูง (ขึ้น) หรือสูงไปต่ำ (ลง) การสวิงที่ไม่ดี = ระดับที่ไร้ประโยชน์ ฝึกเลือกวงสวิงบน Chart Lab DEMO"},{"h":"การย้อนกลับที่สำคัญ","t":"ทั่วไป: 23.6% (ตื้น), 38.2%, 50% (ไม่ใช่ Fib บริสุทธิ์แต่ใช้กันอย่างแพร่หลาย), 61.8% (สีทอง), 78.6% (ลึก) การถอยกลับลึกอาจส่งสัญญาณถึงความอ่อนแอของแนวโน้ม"},{"h":"การซื้อแบบดึงกลับ (ขาขึ้น)","t":"หลังจากแรงกระตุ้นขึ้น ให้รอการกลับตัวเข้าสู่โซน 38.2–61.8 + แท่งเทียนรั้น + แนวรับ BB ตรงกลาง/ล่าง หรือ RSI ถือ >40–45"},{"h":"ขายแบบดึงกลับ (ขาลง)","t":"หลังจากแรงกระตุ้นลดลง ขึ้นมาที่ 38.2–61.8 + แท่งเทียนหมี + RSI ล้มเหลวต่ำกว่า 55–60"},{"h":"ส่วนขยาย/เป้าหมาย","t":"ส่วนขยายทั่วไป: 127.2%, 161.8% เหนือกว่าแนวคิด TP2 ใช้กับเทรล — อย่าบังคับขีดแน่นอน"},{"h":"การบรรจบกัน = อำนาจ","t":"โซนแนวปฏิบัติที่ดีที่สุด: Fib 50/61.8 + BB ตรงกลาง/ล่าง + โครงสร้างก่อนหน้า + การเลี้ยว RSI สาย Fib เพียงอย่างเดียวก็อ่อนแอ"},{"h":"ไฟเบอร์+บีบี","t":"หาก 61.8% อยู่ใกล้กับ BB ที่ต่ำกว่าในแนวโน้มขาขึ้น การทับซ้อนกันนั้นจะเป็นโซนการศึกษา Paper คุณภาพสูง เข้าด้วยเทียนยืนยันเท่านั้น"},{"h":"ไฟเบอร์หลายตัว","t":"ผู้เริ่มต้นควรใช้วงสวิงเดียวที่สะอาด การซ้อน 5 Fibs จะสร้างสัญญาณรบกวนบนกราฟและรายการ FOMO"},{"h":"การทำให้เป็นโมฆะ","t":"หากราคาปิดอย่างชัดเจนเกิน 78.6% เมื่อเทียบกับอคติของคุณ วิทยานิพนธ์การดึงกลับมักจะล้มเหลว — ออกหรือยืนเคียงข้างกัน"},{"h":"ฟอเร็กซ์ กับ การเข้ารหัสลับ","t":"อัตราส่วนเดียวกัน วิชาเอก Forex มักจะเคารพระดับที่ชัดเจนมากขึ้นในช่วงที่มีสภาพคล่อง crypto สามารถไส้ตะเกียงผ่านแล้วย้อนกลับ — ขนาดที่เล็กลง"},{"h":"ความผิดพลาด","t":"การวาด Fib บนเสียงที่แกว่งไปมาเล็กน้อย เข้าสู่กลางอากาศโดยไม่มีเทียน ย้าย SL ออกไปอีกเมื่อ Fib “เกือบ” ถือ; ไม่สนใจ TF ที่สูงขึ้น"},{"h":"รายการตรวจสอบการปฏิบัติ","t":"1 มาร์คสวิง 2 หมายเหตุ 38.2/50/61.8 3 รอราคามาถึง ④ เทียน + RSI/BB ⑤ ชุดความเสี่ยง ⑥ กระดาษ → วารสาร"}]},{"id":"money","title":"4 ·การจัดการเงิน","summary":"วิธีการใช้จริง: เสี่ยงเป็นเปอร์เซ็นต์คงที่, ขนาดจากการหยุด, เหลือส่วนของกำไร และหยุดในวันถัดไปหลังจากขีดจำกัดการขาดทุน CPE สามารถใช้สิ่งนี้กับการซื้อขายด้วยตนเองและการซื้อขายอัตโนมัติ","lessons":[{"h":"เป้าหมายของการบริหารเงิน","t":"อยู่ในเกม การซื้อขายที่ไม่ดีครั้งหนึ่งไม่ควรล้างบัญชี ความสม่ำเสมอมีชัยเหนือขนาดลอตเตอรี"},{"h":"วิธีที่เทรดเดอร์ใช้งานจริง","t":"แนวทางปฏิบัติทั่วไปคือความเสี่ยงแบบเศษส่วนคงที่ คุณไม่เลือกจำนวนเหรียญก่อน คุณเขียนจุดหยุดก่อน ตัดสินใจว่าแนวคิดนี้อาจสูญเสียบัญชีไปประมาณ 1% จากนั้นขนาดก็จะลดขนาดลง การหยุดแบบกว้างจะได้ตำแหน่งที่เล็กลง การหยุดนิ่งจะทำให้ตำแหน่งมีขนาดใหญ่ขึ้น และความเสี่ยงของเงินดอลลาร์จะยังคงเท่าเดิม นี่คือวิธีที่ CPE ใช้เมื่อเปิดเครื่องหมายการจัดการเงิน"},{"h":"ตัวอย่างการทำงาน ($1,000 บัญชีฝึกหัด)","t":"บัญชี $1,000. ความเสี่ยง 1% = $10 เข้า 100 หยุด 98 ระยะทาง = 2% ขนาด = 10 ۞ 0.02 = $500 ตามสัญญา หากถึงจุดหยุด การขาดทุนจะอยู่ที่ประมาณ 10 ดอลลาร์ ไม่ใช่ 500 ดอลลาร์ หากราคาถึง 103 (1.5 เท่าของความเสี่ยง) กำไรจะอยู่ที่ประมาณ 15 ดอลลาร์ แนวคิดเดียวกันในทุกคู่: ดอลลาร์ที่มีความเสี่ยงอยู่ใกล้ 1% ปริมาณเหรียญเปลี่ยนแปลง"},{"h":"CPE ทำอะไรกับเห็บ","t":"ซื้อขายทันที → อัตโนมัติ: ทำเครื่องหมายที่ “ใช้การจัดการเงิน” บันทึกการกำหนดค่าอัตโนมัติ การซื้อขายรถยนต์ใหม่แต่ละครั้งจะใช้ประมาณ 1% ของบัญชีฝึกหัดมูลค่า $1,000 บวกกับผลลัพธ์ที่ปิดแล้ว โดยมีขนาดจากรายการของสัญญาณนั้นและ SL เคารพขั้นต่ำของสปอตและฟิวเจอร์ส: หากการแลกเปลี่ยนขั้นต่ำมีความเสี่ยงมากกว่า 1% การซื้อขายนั้นจะถูกข้ามไป หลังจากประมาณ −2% ในวันปฏิทิน รถยนต์ใหม่จะหยุดจนถึงวันถัดไป มากที่สุดประมาณ 3% มีความเสี่ยงจากการซื้อขายที่เปิดอยู่ Manual Trade มีขีดเดียวกัน ประวัติสัญญาณยังคงแสดงการทดสอบ $10 ที่เท่ากัน และด้านล่างคือขนาดแผน 1% สำหรับบัญชี $1,000 ดังนั้นคุณจึงสามารถเห็นทั้งสองอย่างได้"},{"h":"กำไรบางส่วนและเส้นทาง","t":"การฝึกปฏิบัติคือการออกจากเป้าหมายแรก (มักจะประมาณครึ่งหนึ่ง) และปล่อยให้ส่วนที่เหลือตามรอย เมื่อจุดหยุดขยับขึ้น เป้าหมายก็สามารถเคลื่อนที่ได้เช่นกัน ดังนั้นผู้ชนะจึงสามารถจ่ายมากกว่าเป้าหมายแรกได้ ความเสี่ยงต่อแนวคิดดั้งเดิมไม่เพิ่มขึ้น สัญญาณที่แรงไม่ใช่เหตุผลที่ต้องเสี่ยง 5% ใช้ 1% เท่ากัน เส้นทางคือสิ่งที่ช่วยให้ผู้ชนะที่แข็งแกร่งเติบโตขึ้น"},{"h":"หยุดทุกวันและเปิดความร้อน","t":"กฎที่ใช้: หากวันนั้นลดลงประมาณ 2% ของบัญชี ให้หยุดเปิดการซื้อขาย แนวคิดที่เปิดกว้างสามแนวคิด แนวคิดละ 1% มีความร้อนประมาณ 3% เหรียญห้าเหรียญที่สัมพันธ์กันเป็นเดิมพันเดียว ไม่ใช่ห้าเหรียญ นับพวกเขาด้วยกัน"},{"h":"สิ่งที่วิธีนี้ปฏิเสธ","t":"ไม่ใช้ Martingale (เพิ่มเป็นสองเท่าหลังจากแพ้) การย้ายป้ายให้ไกลออกไปเพื่อ “ให้ที่ว่าง” หลังจากที่ไม่ได้ใช้ทางเข้า ไม่ได้ใช้สัญญาณ All-in ที่ \"แน่นอน\" หากไม่มีการหยุดที่ถูกต้อง ไม่มีขนาด ดังนั้นจึงไม่มีการซื้อขาย"},{"h":"ความเสี่ยงต่อการเทรด","t":"กฎทั่วไป: เสี่ยงเพียง ~0.5–1% ของมูลค่าบัญชีในไอเดียเดียว บน DEMO ให้ฝึกนิสัยเปอร์เซ็นต์เดียวกับ LIVE"},{"h":"สูตรขนาดตำแหน่ง","t":"ขนาด µ (บัญชี × ความเสี่ยง%) ۞ (รายการ - ระยะทางหยุด) SL ที่กว้างขึ้น → ขนาดที่เล็กลง อย่าเลือกขนาดก่อนและวินาที SL"},{"h":"ความเสี่ยง : รางวัล","t":"ชอบแนวคิดที่อาจได้รับผลตอบแทน ≥ ความเสี่ยง (เช่น 1:1.5 หรือดีกว่า) เมื่อเรียนรู้ ขยายขนาดที่ TP1 เพื่อให้นักวิ่ง \"มีความเสี่ยงโดยอิสระ\""},{"h":"การทำกำไรบางส่วน","t":"รูปแบบ CPE: TP1 ล็อคกำไรบางส่วน TP2 / Trail ที่เหลือ การธนาคารบางส่วนช่วยลดความตื่นตระหนกทางอารมณ์"},{"h":"TP + SL ต่อท้าย","t":"ซื้อ: ระดับเส้นทางเพิ่มขึ้นเมื่อราคาสูงขึ้น ขาย: ตามทางลง Trailing ล็อคกำไรที่เปิดอยู่โดยไม่จำเป็นต้องมีการเรียกออกที่สมบูรณ์แบบ"},{"h":"ขีดจำกัดการสูญเสียรายวัน / รายสัปดาห์","t":"กฎตัวอย่าง: หยุดการซื้อขายในวันถัดไปหลังจากบัญชี −2% การแก้แค้นหลังจากขีดจำกัดการสูญเสียถือเป็นการทำลายบัญชี"},{"h":"การปรับขนาดเฉพาะจุด","t":"Spot min notional มีความสำคัญ (เช่น การแลกเปลี่ยน mins) ยังคงใช้ความเสี่ยง%: หากขนาดขั้นต่ำมีความเสี่ยงมากเกินไปเมื่อเทียบกับ SL ของคุณ ให้ข้ามการซื้อขาย"},{"h":"ฟิวเจอร์ส/เลเวอเรจ","t":"เลเวอเรจจะทวีคูณทั้งกำไรและขาดทุน เลเวอเรจสูง + SL กว้าง = บัญชีขาด ชอบเลเวอเรจต่ำในขณะที่เรียนรู้ แยกสามารถจำกัดการสูญเสียต่อตำแหน่งได้"},{"h":"ความสัมพันธ์","t":"การเปิด BTC alts ที่สัมพันธ์กัน 5 รายการ = หนึ่งเดิมพันใหญ่ ไม่ใช่ห้า นับความเสี่ยงเป็นกลุ่ม"},{"h":"ค่าธรรมเนียมและการเลื่อนหลุด","t":"หนังศีรษะตึงดูดีในกราฟ แต่ค่าธรรมเนียมกิน R:R ต้องการชิงช้าที่สะอาดกว่าบน DEMO จนกว่าคุณจะทราบต้นทุน"},{"h":"สาธิต → สะพานสด","t":"แบบฝึกหัด CPE DEMO (กรอบความคิดประมาณ 3 เดือน): กฎบันทึกเดียวกัน % เท่ากัน เมื่อถ่ายทอดสด ให้เริ่มขนาด DEMO ครึ่งหนึ่งในสัปดาห์แรก"},{"h":"ความปลอดภัยของเงิน API","t":"การถอนออกในทุกคีย์ ใช้งานได้หลังจากบัญชีทดสอบตกลงบนแพลตฟอร์มที่ตรงกันเท่านั้น ความลับของแพลตฟอร์มที่ไม่ถูกต้อง = การดำเนินการที่ล้มเหลวหรือเป็นอันตราย"},{"h":"ความผิดพลาด","t":"Martingale (สองเท่าหลังจากแพ้); ย้าย SL ไปให้ไกลยิ่งขึ้น ทั้งหมดในการตั้งค่า \"แน่นอน\"; ไม่สนใจขนาดขั้นต่ำเทียบกับความเสี่ยง%; ซื้อขายโดยไม่หยุดรายวัน"},{"h":"รายการตรวจสอบการปฏิบัติ","t":"1 % ความเสี่ยงที่เขียน 2 ขนาดจากระยะทาง SL 3 TP1/TP2/เส้นทางที่วางแผนไว้ ④ การสูญเสียรายวันสูงสุดที่ทราบ ⑤ กระดาษก่อน ⑥ Journal PnL โดยสุจริต"}]},{"id":"psych","title":"5 · จิตวิทยาเพื่อการซื้อขาย","summary":"Mindset จะตัดสินใจว่าทักษะ BB/RSI/Fib จะอยู่รอดในหน้าจอจริงหรือไม่ FOMO, การแก้แค้น, ความมั่นใจมากเกินไป, ความกลัว — ฝึกฝนสิ่งเหล่านี้บน DEMO เหมือนตัวชี้วัด","lessons":[{"h":"เหตุใดจิตวิทยาจึงมีความสำคัญ","t":"แผน BB+RSI ที่สมบูรณ์แบบจะล้มเหลวหากคุณเข้ามาก่อน ข้าม SL หรือแก้แค้นการค้า ทักษะ = ระบบ × วินัย"},{"h":"กระบวนการมากกว่าการคาดการณ์","t":"คุณไม่จำเป็นต้องทำนายอนาคต คุณต้องปฏิบัติตามกฎ: การตั้งค่า → ความเสี่ยง → จัดการ → บันทึกประจำวัน ผลลัพธ์จะแตกต่างกันไป สามารถควบคุมกระบวนการได้"},{"h":"โฟโม่","t":"กลัวพลาด = ไล่เทียนสีเขียวไปไกลจากโซน BB/Fib แล้ว กฎ: หากคุณพลาดรายการ ให้รอการตั้งค่าถัดไป Chart Lab มักจะมีแท่งเทียนอีกแท่งหนึ่งเสมอ"},{"h":"การซื้อขายแก้แค้น","t":"หลังจากการสูญเสีย ความปรารถนาที่จะ \"ชนะกลับคืนมาเดี๋ยวนี้\" จะทำลายบัญชี คูลดาวน์บังคับ: เดินออกไป บันทึกการขาดทุน ซื้อขายครั้งต่อไปเฉพาะในกรณีที่รายการตรวจสอบสะอาด"},{"h":"ความมั่นใจมากเกินไปหลังชัยชนะ","t":"ชนะ 3 ครั้งติดต่อกัน ≠ เพิ่มขนาด 5× ให้ % ความเสี่ยงคงที่ การชนะต่อเนื่องคือการที่คนส่วนใหญ่ฝ่าฝืนกฎเรื่องเงิน"},{"h":"ความกลัวหลังจากการสูญเสีย","t":"การข้ามการตั้งค่าที่ถูกต้องทุกครั้งหลังจากวันแดงก็ถือเป็นอคติเช่นกัน เชื่อถือแผนงานเขียน ลดขนาดชั่วคราวหากจำเป็น อย่าละทิ้งกระบวนการ"},{"h":"การวิเคราะห์อัมพาต","t":"10 ตัวชี้วัดไม่เห็นด้วย → หยุดนิ่ง ยึดติดกับแกน CPE: แท่งเทียน + BB + RSI (+ โซน Fib) คุณภาพมากกว่าปริมาณเครื่องมือ"},{"h":"เอียงและข่าว","t":"เทียนสีแดงขนาดใหญ่ทำให้อะดรีนาลีนพุ่งพล่าน ชอบที่จะแบนในช่วงที่ยังไม่ทราบหลักๆ จนกระทั่งมีการปฏิรูปโครงสร้าง - อัตตาต้องการการดำเนินการ แผนต้องการความอดทน"},{"h":"วารสาร = การบำบัด + ข้อมูล","t":"เขียนแท็กอารมณ์ (FOMO, รีบเร่ง, สงบ) ใน CPE Journal รูปแบบในความรู้สึกเผยให้เห็นรอยรั่วเร็วกว่า PnL เพียงอย่างเดียว"},{"h":"กฎเกณฑ์ที่เป็นลายลักษณ์อักษร","t":"ถ้าไม่เขียนก็ไม่ใช่กฎ ตัวอย่าง: “เฉพาะ BB+candle+RSI; ความเสี่ยง 1%; ไม่มีการซื้อขายหลังจาก −2% วัน; DEMO จนกว่าจะมีรายการตรวจสอบ 20 เอกสาร”"},{"h":"สิ่งแวดล้อม","t":"การตัดสินใจเปลี่ยนการนอนหลับ ความหิว และการเสียสมาธิทางโทรศัพท์ อย่าเพิ่มขนาดเมื่อหมดแรง การซื้อขายเป็นเรื่องกีฬา — ปกป้องสมอง"},{"h":"เสียงสังคม","t":"โทรเลข “สัญญาณ” และโฆษณาเกินจริงทำลายแผนของคุณ ชั้นเรียนการเรียนรู้ CPE + บันทึกของคุณ > เคล็ดลับแบบสุ่ม กรองข่าวและเคล็ดลับตามบริบท ไม่ใช่คำสั่งซื้อ"},{"h":"การเปลี่ยนแปลงอัตลักษณ์","t":"คิดว่า “ฉันทำตามรายการตรวจสอบของฉัน” ไม่ใช่ “ฉันจะต้องถูก” การทำผิดโดยมีความเสี่ยงเล็กน้อยเป็นเรื่องปกติ การดื้อรั้นและมีความเสี่ยงสูงเป็นทางเลือก"},{"h":"DEMO เป็นยิม","t":"ใช้ DEMO/กระดาษเพื่อซ้อมอารมณ์อย่างปลอดภัย หากคุณไม่สามารถปฏิบัติตามกฎในการสาธิตได้ LIVE จะไม่แก้ไขวินัยอย่างน่าอัศจรรย์"},{"h":"รายการตรวจสอบการปฏิบัติ","t":"① ฉันสงบแล้วหรือยัง? ② รายการตรวจสอบเสร็จสมบูรณ์แล้วหรือยัง? 3 % ความเสี่ยงไม่เปลี่ยนแปลง? ④ ไม่แก้แค้นเหรอ? ⑤ ฉันจะบันทึกอย่างตรงไปตรงมาหรือไม่? หากไม่มี → ไม่มีการซื้อขาย"}]},{"id":"signals","title":"6 · สัญญาณ CPE — ความหมายและสิ่งที่ต้องทำ","summary":"สปอต / ฟิวเจอร์ส / โต๊ะฟอเร็กซ์แสดง ซื้อ · ขาย · ถือ + คะแนน แนวคิดกลไกเดียวกันในทุกแพลตฟอร์ม — แต่คุณซื้อขายเฉพาะบนแพลตฟอร์มที่คุณบันทึกรหัส API ไว้เท่านั้น นี่คือความหมายของแต่ละสัญญาณและขั้นตอนที่แน่นอนหลังจากที่สัญญาณปรากฏขึ้น","lessons":[{"h":"สัญญาณมาจากไหน","t":"CPE ให้คะแนน BB, RSI, Fibonacci, แท่งเทียน, ข้าม EMA, SMA50, MACD และโมเมนตัม คะแนน ≥ +3 → ซื้อ คะแนน ≤ −3 → ขาย ในระหว่าง → ถือ นี่คือการให้คะแนนผู้ช่วย — ไม่ใช่คำมั่นสัญญาเรื่องผลกำไร"},{"h":"สัญญาณซื้อ — ความหมาย","t":"การบรรจบกันของภาวะกระทิงแข็งแกร่งขึ้นในขณะนี้ (ตัวอย่าง: การตีกลับของ BB ที่ลดลง, การกลับตัวของ RSI ที่ขายมากเกินไป, แท่งเทียนแบบกระทิง, เครื่องหมายกากบาทสีทอง, แนวรับ Fib) TP1 / TP2 / SL ที่แนะนำปรากฏบนแถว / Chart Lab / Trade Now"},{"h":"สัญญาณขาย — ความหมาย","t":"การบรรจบกันของภาวะหมีแข็งแกร่งขึ้น (BB บน / RSI ที่ซื้อมากเกินไป / เทียนหมี / เดธครอส / แนวต้าน Fib) ทันที ขาย มักจะหมายถึงออก/ลด long หรือ short เฉพาะในกรณีที่ตลาดของคุณอนุญาตให้ใช้ short (Futures/Forex)"},{"h":"สัญญาณ HOLD — ความหมาย","t":"คะแนนผสมหรือคะแนนอ่อน อย่าบังคับการซื้อขาย แบนถูกต้องแล้ว รายการเฝ้าดู ★ และรอความชัดเจนของการซื้อ/ขายหรือตัวเลือก BB ที่ต่ำกว่า"},{"h":"หมายเลขคะแนน","t":"สูงกว่า |คะแนน| = มีข้อตกลงระหว่างเครื่องมือมากขึ้น BUY +5 แข็งแกร่งกว่า BUY +3 — ยังคงยืนยันบน Chart Lab เทียนก่อนขนาด"},{"h":"BB กระดานล่าง","t":"แยกรายชื่อคู่ที่แท็กแถบล่างของ Bollinger — ฝึกตัวเลือก long ยังคงต้องการแท่งเทียน + RSI ยืนยัน; ไม่ใช่ทุกการสัมผัสที่ต่ำลงจะถือเป็นการเข้า"},{"h":"แพลตฟอร์มเทียบกับสัญญาณ (สำคัญ)","t":"คณิตศาสตร์สัญญาณเป็นแนวคิดเดียวกันกับ Binance, Bybit, OKX, KuCoin, Bitget, Gate, MEXC, Kraken, Coinbase, OANDA, FXCM, MT5, Forex Demo การเปลี่ยนแปลงคืออะไรที่คุณส่งคำสั่งซื้อ: เฉพาะแพลตฟอร์มที่เลือกในคีย์ API / ซื้อขายทันที Binance BUY ไม่เปิดบน Bybit"},{"h":"แพลตฟอร์ม Crypto Spot","t":"Binance Spot, Coinbase ฯลฯ: ซื้อ = ซื้อเหรียญด้วยราคาเสนอ (เช่น USDT) ขาย = ขายการถือครอง / ขายทำกำไร ขนาดขั้นต่ำ (เช่น ~$11) มีความสำคัญ ไม่มีการงัด"},{"h":"แพลตฟอร์ม Crypto Futures","t":"Binance Futures, Bybit, OKX, Bitget…: ซื้อ = ยาว; ขาย = สั้น เลือก Cross/Isolated + Leverage อย่างระมัดระวัง Trail: ซื้อ Trail TP+SL ขึ้น; ขายเส้นทางลง"},{"h":"แพลตฟอร์มฟอเร็กซ์","t":"OANDA / FXCM / MT5 / การสาธิต Forex: ป้าย BUY/SELL/HOLD เหมือนกันในคู่ FX (EURUSD…) ซื้อ = ซื้อสกุลเงินหลัก; ขาย = ฐานการขาย ล็อต (เช่น 0.01) แทนจำนวนเหรียญ เซสชันและข่าวสารมีความสำคัญมากกว่า"},{"h":"เมื่อซื้อปรากฏขึ้น — ให้ทำดังนี้","t":"1) เปิดแถว → อ่านว่าทำไม / แท่งเทียน / RSI ② แผนภูมิแล็บยืนยัน (15นาที–1ชั่วโมง) 3 สาธิตก่อน: ซื้อขายเลย → ตั้งค่า TP1/TP2/SL/trail → เริ่มสาธิต/กระดาษ ④ หลังจากการทดสอบ API ตกลงบนแพลตฟอร์มนั้นเท่านั้น → LIVE ขนาดเล็ก ⑤ ผลบันทึกประจำวัน"},{"h":"เมื่อการขายปรากฏขึ้น — ให้ทำเช่นนี้","t":"1. หากคุณเป็น long Spot: พิจารณา TP / ปิดบางส่วน / เทรล — อย่าเพิกเฉย 2 หาก Futures/Forex และแผนอนุญาตให้ short: ยืนยัน Chart Lab จากนั้น Paper/Live short ด้วย SL 3 ถ้าเมื่อวาน HOLD ดีขึ้น อย่าแก้แค้นขนาดพลิกกลับ"},{"h":"เมื่อ HOLD ปรากฏขึ้น ให้ทำดังนี้","t":"ไม่มีการป้อนข้อมูลด้วยตนเองใหม่ สแกนต่อไป เพิ่มรายการเฝ้าดู★ ศึกษาชั้นเรียนการเรียนรู้ / ห้องปฏิบัติการแผนภูมิ ปกป้องตำแหน่งที่เปิดด้วย Trail เฉพาะในกรณีที่อยู่ในการซื้อขายแล้วเท่านั้น"},{"h":"การค้าอัตโนมัติ + สัญญาณ","t":"ซื้ออัตโนมัติสามารถเปิดได้เมื่อกฎคะแนน BB ต่ำกว่า + แข็งแกร่งตรงกับการกำหนดค่าอัตโนมัติที่คุณบันทึกไว้ ยังคงสาธิตทดสอบอัตโนมัติก่อน LIVE Auto = ความเสี่ยงที่แท้จริง — การถอนเงินปิด ขนาดเล็ก"},{"h":"การแจ้งเตือน","t":"ซื้อสัญญาณปิ้งตามภาษาของคุณ ปฏิบัติต่อสิ่งเหล่านี้เสมือนเป็นการเตือนให้เปิดโต๊ะ — ไม่ใช่เป็นคำสั่งของตลาดเพียงอย่างเดียว"},{"h":"สิ่งที่ไม่ควรทำ","t":"อย่าซื้อทุกครั้งโดยไม่มีกราฟ อย่าใช้คีย์ Binance บน Bybit อย่าข้าม SL อย่าเพิ่มขนาดหลังจากสัญญาณสีเขียวครั้งเดียว อย่าซื้อขายถือโดยถือว่า “เกือบจะซื้อ”"},{"h":"การ์ดการดำเนินการด่วน","t":"สัญญาณ → แล็บแผนภูมิ → ความเสี่ยง % → TP1/TP2/SL → เอกสารสาธิต → บันทึก → (ภายหลัง) ถ่ายทอดสดบนคีย์แพลตฟอร์มที่ตรงกัน"}]},{"id":"forex_sig","title":"7 · สัญญาณ Forex — ความหมายและสิ่งที่ต้องทำ","summary":"Forex Desk ใช้เรตติ้งซื้อ / ขาย / ถือเหมือนกันในคู่ FX เรียนรู้ว่าสัญญาณฟอเร็กซ์แตกต่างจากสกุลเงินดิจิทัลอย่างไร และขั้นตอนที่แน่นอนจากสัญญาณ → กระดาษ → โบรกเกอร์สด","lessons":[{"h":"สัญญาณโต๊ะ Forex","t":"EURUSD, GBPUSD, USDJPY… รับซื้อ / ขาย / ถือ + คะแนนเหมือน crypto คลิกแถวเพื่อดูแผนภูมิ ข้อความจิตวิทยา และระดับที่แนะนำ"},{"h":"ซื้อใน Forex — ความหมาย","t":"ซื้อสกุลเงินหลัก (เช่น ซื้อ EURUSD = ซื้อ EUR เทียบกับ USD) คาดว่าราคาจะขึ้น ใช้ช่วง Chart Lab Forex ที่คุณฝึกฝน (15m/30m/1H)"},{"h":"ขายฟอเร็กซ์ — ความหมาย","t":"ขายฐาน (ชอร์ตคู่) คาดว่าราคาจะลดลง ตั้งค่า SL ไว้เหนือโครงสร้าง / แนวคิดวงบนเสมอ"},{"h":"ถือฟอเร็กซ์","t":"ไม่มีขอบที่ชัดเจน — ข้าม โดยเฉพาะก่อนข่าวใหญ่ (NFP, CPI, ธนาคารกลาง) นิยมถือ/พักตัว"},{"h":"แพลตฟอร์มอัตราการสาธิต Forex","t":"ไม่มีคีย์ API แผนภูมิฝึกหัด + กระดาษเท่านั้น เหมาะสำหรับการฝึกซ้อมในชั้นเรียนการเรียนรู้ก่อนถ่ายทอดสด OANDA/FXCM/MT5"},{"h":"สัญญาณ OANDA → การกระทำ","t":"1 โต๊ะฟอเร็กซ์ซื้อ/ขาย ② Chart Lab ยืนยัน 3 คีย์ API → โทเค็น OANDA + รหัสบัญชี → ทดสอบ ④ กระดาษสาธิตใน CPE ก่อน ⑤ ล็อตสดขนาดเล็ก (ทัศนคติ 0.01) พร้อม TP/SL/เทรล"},{"h":"FXCM / MT5","t":"การอ่านสัญญาณเดียวกัน เชื่อมต่อข้อมูลประจำตัวของโบรกเกอร์นั้นภายใต้คีย์ API Signal จะไม่เข้าสู่ระบบ MT5 ให้คุณโดยอัตโนมัติจนกว่าจะตั้งค่าคีย์/บริดจ์ — ฝึกทำกระดาษจนกระทั่งการทดสอบตกลง"},{"h":"เซสชัน","t":"การคาบเกี่ยวกันของลอนดอน–นิวยอร์กมักจะขับเคลื่อนสาขาวิชาเอกมากกว่า เอเชียอาจจะเงียบกว่า — การถือเป็นเรื่องปกติและดีต่อสุขภาพ"},{"h":"การแพร่กระจายและข่าวสาร","t":"เมื่อมีข่าว สเปรดก็กว้างขึ้น — การซื้อทางเทคนิคที่ดีก็อาจเป็นการเติมที่ไม่ดีได้ ตรวจสอบข่าวสารและเทคนิค; รอเทียนปิดหลังขัดขวาง"},{"h":"ล็อตเทียบกับจำนวน crypto","t":"ขนาดฟอเร็กซ์ = ล็อต ไม่ใช่ USDT ตามสัญญาในลักษณะเดียวกัน % ความเสี่ยงยังคงเป็นกฎ: SL ที่กว้างขึ้น → ล็อตที่เล็กลง"},{"h":"BB ลดลงใน Forex","t":"แนวคิดเดียวกัน: คู่ที่ใกล้แถบล่าง + Hammer + RSI เพิ่มขึ้น = ฝึกฝนการศึกษาระยะยาว ยืนยันอคติ TF ที่สูงขึ้น (4H/รายวัน)"},{"h":"เมื่อ Forex BUY เริ่มทำงาน — ขั้นตอน","t":"① อ่านสาเหตุ ② อคติ TF ที่สูงขึ้น ตกลงไหม? 3 ทำเครื่องหมาย SL เหนือไส้ตะเกียง/โครงสร้าง ④ การค้ากระดาษ ⑤ หากโบรกเกอร์สดพร้อม → ขนาดเล็ก + เทรล ⑥ เซสชันบันทึกประจำวัน (ลอนดอน/นิวยอร์ก) + อารมณ์"},{"h":"เมื่อ Forex SELL เริ่มทำงาน — ขั้นตอน","t":"① ยืนยันว่าไม่ใช่ช่วงกลางข่าว ② แผนภูมิแท่งเทียนขาลงของแล็บ 3 กระดาษสั้นหรือปิดยาว ④ ทางลงหากสั้น ⑤ อย่าเพิ่มล็อตเป็นสองเท่าหลังจากพลาด"},{"h":"ความแตกต่างระหว่าง Forex และ Crypto","t":"เข้ารหัสลับ 24/7; Forex มีเซสชัน Crypto ขั้นต่ำ $ บ่อยครั้ง; ล็อตฟอเร็กซ์ + มูลค่า pip Crypto หลาย alts มีความสัมพันธ์กัน วิชาเอก Forex ทำความสะอาดเพื่อการเรียนรู้"},{"h":"รายการตรวจสอบการปฏิบัติ (FX)","t":"① จับคู่วิชาเอก? ② เซสชั่นตกลงไหม? 3. ข่าวชัดเจนไหม? ④ สัญญาณซื้อ/ขายไม่ถือ? ⑤ แผนภูมิยืนยัน? ⑥ % ความเสี่ยง? ⑦ กระดาษ → วารสาร → รหัสนายหน้าสดเมื่อพร้อมเท่านั้น"}]},{"id":"fomo","title":"8 · FOMO และวินัยทางอารมณ์","summary":"FOMO การแก้แค้น ความโลภ และความกลัวเป็นตัวฆ่าบัญชีที่แท้จริง — ไม่ใช่ตัวชี้วัด เรียนรู้สิ่งกระตุ้น สัญญาณของร่างกาย และกฎที่แน่นอนที่ป้องกันการซื้อขายแบบอิมพัลส์ออกจากบัญชีของคุณ","lessons":[{"h":"FOMO คืออะไรจริงๆ","t":"FOMO = ความกลัวที่จะพลาดท่าที่อยู่ไกลจากโซนของคุณ มันทำให้คุณเข้าช้าด้วยราคาที่แย่ลงและไม่มี SL ที่เหมาะสม เทียนที่คุณ \"พลาด\" คือข้อมูล ไม่ใช่การสูญเสีย"},{"h":"ตัวกระตุ้น FOMO ทั้งสามตัว","t":"1 เทียนสีเขียวหรือสีแดงขนาดใหญ่บนแผนภูมิ 2) โพสต์ของเพื่อนหรือโทรเลขแสดงผลกำไร 3 หัวข้อข่าว สังเกตทริกเกอร์ก่อนที่คุณจะสังเกตเห็นรายการ"},{"h":"สัญญาณทางร่างกาย","t":"หัวใจเต้นเร็ว โน้มตัวลงหน้าจอ อยากคลิกตลาด-ซื้อตอนนี้ ข้ามรายการตรวจสอบของคุณ หากคุณรู้สึกเช่นนี้ ให้ปิดแท็บแล้วรอหนึ่งแท่งเทียน"},{"h":"กฎ \"ดำเนินการแล้ว\"","t":"หากราคาเคลื่อนไหวมากกว่า 1 ATR เกินกว่ารายการที่คุณวางแผนไว้ การซื้อขายจะหายไป รอการดึงกลับไปที่ BB mid / Fib หรือข้ามไป มีการตั้งค่าอื่นอยู่เสมอ"},{"h":"กับดักเทียนสีเขียว","t":"Marubozu ที่คุณไม่ได้วางแผนไว้คือการไล่ล่า ไม่ใช่การเข้ามา การเข้าช้าจะได้รับรางวัลที่เลวร้ายที่สุด: ความเสี่ยงเนื่องจากการหยุดอยู่ไกลออกไป"},{"h":"การซื้อขายแก้แค้น","t":"หลังจากที่เสียไปสมองก็อยากเอาคืนให้ได้ตอนนี้ กฎ: ห้ามเข้าใหม่เป็นเวลา 15–30 นาทีหลังจากการแพ้ และเฉพาะในกรณีที่รายการตรวจสอบสะอาดเท่านั้น ตลาดไม่ได้เป็นหนี้คุณเลย"},{"h":"กลัวเหนี่ยวไกปืน","t":"ปัญหาตรงกันข้าม: การตั้งค่าที่สมบูรณ์แบบปรากฏขึ้นและคุณค้าง ใช้ขนาด DEMO เล็กๆ เพื่อพิสูจน์กระบวนการ และตัดสินใจขนาดของคุณก่อนที่แท่งเทียนจะปรากฏ เพื่อเป็นการตัดสินใจที่ได้เกิดขึ้นแล้ว"},{"h":"ความโลภหลังชัยชนะ","t":"การซื้อขายสีเขียวสองครั้งทำให้คุณรู้สึกอยู่ยงคงกระพัน จากนั้นคุณก็เพิ่มขนาดเป็นสองเท่า รักษา % ความเสี่ยงคงที่ไว้อย่างน้อย 20 การซื้อขาย การชนะสตรีคหมายถึงการย้อนกลับ"},{"h":"การซื้อขายที่น่าเบื่อ","t":"แบนคือตำแหน่ง หากไม่มีการตั้งค่า A+ อย่าทำอะไรเกิดขึ้น การค้าขายที่น่าเบื่อนั้นเป็น FOMO ที่ซ่อนอยู่"},{"h":"วินัยในการใช้เวลาหน้าจอ","t":"ตั้งค่าหน้าต่างสแกนสองหรือสามครั้งต่อวันแทนที่จะดูแผนภูมิ การตัดสินใจน้อยลงหมายถึงการตัดสินใจที่น้อยลง"},{"h":"วารสารอารมณ์","t":"แท็กแต่ละการค้าที่สงบ / รีบเร่ง / FOMO / แก้แค้น หลังจากซื้อขายไป 20 ครั้ง รูปแบบการรั่วไหลของคุณก็จะชัดเจนขึ้น"},{"h":"รีเซ็ตพิธีกรรม","t":"หลังจากการสูญเสียหรือ FOMO หลุด: ลุกขึ้นยืน หายใจเข้าช้าๆ 10 ครั้ง เขียนหนึ่งประโยคเกี่ยวกับสิ่งที่เกิดขึ้น จากนั้นหยุดเป็นเวลาหนึ่งชั่วโมงหรือดำเนินการต่อด้วยความเสี่ยงครึ่งหนึ่งของปกติ"},{"h":"รายการตรวจสอบการปฏิบัติ","t":"① ร่างกายสงบ? ② ทริกเกอร์สังเกตเห็น? 3 ตั้งค่าในโซนของฉัน? ④ SL เขียนก่อน? ⑤ % ความเสี่ยงไม่เปลี่ยนแปลง? ⑥ ไม่แก้แค้นเหรอ? ไม่มี → ไม่มีการซื้อขาย"}]},{"id":"risk_deep","title":"9 · การจัดการความเสี่ยงและการเงิน — เจาะลึก","summary":"คณิตศาสตร์ที่ทำให้บัญชีคงอยู่: การกำหนดขนาดเศษส่วนคงที่, R-ทวีคูณ, คณิตศาสตร์แบบ Drawdown, ความร้อนของความสัมพันธ์ และการหยุดรายวัน เปลี่ยนการซื้อขายให้เป็นธุรกิจที่ดำเนินการโดยตัวเลข","lessons":[{"h":"ความเสี่ยงแบบเศษส่วนคงที่","t":"เสี่ยงต่อ % คงที่ (0.5–1%) ของทุนต่อไอเดีย ขนาดคือผลลัพธ์ของระยะหยุด ไม่เคยเลือกก่อน SL กว้าง → ขนาดเล็ก; SL แน่น → ขนาดใหญ่กว่า; ความเสี่ยงของเงินดอลลาร์ยังคงเหมือนเดิม"},{"h":"สูตรปรับขนาด","t":"ขนาด = (อิควิตี้ × ความเสี่ยง%) ÷ |รายการ − หยุด| ตัวอย่าง: $1,000 × 1% = ความเสี่ยง $10 รายการ 100 หยุด 98 → ระยะทาง 2% → ขนาด 10 ۞ 0.02 = $500 ตามสัญญา"},{"h":"คิดเป็นทวีคูณ R","t":"ความเสี่ยง 1R ต่อการซื้อขาย ผู้ชนะ 2R จ่ายค่าแพ้สองครั้ง ติดตาม R เฉลี่ยของคุณจากการเทรด 20 ครั้ง — นั่นคือความได้เปรียบที่แท้จริงของคุณ ไม่ใช่อัตราการชนะ"},{"h":"รางวัล : ความเสี่ยง","t":"ตั้งเป้าให้มีศักยภาพอย่างน้อย 1.5R ก่อนเข้า ด้านล่างนี้ ให้ข้ามไป เว้นแต่อัตราการชนะของคุณจะสูงมาก"},{"h":"คณิตศาสตร์แบบเบิกจ่าย","t":"การเบิกเงิน −50% ต้องใช้ +100% เพื่อฟื้นตัว การแพ้ต่อเนื่องเป็นเรื่องปกติ: แม้แต่ระบบอัตราการชนะ 60% ก็ยังมีการแพ้มากกว่า 5 ครั้ง ความเสี่ยงเล็กน้อยช่วยให้สตรีครอดได้"},{"h":"หยุดทุกวัน","t":"กฎยาก: หยุดเปิดการซื้อขายหลังจาก −2% ของทุนในหนึ่งวัน (หรือขาดทุน 2–3 ครั้งติดต่อกัน) เซสชันการแก้แค้นหลังจากขีดจำกัดคือนักฆ่าบัญชี"},{"h":"ขีดจำกัดรายสัปดาห์และรายเดือน","t":"ครอบคลุมสัปดาห์ (เช่น −5%) และเดือนด้วย เมื่อกดแล้ว ให้ไปที่ DEMO ตรวจสอบบันทึก จากนั้นสำรองข้อมูลขนาดหลังจาก clean run เท่านั้น"},{"h":"เปิดความร้อน","t":"ความเสี่ยงรวมในการซื้อขายที่เปิดอยู่ทั้งหมดควรอยู่ที่ประมาณ 3% หรือน้อยกว่า อัลท์ที่สัมพันธ์กันห้าอันเป็นเดิมพันเดียว ไม่ใช่ห้า — นับความเสี่ยงที่สัมพันธ์กันด้วยกัน"},{"h":"การปรับขนาดเฉพาะจุด","t":"Spot มีการกำหนดขั้นต่ำ หากการแลกเปลี่ยนขั้นต่ำมีความเสี่ยงมากกว่า 1% ของคุณ ให้ข้ามการซื้อขาย — อย่าปัดเศษความเสี่ยงขึ้น"},{"h":"ขนาดฟิวเจอร์ส","t":"เลเวอเรจเปลี่ยนมาร์จิ้น ไม่ใช่ความเสี่ยง ความเสี่ยงยังคงเป็นรายการ - หยุด × ขนาด ใช้เลเวอเรจต่ำในขณะที่เรียนรู้และชอบมาร์จิ้นแบบแยก"},{"h":"ขนาดฟอเร็กซ์","t":"ความเสี่ยง = ล็อต × ค่า pip × จุดหยุด แก้ได้มากมาย.. คำแนะนำคร่าวๆ: 0.01 ล็อต อยู่ที่ 0.10 ดอลลาร์ต่อ pip; หยุด 20 pip เสี่ยง 1% ของ $1,000 ($10) → 10 ۞ 0.10 ۞ 20 = 0.05 ล็อต"},{"h":"ขยายขนาดออก","t":"รับส่วนลดประมาณ 50% ที่ TP1 เพื่อให้ส่วนที่เหลือปราศจากความเสี่ยง แล้วค่อยออกเดินทาง สิ่งนี้จะเปลี่ยนการค้าขายที่ดีให้กลายเป็นนักวิ่งที่มีความเครียดต่ำ"},{"h":"ทบต้นกับคงที่","t":"เสี่ยงเป็น % คงที่ของส่วนของผู้ถือหุ้นปัจจุบัน (ทบต้น) อย่าแก้ไขความเสี่ยงของคุณที่ขนาดบัญชีที่สูงเป็นประวัติการณ์"},{"h":"ค่าธรรมเนียมและการเลื่อนหลุดในหน่วย R","t":"ลบค่าธรรมเนียมออกจาก R ค่าธรรมเนียม 0.2% ต่อหนังศีรษะ 0.5% สามารถเช็ดขอบได้ — ชอบชิงช้าที่สะอาดกว่า"},{"h":"กฎหมาย “ไม่หยุด ไม่มีการค้า”","t":"หากคุณไม่สามารถกำหนดจุดหยุดเชิงตรรกะได้ แสดงว่าคุณไม่ทราบความเสี่ยงของตัวเอง ดังนั้นจึงไม่มีขนาด ดังนั้นจึงไม่มีการซื้อขาย"},{"h":"ต่อต้าน Martingale","t":"อย่าเพิ่มเป็นสองเท่าหลังจากการสูญเสีย เพิ่มขนาดหลังจากหลายสัปดาห์ที่มีผลกำไรและมีระเบียบวินัยของกระบวนการที่ได้รับการพิสูจน์แล้วเท่านั้น และแม้แต่อย่างช้าๆ"},{"h":"รายการตรวจสอบการปฏิบัติ","t":"1 ทราบมูลค่าหุ้น 2 % ความเสี่ยงที่เขียน 3 จุดหยุดที่กำหนด ④ ขนาดจากจุดหยุด ⑤ รางวัล ≥ 1.5R ⑥ ทราบจุดหยุดรายวัน ⑦ นับความร้อนที่สัมพันธ์กัน"}]},{"id":"sl_tp","title":"10 · ความเชี่ยวชาญในการหยุดการขาดทุนและทำกำไร","summary":"วาง SL ในที่ที่ตลาดพิสูจน์ว่าคุณผิด ทำกำไรเป็นขั้นๆ และตามจุดหยุดเพื่อให้ผู้ชนะสามารถวิ่งได้ — เหมือนกับที่ CPE ทำกับ multi-TP และ Trailing SL","lessons":[{"h":"SL คือการตัดสินใจ ไม่ใช่ตัวเลข","t":"วางจุดหยุดที่แนวคิดไม่ถูกต้อง (ต่ำกว่าจุดแกว่งต่ำ ไส้ตะเกียง หรือโครงสร้าง) ไม่ใช่ที่ระยะดอลลาร์แบบสุ่ม คุณกำลังซื้อข้อมูล: หากราคาอยู่ที่นี่ แสดงว่าเหตุผลของฉันผิด"},{"h":"โครงสร้างหยุดลง","t":"ยาว: SL อยู่ต่ำกว่าไส้เทียนวงสวิงต่ำหรือแถบล่าง สั้น: อยู่เหนือจุดสวิงสูง ให้บัฟเฟอร์เล็กน้อยสำหรับการแพร่กระจายและเสียงรบกวนของไส้ตะเกียง ประมาณ 0.1–0.3%"},{"h":"ความผันผวนหยุดลง","t":"ตลาดที่กว้างขึ้นจำเป็นต้องหยุดให้กว้างขึ้น ใช้ ATR หรือความยาวไส้ตะเกียงเพื่อปรับขนาดจุดหยุด จากนั้นย่อตำแหน่งเพื่อให้ความเสี่ยงต่อดอลลาร์คงเดิม"},{"h":"เหตุใด SL แบบคงที่จึงล้มเหลว","t":"การหยุด BTC มูลค่า 10 ดอลลาร์และการหยุด BTC มูลค่า 10 ดอลลาร์สำหรับ EURUSD ถือเป็นความเสี่ยงที่แตกต่างอย่างสิ้นเชิง ระยะทางต้องวัดเป็น % ไม่ใช่ดอลลาร์"},{"h":"บัฟเฟอร์ต่อต้านการหยุดล่า","t":"CPE ละเว้นการสัมผัสไส้ตะเกียงเพียงครั้งเดียว: มันต้องมีการละเมิดสองครั้งติดต่อกันบวกกับบัฟเฟอร์ขนาดเล็ก (0.15%) ก่อนที่จะปิด ที่หยุดเสียงรบกวนจากการตามล่าหยุดของคุณ"},{"h":"ทำกำไรเป็นขั้นตอน","t":"ไม่เคยปิด 100% ในราคาเดียว ขยายขนาด: ส่วนของหนังสือ TP1 จากนั้น TP2 / ขี่เทรลส่วนที่เหลือ เพื่อให้การเคลื่อนไหวครั้งใหญ่สามารถจ่ายให้กับผู้แพ้จำนวนมาก"},{"h":"หลายระดับ TP","t":"CPE ให้คุณเพิ่มระดับ TP ได้มากเท่าที่คุณต้องการ โดยแต่ละระดับมี % ปิดของตัวเอง ตัวอย่าง: TP1 40%, TP2 30%, TP3 30% — หรือใช้ TP1 และติดตามส่วนที่เหลือ"},{"h":"กำลังตามป้ายหยุด","t":"หลังจาก TP1 เลื่อนจุดหยุดไปที่จุดคุ้มทุน หลังจาก TP2 ให้ย้ายไปที่ TP1 ปล่อยให้ราคาหยุดตามเพื่อให้กำไรที่เปิดอยู่ได้รับการปกป้องในขณะที่นักวิ่งยังคงดำเนินต่อไป"},{"h":"การเลือกเส้นทาง %","t":"เส้นทางที่แคบจะล็อคกำไรอย่างรวดเร็วแต่ออกก่อน เส้นทางอันกว้างใหญ่ยังหายใจแต่ก็ตอบแทนกลับมาบ้าง เริ่มต้นประมาณ 1–2% สำหรับ crypto และปรับแต่งใน Modal แก้ไขตำแหน่ง"},{"h":"นักวิ่ง","t":"เมื่อราคาเดินตามวงในแนวโน้มที่แข็งแกร่ง ให้ขยายเป้าหมายและเส้นทางให้กว้างขึ้น แทนที่จะยึดทุกอย่างที่ TP2 นั่นคือวิธีที่การซื้อขายหนึ่งครั้งจ่ายตลอดทั้งสัปดาห์"},{"h":"ปุ่มปิดบางส่วน","t":"ใช้ปุ่มปิด 50% / 100% ในตำแหน่งสำหรับการควบคุมด้วยตนเอง หรือปล่อยให้ปิดอัตโนมัติจัดการ TP / SL ตามแผน"},{"h":"กับดักคุ้มทุน","t":"อย่าขยับ SL ให้ถึงจุดคุ้มทุนเร็วเกินไป ก่อนที่ TP1 การดึงกลับตามปกติจะทำให้คุณออกจากการซื้อขายที่ดี"},{"h":"ไม่เคยขยายจุดหยุดขาดทุน","t":"การย้าย SL ออกไปเพื่อให้มีที่ว่างจะทำให้การสูญเสียเพียงเล็กน้อยกลายเป็นนักฆ่าบัญชี จุดจอดที่คุณตั้งไว้ก่อนเข้าคือจุดจอด"},{"h":"หยุดเวลา","t":"หากการซื้อขายไม่ได้ช่วยอะไรกับแท่งเทียนจำนวนมากในขณะที่มีรูปแบบการตั้งค่าที่ดีกว่าอย่างชัดเจน การปิดตลาดแบบคงที่และปรับใช้ความเสี่ยงอีกครั้งถือเป็นทางออกที่ถูกต้อง"},{"h":"รายการตรวจสอบการปฏิบัติ","t":"1 SL เมื่อใช้งานไม่ได้ ไม่ใช่การสุ่ม 2 บัฟเฟอร์สำหรับไส้ตะเกียง 3 TP1 วางแผนไว้บางส่วน ④ เทรลหลังจาก TP1 ⑤ อย่าขยาย SL ⑥ ปล่อยให้ผู้ชนะวิ่งไป"}]},{"id":"plan_journal","title":"11 · แผนการค้าและการจดบันทึก","summary":"แผนงานที่เป็นลายลักษณ์อักษรเปลี่ยนการซื้อขายจากการพนันให้เป็นกระบวนการ เรียนรู้แผนหน้าเดียว รายการตรวจสอบก่อนการซื้อขาย และวิธีการบันทึกเพื่อให้มองเห็นรอยรั่วของคุณ","lessons":[{"h":"ทำไมต้องเขียนแผน.","t":"ถ้าไม่เขียนก็ไม่ใช่กฎเกณฑ์ แผนจะช่วยขจัดการตัดสินใจที่เกิดขึ้นจริงภายใต้ความเครียดและทำให้ผลลัพธ์ของคุณสามารถวัดผลได้"},{"h":"แผนหน้าเดียว","t":"คู่, ตลาด, การตั้งค่า (BB + RSI + เทียน + โซน Fib), ทิศทาง, รายการ, SL, TP1 / TP2, ขนาด (จาก SL) และการสูญเสียรายวันสูงสุด หากบรรทัดใดว่าง → ไม่มีการซื้อขาย"},{"h":"รายการตรวจสอบก่อนการซื้อขาย","t":"อคติ TF ที่สูงขึ้น? · ตั้งค่าในโซนของฉัน? · เทียนยืนยัน? · RSI เห็นด้วยไหม? · SL เขียน? · เสี่ยง %? · รางวัล ≥ 1.5R? · เงียบสงบ? ใช่ทั้งหมด → ซื้อขาย"},{"h":"กิจวัตรก่อนเซสชั่น","t":"ตรวจสอบกรอบเวลาที่สูงขึ้น ระดับสำคัญ และข่าวสาร เขียนคู่นาฬิกาสองหรือสามคู่ของวันนี้ก่อนเซสชัน ไม่ใช่หลังจากเทียนระเบิด"},{"h":"สิ่งที่จะบันทึก","t":"สัญลักษณ์ ด้านข้าง การเข้า ออก ขนาด R เหตุผล กรอบเวลา เซสชั่น และแท็กอารมณ์ CPE Journal บันทึก P/L และเหตุผลโดยอัตโนมัติ เพิ่มบันทึกย่อของคุณเอง"},{"h":"บันทึกทำไม","t":"บันทึกสิ่งที่คุณเห็น (ตั้งค่า) และสิ่งที่คุณรู้สึก (สงบ / FOMO / รีบเร่ง) ผลลัพธ์ที่ไม่มีบริบทไม่ได้สอนอะไรเลย"},{"h":"แทร็ก R ไม่ชนะ","t":"เทรดเดอร์สองคนที่มีอัตราการชนะเท่ากันสามารถให้ผลลัพธ์ที่ตรงกันข้ามได้ ค่า R เฉลี่ยและการขาดทุนสูงสุดมีความสำคัญมากกว่าเปอร์เซ็นต์การชนะ"},{"h":"นิสัยการแคปหน้าจอ","t":"บันทึกแผนภูมิก่อนและหลังการซื้อขายแต่ละครั้ง การตรวจสอบภาพหน้าจอ 20 ภาพ แสดงให้เห็นความได้เปรียบและการรั่วไหลของคุณเร็วกว่าตัวบ่งชี้ใดๆ"},{"h":"รีวิวประจำสัปดาห์","t":"สัปดาห์ละครั้งนับการซื้อขายของคุณ R เฉลี่ย การตั้งค่าที่ดีที่สุดและแย่ที่สุด และการละเมิดกฎ เลือกการรั่วไหลหนึ่งรายการเพื่อแก้ไขในสัปดาห์หน้า"},{"h":"แท็กการรั่วไหล","t":"แท็กทั่วไป: การเข้าช้า, ไม่มี SL, ขนาดใหญ่, ย้าย SL, การแก้แค้น, ความเบื่อหน่าย เมื่อแท็กซ้ำ ให้เปลี่ยนให้เป็นกฎตายตัว"},{"h":"สิ่งที่ไม่ควรบันทึก","t":"อย่าบันทึกเฉพาะผู้ชนะเท่านั้น การสูญเสียคือข้อมูล บันทึกที่มีแต่ชัยชนะเท่านั้นที่เป็นโบรชัวร์ ไม่ใช่บันทึกประจำวัน"},{"h":"วางแผนขั้นตอนการสาธิต → ถ่ายทอดสด","t":"พิสูจน์แผนบน DEMO สำหรับจำนวนการซื้อขายที่กำหนดด้วย R เฉลี่ยที่เป็นบวก ก่อนที่จะเสี่ยงด้วยเงินจริง - จากนั้นเริ่มต้นที่ขนาดครึ่งหนึ่ง"},{"h":"รายการตรวจสอบการปฏิบัติ","t":"1 แผนเขียนก่อนเข้า 2 รายการตรวจสอบผ่าน 3 รายการบันทึก + อารมณ์ ④ ทบทวนรายสัปดาห์ ⑤ แก้ไขรอยรั่ว 1 รายการ"}]},{"id":"leverage","title":"12 · เลเวอเรจ มาร์จิ้น และการชำระบัญชี","summary":"เลเวอเรจจะทวีคูณการสูญเสียอย่างรวดเร็วเท่ากับกำไร เรียนรู้เรื่องมาร์จิ้น การชำระบัญชี มาร์จิ้นแยกเทียบกับครอสมาร์จิ้น และกฎความปลอดภัยที่หยุดการซื้อขายหนึ่งรายการจากการล้างข้อมูลบัญชี","lessons":[{"h":"เลเวอเรจคืออะไร","t":"เลเวอเรจช่วยให้คุณควบคุมตำแหน่งที่ใหญ่ขึ้นโดยมีมาร์จิ้นน้อยลง มันเพิ่มทั้งกำไรและขาดทุน — มันไม่ได้เพิ่มความได้เปรียบของคุณ"},{"h":"มาร์จิ้นเทียบกับความเสี่ยง","t":"มาร์จิ้นคือเงินฝากที่ล็อคการแลกเปลี่ยน ความเสี่ยงคือการเข้า - หยุด × ขนาด เลเวอเรจจะเปลี่ยนแปลงมาร์จิ้น ไม่ต้องเสี่ยงกับเงินดอลลาร์ของคุณ"},{"h":"การชำระบัญชี","t":"หากการขาดทุนกินมาร์จิ้นของคุณ แรงแลกเปลี่ยนจะปิดสถานะ (การชำระบัญชี) ซึ่งมักจะเป็นเวลาที่เลวร้ายที่สุด หยุดการหยุดของคุณให้ห่างจากราคาการชำระบัญชี"},{"h":"แยกกับครอส","t":"การแยกส่วนจะจำกัดการสูญเสียให้กับมาร์จิ้นของสถานะนั้น Cross ใช้ยอดคงเหลือในกระเป๋าสตางค์ทั้งหมด — อันตรายมากขึ้นสำหรับผู้เริ่มต้น ชอบแยกตัวในขณะที่เรียนรู้"},{"h":"เลเวอเรจที่ปลอดภัยยิ่งขึ้น","t":"เลเวอเรจต่ำ (2–5x) บวกกับการหยุดที่เหมาะสมจะปลอดภัยกว่า 50x โดยไม่มีการหยุด การหยุดไม่ใช่หมายเลขเลเวอเรจคือการปกป้องของคุณ"},{"h":"กฎการชำระบัญชี-ระยะทาง","t":"ตรวจสอบว่า SL ของคุณอยู่ในราคาการชำระบัญชีได้ดี หากอยู่ใกล้ให้ลดขนาดลงจนกว่าจะมีเนื้อที่ที่สะดวกสบาย"},{"h":"เลเวอเรจไม่สามารถแก้ไขรายการที่ไม่ดีได้","t":"เลเวอเรจสูงจากการเข้าที่ไม่ดีจะสูญเสียเร็วขึ้น แก้ไขการตั้งค่าก่อน จากนั้นจึงปรับขนาด"},{"h":"เงินทุนและค่าธรรมเนียม","t":"ฟิวเจอร์สถาวรจะเรียกเก็บเงินตามระยะเวลา การถือครองเงินทุนที่มีเลเวอเรจเป็นเวลานาน - อีกเหตุผลหนึ่งที่ต้องคำนึงถึงขนาดและเวลาอย่างระมัดระวัง"},{"h":"สปอตเทียบกับฟิวเจอร์ส","t":"Spot ไม่สามารถชำระบัญชีได้ (คุณเป็นเจ้าของเหรียญ) ฟิวเจอร์สสามารถและสามารถไปที่ศูนย์ได้ ใช้ฟิวเจอร์สเฉพาะกับแผนการเป็นลายลักษณ์อักษรและส่วนต่างที่แยกออกมา"},{"h":"การปรับขนาดภายใต้การงัด","t":"คำนวณขนาดจากระยะหยุด จากนั้นตรวจสอบว่าระยะขอบที่ได้มีราคาไม่แพง อย่าเลือกเลเวอเรจก่อน"},{"h":"การทดสอบ \"หนึ่งการซื้อขาย\"","t":"ก่อนเข้าถาม: สิ่งนี้ถึงจุดหยุด มันเป็นยักไหล่หรือหายนะ? ถ้าไม่ยักแสดงว่าไซส์ใหญ่เกินไป"},{"h":"รายการตรวจสอบการปฏิบัติ","t":"1 ชุดแยก 2 เลเวอเรจต่ำ 3 SL ภายในราคาการชำระบัญชี ④ ขนาดจากจุดหยุด ⑤ ฉันสามารถรอดจากการสูญเสียทั้งหมดได้ที่นี่หรือไม่? ใช่ → ซื้อขาย"}]},{"id":"practice","title":"13 · กิจวัตรการฝึกฝนและการทดสอบย้อนหลัง","summary":"ทักษะถูกสร้างขึ้นบน DEMO ก่อนการถ่ายทอดสด เรียนรู้แนวทางปฏิบัติที่ทำซ้ำได้ วิธี “ทดสอบย้อนหลัง” โดยการเลื่อนแผนภูมิ และวิธีการเปลี่ยนเป็นเงินจริงอย่างปลอดภัย","lessons":[{"h":"DEMO คือห้องออกกำลังกาย","t":"Paper / DEMO มีไว้เพื่อซ้อมกระบวนการและอารมณ์ของคุณโดยไม่มีความเสี่ยง หากคุณไม่สามารถปฏิบัติตามกฎบน DEMO ได้ LIVE จะไม่แก้ไขอย่างน่าอัศจรรย์"},{"h":"วงการปฏิบัติ","t":"เลือกการตั้งค่าหนึ่งรายการ (เช่น BB ล่าง + ค้อน + การหมุน RSI) ทำเครื่องหมายตัวอย่างทางประวัติศาสตร์ 20 ตัวอย่างบนแผนภูมิ กำหนดรายการ / SL / TP บันทึกผลลัพธ์ ทำซ้ำ."},{"h":"การทดสอบย้อนกลับด้วยตนเอง","t":"เลื่อนย้อนกลับไปใน Chart Lab ซ่อนอนาคต และทำเครื่องหมายแต่ละสัญญาณด้วยมือ มันฝึกการจดจำรูปแบบและหยุดคุณหลอกตัวเอง"},{"h":"ขนาดตัวอย่าง","t":"การซื้อขายสิบครั้งไม่มีความหมายอะไรเลย ตั้งเป้าการซื้อขายที่บันทึกไว้ 30–50 รายการในการตั้งค่าเดียวก่อนที่จะตัดสิน"},{"h":"ทดสอบส่งต่อบน DEMO","t":"หลังจากการทำเครื่องหมายด้วยมือ ให้ดำเนินการตั้งค่าเดียวกันแบบสดบน DEMO พร้อมสัญญาณของซอฟต์แวร์เป็นเวลาสองถึงสี่สัปดาห์ เปรียบเทียบการเติมเต็มและอารมณ์ที่แท้จริงกับการทดสอบย้อนหลัง"},{"h":"ตั้งค่าครั้งละหนึ่งรายการ","t":"อย่าทดสอบห้าระบบพร้อมกัน เชี่ยวชาญด้านหนึ่งแล้วเพิ่มอีกหนึ่งวินาที"},{"h":"รักษากิจวัตรให้เล็กลง","t":"กิจวัตรประจำวัน 20 นาที (สแกน ทำเครื่องหมาย บันทึก ทบทวน) ดีกว่าการจ้องมองแผนภูมิแบบสุ่มเป็นเวลาหกชั่วโมง"},{"h":"สำเร็จการศึกษาเพื่อ LIVE","t":"เกณฑ์: ค่าเฉลี่ยเชิงบวก R มากกว่า 30+ การซื้อขาย DEMO ปฏิบัติตามกฎ ไม่มีตอนแก้แค้น จากนั้นเริ่ม LIVE ที่ขนาดครึ่งหนึ่งและปรับขนาดอย่างช้าๆ"},{"h":"กฎการขยายขนาด","t":"เพิ่มขนาดหลังจากจำนวนสัปดาห์ที่ทำกำไรและมีระเบียบวินัยตามที่กำหนดเท่านั้น ไม่เคยได้รับชัยชนะครั้งใหญ่เพียงครั้งเดียว"},{"h":"เมื่อไหร่จะถอยหลัง.","t":"ถึงขีดจำกัดการสูญเสียรายวันหรือรายสัปดาห์ หรือสังเกตเห็นการละเมิดกฎซ้ำๆ → กลับไปที่ DEMO และสร้างระเบียบวินัยใหม่ก่อนดำเนินการต่อ"},{"h":"ติดตามตัวชี้วัดกระบวนการ","t":"อัตราการผ่านรายการตรวจสอบ บันทึกการฝ่าฝืนกฎต่อสัปดาห์ และ R เฉลี่ย สิ่งเหล่านี้คาดการณ์การเติบโตได้ดีกว่าตัวเลข P/L เดียว"},{"h":"เส้นทางการฝึก CPE","t":"ชั้นเรียนการเรียนรู้ → แล็บแผนภูมิ (การตั้งค่าเครื่องหมาย) → การค้ากระดาษ → การตรวจสอบวารสาร → โต๊ะสัญญาณบน DEMO → LIVE ขนาดเล็กบนคีย์แพลตฟอร์มที่ตรงกัน"},{"h":"รายการตรวจสอบการปฏิบัติ","t":"1 การตั้งค่าที่เลือก 2 ตัวอย่าง 30 ตัวอย่าง 3 การทดสอบการส่งต่อ DEMO ④ วารสาร + บทวิจารณ์ ⑤ Positive R → ครึ่งขนาด LIVE"}]},{"id":"volatility","title":"14 · ความผันผวนและการทบทุน","summary":"วิธีอ่านความผันผวนของตลาด (เหตุใดราคาจึงเปลี่ยนแปลง) วิธีเพิ่มเส้นเหตุผลลงในสัญญาณทุกสัญญาณ และวิธีการทำงานของบันได Martingale ที่เป็นตัวเลือก รวมถึงเหตุใดจึงเป็นวิธีที่เร็วที่สุดในการสูญเสียบัญชีเมื่อใช้อย่างไม่ระมัดระวัง","lessons":[{"h":"ความผันผวนหมายถึงอะไร","t":"ความผันผวนคือราคาที่เคลื่อนไหวไปมากน้อยเพียงใด ไม่ใช่ทิศทางใด ความผันผวนสูง = แท่งเทียนกว้างและการแกว่งที่รวดเร็ว ความผันผวนต่ำ = ช่วงที่เงียบและแคบ การตั้งค่าเดียวกันมีความน่าเชื่อถือที่แตกต่างกันมากในแต่ละรายการ"},{"h":"การอ่านค่าความผันผวนของ CPE","t":"ตอนนี้แต่ละสัญญาณจะวัดช่วงแท่งเทียนเฉลี่ยและความกว้างของโบลินเจอร์ แบนด์ จากนั้นจึงเปรียบเทียบกับค่าปกติล่าสุดของคู่นั้น คุณจะได้รับ LOW / NORMAL / HIGH / EXTREME บวกกับบรรทัดเหตุผลในภาษาธรรมดา — “ทำไม” สำหรับการเปลี่ยนแปลงตลาด ซึ่งแสดงพร้อมสัญญาณ"},{"h":"ความผันผวนอย่างมาก = ปรับลดรุ่น","t":"เมื่อเทปอยู่ในสถานะ EXTREME สัญญาณ Strong ใหม่จะถูกลดระดับลงเป็น CAUTION (สาเหตุแสดงอยู่) ในตลาดแส้ รูปแบบเดียวกันนี้จะล้มเหลวบ่อยกว่ามาก — ไส้เทียนปลอมและไส้เทียนหยุดล่าถือเป็นเรื่องปกติ"},{"h":"สิ่งที่ต้องทำใน HIGH / EXTREME","t":"ขนาดที่เล็กลง หยุดที่กว้างขึ้น การซื้อขายน้อยลง รอแท่งเทียนที่เสร็จสมบูรณ์แทนที่จะเป็นแท่งเทียนที่อยู่ตรงกลาง หากข้อความที่อ่านว่า EXTREME ให้ถือว่าสถานที่นี้เป็นโซนศึกษา ไม่ใช่ทางเข้า"},{"h":"มาร์ติงเกลคืออะไร","t":"Martingale เพิ่มตำแหน่งที่สูญเสียเพื่อลดการเข้าโดยเฉลี่ย: หลังจากการเคลื่อนไหวที่ไม่พึงประสงค์แต่ละครั้ง คุณจะเพิ่มคำสั่งอื่น ซึ่งมักจะใหญ่กว่า (1x, 2x, 4x …) ชนะบ่อยแล้วแพ้ทุกอย่างในการวิ่งที่แย่เพียงครั้งเดียว"},{"h":"กฎ CPE Martingale","t":"CPE จะเพิ่มคำสั่งพิเศษเมื่อทั้งสองเป็นจริงเท่านั้น: (1) ราคาเคลื่อนไหวต้านการซื้อขายอย่างน้อยขั้น × รุ่ง % และ (2) สัญญาณฝั่งเดียวกันใหม่ยังคงอยู่สำหรับคู่นั้น มันไม่เคยเพิ่มเพียงเพราะราคาลดลง"},{"h":"ตัวเลขสี่ตัว","t":"ขั้นตอน % = ต้องมีการเคลื่อนไหวที่ไม่พึงประสงค์ก่อนที่จะเพิ่มแต่ละครั้ง ตัวคูณ = ขนาดของแต่ละบวกเทียบกับฐาน (1 = แบน, 2 = สองเท่า) เพิ่มสูงสุด = ขีดจำกัดสูงสุดสำหรับคำสั่งซื้อพิเศษ ความเสี่ยงสูงสุดของบันได % = ความเสี่ยงของบันไดทั้งหมดคิดเป็น % ของส่วนของผู้ถือหุ้น ทั้งสี่เป็นของคุณที่จะเลือก"},{"h":"หมวกแข็งช่วยปกป้องคุณ","t":"แม้ว่าจะมีตัวคูณจำนวนมากและการเพิ่มจำนวนมาก CPE จะปฏิเสธคำสั่งเมื่อความเสี่ยงรวมของบันไดจะผ่าน % ทุนสูงสุดของคุณ นอกจากนี้ยังคำนึงถึงขนาดการแลกเปลี่ยนขั้นต่ำและการหยุดรายวัน −2%"},{"h":"มันวิ่งไปไหน.","t":"ทำเครื่องหมายที่ Manual เพื่อจัดการการซื้อขายหนึ่งรายการ หรือในเซสชันอัตโนมัติเพื่อจัดการการซื้อขายอัตโนมัติ ทั้งสาธิตและสด ในโหมดแมนนวล คู่จะต้องอยู่ในรายการสแกน เพื่อให้สามารถอ่านสัญญาณด้านเดียวกันใหม่ได้"},{"h":"เหตุใดหมวกจึงมีความสำคัญ (ตัวอย่าง)","t":"ขั้นตอนที่ 1% ตัวคูณ 2 สามบวกบนฐานความเสี่ยง 1%: ความเสี่ยงไป 1% → 2% → 4% → 8% การหยุดการหยุดชั่วคราวหนึ่งครั้งในขั้นสุดท้ายจะลบผู้ชนะจำนวนมาก นั่นคือสาเหตุว่าทำไมถึงมีขีดจำกัดและเหตุใดตัวเลขเริ่มต้นจึงน้อย"},{"h":"ทางเลือกต่อต้าน Martingale","t":"ข้อดีหลายๆ คนทำตรงกันข้าม: เพิ่มเฉพาะผู้ชนะและตัดผู้แพ้อย่างรวดเร็ว รู้สึกแย่ลง (ขาดทุนเล็กน้อยมากขึ้น) แต่ไม่สามารถระเบิดบัญชีในแนวโน้มเดียวที่ขัดแย้งกับคุณได้"},{"h":"ความเสี่ยงจะไม่ถูกลบออก","t":"การเฉลี่ยลงไม่ได้ช่วยขจัดความเสี่ยง — เป็นการเปลี่ยนความเสี่ยงจาก “การสูญเสียเล็กๆ น้อยๆ จำนวนมาก” ไปเป็น “การสูญเสียครั้งใหญ่เพียงครั้งเดียว” อย่าเพิ่มเงินที่คุณไม่สามารถสูญเสียได้ และอย่าปิดขีดจำกัดเพื่อ \"กู้คืน\" การซื้อขายที่สูญเสีย"},{"h":"เส้นทางปฏิบัติ","t":"เรียนรู้การอ่านค่าความผันผวนบน DEMO ก่อน ลองใช้ Martingale โดยเพิ่มสูงสุด 1–2 และตัวคูณเล็กน้อยบน DEMO สำหรับการเทรดมากกว่า 30 ครั้ง บันทึกทุกบันไดแล้วตัดสินใจ — เทรดเดอร์ส่วนใหญ่พบว่าวิธีแบบคงที่ / ต่อต้านมาร์ติงเกลปลอดภัยกว่า"},{"h":"รายการตรวจสอบความผันผวน + Martingale","t":"1 อ่านระดับความผันผวนก่อน 2 ข้ามหรือย่อขนาดใน EXTREME 3 ทบทุนเท่านั้นที่มีสัญญาณฝั่งเดียวกันใหม่ ④ ขั้นตอน × รุ่งถึง ⑤ ใต้ขีดจำกัดความเสี่ยง → เพิ่ม “ไม่” ใดๆ → ไม่มีการเพิ่ม"}]},{"id":"lab_indicators","title":"15 · ตัวบ่งชี้ห้องปฏิบัติการแผนภูมิ (Stoch · ADX · Ichimoku · VWAP)","summary":"ขณะนี้ Chart Lab มีแถบตัวบ่งชี้เต็มรูปแบบ — ทุกปุ่มจะเป็นเครื่องหมายเปิด/ปิดที่จะวาดแผนภูมิใหม่ทันที นอกจาก BB / RSI / MACD / EMA / SMA50 / Volume แล้ว คุณยังได้รับ Stochastic, ADX/DMI, Ichimoku และ VWAP และกลไกสัญญาณจะอ่านด้วยเช่นกัน ไม่ใช่แค่แผนภูมิ","lessons":[{"h":"บาร์อยู่ที่ไหน","t":"Chart Lab → แถวของปุ่ม “Indicators” ใต้แผนภูมิ คลิกเพียงครั้งเดียวเพื่อเปิดตัวบ่งชี้ คลิกถัดไปจะปิดตัวบ่งชี้ แผนภูมิจะวาดใหม่ทันที เห็บนั้นมองเห็นได้และป้อนสัญญาณให้กับเครื่องยนต์"},{"h":"สุ่ม (14,3,3)","t":"%K / %D ออสซิลเลเตอร์วาดอยู่ใต้แท่งเทียน สเกล 0–100 สูงกว่า ~80 = โซนซื้อมากเกินไป, ต่ำกว่า ~20 = โซนขายมากเกินไป %K ที่ตัดผ่าน %D ในโซนขายมากเกินไปถือเป็นการศึกษาภาวะกระทิง กากบาทที่ด้านบนนั้นเป็นภาวะหมี ในแนวโน้มที่แข็งแกร่ง มันสามารถตรึงไว้ที่ปลายด้านหนึ่งเป็นเวลานาน — รวมกับ BB และแท่งเทียนเสมอ"},{"h":"ADX / DMI (14)","t":"ADX วัดแนวโน้ม STRENGTH ไม่ใช่ทิศทาง สูงกว่า ~25 = แนวโน้มที่แท้จริงกำลังดำเนินอยู่ ต่ำกว่า ~20 = ช่วงที่เปลี่ยนแปลงเร็ว +DI เหนือ −DI = ผู้ซื้อรับผิดชอบ; −DI เหนือ +DI = ผู้ขายที่รับผิดชอบ ใช้ ADX เพื่อตัดสินใจว่าจะเทรดตามเทรนด์เลยหรือทรงตัว"},{"h":"อิจิโมกุ คลาวด์ (9,26,52)","t":"Tenkan (สายด่วน), Kijun (สายช้า) และเมฆ Senkou ราคาเหนือเมฆที่เพิ่มขึ้น = พื้นหลังเป็นกระทิง; ใต้เมฆที่ตกลงมา = ภาวะหมี การข้าม Tenkan/Kijun ภายในก้อนเมฆนั้นอ่อนแอ การข้ามที่มีราคาออกจากคลาวด์นั้นแข็งแกร่งกว่า ขอบเมฆมักจะทำหน้าที่เป็นแนวรับ / แนวต้าน"},{"h":"วีเอพี","t":"ราคาเฉลี่ยถ่วงน้ำหนักตามปริมาณ — ราคาเฉลี่ยถ่วงน้ำหนักตามปริมาณ รีเซ็ตแต่ละเซสชัน สถาบันใหญ่ๆ ต่างก็วัดผลการเติมเต็มของพวกเขา ราคาที่สูงกว่า VWAP ที่เพิ่มขึ้น = ผู้ซื้ออยู่ในการควบคุม; การปฏิเสธอย่างชัดเจนที่ VWAP ระหว่างแนวโน้มขาลงถือเป็นการศึกษาสั้นๆ ในสกุลเงินดิจิทัลตลอด 24 ชั่วโมงทุกวัน ระบบจะรีเซ็ตแตกต่างจากใน FX — ถือเป็นแนวทาง ไม่ใช่กฎหมาย"},{"h":"เครื่องยนต์ใช้งานอย่างไร","t":"ตัวบ่งชี้ใหม่แต่ละตัวจะเพิ่มการยืนยันเล็กน้อยให้กับคะแนนในด้านเดียวกับที่ชี้ (Stochastic, Ichimoku, VWAP, ADX เมื่อเห็นด้วยกับทิศทาง และ Elliott) มันเป็นการยืนยัน ไม่ใช่สิ่งกระตุ้น — หากพวกเขาไม่เห็นด้วยกับ BB / RSI / แท่งเทียน คะแนนจะผสมปนเปกันมากขึ้น และคุณจะได้รับการถือครองมากขึ้น"},{"h":"เหตุใด CAUION จึงเข้มงวดมากขึ้น","t":"เนื่องจากขณะนี้มีการตรวจสอบมากขึ้นในกลุ่ม แถบข้อควรระวังจึงถูกทำให้รัดกุม: ต้องมีคะแนน ≥ 4 และการตรวจสอบที่ตกลงกันอย่างน้อย 3 ครั้ง ซึ่งจะทำให้แอปไม่ท่วมคุณด้วยสัญญาณที่อ่อนลงเพียงเพราะมีเครื่องมือเปิดอยู่มากขึ้น"},{"h":"ลำดับการอ่านที่ใช้งานได้","t":"ทิศทาง TF ที่สูงขึ้น (เมฆ Ichimoku + ADX) ② ราคาอยู่ที่ (BB / Fib / VWAP) 3 โมเมนตัม (RSI + สุ่ม) ④ การยืนยันเทียน ⑤ % ความเสี่ยงและระดับที่เขียน → กระดาษก่อน"},{"h":"ข้อผิดพลาดที่ควรหลีกเลี่ยง","t":"เปิดไฟทุกดวงแล้วจ้องมองรุ้งกินน้ำ ใช้ ADX เป็นทิศทาง (เป็นเพียงความเข้มแข็ง) การลัดวงจรเพียงเพราะ Stochastic อยู่ที่ >80 ในการวิ่งกระทิง โดยไม่สนใจว่า VWAP มีความหมายที่แตกต่างกันใน crypto และ FX"},{"h":"รายการตรวจสอบการปฏิบัติ","t":"1 อคติจากคลาวด์ + ADX 2 ตำแหน่งจาก BB / Fib / VWAP 3 โมเมนตัมจาก RSI + Stoch ④ เทียนยืนยัน ⑤ SL / TP ที่เขียน ⑥ กระดาษ จากนั้นบันทึกประจำวัน"}]},{"id":"elliott","title":"16 · เอลเลียตเวฟ (จำนวนแสง)","summary":"CPE มีเครื่องนับ Elliott Wave น้ำหนักเบา ทำเครื่องหมายที่ “Elliott” ในแถบตัวบ่งชี้ Chart Lab และมันจะติดป้ายกำกับแรงกระตุ้น 0-1-2-3-4-5 สุดท้ายบนแท่งเทียนและฉายภาพเป้าหมาย Fibonacci คลื่น 5 มันเป็นเครื่องมือในการศึกษา ไม่ใช่ลูกบอลคริสตัล","lessons":[{"h":"ความคิดในบรรทัดเดียว","t":"ตลาดเคลื่อนไหวเป็นคลื่น: แรงกระตุ้น (5 ขาในทิศทางของแนวโน้ม) และการปรับฐาน (3 ขาสวนทางกัน) CPE นับเฉพาะแรงกระตุ้นซึ่งเป็นส่วนที่นำเทรนด์"},{"h":"CPE นับอย่างไร","t":"โดยจะค้นหาวงสวิงเดือยสุดท้าย (แฟร็กทัล 3 แท่ง) สลับสูง/ต่ำ และทดสอบวงสวิง 5–6 ครั้งล่าสุดตามกฎของเอลเลียต หากรูปร่างพอดี มันจะวาดป้ายกำกับ 0→5 (คลื่นที่ยังคงวิ่งอยู่เป็นสีเหลือง) และเส้นเป้าหมาย W5 ที่สร้างจากความยาวคลื่น-1 × 1.618 วัดจากคลื่น 4"},{"h":"กฎเกณฑ์ที่มันตรวจสอบ","t":"คลื่น 2 ไม่ผ่านจุดเริ่มต้นของคลื่น 1; คลื่น 4 ไม่ทับซ้อนอาณาเขตของคลื่น 1; คลื่น 3 ไม่ใช่ค่าที่สั้นที่สุดของ 1 / 3 / 5 เมื่อกฎล้มเหลว จะไม่แสดงอะไรเลย — ไม่มีการบังคับนับ"},{"h":"รั้นและหยาบคาย","t":"การเพิ่มขึ้น 0-1-2-3-4-5 ถือเป็นแรงกระตุ้นเชิงบวก ภาพสะท้อนทางขาลงเป็นภาพหมีๆ เครื่องยนต์เพิ่มการยืนยันเล็กน้อยให้กับคะแนนทางฝั่งคลื่น"},{"h":"ถ่ายทอดสด vs เสร็จสมบูรณ์","t":"คลื่น LIVE 5 (ยังคงทำงานอยู่) อ่านว่าเป็นแนวโน้มต่อเนื่อง แรงกระตุ้นที่สมบูรณ์ (0–5 เสร็จสิ้น) เตือนว่าแนวโน้มอาจจะเหนื่อย — มักจะมีการปรับฐานตามมา"},{"h":"เส้นเป้าหมาย W5","t":"ส่วนขยาย Fibonacci ของคลื่น 1 จากคลื่น 4 ต่ำ / สูง มันเป็นแนวคิดที่เป็นเป้าหมาย ไม่ใช่แม่เหล็ก ราคาสามารถหยุดให้ขาดหรือเกินกว่านั้นได้"},{"h":"วิธีการใช้งาน","t":"ถือว่าการนับเป็นจุดบรรจบกัน: ที่โซน BB / Fib ที่ชัดเจนพร้อมกับเทียนและ RSI การนับแบบหุนหันพลันแล่นจะเพิ่มความเชื่อมั่น เป็นเพียงภาพร่างเท่านั้นเอง"},{"h":"ข้อผิดพลาดที่ควรหลีกเลี่ยง","t":"นับคลื่นอีกครั้งจนกว่าจะพอดีกับตำแหน่งของคุณ (บาปของ Elliott แบบคลาสสิก); นับการกระดิกเล็ก ๆ ; ไม่สนใจการนับกรอบเวลาที่สูงกว่า โดยลืมจำนวนการเปลี่ยนแปลงทุกครั้งที่มีการพิมพ์แถบใหม่"},{"h":"รายการตรวจสอบการปฏิบัติ","t":"1 เลือกการสวิงที่ชัดเจน 2 ผ่านกฎ 3 ซิกแซกเห็นด้วยกับ BB / Fib ④ เทียนยืนยัน ⑤ SL เลยจุดคลื่นที่ 4 เป็นโมฆะ"}]},{"id":"forecast","title":"17 · พยากรณ์ราย 3 เดือน (ขีดพยากรณ์ 3 เดือน)","summary":"เครื่องฉายขอบฟ้าระยะยาว: กราฟนี้มีแนวโน้มที่จะก่อตัวอย่างไรในอีกประมาณ 3 เดือนข้างหน้า โดยสร้างขึ้นจากแนวโน้ม เป้าหมาย และความผันผวนของสัญญาณเอง เปิดหรือปิดด้วยเครื่องหมาย “Forecast 3M” ใน Chart Lab","lessons":[{"h":"มันวาดอะไร.","t":"เส้นกึ่งกลางเส้นประที่วิ่งจากรายการที่วิเคราะห์ไปยังเป้าหมายที่ดีที่สุดที่เครื่องยนต์รู้อยู่แล้ว (เป้าหมาย Elliott → tp2 → tp1) ล้อมรอบด้วย \"กรวย\" ที่กว้างขึ้นซึ่งแสดงการแพร่กระจายของราคาที่เป็นไปได้ เครื่องหมายเดือน M+1 / M+2 / M+3 แบ่งเส้นขอบฟ้า"},{"h":"ทำไมกรวยและไม่เส้น","t":"ไม่มีใครสามารถรู้ราคาที่แน่นอนในอนาคตได้ กรวยจะกว้างขึ้นตามรากที่สองของเวลาและความผันผวนของทั้งคู่ ดังนั้นคู่ FX ที่เงียบจะได้กรวยที่แคบและ altcoin แบบ wild จะมีกรวยที่กว้างมาก ความกว้างนั้นคือข้อความ ยิ่งคุณมองออกไปไกล ราคาก็ยิ่งไม่แน่นอน"},{"h":"ตัวเลขมาจากไหน.","t":"การดริฟท์มาจากเป้าหมายสัญญาณปัจจุบัน ความผันผวนรายวันมาจาก ATR% ของสัญญาณที่ปรับขนาดเป็นหนึ่งวัน ดังนั้นกรวยจึงมีความหมายเหมือนกันบนแผนภูมิ 5m หรือ 1d ความผันผวนสูงมาก / สูงทำให้กว้างขึ้นอีก"},{"h":"อ่านยังไงครับ","t":"ดูความชัน (ทางลาดเอียงของเส้นทาง) และความกว้าง (มีข้อสงสัยมากน้อยเพียงใด) เส้นทางขาขึ้นที่มีกรวยแคบ = แนวคิดแนวโน้มที่มั่นคงยิ่งขึ้น ทางเรียบที่มีกรวยขนาดใหญ่ = “ไม่มีขอบที่นี่ คาดว่าจะมีเสียงรบกวน”"},{"h":"การเปิดและปิด","t":"ปุ่ม \"พยากรณ์ 3M\" อยู่ถัดจาก \"พื้นที่ในอนาคต\" ต้องมี Future space ON (พื้นที่ว่างทางด้านขวาที่ฉายภาพเข้ามา) ถ้าสัญญาณเป็น HOLD แสดงว่าไม่มีทิศทางจึงไม่มีอะไรถูกดึงออกมา"},{"h":"มันเป็นเทรนด์ ไม่ใช่การค้าขาย","t":"การคาดการณ์เป็นแผนที่ภาพใหญ่ ระดับการซื้อขายจริง — รายการ, TP1 / TP2, SL และการประมาณการระยะสั้น — ยังคงเป็นสิ่งที่คุณซื้อขาย"},{"h":"ข้อจำกัดที่ซื่อสัตย์","t":"ข่าวสาร การลงประกาศ การเพิกถอน และการเปลี่ยนแปลงมหภาคไม่ได้อยู่ในโมเดล เส้นทางมีการดริฟท์เรียบๆ ดังนั้นราคาจริงจะกระดิกไปไกลกว่านี้มาก กรวยระยะเวลา 3 เดือนเป็นเครื่องช่วยการเรียน ไม่ใช่คำสัญญาใดๆ"},{"h":"วิเคราะห์ซ้ำบ่อยๆ","t":"เมื่อแท่งเทียนใหม่พิมพ์ เป้าหมาย ความผันผวน และกรวยทั้งหมดจะอัปเดต การคาดการณ์เป็นเพียงภาพรวม ไม่ใช่สัญญา"},{"h":"รายการตรวจสอบการปฏิบัติ","t":"1 อ่านทิศทางของเส้นทาง 2 ตรวจสอบความกว้างของกรวย 3 เปรียบเทียบกับโครงสร้าง TF ที่สูงกว่า ④ ปรับขนาดตำแหน่งจาก SL จริง ไม่ใช่จากกรวย"}]}],"platforms":{"BINANCE":{"title":"Binance การซื้อขาย A → Z","steps":["สร้างบัญชี → เปิดใช้งาน 2FA","การจัดการ API → สร้างคีย์ → เปิดการซื้อขายสปอต &/หรือฟิวเจอร์ส ปิดการถอนเงิน","วางคีย์ + ความลับใน CPE → คีย์ API → Binance → บันทึก → บัญชีทดสอบ","ใช้การสแกน Spot Desk / Futures Desk (แผนภูมิสาธารณะใช้งานได้ก่อนคีย์ด้วยซ้ำ)","แนวปฏิบัติ: การค้าขายด้วยตนเอง → เริ่มการซื้อขายกระดาษ (ไม่มีเงินจริง)","ใช้งานจริง: ตั้งค่า TP1/TP2/SL + Trailing → เริ่มการซื้อขายจริง (ต้องใช้ API)","จัดการในตำแหน่ง: แก้ไขระดับ, ปิดบางส่วน, ยกเลิกอัตโนมัติ","ใบอนุญาต: ทดลองใช้ 7d → 3 เดือนหรือตลอดชีพ (ราคาของเจ้าของในแอป)"]},"BYBIT":{"title":"Bybit การซื้อขาย A → Z","steps":["บัญชี + 2FA","การจัดการ API → การค้าเท่านั้น ปิดการถอนเงิน","CPE → คีย์ API → Bybit → บันทึก","Futures Desk สำหรับความคิดแบบ perps; Chart Lab เพื่อศึกษาเทียน","การค้ากระดาษก่อน; ถ่ายทอดสดหลังจากคีย์ทำงาน","เส้นทาง TP+SL: ซื้อ↑ / ขาย↓"]},"OKX":{"title":"OKX การซื้อขาย A → Z","steps":["ต้องใช้คีย์ API + ความลับ + รหัสผ่าน","การถอนเงินจะถูกปิดเสมอ","บันทึกทั้งสามฟิลด์ในคีย์ CPE","แบบฝึกหัดกระดาษ → ขนาดเล็กสด","การพิมพ์รหัสผ่านผิดถือเป็นข้อผิดพลาดอันดับ 1 — โปรดคัดลอกอย่างระมัดระวัง"]},"KUCOIN":{"title":"การซื้อขาย KuCoin A → Z","steps":["คีย์ + ความลับ + รหัสผ่าน","อนุญาตการค้าเท่านั้น","กระดาษใน CPE → แล้วอาศัยขนาดเล็ก","ใช้โต๊ะ Spot/Futures สำหรับสัญญาณ"]},"BITGET":{"title":"การซื้อขาย Bitget A → Z","steps":["API พร้อมการแลกเปลี่ยนเท่านั้น","กระดาษแล้วมีชีวิตอยู่","ฟิวเจอร์ส: เลือก Cross หรือ Isolated ในการซื้อขายด้วยตนเอง","ติดตาม TP+SL เพื่อล็อคผลกำไร"]},"GATE":{"title":"Gate.io การซื้อขาย A → Z","steps":["สร้างคีย์ API v4 (แลกเปลี่ยน)","ปิดการถอนเงิน","บันทึกใน CPE → กระดาษฝึกหัด","Scan + Chart Lab เพื่อดูรายการก่อนถ่ายทอดสด"]},"MEXC":{"title":"MEXC การซื้อขาย A → Z","steps":["เริ่มต้นจุดความคิด","คีย์ในคีย์ CPE API","กระดาษ → สด","ใช้เส้นทางเพื่อล็อคกำไรที่เปิดอยู่"]},"KRAKEN":{"title":"Kraken การซื้อขาย A → Z","steps":["สร้างคีย์ที่ได้รับอนุญาตทางการค้าเท่านั้น","ไม่มีสิทธิในการถอน/ให้ทุน","แบบฝึกหัดกระดาษใน CPE","ตรวจสอบทุกคำสั่งซื้อสดบน Kraken ด้วย"]},"COINBASE":{"title":"Coinbase ขั้นสูง A → Z","steps":["คีย์ API การค้าขั้นสูง","โต๊ะเน้นเฉพาะจุดใน CPE","กระดาษแล้วมีชีวิตอยู่","ปิดการถอนเงินไว้"]},"FOREX_OANDA":{"title":"ฟอเร็กซ์ (OANDA) A → Z","steps":["เปิดการสาธิต OANDA → ความเสี่ยง ~1%","โทเค็นการเข้าถึงส่วนบุคคล + รหัสบัญชีในคีย์ CPE","สแกนโต๊ะ Forex + แล็บแผนภูมิ (EURUSD…)","การซื้อขายด้วยตนเอง → กระดาษด้วยแพลตฟอร์ม Forex","ใช้งานจริงหลังจากความมั่นใจในการสาธิตเท่านั้น"]},"FOREX_FXCM":{"title":"FXCM ฟอเร็กซ์ A → Z","steps":["ข้อมูลรับรอง API ของโบรกเกอร์","กระดาษใน CPE ก่อน","ดูเซสชันในลอนดอน/นิวยอร์กและข่าวสารที่พุ่งสูงขึ้น","บันทึก Live after Practice ดูสะอาดตา"]},"FOREX_MT5":{"title":"MetaTrader 5 A → Z","steps":["เข้าสู่ระบบ + เซิร์ฟเวอร์ + รหัสผ่านในคีย์ CPE","ต้องการรหัสผ่านนักลงทุน (อ่าน) หากเป็นไปได้","แบบฝึกหัด 0.01","กระดาษใน CPE; ถ่ายทอดสดผ่านนายหน้าเมื่อพร้อม"]},"FOREX_DEMO":{"title":"อัตราการสาธิต Forex A → Z","steps":["ไม่จำเป็นต้องมีคีย์ API","Forex Desk + Chart Lab สำหรับกราฟฟรี","การซื้อขายกระดาษเท่านั้น (แบบฝึกหัด)","เมื่อพร้อมสำหรับโบรกเกอร์จริง เพิ่มคีย์ OANDA / FXCM / MT5 สำหรับการถ่ายทอดสด"]}},"forexAz":{"title":"การซื้อขายฟอเร็กซ์ A → Z (คลาสเต็ม)","lessons":[{"h":"เอ — บัญชีและความเสี่ยง","t":"สาธิตก่อน ความเสี่ยง ~0.5–1% ต่อไอเดีย อย่าแก้แค้นการค้าขาย"},{"h":"B - คู่","t":"คู่สกุลเงินหลัก (EURUSD, GBPUSD, USDJPY) ก่อนคู่สกุลเงินแปลกใหม่"},{"h":"C — เทียน","t":"เรียนรู้ Doji, Hammer, Engulfing บน Chart Lab Forex"},{"h":"D - อคติรายวัน","t":"ตรวจสอบกรอบเวลาที่สูงขึ้นก่อนเข้า 15 นาที/30 นาที"},{"h":"E — รายการ","t":"BB การตีกลับที่ต่ำกว่า + การยืนยันเทียนเป็นการตั้งค่าการปฏิบัติทั่วไป"},{"h":"เอฟ — ตอแหล","t":"การดึงกลับ 50% / 61.8% มักใช้เป็นโซนฝึกซ้อม"},{"h":"G — เป้าหมาย (TP)","t":"TP1 สเกลเอาท์, นักวิ่ง TP2, เทรล SL"},{"h":"H — ชั่วโมง","t":"การทับซ้อนกันระหว่างลอนดอน–นิวยอร์ก = การเคลื่อนไหวมากขึ้น"},{"h":"ฉัน — ตัวบ่งชี้","t":"RSI + MACD + BB รวมกัน; หลีกเลี่ยงการโอเวอร์โหลดตัวบ่งชี้"},{"h":"เจ — วารสาร","t":"บันทึกทุกการซื้อขายกระดาษ/สดใน CPE Journal"},{"h":"เค — คีย์","t":"โบรกเกอร์ฟอเร็กซ์สดต้องการ API/โทเค็น อัตราสาธิตไม่จำเป็นต้องมีเลย"},{"h":"L - มากมาย","t":"เริ่มต้น 0.01 ล็อต ในการฝึก Mindset"},{"h":"M - ความคิด","t":"กระบวนการมากกว่าการคาดการณ์ ข้ามวันที่เลวร้าย"},{"h":"เอ็น — ข่าว","t":"ตรวจสอบข่าวสารและเคล็ดลับก่อนงานสำคัญ"},{"h":"โอ - คำสั่ง","t":"ตั้งค่า SL เสมอ Trailing ปกป้องผลกำไรที่เปิดอยู่"},{"h":"ป — การปฏิบัติ","t":"ปุ่ม Paper Trade = ฝึกฝนโดยไม่ต้องใช้ API แบบสด"},{"h":"ถาม — คุณภาพ","t":"การตั้งค่าคุณภาพสูงน้อยกว่าจะเอาชนะการซื้อขายมากเกินไป"},{"h":"R — ความเสี่ยง:รางวัล","t":"ตั้งเป้าหมายโดยให้รางวัล ≥ ความเสี่ยงเมื่อเป็นไปได้"},{"h":"S — เซสชัน","t":"เอเชียเงียบกว่า ลอนดอน/นิวยอร์กมีความกระตือรือร้นมากขึ้น"},{"h":"T — เทรนด์","t":"ซื้อขายกับแนวโน้ม TF ที่สูงกว่าเมื่อเรียนรู้"},{"h":"คุณ - อัปเดต","t":"ดูแบนเนอร์อัปเดต CPE + ความช่วยเหลือแบบสด"},{"h":"V — ความผันผวน","t":"ความอดทนเพิ่มขึ้นเมื่อ ATR เพิ่มขึ้นอย่างรวดเร็ว"},{"h":"W — ถอน API","t":"อย่าเปิดใช้งานการถอนคีย์ API ใด ๆ"},{"h":"X — ออก","t":"TP + เทรลบางส่วนมีความหวัง"},{"h":"Y — แผนของคุณ","t":"เขียนกฎ; ติดตามพวกเขาในโหมดแมนนวล/อัตโนมัติ"},{"h":"Z - การเร่งรีบเป็นศูนย์","t":"ไม่มีโฟโม่ ฝึกฝน → จากนั้นใช้งาน API แบบสด"}]}};

window.CPE_LEARN.id = {"intro":"Latihan dengan Paper/DEMO terlebih dahulu. Pelajari candle, grafik, BB/RSI/Fib, uang, psikologi — lalu Sinyal (arti BELI/JUAL/TAHAN + apa yang harus dilakukan) dan sinyal Forex. Live memerlukan kunci API platform yang benar (Penarikan MATI).","candles":[{"shape":"doji","name":"Doji","color":"#94a3b8","bias":"Netral / tunggu","tip":"Buka ≈ tutup — badan menyilang atau kurus. Keragu-raguan pasar setelah pergerakan.","also":"Juga mengajarkan: jangan FOMO. Tunggu lilin berikutnya. Dekat BB ekstrim + Doji = pemerasan opini; periksa kemiringan RSI sebelum menebak arah."},{"shape":"hammer","name":"Palu","color":"#22c55e","bias":"bias BELI","tip":"Badan kecil di atas, sumbu bawah panjang (≈2× badan) setelah terjatuh — pembeli menolak harga yang lebih rendah.","also":"Juga: tempatkan latihan SL di bawah sumbu rendah. Terbaik dengan BB + RSI yang lebih rendah naik dari oversold. Psikologi: kesabaran hingga sumbu habis - jangan membeli sumbu tengah."},{"shape":"invhammer","name":"Palu Terbalik","color":"#22c55e","bias":"BELI (lemah)","tip":"Sumbu atas panjang di bawah. Pembeli memperkirakan harga tertinggi namun ditutup mendekati harga pembukaan – memerlukan konfirmasi hijau berikutnya.","also":"Juga: lebih lemah dari Hammer saja. Gunakan sebagai peringatan, bukan entri. Fib 61.8 bouncing + Inverted Hammer = zona belajar hanya sampai konfirmasi candle."},{"shape":"shooting","name":"Bintang Jatuh","color":"#ef4444","bias":"bias JUAL","tip":"Tubuh bagian bawah kecil, sumbu atas panjang setelah kenaikan — penjual menolak harga tertinggi.","also":"Juga: SL di atas sumbu tinggi. Lebih kuat di dekat ekstensi BB / Fib atas / RSI overbought. Mengajarkan: lilin bulan bisa gagal — jangan mengejar warna hijau terakhir."},{"shape":"hanging","name":"Manusia Gantung","color":"#f59e0b","bias":"JUAL hati-hati","tip":"Tampak seperti Hammer tetapi muncul setelah tanjakan — kemungkinan kelelahan puncak.","also":"Juga: konteks adalah segalanya (bentuk yang sama ≠ perdagangan yang sama). Lokasi jurnal: atas vs bawah. Psikologi: jangan mundur hanya karena bentuknya cocok — konfirmasikan dengan candle berikutnya + RSI."},{"shape":"engulf_bull","name":"Menelan Bullish","color":"#22c55e","bias":"MEMBELI","tip":"Badan berwarna hijau sepenuhnya menutupi badan merah sebelumnya — pembeli mengambil kendali dalam satu batang.","also":"Juga: lebih kuat di support / BB lebih rendah / Fib 50–61.8. Ukuran dari engulfing serendah SL. Tip uang: bodi yang lebar → SL lebih lebar → ukuran lebih kecil."},{"shape":"engulf_bear","name":"Menelan Bearish","color":"#ef4444","bias":"JUAL","tip":"Badan berwarna merah sepenuhnya menutupi warna hijau sebelumnya — penjual mendominasi.","also":"Juga: hati-hati pada posisi beli terbuka. Dekat BB atas + RSI>70 = kualitas belajar tinggi. Mengajarkan resiko: jika sudah lama, sebagian TP/jejak bukannya harapan."},{"shape":"morning","name":"Bintang Kejora","color":"#22c55e","bias":"MEMBELI","tip":"3 lilin: merah besar → bintang kecil → hijau besar. Cerita pembalikan bawah.","also":"Juga: kesabaran multi-lilin. Masuk setelah penutupan ke-3; SL dibawah bintang rendah. Dikombinasikan dengan baik dengan divergensi RSI BB yang lebih rendah + bullish."},{"shape":"evening","name":"Bintang Sore","color":"#ef4444","bias":"JUAL","tip":"3 lilin: hijau besar → bintang kecil → merah besar. Kisah pembalikan teratas.","also":"Juga: jangan menyingkat bintang tengahnya saja. Tunggu ke-3 tutup. Pertemuan ekstensi BB / Fib atas. Psikologi: abaikan FOMO pada green run pertama."},{"shape":"maru_bull","name":"Banteng Marubozu","color":"#22c55e","bias":"Tekanan BELI yang kuat","tip":"Badan hijau panjang, hampir tidak ada sumbu — pembeli mengontrol buka→tutup.","also":"Juga: petunjuk kelanjutan tren, tidak selalu merupakan pembelian terbawah. Walk-the-band mungkin. Resiko: mengejar late Marubozu tanpa pullback ke BB mid/Fib."},{"shape":"maru_bear","name":"Beruang Marubozu","color":"#ef4444","bias":"Tekanan JUAL yang kuat","tip":"Bodinya berwarna merah panjang, hampir tidak ada sumbu — penjual memegang kendali.","also":"Juga: jangan menangkap pisau yang jatuh. Tunggu pemantulan BB/Fib + Hammer nanti. Mengajarkan: tekanan kuat = ukuran lebih kecil atau menyingkir."},{"shape":"spin","name":"Berputar Atas","color":"#94a3b8","bias":"Keragu-raguan","tip":"Badan kecil, sumbu atas + bawah — kedua belah pihak bertarung, tidak ada yang menang dengan jelas.","also":"Juga: sering-seringlah menekan bagian dalam BB. Jeda perdagangan; tunggu break + arah candle. Pelajaran psikologi: pasar tidak bisa berbuat apa-apa — flat adalah pilihan yang valid."},{"shape":"pierce","name":"Garis Menusuk","color":"#22c55e","bias":"MEMBELI","tip":"Merah lalu hijau yang dibuka lebih rendah namun ditutup di atas titik tengah merah sebelumnya.","also":"Juga: lebih lembut dari Engulfing. Konfirmasikan dengan giliran RSI. Bor kertas yang bagus untuk membaca kekuatan parsial — tidak semua sayuran sama."},{"shape":"darkcloud","name":"Tutupan Awan Gelap","color":"#ef4444","bias":"JUAL","tip":"Hijau lalu merah yang dibuka lebih tinggi namun ditutup di bawah titik tengah hijau sebelumnya.","also":"Juga: peringatan dini sebelum Bear Engulfing penuh. Jejak panjang / ambil TP1. Mengajarkan penskalaan sebelum pencetakan pembalikan penuh."},{"shape":"soldiers","name":"Tiga Tentara Putih","color":"#22c55e","bias":"Tren BELI","tip":"Tiga saham hijau yang sedang naik daun dengan penutupan lebih tinggi — pembelian stabil.","also":"Juga: isyarat tren naik yang kuat; kemunduran ke Fib 38–50 atau BB mid adalah penambahan latihan. Risiko terlalu percaya diri setelah 3 green — pertahankan% risiko tetap."},{"shape":"crows","name":"Tiga Gagak Hitam","color":"#ef4444","bias":"Tren JUAL","tip":"Tiga warna merah jatuh dengan penutupan lebih rendah — penjualan stabil.","also":"Juga: jangan rata-rata turun. Tunggu struktur. RSI yang oversold bisa tetap oversold — aturan uang: batas kerugian > harapan."},{"shape":"harami_bull","name":"Harami yang Bullish","color":"#22c55e","bias":"BELI (lembut)","tip":"Merah besar, lalu hijau kecil di dalam bodi sebelumnya — tekanan jual menyusut.","also":"Juga: sinyal jeda awal. Perlu konfirmasi. Pasangkan dengan studi divergensi bullish RSI. Mengajarkan membaca “kekuatan memudar” tidak hanya pembalikan."},{"shape":"harami_bear","name":"Harami yang kasar","color":"#ef4444","bias":"JUAL (lunak)","tip":"Hijau besar, lalu merah kecil di dalamnya — tekanan beli menyusut.","also":"Juga: ambil sebagian posisi beli. Tidak otomatis pendek. Psikologi: keserakahan terhadap big green seringkali mengabaikan peringatan Harami."},{"shape":"tweezer_bot","name":"Penjepit Bawah","color":"#22c55e","bias":"MEMBELI","tip":"Dua candle dengan posisi terendah yang cocok — uji support ganda.","also":"Juga: tandai serendah itu sebagai struktur. SL tepat di bawah. Penyelarasan Fib/BB membantu. Sepupu pola grafik dari Double Bottom — pelajaran dukungan yang sama."},{"shape":"tweezer_top","name":"Pinset Atas","color":"#ef4444","bias":"JUAL","tip":"Dua candle dengan harga tertinggi yang cocok — uji resistensi ganda.","also":"Juga: tandai resistensi. Sepupu Double Top. Kegagalan RSI pada titik tertinggi = pertemuan. Mengajarkan: harga yang sama dua kali ditolak = hormati levelnya."},{"shape":"longlegged","name":"Doji Berkaki Panjang","color":"#94a3b8","bias":"Keragu-raguan","tip":"Sumbu atas DAN bawah yang sangat panjang dengan tubuh mungil — pertarungan dua arah yang penuh kekerasan yang berakhir di tempat dimulainya.","also":"Juga: pergerakan besar sering kali terjadi, tetapi arahnya tidak diketahui — tunggu hingga candle tembus. Mengajarkan: volatilitas yang tinggi bukanlah kepastian yang tinggi."},{"shape":"dragonfly","name":"Capung Doji","color":"#22c55e","bias":"bias BELI","tip":"Buka = tutup = tinggi, dengan sumbu bawah yang panjang — penjual mendorong ke bawah dan pembeli membantingnya kembali ke atas.","also":"Juga: terkuat di support / BB lebih rendah setelah turun. SL di bawah ekor sumbu. Mengajarkan: penolakan adalah sebuah cerita, bukan jaminan — konfirmasikan candle berikutnya."},{"shape":"gravestone","name":"Doji Batu Nisan","color":"#ef4444","bias":"bias JUAL","tip":"Buka = tutup = rendah, dengan sumbu atas yang panjang — pembeli mendorong ke atas dan penjual menyeretnya kembali ke titik terendah.","also":"Juga: terkuat di resistance/BB atas/RSI overbought. Cermin Capung. Mengajarkan: lonjakan tertinggi yang ditutup pada titik terendah adalah penembusan yang gagal."},{"shape":"inside_bar","name":"Di dalam Bar","color":"#94a3b8","bias":"Melingkar / menunggu","tip":"Lilin kedua berada sepenuhnya di dalam lilin pertama — kisarannya terkompresi dan pasar menahan napas.","also":"Juga: penembusan bar induk adalah pemicunya — lakukan perdagangan dalam arah penembusan. Pasangkan dengan pemerasan BB. Mengajarkan: kontraksi terjadi sebelum ekspansi."},{"shape":"outside_bar","name":"Bar Luar","color":"#22c55e","bias":"Penembusan / pembalikan","tip":"Lilin kedua menelan lilin pertama dari titik tertinggi ke titik terendah — pengambilalihan yang hebat dalam satu batang.","also":"Juga: arah = dimana bar luar ditutup. Bar yang besar berarti SL yang besar, jadi ukurannya lebih kecil. Mengajarkan: satu batang dapat menghapus tiga batang terakhir."},{"shape":"belt_bull","name":"Penahan Sabuk Bullish","color":"#22c55e","bias":"MEMBELI","tip":"Dibuka pada harga terendah tanpa sumbu bawah dan berjalan hijau — pembeli mengambil kendali sejak tick pertama.","also":"Juga: terkuat setelah gap ke bawah atau langsung ke support. SL di bawah terbuka. Mengajarkan: drive pembuka menunjukkan niat sebenarnya."},{"shape":"belt_bear","name":"Penahan Sabuk Bearish","color":"#ef4444","bias":"JUAL","tip":"Dibuka pada titik tertinggi tanpa sumbu atas dan berubah menjadi merah — penjual mengendalikannya dari pembukaan.","also":"Juga: terkuat setelah gap naik atau pada resistance. Jejak panjang. Mengajarkan: langkah pertama bisa diatur sepanjang hari."},{"shape":"kick_bull","name":"Penendang Bullish","color":"#22c55e","bias":"BELI yang kuat","tip":"Lilin merah, lalu celah naik menjadi lilin hijau — suasana berubah di antara penutupan tanpa tumpang tindih.","also":"Juga: langka dan kuat; kesenjangan diperlukan, tidak boleh ada tumpang tindih. Pelajarannya: sentimen bisa berubah saat pasar tertidur."},{"shape":"kick_bear","name":"Penendang Beruang","color":"#ef4444","bias":"JUAL yang kuat","tip":"Lilin hijau, lalu celah turun menjadi lilin merah — pembeli menghilang di antara penutupan.","also":"Juga: keluar dari posisi beli dengan cepat — penendang tidak menunggu Anda. Mengajarkan: kesenjangan adalah penetapan harga pasar saat Anda pergi."},{"shape":"abandoned","name":"Bayi Terbengkalai yang Bullish","color":"#22c55e","bias":"BELI yang kuat","tip":"Lilin merah, doji dengan celah ke bawah, lalu lilin hijau dengan celah ke atas - sebuah pulau kebimbangan yang sepi.","also":"Juga: doji harus berjarak jauh di KEDUA sisi. Langka tetapi berkualitas tinggi di bagian bawah. Mengajarkan: pembalikan dimulai ketika semua orang menyerah."},{"shape":"three_inside_up","name":"Tiga Di Dalam","color":"#22c55e","bias":"MEMBELI","tip":"Bullish Harami ditambah candle hijau ketiga yang ditutup di atas candle pertama — bar bagian dalam akhirnya pecah.","also":"Juga: Harami yang terkonfirmasi jauh lebih kuat daripada Harami yang telanjang. SL di bawah harami rendah. Mengajarkan: konfirmasi mengalahkan prediksi."},{"shape":"three_inside_down","name":"Tiga Dalam Bawah","color":"#ef4444","bias":"JUAL","tip":"Bearish Harami ditambah candle merah ketiga yang ditutup di bawah candle pertama — bar bagian dalam rusak.","also":"Juga: potong posisi beli segera setelah penutupan ketiga. Mengajarkan: jeda yang gagal dapat melanjutkan tren lama."},{"shape":"three_methods_bull","name":"Bangkitnya Tiga Metode","color":"#22c55e","bias":"Tren BELI","tip":"Lilin hijau panjang, tiga merah kecil di dalamnya, lalu hijau panjang lainnya — berhenti di dalam kenaikan.","also":"Selain itu: jeda tidak pernah meninggalkan kisaran candle pertama, sehingga trennya tenang. Perdagangkan terobosan candle terakhir. Mengajarkan: tren berhenti tanpa putus."},{"shape":"three_methods_bear","name":"Jatuh Tiga Metode","color":"#ef4444","bias":"Tren JUAL","tip":"Lilin merah panjang, tiga sayuran hijau kecil di dalamnya, lalu satu lagi lilin merah panjang — istirahat di dalam musim gugur.","also":"Juga: cerminan dari Rising Three Methods. Jangan membeli sayuran kecil – mereka berisik. Mengajarkan: kemunduran dalam rentang bukanlah pembalikan."},{"shape":"tower_bot","name":"Menara Bawah","color":"#22c55e","bias":"BELI pembalikan","tip":"Lilin merah panjang, sekumpulan lilin kecil, lalu lilin hijau panjang — suasana berubah pada dasar datar.","also":"Juga: bagian tengah yang datar adalah pertarungan dan candle terakhir menyatakan pemenang. Mengajarkan: dasar memerlukan waktu."},{"shape":"tower_top","name":"Menara Puncak","color":"#ef4444","bias":"JUAL pembalikan","tip":"Lilin hijau panjang, sekelompok lilin kecil, lalu lilin merah panjang — pembeli kehabisan tenaga dan penjual mengambil alih.","also":"Juga: cermin Tower Bottom. Ambil sebagian selagi alasnya terbentuk. Mengajarkan: puncak adalah suatu proses, bukan sesaat."}],"chartPatterns":[{"shape":"double_bot","name":"Bawah Ganda (W)","color":"#22c55e","bias":"bias BELI","tip":"Dua titik terendah mendekati harga yang sama, lalu menembus puncak tengah — bentuk W.","also":"Juga: jeda garis leher = pemicu latihan. Ukur tinggi badan untuk ide TP. Tautan ke Tweezer Bottom + Fib dari peak→low. Resiko: false break — tunggu hingga melampaui garis leher."},{"shape":"double_top","name":"Atasan Ganda (M)","color":"#ef4444","bias":"bias JUAL","tip":"Dua harga tertinggi mendekati harga yang sama, lalu menembus palung tengah — bentuk M.","also":"Juga: sama seperti Tweezer Top dalam skala yang lebih besar. Jejak jauh sebelum garis leher putus. Psikologi: FOMO teratas kedua itu mahal — rencana sudah ada."},{"shape":"hs_top","name":"Kepala & Bahu","color":"#ef4444","bias":"bias JUAL","tip":"Bahu kiri, kepala lebih tinggi, bahu kanan; mematahkan garis leher ke bawah.","also":"Juga: distribusi klasik. Targetkan ≈ tinggi kepala di bawah garis leher. RSI sering kali menyimpang. Mengajarkan kesabaran multi-swing — bukan trading satu candle."},{"shape":"ihs","name":"H&S terbalik","color":"#22c55e","bias":"bias BELI","tip":"H&S terbalik di bagian bawah — garis leher putus.","also":"Juga: kisah akumulasi. Konfirmasikan dengan volume/momentum jika tersedia. Pasangkan dengan Morning Star di zona bahu kanan untuk studi pertemuan."},{"shape":"triangle","name":"Segitiga (peras)","color":"#f0b429","bias":"Tunggu sebentar","tip":"Nilai tertinggi yang lebih rendah + kompresi nilai terendah yang lebih tinggi — pembentukan energi.","also":"Juga: pelajaran yang sama dengan pemerasan BB. Jangan menebak arah ke dalam. Jeda perdagangan + penutupan candle. Uang: ukuran demi arah diketahui."},{"shape":"flag","name":"Bendera Banteng","color":"#22c55e","bias":"BELI lanjutan.","tip":"Kenaikan tajam (kutub) lalu saluran kecil ke bawah/samping — lalu berlanjut.","also":"Juga: Kedalaman bendera fib seringkali dangkal (38%). Tiang Marubozu + bendera = latihan tren. Jangan membeli terlambat setelah perpanjangan penuh tanpa kemunduran."},{"shape":"channel","name":"Saluran Tren","color":"#38bdf8","bias":"Dengan tren","tip":"Harga antara garis paralel naik (atau turun) — alat swing trade.","also":"Juga: beli saluran bawah + Palu dalam tren naik; jual upper + Shooting Star. BB mid sering melacak saluran. Mengajarkan “di mana” bukan hanya “lilin apa”."},{"shape":"support_res","name":"Dukungan & Perlawanan","color":"#a78bfa","bias":"Konteks dulu","tip":"Zona horizontal tempat harga bereaksi berulang kali — peta di bawah setiap candle.","also":"Juga: setiap pola lebih kuat di S/R. Gambarlah zona di Chart Lab sebelum BB/RSI. Psikologi: level > tip; tulislah sebelum masuk."},{"shape":"triple_top","name":"Tiga Atas","color":"#ef4444","bias":"bias JUAL","tip":"Tiga harga tertinggi dengan harga yang hampir sama — pembeli gagal tiga kali di satu dinding.","also":"Juga: lebih kuat dari Double Top (tiga penolakan = pasokan membandel). Patahnya garis leher adalah pemicunya; target ≈ tinggi pola. Mengajarkan: levelnya, bukan lilinnya, yang menjadi bosnya."},{"shape":"triple_bot","name":"Tiga Bawah","color":"#22c55e","bias":"bias BELI","tip":"Tiga titik terendah pada harga yang hampir sama — penjual gagal tiga kali dalam satu harga.","also":"Juga: cermin Triple Top. Setiap sentuhan bisa menjadi pembelajaran Palu/Penjepit. Tunggu hingga garis leher tembus + tutup. Mengajarkan kesabaran dalam menghadapi banyak ayunan."},{"shape":"cup_handle","name":"Cangkir & Pegangan","color":"#22c55e","bias":"BELI lanjutan.","tip":"Bentuk “U” bulat (cangkir) lalu tarikan kecil ke belakang (pegangan) — lanjutan setelah istirahat.","also":"Juga: populer di kalangan pedagang breakout. Pegangan harus dangkal dan pendek — pegangan yang dalam berarti tangan lemah. Masuk pada handle-break dengan konfirmasi candle."},{"shape":"rounding_bot","name":"Pembulatan Bawah","color":"#22c55e","bias":"BELI pembalikan","tip":"“Piring” rendah yang lambat dan mulus — penjualan memudar secara bertahap, kemudian pembeli mengambil alih.","also":"Juga: Double Bottom gerak lambat. Pesannya adalah penjual kehabisan energi, tidak ada satu lonjakan pun — diperlukan kesabaran penuh."},{"shape":"rounding_top","name":"Pembulatan Atas","color":"#ef4444","bias":"JUAL pembalikan","tip":"Level tinggi “kubah” yang mulus — pembelian memudar secara bertahap sebelum harga bergulir.","also":"Juga: cermin Rounding Bottom. Ambil sebagian lebih awal saat momentum mati. Mengajarkan: puncak adalah suatu proses, bukan satu lilin pun."},{"shape":"rising_wedge","name":"Baji yang Meningkat","color":"#ef4444","bias":"bias JUAL","tip":"Kedua relnya naik, tetapi keduanya menyatu ke atas — pembeli menjadi lelah karena jaraknya semakin sempit.","also":"Juga: menyesatkan karena harga masih naik; penyempitan adalah petunjuk sebenarnya. Sering rusak. Jangan mengejar dorongan terakhir."},{"shape":"falling_wedge","name":"Baji Jatuh","color":"#22c55e","bias":"bias BELI","tip":"Kedua relnya jatuh, namun menyatu ke bawah — penjual menjadi lelah saat jaraknya semakin sempit.","also":"Juga: cermin Rising Wedge. Sering putus. Palu di ekor baji adalah studi klasik. Tunggu istirahat+close."},{"shape":"asc_triangle","name":"Segitiga Menaik","color":"#f0b429","bias":"bias BELI","tip":"Langit-langit datar + dasar meninggi — pembeli terus memasuki resistensi tetap.","also":"Juga: tekanan meningkat terhadap satu harga; breakout adalah hal biasa. Masuk dari dekat di atas langit-langit. Mengajarkan: pembeli menjadi tidak sabar."},{"shape":"desc_triangle","name":"Segitiga Menurun","color":"#f0b429","bias":"bias JUAL","tip":"Lantai datar + langit-langit runtuh — penjual terus mendorong ke support tetap.","also":"Juga: cermin dari Ascending Triangle. Breakout adalah hal biasa. Masuk dekat di bawah lantai. Mengajarkan: penjual mendapatkan kendali."},{"shape":"pennant","name":"panji","color":"#22c55e","bias":"Lanjutan","tip":"Sebuah kutub yang tajam kemudian sebuah segitiga kecil yang rapat — istirahat yang sangat singkat sebelum tren berlanjut.","also":"Juga: seperti Bendera tetapi lebih pendek dan berbentuk segitiga. Ukur tiang untuk ide sasaran. Jangan pernah menebak-nebak bagian dalam kumparan kecil itu."},{"shape":"flag_bear","name":"Bendera Beruang","color":"#ef4444","bias":"JUAL lanjutan.","tip":"Penurunan tajam (kutub) lalu saluran kecil ke atas / ke samping — lalu berlanjut ke bawah.","also":"Juga: cermin Bendera Banteng. Pantulan kecil itu adalah jeda, bukan pembalikan. Kejar benderanya dan Anda membeli harga terburuk — tunggu sampai jeda."},{"shape":"rectangle","name":"Persegi Panjang (Rentang)","color":"#f0b429","bias":"Perdagangan jarak jauh","tip":"Harga memantul antara langit-langit datar dan lantai — kotak menyamping.","also":"Juga: memudarkan tepian di dalam, tukarkan bagian luarnya. Pemerasan BB biasanya berada di dalam persegi panjang. Mengajarkan: disiplin tingkat ke tingkat."},{"shape":"broadening","name":"Memperluas Formasi","color":"#f0b429","bias":"Perhatian","tip":"Nilai tertinggi yang lebih tinggi DAN nilai terendah yang lebih rendah — rentangnya menyebar dan bukannya terjepit.","also":"Juga: pasar yang kacau dan emosional. Berhenti terkena dua arah. Ukuran lebih kecil atau berdiri di samping; sering kali berakhir dengan gerakan satu arah yang penuh kekerasan."},{"shape":"diamond","name":"berlian","color":"#f0b429","bias":"Pembalikan","tip":"Lebar di tengah, sempit di kedua ujungnya — formasi topping/bottoming klasik.","also":"Juga: Segitiga yang berubah lalu tidak berubah. Arah breakout menentukan. Jarang dan lambat, sehingga sebagian besar baris terasa seperti kebisingan — bersabarlah."},{"shape":"island_rev","name":"Pembalikan Pulau","color":"#ef4444","bias":"Pembalikan","tip":"Selisih harga menjauh, diperdagangkan dalam kelompok yang sepi, lalu terjadi kesenjangan kembali — sebuah “pulau”.","also":"Juga: membutuhkan kesenjangan nyata (lebih umum di saham/FX). Pulau ini menjebak pembeli atau penjual. Perlakukan kesenjangan sebagai sinyal, bukan candle pulau."},{"shape":"breakaway_gap","name":"Kesenjangan yang Memisahkan","color":"#22c55e","bias":"Tren dimulai","tip":"Celah di luar jangkauan atau pangkalan — gerakan dimulai dengan kekuatan, bukan tekanan.","also":"Juga: tidak seperti kesenjangan kelelahan, kesenjangan ini muncul di awal suatu pergerakan. Kesenjangan sering kali kemudian bertindak sebagai support/resistance. Mengajarkan: momentum vs. kesenjangan nilai."},{"shape":"v_reversal","name":"V-Pembalikan","color":"#22c55e","bias":"Pembalikan","tip":"Jatuh bebas tajam yang muncul seketika tanpa dasar — huruf “V”.","also":"Juga: cepat dan menakutkan; sering kali didorong oleh berita. Sulit ditangkap, mudah dikejar. Tunggu kemunduran kecil + candle daripada membeli lonjakan."},{"shape":"harmonic","name":"Pola Harmonik","color":"#f0b429","bias":"Zona pembalikan","tip":"Zig-zag terukur (X-A-B-C-D) di mana setiap kaki memiliki rasio Fibonacci — peta gaya “Gartley/Bat”.","also":"Juga: tingkat lanjut. Titik D adalah zona masuk, ditentukan oleh rasio, bukan perasaan. Kuasai Fib biasa terlebih dahulu; ini adalah Fib yang diambil satu tingkat lebih dalam."}],"modules":[{"id":"bb","title":"1 · Bollinger Band (BB)","summary":"Volatilitas berada di sekitar rata-rata pergerakan. Pelajari pemerasan, walk-the-band, sentuhan bawah/atas + konfirmasi lilin — pengaturan latihan inti CPE.","lessons":[{"h":"Apa itu BB","t":"Bollinger Bands = SMA tengah (seringkali 20) + band atas/bawah pada deviasi standar N (seringkali 2). Batasan melebar ketika volatilitas meningkat dan menyempit ketika pasar tenang."},{"h":"Jalur tengah","t":"Garis tengah adalah mean. Harga di atas tengah seringkali menunjukkan tekanan bullish; di bawah ini menunjukkan tekanan bearish. Gunakan itu sebagai garis bias dinamis, bukan pembelian/penjualan ajaib."},{"h":"Pita bawah (latihan BELI)","t":"Memberi label harga pada pita bawah setelah penurunan dapat berarti “meregangkan ke bawah”. JANGAN membeli setiap sentuhan. Tunggu candle bullish (Hammer, Engulfing) dan idealnya RSI muncul."},{"h":"Pita atas (JUAL / hati-hati)","t":"Memberi label harga pada pita atas dapat berarti “meregangkan”. Dalam tren naik, harga bisa naik ke jalur atas (walk-the-band). Lebih suka ide JUAL hanya dengan candle bearish + kelemahan TF lebih tinggi."},{"h":"Meremas","t":"Pita sempit = volatilitas rendah → sering terjadi penembusan. Jangan menebak arah dalam keadaan terjepit; tandai breakout dan konfirmasi dengan candle + volume jika tersedia."},{"h":"Berjalanlah dalam band","t":"Dalam tren yang kuat, harga berada di garis atas (atau bawah) untuk banyak candle. Melawannya dengan mean-reversion fades adalah kesalahan umum pemula."},{"h":"BB + Lab Bagan","t":"Di CPE Chart Lab / meja, pelajari BB dengan candle di DEMO. Latihan: pita bawah + Palu → Paper Trade dengan SL di bawah sumbu, TP1 dekat pita tengah."},{"h":"Kombinasi BB+RSI","t":"Filter praktik yang lebih kuat: BB lebih rendah + RSI oversold (atau naik dari oversold) + candle bullish. BB atas + RSI overbought + candle bearish untuk latihan singkat."},{"h":"Hentikan penempatan","t":"Latihan panjang: SL di bawah ayunan rendah / di bawah sumbu pita bawah. Latihan singkat: SL diatas swing high. Jangan pernah memasuki perdagangan BB tanpa SL tertulis."},{"h":"Target","t":"Jalur umum: TP1 di jalur tengah, TP2 menuju jalur atau jalur berlawanan. Perluas skalanya — tidak perlu seluruh langkah."},{"h":"Kerangka waktu","t":"Tentukan bias pada TF yang lebih tinggi (4H/1D). Masukkan pada BB 15m/30m + candle. Mencampur TF acak menyebabkan sinyal yang bertentangan."},{"h":"Kesalahan yang harus dihindari","t":"Membeli setiap sentuhan harga yang lebih rendah di pasar yang sedang jatuh; menjual setiap sentuhan terbaik dalam perjalanan bulan; tidak ada SL; mengabaikan lonjakan berita yang memperluas jangkauan secara drastis."},{"h":"Daftar periksa latihan","t":"① Bias TF lebih tinggi ② Sentuhan atau pencetan BB ③ Konfirmasi candle ④ RSI setuju ⑤ % risiko ditetapkan ⑥ Makalah terlebih dahulu ⑦ Hasil jurnal."}]},{"id":"rsi","title":"2 · RSI (Indeks Kekuatan Relatif)","summary":"Osilator momentum 0–100. Default 14 periode. Gunakan dengan BB dan candle — jangan pernah RSI sendirian sebagai sistem lengkap.","lessons":[{"h":"Apa yang diukur RSI","t":"RSI membandingkan keuntungan rata-rata vs kerugian pada N bar. RSI tinggi = momentum bullish terkini; RSI rendah = momentum bearish terkini. Ini bukan “overbought = must sell” setiap saat."},{"h":"Zona klasik","t":"Seringkali: di atas 70 = zona overbought, di bawah 30 = zona oversold. Dalam tren yang kuat, RSI bisa berada dalam kondisi jenuh beli/jenuh jual dalam jangka waktu lama — hal ini normal."},{"h":"Garis tengah 50","t":"RSI yang melintasi di atas 50 dapat mendukung bias bullish; bias bearish di bawah 50. Banyak pedagang menggunakan 50 sebagai filter tren dengan pita tengah BB."},{"h":"Divergensi — bullish","t":"Harga menjadi lebih rendah menjadi rendah, RSI menjadi lebih tinggi menjadi rendah → momentum melemah pada sisi bawah. Masih menunggu candle + struktur pecah sebelum entri Paper."},{"h":"Divergensi — kasar","t":"Harga semakin tinggi, RSI semakin rendah → momentum kenaikan memudar. Konfirmasikan dengan Shooting Star / Engulfing di dekat resistance atau BB atas."},{"h":"Perubahan kegagalan","t":"RSI gagal menguji ulang titik ekstrim sebelumnya kemudian melintasi kembali angka 50 - petunjuk awal pergeseran momentum. Kombinasikan dengan struktur Chart Lab."},{"h":"RSI + BB (gaya CPE)","t":"Latihan long: harga mendekati BB yang lebih rendah, RSI ≤ 35 (atau naik dari ≤ 30), candle bullish. Latihan singkat: BB atas, RSI ≥ 65–70, candle bearish."},{"h":"Divergensi yang tersembunyi","t":"Petunjuk kelanjutan tren (misalnya harga lebih tinggi rendah, RSI lebih rendah rendah dalam tren naik). Tingkat Lanjut — kuasai divergensi klasik terlebih dahulu di DEMO."},{"h":"Pengaturan","t":"RSI(14) adalah default umum. RSI yang lebih pendek = lebih banyak noise. Jangan terus-menerus mengubah pengaturan untuk memaksakan sinyal."},{"h":"Keluar dengan RSI","t":"Jika Anda membeli saat oversold, mengambil keuntungan sebagian saat RSI mencapai zona tengah/atas adalah hal yang wajar. Telusuri sisanya dengan struktur atau BB tengah."},{"h":"Berita & RSI","t":"Berita besar dapat meningkatkan RSI secara instan. Lebih suka menunggu hingga candle kekerasan pertama selesai sebelum bertindak pada RSI ekstrem."},{"h":"Kesalahan","t":"Memperpendek setiap RSI>70 di pasar bullish; merindukan setiap RSI<30 dalam kondisi bearish; tidak ada pertemuan; balas dendam masuk kembali ketika RSI “terlihat lebih baik.”"},{"h":"Daftar periksa latihan","t":"① Catat nilai RSI + kemiringan ② Periksa lokasi BB ③ Konfirmasi candle ④ TF lebih tinggi ⑤ Kertas + jurnal ⑥ Satu ide dalam satu waktu."}]},{"id":"fib","title":"3 · Fibonacci (Retracement & Ekstensi)","summary":"Ukur kemunduran dan target dari ayunan tinggi → ayunan rendah (atau mundur). Fokus pada 38.2 · 50 · 61.8 dengan pertemuan BB/RSI.","lessons":[{"h":"Mengapa Fib digunakan","t":"Banyak pedagang memperhatikan rasio yang sama, sehingga likuiditas sering kali bereaksi mendekati rasio tersebut. Fib adalah peta kemungkinan zona — bukan jaminan."},{"h":"Titik ayunan","t":"Selalu menggambar dari ayunan rendah ke ayunan tinggi (gerakan naik) atau tinggi ke rendah (gerakan turun). Ayunan yang buruk = level yang tidak berguna. Berlatih memilih ayunan di Chart Lab DEMO."},{"h":"Retracement kunci","t":"Umum: 23,6% (dangkal), 38,2%, 50% (bukan Fib murni tetapi banyak digunakan), 61,8% (emas), 78,6% (dalam). Penelusuran kembali yang dalam dapat menandakan kelemahan tren."},{"h":"Pembelian mundur (tren naik)","t":"Setelah dorongan ke atas, tunggu pullback ke zona 38.2–61.8 + candle bullish + sebaiknya support menengah/bawah BB atau RSI bertahan >40–45."},{"h":"Penjualan mundur (tren turun)","t":"Setelah dorongan turun, reli ke 38.2–61.8 + candle bearish + RSI gagal di bawah 55–60."},{"h":"Perluasan/target","t":"Perluasan umum: 127,2%, 161,8% melampaui ayunan ide TP2. Gunakan dengan jejak — jangan memaksakan tanda centang yang tepat."},{"h":"Pertemuan = kekuatan","t":"Zona praktik terbaik: Fib 50/61.8 + BB tengah/bawah + struktur sebelumnya + putaran RSI. Satu garis Fib saja sudah lemah."},{"h":"Fib + BB","t":"Jika 61,8% berada di dekat BB yang lebih rendah dalam tren naik, tumpang tindih tersebut adalah zona studi Paper berkualitas tinggi. Masuk hanya dengan konfirmasi lilin."},{"h":"Beberapa Fib","t":"Pemula harus menggunakan SATU ayunan bersih. Menumpuk 5 Fib menciptakan noise grafik dan entri FOMO."},{"h":"Pembatalan","t":"Jika harga ditutup dengan jelas melampaui 78,6% terhadap bias Anda, tesis kemunduran sering kali gagal — keluar atau menyingkir."},{"h":"Valas vs kripto","t":"Rasio yang sama. Mata uang utama Forex sering kali mengikuti level dengan lebih rapi dalam sesi likuid; crypto dapat melewatinya lalu membalikkannya — ukurannya lebih kecil."},{"h":"Kesalahan","t":"Menggambar Fib pada ayunan kebisingan kecil; memasuki udara tanpa lilin; memindahkan SL lebih jauh ketika Fib “hampir” tertahan; mengabaikan TF yang lebih tinggi."},{"h":"Daftar periksa latihan","t":"① Mark swing ② Note 38.2/50/61.8 ③ Tunggu harga tiba ④ Candle + RSI/BB ⑤ Risk set ⑥ Paper → jurnal."}]},{"id":"money","title":"4 · Pengelolaan Uang","summary":"Bagaimana metode ini sebenarnya digunakan: mempertaruhkan persentase tetap, ukuran dari stop, menyimpan sebagian keuntungan, dan stop untuk hari setelah batas kerugian. CPE dapat menerapkan ini pada perdagangan manual dan otomatis.","lessons":[{"h":"Tujuan pengelolaan uang","t":"Tetap dalam permainan. Satu perdagangan yang buruk tidak boleh menghapus akun. Konsistensi mengalahkan ukuran lotere."},{"h":"Bagaimana pedagang sebenarnya menggunakannya","t":"Praktik yang umum adalah risiko pecahan tetap. Anda tidak memilih jumlah koin terlebih dahulu. Anda menulis pemberhentiannya terlebih dahulu, memutuskan bahwa ide ini mungkin akan kehilangan sekitar 1% dari akun Anda, kemudian ukurannya akan berkurang. Perhentian lebar mendapat posisi lebih kecil. Perhentian yang ketat akan mendapatkan posisi yang lebih besar, dan risiko dolar tetap sama. Ini adalah metode yang digunakan CPE ketika tanda pengelolaan uang aktif."},{"h":"Contoh yang berhasil ($1000 akun latihan)","t":"Akun $1000. Risiko 1% = $10. Masuk 100, berhenti 98. Jarak = 2%. Ukuran = 10 0,02 = nosional $500. Jika stop tercapai, kerugiannya sekitar $10, bukan $500. Jika harga mencapai 103 (risiko 1,5 kali), keuntungannya sekitar $15. Ide yang sama pada setiap pasangan: risiko dolar tetap mendekati 1%, kuantitas koin berubah."},{"h":"Apa yang dilakukan CPE dengan tanda centang","t":"Berdagang Sekarang → Otomatis: centang “Gunakan pengelolaan uang”. Simpan Konfigurasi Otomatis. Setiap perdagangan otomatis baru kemudian menggunakan sekitar 1% dari akun latihan $1000 ditambah hasil yang ditutup, diukur dari entri sinyal dan SL tersebut. Nilai minimum spot dan kontrak berjangka dipatuhi: jika nilai minimum bursa akan berisiko lebih dari 1%, perdagangan tersebut dilewati. Setelah sekitar −2% pada hari kalender, mobil baru berhenti hingga hari berikutnya. Paling banyak sekitar 3% beresiko di seluruh perdagangan terbuka. Perdagangan Manual memiliki tanda centang yang sama. Riwayat Sinyal masih menunjukkan pengujian yang sama dengan $10, dan di bawahnya terdapat ukuran paket 1% untuk akun $1000, sehingga Anda dapat melihat keduanya."},{"h":"Keuntungan sebagian dan jejaknya","t":"Latihannya adalah dengan mengambil bagian pada target pertama (seringkali sekitar setengahnya) dan membiarkan sisanya mengikuti. Saat stop bergerak naik, target juga bisa bergerak, sehingga pemenang bisa membayar lebih dari target pertama. Risiko pada ide awal tidak meningkat. Sinyal yang kuat bukanlah alasan untuk mengambil risiko 5%. 1% yang sama digunakan. Jejak inilah yang membuat pemenang yang kuat bisa bertumbuh."},{"h":"Berhenti setiap hari dan panas terbuka","t":"Aturan yang digunakan: jika hari ini turun sekitar 2% dari akun, hentikan pembukaan perdagangan. Tiga ide terbuka masing-masing 1% adalah sekitar 3% panas. Lima koin yang berkorelasi adalah satu taruhan, bukan lima. Hitung bersama-sama."},{"h":"Apa yang ditolak metode ini","t":"Martingale (menggandakan setelah kalah) tidak digunakan. Memindahkan perhentian lebih jauh untuk “memberi ruang” setelah masuk tidak digunakan. All-in pada sinyal “pasti” tidak digunakan. Jika tidak ada stop yang valid, maka tidak ada ukuran, sehingga tidak ada perdagangan."},{"h":"Risiko per perdagangan","t":"Aturan umum: risiko hanya ~0,5–1% ekuitas akun pada satu ide. Di DEMO, praktikkan kebiasaan persentase yang sama seperti LIVE."},{"h":"Rumus ukuran posisi","t":"Ukuran ≈ (Akun × Risiko%) (Masuk − Jarak berhenti). SL lebih lebar → ukuran lebih kecil. Jangan pernah memilih ukuran terlebih dahulu dan SL kedua."},{"h":"Resiko : Imbalan","t":"Lebih menyukai gagasan yang potensi imbalannya ≥ risiko (misalnya 1:1.5 atau lebih baik) saat belajar. Perluas skala pada TP1 sehingga pelari “bebas risiko.”"},{"h":"Pengambilan keuntungan sebagian","t":"Gaya CPE: TP1 mengunci sebagian keuntungan, TP2 / jejak untuk sisanya. Perbankan parsial mengurangi kepanikan emosional."},{"h":"Tertinggal TP + SL","t":"BELI: jejak naik seiring kenaikan harga. JUAL: turun. Trailing mengunci keuntungan terbuka tanpa memerlukan exit call yang sempurna."},{"h":"Batas kerugian harian/mingguan","t":"Contoh aturan: hentikan perdagangan pada hari setelah akun −2%. Sesi balas dendam setelah batas kerugian adalah pembunuh akun."},{"h":"Ukuran titik","t":"Nosional spot min penting (misalnya min pertukaran). Tetap terapkan% risiko: jika ukuran minimum berisiko terlalu besar vs SL Anda, lewati perdagangan."},{"h":"Kontrak berjangka / leverage","t":"Leverage melipatgandakan keuntungan dan kerugian. Leverage tinggi + SL lebar = akun rusak. Lebih memilih leverage yang rendah saat belajar; Terisolasi dapat membatasi kerugian per posisi."},{"h":"Korelasi","t":"Membuka 5 alts BTC yang berkorelasi = satu taruhan besar, bukan lima. Hitung risiko sebagai sebuah kelompok."},{"h":"Biaya & selip","t":"Kulit kepala yang ketat terlihat bagus di grafik tetapi biayanya memakan R:R. Lebih suka ayunan yang lebih bersih di DEMO sampai Anda mengetahui biayanya."},{"h":"DEMO → Jembatan LANGSUNG","t":"Latihan CPE DEMO (~ pola pikir 3 bulan): aturan jurnal sama, % sama. Saat LIVE, mulai setengah ukuran DEMO untuk minggu pertama."},{"h":"Keamanan uang API","t":"Penarikan OFF pada setiap tombol. Hidup hanya setelah Akun Uji OK di platform yang cocok. Rahasia platform salah = operasi gagal atau berbahaya."},{"h":"Kesalahan","t":"Martingale (ganda setelah kalah); memindahkan SL lebih jauh; all-in pada pengaturan “pasti”; mengabaikan ukuran minimum vs risiko%; berdagang tanpa henti setiap hari."},{"h":"Daftar periksa latihan","t":"① % Resiko tertulis ② Ukuran dari jarak SL ③ TP1/TP2/jalur yang direncanakan ④ Kerugian harian maksimal diketahui ⑤ Makalah pertama ⑥ Jurnal PnL jujur."}]},{"id":"psych","title":"5 · Psikologi untuk Trading","summary":"Pola pikir menentukan apakah keterampilan BB/RSI/Fib bertahan di layar nyata. FOMO, balas dendam, terlalu percaya diri, ketakutan - latih ini pada indikator seperti DEMO.","lessons":[{"h":"Mengapa psikologi penting","t":"Paket BB+RSI yang sempurna akan gagal jika Anda masuk lebih awal, melewatkan SL, atau melakukan perdagangan balas dendam. Keterampilan = sistem × disiplin."},{"h":"Proses melebihi prediksi","t":"Anda tidak perlu memprediksi masa depan. Anda perlu mengikuti aturan: pengaturan → risiko → pengelolaan → jurnal. Hasilnya bervariasi; proses dapat dikontrol."},{"h":"FOMO","t":"Takut ketinggalan = mengejar candle hijau yang sudah jauh dari zona BB/Fib. Aturan: jika Anda melewatkan entri, tunggu pengaturan berikutnya. Chart Lab selalu memiliki candle lain."},{"h":"Perdagangan balas dendam","t":"Setelah mengalami kekalahan, dorongan untuk “memenangkannya kembali sekarang” menghancurkan banyak hal. Pendinginan wajib: pergi, catat kerugiannya, perdagangan berikutnya hanya jika daftar periksa sudah bersih."},{"h":"Terlalu percaya diri setelah menang","t":"3 kemenangan berturut-turut ≠ menambah ukuran 5×. Pertahankan% risiko tetap. Kemenangan beruntun adalah saat kebanyakan orang melanggar aturan uang."},{"h":"Ketakutan setelah kehilangan","t":"Melewatkan setiap pengaturan yang valid setelah hari merah juga merupakan bias. Percayai rencana tertulis; kurangi ukuran sementara jika diperlukan, jangan tinggalkan proses."},{"h":"Kelumpuhan analisis","t":"10 indikator tidak setuju → membekukan. Tetap berpegang pada inti CPE: candle + BB + RSI (+ zona Fib). Kualitas melebihi kuantitas alat."},{"h":"Miringkan & berita","t":"Lilin merah besar di berita meningkatkan adrenalin. Lebih suka datar selama hal-hal besar yang tidak diketahui sampai reformasi struktur — ego menginginkan tindakan; rencana menginginkan kesabaran."},{"h":"Jurnal = terapi + data","t":"Tulis tag emosi (FOMO, terburu-buru, tenang) di Jurnal CPE. Pola perasaan mengungkap kebocoran lebih cepat daripada PnL saja."},{"h":"Aturan tertulis","t":"Kalau tidak tertulis maka itu bukan aturan. Contoh: “Hanya BB+candle+RSI; risiko 1%; tidak ada perdagangan setelah −2% hari; DEMO hingga checklist 20 makalah.”"},{"h":"Lingkungan Hidup","t":"Tidur, lapar, dan gangguan telepon mengubah keputusan. Jangan menambah ukuran saat habis. Trading itu bersifat atletik — lindungi otak."},{"h":"Kebisingan sosial","t":"“Sinyal” dan hype Telegram merusak rencana Anda. Kelas Pembelajaran CPE + jurnal Anda > tips acak. Filter Berita & Trik berdasarkan konteks, bukan perintah."},{"h":"Pergeseran identitas","t":"Pikirkan “Saya mengikuti daftar periksa saya” bukan “Saya pasti benar.” Melakukan kesalahan dengan risiko kecil adalah hal yang wajar; keras kepala dengan risiko besar adalah opsional."},{"h":"DEMO sebagai gimnasium","t":"Gunakan DEMO/Kertas untuk melatih emosi dengan aman. Jika Anda tidak bisa mengikuti peraturan di DEMO, LIVE tidak akan secara ajaib memperbaiki disiplin."},{"h":"Daftar periksa latihan","t":"① Apakah saya tenang? ② Daftar periksa selesai? ③ % Risiko tidak berubah? ④ Bukan balas dendam? ⑤ Apakah saya akan membuat jurnal dengan jujur? Jika ada TIDAK → tidak ada perdagangan."}]},{"id":"signals","title":"6 · Sinyal CPE — makna & apa yang harus dilakukan","summary":"Tabel Spot / Futures / Forex menunjukkan BELI · JUAL · TAHAN + skor. Ide mesin yang sama di setiap platform — tetapi Anda hanya berdagang di platform yang kunci API-nya Anda simpan. Berikut arti setiap sinyal dan langkah pastinya setelah muncul.","lessons":[{"h":"Dari mana sinyal berasal","t":"Skor CPE BB, RSI, Fibonacci, candle stick, EMA cross, SMA50, MACD dan momentum. Skor ≥ +3 → BELI. Skor ≤ −3 → JUAL. Di antara → TAHAN. Ini adalah peringkat pembantu — bukan janji keuntungan."},{"h":"Sinyal BELI — artinya","t":"Pertemuan bullish lebih kuat saat ini (contoh: pemantulan BB yang lebih rendah, perubahan oversold RSI, candle bullish, golden cross, support Fib). Disarankan TP1/TP2/SL muncul pada baris / Chart Lab / Trade Now."},{"h":"Sinyal JUAL — artinya","t":"Pertemuan bearish lebih kuat (BB atas / RSI overbought / candle bearish / death cross / resistensi Fib). Di Spot, SELL biasanya berarti keluar/mengurangi posisi long atau short hanya jika pasar Anda mengizinkan posisi short (Futures/Forex)."},{"h":"Sinyal TAHAN — artinya","t":"Skor campuran atau lemah. JANGAN memaksakan perdagangan. Datar benar. Watchlist ★ dan tunggu calon BUY/SELL atau BB Lower yang lebih jelas."},{"h":"Nomor skor","t":"|skor| lebih tinggi = lebih banyak kesepakatan antar alat. BELI +5 lebih kuat dari BELI +3 — masih konfirmasi pada candle Chart Lab sebelum ukurannya."},{"h":"BB Papan bawah","t":"Daftar terpisah dari pasangan yang menandai pita bawah Bollinger — praktikkan kandidat panjang. Masih memerlukan konfirmasi candle + RSI; tidak setiap sentuhan yang lebih rendah merupakan sebuah entri."},{"h":"Platform vs sinyal (penting)","t":"Matematika sinyal adalah ide yang sama di Binance, Bybit, OKX, KuCoin, Bitget, Gate, MEXC, Kraken, Coinbase, OANDA, FXCM, MT5, Forex Demo. Yang berubah adalah DI MANA Anda mengirim pesanan: hanya platform yang dipilih di Kunci API/Perdagangkan Sekarang. BELI Binance tidak terbuka di Bybit."},{"h":"Platform Kripto Spot","t":"Binance Spot, Coinbase, dll.: BELI = beli koin dengan penawaran harga (misalnya USDT). JUAL = jual kepemilikan / ambil untung. Ukuran minimum (misalnya ~$11) penting. Tidak ada pengaruh."},{"h":"Platform Kripto Berjangka","t":"Binance Futures, Bybit, OKX, Bitget…: BELI = panjang; JUAL = pendek. Pilih Cross/Isolated + leverage dengan hati-hati. Jalur: BELI jalur TP+SL naik; JUAL menurun."},{"h":"Platform valas","t":"OANDA / FXCM / MT5 / Demo Forex: label BELI/JUAL/TAHAN yang sama pada pasangan FX (EURUSD…). BELI = beli mata uang dasar; JUAL = dasar jual. Banyak (misalnya 0,01) bukan jumlah koin. Sesi & berita lebih penting."},{"h":"Saat BELI muncul — lakukan ini","t":"① Buka baris → baca Why / candle / RSI. ② Konfirmasi Chart Lab (15m–1H). ③ DEMO terlebih dahulu: Trading Sekarang → atur TP1/TP2/SL/trail → Mulai Demo/Paper. ④ Hanya setelah Uji API OK di platform itu → LIVE kecil. ⑤ Hasil jurnal."},{"h":"Ketika JUAL muncul — lakukan ini","t":"① Jika Anda sedang membeli Spot: pertimbangkan TP / penutupan sebagian / jejak — jangan abaikan. ② Jika Futures/Forex dan plan memungkinkan short: konfirmasikan Chart Lab lalu Paper/Live short dengan SL. ③ Jika HOLD kemarin lebih baik, jangan balas dendam ukuran flip."},{"h":"Saat HOLD muncul — lakukan ini","t":"Tidak ada entri Manual baru. Terus memindai. Tambahkan ★ daftar pantauan. Kelas Pembelajaran Kajian / Lab Bagan. Lindungi posisi terbuka dengan jejak hanya jika sudah dalam perdagangan."},{"h":"Perdagangan Otomatis + sinyal","t":"BELI Otomatis dapat terbuka ketika aturan skor BB Lebih Rendah + kuat cocok dengan konfigurasi Otomatis yang Anda simpan. Masih DEMO-test Auto dulu. LIVE Otomatis = risiko nyata — Penarikan MATI, ukuran kecil."},{"h":"Pemberitahuan","t":"BELI Signal bersulang mengikuti bahasa Anda. Perlakukan hal tersebut sebagai peringatan untuk membuka perdagangan — bukan sebagai perintah pasar saja."},{"h":"Apa yang TIDAK boleh dilakukan","t":"Jangan membeli setiap BELI tanpa grafik. Jangan gunakan kunci Binance di Bybit. Jangan lewatkan SL. Jangan menaikkan ukuran setelah satu sinyal hijau. Jangan memperdagangkan HOLD sebagai “hampir BELI”."},{"h":"Kartu tindakan cepat","t":"Sinyal → Lab Grafik → % Risiko → TP1/TP2/SL → Makalah DEMO → Jurnal → (nanti) LANGSUNG pada kunci platform yang cocok."}]},{"id":"forex_sig","title":"7 · Sinyal forex — arti & apa yang harus dilakukan","summary":"Forex Desk menggunakan peringkat BELI / JUAL / TAHAN yang sama pada pasangan FX. Pelajari perbedaan sinyal forex dengan kripto, dan langkah pastinya dari sinyal → Kertas → broker langsung.","lessons":[{"h":"Sinyal Meja Forex","t":"EURUSD, GBPUSD, USDJPY… dapatkan skor BELI / JUAL / TAHAN + seperti kripto. Klik baris untuk bagan, teks psikologi, dan level yang disarankan."},{"h":"BELI di Forex — artinya","t":"Beli mata uang dasar (misalnya BELI EURUSD = beli EUR vs USD). Harapkan harga naik. Gunakan interval Chart Lab Forex Anda berlatih (15m/30m/1H)."},{"h":"JUAL di Forex — artinya","t":"Jual basisnya (pendekkan pasangannya). Harapkan harga turun. Selalu atur SL di atas struktur/ide pita atas."},{"h":"TAHAN di Forex","t":"Tidak ada batas yang jelas — lewati. Apalagi sebelum berita besar (NFP, CPI, bank sentral) lebih memilih HOLD/flat."},{"h":"Platform Tarif Demo Forex","t":"Tidak ada kunci API. Grafik latihan + Kertas saja. Sempurna untuk latihan Kelas Belajar sebelum OANDA/FXCM/MT5 live."},{"h":"Sinyal OANDA → tindakan","t":"① Meja Forex BELI/JUAL. ② Konfirmasi Lab Bagan. ③ Kunci API → Token OANDA + ID Akun → Tes. ④ Makalah DEMO di CPE terlebih dahulu. ⑤ Kavling kecil (pola pikir 0,01) dengan TP/SL/trail."},{"h":"FXCM / MT5","t":"Pembacaan sinyal yang sama. Hubungkan kredensial broker tersebut di bawah Kunci API. Signal tidak melakukan login otomatis ke MT5 untuk Anda hingga kunci/jembatan disetel — latihan Kertas hingga Tes OK."},{"h":"Sesi","t":"Tumpang tindih London-NY sering kali lebih menggerakkan negara-negara besar. Asia mungkin lebih tenang — HOLD merupakan hal yang umum dan menyehatkan."},{"h":"Penyebaran & berita","t":"Sehubungan dengan berita, spread melebar — teknik BELI yang baik masih bisa menjadi hasil yang buruk. Periksa Berita & Trik; tunggu candle tutup setelah lonjakan."},{"h":"Banyak vs jumlah kripto","t":"Ukuran valas = lot, bukan nosional USDT dengan cara yang sama. % Risiko masih berlaku: SL lebih lebar → lot lebih kecil."},{"h":"BB Lebih Rendah di Forex","t":"Ide yang sama: pasangkan di dekat pita bawah + Hammer + RSI naik = latihan belajar panjang. Konfirmasikan bias TF yang lebih tinggi (4 Jam/Harian)."},{"h":"Saat BELI Forex terjadi — langkah-langkah","t":"① Baca Alasannya. ② Bias TF lebih tinggi oke? ③ Tandai SL di luar sumbu/struktur. ④ Perdagangan kertas. ⑤ Jika broker langsung siap → ukuran kecil + jejak. ⑥ Sesi jurnal (London/NY) + emosi."},{"h":"Saat Forex SELL menyala — langkah","t":"① Konfirmasikan bukan lonjakan berita di tengah-tengah. ② Lilin bearish Chart Lab. ③ Kertas pendek atau pendek. ④ Turun jika pendek. ⑤ Jangan menggandakan lot setelah gagal."},{"h":"Perbedaan Forex vs Kripto","t":"Kripto 24/7; Forex memiliki sesi. Kripto min $ sering; Lot forex + nilai pip. Crypto banyak yang berkorelasi; Jurusan forex lebih bersih untuk belajar."},{"h":"Daftar periksa latihan (FX)","t":"① Pasangan mayor? ② Sesi oke? ③ Berita jelas? ④ Sinyal BELI/JUAL tidak TAHAN? ⑤ Konfirmasi grafik? ⑥% Risiko? ⑦ Kertas → jurnal → kunci broker langsung hanya jika sudah siap."}]},{"id":"fomo","title":"8 · FOMO & Disiplin Emosional","summary":"FOMO, balas dendam, keserakahan, dan ketakutan adalah pembunuh akun yang sebenarnya — bukan indikator. Pelajari pemicunya, tanda-tanda tubuh, dan aturan pasti yang mencegah perdagangan impulsif masuk ke akun Anda.","lessons":[{"h":"Apa sebenarnya FOMO itu","t":"FOMO = takut ketinggalan pergerakan yang sudah jauh dari zona Anda. Itu membuat Anda terlambat masuk dengan harga yang lebih buruk dan tidak ada SL yang tepat. Lilin yang Anda “lewatkan” adalah informasi, bukan kerugian."},{"h":"Tiga pemicu FOMO","t":"① Lilin hijau atau merah besar pada grafik. ② Postingan teman atau Telegram menunjukkan keuntungan. ③ Judul berita. Perhatikan pemicunya sebelum Anda memperhatikan entri tersebut."},{"h":"Tanda-tanda tubuh","t":"Detak jantung yang cepat, bersandar ke layar, keinginan untuk mengklik pasar-beli-sekarang, melewatkan daftar periksa Anda. Jika Anda merasakannya, tutup tab dan tunggu satu candle."},{"h":"Aturan “sudah berjalan”.","t":"Jika harga telah bergerak lebih dari 1 ATR melewati rencana masuk Anda, perdagangan tersebut hilang. Tunggu pullback ke BB mid/Fib atau skip saja. Selalu ada pengaturan lain."},{"h":"Perangkap lilin hijau","t":"Marubozu yang tidak Anda rencanakan adalah pengejaran, bukan entri. Entri yang terlambat memiliki imbalan terburuk: risiko karena pemberhentiannya jauh sekali."},{"h":"Perdagangan balas dendam","t":"Setelah mengalami kekalahan, otak ingin memenangkannya kembali sekarang. Aturan: tidak ada entri baru selama 15–30 menit setelah kekalahan, dan hanya jika daftar periksanya bersih. Pasar tidak berhutang apa pun kepada Anda."},{"h":"Takut menarik pelatuknya","t":"Masalah sebaliknya: pengaturan sempurna muncul dan Anda terhenti. Gunakan ukuran DEMO kecil untuk membuktikan prosesnya, dan tentukan ukuran Anda SEBELUM lilin muncul sehingga keputusan sudah dibuat."},{"h":"Keserakahan demi kemenangan","t":"Dua perdagangan hijau membuat Anda merasa tak terkalahkan, lalu Anda menggandakannya. Pertahankan % risiko tetap untuk setidaknya 20 perdagangan; kemenangan beruntun berarti kembali."},{"h":"Perdagangan kebosanan","t":"Datar adalah sebuah posisi. Jika tidak ada pengaturan A+, jangan lakukan sesuatu. Perdagangan kebosanan adalah FOMO yang menyamar."},{"h":"Disiplin waktu layar","t":"Atur dua atau tiga jendela pemindaian sehari alih-alih menatap grafik. Lebih sedikit keputusan berarti lebih sedikit keputusan impulsif."},{"h":"Jurnal emosional","t":"Tandai setiap perdagangan dengan tenang / terburu-buru / FOMO / balas dendam. Setelah 20 perdagangan, pola kebocoran Anda menjadi jelas."},{"h":"Setel ulang ritual","t":"Setelah kalah atau terpeleset FOMO: berdiri, ambil 10 napas perlahan, tulis satu kalimat tentang apa yang terjadi, lalu berhenti selama satu jam atau lanjutkan dengan setengah risiko normal."},{"h":"Daftar periksa latihan","t":"① Tubuh tenang? ② Pemicu memperhatikan? ③ Pengaturan di zona saya? ④ SL ditulis terlebih dahulu? ⑤ % Risiko tidak berubah? ⑥ Bukan balas dendam? TIDAK apa pun → tidak ada perdagangan."}]},{"id":"risk_deep","title":"9 · Manajemen Risiko & Uang — mendalam","summary":"Matematika yang membuat akun tetap hidup: ukuran pecahan tetap, kelipatan R, matematika penarikan, panas korelasi, dan pemberhentian harian. Ubah perdagangan menjadi bisnis yang dijalankan dengan angka.","lessons":[{"h":"Risiko pecahan tetap","t":"Risiko sebesar % (0,5–1%) ekuitas per ide. Ukuran adalah HASIL dari jarak berhenti, tidak pernah dipilih terlebih dahulu. SL lebar → ukuran kecil; SL ketat → ukuran lebih besar; risiko dolar tetap sama."},{"h":"Rumus ukurannya","t":"Ukuran = (Ekuitas × Risiko%) |Masuk − Berhenti|. Contoh: $1000 × 1% = $10 risiko. Masuk 100, berhenti 98 → jarak 2% → ukuran 10 0,02 = nosional $500."},{"h":"Pikirkan dalam kelipatan R","t":"Risiko 1R per perdagangan. Pemenang 2R membayar dua kekalahan. Lacak R rata-rata Anda dalam 20 perdagangan — itulah keunggulan Anda yang sebenarnya, bukan tingkat kemenangan."},{"h":"Hadiah : risiko","t":"Targetkan setidaknya potensi 1,5R sebelum masuk. Di bawah itu, lewati kecuali tingkat kemenangan Anda sangat tinggi."},{"h":"Matematika penarikan","t":"Penarikan −50% membutuhkan +100% untuk pulih. Kalah beruntun adalah hal yang normal: bahkan sistem dengan tingkat kemenangan 60% memiliki 5+ kekalahan. Risiko kecil membuat rekor tersebut tetap bertahan."},{"h":"Perhentian harian","t":"Aturan kerasnya: hentikan pembukaan perdagangan setelah −2% ekuitas dalam sehari (atau 2–3 kerugian berturut-turut). Sesi balas dendam setelah batas adalah pembunuh akun."},{"h":"Batas mingguan dan bulanan","t":"Batasi juga minggunya (misalnya −5%) dan bulannya. Saat terkena, turunkan ke DEMO, tinjau jurnal, lalu ukur kembali hanya setelah proses bersih."},{"h":"Buka panas","t":"Risiko total di seluruh perdagangan terbuka harus tetap berada di sekitar 3% atau kurang. Lima alts yang berkorelasi adalah satu taruhan, bukan lima — hitung eksposur yang berkorelasi bersama-sama."},{"h":"Ukuran titik","t":"Spot memiliki nosional minimum. Jika nilai minimum pertukaran akan menimbulkan risiko lebih dari 1%, lewati perdagangan — jangan pernah membulatkan risiko ke atas."},{"h":"Ukuran berjangka","t":"Leverage mengubah margin, bukan risiko. Risiko masih Masuk - Hentikan × ukuran. Gunakan leverage rendah saat belajar dan pilih margin terisolasi."},{"h":"Ukuran valas","t":"Risiko = lot × nilai pip × stop-pips. Selesaikan banyak hal. Panduan kasar: 0,01 lot ≈ $0,10 per pip; stop 20 pip dengan risiko 1% dari $1000 ($10) → 10 0,10 20 = 0,05 lot."},{"h":"Memperluas","t":"Ambil diskon sekitar 50% di TP1 agar sisanya bebas risiko, lalu ikuti. Hal ini mengubah perdagangan yang baik menjadi pelari dengan tingkat stres yang rendah."},{"h":"Peracikan vs tetap","t":"Risiko sebesar % tetap dari ekuitas SAAT INI (majemuk). Jangan tetapkan risiko Anda pada ukuran akun tertinggi sepanjang masa."},{"h":"Biaya dan slippage di R","t":"Kurangi biaya dari R. Biaya 0,2% terhadap kulit kepala 0,5% dapat menghapus batas - lebih memilih ayunan yang lebih bersih."},{"h":"Undang-undang “tidak ada henti, tidak ada perdagangan”.","t":"Jika Anda tidak dapat menentukan penghentian yang logis, Anda tidak mengetahui risiko Anda, jadi tidak ada ukurannya, sehingga tidak ada perdagangan."},{"h":"Anti-martingale","t":"Jangan pernah menggandakan diri setelah mengalami kekalahan. Tingkatkan ukuran hanya setelah beberapa minggu yang menguntungkan dan disiplin melalui proses yang terbukti — dan itupun secara perlahan."},{"h":"Daftar periksa latihan","t":"① Ekuitas diketahui ② % Risiko tertulis ③ Stop ditentukan ④ Ukuran dari stop ⑤ Hadiah ≥ 1,5R ⑥ Stop harian diketahui ⑦ Panas berkorelasi dihitung."}]},{"id":"sl_tp","title":"10 · Penguasaan Hentikan Kerugian & Ambil Untung","summary":"Tempatkan SL di mana pasar membuktikan bahwa Anda salah, ambil untung secara bertahap, dan ikuti jejaknya sehingga pemenang dapat berlari — persis seperti yang dilakukan CPE dengan multi-TP dan SL tambahan.","lessons":[{"h":"SL adalah sebuah keputusan, bukan sebuah angka","t":"Letakkan stop di tempat idenya tidak valid (di bawah swing low, sumbu, atau struktur), bukan pada jarak dolar acak. Anda membeli informasi: jika harga mengarah ke sini, alasan saya salah."},{"h":"Struktur berhenti","t":"Panjang: SL tepat di bawah sumbu ayunan rendah atau pita bawah. Pendek: tepat di atas ayunan tinggi. Berikan sedikit buffer untuk penyebaran dan kebisingan sumbu, sekitar 0,1–0,3%."},{"h":"Volatilitas berhenti","t":"Pasar yang lebih luas membutuhkan perhentian yang lebih luas. Gunakan ATR atau panjang sumbu untuk mengukur stop, lalu kecilkan posisinya sehingga risiko dolar tetap sama."},{"h":"Mengapa SL dolar tetap gagal","t":"Stop $10 pada BTC dan stop $10 pada EURUSD merupakan risiko yang sangat berbeda. Jarak harus diukur dalam %, bukan dolar."},{"h":"Buffer anti berhenti berburu","t":"CPE mengabaikan satu sentuhan sumbu: memerlukan dua pelanggaran berturut-turut ditambah buffer kecil (0,15%) sebelum ditutup. Itu menghentikan kebisingan memburu perhentian Anda."},{"h":"Ambil keuntungan dalam beberapa langkah","t":"Jangan pernah menutup 100% pada satu harga. Scale out: TP1 membukukan sebagian, lalu TP2/trail ride sisanya sehingga perpindahan besar dapat membayar banyak pecundang."},{"h":"Level multi-TP","t":"CPE memungkinkan Anda menambahkan level TP sebanyak yang Anda perlukan, masing-masing dengan persentase penutupannya sendiri. Contoh: TP1 40%, TP2 30%, TP3 30% — atau ambil TP1 dan ikuti sisanya."},{"h":"Mengikuti halte","t":"Setelah TP1 pindahkan stop ke titik impas; setelah TP2 pindahkan ke TP1. Biarkan stop mengikuti harga sehingga keuntungan terbuka terlindungi sementara pelari melanjutkan."},{"h":"Memilih jalur %","t":"Jalur yang ketat mengunci keuntungan dengan cepat tetapi keluar lebih awal; jejak lebar bernafas tetapi memberi kembali. Mulai sekitar 1–2% untuk kripto dan sesuaikan dengan modal edit Posisi."},{"h":"Pelari","t":"Ketika harga berada dalam tren yang kuat, perluas target dan ikuti daripada mengambil semuanya di TP2. Begitulah cara satu perdagangan menghasilkan keuntungan selama seminggu penuh."},{"h":"Tombol tutup sebagian","t":"Gunakan tombol tutup 50% / 100% di Posisi untuk kontrol manual, atau biarkan Tutup Otomatis mengatur TP/SL sesuai rencana."},{"h":"Perangkap titik impas","t":"Jangan pindahkan SL ke titik impas terlalu dini, sebelum TP1 — kemunduran normal akan membuat Anda keluar dari perdagangan yang bagus."},{"h":"Jangan pernah memperlebar perhentian yang kalah","t":"Memindahkan SL lebih jauh untuk memberikan ruang adalah bagaimana kerugian kecil menjadi pembunuh akun. Perhentian yang Anda tetapkan sebelum masuk adalah perhentian."},{"h":"Waktu berhenti","t":"Jika perdagangan tidak menghasilkan apa-apa untuk banyak candle sementara pengaturannya jelas lebih baik, penutupan datar dan penerapan kembali risiko adalah jalan keluar yang valid."},{"h":"Daftar periksa latihan","t":"① SL pada pembatalan, bukan acak ② Buffer untuk sumbu ③ TP1 direncanakan sebagian ④ Trail setelah TP1 ⑤ Jangan pernah memperlebar SL ⑥ Biarkan pemenang berlari."}]},{"id":"plan_journal","title":"11 · Rencana Perdagangan & Penjurnalan","summary":"Rencana tertulis mengubah perdagangan dari perjudian menjadi sebuah proses. Pelajari rencana satu halaman, daftar periksa pra-perdagangan, dan cara membuat jurnal sehingga kebocoran Anda terlihat.","lessons":[{"h":"Mengapa menulis rencana","t":"Kalau tidak tertulis, maka itu bukan aturan. Sebuah rencana menghilangkan pengambilan keputusan langsung di bawah tekanan dan membuat hasil Anda dapat diukur."},{"h":"Paket satu halaman","t":"Pasangan, pasar, setup (BB + RSI + candle + zona Fib), arah, entri, SL, TP1 / TP2, ukuran (dari SL) dan kerugian harian maksimal. Jika ada baris yang kosong → tidak ada perdagangan."},{"h":"Daftar periksa pra-perdagangan","t":"Bias TF lebih tinggi? · Pengaturan di zona saya? · Konfirmasi lilin? · RSI setuju? · SL tertulis? · Mempertaruhkan %? · Hadiah ≥ 1,5R? · Tenang? Semua ya → berdagang."},{"h":"Rutinitas sebelum sesi","t":"Periksa jangka waktu yang lebih tinggi, level kunci, dan berita. Tuliskan dua atau tiga pasang jam tangan hari ini sebelum sesi — bukan setelah candle meledak."},{"h":"Apa yang harus dijadikan jurnal","t":"Simbol, sisi, masuk, keluar, ukuran, R, alasan, jangka waktu, sesi dan tag emosi. Jurnal CPE menyimpan P/L dan alasannya secara otomatis; tambahkan catatan Anda sendiri."},{"h":"Buat jurnal MENGAPA","t":"Catat apa yang Anda lihat (setup) dan apa yang Anda rasakan (tenang / FOMO / terburu-buru). Hasil tanpa konteks tidak akan mengajarkan apa pun."},{"h":"Lacak R, bukan menang","t":"Dua trader dengan tingkat kemenangan yang sama bisa mendapatkan hasil yang berlawanan. Rata-rata R dan penarikan maksimum lebih penting daripada% kemenangan."},{"h":"Kebiasaan tangkapan layar","t":"Simpan grafik sebelum dan sesudah setiap perdagangan. Meninjau 20 tangkapan layar menunjukkan keunggulan dan kebocoran Anda lebih cepat daripada indikator apa pun."},{"h":"Ulasan mingguan","t":"Seminggu sekali hitung perdagangan Anda, rata-rata R, pengaturan terbaik dan terburuk, dan pelanggaran aturan. Pilih SATU kebocoran untuk diperbaiki minggu depan."},{"h":"Tandai kebocorannya","t":"Tag umum: terlambat masuk, tidak ada SL, kebesaran, SL pindah, balas dendam, kebosanan. Saat sebuah tag diulang, ubahlah menjadi aturan yang tegas."},{"h":"Apa yang tidak boleh dicatat","t":"Jangan hanya mencatat pemenang. Kerugian adalah datanya. Jurnal yang hanya berisi kemenangan adalah brosur, bukan jurnal."},{"h":"Rencanakan langkah DEMO → LANGSUNG","t":"Buktikan rencana DEMO untuk sejumlah perdagangan dengan rata-rata R positif sebelum mempertaruhkan uang sungguhan — lalu mulailah dengan setengah ukuran."},{"h":"Daftar periksa latihan","t":"① Rencana ditulis sebelum entri ② Daftar periksa lulus ③ Entri jurnal + emosi ④ Tinjauan mingguan ⑤ Satu kebocoran diperbaiki."}]},{"id":"leverage","title":"12 · Leverage, Margin & Likuidasi","summary":"Leverage melipatgandakan kerugian secepat keuntungan. Pelajari margin, likuidasi, margin terisolasi vs margin silang, dan aturan keselamatan yang menghentikan satu perdagangan untuk menghapus akun.","lessons":[{"h":"Apa pengaruhnya","t":"Leverage memungkinkan Anda mengontrol posisi yang lebih besar dengan margin yang lebih kecil. Ini meningkatkan untung dan rugi — itu tidak meningkatkan keunggulan Anda."},{"h":"Margin vs risiko","t":"Margin adalah deposit yang dikunci oleh bursa. Risk is Entry - Berhenti × ukuran. Leverage mengubah margin, bukan risiko dolar Anda."},{"h":"Likuidasi","t":"Jika kerugian memakan margin Anda, bursa akan menutup posisi secara paksa (likuidasi), seringkali pada saat yang paling buruk. Jauhkan pemberhentian Anda dari harga likuidasi."},{"h":"Terisolasi vs Salib","t":"Terisolasi membatasi kerugian pada margin satu posisi tersebut. Cross menggunakan seluruh saldo dompet — lebih berbahaya bagi pemula. Lebih suka terisolasi saat belajar."},{"h":"Leverage yang lebih aman","t":"Leverage rendah (2–5x) ditambah stop yang tepat jauh lebih aman dibandingkan 50x tanpa stop. Perhentiannya, bukan angka leverage, adalah perlindungan Anda."},{"h":"Aturan jarak likuidasi","t":"Periksa apakah SL Anda sesuai dengan harga likuidasi. Jika berdekatan, kurangi ukurannya hingga tersedia ruang yang nyaman."},{"h":"Leverage tidak memperbaiki entri yang buruk","t":"Leverage tinggi pada entri yang buruk akan hilang lebih cepat. Perbaiki pengaturannya terlebih dahulu, lalu ukur."},{"h":"Pendanaan dan biaya","t":"Kontrak berjangka abadi membebankan pendanaan seiring waktu. Penahanan jangka panjang pada pelaku yang menggunakan leverage akan menguras pendanaan — alasan lain untuk mengukur dan mengatur waktu dengan hati-hati."},{"h":"Spot vs Kontrak Berjangka","t":"Spot tidak dapat dilikuidasi (Anda memiliki koinnya). Masa depan bisa, dan bisa menuju nol. Gunakan Kontrak Berjangka hanya dengan rencana tertulis dan margin terisolasi."},{"h":"Ukuran di bawah leverage","t":"Hitung ukuran dari jarak berhenti, lalu periksa apakah margin yang dihasilkan terjangkau. Jangan pernah memilih leverage terlebih dahulu."},{"h":"Tes “satu perdagangan”.","t":"Sebelum masuk, tanyakan: jika ini berhenti, apakah ini sebuah angkat bahu atau sebuah bencana? Kalau bukan angkat bahu berarti ukurannya terlalu besar."},{"h":"Daftar periksa latihan","t":"① Set terisolasi ② Leverage rendah ③ SL di dalam harga likuidasi ④ Ukuran dari stop ⑤ Bisakah saya bertahan dari kerugian penuh di sini? ya → berdagang."}]},{"id":"practice","title":"13 · Latihan Rutin & Backtesting","summary":"Keterampilan dibangun di DEMO sebelum LIVE. Pelajari putaran latihan yang berulang, cara melakukan “backtest” dengan menggulir grafik, dan cara beralih ke uang sungguhan dengan aman.","lessons":[{"h":"DEMO adalah gimnasium","t":"Paper / DEMO hadir untuk melatih proses dan emosi Anda tanpa risiko. Jika Anda tidak dapat mengikuti peraturan di DEMO, LIVE tidak akan memperbaikinya secara ajaib."},{"h":"Lingkaran latihan","t":"Pilih salah satu setup (misal BB turun + Hammer + putar RSI). Tandai 20 contoh sejarah pada grafik. Tentukan entri / SL / TP. Catat hasilnya. Mengulang."},{"h":"Pengujian ulang manual","t":"Gulir kembali ke Chart Lab, sembunyikan masa depan, dan tandai setiap sinyal dengan tangan. Ini melatih pengenalan pola dan menghentikan Anda membodohi diri sendiri."},{"h":"Ukuran sampel","t":"Sepuluh perdagangan tidak berarti apa-apa. Targetkan 30-50 perdagangan yang tercatat dalam satu pengaturan sebelum menilainya."},{"h":"Tes maju pada DEMO","t":"Setelah menandai dengan tangan, jalankan pengaturan yang sama secara langsung di DEMO dengan sinyal perangkat lunak selama dua hingga empat minggu. Bandingkan isi dan emosi nyata dengan backtest."},{"h":"Satu pengaturan pada satu waktu","t":"Jangan menguji lima sistem sekaligus. Kuasai satu sisi, lalu tambahkan sisi kedua."},{"h":"Jaga rutinitas tetap kecil","t":"Rutinitas harian selama 20 menit (memindai, menandai, membuat jurnal, mengulas) mengalahkan enam jam menatap grafik secara acak."},{"h":"Lulus ke LANGSUNG","t":"Kriteria: R rata-rata positif pada 30+ perdagangan DEMO, aturan diikuti, tidak ada episode balas dendam. Kemudian mulai LIVE dengan ukuran setengah dan skalakan secara perlahan."},{"h":"Aturan peningkatan skala","t":"Tingkatkan ukuran hanya setelah beberapa minggu yang menguntungkan dan disiplin — tidak pernah setelah satu kemenangan besar."},{"h":"Kapan harus mundur","t":"Capai batas kerugian harian atau mingguan, atau perhatikan pelanggaran aturan yang berulang → kembali ke DEMO dan bangun kembali disiplin sebelum melanjutkan."},{"h":"Lacak metrik proses","t":"Catat tingkat kelulusan daftar periksa, pelanggaran aturan per minggu, dan rata-rata R. Ini memprediksi pertumbuhan lebih baik daripada angka P/L tunggal."},{"h":"jalur latihan CPE","t":"Kelas Pembelajaran → Lab Bagan (penyiapan tanda) → Paper Trade → Review jurnal → Meja sinyal di DEMO → LIVE kecil pada kunci platform yang cocok."},{"h":"Daftar periksa latihan","t":"① Satu pengaturan dipilih ② 30 contoh ditandai ③ Tes maju DEMO ④ Jurnal + ulasan ⑤ R Positif → LIVE setengah ukuran."}]},{"id":"volatility","title":"14 · Volatilitas & Martingale","summary":"Cara membaca volatilitas pasar (mengapa harga berubah), bagaimana hal itu ditambahkan ke setiap sinyal sebagai garis alasan, dan cara kerja tangga Martingale opsional — ditambah mengapa ini adalah cara tercepat untuk kehilangan akun jika digunakan secara sembarangan.","lessons":[{"h":"Apa yang dimaksud dengan volatilitas","t":"Volatilitas adalah seberapa besar pergerakan harga – bukan ke arah mana. Volatilitas tinggi = candle lebar dan ayunan cepat. Volatilitas rendah = kisaran yang tenang dan sempit. Pengaturan yang sama memiliki keandalan yang sangat berbeda di setiap pengaturannya."},{"h":"Pembacaan volatilitas CPE","t":"Setiap sinyal sekarang mengukur kisaran rata-rata candle dan lebar Bollinger band, lalu membandingkannya dengan harga normal terkini dari pasangan tersebut. Anda mendapatkan RENDAH / NORMAL / TINGGI / EKSTRIM ditambah baris alasan sederhana — “mengapa” untuk perubahan pasar, ditunjukkan dengan sinyal."},{"h":"Volatilitas EKSTRIM = penurunan peringkat","t":"Ketika rekamannya EXTREME, sinyal KUAT yang baru diturunkan menjadi PERHATIAN (alasannya ditunjukkan). Di pasar whipsaw, pola yang sama jauh lebih sering gagal — break palsu dan stop-hunt wick adalah hal yang biasa."},{"h":"Apa yang harus dilakukan di TINGGI / EKSTRIM","t":"Ukuran lebih kecil. Perhentian yang lebih luas. Lebih sedikit perdagangan. Tunggu hingga candle selesai, bukan lonjakan di tengah candle. Jika pembacaannya menunjukkan EKSTRIM, perlakukan pengaturan tersebut sebagai zona belajar, bukan sebuah entri."},{"h":"Apa itu Martingale","t":"Martingale menambah posisi kalah untuk menurunkan rata-rata entri: setelah setiap pergerakan merugikan, Anda menambahkan order lain, biasanya lebih besar (1x, 2x, 4x…). Ia sering menang, lalu kehilangan segalanya dalam satu kali kegagalan."},{"h":"Aturan CPE Martingale","t":"CPE menambahkan pesanan tambahan hanya jika KEDUAnya benar: (1) harga telah bergerak berlawanan dengan perdagangan setidaknya satu langkah × %, dan (2) sinyal baru di sisi yang sama masih mewakili pasangan tersebut. Tidak pernah bertambah hanya karena harga turun."},{"h":"Empat angka","t":"Langkah % = gerakan merugikan diperlukan sebelum setiap penambahan. Pengganda = ukuran masing-masing penambahan versus basis (1 = datar, 2 = ganda). Penambahan maksimum = batas keras pada pesanan tambahan. % Batas risiko tangga = risiko keseluruhan tangga sebagai % ekuitas. Keempatnya adalah milik Anda untuk dipilih."},{"h":"Tutup keras melindungi Anda","t":"Bahkan dengan pengganda yang besar dan banyak penambahan, CPE menolak pesanan setelah total risiko tangga melampaui batas % ekuitas Anda. Ini juga menghormati ukuran minimum pertukaran dan penghentian harian −2%."},{"h":"Di mana ia berjalan","t":"Centang pada Manual untuk mengelola satu perdagangan tersebut, atau pada sesi Otomatis untuk mengelola perdagangan otomatisnya. Baik DEMO maupun LANGSUNG. Pada Manual, pasangan harus ada dalam daftar pindaian sehingga sinyal sisi yang sama dapat dibaca."},{"h":"Mengapa batasan itu penting (contoh)","t":"Langkah 1%, pengganda 2, tiga penambahan pada basis risiko 1%: risiko meningkat 1% → 2% → 4% → 8%. Satu stop-out penuh pada anak tangga terakhir akan menghapus banyak pemenang. Itulah sebabnya batasannya ada dan mengapa angka defaultnya kecil."},{"h":"Alternatif anti-martingale","t":"Banyak profesional yang melakukan hal sebaliknya: hanya menambah pemenang dan mengurangi pecundang dengan cepat. Rasanya lebih buruk (kerugian lebih kecil) namun tidak dapat meledakkan akun dalam satu tren yang merugikan Anda."},{"h":"Risiko tidak dihilangkan","t":"Rata-rata turun tidak menghilangkan risiko — ini memindahkan risiko dari “banyak kerugian kecil” menjadi “satu kerugian besar”. Jangan pernah menambahkan uang yang tidak dapat Anda hilangkan, dan jangan pernah menutup batasan untuk “memulihkan” perdagangan yang merugi."},{"h":"Jalur latihan","t":"Pelajari pembacaan volatilitas di DEMO terlebih dahulu. Coba Martingale dengan penambahan maksimal 1–2 dan pengganda kecil di DEMO untuk 30+ perdagangan. Catat setiap tangga, lalu putuskan — sebagian besar pedagang menganggap metode datar / anti-martingale lebih aman."},{"h":"Volatilitas + Daftar periksa Martingale","t":"① Baca tingkat volatilitas terlebih dahulu ② Lewati atau menyusutkan secara EXTREME ③ Martingale hanya dengan sinyal sisi yang sama yang baru ④ Langkah × anak tangga tercapai ⑤ Di bawah batas risiko → tambahkan. Setiap kata “tidak” → tidak perlu ditambahkan."}]},{"id":"lab_indicators","title":"15 · Indikator Lab Grafik (Stoch · ADX · Ichimoku · VWAP)","summary":"Chart Lab kini memiliki bilah indikator lengkap — setiap tombol merupakan tanda centang hidup/mati yang langsung menggambar ulang grafik. Selain BB / RSI / MACD / EMA / SMA50 / Volume Anda sekarang mendapatkan Stochastic, ADX/DMI, Ichimoku dan VWAP, dan mesin sinyal juga membacanya — bukan hanya grafik.","lessons":[{"h":"Dimana barnya","t":"Chart Lab → deretan tombol “Indikator” di bawah grafik. Satu klik menyalakan indikator, klik berikutnya mematikannya; grafik segera digambar ulang. Kutunya bersifat visual DAN memberi makan mesin sinyal."},{"h":"Stokastik (14,3,3)","t":"Osilator %K / %D yang digambar di bawah candle, skala 0–100. Di atas ~80 = zona jenuh beli, di bawah ~20 = zona jenuh jual. %K melintasi %D di zona oversold adalah studi bullish; persilangan ke bawah di bagian atas bersifat bearish. Dalam tren yang kuat, ia dapat tetap berada di salah satu ujungnya untuk waktu yang lama — selalu digabungkan dengan BB dan candle."},{"h":"ADX / DMI (14)","t":"ADX mengukur KEKUATAN tren, bukan arah. Di atas ~25 = tren nyata sedang berjalan; di bawah ~20 = rentang yang berombak. +DI di atas −DI = pembeli yang bertanggung jawab; −DI di atas +DI = penjual yang bertanggung jawab. Gunakan ADX untuk memutuskan apakah akan melakukan perdagangan tren atau tetap datar."},{"h":"Awan Ichimoku (9,26,52)","t":"Tenkan (jalur cepat), Kijun (jalur lambat) dan awan Senkou. Harga di atas awan yang naik = latar belakang bullish; di bawah awan yang jatuh = bearish. Persilangan Tenkan/Kijun di dalam awan lemah; persilangan dengan harga yang meninggalkan cloud lebih kuat. Cloud edge sendiri seringkali berperan sebagai support/resistance."},{"h":"VWAP","t":"Harga Rata-Rata Tertimbang Volume — harga rata-rata yang ditimbang berdasarkan volume, diatur ulang setiap sesi. Institusi-institusi besar mengukur kepuasan mereka terhadap hal tersebut. Harga di atas kenaikan VWAP = pembeli memegang kendali; penolakan total pada VWAP selama tren turun adalah sebuah studi singkat. Pada kripto 24/7, pengaturan ulangnya berbeda dibandingkan pada FX — perlakukan ini sebagai garis panduan, bukan undang-undang."},{"h":"Bagaimana mesin menggunakannya","t":"Setiap indikator baru menambahkan konfirmasi kecil pada skor di sisi yang sama yang ditunjuknya (Stochastic, Ichimoku, VWAP, ADX jika sesuai dengan arahnya, dan Elliott). Itu adalah konfirmasi, bukan pemicu — jika mereka tidak setuju dengan BB / RSI / candle, skornya akan bertambah beragam dan Anda mendapatkan lebih banyak HOLD."},{"h":"Mengapa PERHATIAN menjadi lebih ketat","t":"Karena sekarang ada lebih banyak pemeriksaan di kumpulan, bilah PERHATIAN diperketat: diperlukan skor ≥ 4 DAN setidaknya 3 pemeriksaan yang menyetujui. Hal ini mencegah aplikasi membanjiri Anda dengan sinyal yang lebih lemah hanya karena lebih banyak alat yang aktif."},{"h":"Urutan membaca yang berhasil","t":"① Arah TF lebih tinggi (Ichimoku cloud + ADX). ② Dimana harganya (BB / Fib / VWAP). ③ Momentum (RSI + Stokastik). ④ Konfirmasi lilin. ⑤ Tulisan % dan tingkat risiko → Makalah terlebih dahulu."},{"h":"Kesalahan yang harus dihindari","t":"Menyalakan setiap indikator dan menatap pelangi; menggunakan ADX sebagai arah (itu hanya kekuatan); short hanya karena Stochastic >80 di dalam bull run; mengabaikan bahwa VWAP memiliki arti yang berbeda pada crypto vs FX."},{"h":"Daftar periksa latihan","t":"① Bias dari cloud + ADX ② Lokasi dari BB/Fib/VWAP ③ Momentum dari RSI + Stoch ④ Konfirmasi candle ⑤ SL/TP tertulis ⑥ Paper, lalu jurnal."}]},{"id":"elliott","title":"16 · Elliott Wave (hitungan cahaya)","summary":"CPE mencakup penghitung Elliott Wave yang ringan. Centang “Elliott” di bilah indikator Chart Lab dan beri label impuls 0-1-2-3-4-5 terakhir pada candle dan proyeksikan target Fibonacci gelombang-5. Ini adalah alat belajar — bukan bola kristal.","lessons":[{"h":"Idenya dalam satu baris","t":"Pasar bergerak dalam gelombang: impuls (5 arah dalam arah tren) dan koreksi (3 arah berlawanan). CPE hanya menghitung impuls, yaitu bagian yang membawa tren."},{"h":"Bagaimana CPE menghitungnya","t":"Ia menemukan pivot ayunan terakhir (fraktal 3-bar), bergantian tinggi / rendah, dan menguji 5–6 ayunan terakhir terhadap aturan Elliott. Jika bentuknya cocok, ia akan menggambar label 0→5 (gelombang yang masih berjalan berwarna kuning) dan garis target W5 yang dibuat dari panjang gelombang-1 × 1,618 diukur dari gelombang 4."},{"h":"Aturan yang diperiksanya","t":"Gelombang 2 tidak melewati permulaan gelombang 1; gelombang 4 tidak tumpang tindih dengan wilayah gelombang 1; gelombang 3 bukanlah yang terpendek dari 1/3/5. Jika suatu aturan gagal, maka aturan tersebut tidak menunjukkan apa pun — tidak ada penghitungan paksa."},{"h":"Bullish vs bearish","t":"Kenaikan 0-1-2-3-4-5 adalah dorongan bullish; bayangan cermin saat turun adalah bearish. Mesinnya menambahkan konfirmasi kecil pada skor di sisi gelombang."},{"h":"Langsung vs lengkap","t":"Gelombang LIVE 5 (masih berjalan) terbaca sebagai kelanjutan tren. Dorongan LENGKAP (selesai 0–5) memperingatkan bahwa tren mungkin melelahkan — sering kali terjadi koreksi."},{"h":"Garis sasaran W5","t":"Merupakan perpanjangan Fibonacci dari gelombang 1 dari gelombang ke-4 yang rendah/tinggi. Ini adalah ide target, bukan magnet – harga bisa berhenti atau melampauinya."},{"h":"Bagaimana cara menggunakannya","t":"Perlakukan penghitungan sebagai pertemuan: pada zona BB/Fib yang jelas dengan candle dan RSI, penghitungan impulsif menambah keyakinan. Kalau sendiri, itu hanya sketsa."},{"h":"Kesalahan yang harus dihindari","t":"Menghitung ulang gelombang sampai sesuai dengan posisi Anda (dosa klasik Elliott); menghitung gerakan kecil; mengabaikan hitungan jangka waktu yang lebih tinggi; lupa hitungannya berubah setiap kali bilah baru dicetak."},{"h":"Daftar periksa latihan","t":"① Clear swings dipilih ② Rules pass ③ Zig-zag setuju dengan BB / Fib ④ Konfirmasi candle ⑤ SL melampaui titik pembatalan wave-4."}]},{"id":"forecast","title":"17 · Prakiraan 3 Bulan (Prakiraan 3M centang)","summary":"Proyektor cakrawala panjang: bagaimana grafik ini kemungkinan terbentuk selama ~3 bulan ke depan, dibangun berdasarkan tren, target, dan volatilitas sinyal itu sendiri. Aktifkan atau nonaktifkan dengan centang “Forecast 3M” di Chart Lab.","lessons":[{"h":"Apa yang digambarnya","t":"Jalur tengah putus-putus yang dimulai dari entri yang dianalisis menuju target terbaik yang sudah diketahui mesin (target Elliott → tp2 → tp1), dibungkus dengan “kerucut” yang melebar yang menunjukkan penyebaran harga yang masuk akal. Penanda bulan M+1 / M+2 / M+3 membagi cakrawala."},{"h":"Mengapa berbentuk kerucut dan bukan garis","t":"Tidak ada yang bisa mengetahui secara pasti harga di masa depan. Kerucutnya melebar seiring dengan akar kuadrat waktu dan volatilitas pasangan itu sendiri, sehingga pasangan FX yang tenang mendapatkan kerucut yang sempit dan altcoin liar mendapatkan kerucut yang sangat lebar. Lebar itu ADALAH pesannya: semakin jauh Anda melihat, semakin kurang pasti harganya."},{"h":"Dari mana angka-angka itu berasal","t":"Penyimpangan tersebut berasal dari target sinyal saat ini; volatilitas harian berasal dari sinyal ATR% yang diskalakan menjadi satu hari sehingga kerucut memiliki arti yang sama pada grafik 5 menit atau 1 hari; Volatilitas EKSTRIM / TINGGI semakin memperlebarnya."},{"h":"Bagaimana cara membacanya","t":"Perhatikan SLOPE (ke arah mana jalannya condong) dan LEBARnya (seberapa besar keraguannya). Jalur menanjak dengan kerucut sempit = gagasan tren yang lebih stabil; jalan datar dengan kerucut besar = “tidak ada tepian di sini, diperkirakan akan ada kebisingan”."},{"h":"Menghidupkan dan mematikannya","t":"Tombol “Prakiraan 3M” berada di sebelah “Ruang masa depan”. Dibutuhkan ruang Masa Depan AKTIF (area kosong di sebelah kanan tempat proyeksi digambar). Kalau sinyal HOLD tidak ada arah, jadi tidak ada yang ditarik."},{"h":"Ini adalah tren, bukan perdagangan","t":"Ramalan cuaca adalah peta gambaran besar. Level perdagangan sebenarnya — entri, TP1 / TP2, SL, dan proyeksi jangka pendek — tetap sesuai dengan yang Anda perdagangkan."},{"h":"Batasan yang jujur","t":"Berita, pencatatan, penghapusan pencatatan, dan perubahan makro tidak ada dalam model; jalurnya mulus, sehingga harga riil akan bergerak lebih jauh; kerucut 3 bulan adalah bantuan belajar, tidak pernah menjadi janji."},{"h":"Sering-seringlah menganalisis ulang","t":"Saat candle baru dicetak, target, volatilitas, dan keseluruhan kerucut diperbarui. Perkiraan adalah gambaran singkat, bukan kontrak."},{"h":"Daftar periksa latihan","t":"① Baca arah jalur ② Periksa lebar kerucut ③ Bandingkan dengan struktur TF yang lebih tinggi ④ Ukur posisi dari SL sebenarnya, jangan pernah dari kerucut."}]}],"platforms":{"BINANCE":{"title":"Perdagangan Binance A → Z","steps":["Buat akun → aktifkan 2FA.","Manajemen API → Buat Kunci → Perdagangan Spot &/atau Kontrak Berjangka AKTIF, Penarikan NONAKTIF.","Tempel Kunci + Rahasia di CPE → Kunci API → Binance → Simpan → Akun Uji.","Gunakan pemindaian Spot Desk / Futures Desk (grafik publik berfungsi bahkan sebelum kunci).","Latihan: Perdagangan Manual → Mulai Perdagangan Kertas (tanpa uang langsung).","Live: atur TP1/TP2/SL + Trailing → Mulai Live Trade (membutuhkan API).","Kelola di Posisi: edit level, penutupan sebagian, batalkan otomatis.","Lisensi: Uji Coba 7 hari → 3 Bulan atau Seumur Hidup (harga pemilik di aplikasi)."]},"BYBIT":{"title":"Perdagangan Bybit A → Z","steps":["Akun + 2FA.","Manajemen API → perdagangan saja, Penarikan MATI.","CPE → Kunci API → Bybit → Simpan.","Futures Desk untuk pola pikir pelaku; Chart Lab untuk mempelajari candle.","Perdagangan Kertas terlebih dahulu; Hidup setelah kunci berfungsi.","Jejak TP+SL: BELI↑ / JUAL↓."]},"OKX":{"title":"Perdagangan OKX A → Z","steps":["Diperlukan Kunci API + Rahasia + Frasa Sandi.","Penarikan MATI selalu.","Simpan ketiga bidang di Kunci CPE.","Latihan kertas → ukuran langsung kecil.","Kesalahan ketik frasa sandi adalah kegagalan #1 — salin dengan hati-hati."]},"KUCOIN":{"title":"Perdagangan KuCoin A → Z","steps":["Kunci + Rahasia + Frasa Sandi.","Izin perdagangan saja.","Kertas di CPE → lalu tinggal kecil.","Gunakan tabel Spot/Futures untuk sinyal."]},"BITGET":{"title":"Perdagangan Bitget A → Z","steps":["API dengan perdagangan saja.","Kertas kemudian hidup.","Kontrak Berjangka: pilih Cross atau Isolated di Manual Trade.","Jejak TP+SL untuk mengunci keuntungan."]},"GATE":{"title":"Perdagangan Gate.io A → Z","steps":["Buat kunci API v4 (perdagangan).","Penarikan MATI.","Simpan di CPE → Makalah latihan.","Pindai + Lab Bagan untuk entri sebelum siaran langsung."]},"MEXC":{"title":"Perdagangan MEXC A → Z","steps":["Mulai pola pikir Spot.","Kunci dalam Kunci API CPE.","Kertas → hidup.","Gunakan jejak untuk mengunci keuntungan terbuka."]},"KRAKEN":{"title":"Perdagangan Kraken A → Z","steps":["Hasilkan kunci hanya dengan izin perdagangan.","Tidak ada hak penarikan/dana.","Latihan makalah di CPE.","Verifikasi juga setiap pesanan langsung di Kraken."]},"COINBASE":{"title":"Coinbase Tingkat Lanjut A → Z","steps":["Kunci API Perdagangan Tingkat Lanjut.","Meja yang berfokus pada titik di CPE.","Kertas kemudian hidup.","Jauhkan Penarikan."]},"FOREX_OANDA":{"title":"Valas (OANDA) A → Z","steps":["Buka demo OANDA → risiko ~1%.","Token akses pribadi + ID Akun di Kunci CPE.","Pemindaian Meja Forex + Lab Grafik (EURUSD…).","Perdagangan Manual → Kertas dengan platform Forex.","Hidup hanya setelah kepercayaan diri demo."]},"FOREX_FXCM":{"title":"FXCM Valas A → Z","steps":["Kredensial API pialang.","Kertas di CPE dulu.","Tonton sesi London/NY & lonjakan berita.","Jurnal live setelah latihan terlihat bersih."]},"FOREX_MT5":{"title":"0 A → Z","steps":["Login + server + kata sandi di Kunci CPE.","Lebih suka kata sandi investor (baca) jika memungkinkan.","Latihan banyak 0,01.","Kertas dalam CPE; langsung melalui broker jika sudah siap."]},"FOREX_DEMO":{"title":"Tarif Demo Forex A → Z","steps":["Tidak diperlukan kunci API.","Forex Desk + Chart Lab untuk grafik gratis.","Perdagangan kertas saja (latihan).","Jika sudah siap untuk broker sungguhan, tambahkan kunci OANDA / FXCM / MT5 untuk live."]}},"forexAz":{"title":"Perdagangan Forex A → Z (kelas penuh)","lessons":[{"h":"A — Akun & risiko","t":"Demo dulu. Risiko ~0,5–1% per ide. Jangan pernah membalas perdagangan."},{"h":"B — Berpasangan","t":"Mata uang utama (EURUSD, GBPUSD, USDJPY) sebelum eksotik."},{"h":"C — Lilin","t":"Pelajari Doji, Hammer, Engulfing di Chart Lab Forex."},{"h":"D - Bias harian","t":"Periksa jangka waktu yang lebih tinggi sebelum entri 15m/30m."},{"h":"E — Entri","t":"Pantulan BB yang lebih rendah + konfirmasi candle adalah pengaturan praktik yang umum."},{"h":"F — Fib","t":"Kemunduran 50% / 61,8% sering digunakan sebagai zona latihan."},{"h":"G — Sasaran (TP)","t":"Skala keluar TP1, pelari TP2, jejak SL."},{"h":"H - Jam","t":"London–NY tumpang tindih = lebih banyak pergerakan."},{"h":"Saya — Indikator","t":"RSI + MACD + BB bersamaan; hindari indikator yang berlebihan."},{"h":"J - Jurnal","t":"Catat setiap perdagangan kertas/langsung di Jurnal CPE."},{"h":"K — Kunci","t":"Broker forex langsung membutuhkan API/token; tarif demo tidak memerlukan apa pun."},{"h":"L - Banyak","t":"Mulai 0,01 lot dalam pola pikir latihan."},{"h":"M - Pola Pikir","t":"Proses melebihi prediksi. Lewati hari-hari buruk."},{"h":"N - Berita","t":"Periksa Berita & Trik sebelum acara besar."},{"h":"HAI — Perintah","t":"Selalu atur SL. Trailing melindungi keuntungan terbuka."},{"h":"P - Latihan","t":"Tombol Paper Trade = berlatih tanpa API langsung."},{"h":"T — Kualitas","t":"Lebih sedikit setup berkualitas tinggi yang mengalahkan overtrading."},{"h":"R — Risiko: imbalan","t":"Arahkan pengaturan di mana imbalan ≥ risiko jika memungkinkan."},{"h":"S - Sesi","t":"Asia lebih tenang; London/NY lebih aktif."},{"h":"T — Tren","t":"Berdaganglah dengan tren TF yang lebih tinggi saat belajar."},{"h":"kamu — Pembaruan","t":"Tonton spanduk pembaruan CPE + Bantuan Langsung."},{"h":"V — Volatilitas","t":"Perluas kesabaran saat ATR melonjak."},{"h":"W — Tarik API","t":"Jangan pernah mengaktifkan penarikan pada kunci API apa pun."},{"h":"X — keluar","t":"Jejak TP + parsial mengalahkan harapan."},{"h":"Y - Rencanamu","t":"Tulis aturan; ikuti mereka di Manual/Otomatis."},{"h":"Z - Tidak terburu-buru","t":"Tidak ada FOMO. Latihan → lalu hidupkan API."}]}};

window.CPE_LEARN.es = {"intro":"Practique primero con Paper/DEMO. Estudie velas, gráficos, BB/RSI/Fib, dinero, psicología, luego Señales (lo que significa COMPRAR/VENDER/MANTENER + qué hacer) y señales de Forex. Live necesita la clave API de la plataforma correcta (Retiros desactivados).","candles":[{"shape":"doji","name":"Doji","color":"#94a3b8","bias":"Neutral / espera","tip":"Abrir ≈ cerrar: cuerpo cruzado o delgado. Indecisión del mercado tras una mudanza.","also":"También enseña: no hagas FOMO. Espera la próxima vela. Cerca de BB extremo + Doji = compresión de opiniones; verifique la pendiente del RSI antes de adivinar la dirección."},{"shape":"hammer","name":"Martillo","color":"#22c55e","bias":"COMPRAR sesgo","tip":"Cuerpo pequeño arriba, mecha larga abajo (≈2× cuerpo) después de una caída: los compradores rechazaron precios más bajos.","also":"Además: coloque la práctica SL debajo de la mecha baja. Lo mejor es que un BB + RSI más bajo aumente desde la sobreventa. Psicología: paciencia para que se acabe la mecha; no compres la mecha a mitad de camino."},{"shape":"invhammer","name":"Martillo invertido","color":"#22c55e","bias":"COMPRAR (débil)","tip":"Mecha superior larga en la parte inferior. Los compradores sondearon alto pero cerraron casi abiertos; necesita la próxima confirmación verde.","also":"Además: más débil que Hammer solo. Úselo como alerta, no como entrada. Rebote Fib 61.8 + Martillo Invertido = zona de estudio solo hasta confirmar vela."},{"shape":"shooting","name":"estrella fugaz","color":"#ef4444","bias":"VENDER sesgo","tip":"Fondo de cuerpo pequeño, mecha superior larga después de una subida: los vendedores rechazaron los máximos.","also":"También: SL encima de la mecha alta. Más fuerte cerca de BB superior / extensión de Fib / sobrecompra de RSI. Enseña: las velas lunares pueden fallar; no persigas el último verde."},{"shape":"hanging","name":"hombre colgado","color":"#f59e0b","bias":"VENDER precaución","tip":"Se parece a Hammer pero aparece después de una subida: posible agotamiento superior.","also":"Además: el contexto lo es todo (misma forma ≠ mismo comercio). Ubicación del diario: arriba versus abajo. Psicología: no retroceda solo porque la forma coincide; confirme con la siguiente vela + RSI."},{"shape":"engulf_bull","name":"envolvente alcista","color":"#22c55e","bias":"COMPRAR","tip":"El cuerpo verde cubre completamente el cuerpo rojo anterior: los compradores tomaron el control en una barra.","also":"Además: más fuerte en el soporte / BB más bajo / Fib 50–61,8. Tamaño desde envolvente bajo como SL. Consejo económico: cuerpo envolvente ancho → SL más ancho → tamaño más pequeño."},{"shape":"engulf_bear","name":"envolvente bajista","color":"#ef4444","bias":"VENDER","tip":"El cuerpo rojo cubre completamente el verde anterior: los vendedores dominaron.","also":"Además: precaución con las posiciones largas abiertas. Cerca de BB superior + RSI>70 = alta calidad del estudio. Enseña riesgo: si ya es largo, TP/sendero parcial en lugar de esperanza."},{"shape":"morning","name":"estrella de la mañana","color":"#22c55e","bias":"COMPRAR","tip":"3 velas: roja grande → estrella pequeña → verde grande. Historia de reversión de fondo.","also":"Además: paciencia con varias velas. Ingrese después del tercer cierre; SL bajo estrella baja. Combina bien con BB inferior + divergencia alcista del RSI."},{"shape":"evening","name":"Estrella de la tarde","color":"#ef4444","bias":"VENDER","tip":"3 velas: verde grande → estrella pequeña → roja grande. Historia de reversión superior.","also":"Además: no acorte solo con la estrella del medio. Espere el tercer cierre. Confluencia de extensión BB superior/Fib. Psicología: ignore el FOMO de la primera carrera verde."},{"shape":"maru_bull","name":"Toro Marubozu","color":"#22c55e","bias":"Fuerte presión de COMPRA","tip":"Cuerpo verde largo, casi sin mechas: los compradores controlaban abrir → cerrar.","also":"Además: pista de continuación de la tendencia, no siempre una compra mínima. Es posible caminar con la banda. Riesgo: perseguir al último Marubozu sin retroceso a BB mid/Fib."},{"shape":"maru_bear","name":"Oso Marubozu","color":"#ef4444","bias":"Fuerte presión de VENTA","tip":"Cuerpo largo y rojo, casi sin mechas: los vendedores tienen el control.","also":"Además: no atrape los cuchillos que caen. Espere rebote BB/Fib + Martillo más tarde. Enseña: presión fuerte = tamaño más pequeño o hacerse a un lado."},{"shape":"spin","name":"Peonza","color":"#94a3b8","bias":"Indecisión","tip":"Cuerpo pequeño, mechas superior + inferior: ambos bandos lucharon, nadie ganó claramente.","also":"Además: apriete el BB interior con frecuencia. Pausar el comercio; espera descanso + dirección vela. Lección de psicología: el mercado “no puede hacer nada”; lo plano es una opción válida."},{"shape":"pierce","name":"Línea de perforación","color":"#22c55e","bias":"COMPRAR","tip":"Rojo y luego verde que abre hacia abajo pero cierra por encima del punto medio del rojo anterior.","also":"Además: más suave que Engulfing. Confirmar con giro RSI. Buen ejercicio de papel para lectura de fuerza parcial: no todos los greens son iguales."},{"shape":"darkcloud","name":"Cubierta de nubes oscuras","color":"#ef4444","bias":"VENDER","tip":"Verde y luego rojo que abre más arriba pero cierra por debajo del punto medio del verde anterior.","also":"Además: alerta temprana antes de que el oso se envuelva por completo. Sendero largo/toma TP1. Enseña cómo ampliar antes de una impresión invertida completa."},{"shape":"soldiers","name":"Tres soldados blancos","color":"#22c55e","bias":"COMPRAR tendencia","tip":"Tres verdes al alza con cierres más altos: compras constantes.","also":"Además: fuerte señal de tendencia alcista; los retrocesos a Fib 38–50 o BB mid son adiciones de práctica. Riesgo de exceso de confianza después de 3 greens: mantenga fijo el porcentaje de riesgo."},{"shape":"crows","name":"Tres cuervos negros","color":"#ef4444","bias":"VENDER tendencia","tip":"Tres rojos en caída con cierres más bajos: ventas constantes.","also":"Además: no promedies hacia abajo. Estructura de espera. La sobreventa del RSI puede permanecer sobrevendido: regla del dinero: límite de pérdidas> esperanza."},{"shape":"harami_bull","name":"Harami alcista","color":"#22c55e","bias":"COMPRAR (suave)","tip":"Rojo grande, luego verde pequeño dentro del cuerpo anterior: la presión de venta se reduce.","also":"Además: señal de pausa anticipada. Necesita confirmar. Pares con estudio de divergencia alcista del RSI. Enseña a leer “desvanecimiento de la fuerza” no solo reversiones."},{"shape":"harami_bear","name":"Harami bajista","color":"#ef4444","bias":"VENDER (suave)","tip":"Verde grande, luego rojo pequeño en el interior: la presión de compra se reduce.","also":"Además: tome parciales en largos. No corto automático. Psicología: la codicia tras el gran green a menudo ignora la advertencia de Harami."},{"shape":"tweezer_bot","name":"Fondo de pinza","color":"#22c55e","bias":"COMPRAR","tip":"Dos velas con mínimos coincidentes: doble prueba de soporte.","also":"Además: marque ese bajo como estructura. SL justo debajo. La alineación de Fib/BB ayuda. Primo del patrón gráfico del doble fondo: la misma lección de soporte."},{"shape":"tweezer_top","name":"Pinza superior","color":"#ef4444","bias":"VENDER","tip":"Dos velas con máximos coincidentes: doble prueba de resistencia.","also":"También: resistencia a las marcas. Primo de Doble Top. Fallo del RSI en máximos = confluencia. Enseña: mismo precio rechazado dos veces = respetar el nivel."},{"shape":"longlegged","name":"Doji de piernas largas","color":"#94a3b8","bias":"Indecisión","tip":"Mechas superiores e inferiores muy largas con un cuerpo diminuto: una violenta lucha bidireccional que terminó donde comenzó.","also":"Además: a menudo sigue un gran movimiento, pero se desconoce la dirección: espere a que se rompa la vela. Enseña: una alta volatilidad no es una alta certeza."},{"shape":"dragonfly","name":"Doji libélula","color":"#22c55e","bias":"COMPRAR sesgo","tip":"Abrir = cerrar = alto, con una mecha inferior larga: los vendedores empujaron hacia abajo y los compradores la volvieron a cerrar de golpe.","also":"Además: más fuerte en el soporte / BB más bajo después de una caída. SL debajo de la cola de la mecha. Enseña: el rechazo es una historia, no una garantía; confirme la siguiente vela."},{"shape":"gravestone","name":"Lápida Doji","color":"#ef4444","bias":"VENDER sesgo","tip":"Abrir = cerrar = mínimo, con una mecha superior larga: los compradores empujaron hacia arriba y los vendedores lo arrastraron de regreso al mínimo.","also":"Además: más fuerte en resistencia / BB superior / sobrecompra de RSI. Espejo de la Libélula. Enseña: un pico alto que se cierra en el mínimo es una ruptura fallida."},{"shape":"inside_bar","name":"Barra interior","color":"#94a3b8","bias":"Arrollar / esperar","tip":"La segunda vela se encuentra completamente dentro de la primera: el rango se comprime y el mercado contiene la respiración.","also":"Además: la ruptura de la barra madre es el detonante: opere en la dirección de ruptura. Se combina con un apretón de BB. Enseña: la contracción viene antes de la expansión."},{"shape":"outside_bar","name":"Barra exterior","color":"#22c55e","bias":"Ruptura / reversión","tip":"La segunda vela envuelve a la primera de mayor a menor: una toma violenta dentro de una barra.","also":"Además: dirección = donde se cierra la barra exterior. Una barra grande significa un SL grande, por lo que el tamaño es más pequeño. Enseña: una barra puede borrar las últimas tres."},{"shape":"belt_bull","name":"Mantención del cinturón alcista","color":"#22c55e","bias":"COMPRAR","tip":"Se abre en el nivel más bajo sin mecha inferior y se ejecuta en verde: los compradores tomaron el control desde el primer tic.","also":"Además: más fuerte después de un hueco hacia abajo o directamente hacia el soporte. SL al aire libre. Enseña: un impulso de apertura muestra una intención real."},{"shape":"belt_bear","name":"Mantención del cinturón bajista","color":"#ef4444","bias":"VENDER","tip":"Se abre en lo alto sin mecha superior y es rojo; los vendedores lo controlaron desde la apertura.","also":"Además: más fuerte después de un hueco al alza o en resistencia. Anhelos del sendero. Enseña: el primer movimiento puede fijar todo el día."},{"shape":"kick_bull","name":"Pateador alcista","color":"#22c55e","bias":"COMPRA fuerte","tip":"Una vela roja, luego un hueco hacia una vela verde: el estado de ánimo cambiaba entre cierres sin superposición.","also":"También: raro y poderoso; se requiere el espacio, no se permite superposición. Enseña: el sentimiento puede cambiar mientras el mercado duerme."},{"shape":"kick_bear","name":"Pateador bajista","color":"#ef4444","bias":"VENTA fuerte","tip":"Una vela verde, luego un hueco hacia una vela roja: los compradores desaparecieron entre los cierres.","also":"Además: salga rápido de los largos: los kickers no le esperan. Enseña: una brecha es la revaloración del mercado cuando estás fuera."},{"shape":"abandoned","name":"Bebé abandonado alcista","color":"#22c55e","bias":"COMPRA fuerte","tip":"Una vela roja, un doji abierto, luego una vela verde abierta: una isla solitaria de indecisión.","also":"Además: el doji debe estar separado en AMBOS lados. Raro pero de alta calidad en la parte inferior. Enseña: los retrocesos comienzan cuando todos se dan por vencidos."},{"shape":"three_inside_up","name":"Tres de adentro hacia arriba","color":"#22c55e","bias":"COMPRAR","tip":"Harami alcista más una tercera vela verde que se cierra por encima de la primera: la barra interior finalmente se rompió.","also":"Además: un Harami confirmado es mucho más fuerte que uno desnudo. SL bajo el harami bajo. Enseña: la confirmación vence a la predicción."},{"shape":"three_inside_down","name":"Tres de adentro hacia abajo","color":"#ef4444","bias":"VENDER","tip":"Harami bajista más una tercera vela roja que cierra por debajo de la primera: la barra interior se rompió.","also":"Además: corte largos tan pronto como se cierre el tercero. Enseña: una pausa fallida puede simplemente reanudar la vieja tendencia."},{"shape":"three_methods_bull","name":"Tres métodos ascendentes","color":"#22c55e","bias":"COMPRAR tendencia","tip":"Una larga vela verde, tres pequeñas rojas en su interior, luego otra larga verde: un descanso dentro de una subida.","also":"Además: la pausa nunca sale del rango de la primera vela, por lo que la tendencia es tranquila. Opere la ruptura de la última vela. Enseña: las tendencias descansan sin romperse."},{"shape":"three_methods_bear","name":"Cayendo tres métodos","color":"#ef4444","bias":"VENDER tendencia","tip":"Una larga vela roja, tres pequeñas verdes en su interior, luego otra larga roja: un descanso dentro de una caída.","also":"También: espejo de Rising Three Methods. No compre los greens pequeños, son ruido. Enseña: los retrocesos dentro de un rango no son reversiones."},{"shape":"tower_bot","name":"Fondo de la torre","color":"#22c55e","bias":"COMPRAR reversión","tip":"Una vela roja larga, un grupo de velas pequeñas y luego una verde larga: el ambiente cambia a lo largo de una base plana.","also":"Además: el centro plano es la batalla y la última vela declara al ganador. Enseña: las bases toman tiempo."},{"shape":"tower_top","name":"Cima de la torre","color":"#ef4444","bias":"VENDER reversión","tip":"Una vela verde larga, un grupo de velas pequeñas y luego una roja larga: los compradores se agotan y los vendedores toman el control.","also":"También: espejo de Tower Bottom. Tome parciales mientras se forma la base. Enseña: las cimas son un proceso, no un momento."}],"chartPatterns":[{"shape":"double_bot","name":"Doble Fondo (W)","color":"#22c55e","bias":"COMPRAR sesgo","tip":"Dos mínimos se acercan al mismo precio, luego se rompe el pico medio: forma de W.","also":"Además: rotura del escote = gatillo de práctica. Mida la altura para la idea TP. Enlaces a la parte inferior de las pinzas + Fib desde pico → bajo. Riesgo: rotura falsa: espere cerca más allá del escote."},{"shape":"double_top","name":"Doble Tapa (M)","color":"#ef4444","bias":"VENDER sesgo","tip":"Dos máximos cerca del mismo precio, luego ruptura del mínimo medio: forma de M.","also":"Además: igual que Tweezer Top a mayor escala. Camino anhela antes de romper el escote. Psicología: el segundo FOMO principal es caro; el plan ya estaba ahí."},{"shape":"hs_top","name":"Cabeza y hombros","color":"#ef4444","bias":"VENDER sesgo","tip":"Hombro izquierdo, cabeza más alta, hombro derecho; romper el escote hacia abajo.","also":"Además: distribución clásica. Objetivo ≈ altura de la cabeza por debajo del escote. El RSI a menudo diverge en la cabeza. Enseña paciencia en múltiples swings, no en el trading con una sola vela."},{"shape":"ihs","name":"Salud y seguridad inversas","color":"#22c55e","bias":"COMPRAR sesgo","tip":"Cabeza y cuello al revés en la parte inferior: escote roto.","also":"También: historia de acumulación. Confirme con volumen/impulso si está disponible. Combínelo con Morning Star en la zona del hombro derecho para estudiar la confluencia."},{"shape":"triangle","name":"Triángulo (apretar)","color":"#f0b429","bias":"espera de fuga","tip":"Máximos más bajos + mínimos más altos comprimiéndose: acumulación de energía.","also":"Además: la misma lección que BB squeeze. No adivines la dirección del interior. Pausa comercial + cierre de vela. Dinero: tamaño según dirección conocida."},{"shape":"flag","name":"Bandera de toro","color":"#22c55e","bias":"COMPRAR continuación.","tip":"Ascenso brusco (polo), luego un pequeño canal descendente/lateral y luego continuación.","also":"Además: la profundidad del indicador de fibra suele ser poco profunda (38%). Poste de Marubozu + bandera = práctica de tendencia. No compre tarde después de una extensión total sin retroceso."},{"shape":"channel","name":"Canal de tendencias","color":"#38bdf8","bias":"Con tendencia","tip":"Precio entre líneas paralelas ascendentes (o descendentes): herramientas de swing trade.","also":"Además: comprar canal inferior + Hammer en tendencia alcista; Vendo superior + Estrella fugaz. BB mid a menudo sigue el canal. Enseña “dónde” y no sólo “qué vela”."},{"shape":"support_res","name":"Soporte y resistencia","color":"#a78bfa","bias":"Contexto primero","tip":"Zonas horizontales donde el precio reacciona repetidamente: el mapa debajo de cada vela.","also":"Además: cada patrón es más fuerte en S/R. Dibuje zonas en Chart Lab antes de BB/RSI. Psicología: niveles > consejos; escríbalos antes de la entrada."},{"shape":"triple_top","name":"triple techo","color":"#ef4444","bias":"VENDER sesgo","tip":"Tres máximos a casi el mismo precio: los compradores fracasan tres veces en una pared.","also":"Además: más fuerte que un Double Top (tres rechazos = oferta obstinada). La rotura del escote es el detonante; objetivo ≈ altura del patrón. Enseña: el nivel, no la vela, es el que manda."},{"shape":"triple_bot","name":"Triple fondo","color":"#22c55e","bias":"COMPRAR sesgo","tip":"Tres mínimos a casi el mismo precio: los vendedores fracasan tres veces en un piso.","also":"También: espejo de Triple Top. Cada toque puede ser un estudio de Martillo/Pinza. Esperar a que se rompa el escote + se cierre. Enseña paciencia en muchos cambios."},{"shape":"cup_handle","name":"Taza y mango","color":"#22c55e","bias":"COMPRAR continuación.","tip":"Una “U” (copa) redondeada y luego un pequeño retroceso (asa), continuación después de un descanso.","also":"También: popular entre los comerciantes de ruptura. El mango debe ser poco profundo y corto; un mango profundo significa manos débiles. Ingrese por la manija y confirme con la vela."},{"shape":"rounding_bot","name":"Fondo redondeado","color":"#22c55e","bias":"COMPRAR reversión","tip":"Un mínimo lento y suave: las ventas se desvanecen gradualmente y luego los compradores toman el control.","also":"Además: un doble fondo en cámara lenta. El mensaje es que los vendedores se quedaron sin energía, ni un solo pico: se requiere paciencia total."},{"shape":"rounding_top","name":"Parte superior redondeada","color":"#ef4444","bias":"VENDER reversión","tip":"Un suave máximo de “cúpula”: las compras se desvanecen gradualmente antes de que el precio caiga.","also":"También: espejo de Fondo Redondeado. Tome parciales temprano mientras muere el impulso. Enseña: las copas son un proceso, no una sola vela."},{"shape":"rising_wedge","name":"Cuña ascendente","color":"#ef4444","bias":"VENDER sesgo","tip":"Ambos rieles suben, pero convergen hacia arriba: los compradores se cansan cuando el rango se aprieta.","also":"Además: engañoso porque el precio sigue subiendo; el estrechamiento es la verdadera pista. A menudo se estropea. No persigas el último empujón."},{"shape":"falling_wedge","name":"Cuña que cae","color":"#22c55e","bias":"COMPRAR sesgo","tip":"Ambos rieles caen, pero convergen hacia abajo: los vendedores se cansan cuando el rango se aprieta.","also":"También: espejo de Rising Wedge. A menudo se rompe. Un martillo en la cola de cuña es un estudio clásico. Esperar el descanso + cerrar."},{"shape":"asc_triangle","name":"Triángulo ascendente","color":"#f0b429","bias":"COMPRAR sesgo","tip":"Un techo plano + piso ascendente: los compradores siguen avanzando hacia una resistencia fija.","also":"Además: aumenta la presión contra un precio; la ruptura es común. Ingrese cerca del techo. Enseña: los compradores se impacientan."},{"shape":"desc_triangle","name":"Triángulo descendente","color":"#f0b429","bias":"VENDER sesgo","tip":"Un suelo plano + un techo que se cae: los vendedores siguen empujando hacia un soporte fijo.","also":"También: espejo del Triángulo Ascendente. La ruptura hacia abajo es común. Ingrese cerca debajo del piso. Enseña: los vendedores ganan el control."},{"shape":"pennant","name":"banderín","color":"#22c55e","bias":"Continuación","tip":"Un polo afilado y luego un triángulo pequeño y estrecho: un descanso muy breve antes de que se reanude la tendencia.","also":"También: como una Bandera pero más corta y triangular. Mide el poste para una idea objetivo. Nunca adivines dentro de la pequeña bobina."},{"shape":"flag_bear","name":"Bandera del oso","color":"#ef4444","bias":"VENDER continuación.","tip":"Una caída brusca (polo), luego un pequeño canal ascendente/lateral y luego una continuación hacia abajo.","also":"También: espejo de Bandera del Toro. El pequeño rebote es una pausa, no una reversión. Persigue la bandera y comprarás el peor precio: espera el descanso."},{"shape":"rectangle","name":"Rectángulo (rango)","color":"#f0b429","bias":"Comercio de rango","tip":"El precio rebota entre un techo plano y un piso: una caja lateral.","also":"Además: desvanezca los bordes por dentro, intercambie la rotura por fuera. El apretón de BB generalmente se encuentra dentro de un rectángulo. Enseña: disciplina de nivel a nivel."},{"shape":"broadening","name":"Ampliación de la formación","color":"#f0b429","bias":"Precaución","tip":"Máximos más altos Y mínimos más bajos: el rango se abre en abanico en lugar de pellizcar.","also":"Además: un mercado caótico y emocional. Las paradas son atacadas en ambos sentidos. Tamaño más pequeño o a un lado; a menudo termina en un movimiento violento en un solo sentido."},{"shape":"diamond","name":"diamante","color":"#f0b429","bias":"Reversión","tip":"Ancho en el medio, estrecho en ambos extremos: una formación clásica de arriba/abajo.","also":"Además: un triángulo que se transforma y luego se deshace. La dirección de fuga decide. Raro y lento, por lo que la mayoría de las filas se sienten como ruido: tenga paciencia."},{"shape":"island_rev","name":"Inversión de la isla","color":"#ef4444","bias":"Reversión","tip":"Los diferenciales de precios desaparecen, se negocia en un grupo solitario y luego retroceden: una “isla”.","also":"Además: necesita brechas reales (más común en acciones/FX). La isla está atrapada por compradores o vendedores. Trate los huecos como la señal, no las velas de la isla."},{"shape":"breakaway_gap","name":"Brecha de ruptura","color":"#22c55e","bias":"Inicio de tendencia","tip":"Una brecha fuera de un rango o base: el movimiento comienza con fuerza, no con un apretón.","also":"Además: a diferencia de una brecha de agotamiento, aparece al principio de un movimiento. Las brechas a menudo actúan como soporte/resistencia más adelante. Enseña: impulso versus brechas de valor."},{"shape":"v_reversal","name":"Inversión en V","color":"#22c55e","bias":"Reversión","tip":"Una caída libre brusca que aparece instantáneamente sin base: una \"V\".","also":"Además: rápido y aterrador; a menudo impulsado por noticias. Difícil de atrapar, fácil de perseguir. Espere un pequeño retroceso + vela en lugar de comprar el pico."},{"shape":"harmonic","name":"Patrón armónico","color":"#f0b429","bias":"Zonas de inversión","tip":"Un zig-zag medido (X-A-B-C-D) donde cada pata tiene una relación de Fibonacci: un mapa estilo “Gartley/Bat”.","also":"También: avanzado. El punto D es la zona de entrada, definida por proporciones, no por sentimientos. Master Fib simple primero; Esta es Fib llevada a un nivel más profundo."}],"modules":[{"id":"bb","title":"1 · Bandas de Bollinger (BB)","summary":"Bandas de volatilidad alrededor de una media móvil. Aprenda a apretar, caminar con la banda, tocar inferior/superior + confirmación de vela: la configuración básica de la práctica de CPE.","lessons":[{"h":"que es bb","t":"Bandas de Bollinger = SMA media (a menudo 20) + bandas superior/inferior en N desviaciones estándar (a menudo 2). Las bandas se amplían cuando aumenta la volatilidad y se contraen cuando el mercado está tranquilo."},{"h":"banda media","t":"La línea media es la media. El precio por encima del nivel medio a menudo muestra presión alcista; A continuación se muestra la presión bajista. Úselo como una línea de sesgo dinámica, no como una compra/venta mágica."},{"h":"Banda inferior (COMPRAR práctica)","t":"El precio marcado en la banda inferior después de una caída puede significar \"estirado hacia abajo\". NO compres cada toque. Espere a que aparezca una vela alcista (Hammer, Engulfing) e idealmente el RSI."},{"h":"Banda superior (VENTA / precaución)","t":"Etiquetar el precio en la banda superior puede significar \"estirado hacia arriba\". En una tendencia alcista, el precio puede subir a la banda superior (caminar por la banda). Prefiera VENDER ideas solo con vela bajista + debilidad de TF más alta."},{"h":"Estrujar","t":"Bandas estrechas = baja volatilidad → a menudo sigue una ruptura. No adivine la dirección dentro de un espacio apretado; marque la ruptura y confirme con vela + volumen si está disponible."},{"h":"camina la banda","t":"En una tendencia fuerte, el precio abraza la banda superior (o inferior) de muchas velas. Luchar contra eso con desvanecimientos de reversión a la media es un error común de los principiantes."},{"h":"Laboratorio de gráficos BB +","t":"En CPE Chart Lab / escritorios, estudie BB con velas en DEMO. Práctica: banda inferior + Martillo → Paper Trade con SL debajo de la mecha, TP1 cerca de la banda media."},{"h":"Combinación BB + RSI","t":"Filtro de práctica más fuerte: BB inferior + sobreventa del RSI (o aumento desde sobreventa) + vela alcista. BB superior + sobrecompra RSI + vela bajista para práctica corta."},{"h":"Detener colocación","t":"Práctica larga: SL bajo el swing bajo / debajo de la mecha de la banda inferior. Práctica corta: SL por encima del swing alto. Nunca inicie operaciones con BB sin un SL escrito."},{"h":"Objetivos","t":"Camino común: TP1 en banda media, TP2 hacia banda o sendero opuesto. Ampliación: no es necesario realizar todo el movimiento."},{"h":"Plazos","t":"Decidir el sesgo sobre un TF más alto (4H/1D). Entra en BB + vela de 15m/30m. La mezcla de TF aleatorios provoca señales contradictorias."},{"h":"Errores a evitar","t":"Comprar cada toque de banda inferior en un mercado en crisis; vender cada toque superior en una carrera lunar; sin SL; ignorando los picos de noticias que amplían violentamente las bandas."},{"h":"Lista de verificación de práctica","t":"① Mayor sesgo de TF ② Toque BB o ruptura de presión ③ Confirmación de vela ④ RSI de acuerdo ⑤ % de riesgo establecido ⑥ Papel primero ⑦ Resultado del diario."}]},{"id":"rsi","title":"2 · RSI (Índice de Fuerza Relativa)","summary":"Oscilador de momento 0–100. Por defecto 14 períodos. Úselo con BB y velas; nunca RSI solo como sistema completo.","lessons":[{"h":"Qué mide el RSI","t":"RSI compara las ganancias promedio con las pérdidas en N barras. RSI alto = impulso alcista reciente; RSI bajo = impulso bajista reciente. No siempre hay “sobrecompra = hay que vender”."},{"h":"Zonas clásicas","t":"A menudo: por encima de 70 = zona de sobrecompra, por debajo de 30 = zona de sobreventa. En tendencias fuertes, el RSI puede permanecer sobrecomprado/sobrevendido durante mucho tiempo, eso es normal."},{"h":"Línea media 50","t":"Un cruce del RSI por encima de 50 puede respaldar un sesgo alcista; por debajo de 50 sesgo bajista. Muchos traders utilizan 50 como filtro de tendencia con banda media BB."},{"h":"Divergencia – alcista","t":"El precio baja, el RSI sube mínimo → el impulso se debilita a la baja. Todavía estoy esperando la ruptura de vela + estructura antes de la entrada del papel."},{"h":"Divergencia – bajista","t":"Precio máximo más alto, RSI máximo más bajo → el impulso alcista se desvanece. Confirme con Shooting Star / Engulfing cerca de la resistencia o BB superior."},{"h":"Cambios de fracaso","t":"El RSI no logra volver a probar el extremo anterior y luego vuelve a cruzar 50: pista inicial del cambio de impulso. Combínelo con la estructura de Chart Lab."},{"h":"RSI + BB (estilo CPE)","t":"Practique largo: precio cerca del BB inferior, RSI ≤ 35 (o subiendo desde ≤ 30), vela alcista. Practique corto: BB superior, RSI ≥ 65–70, vela bajista."},{"h":"Divergencia oculta","t":"Pista de continuación de la tendencia (por ejemplo, precio mínimo más alto, mínimo más bajo del RSI en una tendencia alcista). Avanzado: primero domine la divergencia clásica en DEMO."},{"h":"Configuración","t":"RSI(14) es el valor predeterminado común. RSI más corto = más ruido. No sigas cambiando la configuración para forzar una señal."},{"h":"Sale con RSI","t":"Si compró sobreventa, es razonable obtener ganancias parciales cuando el RSI alcance la zona media/superior. Sigue el resto con estructura o BB medio."},{"h":"Noticias y RSI","t":"Las grandes noticias pueden disparar el RSI instantáneamente. Prefiera esperar a que termine la primera vela violenta antes de actuar sobre los extremos del RSI."},{"h":"Errores","t":"Poner en corto cada RSI>70 en un mercado alcista; anhelar cada RSI <30 en una caída bajista; sin confluencia; reingreso de venganza cuando el RSI \"se ve mejor\"."},{"h":"Lista de verificación de práctica","t":"① Anote el valor RSI + pendiente ② Verifique la ubicación de BB ③ Confirme la vela ④ TF más alto ⑤ Papel + diario ⑥ Una idea a la vez."}]},{"id":"fib","title":"3 · Fibonacci (Retroceso y Extensión)","summary":"Mida los retrocesos y los objetivos desde un claro movimiento alto → movimiento bajo (o retroceso). Concéntrese en 38,2 · 50 · 61,8 con confluencia BB/RSI.","lessons":[{"h":"Por qué se usa Fib","t":"Muchos traders observan los mismos ratios, por lo que la liquidez suele reaccionar cerca de ellos. Fib es un mapa de posibles zonas, no una garantía."},{"h":"Puntos de oscilación","t":"Siempre dibuja desde un swing claro de bajo a un swing alto (movimiento hacia arriba) o de alto a bajo (movimiento hacia abajo). Malos cambios = niveles inútiles. Practica cómo elegir cambios en Chart Lab DEMO."},{"h":"Retrocesos clave","t":"Común: 23,6% (superficial), 38,2%, 50% (no Fib puro pero ampliamente utilizado), 61,8% (dorado), 78,6% (profundo). Los retrocesos profundos pueden indicar debilidad de la tendencia."},{"h":"Compras de retroceso (tendencia alcista)","t":"Después del impulso alcista, espere un retroceso a la zona 38,2–61,8 + vela alcista + preferiblemente soporte medio/inferior BB o mantenimiento del RSI >40–45."},{"h":"Ventas de retroceso (tendencia bajista)","t":"Después del impulso bajista, repunte hasta 38,2–61,8 + vela bajista + RSI cayendo por debajo de 55–60."},{"h":"Extensiones/objetivos","t":"Extensiones comunes: 127,2%, 161,8% más allá del swing para ideas TP2. Úselo con el rastro: no fuerce los tics exactos."},{"h":"Confluencia = poder","t":"Zonas de mejores prácticas: Fib 50/61.8 + BB medio/inferior + estructura previa + giro RSI. Una sola línea de Fib es débil."},{"h":"Fib + BB","t":"Si el 61,8% se ubica cerca del BB inferior en una tendencia alcista, esa superposición es una zona de estudio de Paper de alta calidad. Ingrese solo con confirmación de vela."},{"h":"Múltiples mentiras","t":"Los principiantes deben usar UN swing limpio. Apilar 5 Fibs crea ruido en los gráficos y entradas FOMO."},{"h":"Invalidación","t":"Si el precio cierra claramente por encima del 78,6% en contra de su tendencia, la tesis del retroceso a menudo falla: salga o permanezca al margen."},{"h":"Forex vs cripto","t":"Mismas proporciones. Las grandes empresas de Forex suelen respetar los niveles de forma más limpia en sesiones líquidas; Las criptomonedas pueden pasar y luego revertirse, con un tamaño más pequeño."},{"h":"Errores","t":"Dibujar Fib en pequeños cambios de ruido; entrar en el aire sin vela; moviendo SL más lejos cuando Fib “casi” se mantuvo; ignorando un TF más alto."},{"h":"Lista de verificación de práctica","t":"① Mark swing ② Nota 38.2/50/61.8 ③ Espere a que llegue el precio ④ Vela + RSI/BB ⑤ Conjunto de riesgos ⑥ Papel → diario."}]},{"id":"money","title":"4 · Gestión del dinero","summary":"Cómo se utiliza realmente el método: arriesgar un porcentaje fijo, tamaño desde el stop, depositar parte de las ganancias y stop para el día siguiente con un límite de pérdidas. CPE puede aplicar esto en operaciones manuales y automáticas.","lessons":[{"h":"Objetivo de la gestión del dinero","t":"Mantente en el juego. Una mala operación nunca debería borrar la cuenta. La consistencia supera al tamaño de la lotería."},{"h":"Cómo lo utilizan realmente los comerciantes","t":"La práctica común es el riesgo fraccionado fijo. No eliges primero la cantidad de moneda. Primero escribe la parada, decide que esta idea puede perder aproximadamente el 1% de la cuenta y luego el tamaño se reduce. Un stop amplio obtiene una posición más pequeña. Un stop estricto consigue una posición mayor y el riesgo del dólar se mantiene más o menos igual. Este es el método que utiliza CPE cuando la opción de administración de dinero está activada."},{"h":"Ejemplo resuelto ($1000 cuenta de práctica)","t":"Cuenta $1000. Riesgo 1% = $10. Entrada 100, parada 98. Distancia = 2%. Tamaño = 10 ÷ 0,02 = $500 nocionales. Si se alcanza el tope, la pérdida es de aproximadamente $10, no $500. Si el precio llega a 103 (1,5 veces el riesgo), la ganancia es de aproximadamente 15 dólares. La misma idea para cada par: los dólares en riesgo se mantienen cerca del 1%, la cantidad de la moneda cambia."},{"h":"¿Qué hace CPE con la garrapata?","t":"Opere ahora → Automático: marque “Usar administración de dinero”. Guardar configuración automática. Cada nueva operación automática utiliza aproximadamente el 1% de una cuenta de práctica de $1000 más los resultados cerrados, dimensionados a partir de la entrada de esa señal y SL. Se respetan los mínimos al contado y de futuros: si el mínimo de cambio arriesgaría más del 1%, esa operación se omite. Después de aproximadamente -2% en el día calendario, los autos nuevos se detienen hasta el día siguiente. Como máximo, alrededor del 3% está en riesgo en las operaciones abiertas. El comercio manual tiene el mismo tick. El historial de señales todavía muestra la prueba equivalente de $10 y debajo de ella el tamaño del plan del 1% para una cuenta de $1000, por lo que puede ver ambos."},{"h":"Beneficio parcial y el rastro.","t":"La práctica consiste en participar en el primer objetivo (a menudo alrededor de la mitad) y dejar que el resto siga. Cuando el stop sube, el objetivo también puede moverse, por lo que el ganador puede pagar más que el primer objetivo. El riesgo sobre la idea original no aumenta. Una señal fuerte no es motivo para arriesgar el 5%. Se utiliza el mismo 1%. El camino es lo que permite crecer a un ganador fuerte."},{"h":"Parada diaria y calor abierto.","t":"Una regla usada: si el día baja alrededor del 2% de la cuenta, deje de abrir operaciones. Tres ideas abiertas al 1% cada una equivalen aproximadamente al 3% de calor. Cinco monedas correlacionadas son una apuesta, no cinco. Cuéntelos juntos."},{"h":"Lo que este método rechaza","t":"No se utiliza la martingala (doblar después de una pérdida). No se utiliza mover la parada más lejos para “darle espacio” después de la entrada. No se utiliza all-in en una señal \"segura\". Si no hay una parada válida, no hay tamaño, por lo que no hay comercio."},{"h":"Riesgo por operación","t":"Regla común: arriesgar solo entre el 0,5% y el 1% del capital de la cuenta en una sola idea. En DEMO, practica el mismo hábito porcentual que EN VIVO."},{"h":"Fórmula de tamaño de posición","t":"Tamaño ≈ (Cuenta × Riesgo%) ÷ (Entrada − Distancia de parada). SL más ancho → tamaño más pequeño. Nunca elija el tamaño primero y el SL en segundo lugar."},{"h":"Riesgo: recompensa","t":"Prefiera ideas donde la recompensa potencial sea ≥ riesgo (por ejemplo, 1:1,5 o mejor) al aprender. Ampliar en TP1 para que los corredores estén \"libres de riesgo\"."},{"h":"Toma de ganancias parcial","t":"Estilo CPE: TP1 bloquea algunas ganancias, TP2/trazado para el resto. Los parciales bancarios reducen el pánico emocional."},{"h":"TP final + SL","t":"COMPRAR: el sendero sube de nivel a medida que sube el precio. VENDER: sendero hacia abajo. Los bloqueos finales abren ganancias sin necesidad de una llamada de salida perfecta."},{"h":"Límite de pérdida diaria/semanal","t":"Regla de ejemplo: dejar de operar el día siguiente a la cuenta del −2%. Las sesiones de venganza después de un límite de pérdidas matan cuentas."},{"h":"Tamaño del punto","t":"Los valores mínimos al contado son importantes (por ejemplo, los mínimos de intercambio). Aún aplique el% de riesgo: si el tamaño mínimo arriesga demasiado en comparación con su SL, omita la operación."},{"h":"Futuros / apalancamiento","t":"El apalancamiento multiplica tanto las ganancias como las pérdidas. Alto apalancamiento + SL amplio = cuenta arruinada. Prefiera un apalancamiento bajo mientras aprende; El aislamiento puede limitar las pérdidas por posición."},{"h":"Correlación","t":"Abrir 5 alts BTC correlacionados = una gran apuesta, no cinco. Cuente el riesgo como grupo."},{"h":"Tarifas y deslizamiento","t":"Los cueros cabelludos ajustados se ven bien en el gráfico, pero las tarifas consumen R:R. Prefiere columpios más limpios en DEMO hasta que conozcas los costos."},{"h":"DEMO → Puente EN VIVO","t":"Práctica DEMO de CPE (~3 meses de mentalidad): mismas reglas de diario, mismo porcentaje. Cuando esté EN VIVO, comience con la mitad del tamaño DEMO durante las primeras semanas."},{"h":"Seguridad del dinero API","t":"Retiros APAGADOS en cada clave. Vive solo después de que la cuenta de prueba esté bien en la plataforma coincidente. Secreto de plataforma incorrecto = operaciones fallidas o peligrosas."},{"h":"Errores","t":"Martingala (doble tras pérdida); moviendo SL más lejos; todo incluido en configuraciones \"seguras\"; ignorando el tamaño mínimo versus el% de riesgo; Negociar sin parada diaria."},{"h":"Lista de verificación de práctica","t":"① % de riesgo escrito ② Tamaño desde la distancia SL ③ TP1/TP2/recorrido planificado ④ Pérdida diaria máxima conocida ⑤ Papel primero ⑥ Diario PnL honestamente."}]},{"id":"psych","title":"5 · Psicología para el Trading","summary":"La mentalidad decide si las habilidades BB/RSI/Fib sobreviven a las pantallas reales. FOMO, venganza, exceso de confianza, miedo: entrénelos en indicadores tipo DEMO.","lessons":[{"h":"Por qué es importante la psicología","t":"Un plan BB+RSI perfecto falla si ingresa temprano, se salta SL o realiza operaciones de venganza. Habilidad = sistema × disciplina."},{"h":"Proceso sobre predicción","t":"No es necesario predecir el futuro. Debe ejecutar reglas: configurar → riesgo → administrar → diario. Los resultados varían; El proceso es controlable."},{"h":"FOMO","t":"Miedo a perderse algo = perseguir velas verdes que ya están lejos de la zona BB/Fib. Regla: si te perdiste la entrada, espera a la siguiente configuración. Chart Lab siempre tiene otra vela."},{"h":"Comercio de venganza","t":"Después de una pérdida, la necesidad de “recuperarla ahora” destruye las cuentas. Enfriamiento obligatorio: aléjese, registre la pérdida y realice la siguiente operación solo si la lista de verificación está limpia."},{"h":"Exceso de confianza después de las victorias","t":"3 victorias seguidas ≠ aumentar el tamaño 5×. Mantenga el % de riesgo fijo. Las rachas ganadoras ocurren cuando la mayoría de la gente rompe las reglas del dinero."},{"h":"Miedo después de las pérdidas","t":"Saltarse todas las configuraciones válidas después de un día rojo también es un sesgo. Confíe en el plan escrito; reduzca el tamaño temporalmente si es necesario, no abandone el proceso."},{"h":"Parálisis del análisis","t":"10 indicadores no están de acuerdo → congelarse. Cíñete al núcleo de CPE: velas + BB + RSI (+ zona Fib). Calidad sobre cantidad de herramientas."},{"h":"Inclinación y noticias","t":"Las grandes velas rojas sobre las noticias aumentan la adrenalina. Prefiere permanecer plano durante las principales incógnitas hasta que la estructura se reforme: el ego quiere acción; El plan requiere paciencia."},{"h":"Diario = terapia + datos","t":"Escriba etiquetas de emociones (FOMO, prisa, calma) en CPE Journal. Los patrones en los sentimientos revelan fugas más rápidamente que la PnL por sí sola."},{"h":"reglas escritas","t":"Si no está escrito, no es una regla. Ejemplo: \"Solo BB+vela+RSI; riesgo 1%; no realizar transacciones después del -2% del día; DEMO hasta la lista de verificación de 20 artículos\"."},{"h":"Medio ambiente","t":"El sueño, el hambre y la distracción del teléfono cambian las decisiones. No aumentes el tamaño cuando estés agotado. El trading es atlético: protege el cerebro."},{"h":"Ruido social","t":"Las “señales” de Telegram y las exageraciones rompen tu plan. Clase de aprendizaje CPE + tu diario > consejos aleatorios. Filtre noticias y trucos según el contexto, no según los pedidos."},{"h":"Cambio de identidad","t":"Piense \"sigo mi lista de verificación\", no \"debo tener razón\". Equivocarse con un riesgo pequeño es normal; ser terco con un gran riesgo es opcional."},{"h":"DEMO como gimnasio","t":"Utilice DEMO/Paper para ensayar emociones de forma segura. Si no puedes seguir las reglas en DEMO, LIVE no arreglará mágicamente la disciplina."},{"h":"Lista de verificación de práctica","t":"① ¿Estoy tranquilo? ② ¿Lista de verificación completa? ③ ¿Porcentaje de riesgo sin cambios? ④ ¿No es venganza? ⑤ ¿Escribiré un diario honestamente? En caso afirmativo NO → no hay intercambio."}]},{"id":"signals","title":"6 · Señales CPE: significado y qué hacer","summary":"Los escritorios Spot / Futuros / Forex muestran COMPRAR · VENDER · MANTENER + puntuación. La misma idea de motor en todas las plataformas, pero solo opera en la plataforma cuya clave API guardó. Esto es lo que significa cada señal y los pasos exactos después de que aparece.","lessons":[{"h":"De donde vienen las señales","t":"CPE puntúa BB, RSI, Fibonacci, vela, cruce EMA, SMA50, MACD e impulso. Puntuación ≥ +3 → COMPRAR. Puntuación ≤ −3 → VENDER. En el medio → MANTENER. Esta es una calificación de ayuda, no una promesa de ganancias."},{"h":"Señal de COMPRA — significado","t":"La confluencia alcista es más fuerte en este momento (ejemplos: menor rebote de BB, giro de sobreventa del RSI, vela alcista, cruce dorado, soporte de Fib). Los TP1 / TP2 / SL sugeridos aparecen en la fila / Chart Lab / Trade Now."},{"h":"Señal de VENTA - significado","t":"La confluencia bajista es más fuerte (BB superior / RSI sobrecomprado / vela bajista / cruce de la muerte / resistencia Fib). En el mercado al contado, VENDER generalmente significa salir/reducir posiciones largas o cortas sólo si su mercado permite posiciones cortas (Futuros/Forex)."},{"h":"Señal HOLD - significado","t":"Puntuación mixta o débil. NO fuerces un intercambio. Plano es correcto. Lista de seguimiento ★ y espere una COMPRA/VENTA más clara o un candidato BB Lower."},{"h":"Número de puntuación","t":"Mayor |puntuación| = más acuerdo entre herramientas. UNA COMPRA +5 es más fuerte que COMPRAR +3; aún así, confirme en las velas de Chart Lab antes del tamaño."},{"h":"Tablero inferior BB","t":"Lista separada de pares que etiquetan la banda inferior de Bollinger: practique candidatos largos. Todavía necesito confirmación de vela + RSI; No cada toque inferior es una entrada."},{"h":"Plataforma vs señal (importante)","t":"La matemática de señales es la misma idea en Binance, Bybit, OKX, KuCoin, Bitget, Gate, MEXC, Kraken, Coinbase, OANDA, FXCM, MT5, Forex Demo. Lo que cambia es DONDE envías el pedido: solo la plataforma seleccionada en Claves API / Trade Now. Una COMPRA de Binance no se abre en Bybit."},{"h":"Plataformas Crypto Spot","t":"Binance Spot, Coinbase, etc.: COMPRAR = comprar la moneda con cotización (por ejemplo, USDT). VENDER = vender participaciones / obtener ganancias. El tamaño mínimo (por ejemplo, ~$11) es importante. Sin apalancamiento."},{"h":"Plataformas de futuros criptográficos","t":"Binance Futures, Bybit, OKX, Bitget…: COMPRAR = largo; VENDER = corto. Elija Cruzado/Aislado + apalancamiento con cuidado. Sendero: COMPRAR senderos TP+SL hacia arriba; VENDER cae."},{"h":"plataformas de divisas","t":"OANDA / FXCM / MT5 / Forex Demo: mismas etiquetas COMPRAR/VENDER/MANTENER en pares FX (EURUSD…). COMPRAR = comprar moneda base; VENDER = vender base. Lotes (por ejemplo, 0,01) en lugar de cantidad de monedas. Las sesiones y las noticias importan más."},{"h":"Cuando aparezca una COMPRA, haz esto","t":"① Abra la fila → lea Por qué / vela / RSI. ② Confirmación del laboratorio de gráficos (15 m – 1 h). ③ DEMO primero: Opere ahora → configure TP1/TP2/SL/trail → Iniciar demostración/papel. ④ Solo después de que la prueba API esté bien en esa plataforma → pequeño EN VIVO. ⑤ Resultado del diario."},{"h":"Cuando aparezca una VENTA, haga esto","t":"① Si tiene una posición larga en Spot: considere TP/cierre parcial/trazado – no lo ignore. ② Si Futures/Forex y el plan permiten posiciones cortas: confirme Chart Lab y luego Paper/Live short con SL. ③ Si HOLD fue mejor ayer, no te vengas del tamaño del flip."},{"h":"Cuando aparezca HOLD, haz esto","t":"No hay nueva entrada manual. Sigue escaneando. Agregue ★ lista de seguimiento. Clase de aprendizaje de estudio/laboratorio de gráficos. Proteja las posiciones abiertas con seguimiento solo si ya está en una operación."},{"h":"Comercio automático + señal","t":"La COMPRA automática se puede abrir cuando las reglas de puntuación BB Lower + Strong coinciden con la configuración automática guardada. Sigue siendo la prueba DEMO automática primero. LIVE Auto = riesgo real – Retiros APAGADOS, tamaño pequeño."},{"h":"Notificaciones","t":"COMPRAR Los brindis de señal siguen tu idioma. Trátelos como alertas para abrir el escritorio, no como órdenes de mercado en sí mismas."},{"h":"Que NO hacer","t":"No compre todas las COMPRAS sin gráfico. No utilices la clave de Binance en Bybit. No te saltes SL. No aumente el tamaño después de una señal verde. No cambie MANTENER como \"casi COMPRAR\"."},{"h":"tarjeta de acción rápida","t":"Señal → Laboratorio de gráficos → % de riesgo → TP1/TP2/SL → Documento DEMO → Diario → (más tarde) EN VIVO en la clave de plataforma coincidente."}]},{"id":"forex_sig","title":"7 · Señales de Forex: significado y qué hacer","summary":"Forex Desk utiliza la misma calificación COMPRAR / VENDER / MANTENER en los pares de divisas. Descubra en qué se diferencian las señales de Forex de las criptomonedas y los pasos exactos desde Señal → Papel → Broker en vivo.","lessons":[{"h":"Señales de mesa de Forex","t":"EURUSD, GBPUSD, USDJPY… obtenga COMPRAR / VENDER / MANTENER + puntuación como criptografía. Haga clic en una fila para ver el gráfico, el texto de psicología y los niveles sugeridos."},{"h":"COMPRAR en Forex — significado","t":"Compre la moneda base (por ejemplo, COMPRAR EURUSD = comprar EUR vs USD). Espere que el precio suba. Utilice el intervalo de Forex de Chart Lab que practique (15 m/30 m/1 H)."},{"h":"VENDER en Forex — significado","t":"Vender la base (cortar el par). Espere que el precio baje. Siempre establezca SL por encima de la idea de estructura/banda superior."},{"h":"MANTENER en Forex","t":"No hay un borde claro: salta. Especialmente antes de grandes noticias (NFP, IPC, banco central), prefieren MANTENER/plano."},{"h":"Plataforma de tasas de demostración de Forex","t":"Sin clave API. Tablas de práctica + Solo papel. Perfecto para ejercicios de clase de aprendizaje antes de OANDA/FXCM/MT5 en vivo."},{"h":"Señal de OANDA → acción","t":"① Mesa Forex COMPRA/VENTA. ② Confirmación del laboratorio de gráficos. ③ Claves API → token OANDA + ID de cuenta → Prueba. ④ Primero el documento DEMO en CPE. ⑤ Lotes vivos pequeños (mentalidad 0,01) con TP/SL/trail."},{"h":"FXCM/MT5","t":"Misma lectura de señal. Conecte las credenciales de ese corredor en Claves API. Signal no inicia sesión automáticamente en MT5 hasta que se configuran las claves/puente; practique en papel hasta que la prueba sea correcta."},{"h":"Sesiones","t":"La superposición entre Londres y Nueva York a menudo conmueve más a las grandes empresas. Asia puede estar más tranquila: MANTENER es común y saludable."},{"h":"Difusión y noticias","t":"En torno a las noticias, los diferenciales se amplían: una buena COMPRA técnica aún puede ser un mal complemento. Consultar noticias y trucos; espere a que la vela se cierre después del pico."},{"h":"Lotes vs cantidad criptográfica","t":"Tamaño de Forex = lotes, no USDT nocional de la misma manera. El porcentaje de riesgo sigue dominando: SL más amplio → lotes más pequeños."},{"h":"BB más bajo en Forex","t":"Misma idea: par cerca de la banda inferior + Martillo + RSI en aumento = practicar un estudio prolongado. Confirme un mayor sesgo de TF (4H/Diario)."},{"h":"Cuando se dispara Forex BUY: pasos","t":"① Lea por qué. ② ¿Está bien un mayor sesgo de TF? ③ Marque SL más allá de la mecha/estructura. ④ Comercio de papel. ⑤ Si el corredor en vivo está listo → tamaño pequeño + rastro. ⑥ Sesión de diario (Londres/NY) + emoción."},{"h":"Cuando se dispara Forex SELL: pasos","t":"① Confirme que no haya un aumento a mitad de las noticias. ② Vela bajista de Chart Lab. ③ Papel corto o cierre largo. ④ Camino hacia abajo si es corto. ⑤ No duplique el lote después de fallar."},{"h":"Diferencia entre Forex y criptomonedas","t":"Cripto 24 horas al día, 7 días a la semana; Forex tiene sesiones. Cripto min $ a menudo; Lotes de Forex + valor del pip. Cripto muchas alternativas correlacionadas; Limpiador de Forex Majors para aprender."},{"h":"Lista de verificación de práctica (FX)","t":"① ¿Par mayor? ② ¿Sesión correcta? ③ ¿Noticias claras? ④ ¿Señal COMPRAR/VENDER no MANTENER? ⑤ ¿Confirma el gráfico? ⑥ ¿% de riesgo? ⑦ Papel → diario → clave de corredor en vivo solo cuando esté listo."}]},{"id":"fomo","title":"8 · FOMO y disciplina emocional","summary":"FOMO, venganza, codicia y miedo son los verdaderos asesinos de cuentas, no indicadores. Conozca los factores desencadenantes, los signos corporales y las reglas exactas que mantienen las operaciones impulsivas fuera de su cuenta.","lessons":[{"h":"¿Qué es realmente FOMO?","t":"FOMO = el miedo a perderte un movimiento que ya está lejos de tu zona. Te hace entrar tarde con peor precio y sin SL adecuado. La vela que “perdiste” es información, no una pérdida."},{"h":"Los tres desencadenantes de FOMO","t":"① Una gran vela verde o roja en el gráfico. ② Una publicación de un amigo o de Telegram que muestre ganancias. ③ Un titular de noticias. Observe el desencadenante antes de notar la entrada."},{"h":"signos corporales","t":"Latidos cardíacos rápidos, inclinarse hacia la pantalla, una necesidad urgente de hacer clic en \"comprar en el mercado\" y saltarse la lista de verificación. Si los siente, cierre la pestaña y espere una vela."},{"h":"La regla \"ya se ejecutó\"","t":"Si el precio se ha movido más de 1 ATR más allá de su entrada planificada, la operación desaparece. Espere un retroceso a BB mid/Fib o sáltelo. Siempre hay otra configuración."},{"h":"La trampa de la vela verde","t":"Un Marubozu que no planeaste es una persecución, no una entrada. Las entradas tardías tienen la peor recompensa: el riesgo de que la parada acabe muy lejos."},{"h":"Comercio de venganza","t":"Después de una pérdida, el cerebro quiere recuperarla ahora. Regla: no realizar nuevas entradas durante 15 a 30 minutos después de una pérdida, y solo si la lista de verificación está limpia. El mercado no te debe nada."},{"h":"Miedo a apretar el gatillo","t":"El problema opuesto: aparece una configuración perfecta y te congelas. Utilice un pequeño tamaño DEMO para probar el proceso y decida su tamaño ANTES de que aparezca la vela para que la decisión ya esté tomada."},{"h":"Codicia después de las victorias","t":"Dos intercambios verdes te hacen sentir invencible y luego duplicas tu tamaño. Mantenga el porcentaje de riesgo fijo para al menos 20 operaciones; Las rachas ganadoras significan reversión."},{"h":"Comercio de aburrimiento","t":"Piso es una posición. Si no existe una configuración A+, no hagas que suceda nada. Los intercambios de aburrimiento son FOMO disfrazados."},{"h":"Disciplina frente a la pantalla","t":"Establezca dos o tres ventanas de escaneo por día en lugar de mirar gráficos. Menos decisiones significan menos decisiones impulsivas."},{"h":"Diario emocional","t":"Etiqueta cada intercambio con calma / prisa / FOMO / venganza. Después de 20 operaciones, el patrón de sus fugas se vuelve obvio."},{"h":"Restablecer ritual","t":"Después de una pérdida o un desliz de FOMO: levántese, respire lentamente 10 veces, escriba una oración sobre lo que sucedió, luego deténgase durante una hora o continúe con la mitad del riesgo normal."},{"h":"Lista de verificación de práctica","t":"① ¿Cuerpo tranquilo? ② ¿Se ha notado el gatillo? ③ ¿Configuración en mi zona? ④ ¿SL escrito primero? ⑤ ¿Porcentaje de riesgo sin cambios? ⑥ ¿No es venganza? Cualquier NO → no hay intercambio."}]},{"id":"risk_deep","title":"9 · Gestión de riesgos y dinero: profunda","summary":"Las matemáticas que mantienen viva una cuenta: tamaño fraccionario fijo, múltiplos R, matemáticas de reducción, calor de correlación y parada diaria. Convierta el comercio en un negocio dirigido por números.","lessons":[{"h":"Riesgo fijo-fraccional","t":"Arriesgue un porcentaje fijo (0,5–1 %) del capital por idea. El tamaño es el RESULTADO de la distancia de parada, nunca elegido primero. Ancho SL → tamaño pequeño; apretado SL → tamaño más grande; El riesgo del dólar sigue siendo el mismo."},{"h":"La fórmula del tamaño","t":"Tamaño = (Capital × Riesgo%) ÷ |Entrada − Detener|. Ejemplo: $1000 × 1% = $10 de riesgo. Entrada 100, parada 98 → distancia 2% → tamaño 10 ÷ 0,02 = $500 nocionales."},{"h":"Piensa en R-múltiplos","t":"Riesgo 1R por operación. Un ganador 2R paga por dos pérdidas. Realice un seguimiento de su R promedio en 20 operaciones: esa es su ventaja real, no la tasa de ganancias."},{"h":"Recompensa: riesgo","t":"Apunte a tener al menos 1,5 R de potencial antes de entrar. Por debajo de eso, omítelo a menos que tu tasa de ganancias sea muy alta."},{"h":"Matemáticas de reducción","t":"Una reducción del −50% necesita +100% para recuperarse. Las rachas de derrotas son normales: incluso un sistema con una tasa de victorias del 60% tiene rachas de más de 5 derrotas. Un pequeño riesgo mantiene la racha sobrevivible."},{"h":"La parada diaria","t":"Regla estricta: dejar de abrir operaciones después del −2% del capital en un día (o 2 o 3 pérdidas seguidas). Las sesiones de venganza después del límite son asesinas de cuentas."},{"h":"Límites semanales y mensuales","t":"También limite la semana (por ejemplo −5%) y el mes. Cuando lo presione, vaya a DEMO, revise el diario y luego haga una copia de seguridad del tamaño solo después de una ejecución limpia."},{"h":"calor abierto","t":"El riesgo total en todas las operaciones abiertas debería mantenerse en torno al 3% o menos. Cinco alternativas correlacionadas son una apuesta, no cinco: cuenten juntas la exposición correlacionada."},{"h":"Tamaño del punto","t":"El spot tiene un nocional mínimo. Si el mínimo de intercambio arriesgaría más de su 1%, omita la operación; nunca redondee el riesgo al alza."},{"h":"Dimensionamiento de futuros","t":"El apalancamiento cambia el margen, no el riesgo. El riesgo sigue siendo Entrada − Stop × tamaño. Utilice un apalancamiento bajo mientras aprende y prefiera un margen aislado."},{"h":"Tamaño de divisas","t":"Riesgo = lotes × valor de pip × stop-pips. Resuelve por lotes. Guía aproximada: 0,01 lote ≈ $0,10 por pip; un stop de 20 pips arriesgando el 1% de $1000 ($10) → 10 ÷ 0,10 ÷ 20 = 0,05 lotes."},{"h":"Ampliación","t":"Obtenga aproximadamente un 50% de descuento en TP1 para que el resto esté libre de riesgos y luego siga. Esto convierte a un buen trade en un corredor sin estrés."},{"h":"Compuesto vs fijo","t":"Arriesgar un % fijo del patrimonio ACTUAL (composición). No fije su riesgo en el tamaño de cuenta más alto de todos los tiempos."},{"h":"Tarifas y deslizamiento en R","t":"Reste las tarifas de R. Una tarifa del 0,2% frente a un cuero cabelludo del 0,5% puede limpiar el borde; prefiera cambios más limpios."},{"h":"La ley “no stop, no trade”","t":"Si no puede definir una parada lógica, no conoce su riesgo, por lo que no hay tamaño, por lo que no hay operación."},{"h":"Anti-martingala","t":"Nunca dobles después de una pérdida. Aumente el tamaño solo después de varias semanas disciplinadas y rentables de un proceso probado, e incluso entonces lentamente."},{"h":"Lista de verificación de práctica","t":"① Equidad conocida ② % de riesgo emitido ③ Stop definido ④ Tamaño desde el stop ⑤ Recompensa ≥ 1,5 R ⑥ Stop diario conocido ⑦ Calor correlacionado contado."}]},{"id":"sl_tp","title":"10 · Dominio de Stop Loss y Take Profit","summary":"Coloque el SL donde el mercado demuestre que está equivocado, obtenga ganancias en pasos y siga el stop para que pueda correr un ganador, exactamente lo que hace CPE con multi-TP y un SL final.","lessons":[{"h":"SL es una decisión, no un número","t":"Coloque el tope donde la idea queda invalidada (debajo del mínimo, la mecha o la estructura del swing), no a una distancia aleatoria en dólares. Estás comprando información: si el precio va aquí, mi razón es incorrecta."},{"h":"Paradas de estructura","t":"Largo: SL justo debajo de la mecha del swing bajo o de la banda inferior. Corto: justo por encima del máximo del swing. Proporcione un pequeño amortiguador para la propagación y el ruido de la mecha, aproximadamente entre 0,1 y 0,3 %."},{"h":"La volatilidad se detiene","t":"Los mercados más amplios necesitan paradas más amplias. Utilice ATR o la longitud de la mecha para dimensionar el stop, luego reduzca la posición para que el riesgo del dólar se mantenga igual."},{"h":"Por qué fracasa un SL de dólar fijo","t":"Un stop de $10 en BTC y un stop de $10 en EURUSD son riesgos completamente diferentes. La distancia debe medirse en %, no en dólares."},{"h":"Búfer anti parada de búsqueda","t":"CPE ignora un solo toque de mecha: necesita dos violaciones consecutivas más un pequeño amortiguador (0,15%) antes de cerrar. Eso evita que el ruido persiga su parada."},{"h":"Obtenga ganancias en pasos","t":"Nunca cierres el 100% a un precio. Ampliación: TP1 reserva una parte, luego TP2/trail se encarga del resto, por lo que un gran movimiento puede compensar a muchos perdedores."},{"h":"Niveles de múltiples TP","t":"CPE le permite agregar tantos niveles de TP como necesite, cada uno con su propio porcentaje cercano. Ejemplo: TP1 40%, TP2 30%, TP3 30%, o tome TP1 y siga al resto."},{"h":"Tras la parada","t":"Después de TP1, mueva el stop al punto de equilibrio; después de TP2 muévalo a TP1. Deje que el stop siga al precio para proteger la ganancia abierta mientras el corredor continúa."},{"h":"Eligiendo el sendero %","t":"Un camino estrecho asegura ganancias rápidamente pero sale temprano; un sendero ancho respira pero devuelve algo. Comience alrededor del 1% al 2% para criptografía y ajústelo en el modo de edición de Posiciones."},{"h":"corredores","t":"Cuando el precio recorre la banda en una tendencia fuerte, amplíe el objetivo y la trayectoria en lugar de tomar todo en TP2. Así es como una operación paga por una semana entera."},{"h":"Botones de cierre parcial","t":"Utilice los botones de cierre 50%/100% en Posiciones para control manual, o deje que Auto Close administre TP/SL según el plan."},{"h":"La trampa del equilibrio","t":"No mueva el SL al punto de equilibrio demasiado pronto, antes de TP1: los retrocesos normales lo dejarán fuera de buenas operaciones."},{"h":"Nunca amplíes una parada perdedora","t":"Alejar más el SL para darle espacio es la forma en la que las pequeñas pérdidas acaban con las cuentas. La parada que establezca antes de entrar es la parada."},{"h":"parada del tiempo","t":"Si una operación no hace nada durante muchas velas mientras se forma una configuración claramente mejor, cerrar sin cambios y redistribuir el riesgo es una salida válida."},{"h":"Lista de verificación de práctica","t":"① SL en la invalidación, no aleatorio ② Amortiguador para mechas ③ TP1 parcial planificado ④ Camino después de TP1 ⑤ Nunca ampliar el SL ⑥ Dejar correr un ganador."}]},{"id":"plan_journal","title":"11 · Plan comercial y diario","summary":"Un plan escrito convierte el comercio de un juego en un proceso. Conozca el plan de una página, la lista de verificación previa a la negociación y cómo llevar un diario para que sus filtraciones sean visibles.","lessons":[{"h":"¿Por qué escribir un plan?","t":"Si no está escrito no es una regla. Un plan elimina la toma de decisiones en vivo bajo estrés y hace que sus resultados sean mensurables."},{"h":"El plan de una página","t":"Par, mercado, configuración (BB + RSI + vela + zona Fib), dirección, entrada, SL, TP1 / TP2, tamaño (desde SL) y pérdida máxima diaria. Si alguna línea está en blanco → no hay comercio."},{"h":"Lista de verificación previa a la negociación","t":"¿Sesgo de mayor TF? · ¿Configurar en mi zona? ·¿Vela confirmada? · ¿RSI está de acuerdo? · ¿SL escrito? · Riesgo %? · ¿Recompensa ≥ 1,5R? · ¿Calma? Todos sí → comercio."},{"h":"Rutina previa a la sesión","t":"Consulta el calendario superior, los niveles clave y las novedades. Escriba los dos o tres pares de relojes de hoy antes de la sesión, no después de que explote la vela."},{"h":"Que escribir en el diario","t":"Símbolo, lado, entrada, salida, tamaño, R, motivo, período de tiempo, sesión y una etiqueta de emoción. CPE Journal guarda las pérdidas y ganancias y los motivos automáticamente; añade tus propias notas."},{"h":"Diario el POR QUÉ","t":"Registre lo que vio (preparación) y lo que sintió (calma/FOMO/apurado). Un resultado sin contexto no enseña nada."},{"h":"Pista R, no gana","t":"Dos operadores con la misma tasa de ganancias pueden obtener resultados opuestos. El R promedio y la reducción máxima importan más que el porcentaje de ganancias."},{"h":"Hábito de captura de pantalla","t":"Guarde el gráfico antes y después de cada operación. La revisión de 20 capturas de pantalla muestra su ventaja y sus fugas más rápido que cualquier indicador."},{"h":"revisión semanal","t":"Una vez a la semana, cuente sus operaciones, el R promedio, la mejor y peor configuración y las infracciones de reglas. Elija UNA fuga para repararla la próxima semana."},{"h":"Etiqueta las fugas","t":"Etiquetas comunes: entrada tardía, sin SL, sobredimensionado, SL movido, venganza, aburrimiento. Cuando una etiqueta se repite, conviértala en una regla estricta."},{"h":"Qué no registrar","t":"No registres solo a los ganadores. Las pérdidas son los datos. Un diario de únicas victorias es un folleto, no un diario."},{"h":"Planifique el paso DEMO → EN VIVO","t":"Pruebe el plan en DEMO para una cantidad determinada de operaciones con un R promedio positivo antes de arriesgar dinero real y luego comience con la mitad del tamaño."},{"h":"Lista de verificación de práctica","t":"① Plan escrito antes de la entrada ② Lista de verificación aprobada ③ Entrada en el diario + emoción ④ Revisión semanal ⑤ Una fuga reparada."}]},{"id":"leverage","title":"12 · Apalancamiento, Margen y Liquidación","summary":"El apalancamiento multiplica las pérdidas tan rápido como las ganancias. Conozca el margen, la liquidación, el margen aislado versus el margen cruzado y las reglas de seguridad que impiden que una operación borre la cuenta.","lessons":[{"h":"¿Qué es el apalancamiento?","t":"El apalancamiento le permite controlar una posición más grande con menos margen. Aumenta tanto las ganancias como las pérdidas, no aumenta su ventaja."},{"h":"Margen vs riesgo","t":"El margen es el depósito que bloquea el intercambio. El riesgo es entrada - parada × tamaño. El apalancamiento cambia el margen, nunca el riesgo en dólares."},{"h":"Liquidación","t":"Si las pérdidas consumen su margen, el intercambio fuerza el cierre de la posición (liquidación), a menudo en el peor momento. Mantenga su stop alejado del precio de liquidación."},{"h":"Aislado vs Cruz","t":"Aislado limita la pérdida al margen de esa posición. Cross utiliza todo el saldo de la billetera, lo que es más peligroso para los principiantes. Prefiero aislado mientras aprende."},{"h":"Apalancamiento más seguro","t":"Un apalancamiento bajo (2-5x) más una parada adecuada es mucho más seguro que 50x sin parada. El stop, no el número de apalancamiento, es su protección."},{"h":"La regla de la distancia de liquidación","t":"Compruebe que su SL se encuentre dentro del precio de liquidación. Si están cerca, reduce el tamaño hasta que quede un espacio cómodo."},{"h":"El apalancamiento no soluciona una mala entrada","t":"Un alto apalancamiento en una mala entrada simplemente pierde más rápido. Primero arregle la configuración y luego dimensione."},{"h":"Financiamiento y tarifas","t":"Los futuros perpetuos cobran financiación a lo largo del tiempo. Las retenciones prolongadas sobre delincuentes apalancados desangran los fondos: otra razón para dimensionar y cronometrar cuidadosamente."},{"h":"Al contado frente a futuros","t":"El spot no se puede liquidar (usted es dueño de la moneda). Los futuros pueden y pueden llegar a cero. Utilice Futuros únicamente con un plan escrito y un margen aislado."},{"h":"Dimensionamiento bajo apalancamiento","t":"Calcule el tamaño a partir de la distancia de parada y luego verifique que el margen resultante sea asequible. Nunca elijas el apalancamiento primero."},{"h":"La prueba de “una sola operación”","t":"Antes de entrar pregunte: si esto llega al tope, ¿es un encogimiento de hombros o un desastre? Si no se encoge de hombros, la talla es demasiado grande."},{"h":"Lista de verificación de práctica","t":"① Conjunto aislado ② Apalancamiento bajo ③ SL dentro del precio de liquidación ④ Tamaño desde el stop ⑤ ¿Puedo sobrevivir a una pérdida total aquí? sí → comercio."}]},{"id":"practice","title":"13 · Rutina de práctica y backtesting","summary":"La habilidad se basa en DEMO antes de EN VIVO. Aprenda un ciclo de práctica repetible, cómo realizar pruebas retrospectivas mediante gráficos de desplazamiento y cómo pasar a ganar dinero real de forma segura.","lessons":[{"h":"DEMO es el gimnasio","t":"Paper / DEMO existe para ensayar el proceso y tus emociones con riesgo cero. Si no puedes seguir las reglas en DEMO, LIVE no lo solucionará mágicamente."},{"h":"El circuito de práctica","t":"Elija una configuración (por ejemplo BB lower + Hammer + giro RSI). Marque 20 ejemplos históricos en el cuadro. Definir entrada / SL / TP. Registre el resultado. Repetir."},{"h":"Pruebas retrospectivas manuales","t":"Desplácese hacia atrás en Chart Lab, oculte el futuro y marque cada señal a mano. Entrena el reconocimiento de patrones y evita que te engañes."},{"h":"Tamaño de la muestra","t":"Diez intercambios no significan nada. Apunte a realizar entre 30 y 50 operaciones registradas de una configuración antes de juzgarla."},{"h":"Prueba directa en DEMO","t":"Después del marcado manual, ejecute la misma configuración en vivo en DEMO con las señales del software durante dos a cuatro semanas. Compare rellenos y emociones reales con el backtest."},{"h":"Una configuración a la vez","t":"No pruebe cinco sistemas a la vez. Domina un borde y luego agrega un segundo."},{"h":"Mantenga la rutina pequeña","t":"Una rutina diaria de 20 minutos (escanear, marcar, registrar, revisar) es mejor que seis horas de observación aleatoria de gráficos."},{"h":"Graduarse para VIVIR","t":"Criterios: R promedio positivo en más de 30 operaciones DEMO, reglas seguidas, sin episodios de venganza. Luego comience LIVE a la mitad del tamaño y escale lentamente."},{"h":"Regla de ampliación","t":"Aumente el tamaño sólo después de un número determinado de semanas disciplinadas y rentables, nunca después de una gran victoria."},{"h":"Cuando dar un paso atrás","t":"Alcance el límite de pérdidas diario o semanal, o observe repetidas infracciones de las reglas → regrese a DEMO y reconstruya la disciplina antes de continuar."},{"h":"Seguimiento de métricas de proceso","t":"Registre la tasa de aprobación de la lista de verificación, las infracciones de reglas por semana y el R promedio. Estos predicen el crecimiento mejor que un solo número de P/L."},{"h":"Ruta de práctica de CPE","t":"Clase de aprendizaje → Laboratorio de gráficos (configuraciones de marcas) → Comercio de papel → Revisión de revistas → Escritorios de señales en DEMO → pequeño EN VIVO en la clave de plataforma correspondiente."},{"h":"Lista de verificación de práctica","t":"① Una configuración elegida ② 30 ejemplos marcados ③ Prueba directa DEMO ④ Diario + revisión ⑤ R positivo → tamaño medio EN VIVO."}]},{"id":"volatility","title":"14 · Volatilidad y Martingala","summary":"Cómo leer la volatilidad del mercado (por qué está cambiando el precio), cómo se agrega a cada señal como una línea de razón y cómo funciona la escalera Martingala opcional, además de por qué es la forma más rápida de perder una cuenta cuando se usa descuidadamente.","lessons":[{"h":"¿Qué significa la volatilidad?","t":"La volatilidad es cuánto se mueve el precio, no en qué dirección. Alta volatilidad = velas anchas y oscilaciones rápidas. Baja volatilidad = un rango tranquilo y estrecho. La misma configuración tiene una confiabilidad muy diferente en cada uno."},{"h":"La lectura de volatilidad del CPE","t":"Cada señal ahora mide el rango promedio de la vela y el ancho de la banda de Bollinger, luego los compara con la normal reciente de ese par. Obtendrá BAJO / NORMAL / ALTO / EXTREMO más una línea de motivo en lenguaje sencillo: el \"por qué\" del cambio de mercado, que se muestra con la señal."},{"h":"Volatilidad EXTREMA = rebaja","t":"Cuando la cinta es EXTREMA, una nueva señal FUERTE se degrada a PRECAUCIÓN (se muestra el motivo). En un mercado de inestabilidad, el mismo patrón falla con mucha más frecuencia: las rupturas falsas y las mechas de parada son la norma."},{"h":"Qué hacer en ALTO/EXTREMO","t":"Tamaño más pequeño. Parada más amplia. Menos intercambios. Espere a que se complete la vela en lugar de un pico a mitad de la vela. Si la lectura dice EXTREMO, trate la configuración como una zona de estudio, no como una entrada."},{"h":"¿Qué es la martingala?","t":"La martingala se suma a una posición perdedora para bajar la entrada media: después de cada movimiento adverso se añade otra orden, normalmente mayor (1x, 2x, 4x…). Gana a menudo y luego lo pierde todo en una mala racha."},{"h":"La regla de la martingala CPE","t":"CPE agrega una orden adicional solo cuando AMBAS son verdaderas: (1) el precio se ha movido en contra de la operación al menos en un paso × % de peldaño y (2) una nueva señal del mismo lado todavía se mantiene para ese par. Nunca aumenta solo porque el precio bajó."},{"h":"los cuatro numeros","t":"% de paso = movimiento adverso necesario antes de cada adición. Multiplicador = el tamaño de cada suma versus la base (1 = plano, 2 = doble). Max agrega = límite estricto en pedidos adicionales. % del límite de riesgo de la escalera = el riesgo de toda la escalera como porcentaje del capital. Los cuatro son tuyos para elegir."},{"h":"La tapa dura te protege","t":"Incluso con un gran multiplicador y muchas adiciones, CPE rechaza la orden una vez que el riesgo total de la escalera supera su porcentaje máximo de capital. También respeta el tamaño mínimo del intercambio y la parada diaria del −2%."},{"h":"donde corre","t":"Márquelo en Manual para administrar esa operación, o en una sesión Automática para administrar sus operaciones automáticas. Tanto DEMO como EN VIVO. En Manual, el par debe estar en la lista de exploración para que se pueda leer una señal nueva del mismo lado."},{"h":"Por qué es importante el límite (ejemplo)","t":"Paso 1%, multiplicador 2, tres sumas sobre una base de riesgo del 1%: el riesgo va del 1% → 2% → 4% → 8%. Una parada completa en el último peldaño borra a muchos ganadores. Por eso existe el límite y por eso las cifras predeterminadas son pequeñas."},{"h":"Alternativa anti-martingala","t":"Muchos profesionales hacen lo contrario: suman sólo a los ganadores y eliminan rápidamente a los perdedores. Se siente peor (más pérdidas pequeñas) pero no puede hacer estallar la cuenta en una sola tendencia en su contra."},{"h":"El riesgo no se elimina","t":"Promediar hacia abajo no elimina el riesgo: lo traslada de “muchas pérdidas pequeñas” a “una pérdida grande”. Nunca agregue dinero que no pueda perder y nunca apague el límite para “recuperar” una operación perdedora."},{"h":"Camino de práctica","t":"Conozca primero la lectura de volatilidad en DEMO. Pruebe Martingale con sumas máximas de 1 a 2 y un pequeño multiplicador en DEMO para más de 30 operaciones. Registre cada escalera y luego decida: la mayoría de los operadores consideran que el método plano/antimartingala es más seguro."},{"h":"Lista de verificación de volatilidad + martingala","t":"① Lea primero el nivel de volatilidad ② Saltar o reducir en EXTREMO ③ Martingala solo con una nueva señal del mismo lado ④ Paso × peldaño alcanzado ⑤ Por debajo del límite de riesgo → agregar. Cualquier “no” → sin agregar."}]},{"id":"lab_indicators","title":"15 · Indicadores de Chart Lab (Stoch · ADX · Ichimoku · VWAP)","summary":"Chart Lab ahora tiene una barra indicadora completa: cada botón es una marca de activación/desactivación que vuelve a dibujar el gráfico al instante. Además de BB / RSI / MACD / EMA / SMA50 / Volumen, ahora obtienes Stochastic, ADX/DMI, Ichimoku y VWAP, y el motor de señales también los lee, no solo el gráfico.","lessons":[{"h":"donde esta la barra","t":"Chart Lab → la fila de botones \"Indicadores\" debajo del gráfico. Un clic enciende un indicador, el siguiente clic lo apaga; el gráfico se vuelve a dibujar inmediatamente. Los ticks son visuales Y alimentan el motor de señales."},{"h":"Estocástico (14,3,3)","t":"Oscilador %K / %D dibujado debajo de las velas, escala 0–100. Por encima de ~80 = zona de sobrecompra, por debajo de ~20 = zona de sobreventa. %K cruzando %D en la zona de sobreventa es un estudio alcista; un cruce hacia abajo en la parte superior es bajista. En una tendencia fuerte, puede permanecer fijada en un extremo durante mucho tiempo; combínela siempre con BB y la vela."},{"h":"ADX/DMI (14)","t":"ADX mide la FORTALEZA de la tendencia, no la dirección. Por encima de ~25 = se está produciendo una tendencia real; por debajo de ~20 = un rango entrecortado. +DI arriba −DI = compradores a cargo; −DI arriba +DI = vendedores a cargo. Utilice ADX para decidir si operar con tendencia o permanecer estable."},{"h":"Nube Ichimoku (9,26,52)","t":"Tenkan (línea rápida), Kijun (línea lenta) y la nube Senkou. Precio por encima de una nube ascendente = fondo alcista; debajo de una nube que cae = bajista. Un cruce Tenkan/Kijun dentro de la nube es débil; un cruce con precio saliendo de la nube es más fuerte. El propio borde de la nube a menudo actúa como soporte/resistencia."},{"h":"VWAP","t":"Precio promedio ponderado por volumen: el precio promedio ponderado por volumen, restablecido en cada sesión. Las grandes instituciones comparan sus niveles con este. Precio por encima de un VWAP en aumento = compradores en control; un rechazo claro en VWAP durante una tendencia bajista es un estudio breve. En las criptomonedas 24 horas al día, 7 días a la semana, se reinicia de manera diferente que en FX: trátelo como una guía, no como una ley."},{"h":"Cómo los utiliza el motor","t":"Cada nuevo indicador añade una pequeña confirmación al puntaje en el mismo lado al que apunta (Stochastic, Ichimoku, VWAP, ADX cuando concuerda con la dirección y Elliott). Son confirmaciones, no desencadenantes: si no están de acuerdo con BB/RSI/la vela, el puntaje simplemente se vuelve más mixto y obtienes más MANTENER."},{"h":"Por qué la PRECAUCIÓN se volvió más estricta","t":"Debido a que ahora hay más controles en el grupo, la barra de PRECAUCIÓN se hizo más estricta: necesita una puntuación ≥ 4 Y al menos 3 controles que estén de acuerdo. Eso evita que la aplicación te inunde con señales más débiles sólo porque hay más herramientas activadas."},{"h":"Un orden de lectura que funciona","t":"① Dirección TF superior (nube Ichimoku + ADX). ② Donde el precio es (BB / Fib / VWAP). ③ Momento (RSI + Estocástico). ④ Confirmación de velas. ⑤ % de riesgo y niveles escritos → Papel primero."},{"h":"Errores a evitar","t":"Encendiendo todos los indicadores y mirando un arcoíris; usando ADX como dirección (es solo fuerza); ponerse en corto sólo porque el estocástico es >80 dentro de una corrida alcista; ignorando que VWAP significa cosas diferentes en criptografía y FX."},{"h":"Lista de verificación de práctica","t":"① Sesgo de la nube + ADX ② Ubicación de BB / Fib / VWAP ③ Impulso de RSI + Stoch ④ Confirmación de vela ⑤ SL / TP escrito ⑥ Papel, luego diario."}]},{"id":"elliott","title":"16 · Onda de Elliott (recuento de luces)","summary":"CPE incluye un contador Elliott Wave liviano. Marque \"Elliott\" en la barra indicadora de Chart Lab y etiquetará el último impulso 0-1-2-3-4-5 en las velas y proyecta un objetivo de Fibonacci de onda 5. Es una herramienta de estudio, no una bola de cristal.","lessons":[{"h":"La idea en una línea.","t":"Los mercados se mueven en ondas: impulsos (5 tramos en la dirección de la tendencia) y correcciones (3 tramos en contra). El CPE cuenta sólo el impulso, que es la parte que lleva la tendencia."},{"h":"Cómo lo cuenta CPE","t":"Encuentra los últimos pivotes del swing (fractales de 3 barras), alterna alto/bajo y prueba los últimos 5 a 6 swings según las reglas de Elliott. Si la forma encaja, dibuja las etiquetas 0→5 (la onda que aún está en marcha en amarillo) y una línea objetivo W5 construida a partir de la longitud de la onda 1 × 1,618 medida en la onda 4."},{"h":"Las reglas que verifica","t":"La onda 2 no pasa el inicio de la onda 1; la onda 4 no se superpone al territorio de la onda 1; La onda 3 no es la más corta de 1/3/5. Cuando una regla falla, no muestra nada, no hay conteo forzado."},{"h":"Alcista vs bajista","t":"Un 0-1-2-3-4-5 ascendente es un impulso alcista; la imagen especular en el camino hacia abajo es bajista. El motor añade una pequeña confirmación a la puntuación del lado de la ola."},{"h":"En vivo versus completo","t":"Una onda VIVA 5 (aún en ejecución) se lee como una continuación de la tendencia. Un impulso COMPLETO (0-5 finalizado) advierte que la tendencia puede estar cansando; a menudo sigue una corrección."},{"h":"La línea objetivo W5","t":"Una extensión de Fibonacci de la onda 1 desde el mínimo/alto de la onda 4. Es una idea objetivo, no un imán: el precio puede no alcanzarla o sobrepasarla."},{"h":"como usarlo","t":"Trate el conteo como una confluencia: en una zona clara de BB/Fib con una vela y RSI, un conteo impulsivo agrega convicción. Por sí solo es sólo un boceto."},{"h":"Errores a evitar","t":"Volver a contar las ondas hasta que se ajusten a tu posición (el clásico pecado de Elliott); contando pequeños movimientos; ignorar el recuento de plazos más altos; olvidar que el recuento cambia cada vez que se imprime una nueva barra."},{"h":"Lista de verificación de práctica","t":"① Cambios claros elegidos ② Las reglas pasan ③ El zig-zag está de acuerdo con BB / Fib ④ Confirmación de vela ⑤ SL más allá del punto de invalidación de la onda 4."}]},{"id":"forecast","title":"17 · Pronóstico de 3 meses (el tick de Pronóstico 3M)","summary":"El proyector de horizonte largo: cómo es probable que se forme este gráfico durante los próximos 3 meses, elaborado a partir de la propia tendencia, objetivos y volatilidad de la señal. Actívelo o desactívelo con la marca \"Forecast 3M\" en Chart Lab.","lessons":[{"h":"lo que dibuja","t":"Una trayectoria central discontinua que va desde la entrada analizada hacia el mejor objetivo que el motor ya conoce (objetivo Elliott → tp2 → tp1), envuelto en un “cono” cada vez más amplio que muestra la dispersión de precios plausibles. Los marcadores de mes M+1 / M+2 / M+3 dividen el horizonte."},{"h":"¿Por qué un cono y no una línea?","t":"Nadie puede saber un precio futuro exacto. El cono se ensancha con la raíz cuadrada del tiempo y la propia volatilidad del par, por lo que un par de divisas tranquilo obtiene un cono estrecho y una altcoin salvaje uno muy ancho. Esa amplitud ES el mensaje: cuanto más lejos se mira, menos seguro es el precio."},{"h":"De dónde vienen los números","t":"La deriva proviene del objetivo de la señal actual; la volatilidad diaria proviene del% ATR de la señal escalado a un día, por lo que el cono significa lo mismo en un gráfico de 5 mo un gráfico de 1 día; La volatilidad EXTREMA / ALTA lo amplía aún más."},{"h":"como leerlo","t":"Mira la PENDIENTE (en qué dirección se inclina el camino) y el ANCHO (cuánta duda). Una trayectoria ascendente con un cono estrecho = una idea de tendencia más estable; un camino plano con un cono enorme = “aquí no hay borde, espere ruido”."},{"h":"Encenderlo y apagarlo","t":"El botón \"Previsión 3M\" se encuentra junto a \"Espacio futuro\". Necesita espacio futuro activado (el área en blanco a la derecha donde se dibuja la proyección). Si la señal es MANTENER no hay dirección, por lo que no se dibuja nada."},{"h":"Es la tendencia, no el comercio.","t":"El pronóstico es un mapa de gran tamaño. Los niveles comerciales reales (entrada, TP1/TP2, SL y la proyección a corto plazo) siguen siendo lo que usted negocia."},{"h":"Límites honestos","t":"Las noticias, las cotizaciones, las eliminaciones de las listas y los cambios macroeconómicos no están en el modelo; el camino es una deriva suave, por lo que los precios reales se moverán mucho más; un cono de 3 meses es una ayuda para el estudio, nunca una promesa."},{"h":"Vuelva a analizar con frecuencia","t":"A medida que se imprimen nuevas velas, el objetivo, la volatilidad y, por lo tanto, todo el cono se actualizan. Un pronóstico es una instantánea, no un contrato."},{"h":"Lista de verificación de práctica","t":"① Lea la dirección de la ruta ② Verifique el ancho del cono ③ Compare con una estructura TF superior ④ Dimensione la posición desde el SL real, nunca desde el cono."}]}],"platforms":{"BINANCE":{"title":"Comercio de Binance A → Z","steps":["Crear cuenta → habilitar 2FA.","Gestión de API → Crear clave → Comercio al contado y/o de futuros activado, retiros desactivados.","Pegue Clave + Secreto en CPE → Claves API → Binance → Guardar → Cuenta de prueba.","Utilice el escaneo Spot Desk / Futures Desk (los gráficos públicos funcionan incluso antes que las claves).","Práctica: Comercio manual → Iniciar comercio en papel (sin dinero real).","En vivo: configure TP1/TP2/SL + Trailing → Iniciar Live Trade (necesita API).","Gestionar en Posiciones: editar niveles, cierre parcial, cancelar auto.","Licencia: Prueba 7d → 3 meses o de por vida (precios de propietario en la aplicación)."]},"BYBIT":{"title":"Comercio Bybit A → Z","steps":["Cuenta + 2FA.","Gestión de API → solo comercio, retiros desactivados.","CPE → Claves API → Bybit → Guardar.","Futures Desk para la mentalidad de los delincuentes; Chart Lab para estudiar velas.","Comercio de papel primero; Vive después de que las llaves funcionen.","Ruta TP+SL: COMPRAR ↑ / VENDER ↓."]},"OKX":{"title":"Operaciones con OKX A → Z","steps":["Se requiere clave API + secreto + frase de contraseña.","Retiros APAGADOS siempre.","Guarde los tres campos en Claves CPE.","Práctica en papel → tamaño pequeño en vivo.","Los errores tipográficos en las frases de contraseña son el error número uno: copie con cuidado."]},"KUCOIN":{"title":"Comercio de KuCoin A → Z","steps":["Clave + Secreto + Frase de contraseña.","Sólo permiso comercial.","Papel en CPE → luego vive en pequeño.","Utilice escritorios Spot/Futures para señales."]},"BITGET":{"title":"Bitget Trading A → Z","steps":["API solo con comercio.","El papel entonces vive.","Futuros: elija Cruzado o Aislado en Comercio manual.","Trail TP+SL para bloquear ganancias."]},"GATE":{"title":"Operaciones con Gate.io A → Z","steps":["Crear claves API v4 (comercio).","Retiros APAGADOS.","Guardar en CPE → papel de práctica.","Scan + Chart Lab para entradas antes del directo."]},"MEXC":{"title":"Comercio MEXC A → Z","steps":["Inicie la mentalidad puntual.","Claves en claves API de CPE.","Papel → vivir.","Utilice el rastro para bloquear ganancias abiertas."]},"KRAKEN":{"title":"Operaciones con Kraken A → Z","steps":["Genere clave solo con permiso comercial.","Sin derechos de retiro/fondos.","Práctica en papel en CPE.","Verifique también todos los pedidos en vivo en Kraken."]},"COINBASE":{"title":"Coinbase Avanzado A → Z","steps":["Claves de API de comercio avanzado.","Escritorio puntual en CPE.","El papel entonces vive.","Mantenga los retiros desactivados."]},"FOREX_OANDA":{"title":"Forex (OANDA) A → Z","steps":["Abrir demostración de OANDA → riesgo ~1%.","Token de acceso personal + ID de cuenta en claves CPE.","Escaneo de Forex Desk + Laboratorio de gráficos (EURUSD…).","Comercio manual → Papel con plataforma Forex.","Viva solo después de demostrar confianza."]},"FOREX_FXCM":{"title":"FXCM Forex A → Z","steps":["Credenciales API del corredor.","Papel en CPE primero.","Vea las sesiones de Londres y Nueva York y los picos de noticias.","El diario en vivo después de la práctica se ve limpio."]},"FOREX_MT5":{"title":"MetaTrader 5 A → Z","steps":["Inicio de sesión + servidor + contraseña en claves CPE.","Prefiera la contraseña de inversor (lectura) siempre que sea posible.","Practica lotes 0.01.","Papel en CPE; vivir a través de corredor cuando esté listo."]},"FOREX_DEMO":{"title":"Tasas de demostración de Forex A → Z","steps":["No se requiere clave API.","Forex Desk + Chart Lab para gráficos gratuitos.","Sólo operaciones en papel (práctica).","Cuando esté listo para un corredor real, agregue claves OANDA / FXCM / MT5 para vivir."]}},"forexAz":{"title":"Comercio de Forex A → Z (clase completa)","lessons":[{"h":"A - Cuenta y riesgo","t":"Demostración primero. Riesgo ~0,5–1% por idea. Nunca comerciar con venganza."},{"h":"B - Parejas","t":"Principales (EURUSD, GBPUSD, USDJPY) antes que exóticos."},{"h":"C - Velas","t":"Aprenda Doji, Hammer y Engulfing en Chart Lab Forex."},{"h":"D - Sesgo diario","t":"Verifique el plazo más alto antes de las inscripciones de 15/30 m."},{"h":"E - Entradas","t":"BB rebote inferior + confirmación de vela es una configuración de práctica común."},{"h":"F - Fibrilación auricular","t":"Los retrocesos del 50%/61,8% se utilizan a menudo como zonas de práctica."},{"h":"G - Goles (TP)","t":"Escalado TP1, corredor TP2, sendero SL."},{"h":"H - Horas","t":"Superposición entre Londres y Nueva York = más movimiento."},{"h":"I — Indicadores","t":"RSI + MACD + BB juntos; Evite la sobrecarga del indicador."},{"h":"J-Diario","t":"Registre cada operación impresa/en vivo en CPE Journal."},{"h":"K - Claves","t":"El corredor de divisas en vivo necesita API/token; Las tarifas de demostración no necesitan ninguna."},{"h":"L-muchos","t":"Comience 0,01 lotes en la mentalidad de práctica."},{"h":"M - Mentalidad","t":"Proceso sobre predicción. Salta los días malos."},{"h":"N — Noticias","t":"Consulte Noticias y trucos antes de grandes eventos."},{"h":"O - Órdenes","t":"Configure siempre SL. El seguimiento protege las ganancias abiertas."},{"h":"P - Práctica","t":"Botón Paper Trade = practicar sin API en vivo."},{"h":"P - Calidad","t":"Menos configuraciones de alta calidad superan al exceso de operaciones."},{"h":"R - Riesgo:recompensa","t":"Apunte a configuraciones donde la recompensa sea ≥ riesgo cuando sea posible."},{"h":"S - Sesiones","t":"Asia más tranquila; Londres/NY más activo."},{"h":"T - Tendencias","t":"Opere con una tendencia de TF más alta cuando esté aprendiendo."},{"h":"U — Actualizaciones","t":"Vea el banner de actualización de CPE + ayuda en vivo."},{"h":"V - Volatilidad","t":"Amplíe la paciencia cuando el ATR aumente."},{"h":"W - Retirar API","t":"Nunca habilite el retiro en ninguna clave API."},{"h":"X - salidas","t":"El rastro parcial de TP + supera la esperanza."},{"h":"Y-tu plan","t":"Escribir reglas; Síguelos en Manual/Auto."},{"h":"Z - Cero prisa","t":"Sin fomo. Practica → luego vive la API."}]}};

window.CPE_LEARN.pt = {"intro":"Pratique primeiro com Paper / DEMO. Estude velas, gráficos, BB/RSI/Fib, dinheiro, psicologia - depois sinais (o que significa COMPRAR/VENDER/HOLD + o que fazer) e sinais de Forex. Live precisa da chave API da plataforma correta (Retiradas OFF).","candles":[{"shape":"doji","name":"Doji","color":"#94a3b8","bias":"Neutro/espera","tip":"Abrir ≈ fechar — corpo cruzado ou fino. Indecisão do mercado após uma mudança.","also":"Também ensina: não faça FOMO. Espere a próxima vela. Perto do extremo BB + Doji = compressão de opiniões; verifique a inclinação do RSI antes de adivinhar a direção."},{"shape":"hammer","name":"Martelo","color":"#22c55e","bias":"COMPRAR preconceito","tip":"Corpo pequeno na parte superior, pavio inferior longo (≈2× corpo) após uma queda – os compradores rejeitaram preços mais baixos.","also":"Além disso: coloque o SL de prática sob o pavio baixo. Melhor com BB + RSI mais baixo subindo de sobrevenda. Psicologia: paciência para o pavio acabar — não compre no meio do pavio."},{"shape":"invhammer","name":"Martelo Invertido","color":"#22c55e","bias":"COMPRAR (fraco)","tip":"Longo pavio superior na parte inferior. Os compradores sondaram alta, mas fecharam perto da abertura – precisam da próxima confirmação verde.","also":"Além disso: mais fraco que o Hammer sozinho. Use como alerta, não como entrada. Fib 61.8 bounce + Martelo Invertido = zona de estudo apenas até confirmar a vela."},{"shape":"shooting","name":"Estrela cadente","color":"#ef4444","bias":"Viés de VENDA","tip":"Parte inferior do corpo pequena, pavio superior longo após uma alta – os vendedores rejeitaram as altas.","also":"Além disso: SL acima do pavio alto. Mais forte perto da parte superior do BB / extensão Fib / RSI sobrecomprado. Ensina: as velas lunares podem falhar – não persiga o último verde."},{"shape":"hanging","name":"Homem Enforcado","color":"#f59e0b","bias":"VENDA cuidado","tip":"Parece Hammer, mas aparece após uma subida – possível exaustão máxima.","also":"Além disso: o contexto é tudo (mesma forma ≠ mesma negociação). Localização do diário: superior versus inferior. Psicologia: não reverta apenas porque a forma corresponde – confirme com a próxima vela + RSI."},{"shape":"engulf_bull","name":"Engolfo de alta","color":"#22c55e","bias":"COMPRAR","tip":"O corpo verde cobre totalmente o corpo vermelho anterior – os compradores assumiram o controle em uma barra.","also":"Além disso: mais forte no suporte/menor BB/Fib 50–61,8. Tamanho de engolfamento baixo como SL. Dica de dinheiro: corpo amplo e envolvente → SL mais largo → tamanho menor."},{"shape":"engulf_bear","name":"Engolfo de baixa","color":"#ef4444","bias":"VENDER","tip":"O corpo vermelho cobre totalmente o verde anterior – os vendedores dominados.","also":"Além disso: cuidado com posições compradas em aberto. BB próximo ao superior + RSI>70 = alta qualidade de estudo. Ensina risco: se já for longo, TP/trilha parcial em vez de esperança."},{"shape":"morning","name":"Estrela da Manhã","color":"#22c55e","bias":"COMPRAR","tip":"3 velas: vermelha grande → estrela pequena → verde grande. História de reversão inferior.","also":"Além disso: paciência com várias velas. Entrar após o 3º fechamento; SL sob estrela baixa. Combina bem com a divergência inferior do BB + RSI de alta."},{"shape":"evening","name":"Estrela Vespertina","color":"#ef4444","bias":"VENDER","tip":"3 velas: verde grande → estrela pequena → vermelha grande. História de reversão principal.","also":"Além disso: não encurte apenas a estrela do meio. Aguarde o terceiro fechamento. Confluência de extensão BB/Fib superior. Psicologia: ignore o FOMO da primeira corrida verde."},{"shape":"maru_bull","name":"Touro Marubozu","color":"#22c55e","bias":"Forte pressão de COMPRA","tip":"Corpo longo e verde, quase sem mechas - os compradores controlam a abertura → fechamento.","also":"Além disso: pista de continuação da tendência, nem sempre uma compra inferior. Walk-the-band é possível. Risco: perseguir Marubozu tardio sem retrocesso para BB mid/Fib."},{"shape":"maru_bear","name":"Urso Marubozu","color":"#ef4444","bias":"Forte pressão de VENDA","tip":"Corpo longo e vermelho, quase sem mechas – vendedores no controle.","also":"Além disso: não pegue facas que caem. Espere o salto BB/Fib + Hammer mais tarde. Ensina: pressão forte = tamanho menor ou ficar de lado."},{"shape":"spin","name":"Pião","color":"#94a3b8","bias":"Indecisão","tip":"Corpo pequeno, mechas superiores + inferiores – ambos os lados lutaram, ninguém venceu claramente.","also":"Além disso: dentro do BB aperte com frequência. Pausar negociação; espere pausa + vela de direção. Lição de psicologia: o mercado não pode “fazer nada” – flat é uma escolha válida."},{"shape":"pierce","name":"Linha Piercing","color":"#22c55e","bias":"COMPRAR","tip":"Vermelho e depois verde que abre mais baixo, mas fecha acima do ponto médio do vermelho anterior.","also":"Além disso: mais suave que Engulfing. Confirme com RSI turn. Boa broca de papel para leitura de resistência parcial – nem todos os verdes são iguais."},{"shape":"darkcloud","name":"Cobertura de nuvens escuras","color":"#ef4444","bias":"VENDER","tip":"Verde e depois vermelho que abre mais alto, mas fecha abaixo do ponto médio do verde anterior.","also":"Além disso: aviso prévio antes do Bear Engulfing completo. Trilha longa/pega TP1. Ensina o dimensionamento antes de uma impressão de reversão completa."},{"shape":"soldiers","name":"Três soldados brancos","color":"#22c55e","bias":"Tendência de COMPRA","tip":"Três verdes em alta com fechamentos mais altos – compra constante.","also":"Além disso: forte sugestão de tendência de alta; retrocessos para Fib 38-50 ou BB mid são acréscimos práticos. Risco de excesso de confiança após 3 greens — mantenha a % de risco fixa."},{"shape":"crows","name":"Três Corvos Negros","color":"#ef4444","bias":"Tendência de VENDA","tip":"Três tintos em queda com fechamentos mais baixos – vendas constantes.","also":"Além disso: não faça médias baixas. Estrutura de espera. O RSI sobrevendido pode permanecer sobrevendido – regra monetária: limite de perda> esperança."},{"shape":"harami_bull","name":"Harami otimista","color":"#22c55e","bias":"COMPRAR (suave)","tip":"Vermelho grande, depois verde pequeno dentro do corpo anterior – pressão de venda diminuindo.","also":"Além disso: sinal de pausa antecipada. Precisa confirmar. Pares com estudo de divergência de alta do RSI. Ensina a leitura “desvanecimento da força” e não apenas reversões."},{"shape":"harami_bear","name":"Harami baixista","color":"#ef4444","bias":"VENDER (suave)","tip":"Verde grande, depois vermelho pequeno por dentro – a pressão de compra está diminuindo.","also":"Além disso: faça parciais em posições compradas. Não é curto automático. Psicologia: a ganância pelo grande verde muitas vezes ignora o aviso de Harami."},{"shape":"tweezer_bot","name":"Parte inferior da pinça","color":"#22c55e","bias":"COMPRAR","tip":"Duas velas com mínimos correspondentes – teste duplo de suporte.","also":"Além disso: marque esse ponto baixo como estrutura. SL logo abaixo. O alinhamento Fib/BB ajuda. Primo do padrão gráfico do Double Bottom - mesma lição de suporte."},{"shape":"tweezer_top","name":"Pinça Superior","color":"#ef4444","bias":"VENDER","tip":"Duas velas com máximos correspondentes – teste duplo de resistência.","also":"Além disso: marque a resistência. Primo de Double Top. Falha do RSI em máximos = confluência. Ensina: mesmo preço rejeitado duas vezes = respeite o nível."},{"shape":"longlegged","name":"Doji de pernas compridas","color":"#94a3b8","bias":"Indecisão","tip":"Mechas superiores e inferiores muito longas com um corpo minúsculo - uma luta violenta de mão dupla que terminou onde começou.","also":"Além disso: muitas vezes ocorre um grande movimento, mas a direção é desconhecida – espere pela quebra da vela. Ensina: alta volatilidade não significa alta certeza."},{"shape":"dragonfly","name":"Libélula Doji","color":"#22c55e","bias":"COMPRAR preconceito","tip":"Aberto = fechamento = alto, com um pavio longo e inferior – os vendedores empurraram para baixo e os compradores bateram de volta para cima.","also":"Além disso: mais forte no suporte/BB mais baixo após uma queda. SL sob a cauda do pavio. Ensina: a rejeição é uma história, não uma garantia — confirme a próxima vela."},{"shape":"gravestone","name":"Lápide Doji","color":"#ef4444","bias":"Viés de VENDA","tip":"Aberto = fechamento = mínimo, com um longo pavio superior – os compradores empurraram para cima e os vendedores arrastaram-no de volta para o mínimo.","also":"Além disso: mais forte na resistência / BB superior / RSI sobrecomprado. Espelho da Libélula. Ensina: um pico de alta que fecha na mínima é um rompimento fracassado."},{"shape":"inside_bar","name":"Barra interna","color":"#94a3b8","bias":"Enrolando / espere","tip":"A segunda vela fica completamente dentro da primeira – o intervalo se comprime e o mercado prende a respiração.","also":"Além disso: a quebra da barra mãe é o gatilho – negocie na direção da quebra. Combina com um BB squeeze. Ensina: a contração vem antes da expansão."},{"shape":"outside_bar","name":"Bar Externo","color":"#22c55e","bias":"Rompimento/reversão","tip":"A segunda vela engole a primeira de cima para baixo – uma tomada violenta dentro de uma barra.","also":"Além disso: direção = onde a barra externa fecha. Uma barra grande significa um SL grande, portanto, um tamanho menor. Ensina: uma barra pode apagar as três últimas."},{"shape":"belt_bull","name":"Cinto de alta","color":"#22c55e","bias":"COMPRAR","tip":"Abre na baixa sem pavio inferior e fica verde – os compradores assumiram o controle desde o primeiro tick.","also":"Além disso: mais forte após um intervalo para baixo ou direto para o suporte. SL sob o aberto. Ensina: um impulso de abertura mostra a real intenção."},{"shape":"belt_bear","name":"Cinto de baixa","color":"#ef4444","bias":"VENDER","tip":"Abre na máxima sem pavio superior e fica vermelho – os vendedores controlavam desde o aberto.","also":"Além disso: mais forte após um intervalo ou na resistência. A trilha é longa. Ensina: o primeiro movimento pode definir o dia inteiro."},{"shape":"kick_bull","name":"Kicker de alta","color":"#22c55e","bias":"COMPRA Forte","tip":"Uma vela vermelha, depois uma lacuna em uma vela verde - o clima mudou entre os fechamentos sem sobreposição.","also":"Além disso: raro e poderoso; a lacuna é necessária, nenhuma sobreposição é permitida. Ensina: o sentimento pode mudar enquanto o mercado dorme."},{"shape":"kick_bear","name":"Kicker de baixa","color":"#ef4444","bias":"VENDA Forte","tip":"Uma vela verde, depois uma lacuna em uma vela vermelha – os compradores desapareceram entre os fechamentos.","also":"Além disso: saia do long rapidamente – os kickers não esperam por você. Ensina: gap é a reprecificação do mercado quando você está ausente."},{"shape":"abandoned","name":"Bebê abandonado otimista","color":"#22c55e","bias":"COMPRA Forte","tip":"Uma vela vermelha, um doji aberto e depois uma vela verde aberta – uma ilha solitária de indecisão.","also":"Além disso: o doji deve se distanciar de AMBOS os lados. Raro, mas de alta qualidade na parte inferior. Ensina: as reversões começam onde todos desistem."},{"shape":"three_inside_up","name":"Três de dentro para cima","color":"#22c55e","bias":"COMPRAR","tip":"Harami altista mais uma terceira vela verde que fecha acima da primeira – a barra interna finalmente quebrou.","also":"Além disso: um Harami confirmado é muito mais forte do que um nu. SL sob o harami baixo. Ensina: a confirmação vence a previsão."},{"shape":"three_inside_down","name":"Três de dentro para baixo","color":"#ef4444","bias":"VENDER","tip":"Harami baixista mais uma terceira vela vermelha fechando abaixo da primeira – a barra interna quebrou.","also":"Além disso: corte os longos assim que o terceiro fechar. Ensina: uma pausa fracassada pode simplesmente retomar a velha tendência."},{"shape":"three_methods_bull","name":"Subindo Três Métodos","color":"#22c55e","bias":"Tendência de COMPRA","tip":"Uma longa vela verde, três pequenas vermelhas dentro dela, depois outra longa verde – um descanso dentro de uma elevação.","also":"Além disso: a pausa nunca sai do intervalo da primeira vela, então a tendência é calma. Negocie o rompimento da última vela. Ensina: as tendências descansam sem quebrar."},{"shape":"three_methods_bear","name":"Caindo em três métodos","color":"#ef4444","bias":"Tendência de VENDA","tip":"Uma longa vela vermelha, três pequenas verdes dentro dela, depois outra longa vermelha – um descanso dentro de uma queda.","also":"Também: espelho de Rising Three Methods. Não compre verduras pequenas - elas fazem barulho. Ensina: retrocessos dentro de um intervalo não são reversões."},{"shape":"tower_bot","name":"Parte inferior da torre","color":"#22c55e","bias":"COMPRA reversão","tip":"Uma longa vela vermelha, um conjunto de pequenas velas, depois uma longa vela verde – o clima muda em uma base plana.","also":"Além disso: o meio plano é a batalha e a última vela declara o vencedor. Ensina: bases levam tempo."},{"shape":"tower_top","name":"Topo da Torre","color":"#ef4444","bias":"VENDA reversão","tip":"Uma longa vela verde, um conjunto de pequenas velas e, em seguida, uma longa vela vermelha – os compradores se esgotam e os vendedores assumem o controle.","also":"Também: espelho do fundo da torre. Faça parciais enquanto a base se forma. Ensina: os tops são um processo, não um momento."}],"chartPatterns":[{"shape":"double_bot","name":"Fundo Duplo (W)","color":"#22c55e","bias":"COMPRAR preconceito","tip":"Duas mínimas próximas do mesmo preço e, em seguida, quebra do pico intermediário - formato W.","also":"Além disso: quebra de decote = gatilho de treino. Meça a altura para a ideia TP. Links para Tweezer Bottom + Fib de pico → baixo. Risco: falsa ruptura – espere logo além do decote."},{"shape":"double_top","name":"Top Duplo (M)","color":"#ef4444","bias":"Viés de VENDA","tip":"Duas máximas próximas do mesmo preço e, em seguida, quebra da mínima intermediária - formato M.","also":"Além disso: igual ao Tweezer Top em escala maior. A trilha anseia pela ruptura do decote. Psicologia: o segundo FOMO principal é caro – o plano já existia."},{"shape":"hs_top","name":"Cabeça e Ombros","color":"#ef4444","bias":"Viés de VENDA","tip":"Ombro esquerdo, cabeça mais alta, ombro direito; quebrar o decote para baixo.","also":"Além disso: distribuição clássica. Alvo ≈ altura da cabeça abaixo do decote. O RSI frequentemente diverge na cabeça. Ensina paciência em múltiplas oscilações – não na negociação de uma vela."},{"shape":"ihs","name":"H&S inverso","color":"#22c55e","bias":"COMPRAR preconceito","tip":"H&S de cabeça para baixo na parte inferior – decote dividido.","also":"Também: história de acumulação. Confirme com volume/momento, se disponível. Combine com Morning Star na zona do ombro direito para estudo de confluência."},{"shape":"triangle","name":"Triângulo (apertar)","color":"#f0b429","bias":"Espera de intervalo","tip":"Compressão de agudos mais baixos + graves mais altos – aumento de energia.","also":"Além disso: a mesma lição do BB squeeze. Não adivinhe a direção interna. Intervalo comercial + fechamento da vela. Dinheiro: tamanho após direção conhecida."},{"shape":"flag","name":"Bandeira de Touro","color":"#22c55e","bias":"COMPRAR cont.","tip":"Aumento acentuado (pólo) e depois pequeno canal descendente/lateral - depois continuação.","also":"Além disso: a profundidade da bandeira Fib é frequentemente rasa (38%). Poste Marubozu + bandeira = prática de tendência. Não compre tarde após a extensão total sem retrocesso."},{"shape":"channel","name":"Canal de tendências","color":"#38bdf8","bias":"Com tendência","tip":"Preço entre linhas paralelas crescentes (ou decrescentes) — ferramentas de swing trade.","also":"Além disso: compre canal inferior + Hammer em tendência de alta; vender superior + Shooting Star. BB mid geralmente rastreia o canal. Ensina “onde” e não apenas “que vela”."},{"shape":"support_res","name":"Suporte e Resistência","color":"#a78bfa","bias":"Contexto primeiro","tip":"Zonas horizontais onde o preço reage repetidamente – o mapa sob cada vela.","also":"Além disso: todo padrão é mais forte em S/R. Desenhe zonas no Chart Lab antes de BB/RSI. Psicologia: níveis > dicas; escreva-os antes da entrada."},{"shape":"triple_top","name":"Topo Triplo","color":"#ef4444","bias":"Viés de VENDA","tip":"Três máximas quase ao mesmo preço – os compradores falham três vezes em uma parede.","also":"Além disso: mais forte que um Double Top (três rejeições = oferta teimosa). A quebra do decote é o gatilho; alvo ≈ altura do padrão. Ensina: quem manda é o nível, e não a vela."},{"shape":"triple_bot","name":"Fundo Triplo","color":"#22c55e","bias":"COMPRAR preconceito","tip":"Três mínimos quase ao mesmo preço – os vendedores falham três vezes em um andar.","also":"Além disso: espelho do Triple Top. Cada toque pode ser um estudo de Martelo/Pinça. Aguarde a quebra do decote + fechamento. Ensina paciência em muitas oscilações."},{"shape":"cup_handle","name":"Copo e Alça","color":"#22c55e","bias":"COMPRAR cont.","tip":"Um “U” arredondado (xícara) e depois um pequeno recuo (alça) – continuação após um descanso.","also":"Além disso: popular entre os traders iniciantes. O cabo deve ser raso e curto – um cabo profundo significa mãos fracas. Entre na quebra do punho com confirmação da vela."},{"shape":"rounding_bot","name":"Arredondamento inferior","color":"#22c55e","bias":"COMPRA reversão","tip":"Uma baixa lenta e suave em “pires” – as vendas desaparecem gradualmente e então os compradores assumem o controle.","also":"Além disso: um fundo duplo em câmera lenta. A mensagem é que os vendedores ficaram sem energia, e nem um único pico – é necessária muita paciência."},{"shape":"rounding_top","name":"Topo Arredondado","color":"#ef4444","bias":"VENDA reversão","tip":"Uma alta “cúpula” suave – a compra desaparece gradualmente antes que o preço suba.","also":"Também: espelho de Rounding Bottom. Faça parciais mais cedo, enquanto o impulso morre. Ensina: os topos são um processo, não uma única vela."},{"shape":"rising_wedge","name":"Cunha Ascendente","color":"#ef4444","bias":"Viés de VENDA","tip":"Ambos os trilhos sobem, mas convergem para cima – os compradores se cansam à medida que o alcance diminui.","also":"Além disso: enganoso porque o preço ainda sobe; o estreitamento é a verdadeira pista. Freqüentemente quebra. Não persiga o último empurrão."},{"shape":"falling_wedge","name":"Cunha Caindo","color":"#22c55e","bias":"COMPRAR preconceito","tip":"Ambos os trilhos caem, mas convergem para baixo – os vendedores se cansam à medida que o alcance diminui.","also":"Também: espelho de Rising Wedge. Freqüentemente rompe. Um martelo na cauda em cunha é um estudo clássico. Aguarde o intervalo + fechamento."},{"shape":"asc_triangle","name":"Triângulo Ascendente","color":"#f0b429","bias":"COMPRAR preconceito","tip":"Um teto plano + piso ascendente – os compradores continuam avançando em uma resistência fixa.","also":"Além disso: aumenta a pressão contra um preço; o rompimento é comum. Entre perto do teto. Ensina: os compradores ficam impacientes."},{"shape":"desc_triangle","name":"Triângulo Descendente","color":"#f0b429","bias":"Viés de VENDA","tip":"Um piso plano + teto caindo – os vendedores continuam pressionando por um suporte fixo.","also":"Também: espelho do Triângulo Ascendente. O colapso é comum. Entre logo abaixo do chão. Ensina: vendedores ganhando controle."},{"shape":"pennant","name":"Flâmula","color":"#22c55e","bias":"Continuação","tip":"Um pólo pontiagudo e depois um triângulo minúsculo e estreito – um descanso muito curto antes da tendência ser retomada.","also":"Além disso: como uma bandeira, mas mais curta e triangular. Meça o mastro para obter uma ideia alvo. Nunca adivinhe dentro da pequena bobina."},{"shape":"flag_bear","name":"Bandeira do Urso","color":"#ef4444","bias":"VENDA cont.","tip":"Uma queda acentuada (pólo), depois um pequeno canal ascendente/lateral - e depois uma continuação para baixo.","also":"Também: espelho da Bandeira do Touro. O pequeno salto é uma pausa, não uma reversão. Persiga a bandeira e você comprará pelo pior preço – espere o intervalo."},{"shape":"rectangle","name":"Retângulo (intervalo)","color":"#f0b429","bias":"Comércio de gama","tip":"O preço oscila entre um teto plano e um chão – uma caixa lateral.","also":"Além disso: esmaeça as bordas por dentro, troque o intervalo por fora. O BB squeeze geralmente fica dentro de um retângulo. Ensina: disciplina nível a nível."},{"shape":"broadening","name":"Ampliando a Formação","color":"#f0b429","bias":"Cuidado","tip":"Agudos mais altos E graves mais baixos - o alcance se espalha em vez de comprimir.","also":"Além disso: um mercado caótico e emocional. As paradas são atingidas nos dois sentidos. Tamanho menor ou fique de lado; muitas vezes termina em um movimento violento de mão única."},{"shape":"diamond","name":"Diamante","color":"#f0b429","bias":"Reversão","tip":"Largo no meio, estreito em ambas as extremidades – uma formação clássica de cobertura/fundo.","also":"Além disso: um triângulo que se transforma e depois se transforma. A direção do rompimento decide. Raro e lento, então a maioria das fileiras parece barulho – seja paciente."},{"shape":"island_rev","name":"Reversão da Ilha","color":"#ef4444","bias":"Reversão","tip":"As diferenças de preços desaparecem, as negociações formam um grupo solitário e depois recuam – uma “ilha”.","also":"Além disso: precisa de lacunas reais (mais comuns em ações/FX). A ilha está presa a compradores ou vendedores. Trate as lacunas como um sinal, não como velas insulares."},{"shape":"breakaway_gap","name":"Lacuna separatista","color":"#22c55e","bias":"Início da tendência","tip":"Uma lacuna fora de um alcance ou base – o movimento começa com força, não com aperto.","also":"Além disso: ao contrário de uma lacuna de exaustão, ela aparece no início de um movimento. As lacunas geralmente atuam como suporte/resistência posteriormente. Ensina: impulso versus lacunas de valor."},{"shape":"v_reversal","name":"Reversão V","color":"#22c55e","bias":"Reversão","tip":"Uma queda livre acentuada que surge instantaneamente sem base – um “V”.","also":"Além disso: rápido e assustador; muitas vezes impulsionado por notícias. Difícil de pegar, fácil de perseguir. Espere por um pequeno pullback + vela em vez de comprar o pico."},{"shape":"harmonic","name":"Padrão Harmônico","color":"#f0b429","bias":"Zonas de reversão","tip":"Um zigue-zague medido (X-A-B-C-D) onde cada perna tem uma proporção de Fibonacci – um mapa estilo “Gartley/Bat”.","also":"Além disso: avançado. O ponto D é a zona de entrada, definida por proporções, não por sentimentos. Domine o Fib simples primeiro; este é Fib levado um nível mais profundo."}],"modules":[{"id":"bb","title":"1 · Bandas de Bollinger (BB)","summary":"Faixas de volatilidade em torno de uma média móvel. Aprenda squeeze, walk-the-band, toque inferior/superior + confirmação de vela - a configuração básica da prática de CPE.","lessons":[{"h":"O que é BB","t":"Bandas de Bollinger = SMA médio (geralmente 20) + bandas superior/inferior em N desvios padrão (geralmente 2). As bandas se alargam quando a volatilidade aumenta e se contraem quando o mercado está calmo."},{"h":"Banda intermediária","t":"A linha do meio é a média. O preço acima do meio geralmente mostra pressão de alta; abaixo mostra pressão de baixa. Use-a como uma linha de tendência dinâmica, não como uma compra/venda mágica."},{"h":"Banda inferior (prática de COMPRA)","t":"Marcar o preço na faixa inferior após uma queda pode significar “esticado”. NÃO compre cada toque. Aguarde uma vela de alta (Hammer, Engulfing) e, idealmente, o RSI subindo."},{"h":"Banda superior (VENDA / cuidado)","t":"Marcar o preço na faixa superior pode significar “esticado”. Em uma tendência de alta, o preço pode subir na banda superior (walk-the-band). Prefira ideias de VENDA apenas com vela de baixa + fraqueza de TF mais alto."},{"h":"Espremer","t":"Bandas estreitas = baixa volatilidade → geralmente ocorre um rompimento. Não adivinhe a direção dentro de um aperto forte; marque o rompimento e confirme com vela + volume, se disponível."},{"h":"Ande na banda","t":"Em uma tendência forte, o preço atinge a banda superior (ou inferior) de muitas velas. Lutar contra isso com fades de reversão à média é um erro comum para iniciantes."},{"h":"BB + Laboratório de gráficos","t":"No CPE Chart Lab/mesas, estude BB com velas no DEMO. Prática: banda inferior + Martelo → Troca de papel com SL abaixo do pavio, TP1 perto da banda média."},{"h":"Combinação BB + RSI","t":"Filtro de prática mais forte: BB inferior + RSI sobrevendido (ou subindo de sobrevendido) + vela de alta. BB superior + RSI sobrecomprado + vela de baixa para prática curta."},{"h":"Parar posicionamento","t":"Longa prática: SL sob o swing baixo / abaixo do pavio da banda inferior. Prática curta: SL acima do balanço alto. Nunca entre na negociação do BB sem um SL escrito."},{"h":"Alvos","t":"Caminho comum: TP1 na banda intermediária, TP2 em direção à banda ou trilha oposta. Expanda a escala - não precisa de toda a mudança."},{"h":"Prazos","t":"Decida o viés em TF mais alto (4H/1D). Entre em 15m/30m BB + vela. A mistura de TFs aleatórios causa sinais conflitantes."},{"h":"Erros a evitar","t":"Comprar cada toque de banda inferior em um mercado em queda; vendendo cada toque superior em uma corrida lunar; sem SL; ignorando picos de notícias que ampliam as faixas violentamente."},{"h":"Lista de verificação prática","t":"① Maior viés de TF ② BB toca ou quebra de aperto ③ Confirmação de vela ④ RSI concorda ⑤ % de risco definido ⑥ Artigo primeiro ⑦ Resultado do diário."}]},{"id":"rsi","title":"2 · RSI (Índice de Força Relativa)","summary":"Oscilador de momento 0–100. Período padrão 14. Use com BB e velas – nunca RSI sozinho como um sistema completo.","lessons":[{"h":"O que o RSI mede","t":"O RSI compara ganhos e perdas médios em N barras. RSI alto = impulso de alta recente; RSI baixo = impulso de baixa recente. Não é sempre “sobrecomprado = preciso vender”."},{"h":"Zonas clássicas","t":"Frequentemente: acima de 70 = zona de sobrecompra, abaixo de 30 = zona de sobrevenda. Em tendências fortes, o RSI pode permanecer sobrecomprado/sobrevendido por um longo tempo – isso é normal."},{"h":"Linha média 50","t":"O cruzamento do RSI acima de 50 pode apoiar a tendência de alta; abaixo de 50 viés de baixa. Muitos traders usam 50 como filtro de tendência com banda intermediária BB."},{"h":"Divergência – alta","t":"O preço desce para o mínimo, o RSI desce para o mínimo mais alto → enfraquecimento do momentum no lado negativo. Ainda espere pela quebra da vela + estrutura antes da entrada do papel."},{"h":"Divergência – baixa","t":"Preço mais alto, RSI mais baixo → dinâmica de alta desaparecendo. Confirme com Shooting Star / Engulfing perto da resistência ou BB superior."},{"h":"Balanços de falha","t":"O RSI falha em testar novamente o extremo anterior e depois volta para 50 – pista inicial de mudança de impulso. Combine com a estrutura do Chart Lab."},{"h":"RSI + BB (estilo CPE)","t":"Pratique comprado: preço próximo ao BB inferior, RSI ≤ 35 (ou subindo de ≤ 30), vela de alta. Pratique curto: BB superior, RSI ≥ 65–70, vela de baixa."},{"h":"Divergência oculta","t":"Pista de continuação da tendência (por exemplo, preço mais baixo, RSI mais baixo na tendência de alta). Avançado – domine a divergência clássica primeiro no DEMO."},{"h":"Configurações","t":"RSI(14) é o padrão comum. RSI mais curto = mais ruído. Não fique alterando as configurações para forçar um sinal."},{"h":"Sai com RSI","t":"Se você comprou sobrevendido, é razoável obter lucro parcial quando o RSI atingir a zona média/superior. Acompanhe o resto com estrutura ou meio BB."},{"h":"Notícias e RSI","t":"Grandes notícias podem aumentar o RSI instantaneamente. Prefira esperar que a primeira vela violenta termine antes de agir nos extremos do RSI."},{"h":"Erros","t":"Operar a descoberto cada RSI>70 em um mercado altista; ansiando por cada RSI<30 em uma queda de baixa; nenhuma confluência; reentrada de vingança quando o RSI “parece melhor”."},{"h":"Lista de verificação prática","t":"① Observe o valor do RSI + inclinação ② Verifique a localização do BB ③ Confirmação da vela ④ Maior TF ⑤ Papel + diário ⑥ Uma ideia de cada vez."}]},{"id":"fib","title":"3 · Fibonacci (retração e extensão)","summary":"Meça retrocessos e metas a partir de uma oscilação clara para cima → oscilação para baixa (ou reversa). Concentre-se em 38,2 · 50 · 61,8 com confluência BB/RSI.","lessons":[{"h":"Por que Fib é usado","t":"Muitos traders observam os mesmos índices, por isso a liquidez geralmente reage perto deles. Fib é um mapa de zonas possíveis – não uma garantia."},{"h":"Pontos de balanço","t":"Sempre desenhe de um balanço claro de baixo para um balanço alto (movimento para cima) ou de alto para baixo (movimento para baixo). Balanços ruins = níveis inúteis. Pratique escolher oscilações no Chart Lab DEMO."},{"h":"Retrações principais","t":"Comum: 23,6% (raso), 38,2%, 50% (não Fib puro, mas amplamente utilizado), 61,8% (dourado), 78,6% (profundo). Retrocessos profundos podem sinalizar fraqueza da tendência."},{"h":"Compras de pullback (tendência de alta)","t":"Após o impulso de alta, aguarde o retrocesso para a zona 38,2–61,8 + vela de alta + preferencialmente suporte médio/inferior BB ou RSI segurando >40–45."},{"h":"Vendas de retrocesso (tendência de baixa)","t":"Após o impulso descendente, suba para 38,2–61,8 + vela de baixa + RSI falhando abaixo de 55–60."},{"h":"Extensões/alvos","t":"Extensões comuns: 127,2%, 161,8% além da oscilação para ideias TP2. Use com trilha – não force tiques exatos."},{"h":"Confluência = poder","t":"Zonas de melhores práticas: Fib 50/61,8 + BB médio/inferior + estrutura anterior + virada do RSI. Uma linha Fib sozinha é fraca."},{"h":"Fibra + BB","t":"Se 61,8% estiver perto do BB inferior em uma tendência de alta, essa sobreposição é uma zona de estudo do Paper de alta qualidade. Entre apenas com confirmação de vela."},{"h":"Múltiplas mentiras","t":"Os iniciantes devem usar UM swing limpo. Empilhar 5 Fibs cria ruído no gráfico e entradas FOMO."},{"h":"Invalidação","t":"Se o preço fechar claramente além de 78,6% contra a sua tendência, a tese de retrocesso muitas vezes falha – saia ou fique de lado."},{"h":"Forex vs criptografia","t":"Mesmas proporções. As principais empresas de Forex geralmente respeitam os níveis de forma mais limpa em sessões líquidas; a criptografia pode passar e depois reverter - tamanho menor."},{"h":"Erros","t":"Desenhar Fib em pequenas oscilações de ruído; entrando no ar sem vela; movendo o SL ainda mais quando Fib “quase” se manteve; ignorando TF mais alto."},{"h":"Lista de verificação prática","t":"① Balanço da marca ② Nota 38.2/50/61.8 ③ Aguarde a chegada do preço ④ Vela + RSI/BB ⑤ Conjunto de risco ⑥ Papel → diário."}]},{"id":"money","title":"4 · Gestão de dinheiro","summary":"Como o método é realmente usado: arriscar uma porcentagem fixa, tamanho do stop, depositar parte do lucro e parar para o dia seguinte a um limite de perda. O CPE pode aplicar isso em negociações manuais e automáticas.","lessons":[{"h":"Objetivo da gestão do dinheiro","t":"Fique no jogo. Uma negociação ruim nunca deve apagar a conta. A consistência supera o tamanho da loteria."},{"h":"Como os traders realmente o utilizam","t":"A prática comum é o risco fracionário fixo. Você não escolhe o valor da moeda primeiro. Você escreve o stop primeiro, decide que essa ideia pode perder cerca de 1% da conta, aí o tamanho cai fora disso. Uma parada ampla obtém uma posição menor. Um stop apertado obtém uma posição maior e o risco do dólar permanece praticamente o mesmo. Este é o método que o CPE usa quando o tick de gerenciamento de dinheiro está ativado."},{"h":"Exemplo resolvido (conta prática de $ 1000)","t":"Conta $ 1000. Risco 1% = $ 10. Entrada 100, parada 98. Distância = 2%. Tamanho = 10 ÷ 0,02 = $ 500 nocionais. Se o stop for atingido, a perda será de cerca de US$ 10, e não de US$ 500. Se o preço atingir 103 (1,5 vezes o risco), o ganho será de cerca de US$ 15. A mesma ideia para cada par: os dólares em risco ficam próximos de 1%, a quantidade de moedas muda."},{"h":"O que o CPE faz com o tick","t":"Negocie agora → Automático: marque “Usar gerenciamento de dinheiro”. Salve a configuração automática. Cada nova negociação automática usa cerca de 1% de uma conta de prática de US$ 1.000 mais os resultados fechados, dimensionados a partir da entrada desse sinal e do SL. Os mínimos à vista e de futuros são respeitados: se o mínimo cambial arriscar mais de 1%, essa negociação é ignorada. Após cerca de -2% no dia do calendário, os novos automóveis param até o dia seguinte. No máximo cerca de 3% está em risco nas negociações abertas. A negociação manual tem o mesmo tick. O Histórico de Sinais ainda mostra o teste igual de US$ 10 e, abaixo dele, o tamanho do plano de 1% para uma conta de US$ 1.000, para que você possa ver ambos."},{"h":"Lucro parcial e a trilha","t":"A prática consiste em partir no primeiro alvo (geralmente cerca de metade) e deixar o resto seguir. Quando o stop sobe, o alvo também pode se mover, então o vencedor pode pagar mais do que o primeiro alvo. O risco da ideia original não aumenta. Um sinal forte não é motivo para arriscar 5%. O mesmo 1% é usado. A trilha é o que permite que um forte vencedor cresça."},{"h":"Parada diária e aquecimento aberto","t":"Uma regra usada: se o dia cair cerca de 2% da conta, pare de abrir negociações. Três ideias abertas com 1% cada equivalem a cerca de 3% de calor. Cinco moedas correlacionadas são uma aposta, não cinco. Conte-os juntos."},{"h":"O que este método recusa","t":"Martingale (dobrar após uma perda) não é usado. Mover a parada mais longe para “dar espaço” após a entrada não ser usado. All-in em um sinal “certo” não é usado. Se não houver stop válido, não há tamanho, portanto não há negociação."},{"h":"Risco por negociação","t":"Regra comum: arriscar apenas cerca de 0,5–1% do patrimônio da conta em uma única ideia. No DEMO, pratique o mesmo hábito percentual do LIVE."},{"h":"Fórmula de tamanho de posição","t":"Tamanho ≈ (Conta × Risco%) ÷ (Entrada − Distância de parada). SL mais largo → tamanho menor. Nunca escolha o tamanho primeiro e o SL depois."},{"h":"Risco: Recompensa","t":"Prefira ideias onde a recompensa potencial ≥ risco (por exemplo, 1:1,5 ou melhor) ao aprender. Aumente a escala no TP1 para que os corredores estejam “livres de risco”."},{"h":"Take-profit parcial","t":"Estilo CPE: TP1 bloqueia algum lucro, TP2/trilha para o resto. As parciais bancárias reduzem o pânico emocional."},{"h":"Trailer TP + SL","t":"COMPRAR: a trilha sobe à medida que o preço aumenta. VENDER: trilhar para baixo. Trailing locks abrem lucro sem a necessidade de uma chamada de saída perfeita."},{"h":"Limite de perda diária/semanal","t":"Regra de exemplo: parar de negociar no dia seguinte à conta de −2%. Sessões de vingança após um limite de perda são matadoras de contas."},{"h":"Dimensionamento pontual","t":"Os nocionais mínimos spot são importantes (por exemplo, minutos de câmbio). Ainda aplique% de risco: se o tamanho mínimo arriscar muito em relação ao seu SL, pule a negociação."},{"h":"Futuros / alavancagem","t":"A alavancagem multiplica lucros e perdas. Alta alavancagem + SL amplo = conta esgotada. Prefira baixa alavancagem durante o aprendizado; Isolado pode limitar a perda por posição."},{"h":"Correlação","t":"Abrindo 5 alts BTC correlacionados = uma grande aposta, não cinco. Conte o risco como um grupo."},{"h":"Taxas e derrapagem","t":"Couro cabeludo tenso fica bem no gráfico, mas as taxas comem R:R. Prefira balanços mais limpos no DEMO até saber os custos."},{"h":"DEMO → Ponte AO VIVO","t":"Prática de CPE DEMO (mentalidade de aproximadamente 3 meses): mesmas regras de diário, mesma %. Quando AO VIVO, comece com metade do tamanho DEMO nas primeiras semanas."},{"h":"Segurança monetária da API","t":"Retiradas OFF em todas as chaves. Live somente após Test Account OK na plataforma correspondente. Segredo de plataforma errado = operações falhadas ou perigosas."},{"h":"Erros","t":"Martingale (dobradinha após derrota); movendo o SL mais longe; all-in em configurações “seguras”; ignorando tamanho mínimo vs% de risco; negociação sem parada diária."},{"h":"Lista de verificação prática","t":"① % de risco escrito ② Tamanho da distância SL ③ TP1/TP2/trilha planejada ④ Perda diária máxima conhecida ⑤ Artigo primeiro ⑥ Diário PnL honestamente."}]},{"id":"psych","title":"5 · Psicologia para Negociação","summary":"A mentalidade decide se as habilidades BB/RSI/Fib sobrevivem às telas reais. FOMO, vingança, excesso de confiança, medo – treine-os em indicadores semelhantes ao DEMO.","lessons":[{"h":"Por que a psicologia é importante","t":"Um plano BB+RSI perfeito falha se você entrar cedo, pular SL ou negociar vingança. Habilidade = sistema × disciplina."},{"h":"Processo sobre previsão","t":"Você não precisa prever o futuro. Você precisa executar regras: configuração → risco → gerenciar → diário. Os resultados variam; processo é controlável."},{"h":"FOMO","t":"Medo de perder = perseguir velas verdes já longe da zona BB/Fib. Regra: se você perdeu a entrada, aguarde a próxima configuração. Chart Lab sempre tem outra vela."},{"h":"Negociação de vingança","t":"Depois de uma perda, o desejo de “reconquistar agora” destrói contas. Reaquecimento obrigatório: vá embora, registre a perda, próxima negociação somente se a lista de verificação estiver limpa."},{"h":"Excesso de confiança após vitórias","t":"3 vitórias consecutivas ≠ aumentar o tamanho 5×. Mantenha a porcentagem de risco fixa. As sequências de vitórias ocorrem quando a maioria das pessoas quebra as regras financeiras."},{"h":"Medo após perdas","t":"Ignorar todas as configurações válidas após um dia vermelho também é um viés. Confie no plano escrito; reduza o tamanho temporariamente se necessário, não abandone o processo."},{"h":"Paralisia de análise","t":"10 indicadores discordam → congelar. Atenha-se ao núcleo CPE: velas + BB + RSI (+ zona Fib). Qualidade acima da quantidade de ferramentas."},{"h":"Inclinação e notícias","t":"Grandes velas vermelhas nas notícias aumentam a adrenalina. Prefira a calma durante grandes incógnitas até reformas estruturais - o ego quer ação; o plano exige paciência."},{"h":"Diário = terapia + dados","t":"Escreva tags de emoção (FOMO, pressa, calma) no CPE Journal. Os padrões de sentimentos revelam vazamentos mais rapidamente do que apenas o PnL."},{"h":"Regras escritas","t":"Se não estiver escrito, não é regra. Exemplo: “Apenas BB+candle+RSI; risco 1%; nenhuma negociação após o dia -2%; DEMO até checklist de 20 papéis.”"},{"h":"Meio Ambiente","t":"Sono, fome e distração ao telefone mudam as decisões. Não avalie quando estiver exausto. Negociar é atlético – proteja o cérebro."},{"h":"Ruído social","t":"“Sinais” e exageros do telegrama quebram seu plano. Aula de aprendizagem CPE + seu diário> dicas aleatórias. Filtre notícias e truques como contexto, não como pedidos."},{"h":"Mudança de identidade","t":"Pense “Eu sigo minha lista de verificação” e não “Devo estar certo”. Estar errado com risco pequeno é normal; ser teimoso com grande risco é opcional."},{"h":"DEMO como academia","t":"Use DEMO/Paper para ensaiar emoções com segurança. Se você não consegue seguir as regras do DEMO, o LIVE não corrigirá a disciplina magicamente."},{"h":"Lista de verificação prática","t":"① Estou calmo? ② Lista de verificação completa? ③ % de risco inalterado? ④ Não é vingança? ⑤ Vou registrar honestamente? Se houver NÃO → nenhuma negociação."}]},{"id":"signals","title":"6 · Sinais CPE — significado e o que fazer","summary":"As mesas Spot / Futures / Forex mostram COMPRA · VENDA · HOLD + pontuação. A mesma ideia de mecanismo em todas as plataformas — mas você negocia apenas na plataforma cuja chave de API você salvou. Aqui está o que cada sinal significa e as etapas exatas após ele aparecer.","lessons":[{"h":"De onde vêm os sinais","t":"CPE pontua BB, RSI, Fibonacci, candle stick, EMA cross, SMA50, MACD e momentum. Pontuação ≥ +3 → COMPRAR. Pontuação ≤ −3 → VENDER. Entre → HOLD. Esta é uma classificação auxiliar – não uma promessa de lucro."},{"h":"Sinal de COMPRA - significado","t":"A confluência de alta está mais forte agora (exemplos: menor salto do BB, virada de sobrevenda do RSI, vela de alta, cruz dourada, suporte de Fibonacci). TP1 / TP2 / SL sugerido aparece na linha / Chart Lab / Trade Now."},{"h":"Sinal de VENDA - significado","t":"A confluência de baixa é mais forte (BB superior / RSI sobrecomprado / vela de baixa / cruz mortal / resistência Fib). No Spot, VENDER geralmente significa sair/reduzir comprado ou vendido apenas se o seu mercado permitir vendas (Futuros/Forex)."},{"h":"Sinal HOLD - significado","t":"Pontuação mista ou fraca. NÃO force uma negociação. Plano está correto. Watchlist ★ e aguarde uma COMPRA/VENDA mais clara ou um candidato BB Lower."},{"h":"Número da pontuação","t":"Maior |pontuação| = mais concordância entre ferramentas. Uma COMPRA +5 é mais forte que uma COMPRA +3 – ainda confirme nas velas do Chart Lab antes do tamanho."},{"h":"Placa inferior BB","t":"Lista separada de pares marcando a banda inferior de Bollinger – pratique candidatos longos. Ainda precisa de confirmação de vela + RSI; nem todo toque inferior é uma entrada."},{"h":"Plataforma vs sinal (importante)","t":"A matemática do sinal é a mesma ideia em Binance, Bybit, OKX, KuCoin, Bitget, Gate, MEXC, Kraken, Coinbase, OANDA, FXCM, MT5, Forex Demo. O que muda é PARA ONDE você envia o pedido: somente a plataforma selecionada em API Keys/Trade Now. Uma Binance BUY não abre no Bybit."},{"h":"Plataformas Crypto Spot","t":"Binance Spot, Coinbase, etc.: BUY = compre a moeda com cotação (por exemplo, USDT). VENDER = vender participações / obter lucro. O tamanho mínimo (por exemplo, ~$11) é importante. Sem alavancagem."},{"h":"Plataformas de futuros criptográficos","t":"Binance Futures, Bybit, OKX, Bitget…: COMPRAR = comprado; VENDER = vendido. Escolha alavancagem cruzada/isolada + com cuidado. Trilha: COMPRE trilhas TP+SL para cima; VENDER segue para baixo."},{"h":"Plataformas Forex","t":"Demonstração OANDA / FXCM / MT5 / Forex: mesmas etiquetas BUY/SELL/HOLD em pares FX (EURUSD…). COMPRAR = comprar moeda base; VENDA = base de vendas. Lotes (por exemplo, 0,01) em vez de quantidade de moedas. Sessões e notícias são mais importantes."},{"h":"Quando uma COMPRA aparecer - faça isso","t":"① Abra a linha → leia Por que / vela / RSI. ② Confirmação do laboratório gráfico (15m – 1H). ③ DEMO primeiro: Negocie agora → defina TP1/TP2/SL/trilha → Iniciar Demo/Papel. ④ Somente após API Test OK nessa plataforma → pequeno LIVE. ⑤ Resultado do diário."},{"h":"Quando uma VENDA aparecer - faça isso","t":"① Se você estiver comprado no Spot: considere TP / fechamento parcial / trilha - não ignore. ② Se Futuros/Forex e plano permitirem vendas curtas: confirme Chart Lab e depois Paper/Live short com SL. ③ Se HOLD foi melhor ontem, não vingue o tamanho do flip."},{"h":"Quando HOLD aparecer - faça isso","t":"Nenhuma nova entrada manual. Continue digitalizando. Adicione ★ lista de observação. Estude aula de aprendizagem / laboratório de gráficos. Proteja as posições abertas com trilha somente se já estiver em uma negociação."},{"h":"Negociação automática + sinal","t":"O Auto BUY pode ser aberto quando as regras de pontuação BB Lower + forte corresponderem à sua configuração automática salva. Ainda teste o DEMO Auto primeiro. LIVE Auto = risco real — Saques OFF, tamanho pequeno."},{"h":"Notificações","t":"COMPRAR Brindes de sinal seguem seu idioma. Trate-os como alertas para abrir a mesa – e não como ordens de mercado por si só."},{"h":"O que NÃO fazer","t":"Não compre todas as COMPRAS sem gráfico. Não use a chave Binance no Bybit. Não pule o SL. Não aumente o tamanho após um sinal verde. Não negocie HOLD como “quase COMPRAR”."},{"h":"Cartão de ação rápida","t":"Sinal → Chart Lab → Risco % → TP1/TP2/SL → DEMO Paper → Journal → (mais tarde) AO VIVO na chave da plataforma correspondente."}]},{"id":"forex_sig","title":"7 · Sinais Forex — significado e o que fazer","summary":"O Forex Desk usa a mesma classificação BUY/SELL/HOLD em pares FX. Aprenda como os sinais forex diferem da criptografia e as etapas exatas do sinal → Papel → corretor ao vivo.","lessons":[{"h":"Sinais de mesa Forex","t":"EURUSD, GBPUSD, USDJPY… obtenha BUY/SELL/HOLD + pontuação como criptografia. Clique em uma linha para ver gráfico, texto de psicologia e níveis sugeridos."},{"h":"COMPRAR no Forex – significado","t":"Compre a moeda base (por exemplo, COMPRAR EURUSD = comprar EUR vs USD). Espere o preço subir. Use o intervalo Chart Lab Forex que você pratica (15m/30m/1H)."},{"h":"VENDER em Forex - significado","t":"Venda a base (vendido o par). Espere o preço cair. Sempre defina o SL acima da ideia de estrutura/banda superior."},{"h":"ESPERAR no Forex","t":"Nenhuma borda clara – pule. Especialmente antes de grandes notícias (NFP, CPI, banco central) prefira HOLD/flat."},{"h":"Plataforma de taxas de demonstração Forex","t":"Nenhuma chave de API. Pratique gráficos + apenas papel. Perfeito para exercícios de aula de aprendizagem antes do OANDA/FXCM/MT5 ao vivo."},{"h":"Sinal OANDA → ação","t":"① Mesa Forex COMPRA/VENDA. ② Laboratório de gráficos confirma. ③ Chaves API → Token OANDA + ID da conta → Teste. ④ Papel DEMO em CPE primeiro. ⑤ Pequenos lotes vivos (mentalidade 0,01) com TP/SL/trilha."},{"h":"Taxa de câmbio FXCM","t":"Mesma leitura de sinal. Conecte as credenciais desse corretor em Chaves de API. O Signal não faz login automático no MT5 para você até que as chaves/ponte sejam definidas - pratique o Papel até o Teste OK."},{"h":"Sessões","t":"A sobreposição Londres-NY geralmente movimenta mais as grandes empresas. A Ásia pode estar mais tranquila – HOLD é comum e saudável."},{"h":"Divulgação e notícias","t":"Em torno das notícias, os spreads aumentam – uma boa COMPRA técnica ainda pode ser um preenchimento ruim. Verifique notícias e truques; espere a vela fechar após o pico."},{"h":"Lotes vs quantidade criptografada","t":"Tamanho Forex = lotes, não USDT nocional da mesma maneira. % de risco ainda prevalece: SL mais amplo → lotes menores."},{"h":"BB mais baixo no Forex","t":"Mesma ideia: par próximo à banda inferior + Martelo + RSI subindo = praticar estudo longo. Confirme o viés de TF mais alto (4H/Diariamente)."},{"h":"Quando Forex BUY dispara – etapas","t":"① Leia o porquê. ② Maior viés de TF, OK? ③ Marque SL além do pavio/estrutura. ④ Comércio de papel. ⑤ Se o corretor ativo estiver pronto → tamanho minúsculo + trilha. ⑥ Sessão de diário (Londres/NY) + emoção."},{"h":"Quando o Forex SELL dispara – etapas","t":"① Confirme que não há pico de notícias. ② Vela de baixa do Chart Lab. ③ Papel curto ou longo. ④ Trilha para baixo se for curta. ⑤ Não duplique o lote após errar."},{"h":"Diferença entre Forex e criptografia","t":"Criptografia 24 horas por dia, 7 dias por semana; Forex tem sessões. Criptomoeda min $ frequentemente; Lotes Forex + valor pip. Cripto muitos alts correlacionados; Limpador de Forex para aprendizagem."},{"h":"Lista de verificação prática (FX)","t":"① Par principal? ② Sessão OK? ③ Notícias claras? ④ Sinal COMPRA/VENDA não HOLD? ⑤ Gráfico confirma? ⑥ % de risco? ⑦ Papel → diário → chave do corretor ativo somente quando estiver pronto."}]},{"id":"fomo","title":"8 · FOMO e Disciplina Emocional","summary":"FOMO, vingança, ganância e medo são os verdadeiros assassinos de contas – não indicadores. Aprenda os gatilhos, os sinais corporais e as regras exatas que mantêm as negociações por impulso fora da sua conta.","lessons":[{"h":"O que o FOMO realmente é","t":"FOMO = medo de perder uma jogada que já está longe da sua zona. Faz você entrar atrasado com um preço pior e sem SL adequado. A vela que você “perdeu” é uma informação, não uma perda."},{"h":"Os três gatilhos FOMO","t":"① Uma grande vela verde ou vermelha no gráfico. ② Uma postagem de um amigo ou Telegram mostrando lucro. ③ Uma manchete de notícia. Observe o gatilho antes de perceber a entrada."},{"h":"Sinais corporais","t":"Batimento cardíaco acelerado, inclinar-se para a tela, uma vontade de clicar no mercado, comprar agora, pulando sua lista de verificação. Se você sentir isso, feche a aba e espere uma vela."},{"h":"A regra “já executado”","t":"Se o preço tiver passado mais de 1 ATR além da entrada planejada, a negociação acabou. Aguarde um retrocesso para BB mid/Fib ou pule-o. Sempre há outra configuração."},{"h":"A armadilha da vela verde","t":"Um Marubozu que você não planejou é uma perseguição, não uma entrada. As entradas tardias têm a pior recompensa: o risco porque a parada acaba longe."},{"h":"Negociação de vingança","t":"Depois de uma perda, o cérebro quer reconquistá-la agora. Regra: nenhuma nova entrada por 15 a 30 minutos após uma perda e somente se a lista de verificação estiver limpa. O mercado não lhe deve nada."},{"h":"Medo de puxar o gatilho","t":"O problema oposto: aparece uma configuração perfeita e você congela. Use um tamanho DEMO minúsculo para provar o processo e decida o seu tamanho ANTES da vela aparecer para que a decisão já esteja tomada."},{"h":"Ganância após vitórias","t":"Duas negociações verdes fazem você se sentir invencível e depois você dobra de tamanho. Mantenha a % de risco fixa para pelo menos 20 negociações; sequências de vitórias significam reversão."},{"h":"Negociação de tédio","t":"Plana é uma posição. Se não existir nenhuma configuração A+, não faça nada acontecer. As negociações de tédio são FOMO disfarçadas."},{"h":"Disciplina de tempo de tela","t":"Defina duas ou três janelas de varredura por dia em vez de ficar olhando os gráficos. Menos decisões significam menos decisões por impulso."},{"h":"Diário emocional","t":"Marque cada negociação como calma/apressada/FOMO/vingança. Após 20 negociações, o padrão de seus vazamentos torna-se óbvio."},{"h":"Ritual de redefinição","t":"Depois de uma derrota ou deslize do FOMO: levante-se, respire lentamente 10 vezes, escreva uma frase sobre o que aconteceu e depois pare por uma hora ou continue com metade do risco normal."},{"h":"Lista de verificação prática","t":"① Corpo calmo? ② O gatilho foi notado? ③ Configuração na minha zona? ④ SL escrito primeiro? ⑤ % de risco inalterado? ⑥ Não é vingança? Qualquer NÃO → nenhuma negociação."}]},{"id":"risk_deep","title":"9 · Gestão de risco e dinheiro – profundo","summary":"A matemática que mantém uma conta viva: dimensionamento fracionário fixo, múltiplos R, matemática de rebaixamento, calor de correlação e parada diária. Transforme a negociação em um negócio administrado por números.","lessons":[{"h":"Risco fracionário fixo","t":"Arrisque uma% fixa (0,5–1%) do patrimônio por ideia. O tamanho é o RESULTADO da distância de parada, nunca escolhido primeiro. SL largo → tamanho pequeno; SL apertado → tamanho maior; o risco do dólar permanece o mesmo."},{"h":"A fórmula de dimensionamento","t":"Tamanho = (Patrimônio × Risco%) ÷ |Entrada − Stop|. Exemplo: $ 1.000 × 1% = risco de $ 10. Entrada 100, parada 98 → distância 2% → tamanho 10 ÷ 0,02 = $500 nocionais."},{"h":"Pense em R-múltiplos","t":"Risco 1R por negociação. Um vencedor 2R paga por duas derrotas. Acompanhe o seu R médio em 20 negociações – essa é a sua vantagem real, não a taxa de vitória."},{"h":"Recompensa: risco","t":"Procure pelo menos 1,5R de potencial antes da entrada. Abaixo disso, ignore, a menos que sua taxa de vitórias seja muito alta."},{"h":"Matemática de rebaixamento","t":"Um rebaixamento de -50% precisa de +100% para se recuperar. Sequências de derrotas são normais: mesmo um sistema com taxa de vitórias de 60% tem sequências de mais de 5 derrotas. Um pequeno risco mantém a seqüência de sobrevivência."},{"h":"A parada diária","t":"Regra rígida: parar de abrir negociações após -2% do patrimônio líquido em um dia (ou 2–3 perdas consecutivas). Sessões de vingança após o limite são matadoras de contas."},{"h":"Limites semanais e mensais","t":"Limite também a semana (por exemplo -5%) e o mês. Quando atingido, vá para DEMO, revise o diário e dimensione novamente somente após uma execução limpa."},{"h":"Calor aberto","t":"O risco total em todas as negociações abertas deve ficar em torno de 3% ou menos. Cinco alts correlacionados são uma aposta, não cinco – conte a exposição correlacionada em conjunto."},{"h":"Dimensionamento pontual","t":"Spot tem um nocional mínimo. Se o mínimo da troca arriscar mais do que 1%, pule a negociação – nunca arredonde o risco para cima."},{"h":"Dimensionamento de futuros","t":"A alavancagem muda a margem, não o risco. O risco ainda é Entry - Stop × tamanho. Use baixa alavancagem enquanto aprende e prefira margem isolada."},{"h":"Dimensionamento de Forex","t":"Risco = lotes × valor do pip × stop-pips. Resolva muito. Guia aproximado: lote 0,01 ≈ $ 0,10 por pip; um stop de 20 pip arriscando 1% de US$ 1.000 (US$ 10) → 10 ÷ 0,10 ÷ 20 = 0,05 lotes."},{"h":"Escalando","t":"Tire cerca de 50% de desconto no TP1 para deixar o resto sem riscos e depois siga em frente. Isso transforma uma boa negociação em um corredor de baixo estresse."},{"h":"Composto vs fixo","t":"Arrisque uma% fixa do patrimônio atual (composição). Não fixe seu risco no tamanho de conta mais alto de todos os tempos."},{"h":"Taxas e slippage em R","t":"Subtraia as taxas de R. Uma taxa de 0,2% contra um couro cabeludo de 0,5% pode limpar a borda – prefira oscilações mais limpas."},{"h":"A lei “sem parada, sem comércio”","t":"Se você não consegue definir um stop lógico, você não conhece o seu risco, portanto não há tamanho, portanto não há negociação."},{"h":"Antimartingale","t":"Nunca duplique depois de uma derrota. Aumente o tamanho apenas depois de várias semanas disciplinadas e lucrativas de um processo comprovado – e mesmo assim lentamente."},{"h":"Lista de verificação prática","t":"① Patrimônio conhecido ② % de risco escrito ③ Stop definido ④ Tamanho do stop ⑤ Recompensa ≥ 1,5R ⑥ Stop diário conhecido ⑦ Calor correlacionado contado."}]},{"id":"sl_tp","title":"10 · Domínio de Stop Loss e Take Profit","summary":"Coloque o SL onde o mercado provar que você está errado, obtenha lucro em etapas e siga o stop para que um vencedor possa correr – exatamente o que o CPE faz com multi-TP e um SL trailing.","lessons":[{"h":"SL é uma decisão, não um número","t":"Coloque o stop onde a ideia é invalidada (abaixo do swing low, do pavio ou da estrutura), e não a uma distância aleatória do dólar. Você está comprando uma informação: se o preço subir aqui, meu motivo está errado."},{"h":"Paradas de estrutura","t":"Longo: SL logo abaixo do swing low ou do pavio da banda inferior. Curto: logo acima do balanço alto. Dê um pequeno buffer para propagação e ruído de pavio, cerca de 0,1–0,3%."},{"h":"A volatilidade para","t":"Mercados mais amplos precisam de paradas mais amplas. Use o ATR ou o comprimento do pavio para dimensionar o stop e, em seguida, reduza a posição para que o risco do dólar permaneça o mesmo."},{"h":"Por que um SL de dólar fixo falha","t":"Um stop de US$ 10 no BTC e um stop de US$ 10 no EURUSD são riscos completamente diferentes. A distância deve ser medida em%, não em dólares."},{"h":"Buffer anti-stop-hunt","t":"O CPE ignora um único toque no pavio: ele precisa de duas violações consecutivas mais um pequeno buffer (0,15%) antes de fechar. Isso impede que o ruído persiga sua parada."},{"h":"Obtenha lucro em etapas","t":"Nunca feche 100% com um preço. Expandir a escala: TP1 registra parte, depois TP2 / trilha percorre o resto, então uma grande mudança pode pagar por muitos perdedores."},{"h":"Níveis multi-TP","t":"O CPE permite adicionar quantos níveis de TP você precisar, cada um com sua própria porcentagem próxima. Exemplo: TP1 40%, TP2 30%, TP3 30% — ou pegue TP1 e siga o resto."},{"h":"Seguindo a parada","t":"Após TP1 mova o stop para o ponto de equilíbrio; após TP2, mova-o para TP1. Deixe o preço stop follow para que o lucro aberto seja protegido enquanto o corredor continua."},{"h":"Escolhendo a trilha %","t":"Uma trilha apertada bloqueia o lucro rapidamente, mas sai mais cedo; uma trilha larga respira, mas devolve um pouco. Comece em torno de 1–2% para criptografia e ajuste-o no modal de edição de posições."},{"h":"Corredores","t":"Quando o preço caminha na banda em uma tendência forte, amplie o alvo e a trilha em vez de levar tudo em TP2. É assim que uma negociação paga por uma semana inteira."},{"h":"Botões de fechamento parcial","t":"Use os botões de fechamento 50%/100% em Posições para controle manual, ou deixe o Auto Close gerenciar TP/SL pelo plano."},{"h":"A armadilha do ponto de equilíbrio","t":"Não mova o SL para o ponto de equilíbrio muito cedo, antes do TP1 – retrocessos normais tirarão você de boas negociações."},{"h":"Nunca amplie um stop perdedor","t":"Afastar o SL para lhe dar espaço é como pequenas perdas se tornam assassinos de contas. A parada que você definiu antes da entrada é a parada."},{"h":"Parada no tempo","t":"Se uma negociação não fizer nada por muitas velas enquanto uma configuração claramente melhor se forma, fechar estagnado e reimplantar o risco é uma saída válida."},{"h":"Lista de verificação prática","t":"① SL na invalidação, não aleatório ② Buffer para mechas ③ TP1 parcial planejado ④ Trilha após TP1 ⑤ Nunca alargue o SL ⑥ Deixe um vencedor correr."}]},{"id":"plan_journal","title":"11 · Plano de negociação e registro no diário","summary":"Um plano escrito transforma a negociação de jogos de azar em um processo. Aprenda o plano de uma página, a lista de verificação pré-negociação e como registrar um diário para que seus vazamentos se tornem visíveis.","lessons":[{"h":"Por que escrever um plano","t":"Se não estiver escrito não é regra. Um plano elimina a tomada de decisões em tempo real sob estresse e torna seus resultados mensuráveis."},{"h":"O plano de uma página","t":"Par, mercado, configuração (BB + RSI + vela + zona Fib), direção, entrada, SL, TP1/TP2, tamanho (do SL) e perda máxima diária. Se alguma linha estiver em branco → nenhuma negociação."},{"h":"Lista de verificação pré-negociação","t":"Viés de maior TF? · Configuração na minha zona? · Vela confirma? · RSI concorda? · SL escrito? · % de risco? · Recompensa ≥ 1,5R? · Calma? Tudo sim → comércio."},{"h":"Rotina pré-sessão","t":"Verifique o prazo superior, os principais níveis e as novidades. Escreva os dois ou três pares de relógios de hoje antes da sessão – não depois que a vela explodir."},{"h":"O que registrar no diário","t":"Símbolo, lado, entrada, saída, tamanho, R, razão, prazo, sessão e etiqueta de emoção. O CPE Journal salva P/L e motivos automaticamente; adicione suas próprias notas."},{"h":"Registre o PORQUÊ","t":"Registre o que você viu (configuração) e o que sentiu (calma/FOMO/apressado). Um resultado sem contexto não ensina nada."},{"h":"Rastreie R, não ganhe","t":"Dois traders com a mesma taxa de ganho podem ter resultados opostos. O R médio e o rebaixamento máximo são mais importantes do que a% de vitória."},{"h":"Hábito de captura de tela","t":"Salve o gráfico antes e depois de cada negociação. A revisão de 20 capturas de tela mostra sua vantagem e seus vazamentos mais rápido do que qualquer indicador."},{"h":"Revisão semanal","t":"Uma vez por semana, conte suas negociações, R médio, melhor e pior configuração e quebras de regras. Escolha UM vazamento para consertar na próxima semana."},{"h":"Marque os vazamentos","t":"Tags comuns: entrada tardia, sem SL, oversized, SL movido, vingança, tédio. Quando uma tag se repetir, transforme-a em uma regra rígida."},{"h":"O que não registrar","t":"Não registre apenas os vencedores. As perdas são os dados. Um diário só de vitórias é um folheto, não um diário."},{"h":"Planeje a etapa DEMO → AO VIVO","t":"Prove o plano no DEMO para um determinado número de negociações com um R médio positivo antes de arriscar dinheiro real – então comece com metade do tamanho."},{"h":"Lista de verificação prática","t":"① Plano escrito antes da entrada ② Checklist aprovado ③ Lançamento no diário + emoção ④ Revisão semanal ⑤ Um vazamento corrigido."}]},{"id":"leverage","title":"12 · Alavancagem, Margem e Liquidação","summary":"A alavancagem multiplica as perdas tão rapidamente quanto o lucro. Aprenda margem, liquidação, margem isolada versus margem cruzada e as regras de segurança que impedem uma negociação de limpar a conta.","lessons":[{"h":"O que é alavancagem","t":"A alavancagem permite controlar uma posição maior com menos margem. Aumenta tanto os lucros quanto as perdas – não aumenta sua vantagem."},{"h":"Margem vs risco","t":"Margem é o depósito que a bolsa bloqueia. Risco é entrada - Stop × tamanho. A alavancagem altera a margem, nunca o risco do dólar."},{"h":"Liquidação","t":"Se as perdas consumirem a sua margem, a bolsa fecha a posição à força (liquidação), muitas vezes no pior momento. Mantenha seu stop longe do preço de liquidação."},{"h":"Isolado vs Cruzado","t":"Isolado limita a perda à margem dessa posição. Cross usa todo o saldo da carteira – mais perigoso para iniciantes. Prefira Isolado enquanto aprende."},{"h":"Alavancagem mais segura","t":"Baixa alavancagem (2–5x) mais um stop adequado é muito mais seguro do que 50x sem stop. O stop, não o número de alavancagem, é a sua proteção."},{"h":"A regra da distância de liquidação","t":"Verifique se o seu SL está bem dentro do preço de liquidação. Se estiverem próximos, reduza o tamanho até que haja um espaço confortável."},{"h":"A alavancagem não corrige uma entrada incorreta","t":"A alta alavancagem em uma entrada ruim perde mais rápido. Corrija a configuração primeiro e depois dimensione-a."},{"h":"Financiamento e taxas","t":"Os futuros perpétuos cobram financiamento ao longo do tempo. Longas posses de criminosos alavancados sangram o financiamento – outra razão para dimensionar e cronometrar com cuidado."},{"h":"À Vista vs Futuros","t":"O Spot não pode ser liquidado (você possui a moeda). Os futuros podem e podem chegar a zero. Utilize Futuros apenas com plano escrito e margem isolada."},{"h":"Dimensionamento sob alavancagem","t":"Calcule o tamanho a partir da distância de parada e verifique se a margem resultante é acessível. Nunca escolha a alavancagem primeiro."},{"h":"O teste de “uma negociação”","t":"Antes de entrar pergunte: se isso parar, é um encolher de ombros ou um desastre? Se não for um encolher de ombros, o tamanho é muito grande."},{"h":"Lista de verificação prática","t":"① Conjunto isolado ② Baixa alavancagem ③ SL dentro do preço de liquidação ④ Tamanho do stop ⑤ Posso sobreviver a uma perda total aqui? sim → comércio."}]},{"id":"practice","title":"13 · Pratique rotina e backtesting","summary":"A habilidade é construída na DEMO antes do LIVE. Aprenda um ciclo de prática repetível, como fazer “backtest” rolando gráficos e como passar para dinheiro real com segurança.","lessons":[{"h":"DEMO é a academia","t":"Paper/DEMO existe para ensaiar o processo e suas emoções com risco zero. Se você não conseguir seguir as regras do DEMO, o LIVE não irá consertar isso magicamente."},{"h":"O ciclo de prática","t":"Escolha uma configuração (por exemplo BB inferior + Martelo + giro RSI). Marque 20 exemplos históricos no gráfico. Definir entrada / SL / TP. Registre o resultado. Repita."},{"h":"Backtesting manual","t":"Role para trás no Chart Lab, oculte o futuro e marque cada sinal manualmente. Ele treina o reconhecimento de padrões e evita que você se engane."},{"h":"Tamanho da amostra","t":"Dez negociações não significam nada. Procure ter entre 30 e 50 negociações registradas de uma configuração antes de julgá-la."},{"h":"Teste de encaminhamento em DEMO","t":"Após a marcação manual, execute a mesma configuração ao vivo em DEMO com os sinais do software por duas a quatro semanas. Compare preenchimentos e emoções reais com o backtest."},{"h":"Uma configuração de cada vez","t":"Não teste cinco sistemas ao mesmo tempo. Domine uma borda e adicione uma segunda."},{"h":"Mantenha a rotina pequena","t":"Uma rotina diária de 20 minutos (digitalizar, marcar, registrar no diário, revisar) supera seis horas de observação aleatória de gráficos."},{"h":"Graduando para VIVER","t":"Critérios: R médio positivo em mais de 30 negociações DEMO, regras seguidas, sem episódios de vingança. Em seguida, comece o LIVE na metade do tamanho e aumente lentamente."},{"h":"Regra de aumento de escala","t":"Aumente o tamanho somente após um determinado número de semanas disciplinadas e lucrativas – nunca após uma grande vitória."},{"h":"Quando recuar","t":"Atinja o limite de perda diário ou semanal ou observe repetidas quebras de regras → retorne ao DEMO e reconstrua a disciplina antes de continuar."},{"h":"Acompanhe as métricas do processo","t":"Taxa de aprovação da lista de verificação de registro, quebras de regras por semana e R médio. Eles prevêem o crescimento melhor do que um único número de P/L."},{"h":"Caminho de prática de CPE","t":"Aula de aprendizagem → Laboratório de gráficos (configurações de marcas) → Comércio de papel → Revisão de diário → Mesas de sinais em DEMO → pequeno AO VIVO na chave da plataforma correspondente."},{"h":"Lista de verificação prática","t":"① Uma configuração escolhida ② 30 exemplos marcados ③ DEMO forward test ④ Diário + revisão ⑤ R positivo → meio tamanho LIVE."}]},{"id":"volatility","title":"14 · Volatilidade e Martingale","summary":"Como ler a volatilidade do mercado (por que o preço está mudando), como ela é adicionada a cada sinal como uma linha de razão e como funciona a escada opcional de Martingale — além de por que ela é a maneira mais rápida de perder uma conta quando usada de forma descuidada.","lessons":[{"h":"O que significa volatilidade","t":"Volatilidade é o quanto o preço está se movendo – e não para qual direção. Alta volatilidade = velas largas e oscilações rápidas. Baixa volatilidade = uma faixa estreita e silenciosa. A mesma configuração tem confiabilidade muito diferente em cada uma."},{"h":"A leitura da volatilidade do CPE","t":"Cada sinal agora mede o intervalo médio da vela e a largura da banda de Bollinger e, em seguida, compara-os com o normal recente desse par. Você obtém BAIXO/NORMAL/ALTO/EXTREMO além de uma linha de razão em linguagem simples – o “porquê” da mudança de mercado, mostrado com o sinal."},{"h":"Volatilidade EXTREMA = rebaixamento","t":"Quando a fita está EXTREMA, um novo sinal FORTE é rebaixado para CUIDADO (o motivo é mostrado). Em um mercado de serras elétricas, o mesmo padrão falha com muito mais frequência – quebras falsas e mechas de caça são a norma."},{"h":"O que fazer em ALTO/EXTREMO","t":"Tamanho menor. Parada mais ampla. Menos negociações. Aguarde por uma vela completa em vez de um pico no meio da vela. Se a leitura indicar EXTREMO, trate a configuração como uma zona de estudo, não como uma entrada."},{"h":"O que é Martingale","t":"Martingale adiciona uma posição perdedora para diminuir a entrada média: após cada movimento adverso você adiciona outra ordem, geralmente maior (1x, 2x, 4x…). Ele ganha com frequência e depois perde tudo de uma só vez."},{"h":"A regra CPE Martingale","t":"O CPE adiciona uma ordem extra somente quando AMBOS são verdadeiros: (1) o preço se moveu contra a negociação em pelo menos passo × degrau% e (2) um novo sinal do mesmo lado ainda representa esse par. Nunca aumenta só porque o preço caiu."},{"h":"Os quatro números","t":"Etapa % = movimento adverso necessário antes de cada adição. Multiplicador = tamanho de cada adição em relação à base (1 = plano, 2 = duplo). Máximo de acréscimos = limite rígido para pedidos extras. Limite de risco da escada% = risco de toda a escada como% do patrimônio. Todos os quatro são seus para escolher."},{"h":"A capa dura protege você","t":"Mesmo com um grande multiplicador e muitas adições, o CPE recusa a ordem uma vez que o risco total da escada ultrapassaria o seu limite percentual de capital. Também respeita o tamanho mínimo da bolsa e o stop diário de -2%."},{"h":"Onde corre","t":"Marque Manual para gerenciar essa negociação ou em uma sessão Automática para gerenciar suas negociações automáticas. DEMO e AO VIVO. Em Manual, o par deve estar na lista de varredura para que um novo sinal do mesmo lado possa ser lido."},{"h":"Por que o limite é importante (exemplo)","t":"Etapa 1%, multiplicador 2, três somas em uma base de risco de 1%: o risco vai para 1% → 2% → 4% → 8%. Uma parada completa no último degrau apaga muitos vencedores. É por isso que existe o limite e porque os números padrão são pequenos."},{"h":"Alternativa anti-martingale","t":"Muitos profissionais fazem o oposto: somam apenas os vencedores e eliminam os perdedores rapidamente. Parece pior (mais pequenas perdas), mas não pode explodir a conta em uma única tendência contra você."},{"h":"O risco não é removido","t":"A redução da média não elimina o risco – ela transfere o risco de “muitas pequenas perdas” para “uma grande perda”. Nunca adicione dinheiro que você não pode perder e nunca desligue o limite para “recuperar” uma negociação perdida."},{"h":"Caminho de prática","t":"Aprenda primeiro a leitura da volatilidade no DEMO. Experimente Martingale com acréscimos máximos de 1–2 e um pequeno multiplicador em DEMO para mais de 30 negociações. Registre cada escada e depois decida – a maioria dos traders considera o método flat/anti-martingale mais seguro."},{"h":"Lista de verificação de volatilidade + Martingale","t":"① Leia primeiro o nível de volatilidade ② Pular ou encolher em EXTREMO ③ Martingale apenas com um novo sinal do mesmo lado ④ Passo × degrau alcançado ⑤ Sob o limite de risco → adicionar. Qualquer “não” → sem adição."}]},{"id":"lab_indicators","title":"15 · Indicadores de laboratório gráfico (Stoch · ADX · Ichimoku · VWAP)","summary":"O Chart Lab agora tem uma barra de indicadores completa – cada botão é um tique liga/desliga que redesenha o gráfico instantaneamente. Além de BB/RSI/MACD/EMA/SMA50/Volume, agora você obtém Stochastic, ADX/DMI, Ichimoku e VWAP, e o mecanismo de sinal também os lê – não apenas o gráfico.","lessons":[{"h":"Onde fica o bar","t":"Chart Lab → a linha de botões “Indicadores” abaixo do gráfico. Um clique ativa um indicador, o próximo clique o desliga; o gráfico é redesenhado imediatamente. Os ticks são visuais E alimentam o mecanismo de sinal."},{"h":"Estocástico (14,3,3)","t":"Oscilador %K / %D desenhado sob as velas, escala 0–100. Acima de ~80 = zona de sobrecompra, abaixo de ~20 = zona de sobrevenda. %K cruzando %D na zona de sobrevenda é um estudo otimista; uma cruz no topo é de baixa. Numa tendência forte ela pode ficar presa em uma das pontas por muito tempo — combine sempre com BB e a vela."},{"h":"ADX/DMI (14)","t":"ADX mede a FORÇA da tendência, não a direção. Acima de ~25 = existe uma tendência real; abaixo de ~20 = uma faixa instável. +DI acima −DI = compradores responsáveis; −DI acima +DI = vendedores responsáveis. Use o ADX para decidir se deseja negociar a tendência ou permanecer estável."},{"h":"Nuvem Ichimoku (9,26,52)","t":"Tenkan (linha rápida), Kijun (linha lenta) e a nuvem Senkou. Preço acima de uma nuvem ascendente = fundo de alta; abaixo de uma nuvem caindo = baixa. Um cruzamento Tenkan/Kijun dentro da nuvem é fraco; um cruzamento com o preço saindo da nuvem é mais forte. A própria borda da nuvem geralmente atua como suporte/resistência."},{"h":"VWAP","t":"Preço médio ponderado por volume — o preço médio ponderado por volume, redefinido a cada sessão. As grandes instituições comparam seus valores com isso. Preço acima de um VWAP crescente = compradores no controle; uma rejeição clara no VWAP durante uma tendência de baixa é um estudo curto. Na criptografia 24 horas por dia, 7 dias por semana, ela é redefinida de maneira diferente do que no FX – trate-a como uma diretriz, não como uma lei."},{"h":"Como o motor os usa","t":"Cada novo indicador adiciona uma pequena confirmação à pontuação do mesmo lado que aponta (Stochastic, Ichimoku, VWAP, ADX quando concorda com a direção, e Elliott). São confirmações, não gatilhos – se discordarem do BB/RSI/da vela, a pontuação simplesmente fica mais mista e você obtém mais HOLD."},{"h":"Por que CUIDADO ficou mais rígido","t":"Como agora há mais verificações no pool, a barra de CUIDADO foi reforçada: ela precisa de pontuação ≥ 4 E pelo menos 3 verificações de concordância. Isso evita que o aplicativo inunde você com sinais mais fracos só porque mais ferramentas estão ativadas."},{"h":"Uma ordem de leitura que funciona","t":"① Direção TF superior (nuvem Ichimoku + ADX). ② Onde o preço é (BB/Fib/VWAP). ③ Momentum (RSI + Estocástico). ④ Confirmação da vela. ⑤% de risco e níveis escritos → Artigo primeiro."},{"h":"Erros a evitar","t":"Ligar todos os indicadores e olhar para um arco-íris; usar ADX como direção (é apenas força); operar vendido apenas porque o Estocástico está >80 dentro de uma corrida de alta; ignorando que VWAP significa coisas diferentes em criptografia e FX."},{"h":"Lista de verificação prática","t":"① Bias da nuvem + ADX ② Localização de BB / Fib / VWAP ③ Momentum de RSI + Stoch ④ Vela confirmada ⑤ SL / TP escrito ⑥ Papel, depois diário."}]},{"id":"elliott","title":"16 · Elliott Wave (contagem de luz)","summary":"O CPE inclui um contador Elliott Wave leve. Marque “Elliott” na barra do indicador Chart Lab e ele rotula o último impulso 0-1-2-3-4-5 nas velas e projeta uma meta Fibonacci de onda 5. É uma ferramenta de estudo – não uma bola de cristal.","lessons":[{"h":"A ideia em uma linha","t":"Os mercados se movem em ondas: impulsos (5 pernas na direção da tendência) e correções (3 pernas contra ela). O CPE conta apenas o impulso, que é a parte que carrega a tendência."},{"h":"Como o CPE conta","t":"Ele encontra os últimos pivôs de oscilação (fractais de 3 barras), alterna alta/baixa e testa as últimas 5–6 oscilações de acordo com as regras de Elliott. Se a forma se ajustar, ela desenha os rótulos 0 → 5 (a onda ainda em execução em amarelo) e uma linha alvo W5 construída a partir do comprimento da onda 1 × 1,618 medido na onda 4."},{"h":"As regras que verifica","t":"A onda 2 não ultrapassa o início da onda 1; a onda 4 não se sobrepõe ao território da onda 1; a onda 3 não é a mais curta de 1/3/5. Quando uma regra falha, ela não mostra nada - nenhuma contagem forçada."},{"h":"Alta vs baixa","t":"Um 0-1-2-3-4-5 ascendente é um impulso de alta; a imagem espelhada na queda é de baixa. O motor adiciona uma pequena confirmação à pontuação do lado da onda."},{"h":"Ao vivo vs completo","t":"Uma onda 5 AO VIVO (ainda em execução) é considerada uma continuação da tendência. Um impulso COMPLETO (0–5 finalizado) avisa que a tendência pode ser cansativa – muitas vezes segue-se uma correção."},{"h":"A linha alvo W5","t":"Uma extensão Fibonacci da onda 1 da onda 4 baixa/alta. É uma ideia-alvo, não um ímã – o preço pode ficar aquém ou ultrapassá-lo."},{"h":"Como usar","t":"Trate a contagem como uma confluência: em uma zona BB/Fib clara com uma vela e RSI, uma contagem impulsiva acrescenta convicção. Por si só, é apenas um esboço."},{"h":"Erros a evitar","t":"Recontar as ondas até que elas se ajustem à sua posição (o pecado clássico de Elliott); contando pequenos movimentos; ignorando a contagem de prazos mais elevados; esquecer que a contagem muda toda vez que uma nova barra é impressa."},{"h":"Lista de verificação prática","t":"① Balanços claros escolhidos ② Regras aprovadas ③ Zig-zag concorda com BB / Fib ④ Vela confirmada ⑤ SL além do ponto de invalidação da onda 4."}]},{"id":"forecast","title":"17 · Previsão de 3 meses (o tick da previsão 3M)","summary":"O projetor de longo horizonte: como este gráfico provavelmente se formará nos próximos aproximadamente 3 meses, construído a partir da própria tendência, metas e volatilidade do sinal. Ligue ou desligue com a marca “Forecast 3M” no Chart Lab.","lessons":[{"h":"O que isso desenha","t":"Um caminho central tracejado que vai da entrada analisada em direção ao melhor alvo que o mecanismo já conhece (alvo de Elliott → tp2 → tp1), envolto em um “cone” cada vez maior que mostra o spread de preços plausíveis. Os marcadores de mês M+1 / M+2 / M+3 dividem o horizonte."},{"h":"Por que um cone e não uma linha","t":"Ninguém pode saber um preço futuro exato. O cone se alarga com a raiz quadrada do tempo e a própria volatilidade do par, de modo que um par FX silencioso obtém um cone estreito e uma altcoin selvagem, um cone muito largo. Essa largura É a mensagem: quanto mais longe você olha, menos certo é o preço."},{"h":"De onde vêm os números","t":"A deriva vem do alvo do sinal atual; a volatilidade diária vem do ATR% do sinal dimensionado para um dia, de modo que o cone significa o mesmo em um gráfico de 5m ou 1d; A volatilidade EXTREMA/ALTA amplia ainda mais."},{"h":"Como ler","t":"Veja a INCLINAÇÃO (para que lado o caminho se inclina) e a LARGURA (quanta dúvida). Um caminho ascendente com um cone estreito = uma ideia de tendência mais estável; um caminho plano com um cone enorme = “sem arestas aqui, espere barulho”."},{"h":"Ligando e desligando","t":"O botão “Previsão 3M” fica ao lado de “Espaço futuro”. Precisa de espaço Futuro LIGADO (a área em branco à direita onde a projeção é desenhada). Se o sinal for HOLD não há direção, então nada é desenhado."},{"h":"É a tendência, não o comércio","t":"A previsão é um mapa geral. Os níveis reais de negociação – entrada, TP1/TP2, SL e a projeção de curto prazo – ainda são o que você negocia."},{"h":"Limites honestos","t":"Notícias, listagens, exclusões e mudanças macro não estão no modelo; o caminho é uma deriva suave, de modo que os preços reais oscilarão muito mais; um cone de 3 meses é um auxílio de estudo, nunca uma promessa."},{"h":"Reanalisar frequentemente","t":"À medida que novas velas são impressas, o alvo, a volatilidade e, portanto, todo o cone são atualizados. Uma previsão é um instantâneo, não um contrato."},{"h":"Lista de verificação prática","t":"① Leia a direção do caminho ② Verifique a largura do cone ③ Compare com a estrutura de TF superior ④ Dimensione a posição do SL real, nunca do cone."}]}],"platforms":{"BINANCE":{"title":"Negociação Binance A → Z","steps":["Crie uma conta → habilite 2FA.","Gerenciamento de API → Criar chave → Negociação à vista e/ou de futuros ativada, retiradas desativadas.","Cole Chave + Segredo em CPE → Chaves API → Binance → Salvar → Conta de teste.","Use a varredura Spot Desk / Futures Desk (gráficos públicos funcionam mesmo antes das chaves).","Prática: Negociação Manual → Iniciar Negociação em Papel (sem dinheiro real).","Ao vivo: defina TP1/TP2/SL + Trailing → Iniciar negociação ao vivo (precisa de API).","Gerenciar em Posições: editar níveis, fechamento parcial, cancelar automático.","Licença: Avaliação 7d → 3 meses ou vitalícia (preços para proprietários no aplicativo)."]},"BYBIT":{"title":"Negociação de Bybit A → Z","steps":["Conta + 2FA.","Gerenciamento de API → apenas negociação, retiradas DESATIVADAS.","CPE → Chaves API → Bybit → Salvar.","Mesa de Futuros para mentalidade de criminosos; Chart Lab para estudar velas.","Comércio de papel primeiro; Viva depois que as chaves funcionarem.","Trilha TP+SL: COMPRAR↑ / VENDER↓."]},"OKX":{"title":"OKX Negociação A → Z","steps":["Chave de API + segredo + senha obrigatória.","Retiradas OFF sempre.","Salve todos os três campos em Chaves CPE.","Prática de papel → tamanho pequeno ao vivo.","Erros de digitação na senha são a falha número 1 – copie com cuidado."]},"KUCOIN":{"title":"Negociação KuCoin A → Z","steps":["Chave + Segredo + Senha.","Apenas permissão comercial.","Papel em CPE → então viva pequeno.","Use mesas à vista/futuros para sinais."]},"BITGET":{"title":"Negociação de Bitget A → Z","steps":["API apenas com comércio.","Papel então vivo.","Futuros: escolha Cruzado ou Isolado na negociação manual.","Siga TP+SL para garantir lucros."]},"GATE":{"title":"Gate.io Negociação A → Z","steps":["Crie chaves API v4 (comércio).","Retiradas DESATIVADAS.","Salve no CPE → pratique o papel.","Scan + Chart Lab para entradas antes do lançamento."]},"MEXC":{"title":"MEXC Negociação A → Z","steps":["Comece a mentalidade Spot.","Chaves em chaves de API CPE.","Papel → ao vivo.","Use a trilha para bloquear o lucro aberto."]},"KRAKEN":{"title":"Negociação Kraken A → Z","steps":["Gere chave apenas com permissão comercial.","Sem direitos de saque/financiamento.","Prática de papel em CPE.","Verifique também todos os pedidos ao vivo no Kraken."]},"COINBASE":{"title":"Coinbase Avançado A → Z","steps":["Chaves avançadas de API comercial.","Mesa focada em spot em CPE.","Papel então vivo.","Mantenha as retiradas DESATIVADAS."]},"FOREX_OANDA":{"title":"Forex (OANDA) A → Z","steps":["Abra a demonstração da OANDA → risco ~1%.","Token de acesso pessoal + ID da conta nas chaves CPE.","Varredura Forex Desk + Laboratório de gráficos (EURUSD…).","Negociação manual → Papel com plataforma Forex.","Viva somente após demonstrar confiança."]},"FOREX_FXCM":{"title":"FXCM Forex A → Z","steps":["Credenciais da API do corretor.","Papel em CPE primeiro.","Assista às sessões de Londres/NY e picos de notícias.","O diário ao vivo após o treino parece limpo."]},"FOREX_MT5":{"title":"MetaTrader 5 A → Z","steps":["Login + servidor + senha em Chaves CPE.","Prefira a senha do investidor (leitura) sempre que possível.","Pratique o lote 0,01.","Papel em CPE; ao vivo via corretor quando estiver pronto."]},"FOREX_DEMO":{"title":"Taxas de demonstração Forex A → Z","steps":["Nenhuma chave de API é necessária.","Forex Desk + Chart Lab para gráficos gratuitos.","Apenas negociações em papel (prática).","Quando estiver pronto para um corretor real, adicione chaves OANDA/FXCM/MT5 para live."]}},"forexAz":{"title":"Negociação Forex A → Z (aula completa)","lessons":[{"h":"A - Conta e risco","t":"Demonstração primeiro. Risco de aproximadamente 0,5–1% por ideia. Nunca vingue o comércio."},{"h":"B - Pares","t":"Majors (EURUSD, GBPUSD, USDJPY) antes dos exóticos."},{"h":"C – Velas","t":"Aprenda Doji, Hammer, Engulfing no Chart Lab Forex."},{"h":"D - Viés diário","t":"Verifique prazos maiores antes das entradas de 15m/30m."},{"h":"E – Entradas","t":"O salto inferior do BB + confirmação de vela é uma configuração de prática comum."},{"h":"F - mentira","t":"Recuos de 50% / 61,8% frequentemente usados como zonas de prática."},{"h":"G — Gols (TP)","t":"Escala TP1, corredor TP2, trilha SL."},{"h":"H – Horas","t":"Sobreposição Londres-NY = mais movimento."},{"h":"I – Indicadores","t":"RSI + MACD + BB juntos; evite sobrecarga do indicador."},{"h":"J - Diário","t":"Registre todas as negociações em papel/ao vivo no CPE Journal."},{"h":"K - Chaves","t":"O corretor forex ao vivo precisa de API/token; taxas de demonstração não precisam de nenhuma."},{"h":"L – Muitos","t":"Comece 0,01 lotes na mentalidade prática."},{"h":"M - mentalidade","t":"Processo sobre previsão. Pule os dias ruins."},{"h":"N - Notícias","t":"Verifique notícias e truques antes de grandes eventos."},{"h":"Ó - Pedidos","t":"Sempre defina SL. O trailing protege o lucro aberto."},{"h":"P - Prática","t":"Botão Paper Trade = pratique sem API ao vivo."},{"h":"P - Qualidade","t":"Menos configurações de alta qualidade superam o overtrading."},{"h":"R — Risco:recompensa","t":"Visar configurações onde recompensa ≥ risco, quando possível."},{"h":"S - Sessões","t":"Ásia mais tranquila; Londres/NY mais ativa."},{"h":"T - Tendências","t":"Negocie com tendência de TF mais alto ao aprender."},{"h":"U – Atualizações","t":"Assista ao banner de atualização do CPE + Live Help."},{"h":"V — Volatilidade","t":"Aumente a paciência quando o ATR aumentar."},{"h":"W – Retirar API","t":"Nunca ative a retirada em qualquer chave de API."},{"h":"X – saídas","t":"TP parcial + trilha supera a esperança."},{"h":"Y - Seu plano","t":"Escreva regras; siga-os em Manual/Auto."},{"h":"Z – pressa zero","t":"Sem FOMO. Pratique → depois API ao vivo."}]}};

window.CPE_LEARN.fr = {"intro":"Entraînez-vous d'abord avec Paper / DEMO. Étudiez les bougies, les graphiques, BB/RSI/Fib, l'argent, la psychologie — puis les signaux (ce que signifie ACHETER/VENDRE/TENIR + que faire) et les signaux Forex. Live a besoin de la bonne clé API de plateforme (Retraits OFF).","candles":[{"shape":"doji","name":"Doji","color":"#94a3b8","bias":"Neutre / attendre","tip":"Ouvert ≈ fermé – corps croisé ou mince. Indécision du marché après un mouvement.","also":"Apprend également : ne pas FOMO. Attendez la prochaine bougie. Près de BB extrême + Doji = compression des opinions ; vérifiez la pente RSI avant de deviner la direction."},{"shape":"hammer","name":"Marteau","color":"#22c55e","bias":"Biais d'achat","tip":"Petit corps en haut, longue mèche inférieure (≈2 × corps) après une baisse – les acheteurs ont rejeté les prix plus bas.","also":"Aussi : placez le Practice SL sous la mèche basse. Meilleur avec un BB + RSI inférieur en hausse à cause de la survente. Psychologie : patience jusqu'à ce que la mèche se termine – n'achetez pas de mèche intermédiaire."},{"shape":"invhammer","name":"Marteau inversé","color":"#22c55e","bias":"ACHETER (faible)","tip":"Longue mèche supérieure en bas. Les acheteurs ont sondé haut mais ont fermé presque ouvert – il faut une prochaine confirmation verte.","also":"Aussi : plus faible que Hammer seul. Utiliser comme alerte, pas comme entrée. Rebond Fib 61.8 + Marteau inversé = zone d'étude uniquement jusqu'à confirmation de la bougie."},{"shape":"shooting","name":"Étoile filante","color":"#ef4444","bias":"Biais de VENTE","tip":"Petit fond de corps, longue mèche supérieure après une hausse – les vendeurs ont rejeté les sommets.","also":"Aussi : SL au-dessus de la mèche haute. Plus fort près du BB supérieur / extension Fib / surachat RSI. Enseigne : les bougies lunaires peuvent échouer – ne poursuivez pas le dernier vert."},{"shape":"hanging","name":"Homme pendu","color":"#f59e0b","bias":"VENDRE prudence","tip":"Ressemble à Hammer mais apparaît après une montée – possible épuisement maximal.","also":"Aussi : le contexte est tout (même forme ≠ même métier). Emplacement du journal : haut ou bas. Psychologie : n'inversez pas simplement parce que la forme correspond – confirmez avec la prochaine bougie + RSI."},{"shape":"engulf_bull","name":"Engloutissement haussier","color":"#22c55e","bias":"ACHETER","tip":"Le corps vert recouvre entièrement le corps rouge précédent – les acheteurs ont pris le contrôle dans une seule barre.","also":"Aussi : plus fort au support / BB inférieur / Fib 50–61,8. Taille engloutissante aussi basse que SL. Conseil financier : corps engloutissant large → SL plus large → taille plus petite."},{"shape":"engulf_bear","name":"Engloutissement baissier","color":"#ef4444","bias":"VENDRE","tip":"Le corps rouge recouvre entièrement le vert précédent – les vendeurs ont dominé.","also":"Aussi : prudence sur les positions longues ouvertes. Près du BB supérieur + RSI>70 = qualité d'étude élevée. Apprend le risque : si déjà long, TP/trail partiel au lieu d'espérer."},{"shape":"morning","name":"Étoile du matin","color":"#22c55e","bias":"ACHETER","tip":"3 bougies : grande rouge → petite étoile → grande verte. Histoire de renversement du fond.","also":"Aussi : patience multi-bougies. Entrez après la 3ème fermeture ; SL sous étoile basse. Se combine bien avec la divergence RSI BB inférieure + haussière."},{"shape":"evening","name":"Étoile du soir","color":"#ef4444","bias":"VENDRE","tip":"3 bougies : grande verte → petite étoile → grande rouge. Top histoire de renversement.","also":"Aussi : ne court-circuitez pas uniquement l’étoile du milieu. Attendez la 3ème fermeture. Confluence d’extension supérieure BB/Fib. Psychologie : ignorez le FOMO de la première piste verte."},{"shape":"maru_bull","name":"Taureau Marubozu","color":"#22c55e","bias":"Forte pression d’achat","tip":"Corps vert long, presque pas de mèches - les acheteurs contrôlent l'ouverture → la fermeture.","also":"Aussi : indice de continuation de tendance, pas toujours un achat le plus bas. Promenade avec le groupe possible. Risque : courir après Marubozu tardif sans recul vers BB mid / Fib."},{"shape":"maru_bear","name":"Ours Marubozu","color":"#ef4444","bias":"Forte pression de VENTE","tip":"Long corps rouge, presque pas de mèches – les vendeurs aux commandes.","also":"Aussi : n’attrapez pas les couteaux qui tombent. Attendez le rebond BB/Fib + Hammer plus tard. Apprend : forte pression = taille plus petite ou se tenir à l'écart."},{"shape":"spin","name":"Toupie","color":"#94a3b8","bias":"Indécision","tip":"Petit corps, mèches supérieures et inférieures — les deux camps se sont battus, personne n'a clairement gagné.","also":"Aussi : à l’intérieur du BB, pressez-le souvent. Suspendre le trading ; attente pause + bougie de direction. Leçon de psychologie : le marché ne peut « rien faire » – l’appartement est un choix valable."},{"shape":"pierce","name":"Ligne de perçage","color":"#22c55e","bias":"ACHETER","tip":"Rouge puis vert qui s'ouvre plus bas mais se ferme au-dessus du point médian du rouge précédent.","also":"Aussi : plus doux qu’Engulfing. Confirmez avec le tour RSI. Bon foret à papier pour la lecture de la résistance partielle – tous les verts ne sont pas égaux."},{"shape":"darkcloud","name":"Couverture nuageuse sombre","color":"#ef4444","bias":"VENDRE","tip":"Vert puis rouge qui ouvre plus haut mais ferme en dessous du point médian du vert précédent.","also":"Aussi : alerte précoce avant un engloutissement complet de l'ours. Trail longs / prendre TP1. Enseigne la mise à l'échelle avant une impression d'inversion complète."},{"shape":"soldiers","name":"Trois soldats blancs","color":"#22c55e","bias":"ACHETER tendance","tip":"Trois verts en hausse avec des clôtures plus élevées – achats réguliers.","also":"Également : un fort signal de tendance haussière ; les retraits vers Fib 38-50 ou BB mid sont des ajouts pratiques. Risque d’excès de confiance après 3 greens – gardez le % de risque fixe."},{"shape":"crows","name":"Trois corbeaux noirs","color":"#ef4444","bias":"Tendance VENDRE","tip":"Trois rouges en baisse avec des clôtures plus basses – vente stable.","also":"Aussi : ne faites pas de moyenne. Structure d'attente. La survente du RSI peut rester survente – règle monétaire : limite de perte > espoir."},{"shape":"harami_bull","name":"Harami haussier","color":"#22c55e","bias":"ACHETER (soft)","tip":"Gros rouge, puis petit vert à l'intérieur du corps précédent – la pression de vente diminue.","also":"Aussi : signal de pause précoce. Besoin de confirmer. S'associe à l'étude de divergence haussière RSI. Enseigne la lecture de « la diminution de la force » et non seulement des renversements."},{"shape":"harami_bear","name":"Harami baissier","color":"#ef4444","bias":"VENDRE (doux)","tip":"Grand vert, puis petit rouge à l’intérieur – la pression d’achat diminue.","also":"Aussi : prenez des partiels sur des positions longues. Pas de court-circuit automatique. Psychologie : l'avidité après le grand vert ignore souvent l'avertissement d'Harami."},{"shape":"tweezer_bot","name":"Bas de la pince à épiler","color":"#22c55e","bias":"ACHETER","tip":"Deux bougies avec des plus bas correspondants – double test de support.","also":"Aussi : marquez cela bas comme structure. SL juste en dessous. L’alignement Fib/BB aide. Modèle de graphique cousin de Double Bottom – même leçon de support."},{"shape":"tweezer_top","name":"Pince à épiler","color":"#ef4444","bias":"VENDRE","tip":"Deux bougies avec des sommets correspondants – double test de résistance.","also":"Aussi : marquer la résistance. Cousin de Double Top. Échec du RSI aux sommets = confluence. Enseigne : même prix rejeté deux fois = respecter le niveau."},{"shape":"longlegged","name":"Doji aux longues jambes","color":"#94a3b8","bias":"Indécision","tip":"De très longues mèches supérieures ET inférieures avec un corps minuscule – un violent combat à double sens qui s'est terminé là où il avait commencé.","also":"Aussi : un grand mouvement s’ensuit souvent, mais la direction est inconnue – attendez la bougie de rupture. Enseigne : une forte volatilité n’est pas une grande certitude."},{"shape":"dragonfly","name":"Doji libellule","color":"#22c55e","bias":"Biais d'achat","tip":"Ouvrir = fermer = haut, avec une longue mèche inférieure – les vendeurs ont poussé vers le bas et les acheteurs l'ont remonté directement.","also":"Aussi : le plus fort au niveau du support / BB inférieur après une baisse. SL sous la queue de mèche. Enseigne : le rejet est une histoire, pas une garantie — confirmez la prochaine bougie."},{"shape":"gravestone","name":"Doji de pierre tombale","color":"#ef4444","bias":"Biais de VENTE","tip":"Ouvert = clôture = bas, avec une longue mèche supérieure – les acheteurs ont poussé vers le haut et les vendeurs l'ont ramené vers le bas.","also":"Également : le plus fort à la résistance / surachat du BB / RSI supérieur. Miroir de la Libellule. Enseigne : un pic haut qui se ferme au plus bas est une cassure ratée."},{"shape":"inside_bar","name":"Bar intérieur","color":"#94a3b8","bias":"Enroulement / attente","tip":"La deuxième bougie se trouve complètement à l’intérieur de la première – la fourchette se comprime et le marché retient son souffle.","also":"Aussi : la cassure de la barre mère est le déclencheur : échangez dans le sens de la cassure. Se couple avec une pression BB. Enseigne : la contraction précède l’expansion."},{"shape":"outside_bar","name":"Bar extérieur","color":"#22c55e","bias":"Breakout / renversement","tip":"La deuxième bougie engloutit la première de haut en bas – une violente prise de contrôle à l’intérieur d’une barre.","also":"Aussi : direction = où la barre extérieure se ferme. Une grosse barre signifie un gros SL, donc une taille plus petite. Apprend : une mesure peut effacer les trois dernières."},{"shape":"belt_bull","name":"Maintien de la ceinture haussière","color":"#22c55e","bias":"ACHETER","tip":"S'ouvre au plus bas sans mèche inférieure et passe au vert – les acheteurs ont pris le contrôle dès le premier tick.","also":"Aussi : le plus fort après un écart vers le bas ou directement vers le support. SL à l'air libre. Enseigne : un entraînement d’ouverture montre une intention réelle."},{"shape":"belt_bear","name":"Maintien de la ceinture baissière","color":"#ef4444","bias":"VENDRE","tip":"S'ouvre en haut sans mèche supérieure et est rouge – les vendeurs le contrôlaient depuis l'ouverture.","also":"Aussi : le plus fort après un écart ou à la résistance. Le sentier est long. Enseigne : le premier mouvement peut définir toute la journée."},{"shape":"kick_bull","name":"Kicker haussier","color":"#22c55e","bias":"ACHAT Fort","tip":"Une bougie rouge, puis un espace dans une bougie verte – l'ambiance a basculé entre les clôtures sans chevauchement.","also":"Aussi : rare et puissant ; l'espace est requis, aucun chevauchement n'est autorisé. Enseigne : le sentiment peut basculer pendant que le marché dort."},{"shape":"kick_bear","name":"Kicker baissier","color":"#ef4444","bias":"VENTE FORTE","tip":"Une bougie verte, puis un espace vers une bougie rouge – les acheteurs ont disparu entre les clôtures.","also":"Aussi : sortez rapidement des positions longues – les kickers ne vous attendent pas. Enseigne : un écart est la révision des prix du marché lorsque vous êtes absent."},{"shape":"abandoned","name":"Bébé abandonné haussier","color":"#22c55e","bias":"ACHAT Fort","tip":"Une bougie rouge, un doji écarté, puis une bougie verte écartée – une île solitaire d'indécision.","also":"Aussi : le doji doit s'écarter des DEUX côtés. Rare mais de haute qualité en bas. Enseigne : les renversements commencent là où tout le monde abandonne."},{"shape":"three_inside_up","name":"Trois à l'intérieur","color":"#22c55e","bias":"ACHETER","tip":"Harami haussier plus une troisième bougie verte qui se ferme au-dessus de la première – la barre intérieure s'est finalement brisée.","also":"Aussi : un Harami confirmé est bien plus fort qu’un simple. SL sous le harami bas. Enseigne : la confirmation bat la prédiction."},{"shape":"three_inside_down","name":"Trois à l'intérieur vers le bas","color":"#ef4444","bias":"VENDRE","tip":"Harami baissier plus une troisième bougie rouge se fermant en dessous de la première – la barre intérieure est tombée en panne.","also":"Aussi : coupez les positions longues dès la clôture du troisième. Enseigne : une pause ratée peut simplement reprendre l’ancienne tendance."},{"shape":"three_methods_bull","name":"Monter trois méthodes","color":"#22c55e","bias":"ACHETER tendance","tip":"Une longue bougie verte, trois petits rouges à l'intérieur, puis une autre longue bougie verte — un repos à l'intérieur d'une hausse.","also":"Aussi : la pause ne quitte jamais la première plage de bougies, donc la tendance est calme. Échangez la pause de la dernière bougie. Enseigne : les tendances se reposent sans se briser."},{"shape":"three_methods_bear","name":"Chute de trois méthodes","color":"#ef4444","bias":"Tendance VENDRE","tip":"Une longue bougie rouge, trois petits verts à l’intérieur, puis une autre longue rouge – un repos à l’intérieur d’une chute.","also":"Aussi : miroir de Rising Three Methods. N'achetez pas les petits verts, ils font du bruit. Enseigne : les retraits à l’intérieur d’une fourchette ne sont pas des inversions."},{"shape":"tower_bot","name":"Bas de la tour","color":"#22c55e","bias":"ACHETER un renversement","tip":"Une longue bougie rouge, un groupe de petites bougies, puis une longue bougie verte : l'ambiance change sur une base plate.","also":"Aussi : le milieu plat est la bataille et la dernière bougie déclare le vainqueur. Enseigne : les bases prennent du temps."},{"shape":"tower_top","name":"Sommet de la tour","color":"#ef4444","bias":"VENTE inversion","tip":"Une longue bougie verte, un groupe de petites bougies, puis une longue rouge : les acheteurs s'épuisent et les vendeurs prennent le relais.","also":"Egalement : miroir de Tower Bottom. Prenez des partiels pendant que la base se forme. Enseigne : les sommets sont un processus, pas un instant."}],"chartPatterns":[{"shape":"double_bot","name":"Double fond (W)","color":"#22c55e","bias":"Biais d'achat","tip":"Deux plus bas proches du même prix, puis cassure du pic central – forme en W.","also":"Aussi : pause décolleté = déclencheur d’entraînement. Mesurez la hauteur pour l’idée TP. Liens vers Tweezer Bottom + Fib depuis pic → bas. Risque : fausse cassure – attendre juste au-delà du décolleté."},{"shape":"double_top","name":"Double sommet (M)","color":"#ef4444","bias":"Biais de VENTE","tip":"Deux sommets proches du même prix, puis cassure du creux médian – forme en M.","also":"Aussi : identique à Tweezer Top à plus grande échelle. Le sentier dure longtemps avant la cassure du décolleté. Psychologie : le deuxième FOMO coûte cher – le plan était déjà là."},{"shape":"hs_top","name":"Tête et épaules","color":"#ef4444","bias":"Biais de VENTE","tip":"Épaule gauche, tête haute, épaule droite ; casser le décolleté.","also":"Aussi : distribution classique. Cible ≈ hauteur de la tête sous le décolleté. Le RSI diverge souvent en tête. Enseigne la patience multi-swing – pas le trading d’une seule bougie."},{"shape":"ihs","name":"Santé et sécurité inversées","color":"#22c55e","bias":"Biais d'achat","tip":"H&S à l’envers en bas – décolleté cassé.","also":"Aussi : histoire d’accumulation. Confirmez avec volume/élan si disponible. Associez-le à Morning Star dans la zone de l’épaule droite pour une étude de confluence."},{"shape":"triangle","name":"Triangle (presser)","color":"#f0b429","bias":"Attente d'évasion","tip":"Compression des hauts plus bas + des bas plus élevés – accumulation d’énergie.","also":"Aussi : même leçon que BB squeeze. Ne devinez pas la direction à l’intérieur. Pause commerciale + clôture de bougie. Argent : taille après direction connue."},{"shape":"flag","name":"Drapeau de taureau","color":"#22c55e","bias":"ACHETER suite.","tip":"Forte montée (pôle) puis petit canal descendant/latéral — puis continuation.","also":"Aussi : la profondeur du drapeau Fib est souvent faible (38 %). Poteau Marubozu + drapeau = pratique tendance. N'achetez pas tard après une extension complète sans retrait."},{"shape":"channel","name":"Canal de tendance","color":"#38bdf8","bias":"Avec tendance","tip":"Prix entre des lignes parallèles montantes (ou descendantes) – outils de swing trade.","also":"Aussi : achetez le canal inférieur + Hammer dans la tendance haussière ; vends supérieur + Shooting Star. BB Mid suit souvent la chaîne. Enseigne « où » et pas seulement « quelle bougie »."},{"shape":"support_res","name":"Soutien et résistance","color":"#a78bfa","bias":"Le contexte d'abord","tip":"Zones horizontales où le prix réagit de manière répétée – la carte sous chaque bougie.","also":"Aussi : chaque modèle est plus fort en S/R. Dessinez des zones sur Chart Lab avant BB/RSI. Psychologie : niveaux > astuces ; écrivez-les avant d'entrer."},{"shape":"triple_top","name":"Triple sommet","color":"#ef4444","bias":"Biais de VENTE","tip":"Trois sommets à peu près au même prix – les acheteurs échouent trois fois devant un même mur.","also":"Aussi : plus résistant qu'un Double Top (trois rejets = approvisionnement tenace). La cassure du décolleté est le déclencheur ; cible ≈ hauteur du motif. Enseigne : c'est le niveau, pas la bougie, qui est le patron."},{"shape":"triple_bot","name":"Triple fond","color":"#22c55e","bias":"Biais d'achat","tip":"Trois plus bas à presque le même prix – les vendeurs échouent trois fois sur un même étage.","also":"Aussi : miroir de Triple Top. Chaque contact peut être une étude Marteau / Pince à épiler. Attendre la cassure du décolleté + fermer. Enseigne la patience à travers de nombreuses balançoires."},{"shape":"cup_handle","name":"Tasse et poignée","color":"#22c55e","bias":"ACHETER suite.","tip":"Un « U » arrondi (tasse) puis un petit retrait (poignée) — continuation après un repos.","also":"Aussi : populaire auprès des traders en petits groupes. Le manche doit être peu profond et court – un manche profond signifie des mains faibles. Entrez sur rupture de poignée avec confirmation par bougie."},{"shape":"rounding_bot","name":"Fond arrondi","color":"#22c55e","bias":"ACHETER un renversement","tip":"Une « soucoupe » lente et douce – les ventes s’estompent progressivement, puis les acheteurs prennent le relais.","also":"Aussi : un Double Bottom au ralenti. Le message est que les vendeurs ont manqué d’énergie, pas un seul pic – une patience totale est requise."},{"shape":"rounding_top","name":"Haut arrondi","color":"#ef4444","bias":"VENTE inversion","tip":"Un sommet en « dôme » lisse – les achats s’estompent progressivement avant que le prix ne revienne.","also":"Egalement : miroir de Rounding Bottom. Prenez les partiels tôt pendant que l'élan meurt. Enseigne : les sommets sont un processus, pas une seule bougie."},{"shape":"rising_wedge","name":"Coin ascendant","color":"#ef4444","bias":"Biais de VENTE","tip":"Les deux rails montent, mais convergent vers le haut – les acheteurs se fatiguent à mesure que l’autonomie se rétrécit.","also":"Aussi : trompeur car le prix continue d’augmenter ; le rétrécissement est le véritable indice. Souvent en panne. Ne poursuivez pas la dernière poussée."},{"shape":"falling_wedge","name":"Coin tombant","color":"#22c55e","bias":"Biais d'achat","tip":"Les deux rails tombent, mais ils convergent vers le bas – les vendeurs se fatiguent à mesure que la distance se rétrécit.","also":"Aussi : miroir de Rising Wedge. Se brise souvent. Un marteau dans la queue en coin est une étude classique. Attendez la pause + fermez."},{"shape":"asc_triangle","name":"Triangle ascendant","color":"#f0b429","bias":"Biais d'achat","tip":"Un plafond plat + un plancher montant – les acheteurs continuent de se heurter à une résistance fixe.","also":"Aussi : la pression monte contre un prix unique ; les éruptions cutanées sont courantes. Entrez en fermeture au-dessus du plafond. Enseigne : les acheteurs s’impatientent."},{"shape":"desc_triangle","name":"Triangle descendant","color":"#f0b429","bias":"Biais de VENTE","tip":"Un sol plat + un plafond tombant – les vendeurs continuent de pousser vers un support fixe.","also":"Aussi : miroir du Triangle Ascendant. Les pannes sont courantes. Entrez à proximité du sol. Enseigne : les vendeurs prennent le contrôle."},{"shape":"pennant","name":"Fanion","color":"#22c55e","bias":"Suite","tip":"Un pôle pointu puis un petit triangle serré – un très court repos avant que la tendance ne reprenne.","also":"Aussi : comme un drapeau mais plus court et triangulaire. Mesurez le poteau pour une idée cible. Ne devinez jamais à l’intérieur de la petite bobine."},{"shape":"flag_bear","name":"Ours Drapeau","color":"#ef4444","bias":"VENDRE suite.","tip":"Une forte baisse (pôle) puis un petit canal ascendant/latéral – puis continuation vers le bas.","also":"Aussi : miroir de Bull Flag. Le petit rebond est une pause, pas un renversement. Poursuivez le drapeau et vous achetez le pire prix – attendez la pause."},{"shape":"rectangle","name":"Rectangle (plage)","color":"#f0b429","bias":"Commerce de gamme","tip":"Le prix rebondit entre un plafond plat et un sol – une boîte latérale.","also":"Aussi : estompez les bords à l’intérieur, échangez la cassure à l’extérieur. BB squeeze se trouve généralement à l’intérieur d’un rectangle. Enseigne : discipline de niveau à niveau."},{"shape":"broadening","name":"Formation élargie","color":"#f0b429","bias":"Attention","tip":"Des hauts plus élevés ET des bas plus bas – la gamme s’étend au lieu de se pincer.","also":"Aussi : un marché chaotique et émotionnel. Les arrêts sont touchés dans les deux sens. Taille plus petite ou mise de côté ; cela se termine souvent par un mouvement violent à sens unique."},{"shape":"diamond","name":"Diamant","color":"#f0b429","bias":"Inversion","tip":"Large au milieu, étroit aux deux extrémités – une formation classique de haut/bas.","also":"Aussi : un Triangle qui se transforme puis se déforme. La direction de l'évasion décide. Rare et lent, donc la plupart des rangées ressemblent à du bruit – soyez patient."},{"shape":"island_rev","name":"Inversion des îles","color":"#ef4444","bias":"Inversion","tip":"Les écarts de prix disparaissent, se négocient dans un groupe isolé, puis reviennent – une « île ».","also":"Aussi : nécessite de réels écarts (plus courants dans les actions/FX). L'île est piégée par les acheteurs ou les vendeurs. Traitez les écarts comme un signal, pas comme des bougies insulaires."},{"shape":"breakaway_gap","name":"Écart de rupture","color":"#22c55e","bias":"Début de tendance","tip":"Un écart hors de portée ou de base – le mouvement commence avec force, pas avec une pression.","also":"Aussi : contrairement à un écart d’épuisement, il apparaît au début d’un mouvement. Les lacunes agissent souvent comme support/résistance plus tard. Enseigne : élan par rapport aux écarts de valeur."},{"shape":"v_reversal","name":"Inversion en V","color":"#22c55e","bias":"Inversion","tip":"Une chute libre brusque qui apparaît instantanément sans base – un « V ».","also":"Aussi : rapide et effrayant ; souvent axé sur l'actualité. Difficile à attraper, facile à chasser. Attendez un petit recul + bougie au lieu d'acheter le pic."},{"shape":"harmonic","name":"Modèle harmonique","color":"#f0b429","bias":"Zones d'inversion","tip":"Un zigzag mesuré (X-A-B-C-D) où chaque jambe a un rapport de Fibonacci – une carte de style « Gartley/Bat ».","also":"Aussi : avancé. Le point D est la zone d’entrée, définie par des ratios et non par des sentiments. Maîtrisez d’abord Fib simple ; c'est Fib poussé un niveau plus loin."}],"modules":[{"id":"bb","title":"1 · Bandes de Bollinger (BB)","summary":"La volatilité s’articule autour d’une moyenne mobile. Apprenez à presser, à marcher sur le bracelet, à toucher bas/haut + confirmation de bougie - la configuration de base de la pratique CPE.","lessons":[{"h":"Qu'est-ce que BB","t":"Bandes de Bollinger = SMA moyen (souvent 20) + bandes supérieure/inférieure à N écarts types (souvent 2). Les bandes s'élargissent lorsque la volatilité augmente et se resserrent lorsque le marché est calme."},{"h":"Bande médiane","t":"La ligne médiane est la moyenne. Le prix au-dessus du milieu montre souvent une pression haussière ; ci-dessous montre une pression baissière. Utilisez-le comme une ligne de biais dynamique, pas comme un achat/vente magique."},{"h":"Bande inférieure (pratique d'achat)","t":"Le fait d'étiqueter le prix dans la bande inférieure après une baisse peut signifier « étiré vers le bas ». N'achetez PAS chaque touche. Attendez l'apparition d'une bougie haussière (Hammer, Engulfing) et idéalement du RSI."},{"h":"Bande supérieure (VENTE / prudence)","t":"Le fait d’étiqueter le prix dans la bande supérieure peut signifier « étiré vers le haut ». Dans une tendance haussière, le prix peut monter dans la bande supérieure (walk-the-band). Préférez VENDRE les idées uniquement avec une bougie baissière + une faiblesse TF plus élevée."},{"h":"Presser","t":"Bandes étroites = faible volatilité → une cassure s'ensuit souvent. Ne devinez pas la direction à l’intérieur d’une pression serrée ; marquez la cassure et confirmez avec une bougie + volume si disponible."},{"h":"Promenez le groupe","t":"Dans une tendance forte, le prix épouse la bande supérieure (ou inférieure) pour de nombreuses bougies. Combattre cela avec des fondus de retour à la moyenne est une erreur courante du débutant."},{"h":"BB + Laboratoire de graphiques","t":"Dans CPE Chart Lab/bureaux, étudiez BB avec des bougies sur DEMO. Pratique : bande inférieure + Marteau → Paper Trade avec SL en dessous de la mèche, TP1 près de la bande médiane."},{"h":"Combinaison BB + RSI","t":"Filtre pratique plus fort : baisse du BB + RSI survente (ou hausse à partir de la survente) + bougie haussière. BB supérieur + RSI suracheté + bougie baissière pour un entraînement court."},{"h":"Arrêter le placement","t":"Pratique longue : SL sous le swing low / mèche bande inférieure inférieure. Pratique courte : SL au-dessus du swing haut. N'entrez jamais dans une transaction BB sans un SL écrit."},{"h":"Cibles","t":"Chemin commun : TP1 sur la bande médiane, TP2 vers la bande ou le sentier opposé. Évolutivité : vous n’avez pas besoin de tout déplacer."},{"h":"Délais","t":"Décidez du biais sur un TF plus élevé (4H/1D). Entrez sur 15m/30m BB + bougie. Le mélange de TF aléatoires provoque des signaux contradictoires."},{"h":"Les erreurs à éviter","t":"Acheter chaque contact de bande inférieure dans un marché en chute libre ; vendre chaque touche supérieure dans une course sur la lune ; pas de SL ; ignorant les pics d’actualités qui élargissent violemment les bandes."},{"h":"Liste de contrôle pratique","t":"① Biais TF plus élevé ② Toucher BB ou pause par pression ③ Confirmation de la bougie ④ RSI d'accord ⑤ % de risque défini ⑥ Papier en premier ⑦ Résultat du journal."}]},{"id":"rsi","title":"2 · RSI (indice de force relative)","summary":"Oscillateur d'impulsion 0–100. Période par défaut de 14. À utiliser avec BB et bougies – jamais RSI seul en tant que système complet.","lessons":[{"h":"Ce que mesure le RSI","t":"RSI compare les gains moyens aux pertes sur N barres. RSI élevé = dynamique haussière récente ; RSI faible = dynamique baissière récente. Ce n’est pas « surachat = il faut vendre » à chaque fois."},{"h":"Zones classiques","t":"Souvent : au dessus de 70 = zone de surachat, en dessous de 30 = zone de survente. Dans les tendances fortes, le RSI peut rester suracheté/survendu pendant longtemps – c'est normal."},{"h":"Ligne médiane 50","t":"Le passage du RSI au-dessus de 50 peut soutenir un biais haussier ; en dessous de 50 biais baissier. De nombreux traders utilisent 50 comme filtre de tendance avec la bande médiane BB."},{"h":"Divergence – haussière","t":"Le prix atteint un plus bas, le RSI fait un plus bas plus élevé → l'élan s'affaiblit à la baisse. Attendez toujours la rupture de la bougie + de la structure avant l'entrée du papier."},{"h":"Divergence – baissière","t":"Prix plus haut, RSI plus bas → l'élan à la hausse s'estompe. Confirmez avec Shooting Star / Engulfing près de la résistance ou BB supérieur."},{"h":"Balançoires d’échec","t":"RSI ne parvient pas à retester l'extrême précédent, puis repasse à 50 – indice de changement d'élan précoce. Combinez avec la structure Chart Lab."},{"h":"RSI + BB (style CPE)","t":"Pratique longue : prix proche du BB inférieur, RSI ≤ 35 (ou en hausse à partir de ≤ 30), bougie haussière. Pratique courte : BB supérieur, RSI ≥ 65–70, bougie baissière."},{"h":"Divergence cachée","t":"Indice de continuation de tendance (par exemple, prix plus bas, RSI plus bas dans la tendance haussière). Avancé : maîtrisez d'abord la divergence classique sur DEMO."},{"h":"Paramètres","t":"RSI(14) est la valeur par défaut courante. RSI plus court = plus de bruit. Ne continuez pas à modifier les paramètres pour forcer un signal."},{"h":"Sorties avec RSI","t":"Si vous avez acheté survendu, il est raisonnable de réaliser un bénéfice partiel lorsque le RSI atteint la zone médiane/supérieure. Trail le reste avec structure ou milieu BB."},{"h":"Actualités et RSI","t":"Les grandes nouvelles peuvent augmenter instantanément le RSI. Préférez attendre la fin de la première bougie violente avant d'agir sur les extrêmes du RSI."},{"h":"Erreurs","t":"Court-circuiter chaque RSI>70 dans un marché haussier ; aspirer à chaque RSI <30 lors d'un crash baissier ; pas de confluence ; rentrée de vengeance lorsque le RSI « semble meilleur »."},{"h":"Liste de contrôle pratique","t":"① Notez la valeur RSI + pente ② Vérifiez l'emplacement du BB ③ Bougie confirmez ④ TF plus élevé ⑤ Papier + journal ⑥ Une idée à la fois."}]},{"id":"fib","title":"3 · Fibonacci (retracement et extension)","summary":"Mesurez les retraits et les cibles à partir d’un swing clair haut → swing bas (ou inverse). Focus sur 38,2 · 50 · 61,8 avec confluence BB/RSI.","lessons":[{"h":"Pourquoi Fib est utilisé","t":"De nombreux traders surveillent les mêmes ratios, donc la liquidité réagit souvent à proximité d'eux. Fib est une carte des zones possibles – ce n'est pas une garantie."},{"h":"Points d'oscillation","t":"Tirez toujours d'un swing clair bas vers un swing haut (mouvement vers le haut) ou de haut vers bas (mouvement vers le bas). Mauvais swings = niveaux inutiles. Entraînez-vous à choisir des swings sur Chart Lab DEMO."},{"h":"Retracements clés","t":"Commun : 23,6 % (peu profond), 38,2 %, 50 % (pas de Fib pur mais largement utilisé), 61,8 % (doré), 78,6 % (profond). Des retraces profondes peuvent signaler une faiblesse de tendance."},{"h":"Achats de retrait (tendance haussière)","t":"Après l'impulsion haussière, attendez le retrait dans la zone 38,2–61,8 + bougie haussière + de préférence support BB moyen/inférieur ou maintien RSI > 40–45."},{"h":"Ventes de retrait (tendance à la baisse)","t":"Après une impulsion baissière, rallye vers 38,2-61,8 + bougie baissière + RSI défaillant sous 55-60."},{"h":"Extensions / cibles","t":"Extensions communes : 127,2%, 161,8% au-delà du swing pour les idées TP2. Utiliser avec trail – ne forcez pas les ticks exacts."},{"h":"Confluence = pouvoir","t":"Zones de bonnes pratiques : Fib 50/61,8 + BB milieu/inférieur + structure antérieure + virage RSI. Une seule ligne Fib est faible."},{"h":"Fibonacci + BB","t":"Si 61,8 % se situe près du BB inférieur dans une tendance haussière, ce chevauchement est une zone d'étude Paper de haute qualité. Entrez uniquement avec la confirmation d'une bougie."},{"h":"Plusieurs mensonges","t":"Les débutants devraient utiliser UN seul swing propre. L'empilement de 5 Fibs crée du bruit graphique et des entrées FOMO."},{"h":"Invalidation","t":"Si le prix clôture clairement au-delà de 78,6 % contre votre biais, la thèse du repli échoue souvent : sortez ou restez à l'écart."},{"h":"Forex contre crypto","t":"Mêmes ratios. Les majors du Forex respectent souvent les niveaux de manière plus nette lors des sessions liquides ; la crypto peut passer à travers puis inverser – taille plus petite."},{"h":"Erreurs","t":"Dessiner Fib sur de minuscules oscillations sonores ; entrer dans les airs sans bougie ; déplacer SL plus loin lorsque Fib tenait « presque » ; en ignorant le TF plus élevé."},{"h":"Liste de contrôle pratique","t":"① Mark swing ② Note 38,2/50/61,8 ③ Attendez que le prix arrive ④ Bougie + RSI/BB ⑤ Ensemble de risques ⑥ Papier → journal."}]},{"id":"money","title":"4 · Gestion de l'argent","summary":"Comment la méthode est réellement utilisée : risquez un pourcentage fixe, taille à partir du stop, encaissez une partie du profit et stop pour le lendemain d'une limite de perte. CPE peut appliquer cela aux transactions manuelles et automobiles.","lessons":[{"h":"Objectif de la gestion de l'argent","t":"Restez dans le jeu. Une mauvaise transaction ne devrait jamais effacer le compte. La cohérence surpasse le dimensionnement de la loterie."},{"h":"Comment les traders l’utilisent réellement","t":"La pratique courante est le risque fractionnaire fixe. Vous ne choisissez pas d’abord un montant de pièce. Vous écrivez d'abord le stop, décidez que cette idée peut perdre environ 1% du compte, puis la taille en diminue. Un stop large obtient une position plus petite. Un stop serré permet d'obtenir une position plus importante et le risque dollar reste à peu près le même. C'est la méthode utilisée par CPE lorsque la coche de gestion financière est activée."},{"h":"Exemple concret (compte pratique de 1 000 $)","t":"Compte 1 000 $. Risque 1% = 10$. Entrée 100, arrêt 98. Distance = 2%. Taille = 10 ÷ 0,02 = 500 $ notionnel. Si le stop est atteint, la perte est d'environ 10 $, et non 500 $. Si le prix atteint 103 (1,5 fois le risque), le gain est d'environ 15 $. Même idée sur chaque paire : les dollars à risque restent proches de 1%, la quantité de pièces change."},{"h":"Ce que fait le CPE avec la tique","t":"Trader maintenant → Auto : cochez « Utiliser la gestion de l'argent ». Enregistrez la configuration automatique. Chaque nouvelle transaction automobile utilise ensuite environ 1 % d'un compte pratique de 1 000 $ plus les résultats clôturés, dimensionnés à partir de l'entrée de ce signal et du SL. Les minimums au comptant et à terme sont respectés : si le minimum d'échange risque plus de 1%, cette transaction est ignorée. Après environ −2 % le jour calendaire, les nouvelles voitures s'arrêtent jusqu'au lendemain. Au maximum, environ 3 % sont menacés sur les transactions ouvertes. Le commerce manuel a la même coche. L'historique du signal affiche toujours le test égal à 10 $, et en dessous la taille du plan de 1 % pour un compte de 1 000 $, afin que vous puissiez voir les deux."},{"h":"Bénéfice partiel et piste","t":"La pratique consiste à prendre part à la première cible (souvent environ la moitié) et à laisser le reste suivre. Lorsque le stop monte, la cible peut également bouger, de sorte qu'un gagnant peut payer plus que la première cible. Le risque sur l’idée originale n’augmente pas. Un signal fort n’est pas une raison pour risquer 5 %. Le même 1% est utilisé. Le sentier est ce qui permet à un gagnant fort de grandir."},{"h":"Arrêt quotidien et chaleur ouverte","t":"Une règle utilisée : si la journée est en baisse d'environ 2 % du compte, arrêtez d'ouvrir des transactions. Trois idées ouvertes à 1 % chacune représentent environ 3 % de chaleur. Cinq pièces corrélées représentent un pari, pas cinq. Comptez-les ensemble."},{"h":"Ce que refuse cette méthode","t":"La martingale (doubler après une perte) n’est pas utilisée. Déplacer l'arrêt plus loin pour « lui donner de la place » après l'entrée n'est pas utilisé. Le All-in sur un signal « sûr » n’est pas utilisé. S’il n’y a pas de stop valide, il n’y a pas de taille, donc il n’y a pas d’échange."},{"h":"Risque par transaction","t":"Règle commune : ne risquez qu'environ 0,5 à 1 % des capitaux propres du compte sur une seule idée. Sur DEMO, pratiquez le même pourcentage d’habitude que LIVE."},{"h":"Formule de taille de position","t":"Taille ≈ (Compte × Risque%) ÷ (Entrée − Distance d'arrêt). SL plus large → taille plus petite. Ne choisissez jamais la taille en premier et SL en second."},{"h":"Risque : Récompense","t":"Préférez les idées où la récompense potentielle est ≥ le risque (par exemple 1:1,5 ou mieux) lors de l'apprentissage. Évoluez à TP1 pour que les coureurs soient « sans risque »."},{"h":"Take-profit partiel","t":"Style CPE : TP1 verrouille certains bénéfices, TP2 / trail pour le reste. Les partiels bancaires réduisent la panique émotionnelle."},{"h":"TP + SL de fin","t":"ACHETER : le niveau du sentier augmente à mesure que le prix augmente. VENDRE : piste en bas. Les verrous suiveurs ouvrent des bénéfices sans avoir besoin d'un appel de sortie parfait."},{"h":"Limite de perte quotidienne/hebdomadaire","t":"Exemple de règle : arrêter de trader le lendemain du compte à −2 %. Les séances de vengeance après une limite de perte tuent les comptes."},{"h":"Dimensionnement des spots","t":"Les notions minimales ponctuelles sont importantes (par exemple, les minutes d'échange). Appliquez toujours le% de risque : si la taille minimale risque trop par rapport à votre SL, ignorez l'échange."},{"h":"Contrats à terme / effet de levier","t":"L’effet de levier multiplie à la fois les profits et les pertes. Effet de levier élevé + SL large = compte grillé. Préférer un faible effet de levier pendant l’apprentissage ; L’isolement peut limiter les pertes par position."},{"h":"Corrélation","t":"Ouverture de 5 alts BTC corrélés = un gros pari, pas cinq. Comptez le risque en tant que groupe."},{"h":"Frais et dérapages","t":"Les scalps serrés semblent bons sur le graphique, mais les frais mangent R:R. Préférez des swings plus propres sur DEMO jusqu’à ce que vous connaissiez les coûts."},{"h":"DÉMO → Pont LIVE","t":"Pratique CPE DEMO (~3 mois mindset) : mêmes règles de journal, même %. En LIVE, démarrez la moitié de la taille DEMO pendant les premières semaines."},{"h":"Sécurité de l'argent de l'API","t":"Retraits désactivés sur chaque clé. En direct uniquement après avoir testé le compte OK sur la plateforme correspondante. Mauvais secret de plate-forme = opérations échouées ou dangereuses."},{"h":"Erreurs","t":"Martingale (double après perte) ; déplacer SL plus loin ; all-in sur les configurations « certaines » ; ignorer la taille minimale par rapport au % de risque ; trading sans arrêt quotidien."},{"h":"Liste de contrôle pratique","t":"① % de risque écrit ② Taille à partir de la distance SL ③ TP1/TP2/trail prévu ④ Perte journalière max connue ⑤ Papier d'abord ⑥ Journal PnL honnêtement."}]},{"id":"psych","title":"5 · Psychologie pour le trading","summary":"Mindset décide si les compétences BB/RSI/Fib survivent aux écrans réels. FOMO, vengeance, excès de confiance, peur – formez-les sur des indicateurs de type DEMO.","lessons":[{"h":"Pourquoi la psychologie est importante","t":"Un plan BB+RSI parfait échoue si vous entrez tôt, sautez SL ou vendez un échange. Compétence = système × discipline."},{"h":"Processus plutôt que prédiction","t":"Vous n’avez pas besoin de prédire l’avenir. Vous devez exécuter des règles : configuration → risque → gestion → journal. Les résultats varient ; le processus est contrôlable."},{"h":"FOMO","t":"Peur de rater quelque chose = chasser les bougies vertes déjà loin de la zone BB/Fib. Règle : si vous avez manqué l'entrée, attendez la prochaine configuration. Chart Lab a toujours une autre bougie."},{"h":"Commerce de vengeance","t":"Après une perte, l’envie de « reconquérir maintenant » détruit les comptes. Récupération obligatoire : éloignez-vous, consignez la perte, prochaine transaction uniquement si la liste de contrôle est propre."},{"h":"Excès de confiance après les victoires","t":"3 victoires consécutives ≠ augmenter la taille 5×. Gardez le pourcentage de risque fixe. Les séquences de victoires se produisent lorsque la plupart des gens enfreignent les règles financières."},{"h":"Peur après les pertes","t":"Sauter chaque configuration valide après une journée rouge est également un biais. Faites confiance au plan écrit ; réduisez temporairement la taille si nécessaire, n’abandonnez pas le processus."},{"h":"Paralysie de l'analyse","t":"10 indicateurs en désaccord → geler. Tenez-vous en au noyau CPE : bougies + BB + RSI (+ zone Fib). Qualité plutôt que quantité d'outils."},{"h":"Inclinaison et actualités","t":"De grosses bougies rouges sur les nouvelles augmentent l'adrénaline. Préférez le plat pendant les inconnues majeures jusqu'à ce que la structure se réforme - l'ego veut de l'action ; le plan veut de la patience."},{"h":"Journal = thérapie + données","t":"Écrivez des balises d'émotion (FOMO, rush, calme) dans le CPE Journal. Les modèles de sentiments révèlent des fuites plus rapidement que PnL seul."},{"h":"Règles écrites","t":"Si ce n’est pas écrit, ce n’est pas une règle. Exemple : \"Seulement BB+bougie+RSI ; risque 1 % ; aucune transaction après −2 % par jour ; DEMO jusqu'à la liste de contrôle 20 articles.\""},{"h":"Environnement","t":"Le sommeil, la faim et les distractions téléphoniques modifient les décisions. Ne mesurez pas lorsque vous êtes épuisé. Le trading est athlétique – protégez le cerveau."},{"h":"Bruit social","t":"Les « signaux » de télégramme et le battage médiatique brisent votre plan. Cours d'apprentissage CPE + votre journal > conseils aléatoires. Filtrez les actualités et astuces en fonction du contexte et non des commandes."},{"h":"Changement d'identité","t":"Pensez « Je suis ma liste de contrôle » et non « Je dois avoir raison ». Se tromper avec un petit risque est normal ; être têtu avec un risque important est facultatif."},{"h":"DÉMO comme salle de sport","t":"Utilisez DEMO/Paper pour répéter vos émotions en toute sécurité. Si vous ne pouvez pas suivre les règles sur DEMO, LIVE ne réglera pas la discipline comme par magie."},{"h":"Liste de contrôle pratique","t":"① Suis-je calme ? ② Liste de contrôle terminée ? ③ % de risque inchangé ? ④ Pas de vengeance ? ⑤ Vais-je tenir un journal honnêtement ? Le cas échéant NON → pas d’échange."}]},{"id":"signals","title":"6 · Signaux CPE — signification et que faire","summary":"Les bureaux Spot / Futures / Forex affichent ACHETER · VENDRE · CONSERVER + score. Même idée de moteur sur chaque plateforme, mais vous négociez uniquement sur la plateforme dont vous avez enregistré la clé API. Voici ce que signifie chaque signal et les étapes exactes après son apparition.","lessons":[{"h":"D'où viennent les signaux","t":"Le CPE obtient les scores BB, RSI, Fibonacci, chandelier, EMA cross, SMA50, MACD et momentum. Score ≥ +3 → ACHETER. Score ≤ −3 → VENDRE. Entre les deux → MAINTENIR. Il s’agit d’une note d’aide – pas d’une promesse de profit."},{"h":"Signal ACHETER – signification","t":"La confluence haussière est plus forte en ce moment (exemples : rebond BB inférieur, retournement de survente RSI, bougie haussière, croix dorée, support Fib). Les TP1 / TP2 / SL suggérés apparaissent sur la ligne / Chart Lab / Trade Now."},{"h":"Signal de VENTE – signification","t":"La confluence baissière est plus forte (BB supérieur / RSI suracheté / bougie baissière / croisement de la mort / résistance Fib). Sur Spot, VENDRE signifie généralement sortir/réduire une position longue ou courte uniquement si votre marché autorise les positions courtes (Futures/Forex)."},{"h":"Signal HOLD — signification","t":"Note mitigée ou faible. Ne forcez PAS un échange. Le plat est correct. Liste de surveillance ★ et attendez un ACHAT/VENTE plus clair ou un candidat BB Lower."},{"h":"Numéro de score","t":"Un |score| plus élevé = plus d'accord entre les outils. Un ACHAT +5 est plus fort qu'un ACHAT +3 – confirmez toujours sur les bougies Chart Lab avant la taille."},{"h":"Planche inférieure BB","t":"Liste séparée des paires marquant la bande inférieure de Bollinger – entraînez-vous avec des candidats longs. Il faut encore une bougie + une confirmation RSI ; chaque contact inférieur n’est pas une entrée."},{"h":"Plateforme vs signal (important)","t":"Les mathématiques du signal sont la même idée sur Binance, Bybit, OKX, KuCoin, Bitget, Gate, MEXC, Kraken, Coinbase, OANDA, FXCM, MT5, Forex Demo. Ce qui change, c'est OÙ vous envoyez la commande : uniquement la plateforme sélectionnée dans API Keys / Trade Now. Un Binance BUY ne s’ouvre pas sur Bybit."},{"h":"Plateformes Crypto Spot","t":"Binance Spot, Coinbase, etc. : ACHETER = acheter la pièce avec cotation (par exemple USDT). VENDRE = vendre des avoirs / prendre des bénéfices. La taille minimale (par exemple ~ 11 $) est importante. Aucun effet de levier."},{"h":"Plateformes Crypto Futures","t":"Binance Futures, Bybit, OKX, Bitget… : ACHETER = long ; VENDRE = court. Choisissez soigneusement Cross/Isolé + effet de levier. Trail : ACHETER les sentiers TP+SL up ; VENDRE les sentiers vers le bas."},{"h":"Plateformes de change","t":"OANDA / FXCM / MT5 / Forex Demo : mêmes labels BUY/SELL/HOLD sur les paires FX (EURUSD…). ACHETER = acheter la devise de base ; VENDRE = base de vente. Lots (par exemple 0,01) au lieu de la quantité de pièces. Les sessions et les actualités comptent davantage."},{"h":"Lorsqu'un ACHETER apparaît, faites ceci","t":"① Ouvrez la ligne → lisez Pourquoi / bougie / RSI. ② Confirmation du laboratoire graphique (15 m–1 h). ③ DÉMO d'abord : Tradez maintenant → définissez TP1/TP2/SL/trail → Démarrer la démo/le papier. ④ Seulement après le test API OK sur cette plateforme → petit LIVE. ⑤ Résultat du journal."},{"h":"Lorsqu'une VENTE apparaît, faites ceci","t":"① Si vous êtes long sur Spot : pensez à TP / clôture partielle / suivi - n'ignorez pas. ② Si Futures/Forex et le plan autorisent le short : confirmez Chart Lab puis Paper/Live short avec SL. ③ Si HOLD était meilleur hier, ne vous vengez pas de la taille du flip."},{"h":"Lorsque HOLD apparaît, faites ceci","t":"Aucune nouvelle entrée manuelle. Continuez à numériser. Ajouter une liste de surveillance ★. Classe d'apprentissage d'étude / laboratoire de graphiques. Protégez les positions ouvertes avec trail uniquement si vous êtes déjà dans une transaction."},{"h":"Commerce automatique + signal","t":"L'ACHAT automatique peut s'ouvrir lorsque les règles de score BB inférieur + fort correspondent à votre configuration automatique enregistrée. Toujours DEMO-tester Auto en premier. LIVE Auto = risque réel — Retraits OFF, petite taille."},{"h":"Notifications","t":"ACHETER Les toasts Signal suivent votre langue. Traitez-les comme des alertes pour ouvrir le bureau, et non comme des ordres de marché en eux-mêmes."},{"h":"Ce qu'il ne faut PAS faire","t":"N'achetez pas chaque ACHAT sans graphique. N'utilisez pas la clé Binance sur Bybit. Ne sautez pas SL. N’augmentez pas la taille après un signal vert. N’échangez pas HOLD comme « presque ACHETER »."},{"h":"Carte d'action rapide","t":"Signal → Chart Lab → % de risque → TP1/TP2/SL → DEMO Paper → Journal → (plus tard) LIVE sur la clé de plateforme correspondante."}]},{"id":"forex_sig","title":"7 · Signaux Forex – signification et que faire","summary":"Forex Desk utilise la même note ACHAT / VENTE / HOLD sur les paires FX. Découvrez en quoi les signaux forex diffèrent de la crypto et les étapes exactes du signal → Papier → courtier en direct.","lessons":[{"h":"Signaux du bureau Forex","t":"EURUSD, GBPUSD, USDJPY… obtenez un ACHAT / VENTE / HOLD + un score comme la crypto. Cliquez sur une ligne pour afficher le graphique, le texte de psychologie et les niveaux suggérés."},{"h":"ACHETER sur le Forex — ce qui signifie","t":"Achetez la devise de base (par exemple ACHETER EURUSD = acheter EUR contre USD). Attendez-vous à une hausse des prix. Utilisez l'intervalle Chart Lab Forex que vous pratiquez (15m/30m/1H)."},{"h":"VENDRE sur le Forex — ce qui signifie","t":"Vendez la base (vendez la paire). Attendez-vous à une baisse de prix. Placez toujours SL au-dessus de la structure/idée de bande supérieure."},{"h":"MAINTENIR sur le Forex","t":"Pas de bord clair – sautez. Surtout avant les grandes nouvelles (NFP, CPI, banque centrale), préférez HOLD/flat."},{"h":"Plateforme de taux de démonstration Forex","t":"Aucune clé API. Grilles de pratique + Papier uniquement. Parfait pour les exercices d’apprentissage en classe avant le live d’OANDA/FXCM/MT5."},{"h":"Signal OANDA → action","t":"① Bureau Forex ACHAT/VENTE. ② Confirmation du laboratoire de graphiques. ③ Clés API → Jeton OANDA + ID de compte → Test. ④ Papier DEMO en CPE en premier. ⑤ Petits lots live (mentalité 0,01) avec TP/SL/trail."},{"h":"FXCM/MT5","t":"Même lecture de signal. Connectez les informations d’identification de ce courtier sous Clés API. Signal ne se connecte pas automatiquement à MT5 pour vous jusqu'à ce que les clés/ponts soient définis - entraînez-vous sur papier jusqu'à ce que le test soit OK."},{"h":"Séances","t":"Le chevauchement entre Londres et New York déplace souvent davantage les majors. L’Asie est peut-être plus calme – HOLD est courant et sain."},{"h":"Diffusion et actualités","t":"Autour de l’actualité, les spreads s’élargissent – un bon ACHAT technique peut toujours être un mauvais remplissage. Consultez les actualités et astuces ; attendez la fermeture de la bougie après le pic."},{"h":"Quantité de lots vs crypto","t":"Taille Forex = lots, pas notionnel USDT de la même manière. Le % de risque règne toujours : SL plus large → lots plus petits."},{"h":"BB en baisse sur le Forex","t":"Même idée : paire proche de la bande inférieure + Marteau + RSI en hausse = pratique d'étude longue. Confirmez un biais TF plus élevé (4H/quotidien)."},{"h":"Lorsque Forex BUY se déclenche – étapes","t":"① Lisez Pourquoi. ② Biais TF plus élevé, OK ? ③ Mark SL au-delà de la mèche/structure. ④ Commerce du papier. ⑤ Si le courtier en direct est prêt → petite taille + piste. ⑥ Séance de journal (Londres/NY) + émotion."},{"h":"Lorsque Forex SELL se déclenche – étapes","t":"① Confirmez qu'il ne s'agit pas d'un pic d'actualité. ② Bougie baissière Chart Lab. ③ Papier court ou fermé long. ④ Traînée vers le bas si courte. ⑤ Ne doublez pas le lot après un échec."},{"h":"Différence Forex vs crypto","t":"Cryptographie 24h/24 et 7j/7 ; Le Forex a des sessions. Crypto min $ souvent ; Lots Forex + valeur pip. Crypto de nombreux alts corrélés ; Nettoyant pour les majors du Forex pour l'apprentissage."},{"h":"Liste de contrôle pratique (FX)","t":"① Paire majeure ? ② Séance OK ? ③ Les nouvelles sont claires ? ④ Le signal ACHETER/VENDRE ne tient pas ? ⑤ Le graphique confirme-t-il ? ⑥ % de risque ? ⑦ Papier → journal → clé de courtier en direct uniquement lorsque vous êtes prêt."}]},{"id":"fomo","title":"8 · FOMO et discipline émotionnelle","summary":"FOMO, la vengeance, la cupidité et la peur sont les véritables tueurs de comptes – et non des indicateurs. Apprenez les déclencheurs, les signes corporels et les règles exactes qui empêchent les transactions impulsives d'accéder à votre compte.","lessons":[{"h":"Qu'est-ce que FOMO est vraiment","t":"FOMO = la peur de rater un coup déjà loin de votre zone. Cela vous fait entrer tard avec un prix pire et pas de SL approprié. La bougie que vous avez « manquée » est une information, pas une perte."},{"h":"Les trois déclencheurs FOMO","t":"① Une grosse bougie verte ou rouge sur le graphique. ② Une publication d'un ami ou d'un Telegram montrant un bénéfice. ③ Un titre d'actualité. Remarquez le déclencheur avant de remarquer l'entrée."},{"h":"Signes corporels","t":"Battement de cœur rapide, penché vers l'écran, envie de cliquer sur le marché-acheter-maintenant, sautant votre liste de contrôle. Si vous les ressentez, fermez la languette et attendez une bougie."},{"h":"La règle du « déjà exécuté »","t":"Si le prix a évolué de plus d'environ 1 ATR au-delà de votre entrée prévue, la transaction est terminée. Attendez un retrait vers BB mid / Fib ou ignorez-le. Il y a toujours une autre configuration."},{"h":"Le piège à bougie verte","t":"Un Marubozu que vous n’avez pas prévu est une poursuite, pas une entrée. Les entrées tardives ont la pire récompense : le risque, car l'arrêt se termine loin."},{"h":"Commerce de vengeance","t":"Après une perte, le cerveau veut maintenant la reconquérir. Règle : aucune nouvelle entrée pendant 15 à 30 minutes après une défaite, et seulement si la liste de contrôle est vierge. Le marché ne vous doit rien."},{"h":"Peur d'appuyer sur la gâchette","t":"Problème inverse : un setup parfait apparaît et vous vous figez. Utilisez une petite taille DEMO pour prouver le processus et décidez de votre taille AVANT que la bougie n'apparaisse afin que la décision soit déjà prise."},{"h":"La cupidité après les victoires","t":"Deux métiers verts vous font vous sentir invincible, puis vous doublez votre taille. Maintenez le pourcentage de risque fixe pour au moins 20 transactions ; séquences de victoires avec retour à la moyenne."},{"h":"Commerce d'ennui","t":"L'appartement est une position. Si aucune configuration A+ n’existe, ne faites rien se produire. Les métiers de l’ennui sont des FOMO déguisés."},{"h":"Discipline du temps passé devant un écran","t":"Définissez deux ou trois fenêtres d'analyse par jour au lieu de regarder les graphiques. Moins de décisions signifie moins de décisions impulsives."},{"h":"Journal émotionnel","t":"Marquez chaque échange calme/précipité/FOMO/vengeance. Après 20 transactions, la tendance de vos fuites devient évidente."},{"h":"Rituel de réinitialisation","t":"Après une perte ou un dérapage FOMO : levez-vous, prenez 10 respirations lentes, écrivez une phrase sur ce qui s'est passé, puis arrêtez-vous pendant une heure ou continuez avec la moitié du risque normal."},{"h":"Liste de contrôle pratique","t":"① Corps calme ? ② Déclencheur remarqué ? ③ Installation dans ma zone ? ④ SL écrit en premier ? ⑤ % de risque inchangé ? ⑥ Pas de vengeance ? Tout NON → pas d'échange."}]},{"id":"risk_deep","title":"9 · Gestion des risques et de l'argent — approfondie","summary":"Les calculs qui maintiennent un compte en vie : dimensionnement fractionnaire fixe, R-multiples, calculs de réduction, chaleur de corrélation et stop quotidien. Transformez le trading en une entreprise gérée par des chiffres.","lessons":[{"h":"Risque fractionnaire fixe","t":"Risquez un pourcentage fixe (0,5 à 1 %) de capitaux propres par idée. La taille est le RÉSULTAT de la distance d’arrêt, jamais choisie en premier. Large SL → petite taille ; SL serré → taille plus grande ; le risque dollar reste le même."},{"h":"La formule de dimensionnement","t":"Taille = (Actions × Risque%) ÷ |Entrée − Arrêt|. Exemple : 1 000 $ × 1 % = 10 $ de risque. Entrée 100, arrêt 98 → distance 2 % → taille 10 ÷ 0,02 = 500 $ notionnel."},{"h":"Pensez en R-multiples","t":"Risque 1R par transaction. Un gagnant 2R paie pour deux pertes. Suivez votre R moyen sur 20 transactions : c'est votre véritable avantage, pas le taux de réussite."},{"h":"Récompense : risque","t":"Visez au moins 1,5R de potentiel avant d’entrer. En dessous, ignorez-le à moins que votre taux de victoire ne soit très élevé."},{"h":"Mathématiques du retrait","t":"Un retrait de -50 % a besoin de +100 % pour récupérer. Les séquences de défaites sont normales : même un système de taux de victoire de 60 % comporte des séries de 5+ défaites. Un petit risque permet à la séquence de survivre."},{"h":"L'arrêt quotidien","t":"Règle stricte : arrêtez d'ouvrir des transactions après −2 % des capitaux propres en une journée (ou 2 à 3 pertes consécutives). Les séances de vengeance après la limite tuent les comptes."},{"h":"Limites hebdomadaires et mensuelles","t":"Plafonnez également la semaine (par exemple −5 %) et le mois. Lorsque vous appuyez dessus, passez à DEMO, examinez le journal, puis redimensionnez-le seulement après une exécution propre."},{"h":"Chaleur ouverte","t":"Le risque total sur toutes les transactions ouvertes devrait rester autour de 3 % ou moins. Cinq alts corrélés représentent un pari, pas cinq – comptez l'exposition corrélée ensemble."},{"h":"Dimensionnement des spots","t":"Spot a un notionnel minimum. Si le minimum d'échange risque plus que votre 1%, sautez la transaction - n'arrondissez jamais le risque à l'augmentation."},{"h":"Dimensionnement des contrats à terme","t":"L’effet de levier modifie la marge, pas le risque. Le risque est toujours Entry - Stop × taille. Utilisez un faible effet de levier pendant l’apprentissage et préférez une marge isolée."},{"h":"Dimensionnement du Forex","t":"Risque = lots × valeur du pip × stop-pips. Résolvez des lots. Indice approximatif : 0,01 lot ≈ 0,10 $ par pip ; un stop de 20 pips risquant 1 % de 1 000 $ (10 $) → 10 ÷ 0,10 ÷ 20 = 0,05 lots."},{"h":"Mise à l'échelle","t":"Prenez environ 50 % de réduction chez TP1 pour que le reste soit sans risque, puis suivez. Cela transforme un bon trade en un coureur à faible stress."},{"h":"Composition vs fixe","t":"Risquez un % fixe des capitaux propres ACTUELS (composant). Ne fixez pas votre risque à la taille de compte la plus élevée de tous les temps."},{"h":"Frais et dérapages en R","t":"Soustrayez les frais de R. Des frais de 0,2 % contre un scalp de 0,5 % peuvent effacer le bord – préférez des swings plus propres."},{"h":"La loi « no stop, no trade »","t":"Si vous ne pouvez pas définir un stop logique, vous ne connaissez pas votre risque, donc il n'y a pas de taille, donc il n'y a pas de transaction."},{"h":"Anti-martingale","t":"Ne doublez jamais après une défaite. N'augmentez la taille qu'après plusieurs semaines rentables et disciplinées d'un processus éprouvé - et même lentement."},{"h":"Liste de contrôle pratique","t":"① Actions connues ② % de risque écrit ③ Stop défini ④ Taille à partir du stop ⑤ Récompense ≥ 1,5R ⑥ Stop quotidien connu ⑦ Chaleur corrélée comptée."}]},{"id":"sl_tp","title":"10 · Maîtrise du Stop Loss et du Take Profit","summary":"Placez le SL là où le marché vous prouve le contraire, réalisez des bénéfices par étapes et suivez le stop pour qu'un gagnant puisse courir – exactement ce que fait le CPE avec le multi-TP et un SL suiveur.","lessons":[{"h":"SL est une décision, pas un numéro","t":"Placez le stop là où l'idée est invalidée (sous le swing bas, la mèche ou la structure), et non à une distance aléatoire en dollars. Vous achetez des informations : si le prix va ici, ma raison est fausse."},{"h":"La structure s'arrête","t":"Long : SL juste en dessous de la mèche swing low ou de la bande inférieure. Court : juste au-dessus du swing high. Donnez un petit tampon pour le bruit de propagation et de mèche, environ 0,1 à 0,3 %."},{"h":"La volatilité s'arrête","t":"Des marchés plus larges nécessitent des arrêts plus larges. Utilisez l'ATR ou la longueur de la mèche pour dimensionner le stop, puis réduisez la position pour que le risque monétaire reste le même."},{"h":"Pourquoi un SL à dollar fixe échoue","t":"Un stop de 10 $ sur BTC et un stop de 10 $ sur EURUSD représentent un risque complètement différent. La distance doit être mesurée en %, et non en dollars."},{"h":"Tampon anti stop-chasse","t":"Le CPE ignore un seul contact de mèche : il a besoin de deux brèches consécutives plus un petit tampon (0,15 %) avant de fermer. Cela empêche le bruit de rechercher votre arrêt."},{"h":"Réalisez des bénéfices par étapes","t":"Ne fermez jamais à 100 % à un seul prix. Évolutivité : TP1 livre une partie, puis TP2 / trail parcourt le reste, donc un gros mouvement peut payer pour de nombreux perdants."},{"h":"Niveaux multi-TP","t":"CPE vous permet d'ajouter autant de niveaux TP que nécessaire, chacun avec son propre % de clôture. Exemple : TP1 40 %, TP2 30 %, TP3 30 % — ou prenez TP1 et suivez le reste."},{"h":"Suivre l'arrêt","t":"Après TP1, déplacez le stop au seuil de rentabilité ; après TP2, déplacez-le vers TP1. Laissez le stop suivre le prix afin que le profit ouvert soit protégé pendant que le coureur continue."},{"h":"Choisir le sentier %","t":"Une piste étroite permet de réaliser des bénéfices rapidement mais sort tôt ; un large sentier respire mais en rend. Commencez autour de 1 à 2 % pour la cryptographie et réglez-la dans le modal d'édition des positions."},{"h":"Coureurs","t":"Lorsque le prix parcourt la bande dans une tendance forte, élargissez la cible et la piste au lieu de tout prendre au TP2. C'est ainsi qu'un échange paie pendant une semaine entière."},{"h":"Boutons de fermeture partielle","t":"Utilisez les boutons de fermeture 50 %/100 % dans Positions pour un contrôle manuel, ou laissez la fermeture automatique gérer TP/SL selon le plan."},{"h":"Le piège du seuil de rentabilité","t":"Ne déplacez pas le SL vers le seuil de rentabilité trop tôt, avant TP1 – les retraits normaux vous élimineront de bonnes transactions."},{"h":"Ne jamais élargir un stop perdant","t":"En éloignant le SL pour lui donner de la place, les petites pertes deviennent des tueurs de comptes. L'arrêt que vous définissez avant l'entrée est l'arrêt."},{"h":"Le temps s'arrête","t":"Si une transaction ne fait rien pendant de nombreuses bougies alors qu'une configuration nettement meilleure se forme, clôturer à plat et redéployer le risque est une sortie valable."},{"h":"Liste de contrôle pratique","t":"① SL à l'invalidation, pas aléatoire ② Tampon pour mèches ③ TP1 partiel prévu ④ Trail après TP1 ⑤ Ne jamais élargir le SL ⑥ Laisser courir un gagnant."}]},{"id":"plan_journal","title":"11 · Plan commercial et journalisation","summary":"Un plan écrit transforme le trading du jeu en un processus. Découvrez le plan d'une page, la liste de contrôle pré-négociation et comment tenir un journal pour que vos fuites deviennent visibles.","lessons":[{"h":"Pourquoi rédiger un plan","t":"Si ce n’est pas écrit, ce n’est pas une règle. Un plan supprime la prise de décision en direct sous le stress et rend vos résultats mesurables."},{"h":"Le plan d'une page","t":"Paire, marché, configuration (BB + RSI + bougie + zone Fib), direction, entrée, SL, TP1 / TP2, taille (à partir du SL) et perte quotidienne maximale. Si une ligne est vide → pas d'échange."},{"h":"Liste de contrôle pré-négociation","t":"Biais TF plus élevé ? · Installation dans ma zone ? · Bougie confirmer ? · RSI d'accord ? · SL écrit ? · Risque %? · Récompense ≥ 1,5R ? · Calme? Tout oui → commerce."},{"h":"Routine de pré-séance","t":"Vérifiez le calendrier supérieur, les niveaux clés et les actualités. Écrivez les deux ou trois paires de montres d’aujourd’hui avant la séance – pas après l’explosion de la bougie."},{"h":"Quoi journaliser","t":"Symbole, côté, entrée, sortie, taille, R, raison, délai, session et étiquette d'émotion. CPE Journal enregistre automatiquement le P/L et les raisons ; ajoutez vos propres notes."},{"h":"Notez le POURQUOI","t":"Enregistrez ce que vous avez vu (installation) et ce que vous avez ressenti (calme/FOMO/précipité). Un résultat sans contexte n’apprend rien."},{"h":"Track R, pas de victoires","t":"Deux traders avec le même taux de réussite peuvent avoir des résultats opposés. Le R moyen et le retrait maximum comptent plus que le % de gain."},{"h":"Habitude de capture d'écran","t":"Enregistrez le graphique avant et après chaque transaction. L'examen de 20 captures d'écran montre votre avantage et vos fuites plus rapidement que n'importe quel indicateur."},{"h":"Revue hebdomadaire","t":"Une fois par semaine, comptez vos transactions, votre R moyen, la meilleure et la pire configuration et les violations des règles. Choisissez UNE fuite à réparer la semaine prochaine."},{"h":"Marquez les fuites","t":"Tags courants : entrée tardive, pas de SL, surdimensionné, SL déplacé, vengeance, ennui. Lorsqu’une balise se répète, transformez-la en règle stricte."},{"h":"Ce qu'il ne faut pas enregistrer","t":"Ne connectez pas uniquement les gagnants. Les pertes sont les données. Un journal des seules victoires est une brochure, pas un journal."},{"h":"Planifier l'étape DEMO → LIVE","t":"Prouvez le plan sur DEMO pour un nombre défini de transactions avec un R moyen positif avant de risquer de l'argent réel - puis commencez à moitié."},{"h":"Liste de contrôle pratique","t":"① Plan rédigé avant l'entrée ② Liste de contrôle réussie ③ Entrée de journal + émotion ④ Bilan hebdomadaire ⑤ Une fuite corrigée."}]},{"id":"leverage","title":"12 · Effet de levier, marge et liquidation","summary":"L’effet de levier multiplie les pertes aussi vite que les profits. Apprenez la marge, la liquidation, la marge isolée ou croisée et les règles de sécurité qui empêchent une transaction d'effacer le compte.","lessons":[{"h":"Quel est l'effet de levier","t":"L'effet de levier vous permet de contrôler une position plus grande avec moins de marge. Cela augmente à la fois les profits et les pertes – cela n’augmente pas votre avantage."},{"h":"Marge vs risque","t":"La marge est le dépôt que l'échange verrouille. Le risque est l'entrée - Stop × taille. Tirez parti de la marge des changements, sans jamais prendre de risque financier."},{"h":"Liquidation","t":"Si les pertes rongent votre marge, la bourse ferme la position (liquidation), souvent au pire moment. Gardez votre stop loin du prix de liquidation."},{"h":"Isolé ou croisé","t":"Isolé plafonne la perte à la marge de cette position. Cross utilise tout le solde du portefeuille, ce qui est plus dangereux pour les débutants. Préférez l’isolement pendant l’apprentissage."},{"h":"Un effet de levier plus sûr","t":"Un faible effet de levier (2 à 5x) plus un stop approprié sont bien plus sûrs que 50x sans stop. Le stop, et non le numéro de levier, est votre protection."},{"h":"La règle de la distance de liquidation","t":"Vérifiez que votre SL se situe bien dans le prix de liquidation. S'ils sont proches, réduisez la taille jusqu'à ce qu'il y ait un espace confortable."},{"h":"L’effet de levier ne résout pas une mauvaise entrée","t":"Un effet de levier élevé sur une mauvaise entrée perd tout simplement plus rapidement. Corrigez d'abord la configuration, puis dimensionnez-la."},{"h":"Financement et frais","t":"Les contrats à terme perpétuels facturent un financement au fil du temps. Les longues rétentions sur les financements à effet de levier des pers saignent – ​​une autre raison de dimensionner et de planifier avec soin."},{"h":"Spot vs Futures","t":"Le spot ne peut pas être liquidé (vous possédez la pièce). Les contrats à terme le peuvent et peuvent atteindre zéro. Utilisez les contrats à terme uniquement avec un plan écrit et une marge isolée."},{"h":"Dimensionnement sous effet de levier","t":"Calculez la taille à partir de la distance d'arrêt, puis vérifiez que la marge résultante est abordable. Ne choisissez jamais l’effet de levier en premier."},{"h":"Le test du « one trade »","t":"Avant d’entrer, demandez-vous : si cela s’arrête, est-ce un haussement d’épaules ou un désastre ? Si ce n’est pas un haussement d’épaules, la taille est trop grande."},{"h":"Liste de contrôle pratique","t":"① Ensemble isolé ② Faible effet de levier ③ SL à l'intérieur du prix de liquidation ④ Taille à partir du stop ⑤ Puis-je survivre à une perte totale ici ? oui → commerce."}]},{"id":"practice","title":"13 · Pratiquez la routine et le backtesting","summary":"La compétence est construite sur DEMO avant LIVE. Apprenez une boucle d'entraînement reproductible, comment effectuer un backtest en faisant défiler des graphiques et comment passer à l'argent réel en toute sécurité.","lessons":[{"h":"DEMO est la salle de sport","t":"Paper / DEMO existe pour répéter le processus et vos émotions sans risque. Si vous ne pouvez pas suivre les règles de DEMO, LIVE ne résoudra pas le problème comme par magie."},{"h":"La boucle de pratique","t":"Choisissez une configuration (par exemple BB inférieur + Marteau + Tour RSI). Marquez 20 exemples historiques sur le tableau. Définir l'entrée / SL / TP. Enregistrez le résultat. Répéter."},{"h":"Backtest manuel","t":"Revenez en arrière dans Chart Lab, cachez le futur et marquez chaque signal à la main. Il entraîne la reconnaissance des formes et vous empêche de vous tromper."},{"h":"Taille de l'échantillon","t":"Dix échanges ne veulent rien dire. Visez 30 à 50 transactions enregistrées d'une configuration avant de la juger."},{"h":"Test avancé sur DEMO","t":"Après le marquage manuel, exécutez la même configuration en direct sur DEMO avec les signaux du logiciel pendant deux à quatre semaines. Comparez les remplissages et les émotions réels au backtest."},{"h":"Une configuration à la fois","t":"Ne testez pas cinq systèmes à la fois. Maîtrisez un bord, puis ajoutez-en un second."},{"h":"Gardez la routine petite","t":"Une routine quotidienne de 20 minutes (scan, correction, journal, révision) vaut six heures d'observation aléatoire des graphiques."},{"h":"Passer au LIVE","t":"Critères : R moyen positif sur plus de 30 transactions DEMO, règles suivies, pas d'épisodes de vengeance. Ensuite, démarrez LIVE à moitié et évoluez lentement."},{"h":"Règle de mise à l'échelle","t":"N’augmentez la taille qu’après un nombre défini de semaines rentables et disciplinées – jamais après une seule grosse victoire."},{"h":"Quand prendre du recul","t":"Atteignez la limite de perte quotidienne ou hebdomadaire, ou remarquez des violations répétées des règles → revenez à DEMO et reconstruisez la discipline avant de continuer."},{"h":"Suivre les métriques du processus","t":"Enregistrez le taux de réussite de la liste de contrôle, les violations des règles par semaine et le R moyen. Ceux-ci prédisent mieux la croissance qu'un seul chiffre P/L."},{"h":"Parcours de pratique CPE","t":"Classe d'apprentissage → Chart Lab (configurations de marques) → Paper Trade → Revue de journaux → Signal desks sur DEMO → petit LIVE sur la clé de plate-forme correspondante."},{"h":"Liste de contrôle pratique","t":"① Une configuration choisie ② 30 exemples marqués ③ Test avancé DEMO ④ Journal + revue ⑤ R positif → demi-taille LIVE."}]},{"id":"volatility","title":"14 · Volatilité & Martingale","summary":"Comment lire la volatilité du marché (pourquoi le prix change), comment elle est ajoutée à chaque signal comme ligne de raison et comment fonctionne l'échelle Martingale optionnelle - et pourquoi c'est le moyen le plus rapide de perdre un compte lorsqu'elle est utilisée avec négligence.","lessons":[{"h":"Ce que signifie la volatilité","t":"La volatilité est la mesure dans laquelle le prix évolue, et non le sens. Forte volatilité = bougies larges et fluctuations rapides. Faible volatilité = une fourchette calme et étroite. La même configuration a une fiabilité très différente dans chacun."},{"h":"La lecture de la volatilité du CPE","t":"Chaque signal mesure désormais la plage moyenne des bougies et la largeur de la bande de Bollinger, puis les compare à la normale récente de cette paire. Vous obtenez FAIBLE / NORMAL / ÉLEVÉ / EXTRÊME plus une ligne de raison en langage clair – le « pourquoi » du changement du marché, affiché avec le signal."},{"h":"Volatilité EXTRÊME = déclassement","t":"Lorsque la bande est EXTRÊME, un nouveau signal FORT est rétrogradé à ATTENTION (la raison est indiquée). Sur le marché des scies à fouet, le même schéma échoue beaucoup plus souvent : les fausses coupures et les mèches stop-hunting sont la norme."},{"h":"Que faire en HAUT/EXTREME","t":"Taille plus petite. Arrêt plus large. Moins de métiers. Attendez une bougie terminée au lieu d'une pointe à mi-bougie. Si la lecture indique EXTREME, traitez la configuration comme une zone d'étude et non comme une entrée."},{"h":"Qu'est-ce que la martingale","t":"La martingale s'ajoute à une position perdante pour faire baisser l'entrée moyenne : après chaque coup adverse vous ajoutez un autre ordre, généralement plus gros (1x, 2x, 4x…). Il gagne souvent, puis perd tout en un seul mauvais run."},{"h":"La règle CPE Martingale","t":"CPE ajoute un ordre supplémentaire uniquement lorsque les DEUX sont vrais : (1) le prix a évolué à l'encontre de la transaction d'au moins pas × échelon %, et (2) un nouveau signal du même côté représente toujours cette paire. Cela n’ajoute jamais simplement parce que le prix a baissé."},{"h":"Les quatre nombres","t":"Pas % = mouvement adverse nécessaire avant chaque ajout. Multiplicateur = taille de chaque ajout par rapport à la base (1 = plat, 2 = double). Max ajoute = limite stricte sur les commandes supplémentaires. % du plafond de risque du Ladder = le risque de l’ensemble du Ladder en % des capitaux propres. Vous avez le choix entre les quatre."},{"h":"La casquette rigide vous protège","t":"Même avec un multiplicateur important et de nombreux ajouts, le CPE refuse l’ordre une fois que le risque total de l’échelle dépasse votre plafond % des capitaux propres. Il respecte également la taille minimale d'échange et le stop quotidien de −2%."},{"h":"Où ça court","t":"Cochez-le sur Manuel pour gérer cette transaction, ou sur une session Auto pour gérer ses transactions automatiques. À la fois DÉMO et LIVE. En manuel, la paire doit être dans la liste de balayage afin qu'un nouveau signal du même côté puisse être lu."},{"h":"Pourquoi le plafond est important (exemple)","t":"Étape 1 %, multiplicateur 2, trois ajouts sur une base de risque de 1 % : le risque va de 1 % → 2 % → 4 % → 8 %. Un arrêt complet sur le dernier échelon efface de nombreux gagnants. C'est pourquoi le plafond existe et pourquoi les chiffres par défaut sont petits."},{"h":"Alternative anti-martingale","t":"De nombreux pros font le contraire : n’ajoutent que les gagnants et éliminent rapidement les perdants. C'est pire (plus de petites pertes) mais cela ne peut pas faire exploser le compte en une seule tendance contre vous."},{"h":"Le risque n’est pas supprimé","t":"La réduction de la moyenne ne supprime pas le risque : elle fait passer le risque de « plusieurs petites pertes » à « une seule grande perte ». N'ajoutez jamais d'argent que vous ne pouvez pas perdre et ne désactivez jamais le plafond pour « récupérer » une transaction perdante."},{"h":"Parcours de pratique","t":"Apprenez d’abord la lecture de la volatilité sur DEMO. Essayez Martingale avec un maximum d'ajouts de 1 à 2 et un petit multiplicateur sur DEMO pour plus de 30 transactions. Journalisez chaque échelle, puis décidez – la plupart des traders trouvent la méthode plate/anti-martingale plus sûre."},{"h":"Liste de contrôle Volatilité + Martingale","t":"① Lisez d'abord le niveau de volatilité ② Sauter ou réduire en EXTREME ③ Martingale uniquement avec un nouveau signal du même côté ④ Étape × échelon atteint ⑤ Sous le plafond de risque → ajouter. Tout « non » → aucun ajout."}]},{"id":"lab_indicators","title":"15 · Indicateurs de laboratoire graphique (Stoch · ADX · Ichimoku · VWAP)","summary":"Chart Lab dispose désormais d'une barre d'indicateurs complète : chaque bouton est une coche marche/arrêt qui redessine le graphique instantanément. Outre BB / RSI / MACD / EMA / SMA50 / Volume, vous obtenez désormais Stochastic, ADX/DMI, Ichimoku et VWAP, et le moteur de signaux les lit également – ​​pas seulement le graphique.","lessons":[{"h":"Où est le bar","t":"Chart Lab → la rangée de boutons « Indicateurs » sous le graphique. Un clic allume un indicateur, le clic suivant l'éteint ; le graphique se redessine immédiatement. Les ticks sont visuels ET ils alimentent le moteur de signaux."},{"h":"Stochastique (14,3,3)","t":"Oscillateur %K / %D dessiné sous les bougies, échelle 0–100. Au-dessus de ~80 = zone de surachat, en dessous de ~20 = zone de survente. %K passant par %D dans la zone de survente est une étude haussière ; une croix vers le haut est baissière. Dans une tendance forte, il peut rester coincé à une extrémité pendant longtemps – combinez-le toujours avec BB et la bougie."},{"h":"ADX/DMI (14)","t":"ADX mesure la FORCE de la tendance, pas la direction. Au-dessus de ~25 = une véritable tendance est en cours ; en dessous de ~20 = une plage instable. +DI au-dessus −DI = acheteurs en charge ; −DI au-dessus +DI = vendeurs en charge. Utilisez ADX pour décider si vous souhaitez suivre une tendance ou rester stable."},{"h":"Nuage Ichimoku (9,26,52)","t":"Tenkan (ligne rapide), Kijun (ligne lente) et le nuage Senkou. Prix ​​au-dessus d'un nuage ascendant = contexte haussier ; en dessous d'un nuage qui tombe = baissier. Un croisement Tenkan/Kijun à l’intérieur du nuage est faible ; un croisement avec un prix quittant le cloud est plus fort. Le bord du cloud lui-même fait souvent office de support/résistance."},{"h":"VWAP","t":"Prix moyen pondéré en fonction du volume – le prix moyen pondéré en fonction du volume, réinitialisé à chaque session. Les grandes institutions y comparent leurs remplissages. Prix ​​supérieur à un VWAP en hausse = acheteurs aux commandes ; un rejet net chez VWAP pendant une tendance baissière est une courte étude. Sur la cryptographie 24h/24 et 7j/7, la réinitialisation est différente de celle sur FX : traitez-la comme une ligne directrice, pas comme une loi."},{"h":"Comment le moteur les utilise","t":"Chaque nouvel indicateur ajoute une petite confirmation au score du même côté qu'il pointe (Stochastic, Ichimoku, VWAP, ADX lorsqu'il est en accord avec la direction, et Elliott). Ce sont des confirmations, pas des déclencheurs – s’ils ne sont pas d’accord avec BB/RSI/la bougie, le score devient simplement plus mitigé et vous obtenez plus de HOLD."},{"h":"Pourquoi la prudence est devenue plus stricte","t":"Parce qu'il y a désormais plus de checks dans la poule, la barre de ATTENTION a été renforcée : il faut un score ≥ 4 ET au moins 3 checks concordants. Cela empêche l'application de vous inonder de signaux plus faibles simplement parce que davantage d'outils sont activés."},{"h":"Un ordre de lecture qui fonctionne","t":"① Direction TF supérieure (nuage Ichimoku + ADX). ② Où se trouve le prix (BB / Fib / VWAP). ③ Momentum (RSI + Stochastique). ④ Confirmation de bougie. ⑤ % de risque et niveaux écrits → Papier d'abord."},{"h":"Les erreurs à éviter","t":"Allumer tous les indicateurs et regarder un arc-en-ciel ; utiliser ADX comme direction (ce n'est que de la force) ; vente à découvert uniquement parce que le stochastique est> 80 dans une course haussière ; ignorant que VWAP signifie des choses différentes sur la cryptographie et sur le FX."},{"h":"Liste de contrôle pratique","t":"① Biais du cloud + ADX ② Localisation depuis BB / Fib / VWAP ③ Momentum depuis RSI + Stoch ④ Bougie confirmée ⑤ SL / TP écrit ⑥ Papier, puis journal."}]},{"id":"elliott","title":"16 · Elliott Wave (compte de lumière)","summary":"Le CPE comprend un compteur léger Elliott Wave. Cochez « Elliott » dans la barre indicatrice de Chart Lab et il marque la dernière impulsion 0-1-2-3-4-5 sur les bougies et projette une cible de Fibonacci de vague 5. Il s’agit d’un outil d’étude, pas d’une boule de cristal.","lessons":[{"h":"L'idée en une ligne","t":"Les marchés évoluent par vagues : impulsions (5 jambes dans la direction de la tendance) et corrections (3 jambes contre elle). Le CPE ne compte que l'impulsion, qui est la partie qui porte la tendance."},{"h":"Comment le CPE le compte","t":"Il trouve les derniers pivots de swing (fractales à 3 barres), alterne haut/bas et teste les 5 à 6 derniers swings par rapport aux règles d'Elliott. Si la forme correspond, elle dessine les étiquettes 0 → 5 (la vague toujours en cours en jaune) et une ligne cible W5 construite à partir de la longueur de la vague 1 × 1,618 mesurée sur la vague 4."},{"h":"Les règles qu'il vérifie","t":"La vague 2 ne dépasse pas le début de la vague 1 ; la vague 4 ne chevauche pas le territoire de la vague 1 ; la vague 3 n'est pas la plus courte de 1/3/5. Lorsqu'une règle échoue, elle n'affiche rien – pas de décompte forcé."},{"h":"Haussier ou baissier","t":"Une hausse de 0-1-2-3-4-5 est une impulsion haussière ; l'image miroir à la baisse est baissière. Le moteur ajoute une petite confirmation au score du côté de la vague."},{"h":"En direct ou complet","t":"Une vague 5 LIVE (toujours en cours) se lit comme une continuation de la tendance. Une impulsion COMPLÈTE (0 à 5 terminé) avertit que la tendance peut être fatigante — une correction s'ensuit souvent."},{"h":"La ligne cible du W5","t":"Une extension de Fibonacci de la vague 1 à partir de la vague 4 bas/haut. Il s’agit d’une idée cible, pas d’un aimant : le prix peut s’arrêter avant ou le dépasser."},{"h":"Comment l'utiliser","t":"Traitez le décompte comme une confluence : dans une zone BB/Fib claire avec une bougie et un RSI, un décompte impulsif ajoute de la conviction. À lui seul, ce n’est qu’une esquisse."},{"h":"Les erreurs à éviter","t":"Recompter les vagues jusqu'à ce qu'elles correspondent à votre position (le péché classique d'Elliott) ; compter les petits mouvements; ignorer le nombre de délais plus élevés ; oublier que le décompte change à chaque fois qu'une nouvelle barre s'imprime."},{"h":"Liste de contrôle pratique","t":"① Swings clairs choisis ② Passage des règles ③ Zig-zag est d'accord avec BB / Fib ④ Bougie confirmée ⑤ SL au-delà du point d'invalidation de la vague 4."}]},{"id":"forecast","title":"17 · Prévisions sur 3 mois (la coche Forecast 3M)","summary":"Le projecteur à long horizon : comment ce graphique est susceptible de se former au cours des 3 prochains mois, construit à partir de la tendance, des objectifs et de la volatilité du signal. Activez-le ou désactivez-le avec la coche « Forecast 3M » dans Chart Lab.","lessons":[{"h":"Ce qu'il dessine","t":"Un chemin central en pointillé allant de l'entrée analysée vers la meilleure cible que le moteur connaît déjà (cible Elliott → tp2 → tp1), enveloppé dans un « cône » élargi qui montre l'écart des prix plausibles. Les marqueurs mensuels M+1 / M+2 / M+3 divisent l'horizon."},{"h":"Pourquoi un cône et pas une ligne","t":"Personne ne peut connaître le prix futur exact. Le cône s’élargit avec la racine carrée du temps et la propre volatilité de la paire, de sorte qu’une paire de devises calme obtient un cône étroit et un altcoin sauvage un cône très large. Cette largeur EST le message : plus vous regardez loin, moins le prix est certain."},{"h":"D'où viennent les chiffres","t":"La dérive provient de la cible actuelle du signal ; la volatilité quotidienne provient du % ATR du signal mis à l'échelle sur un jour, donc le cône a la même signification sur un graphique à 5 mois ou à 1 jour ; La volatilité EXTRÊME/ÉLEVÉE l’élargit encore."},{"h":"Comment le lire","t":"Regardez la PENTE (dans quelle direction le chemin penche) et la LARGEUR (quel degré de doute). Un chemin ascendant avec un cône étroit = ​​une idée de tendance plus stable ; un chemin plat avec un énorme cône = « pas de bord ici, attendez-vous à du bruit »."},{"h":"L'allumer et l'éteindre","t":"Le bouton « Prévisions 3M » se trouve à côté de « Espace futur ». Il a besoin de l'espace Future ON (la zone vide à droite dans laquelle la projection est dessinée). Si le signal est HOLD, il n'y a pas de direction, donc rien n'est dessiné."},{"h":"C'est la tendance, pas le commerce","t":"La prévision est une carte globale. Les niveaux commerciaux réels – entrée, TP1 / TP2, SL et projection à court terme – sont toujours ceux que vous négociez."},{"h":"Des limites honnêtes","t":"Les actualités, les cotations, les radiations et les changements macroéconomiques ne sont pas dans le modèle ; le chemin est une dérive douce, de sorte que les prix réels bougeront beaucoup plus ; un cône de 3 mois est une aide aux études, jamais une promesse."},{"h":"Réanalyser souvent","t":"Au fur et à mesure que de nouvelles bougies s'impriment, la cible, la volatilité et donc l'ensemble du cône se mettent à jour. Une prévision est un instantané, pas un contrat."},{"h":"Liste de contrôle pratique","t":"① Lisez la direction du chemin ② Vérifiez la largeur du cône ③ Comparez avec une structure TF supérieure ④ Dimensionnez la position à partir du SL réel, jamais à partir du cône."}]}],"platforms":{"BINANCE":{"title":"Binance Trading A → Z","steps":["Créer un compte → activer 2FA.","Gestion des API → Créer une clé → Commerce au comptant et/ou à terme activé, retraits désactivés.","Collez la clé + le secret dans CPE → Clés API → Binance → Enregistrer → Compte test.","Utilisez le scan Spot Desk / Futures Desk (les graphiques publics fonctionnent avant même les clés).","Pratique : Commerce manuel → Démarrer le commerce papier (pas d'argent réel).","En direct : définissez TP1/TP2/SL + Trailing → Démarrer le commerce en direct (nécessite une API).","Gérer dans les positions : modifier les niveaux, fermer partiellement, annuler automatiquement.","Licence : Essai 7j → 3 mois ou à vie (prix propriétaire dans l'application)."]},"BYBIT":{"title":"Trading de bits A → Z","steps":["Compte + 2FA.","Gestion des API → échange uniquement, retraits désactivés.","CPE → Clés API → Bybit → Enregistrer.","Futures Desk pour l’état d’esprit des criminels ; Chart Lab pour étudier les bougies.","Le commerce du papier d'abord ; Vivez après le travail des clés.","Trail TP+SL : ACHETER↑ / VENDRE↓."]},"OKX":{"title":"OKX Trading A → Z","steps":["Clé API + Secret + Phrase secrète requise.","Retraits toujours désactivés.","Enregistrez les trois champs dans les clés CPE.","Pratique du papier → petite taille réelle.","Les fautes de frappe dans les phrases secrètes sont l’échec n°1 – copiez-les soigneusement."]},"KUCOIN":{"title":"Commerce de KuCoin A → Z","steps":["Clé + Secret + Phrase secrète.","Autorisation commerciale uniquement.","Papier en CPE → puis vis petit.","Utilisez les bureaux Spot/Futures pour les signaux."]},"BITGET":{"title":"BitgetTrading A → Z","steps":["API avec échange uniquement.","Le papier vit alors.","Futures : choisissez Cross ou Isolé dans le commerce manuel.","Suivez TP+SL pour verrouiller les bénéfices."]},"GATE":{"title":"Gate.io Trading A → Z","steps":["Créer des clés API v4 (commerce).","Retraits OFF.","Enregistrer dans CPE → papier d'entraînement.","Scan + Chart Lab pour les entrées avant la mise en ligne."]},"MEXC":{"title":"MEXC Trading A → Z","steps":["Démarrez l’état d’esprit Spot.","Clés dans les clés API CPE.","Papier → en direct.","Utilisez Trail pour verrouiller les bénéfices ouverts."]},"KRAKEN":{"title":"Kraken Trading A → Z","steps":["Générez une clé avec une autorisation commerciale uniquement.","Aucun droit de retrait/fonds.","Pratique du papier en CPE.","Vérifiez également chaque commande en direct sur Kraken."]},"COINBASE":{"title":"Coinbase avancé A → Z","steps":["Clés API commerciales avancées.","Bureau focalisé sur le spot en CPE.","Le papier vit alors.","Gardez les retraits désactivés."]},"FOREX_OANDA":{"title":"Forex (OANDA) A → Z","steps":["Démo ouverte OANDA → risque ~1%.","Jeton d'accès personnel + ID de compte dans les clés CPE.","Analyse Forex Desk + Chart Lab (EURUSD…).","Commerce manuel → Papier avec plateforme Forex.","Vivez seulement après la démonstration de confiance."]},"FOREX_FXCM":{"title":"FXCM Forex A → Z","steps":["Informations d'identification de l'API du courtier.","Papier en CPE en premier.","Regardez les sessions Londres/NY et les pics d'actualité.","Le journal en direct après l’entraînement a l’air propre."]},"FOREX_MT5":{"title":"MetaTrader 5 A → Z","steps":["Login + serveur + mot de passe dans CPE Keys.","Préférez le mot de passe investisseur (lu) lorsque cela est possible.","Pratiquez les lots 0,01.","Papier en CPE ; en direct via un courtier lorsque vous êtes prêt."]},"FOREX_DEMO":{"title":"Taux de démonstration Forex A → Z","steps":["Aucune clé API requise.","Forex Desk + Chart Lab pour des graphiques gratuits.","Métiers du papier uniquement (pratique).","Lorsque vous êtes prêt à utiliser un vrai courtier, ajoutez les clés OANDA / FXCM / MT5 pour le direct."]}},"forexAz":{"title":"Forex Trading A → Z (cours complet)","lessons":[{"h":"A — Compte et risque","t":"Démo d'abord. Risque ~0,5 à 1 % par idée. Ne vous vengez jamais du commerce."},{"h":"B — Paires","t":"Majors (EURUSD, GBPUSD, USDJPY) avant les exotiques."},{"h":"C — Bougies","t":"Apprenez Doji, Hammer, Engulfing sur Chart Lab Forex."},{"h":"D — Biais quotidien","t":"Vérifiez un délai plus élevé avant les entrées de 15 min/30 min."},{"h":"E — Entrées","t":"BB rebond inférieur + confirmation de bougie est une configuration de pratique courante."},{"h":"F — Fibonacci","t":"Des retraits de 50 % / 61,8 % sont souvent utilisés comme zones d'entraînement."},{"h":"G — Objectifs (TP)","t":"TP1 scale-out, TP2 runner, trail SL."},{"h":"H — Heures","t":"Chevauchement Londres-NY = plus de mouvement."},{"h":"I — Indicateurs","t":"RSI + MACD + BB ensemble ; éviter la surcharge de l'indicateur."},{"h":"J-Journal","t":"Enregistrez chaque transaction papier/en direct dans CPE Journal."},{"h":"K-Clés","t":"Le courtier forex en direct a besoin d'une API/jeton ; les tarifs de démonstration n’en ont pas besoin."},{"h":"L — Beaucoup","t":"Commencez 0,01 lots dans un état d’esprit pratique."},{"h":"M – État d’esprit","t":"Processus plutôt que prédiction. Évitez les mauvais jours."},{"h":"N — Actualités","t":"Consultez News & Tricks avant les grands événements."},{"h":"O — Commandes","t":"Réglez toujours SL. Le trailing protège le profit ouvert."},{"h":"P-Pratique","t":"Bouton Paper Trade = pratique sans API live."},{"h":"Q-Qualité","t":"Moins de configurations de haute qualité battent le surtrading."},{"h":"R — Risque : récompense","t":"Visez les configurations où la récompense ≥ le risque lorsque cela est possible."},{"h":"S — Séances","t":"L'Asie est plus calme ; Londres/NY plus actif."},{"h":"T — Tendances","t":"Tradez avec une tendance TF plus élevée lors de l'apprentissage."},{"h":"U — Mises à jour","t":"Regardez la bannière de mise à jour du CPE + l'aide en direct."},{"h":"V — Volatilité","t":"Augmentez la patience lorsque l'ATR augmente."},{"h":"W — Retirer l'API","t":"N'activez jamais le retrait sur une clé API."},{"h":"X — sorties","t":"Le trail TP + partiel bat l'espoir."},{"h":"Y — Votre plan","t":"Écrire des règles ; suivez-les en Manuel/Auto."},{"h":"Z — Zéro précipitation","t":"Pas de FOMO. Entraînez-vous → puis API en direct."}]}};

window.CPE_LEARN.de = {"intro":"Üben Sie zunächst mit Papier/DEMO. Studieren Sie Kerzen, Diagramme, BB/RSI/Fib, Geld, Psychologie – dann Signale (was KAUFEN/VERKAUFEN/HALTEN bedeutet + was zu tun ist) und Forex-Signale. Live benötigt den richtigen Plattform-API-Schlüssel (Auszahlungen AUS).","candles":[{"shape":"doji","name":"Doji","color":"#94a3b8","bias":"Neutral / warten","tip":"Öffnen ≈ schließen – Kreuz- oder dünner Körper. Marktunentschlossenheit nach einem Umzug.","also":"Lehrt auch: Nicht FOMO. Warten Sie auf die nächste Kerze. Nahezu BB-Extrem + Doji = Meinungsverknappung; Überprüfen Sie die RSI-Steigung, bevor Sie die Richtung erraten."},{"shape":"hammer","name":"Hammer","color":"#22c55e","bias":"KAUF-Voreingenommenheit","tip":"Kleiner Körper oben, langer unterer Docht (≈2× Körper) nach einem Tropfen – Käufer lehnten niedrigere Preise ab.","also":"Außerdem: Übungs-SL tief unter den Docht legen. Am besten mit niedrigerem BB + steigendem RSI aus dem Überverkauf. Psychologie: Geduld, bis der Docht fertig ist – kaufen Sie nicht mitten im Docht."},{"shape":"invhammer","name":"Umgekehrter Hammer","color":"#22c55e","bias":"KAUFEN (schwach)","tip":"Langer oberer Docht unten. Die Käufer waren hoch, schlossen aber nahezu offen – Bestätigung durch das nächste Grün erforderlich.","also":"Außerdem: schwächer als Hammer allein. Als Benachrichtigung verwenden, nicht als Eintrag. Fib 61,8 Bounce + Inverted Hammer = Studienzone nur bis zur Bestätigung der Kerze."},{"shape":"shooting","name":"Sternschnuppe","color":"#ef4444","bias":"VERKAUFS-Voreingenommenheit","tip":"Kleiner Körperboden, langer oberer Docht nach einem Anstieg – Verkäufer lehnten hohe Werte ab.","also":"Außerdem: SL über Docht hoch. Stärker in der Nähe des oberen BB / Fib-Erweiterung / RSI überkauft. Lehrt: Mondkerzen können versagen – jagen Sie nicht dem letzten Grün hinterher."},{"shape":"hanging","name":"Hängender Mann","color":"#f59e0b","bias":"VORSICHT VERKAUFEN","tip":"Sieht aus wie Hammer, erscheint aber nach einem Anstieg – mögliche Top-Erschöpfung.","also":"Außerdem: Kontext ist alles (gleiche Form ≠ gleicher Handel). Journalposition: oben vs. unten. Psychologie: Kehren Sie nicht um, nur weil die Form übereinstimmt – bestätigen Sie mit der nächsten Kerze + RSI."},{"shape":"engulf_bull","name":"Bullisches Engulfing","color":"#22c55e","bias":"KAUFEN","tip":"Der grüne Körper deckt den vorherigen roten Körper vollständig ab – Käufer übernahmen die Kontrolle in einem Balken.","also":"Außerdem: stärker bei Unterstützung / niedrigeres BB / Fib 50–61,8. Größe ab tief wie SL. Geldtipp: weiter umhüllender Körper → breiterer SL → kleinere Größe."},{"shape":"engulf_bear","name":"Bärisches Engulfing","color":"#ef4444","bias":"VERKAUFEN","tip":"Der rote Körper deckt das vorherige Grün vollständig ab – Verkäufer dominieren.","also":"Außerdem: Vorsicht bei offenen Long-Positionen. Nahe dem oberen BB + RSI > 70 = hohe Studienqualität. Lehrt Risiko: wenn schon lang, teilweise TP/Trail statt Hoffnung."},{"shape":"morning","name":"Morgenstern","color":"#22c55e","bias":"KAUFEN","tip":"3 Kerzen: großes Rot → kleiner Stern → großes Grün. Geschichte der unteren Umkehr.","also":"Außerdem: Geduld mit mehreren Kerzen. Eintritt nach 3. Schließung; SL unter Stern niedrig. Lässt sich gut mit der niedrigeren BB + bullischen RSI-Divergenz kombinieren."},{"shape":"evening","name":"Abendstern","color":"#ef4444","bias":"VERKAUFEN","tip":"3 Kerzen: großes Grün → kleiner Stern → großes Rot. Top-Umkehrgeschichte.","also":"Außerdem: Den mittleren Stern nicht allein kurzschließen. Warten Sie bis zum dritten Mal. Oberer Zusammenfluss von BB und Fib-Erweiterung. Psychologie: FOMO des ersten grünen Laufs ignorieren."},{"shape":"maru_bull","name":"Stier Marubozu","color":"#22c55e","bias":"Starker Kaufdruck","tip":"Langer grüner Körper, fast keine Dochte – Käufer kontrollierten Öffnen→Schließen.","also":"Außerdem: Hinweis auf eine Fortsetzung des Trends, nicht immer ein Tiefstkauf. Walk-the-Band möglich. Risiko: Dem späten Marubozu nachjagen, ohne auf BB-Mitte / Fib zurückzufallen."},{"shape":"maru_bear","name":"Bär Marubozu","color":"#ef4444","bias":"Starker Verkaufsdruck","tip":"Langer roter Körper, fast keine Dochte – Verkäufer haben die Kontrolle.","also":"Außerdem: Fallende Messer nicht auffangen. Warten Sie später, BB/Fib Bounce + Hammer. Lehrt: starker Druck = kleinere Größe oder beiseite treten."},{"shape":"spin","name":"Kreisel","color":"#94a3b8","bias":"Unentschlossenheit","tip":"Kleiner Körper, oberer + unterer Docht – beide Seiten kämpften, niemand gewann klar.","also":"Außerdem: Innen-BB oft zusammendrücken. Handel unterbrechen; Warte Pause + Richtung Kerze. Psychologie-Lektion: Der Markt kann „nichts tun“ – flach ist eine gültige Wahl."},{"shape":"pierce","name":"Piercing-Linie","color":"#22c55e","bias":"KAUFEN","tip":"Rot, dann Grün, das tiefer öffnet, aber über der Mitte des vorherigen Rots schließt.","also":"Außerdem: weicher als Engulfing. Mit RSI bestätigen. Gute Papierübung zum Lesen teilweiser Stärke – nicht alle Grüns sind gleich."},{"shape":"darkcloud","name":"Dunkle Wolkendecke","color":"#ef4444","bias":"VERKAUFEN","tip":"Grün, dann Rot, das höher öffnet, aber unterhalb der Mitte des vorherigen Grüns schließt.","also":"Außerdem: Frühwarnung vor vollständigem Bear Engulfing. Trail Longs / TP1 nehmen. Lehrt die Skalierung vor einem vollständigen Umkehrdruck."},{"shape":"soldiers","name":"Drei weiße Soldaten","color":"#22c55e","bias":"KAUFEN-Trend","tip":"Drei steigende Grüntöne mit höheren Schlusskursen – stetige Käufe.","also":"Außerdem: starker Aufwärtstrend; Pullbacks auf Fib 38–50 oder BB Mid sind Übungszuwächse. Risiko einer Selbstüberschätzung nach 3 Grüns – Risikoprozentsatz beibehalten."},{"shape":"crows","name":"Drei schwarze Krähen","color":"#ef4444","bias":"VERKAUFEN-Trend","tip":"Drei fallende Rottöne mit niedrigeren Schlusskursen – stetiger Verkauf.","also":"Außerdem: Den Durchschnitt nicht herabsetzen. Wartestruktur. Ein überverkaufter RSI kann überverkauft bleiben – Geldregel: Verlustgrenze > Hoffnung."},{"shape":"harami_bull","name":"Bullischer Harami","color":"#22c55e","bias":"KAUFEN (weich)","tip":"Großes Rot, dann kleines Grün im Inneren des vorherigen Körpers – Verkaufsdruck schrumpft.","also":"Außerdem: frühes Pausensignal. Muss bestätigt werden. Paart sich mit der bullischen Divergenzstudie des RSI. Lehrt das Lesen von „Kraftverlust“, nicht nur von Umkehrungen."},{"shape":"harami_bear","name":"Bärischer Harami","color":"#ef4444","bias":"VERKAUFEN (weich)","tip":"Großes Grün, dann kleines Rot im Inneren – der Kaufdruck nimmt ab.","also":"Außerdem: Nehmen Sie Teiltöne bei Long-Positionen. Nicht automatisch kurz. Psychologie: Die Gier nach dem großen Grün ignoriert oft die Harami-Warnung."},{"shape":"tweezer_bot","name":"Pinzette unten","color":"#22c55e","bias":"KAUFEN","tip":"Zwei Kerzen mit passenden Tiefs – doppelter Unterstützungstest.","also":"Außerdem: Markieren Sie das Tief als Struktur. SL knapp darunter. Die Fib/BB-Ausrichtung hilft. Cousin des Diagrammmusters von Double Bottom – gleiche Unterstützungslektion."},{"shape":"tweezer_top","name":"Pinzettenoberteil","color":"#ef4444","bias":"VERKAUFEN","tip":"Zwei Kerzen mit übereinstimmenden Höchstwerten – doppelter Widerstandstest.","also":"Außerdem: Markenfestigkeit. Cousin von Double Top. RSI-Fehler bei Höchstständen = Konfluenz. Lehrt: Gleicher Preis zweimal abgelehnt = Niveau respektieren."},{"shape":"longlegged","name":"Langbeiniger Doji","color":"#94a3b8","bias":"Unentschlossenheit","tip":"Sehr lange obere UND untere Dochte mit einem winzigen Körper – ein heftiger Zweikampf, der dort endete, wo er begonnen hatte.","also":"Außerdem folgt oft eine große Bewegung, aber die Richtung ist unbekannt – warten Sie auf die Durchbruchskerze. Lehrt: Hohe Volatilität ist keine hohe Gewissheit."},{"shape":"dragonfly","name":"Libellen-Doji","color":"#22c55e","bias":"KAUF-Voreingenommenheit","tip":"Offen = geschlossen = hoch, mit einem langen unteren Docht – Verkäufer drückten ihn nach unten und Käufer schlugen ihn direkt wieder nach oben.","also":"Außerdem: am stärksten bei Unterstützung / niedrigeres BB nach einem Rückgang. SL unter dem Dochtschwanz. Lehrt: Ablehnung ist eine Geschichte, keine Garantie – bestätigen Sie die nächste Kerze."},{"shape":"gravestone","name":"Grabstein-Doji","color":"#ef4444","bias":"VERKAUFS-Voreingenommenheit","tip":"Offen = geschlossen = tief, mit einem langen oberen Docht – Käufer drückten nach oben und Verkäufer zogen ihn zurück auf den Tiefststand.","also":"Außerdem: am stärksten beim Widerstand / oberes BB / RSI überkauft. Spiegel der Libelle. Lehrt: Ein Spitzenhoch, das am Tief schließt, ist ein gescheiterter Ausbruch."},{"shape":"inside_bar","name":"Innenbar","color":"#94a3b8","bias":"Aufrollen / warten","tip":"Die zweite Kerze liegt vollständig innerhalb der ersten – die Spanne wird kleiner und der Markt hält den Atem an.","also":"Außerdem: Der Bruch des Mutterbalkens ist der Auslöser – handeln Sie in die Bruchrichtung. Kombiniert mit einem BB-Squeeze. Lehrt: Kontraktion kommt vor Expansion."},{"shape":"outside_bar","name":"Außenbar","color":"#22c55e","bias":"Ausbruch / Umkehr","tip":"Die zweite Kerze verschlingt die erste von oben nach unten – eine heftige Übernahme innerhalb eines Balkens.","also":"Außerdem: Richtung = wo die äußere Leiste schließt. Ein großer Balken bedeutet einen großen SL, also eine kleinere Größe. Lehrt: Ein Takt kann die letzten drei löschen."},{"shape":"belt_bull","name":"Bullischer Gürtelhalt","color":"#22c55e","bias":"KAUFEN","tip":"Öffnet am Tiefpunkt ohne unteren Docht und läuft grün – Käufer übernahmen vom ersten Tick an die Kontrolle.","also":"Außerdem: am stärksten nach einem Gap nach unten oder direkt in die Unterstützung hinein. SL unter freiem Himmel. Lehrt: Eine Eröffnungsfahrt zeigt echte Absicht."},{"shape":"belt_bear","name":"Bärischer Belt Hold","color":"#ef4444","bias":"VERKAUFEN","tip":"Öffnet sich in der Höhe ohne oberen Docht und läuft rot aus – die Verkäufer kontrollierten es von Anfang an.","also":"Außerdem: am stärksten nach einer Lücke nach oben oder bei einem Widerstand. Trail sehnt sich. Lehrt: Der erste Zug kann den ganzen Tag bestimmen."},{"shape":"kick_bull","name":"Bullischer Kicker","color":"#22c55e","bias":"Starker KAUF","tip":"Eine rote Kerze, dann ein Gap bis hin zu einer grünen Kerze – die Stimmung wechselte zwischen den Schlusskursen ohne Überschneidung.","also":"Außerdem: selten und kraftvoll; Die Lücke ist erforderlich, Überlappung ist nicht zulässig. Lehrt: Die Stimmung kann umschlagen, während der Markt schläft."},{"shape":"kick_bear","name":"Bärischer Kicker","color":"#ef4444","bias":"Starker VERKAUF","tip":"Eine grüne Kerze, dann eine Lücke in eine rote Kerze – zwischen den Schlusskursen verschwanden die Käufer.","also":"Außerdem: Verlassen Sie Long-Positionen schnell – Kicker warten nicht auf Sie. Lehrt: Eine Lücke ist die Neubewertung des Marktes, wenn Sie weg sind."},{"shape":"abandoned","name":"Bullisches, verlassenes Baby","color":"#22c55e","bias":"Starker KAUF","tip":"Eine rote Kerze, ein Doji mit einer Lücke nach unten, dann eine grüne Kerze mit einer Lücke nach oben – eine einsame Insel der Unentschlossenheit.","also":"Außerdem: Der Doji muss auf BEIDEN Seiten einen Abstand haben. Selten, aber von hoher Qualität an der Unterseite. Lehrt: Umkehrungen beginnen dort, wo alle aufgeben."},{"shape":"three_inside_up","name":"Drei von innen nach oben","color":"#22c55e","bias":"KAUFEN","tip":"Bullischer Harami plus eine dritte grüne Kerze, die über der ersten schließt – der innere Balken brach schließlich durch.","also":"Außerdem: Ein bestätigter Harami ist weitaus stärker als ein nackter. SL unter dem Harami-Low. Lehrt: Bestätigung schlägt Vorhersage."},{"shape":"three_inside_down","name":"Drei von innen nach unten","color":"#ef4444","bias":"VERKAUFEN","tip":"Bärischer Harami plus eine dritte rote Kerze, die unter der ersten schloss – der innere Balken brach zusammen.","also":"Außerdem: Schneiden Sie die Long-Positionen ab, sobald die dritte schließt. Lehrt: Eine gescheiterte Pause kann einfach den alten Trend wieder aufnehmen."},{"shape":"three_methods_bull","name":"Drei Methoden aufsteigen","color":"#22c55e","bias":"KAUFEN-Trend","tip":"Eine lange grüne Kerze, drei kleine rote Kerzen darin, dann eine weitere lange grüne Kerze – ein Rest in einem Anstieg.","also":"Außerdem: Die Pause verlässt nie den Bereich der ersten Kerze, daher ist der Trend ruhig. Handeln Sie den Bruch der letzten Kerze. Lehrt: Trends bleiben bestehen, ohne zu brechen."},{"shape":"three_methods_bear","name":"Fallende drei Methoden","color":"#ef4444","bias":"VERKAUFEN-Trend","tip":"Eine lange rote Kerze, drei kleine grüne Kerzen darin, dann noch eine lange rote Kerze – eine Pause in einem Herbst.","also":"Außerdem: Spiegel von Rising Three Methods. Kaufen Sie nicht die kleinen Grüns – sie sind Lärm. Lehrt: Pullbacks innerhalb einer Spanne sind keine Umkehrungen."},{"shape":"tower_bot","name":"Turmboden","color":"#22c55e","bias":"KAUF-Umkehr","tip":"Eine lange rote Kerze, eine Ansammlung winziger Kerzen, dann eine lange grüne – die Stimmung verschiebt sich auf einer flachen Basis.","also":"Außerdem: Die flache Mitte ist der Kampf und die letzte Kerze erklärt den Gewinner. Lehrt: Basen brauchen Zeit."},{"shape":"tower_top","name":"Turmspitze","color":"#ef4444","bias":"SELL-Umkehr","tip":"Eine lange grüne Kerze, eine Ansammlung winziger Kerzen, dann eine lange rote – die Käufer erschöpfen sich und die Verkäufer übernehmen.","also":"Außerdem: Spiegel von Tower Bottom. Nehmen Sie Teilstücke, während sich die Basis bildet. Lehrt: Tops sind ein Prozess, kein Moment."}],"chartPatterns":[{"shape":"double_bot","name":"Doppelter Boden (W)","color":"#22c55e","bias":"KAUF-Voreingenommenheit","tip":"Zwei Tiefststände in der Nähe des gleichen Preises, dann Durchbruch des mittleren Höhepunkts – W-Form.","also":"Außerdem: Neckline Break = Übungsauslöser. Messen Sie die Höhe für die TP-Idee. Links zum Pinzettenboden + Fib von Spitze→Tief. Risiko: falscher Bruch – warten Sie dicht hinter der Nackenlinie."},{"shape":"double_top","name":"Doppeltop (M)","color":"#ef4444","bias":"VERKAUFS-Voreingenommenheit","tip":"Zwei Hochs nahe dem gleichen Preis, dann Durchbruch des mittleren Tiefs – M-Form.","also":"Außerdem: wie Tweezer Top in größerem Maßstab. Der Trail sehnt sich vor dem Neckline Break. Psychologie: Das zweitbeste FOMO ist teuer – der Plan war bereits da."},{"shape":"hs_top","name":"Kopf und Schultern","color":"#ef4444","bias":"VERKAUFS-Voreingenommenheit","tip":"Linke Schulter, höherer Kopf, rechte Schulter; Ausschnitt nach unten brechen.","also":"Außerdem: klassische Distribution. Ziel ≈ Kopfhöhe unterhalb des Halsausschnitts. Der RSI divergiert häufig im Kopfbereich. Lehrt Multi-Swing-Geduld – nicht den Handel mit einer Kerze."},{"shape":"ihs","name":"Inverses H&S","color":"#22c55e","bias":"KAUF-Voreingenommenheit","tip":"Umgedrehtes Kopf- und Halstuch am Saum – der Ausschnitt ist aufgebrochen.","also":"Außerdem: Akkumulationsgeschichte. Bestätigen Sie mit Volumen/Impuls, falls verfügbar. Kombinieren Sie es mit Morning Star in der rechten Schulterzone für Konfluenzstudien."},{"shape":"triangle","name":"Dreieck (drücken)","color":"#f0b429","bias":"Ausbruch warten","tip":"Niedrigere Höhen + höhere Tiefen komprimieren – Energieaufbau.","also":"Außerdem: Dieselbe Lektion wie beim BB-Squeeze. Erraten Sie nicht die Richtung im Inneren. Handelsunterbrechung + Kerzenschluss. Geld: Größe nach Richtung bekannt."},{"shape":"flag","name":"Bullenflagge","color":"#22c55e","bias":"KAUFEN Fortsetzung.","tip":"Steiler Anstieg (Pol), dann kleiner Abwärts-/Seitwärtskanal – dann Fortsetzung.","also":"Außerdem: Die Tiefe der Fib-Flagge ist oft gering (38 %). Marubozu-Stange + Flagge = Trendübung. Kaufen Sie nicht zu spät nach der vollständigen Erweiterung ohne Rückzug."},{"shape":"channel","name":"Trendkanal","color":"#38bdf8","bias":"Mit Trend","tip":"Preis zwischen steigenden (oder fallenden) parallelen Linien – Swing-Trade-Tools.","also":"Außerdem: Unteren Kanal kaufen + Hammer im Aufwärtstrend; verkaufe Obermaterial + Shooting Star. BB Mid verfolgt häufig den Kanal. Lehrt „wo“, nicht nur „welche Kerze“."},{"shape":"support_res","name":"Unterstützung und Widerstand","color":"#a78bfa","bias":"Zuerst den Kontext","tip":"Horizontale Zonen, in denen der Preis wiederholt reagiert – die Karte unter jeder Kerze.","also":"Außerdem: Bei S/R ist jedes Muster stärker. Zeichnen Sie Zonen auf Chart Lab vor BB/RSI ein. Psychologie: Stufen > Tipps; Schreiben Sie sie vor der Einreise."},{"shape":"triple_top","name":"Dreifache Spitze","color":"#ef4444","bias":"VERKAUFS-Voreingenommenheit","tip":"Drei Höchststände zum nahezu gleichen Preis – Käufer scheitern dreimal an einer Wand.","also":"Außerdem: stärker als ein Double Top (drei Ausschuss = hartnäckiger Nachschub). Nackenbruch ist der Auslöser; Ziel ≈ Musterhöhe. Lehrt: Das Level, nicht die Kerze, ist der Boss."},{"shape":"triple_bot","name":"Dreifachboden","color":"#22c55e","bias":"KAUF-Voreingenommenheit","tip":"Drei Tiefststände bei nahezu demselben Preis – Verkäufer scheitern dreimal auf einer Etage.","also":"Außerdem: Spiegel von Triple Top. Jede Berührung kann eine Hammer-/Pinzettenstudie sein. Warten Sie auf den Neckline-Break + Close. Lehrt Geduld bei vielen Schwüngen."},{"shape":"cup_handle","name":"Tasse und Griff","color":"#22c55e","bias":"KAUFEN Fortsetzung.","tip":"Ein abgerundetes „U“ (Körbchen), dann ein kleiner Rückzug (Griff) – Fortsetzung nach einer Pause.","also":"Außerdem: beliebt bei Breakout-Tradern. Der Griff sollte flach und kurz sein – ein tiefer Griff bedeutet schwache Hände. Geben Sie bei Klinkenbruch mit Kerze ein und bestätigen Sie."},{"shape":"rounding_bot","name":"Abgerundeter Boden","color":"#22c55e","bias":"KAUF-Umkehr","tip":"Ein langsames, sanftes „Untertassen“-Tief – der Verkauf lässt allmählich nach, dann übernehmen die Käufer.","also":"Außerdem: ein Double Bottom in Zeitlupe. Die Botschaft ist, dass den Verkäufern die Energie ausgegangen ist, kein einziger Anstieg – volle Geduld ist gefragt."},{"shape":"rounding_top","name":"Abgerundetes Oberteil","color":"#ef4444","bias":"SELL-Umkehr","tip":"Ein sanftes „Kuppel“-Hoch – der Kauf lässt allmählich nach, bevor der Preis steigt.","also":"Außerdem: Spiegel von Rounding Bottom. Nehmen Sie frühzeitig Teilwiederholungen vor, während der Schwung nachlässt. Lehrt: Tops sind ein Prozess, keine einzelne Kerze."},{"shape":"rising_wedge","name":"Steigender Keil","color":"#ef4444","bias":"VERKAUFS-Voreingenommenheit","tip":"Beide Schienen steigen an, laufen aber nach oben zusammen – Käufer werden müde, wenn die Reichweite enger wird.","also":"Außerdem: irreführend, weil der Preis immer noch steigt; Die Verengung ist der eigentliche Hinweis. Geht oft kaputt. Verfolge nicht den letzten Drang."},{"shape":"falling_wedge","name":"Fallender Keil","color":"#22c55e","bias":"KAUF-Voreingenommenheit","tip":"Beide Schienen fallen, laufen aber nach unten zusammen – die Verkäufer werden müde, wenn die Reichweite enger wird.","also":"Außerdem: Spiegel von Rising Wedge. Bricht oft ab. Ein Hammer im Keilschwanz ist eine klassische Studie. Warten Sie auf die Pause + schließen Sie."},{"shape":"asc_triangle","name":"Aufsteigendes Dreieck","color":"#f0b429","bias":"KAUF-Voreingenommenheit","tip":"Eine flache Decke + steigender Boden – Käufer stoßen immer wieder auf einen festen Widerstand.","also":"Außerdem: Es baut sich Druck auf einen Preis auf; Ausbrüche kommen häufig vor. Betreten Sie den Raum knapp über der Decke. Lehrt: Käufer werden ungeduldig."},{"shape":"desc_triangle","name":"Absteigendes Dreieck","color":"#f0b429","bias":"VERKAUFS-Voreingenommenheit","tip":"Ein flacher Boden + fallende Decke – Verkäufer drängen immer wieder auf eine feste Stütze.","also":"Außerdem: Spiegel des aufsteigenden Dreiecks. Ausbrüche kommen häufig vor. Betreten Sie den Raum dicht unter dem Boden. Lehrt: Verkäufer erlangen die Kontrolle."},{"shape":"pennant","name":"Wimpel","color":"#22c55e","bias":"Fortsetzung","tip":"Ein spitzer Pol, dann ein winziges, enges Dreieck – eine sehr kurze Pause, bevor der Trend wieder einsetzt.","also":"Außerdem: wie eine Flagge, aber kürzer und dreieckig. Messen Sie die Stange für eine Zielidee. Raten Sie niemals in der winzigen Spule."},{"shape":"flag_bear","name":"Bärenflagge","color":"#ef4444","bias":"VERKAUFEN Fortsetzung.","tip":"Ein starker Abfall (Pol), dann ein kleiner Aufwärts-/Seitwärtskanal – dann Fortsetzung nach unten.","also":"Außerdem: Spiegel von Bull Flag. Der kleine Sprung ist eine Pause, keine Umkehr. Wenn Sie der Flagge hinterherjagen, kaufen Sie zum schlechtesten Preis – warten Sie auf den Durchbruch."},{"shape":"rectangle","name":"Rechteck (Bereich)","color":"#f0b429","bias":"Sortimentshandel","tip":"Der Preis schwankt zwischen einer flachen Decke und einem Boden – eine seitliche Box.","also":"Außerdem: Innen die Kanten ausblenden, außen den Bruch tauschen. Der BB-Squeeze befindet sich normalerweise innerhalb eines Rechtecks. Lehrt: Disziplin auf allen Ebenen."},{"shape":"broadening","name":"Erweiterung der Formation","color":"#f0b429","bias":"Achtung","tip":"Höhere Höhen UND tiefere Tiefen – der Bereich breitet sich aus, statt einzuschnüren.","also":"Außerdem: ein chaotischer, emotionaler Markt. Stopps werden in beide Richtungen getroffen. Kleinere Größe oder beiseite stellen; es endet oft in einer gewalttätigen einseitigen Bewegung."},{"shape":"diamond","name":"Diamant","color":"#f0b429","bias":"Umkehrung","tip":"In der Mitte breit, an beiden Enden schmal – eine klassische Topping/Bottom-Formation.","also":"Außerdem: ein Dreieck, das sich verwandelt und dann wieder aufhebt. Die Ausbruchsrichtung entscheidet. Selten und langsam, daher fühlen sich die meisten Reihen wie Lärm an – seien Sie geduldig."},{"shape":"island_rev","name":"Inselumkehr","color":"#ef4444","bias":"Umkehrung","tip":"Der Preis klafft auseinander, handelt in einer einsamen Gruppe und dann wieder zurück – eine „Insel“.","also":"Außerdem: Es sind echte Lücken erforderlich (häufiger bei Aktien/Devisen). Auf der Insel sind Käufer oder Verkäufer gefangen. Betrachten Sie die Lücken als Signal, nicht die Inselkerzen."},{"shape":"breakaway_gap","name":"Breakaway-Lücke","color":"#22c55e","bias":"Trendstart","tip":"Eine Lücke außerhalb einer Reichweite oder Basis – die Bewegung beginnt mit Gewalt, nicht mit Drücken.","also":"Außerdem: Im Gegensatz zu einer Erschöpfungslücke erscheint sie früh in einer Bewegung. Lücken wirken später oft als Unterstützung/Widerstand. Lehrt: Momentum-Value-Lücken."},{"shape":"v_reversal","name":"V-Umkehr","color":"#22c55e","bias":"Umkehrung","tip":"Ein scharfer freier Fall, der ohne Basis sofort nach oben zeigt – ein „V“.","also":"Außerdem: schnell und gruselig; oft nachrichtengesteuert. Schwer zu fangen, leicht zu jagen. Warten Sie auf einen kleinen Rückzug + Kerze, anstatt den Anstieg zu kaufen."},{"shape":"harmonic","name":"Harmonisches Muster","color":"#f0b429","bias":"Umkehrzonen","tip":"Ein gemessener Zickzack (X-A-B-C-D), bei dem jedes Bein ein Fibonacci-Verhältnis hat – eine Karte im „Gartley/Bat“-Stil.","also":"Auch: fortgeschritten. Der D-Punkt ist die Eintrittszone, die durch Verhältnisse und nicht durch Gefühle definiert wird. Meistern Sie zuerst das einfache Fib; Das ist Fib, eine Ebene tiefer."}],"modules":[{"id":"bb","title":"1 · Bollinger-Bänder (BB)","summary":"Die Volatilität bewegt sich um einen gleitenden Durchschnitt. Lernen Sie Squeeze, Walk-the-Band, untere/obere Berührung + Kerzenbestätigung – das grundlegende CPE-Übungssetup.","lessons":[{"h":"Was BB ist","t":"Bollinger-Bänder = mittlerer SMA (oft 20) + obere/untere Bänder bei N Standardabweichungen (oft 2). Die Bänder weiten sich aus, wenn die Volatilität zunimmt, und verengen sich, wenn der Markt ruhig ist."},{"h":"Mittelband","t":"Die Mittellinie ist der Mittelwert. Ein Preis oberhalb der Mitte zeigt oft Aufwärtsdruck an; Unten zeigt der rückläufige Druck. Verwenden Sie es als dynamische Bias-Linie, nicht als magischen Kauf/Verkauf."},{"h":"Unteres Band (KAUFEN-Übung)","t":"Die Markierung des Preises im unteren Bereich nach einem Rückgang kann „nach unten gestreckt“ bedeuten. Kaufen Sie NICHT jede Berührung. Warten Sie, bis eine zinsbullische Kerze (Hammer, Engulfing) und idealerweise der RSI ansteigt."},{"h":"Oberes Band (VERKAUFEN / Vorsicht)","t":"Die Angabe des Preises im oberen Bereich kann „nach oben gestreckt“ bedeuten. In einem Aufwärtstrend kann der Preis dem oberen Band folgen (Walk-the-Band). Bevorzugen Sie VERKAUFS-Ideen nur mit bärischer Kerze + höherer TF-Schwäche."},{"h":"Quetschen","t":"Schmale Bänder = geringe Volatilität → oft folgt ein Ausbruch. Erraten Sie nicht die Richtung innerhalb einer engen Enge; Markieren Sie den Ausbruch und bestätigen Sie mit Kerze + Volumen, falls verfügbar."},{"h":"Gehen Sie mit der Band","t":"Bei einem starken Trend bewegt sich der Preis bei vielen Kerzen am oberen (oder unteren) Band. Dem mit Mean-Reversion-Fades entgegenzuwirken, ist ein häufiger Anfängerfehler."},{"h":"BB + Diagrammlabor","t":"Studieren Sie im CPE Chart Lab/auf den Schreibtischen BB mit Kerzen auf DEMO. Übung: unteres Band + Hammer → Papierhandel mit SL unter dem Docht, TP1 in der Nähe des mittleren Bandes."},{"h":"BB + RSI-Kombination","t":"Stärkerer Übungsfilter: niedrigeres BB + RSI überverkauft (oder steigend aus überverkauft) + bullische Kerze. Oberer BB + RSI überkauft + bärische Kerze für kurzes Üben."},{"h":"Stoppen Sie die Platzierung","t":"Langes Üben: SL unter dem Swing Low / unter dem unteren Banddocht. Kurze Übung: SL über Schwung hoch. Nehmen Sie niemals einen BB-Handel ohne eine schriftliche SL auf."},{"h":"Ziele","t":"Gemeinsamer Pfad: TP1 am mittleren Band, TP2 zum gegenüberliegenden Band oder Trail. Scale-out – Sie brauchen nicht den ganzen Umzug."},{"h":"Zeitrahmen","t":"Entscheiden Sie sich für eine höhere TF (4H/1D). Einstieg auf 15m/30m BB + Kerze. Das Mischen zufälliger TFs führt zu widersprüchlichen Signalen."},{"h":"Fehler, die es zu vermeiden gilt","t":"In einem zusammenbrechenden Markt jede Berührung im unteren Bandbereich kaufen; den Verkauf jeder oberen Berührung bei einem Mondlauf; kein SL; Ignorieren von Nachrichtenspitzen, die die Bande heftig erweitern."},{"h":"Checkliste für die Praxis","t":"① Höherer TF-Bias ② BB Touch oder Squeeze Break ③ Kerze bestätigt ④ RSI stimmt zu ⑤ Risiko % festgelegt ⑥ Papier zuerst ⑦ Journalergebnis."}]},{"id":"rsi","title":"2 · RSI (Relative-Stärke-Index)","summary":"Impulsoszillator 0–100. Standardmäßig 14 Periode. Verwendung mit BB und Kerzen – niemals RSI allein als vollständiges System.","lessons":[{"h":"Was RSI misst","t":"Der RSI vergleicht durchschnittliche Gewinne mit Verlusten über N Balken. Hoher RSI = jüngstes Aufwärtsmomentum; niedriger RSI = jüngstes rückläufiges Momentum. Es ist nicht jedes Mal „überkauft = muss verkauft werden“."},{"h":"Klassische Zonen","t":"Häufig: über 70 = überkaufter Bereich, unter 30 = überverkaufter Bereich. Bei starken Trends kann der RSI lange Zeit überkauft/überverkauft bleiben – das ist normal."},{"h":"Mittellinie 50","t":"Ein RSI-Durchschnitt über 50 kann eine bullische Tendenz unterstützen; unter 50 bärische Tendenz. Viele Händler verwenden 50 als Trendfilter mit BB-Mittelband."},{"h":"Divergenz – bullisch","t":"Der Preis erreicht ein niedrigeres Tief, der RSI erreicht ein höheres Tief → das Momentum schwächt sich nach unten ab. Warten Sie noch auf den Kerzen- und Strukturbruch, bevor Sie ins Papier kommen."},{"h":"Divergenz – bärisch","t":"Preis höher, RSI niedriger, hoch → Aufwärtsdynamik lässt nach. Bestätigen Sie mit Shooting Star / Engulfing in der Nähe des Widerstands oder des oberen BB."},{"h":"Fehlerschwankungen","t":"Der RSI kann das vorherige Extrem nicht erneut testen und überschreitet dann wieder die 50-Marke – ein Hinweis auf eine frühe Momentumverschiebung. Kombinieren Sie es mit der Chart Lab-Struktur."},{"h":"RSI + BB (CPE-Stil)","t":"Üben Sie lange: Preis nahe dem unteren BB, RSI ≤ 35 (oder steigend von ≤ 30), bullische Kerze. Üben Sie kurz: oberes BB, RSI ≥ 65–70, bärische Kerze."},{"h":"Versteckte Divergenz","t":"Hinweis auf die Fortsetzung des Trends (z. B. Preis höher, Tief, RSI niedriger, Tief im Aufwärtstrend). Fortgeschritten – meistern Sie zuerst die klassische Divergenz in der DEMO."},{"h":"Einstellungen","t":"RSI(14) ist der übliche Standardwert. Kürzerer RSI = mehr Rauschen. Ändern Sie nicht ständig die Einstellungen, um ein Signal zu erzwingen."},{"h":"Beendet mit RSI","t":"Wenn Sie überverkauft gekauft haben, ist es sinnvoll, einen Teilgewinn mitzunehmen, wenn der RSI den mittleren/oberen Bereich erreicht. Den Rest mit Struktur oder BB-Mitte nachziehen."},{"h":"Nachrichten & RSI","t":"Große Neuigkeiten können den RSI sofort in die Höhe treiben. Warten Sie lieber auf das Ende der ersten heftigen Kerze, bevor Sie auf RSI-Extreme reagieren."},{"h":"Fehler","t":"Leerverkäufe aller RSI > 70 in einem Bullenmarkt; Ich sehne mich nach jedem RSI<30 bei einem Bärencrash; kein Zusammenfluss; Revanche-Wiedereintritt, wenn der RSI „besser aussieht“."},{"h":"Checkliste für die Praxis","t":"① RSI-Wert + Steigung notieren ② BB-Position prüfen ③ Kerze bestätigen ④ Höherer TF ⑤ Papier + Tagebuch ⑥ Eine Idee nach der anderen."}]},{"id":"fib","title":"3 · Fibonacci (Retracement & Extension)","summary":"Messen Sie Rückzüge und Ziele von einem klaren Swing-Hoch → Swing-Tief (oder umgekehrt). Konzentrieren Sie sich auf 38,2 · 50 · 61,8 mit BB/RSI-Konfluenz.","lessons":[{"h":"Warum Fib verwendet wird","t":"Viele Händler achten auf die gleichen Kennzahlen, daher reagiert die Liquidität oft in deren Nähe. Fib ist eine Karte möglicher Zonen – keine Garantie."},{"h":"Swing-Punkte","t":"Ziehen Sie immer von einem klaren Schwungtief zu Schwunghoch (Aufwärtsbewegung) oder von Hoch zu Tief (Abwärtsbewegung). Schlechte Schwünge = nutzlose Level. Üben Sie das Auswählen von Swings in der Chart Lab DEMO."},{"h":"Wichtige Retracements","t":"Häufig: 23,6 % (flach), 38,2 %, 50 % (kein reines Fib, aber weit verbreitet), 61,8 % (golden), 78,6 % (tief). Tiefe Retracements können auf eine Trendschwäche hinweisen."},{"h":"Pullback-Käufe (Aufwärtstrend)","t":"Warten Sie nach dem Aufwärtsimpuls auf einen Rückzug in die Zone 38,2–61,8 + bullische Kerze + vorzugsweise mittlere/untere BB-Unterstützung oder einen RSI-Wert von >40–45."},{"h":"Pullback-Verkäufe (Abwärtstrend)","t":"Nach dem Abwärtsimpuls erfolgt eine Erholung auf 38,2–61,8 + bärische Kerze + RSI scheitert unter 55–60."},{"h":"Erweiterungen / Ziele","t":"Häufige Erweiterungen: 127,2 %, 161,8 % über den Swing hinaus für TP2-Ideen. Mit Trail verwenden – keine exakten Ticks erzwingen."},{"h":"Zusammenfluss = Macht","t":"Best-Practice-Zonen: Fib 50/61,8 + BB Mitte/Unter + vorherige Struktur + RSI-Wende. Eine Fib-Leitung allein ist schwach."},{"h":"Fib + BB","t":"Wenn 61,8 % in der Nähe des unteren BB in einem Aufwärtstrend liegen, handelt es sich bei dieser Überschneidung um einen hochwertigen Papierstudienbereich. Nur mit Kerzenbestätigung betreten."},{"h":"Mehrere Fibs","t":"Anfänger sollten EINEN sauberen Schwung verwenden. Das Stapeln von 5 Fibs führt zu Diagrammrauschen und FOMO-Einträgen."},{"h":"Ungültigkeit","t":"Wenn der Preis entgegen Ihrer Einschätzung deutlich über 78,6 % schließt, scheitert die Pullback-These oft – steigen Sie aus oder bleiben Sie beiseite."},{"h":"Forex vs. Krypto","t":"Gleiche Verhältnisse. Forex-Majors respektieren die Niveaus in flüssigen Sitzungen oft sauberer; Krypto kann durchdringen und dann umkehren – Größe kleiner."},{"h":"Fehler","t":"Zeichnen von Fib auf winzigen Rauschschwankungen; ohne Kerze mitten in der Luft eintreten; SL weiter verschieben, wenn Fib „fast“ gehalten hat; höhere TF ignorieren."},{"h":"Checkliste für die Praxis","t":"① Markieren Sie den Swing ② Beachten Sie 38,2/50/61,8 ③ Warten Sie, bis der Preis eintrifft ④ Kerze + RSI/BB ⑤ Risikosatz ⑥ Papier → Journal."}]},{"id":"money","title":"4 · Geldmanagement","summary":"Wie die Methode tatsächlich angewendet wird: Risiko eines festen Prozentsatzes, Größe ab dem Stop, Bankanteil des Gewinns und Stop für den Tag nach einem Verlustlimit. CPE kann dies auf manuelle und automatische Geschäfte anwenden.","lessons":[{"h":"Ziel des Geldmanagements","t":"Bleiben Sie im Spiel. Ein schlechter Trade sollte niemals das Konto löschen. Konsistenz übertrifft Lotteriegrößen."},{"h":"Wie Händler es tatsächlich nutzen","t":"Die gängige Praxis ist ein festes Bruchteilrisiko. Sie wählen nicht zuerst einen Münzbetrag aus. Sie schreiben zuerst den Stopp, entscheiden, dass diese Idee etwa 1 % des Kontos verlieren könnte, und dann fällt die Größe daraus. Ein breiter Stopp erhält eine kleinere Position. Ein enger Stop führt zu einer größeren Position und das Dollarrisiko bleibt ungefähr gleich. Dies ist die Methode, die CPE verwendet, wenn das Kontrollkästchen „Money-Management“ aktiviert ist."},{"h":"Ausgearbeitetes Beispiel (1000-Dollar-Übungskonto)","t":"Konto 1000 $. Risiko 1 % = 10 $. Eintrag 100, Stopp 98. Abstand = 2 %. Größe = 10 ÷ 0,02 = 500 $ Nominalwert. Wenn der Stop erreicht wird, beträgt der Verlust etwa 10 $, nicht 500 $. Wenn der Preis 103 erreicht (das 1,5-fache des Risikos), beträgt der Gewinn etwa 15 $. Dieselbe Idee bei jedem Paar: Der gefährdete Dollar bleibt bei etwa 1 %, die Münzmenge ändert sich."},{"h":"Was CPE mit der Zecke macht","t":"Jetzt handeln → Automatisch: Aktivieren Sie „Geldverwaltung verwenden“. Automatische Konfiguration speichern. Jeder neue Auto-Trade verbraucht dann etwa 1 % eines Übungskontos von 1.000 US-Dollar plus geschlossene Ergebnisse, berechnet aus dem Einstieg dieses Signals und SL. Spot- und Futures-Mindestbeträge werden eingehalten: Wenn das Börsenminimum ein Risiko von mehr als 1 % mit sich bringen würde, wird dieser Handel übersprungen. Nach etwa −2 % am Kalendertag bleiben Neuwagen bis zum nächsten Tag stehen. Höchstens etwa 3 % aller offenen Geschäfte sind gefährdet. Manueller Handel hat das gleiche Häkchen. Im Signalverlauf wird immer noch der gleiche 10-Dollar-Test und darunter die 1 %-Plangröße für ein 1000-Dollar-Konto angezeigt, sodass Sie beides sehen können."},{"h":"Teilgewinn und die Spur","t":"Die Übung besteht darin, beim ersten Ziel (oftmals bei etwa der Hälfte) abzuspringen und den Rest nachlaufen zu lassen. Wenn sich der Stopp nach oben bewegt, kann sich auch das Ziel bewegen, sodass ein Gewinner mehr zahlen kann als das erste Ziel. Das Risiko für die ursprüngliche Idee erhöht sich nicht. Ein starkes Signal ist kein Grund, 5 % zu riskieren. Es werden die gleichen 1 % verwendet. Der Weg ist es, der einen starken Gewinner wachsen lässt."},{"h":"Täglicher Halt und offene Hitze","t":"Eine verwendete Regel: Wenn der Tageswert um etwa 2 % des Kontos sinkt, hören Sie auf, Geschäfte zu eröffnen. Drei offene Ideen mit jeweils 1 % ergeben etwa 3 % Hitze. Fünf korrelierte Münzen sind eine Wette, nicht fünf. Zähle sie zusammen."},{"h":"Was diese Methode ablehnt","t":"Martingale (Verdoppelung nach einer Niederlage) wird nicht verwendet. Das Verschieben des Anschlags weiter, um ihm nach dem Eintritt „Raum zu geben“, wird nicht verwendet. All-in bei einem „sicheren“ Signal wird nicht verwendet. Wenn es keinen gültigen Stop gibt, gibt es keine Größe, also findet kein Handel statt."},{"h":"Risiko pro Trade","t":"Allgemeine Regel: Riskieren Sie nur ca. 0,5–1 % des Kontokapitals für eine einzelne Idee. Üben Sie auf der DEMO die gleiche prozentuale Gewohnheit wie LIVE."},{"h":"Formel für die Positionsgröße","t":"Größe ≈ (Konto × Risiko%) ÷ (Eintritt − Stoppdistanz). Breiteres SL → kleinere Größe. Wählen Sie niemals zuerst die Größe und dann SL."},{"h":"Risiko: Belohnung","t":"Bevorzugen Sie beim Lernen Ideen, bei denen potenzieller Gewinn ≥ Risiko ist (z. B. 1:1,5 oder besser). Bei TP1 skalieren, sodass Läufer „freies Risiko“ haben."},{"h":"Teilweiser Take-Profit","t":"CPE-Stil: TP1 sperrt einen Teil des Gewinns, TP2 / Trail für den Rest. Banking-Partials reduzieren emotionale Panik."},{"h":"Nachgestelltes TP + SL","t":"KAUFEN: Die Spur steigt, wenn der Preis steigt. VERKAUFEN: Spur nach unten. Trailing-Sperren eröffnen den Gewinn, ohne dass ein perfekter Exit-Call erforderlich ist."},{"h":"Tägliches/wöchentliches Verlustlimit","t":"Beispielregel: Stoppen Sie den Handel für den Tag nach dem −2 %-Konto. Rachesitzungen nach einem Verlustlimit sind Accountkiller."},{"h":"Spot-Größe","t":"Spot-Min-Nominale sind wichtig (z. B. Wechselkurs-Minen). Wenden Sie weiterhin Risiko% an: Wenn die Mindestgröße im Vergleich zu Ihrem SL ein zu hohes Risiko darstellt, überspringen Sie den Handel."},{"h":"Futures / Leverage","t":"Leverage vervielfacht sowohl Gewinn als auch Verlust. Hohe Hebelwirkung + breiter SL = Konto gesprengt. Bevorzugen Sie beim Lernen eine geringe Hebelwirkung; Isoliert kann der Verlust pro Position begrenzt werden."},{"h":"Korrelation","t":"5 korrelierte BTC-Alternativen eröffnen = eine große Wette, nicht fünf. Zählen Sie das Risiko als Gruppe."},{"h":"Gebühren und Slippage","t":"Straffe Kopfhaut sieht auf dem Diagramm gut aus, aber Gebühren fressen R:R. Bevorzugen Sie sauberere Schaukeln auf DEMO, bis Sie die Kosten kennen."},{"h":"DEMO → LIVE-Brücke","t":"CPE-DEMO-Praxis (~3 Monate Denkweise): gleiche Journalregeln, gleicher Prozentsatz. Wenn Sie LIVE sind, beginnen Sie in den ersten Wochen mit halber DEMO-Größe."},{"h":"API-Geldsicherheit","t":"Auszahlungen AUS bei jeder Taste. Live erst nach OK des Testkontos auf der passenden Plattform. Falsches Plattformgeheimnis = fehlgeschlagene oder gefährliche Operationen."},{"h":"Fehler","t":"Martingal (doppelt nach Verlust); SL weiter bewegen; All-in bei „sicheren“ Setups; Ignorieren von Mindestgröße vs. Risiko %; Handel ohne täglichen Stop."},{"h":"Checkliste für die Praxis","t":"① Risiko % geschrieben ② Größe aus SL-Distanz ③ TP1/TP2/Trail geplant ④ Maximaler täglicher Verlust bekannt ⑤ Papier zuerst ⑥ Journal PnL ehrlich."}]},{"id":"psych","title":"5 · Psychologie für den Handel","summary":"Die Denkweise entscheidet darüber, ob BB-/RSI-/Fib-Fähigkeiten echte Screenings überleben. FOMO, Rache, Selbstüberschätzung, Angst – trainieren Sie diese auf DEMO-ähnlichen Indikatoren.","lessons":[{"h":"Warum Psychologie wichtig ist","t":"Ein perfekter BB+RSI-Plan scheitert, wenn Sie früh einsteigen, SL überspringen oder einen Revanche-Trade durchführen. Fähigkeit = System × Disziplin."},{"h":"Prozess über Vorhersage","t":"Sie müssen die Zukunft nicht vorhersagen. Sie müssen Regeln ausführen: Setup → Risiko → Verwalten → Journal. Die Ergebnisse variieren; Der Prozess ist kontrollierbar."},{"h":"FOMO","t":"Angst, etwas zu verpassen = Jagd nach grünen Kerzen, die bereits weit von der BB/Fib-Zone entfernt sind. Regel: Wenn Sie den Eintrag verpasst haben, warten Sie auf das nächste Setup. Chart Lab hat immer eine weitere Kerze."},{"h":"Rachehandel","t":"Nach einem Verlust zerstört der Drang, „es jetzt zurückzugewinnen“, Konten. Obligatorische Abkühlung: Weggehen, Verlust protokollieren, nächster Handel nur, wenn die Checkliste sauber ist."},{"h":"Selbstüberschätzung nach Siegen","t":"3 Siege in Folge ≠ 5-fache Vergrößerung. Halten Sie den Risikoprozentsatz fest. Bei einer Siegesserie brechen die meisten Menschen die Geldregeln."},{"h":"Angst nach Verlusten","t":"Das Überspringen jedes gültigen Setups nach einem roten Tag ist ebenfalls voreingenommen. Vertrauen Sie dem schriftlichen Plan; Reduzieren Sie die Größe bei Bedarf vorübergehend, brechen Sie den Vorgang nicht ab."},{"h":"Analyselähmung","t":"10 Indikatoren stimmen nicht überein → einfrieren. Bleiben Sie beim CPE-Kern: Kerzen + BB + RSI (+ Fib-Zone). Qualität vor Quantität der Werkzeuge."},{"h":"Neigung & Neuigkeiten","t":"Große rote Kerzen in den Nachrichten sorgen für Adrenalin. Bevorzugen Sie Stillstand bei großen Unbekannten bis zu Strukturreformen – das Ego will handeln; Plan braucht Geduld."},{"h":"Journal = Therapie + Daten","t":"Schreiben Sie Emotions-Tags (FOMO, Rush, Calm) in das CPE Journal. Gefühlsmuster offenbaren Lecks schneller als PnL allein."},{"h":"Schriftliche Regeln","t":"Wenn es nicht geschrieben steht, ist es keine Regel. Beispiel: „Nur BB+Kerze+RSI; Risiko 1 %; kein Handel nach −2 % Tag; DEMO bis Checkliste 20 Papiere.“"},{"h":"Umwelt","t":"Schlaf, Hunger und Ablenkung durch das Telefon verändern Entscheidungen. Größer nicht größer werden, wenn du erschöpft bist. Trading ist sportlich – schützen Sie das Gehirn."},{"h":"Sozialer Lärm","t":"Telegram-„Signale“ und Hype machen Ihren Plan zunichte. CPE-Lernklasse + Ihr Tagebuch > zufällige Tipps. Filtern Sie News & Tricks als Kontext, nicht als Bestellungen."},{"h":"Identitätsverschiebung","t":"Denken Sie: „Ich folge meiner Checkliste“ und nicht: „Ich muss Recht haben.“ Es ist normal, bei geringem Risiko falsch zu liegen. Sturheit mit großem Risiko ist optional."},{"h":"DEMO als Fitnessstudio","t":"Verwenden Sie DEMO/Paper, um Emotionen sicher zu proben. Wenn Sie die Regeln in DEMO nicht befolgen können, wird LIVE die Disziplin nicht auf magische Weise beheben."},{"h":"Checkliste für die Praxis","t":"① Bin ich ruhig? ② Checkliste vollständig? ③ Risiko % unverändert? ④ Keine Rache? ⑤ Werde ich ehrlich Tagebuch führen? Wenn ja, NEIN → kein Handel."}]},{"id":"signals","title":"6 · CPE-Signale – Bedeutung und was zu tun ist","summary":"Spot-/Futures-/Forex-Desks zeigen KAUFEN · VERKAUFEN · HALTEN + Punktestand. Gleiche Engine-Idee auf jeder Plattform – Sie handeln jedoch nur auf der Plattform, deren API-Schlüssel Sie gespeichert haben. Hier ist die Bedeutung jedes Signals und die genauen Schritte nach seinem Erscheinen.","lessons":[{"h":"Woher die Signale kommen","t":"CPE bewertet BB, RSI, Fibonacci, Candlestick, EMA Cross, SMA50, MACD und Momentum. Punktestand ≥ +3 → KAUFEN. Punktzahl ≤ −3 → VERKAUFEN. Zwischendurch → HALTEN. Hierbei handelt es sich um eine Hilfsbewertung – kein Gewinnversprechen."},{"h":"KAUFEN-Signal – Bedeutung","t":"Der bullische Zusammenfluss ist derzeit stärker (Beispiele: niedrigerer BB-Absprung, überverkaufter RSI-Trend, bullische Kerze, goldenes Kreuz, Fib-Unterstützung). Die vorgeschlagenen TP1 / TP2 / SL erscheinen in der Zeile / Chart Lab / Trade Now."},{"h":"SELL-Signal – Bedeutung","t":"Der bärische Zusammenfluss ist stärker (oberes BB / überkaufter RSI / bärische Kerze / Todeskreuz / Fib-Widerstand). On Spot bedeutet VERKAUF normalerweise nur dann den Ausstieg/die Reduzierung von Long- oder Short-Positionen, wenn Ihr Markt Short-Positionen zulässt (Futures/Forex)."},{"h":"HOLD-Signal – Bedeutung","t":"Gemischte oder schwache Bewertung. Erzwingen Sie KEINEN Handel. Flach ist richtig. Beobachtungsliste ★ und warten Sie auf einen klareren KAUF/VERKAUF oder einen BB-niedrigeren Kandidaten."},{"h":"Punktezahl","t":"Höhere |Punktzahl| = mehr Übereinstimmung zwischen den Tools. Ein KAUF +5 ist stärker als ein KAUF +3 – wird bei Chart Lab-Kerzen vor der Größe immer noch bestätigt."},{"h":"BB Unterbrett","t":"Separate Liste von Paaren, die das untere Bollinger-Band markieren – lange Kandidaten üben. Kerze + RSI müssen noch bestätigt werden; Nicht jede untere Berührung ist ein Einstieg."},{"h":"Plattform vs. Signal (wichtig)","t":"Signalmathematik ist die gleiche Idee bei Binance, Bybit, OKX, KuCoin, Bitget, Gate, MEXC, Kraken, Coinbase, OANDA, FXCM, MT5, Forex Demo. Was sich ändert, ist, wohin Sie die Bestellung senden: nur die Plattform, die unter API-Schlüssel/Jetzt handeln ausgewählt wurde. Ein Binance-KAUF öffnet sich nicht auf Bybit."},{"h":"Crypto Spot-Plattformen","t":"Binance Spot, Coinbase usw.: KAUFEN = den Coin mit Kurs kaufen (z. B. USDT). VERKAUFEN = Bestände verkaufen / Gewinn mitnehmen. Die Mindestgröße (z. B. ~11 $) ist wichtig. Keine Hebelwirkung."},{"h":"Krypto-Futures-Plattformen","t":"Binance Futures, Bybit, OKX, Bitget…: KAUFEN = long; VERKAUFEN = kurz. Wählen Sie Kreuz/Isoliert + Hebelwirkung sorgfältig aus. Trail: BUY verfolgt TP+SL nach oben; VERKAUF sinkt."},{"h":"Forex-Plattformen","t":"OANDA / FXCM / MT5 / Forex Demo: gleiche KAUFEN/VERKAUFEN/HALTEN-Kennzeichnungen für FX-Paare (EURUSD…). KAUFEN = Basiswährung kaufen; SELL = Verkaufsbasis. Lots (z. B. 0,01) statt Münzmenge. Sitzungen und Nachrichten sind wichtiger."},{"h":"Wenn ein KAUF angezeigt wird, tun Sie Folgendes","t":"① Öffnen Sie die Zeile → lesen Sie Warum / Kerze / RSI. ② Kartenlabor bestätigen (15 m–1 Std.). ③ DEMO zuerst: Jetzt handeln → TP1/TP2/SL/Trail einstellen → Demo/Paper starten. ④ Erst nach API-Test OK auf dieser Plattform → klein LIVE. ⑤ Journalergebnis."},{"h":"Wenn ein VERKAUF angezeigt wird, tun Sie Folgendes","t":"① Wenn Sie einen Long-Spot haben: Erwägen Sie TP / Partial Close / Trail – ignorieren Sie ihn nicht. ② Wenn Futures/Forex und Plan Short erlauben: Bestätigen Sie Chart Lab, dann Paper/Live Short mit SL. ③ Wenn HOLD gestern besser war, rächen Sie sich nicht an der Flip-Größe."},{"h":"Wenn HOLD angezeigt wird, führen Sie dies aus","t":"Kein neuer manueller Eintrag. Scannen Sie weiter. ★ Merkliste hinzufügen. Lernkurs / Diagrammlabor. Schützen Sie offene Positionen nur dann mit Trail, wenn Sie sich bereits in einem Trade befinden."},{"h":"Auto Trade + Signal","t":"Der automatische KAUF kann geöffnet werden, wenn die BB-Regeln für niedrigere + starke Scores mit Ihrer gespeicherten automatischen Konfiguration übereinstimmen. Immer noch DEMO-Test Auto zuerst. LIVE Auto = echtes Risiko – Auszahlungen AUS, geringe Größe."},{"h":"Benachrichtigungen","t":"KAUFEN Signal-Toasts folgen Ihrer Sprache. Behandeln Sie sie als Benachrichtigungen zum Öffnen des Schalters – und nicht als eigenständige Marktaufträge."},{"h":"Was man NICHT tun sollte","t":"Kaufen Sie nicht jeden KAUF ohne Diagramm. Verwenden Sie auf Bybit keinen Binance-Schlüssel. Überspringen Sie SL nicht. Erhöhen Sie die Größe nicht nach einem grünen Signal. Handeln Sie HALTEN nicht als „fast KAUFEN“."},{"h":"Schnelle Aktionskarte","t":"Signal → Diagrammlabor → Risiko % → TP1/TP2/SL → DEMO-Papier → Journal → (später) LIVE auf passendem Plattformschlüssel."}]},{"id":"forex_sig","title":"7 · Forex-Signale – Bedeutung und was zu tun ist","summary":"Forex Desk verwendet für FX-Paare das gleiche KAUF-/VERKAUF-/HALTEN-Rating. Erfahren Sie, wie sich Forex-Signale von Krypto unterscheiden und erfahren Sie die genauen Schritte unter Signal → Papier → Live-Broker.","lessons":[{"h":"Forex Desk-Signale","t":"EURUSD, GBPUSD, USDJPY ... erhalten Sie KAUFEN / VERKAUFEN / HALTEN + Punkte wie bei Krypto. Klicken Sie auf eine Zeile, um ein Diagramm, einen Psychologietext und empfohlene Stufen anzuzeigen."},{"h":"KAUFEN auf Forex – Bedeutung","t":"Kaufen Sie die Basiswährung (z. B. EURUSD KAUFEN = EUR vs. USD kaufen). Erwarten Sie einen Preisanstieg. Verwenden Sie das Chart Lab Forex-Intervall, das Sie üben (15 m/30 m/1 Stunde)."},{"h":"VERKAUFEN auf Forex – Bedeutung","t":"Verkaufen Sie die Basis (Leerverkauf des Paares). Erwarten Sie einen Preisrückgang. Stellen Sie SL immer über der Struktur/oberen Bandidee ein."},{"h":"HALTEN Sie Forex","t":"Keine klare Kante – überspringen. Vor allem vor großen Nachrichten (NFP, CPI, Zentralbank) bevorzugen Sie HOLD/Flat."},{"h":"Plattform für Forex-Demokurse","t":"Kein API-Schlüssel. Nur Übungstabellen + Papier. Perfekt für Lernübungen vor der Live-Übertragung von OANDA/FXCM/MT5."},{"h":"OANDA-Signal → Aktion","t":"① Forex Desk KAUFEN/VERKAUFEN. ② Chart Lab bestätigen. ③ API-Schlüssel → OANDA-Token + Konto-ID → Test. ④ DEMO-Papier zuerst in CPE. ⑤ Kleine Live-Lots (0,01 Mindset) mit TP/SL/Trail."},{"h":"FXCM / MT5","t":"Gleicher Signalwert. Verbinden Sie die Anmeldeinformationen dieses Brokers unter API-Schlüssel. Signal meldet sich für Sie nicht automatisch bei MT5 an, bis Schlüssel/Brücke festgelegt sind – üben Sie Paper, bis der Test OK ist."},{"h":"Sitzungen","t":"Die Überschneidung zwischen London und New York bewegt die Majors oft stärker. In Asien ist es vielleicht ruhiger – HOLD ist weit verbreitet und gesund."},{"h":"Verbreitung & Neuigkeiten","t":"Bei Nachrichten weiten sich die Spreads aus – ein guter technischer KAUF kann immer noch eine schlechte Füllung sein. Schauen Sie sich Neuigkeiten und Tricks an; Warten Sie, bis die Kerze nach dem Anstieg geschlossen wird."},{"h":"Lots vs. Kryptomenge","t":"Forex-Größe = Lots, nicht der fiktive USDT-Wert auf die gleiche Weise. Risiko % gilt immer noch: breitere SL → kleinere Lose."},{"h":"BB niedriger auf Forex","t":"Gleiche Idee: Paar in der Nähe des unteren Bandes + Hammer + steigender RSI = langes Lernen üben. Bestätigen Sie einen höheren TF-Bias (4 Stunden/täglich)."},{"h":"Wenn Forex BUY ausgelöst wird – Schritte","t":"① Lesen Sie Warum. ② Höhere TF-Vorspannung in Ordnung? ③ Markieren Sie SL hinter Docht/Struktur. ④ Papierhandel. ⑤ Wenn der Live-Broker bereit ist → winzige Größe + Spur. ⑥ Journalsitzung (London/NY) + Emotion."},{"h":"Wenn Forex SELL ausgelöst wird – Schritte","t":"① Bestätigen Sie, dass der Anstieg nicht mitten in den Nachrichten erfolgt. ② Chart Lab bärische Kerze. ③ Papier kurz oder lang schließen. ④ Trail nach unten, wenn kurz. ⑤ Verdoppeln Sie nicht das Los nach einem Fehlschlag."},{"h":"Unterschied zwischen Forex und Krypto","t":"Krypto rund um die Uhr; Forex hat Sitzungen. Krypto min $ oft; Forex-Lots + Pip-Wert. Viele Krypto-Alternativen korrelieren; Forex-Majors-Reiniger zum Lernen."},{"h":"Übungscheckliste (FX)","t":"① Paar-Dur? ② Sitzung in Ordnung? ③ Nachrichten klar? ④ Signal KAUFEN/VERKAUFEN nicht HALTEN? ⑤ Diagramm bestätigen? ⑥ Risiko %? ⑦ Papier → Journal → Live-Broker-Schlüssel nur, wenn bereit."}]},{"id":"fomo","title":"8 · FOMO und emotionale Disziplin","summary":"FOMO, Rache, Gier und Angst sind die wahren Kontokiller – keine Indikatoren. Lernen Sie die Auslöser, die Körperzeichen und die genauen Regeln kennen, die Impulsgeschäfte von Ihrem Konto fernhalten.","lessons":[{"h":"Was FOMO wirklich ist","t":"FOMO = die Angst, einen Zug zu verpassen, der bereits weit von Ihrer Zone entfernt ist. Das führt dazu, dass man zu spät mit einem schlechteren Preis und ohne richtigen SL einsteigt. Die Kerze, die Sie „verpasst“ haben, ist eine Information, kein Verlust."},{"h":"Die drei FOMO-Auslöser","t":"① Eine große grüne oder rote Kerze auf dem Chart. ② Ein Freund- oder Telegram-Beitrag, der den Gewinn zeigt. ③ Eine Schlagzeile. Beachten Sie den Auslöser, bevor Sie den Eintrag bemerken."},{"h":"Körperzeichen","t":"Schneller Herzschlag, sich zum Bildschirm beugen, den Drang verspüren, auf „Jetzt kaufen“ zu klicken und die Checkliste zu überspringen. Wenn Sie diese spüren, schließen Sie die Lasche und warten Sie eine Kerze."},{"h":"Die Regel „bereits ausgeführt“.","t":"Wenn sich der Preis um mehr als etwa 1 ATR über Ihren geplanten Einstieg hinaus bewegt hat, ist der Handel beendet. Warten Sie auf einen Pullback auf BB Mitte/Fib oder überspringen Sie ihn. Es gibt immer ein anderes Setup."},{"h":"Die grüne Kerzenfalle","t":"Ein Marubozu, den Sie nicht geplant haben, ist eine Verfolgungsjagd, kein Einstieg. Späte Einstiege haben das schlechteste Chancen-Risiko-Verhältnis, da der Stopp weit entfernt endet."},{"h":"Rachehandel","t":"Nach einer Niederlage möchte das Gehirn diese nun zurückgewinnen. Regel: 15–30 Minuten nach einem Verlust kein neuer Eintrag und nur dann, wenn die Checkliste sauber ist. Der Markt schuldet Ihnen nichts."},{"h":"Angst, den Abzug zu betätigen","t":"Das gegenteilige Problem: Es erscheint ein perfektes Setup und man friert ein. Verwenden Sie eine kleine DEMO-Größe, um den Vorgang zu testen, und legen Sie Ihre Größe fest, BEVOR die Kerze erscheint, damit die Entscheidung bereits getroffen ist."},{"h":"Gier nach Siegen","t":"Durch zwei grüne Trades fühlst du dich unbesiegbar, dann verdoppelst du deine Größe. Halten Sie den Risikoprozentsatz für mindestens 20 Trades fest; Siegesserien bedeuten-zurück."},{"h":"Handel aus Langeweile","t":"Flat ist eine Position. Wenn kein A+-Setup vorhanden ist, lassen Sie nichts geschehen. Langeweile-Trades sind getarnte FOMO."},{"h":"Disziplin während der Bildschirmzeit","t":"Legen Sie zwei oder drei Scanfenster pro Tag fest, anstatt auf Diagramme zu starren. Weniger Entscheidungen bedeuten weniger Impulsentscheidungen."},{"h":"Emotionales Tagebuch","t":"Kennzeichnen Sie jeden Trade als ruhig, gehetzt, FOMO oder Rache. Nach 20 Trades wird das Muster Ihrer Leaks offensichtlich."},{"h":"Ritual zurücksetzen","t":"Nach einem Verlust oder einem FOMO-Ausrutscher: Stehen Sie auf, atmen Sie 10 Mal langsam durch, schreiben Sie einen Satz darüber, was passiert ist, und halten Sie dann eine Stunde lang inne oder fahren Sie mit der Hälfte des normalen Risikos fort."},{"h":"Checkliste für die Praxis","t":"① Ruhiger Körper? ② Auslöser bemerkt? ③ Einrichtung in meiner Zone? ④ SL zuerst geschrieben? ⑤ Risiko % unverändert? ⑥ Keine Rache? Beliebig NEIN → kein Handel."}]},{"id":"risk_deep","title":"9 · Risiko- und Geldmanagement – tiefgründig","summary":"Die Mathematik, die ein Konto am Leben hält: feste Bruchzahl, R-Vielfache, Drawdown-Mathematik, Korrelationshitze und der tägliche Stopp. Verwandeln Sie den Handel in ein Zahlengeschäft.","lessons":[{"h":"Risiko mit festem Bruchteil","t":"Riskieren Sie einen festen Prozentsatz (0,5–1 %) des Eigenkapitals pro Idee. Die Größe ist das ERGEBNIS des Stoppabstands und wird niemals zuerst ausgewählt. Wide SL → kleine Größe; enges SL → größere Größe; Das Dollarrisiko bleibt gleich."},{"h":"Die Größenformel","t":"Größe = (Eigenkapital × Risiko%) ÷ |Einstieg − Stopp|. Beispiel: 1000 $ × 1 % = 10 $ Risiko. Einstieg 100, Stopp 98 → Distanz 2 % → Größe 10 ÷ 0,02 = 500 $ Nominalwert."},{"h":"Denken Sie in R-Vielfachen","t":"Risiko 1R pro Trade. Ein 2R-Gewinner zahlt für zwei Verluste. Verfolgen Sie Ihren durchschnittlichen R über 20 Trades – das ist Ihr tatsächlicher Vorteil, nicht die Gewinnquote."},{"h":"Belohnung: Risiko","t":"Streben Sie vor dem Eintritt ein Potenzial von mindestens 1,5 R an. Überspringen Sie es darunter, es sei denn, Ihre Gewinnquote ist sehr hoch."},{"h":"Drawdown-Mathematik","t":"Ein Drawdown von –50 % benötigt +100 %, um sich zu erholen. Verluststrähnen sind normal: Selbst bei einem System mit einer Gewinnquote von 60 % gibt es Serien mit mehr als 5 Niederlagen. Ein geringes Risiko hält den Streak überlebensfähig."},{"h":"Der tägliche Halt","t":"Harte Regel: Stoppen Sie die Eröffnung von Trades nach −2 % des Eigenkapitals an einem Tag (oder 2–3 Verlusten in Folge). Rachesitzungen nach dem Limit sind Accountkiller."},{"h":"Wöchentliche und monatliche Limits","t":"Begrenzen Sie außerdem die Woche (zum Beispiel −5 %) und den Monat. Wenn Sie darauf klicken, wechseln Sie zu DEMO, überprüfen Sie das Journal und erhöhen Sie die Größe erst nach einem sauberen Lauf."},{"h":"Offene Hitze","t":"Das Gesamtrisiko aller offenen Geschäfte sollte bei etwa 3 % oder weniger bleiben. Fünf korrelierte Alts sind eine Wette, nicht fünf – korrelierte Exposition zusammen zählen."},{"h":"Spot-Größe","t":"Spot hat einen minimalen Nominalwert. Wenn das Umtauschminimum ein Risiko von mehr als 1 % mit sich bringt, überspringen Sie den Handel – runden Sie das Risiko niemals auf."},{"h":"Dimensionierung von Futures","t":"Der Hebel verändert die Marge, nicht das Risiko. Risiko ist immer noch Entry − Stop × Größe. Verwenden Sie beim Lernen eine geringe Hebelwirkung und bevorzugen Sie einen isolierten Spielraum."},{"h":"Forex-Größe","t":"Risiko = Lots × Pip-Wert × Stop-Pips. Nach Losen auflösen. Grober Richtwert: 0,01 Lot ≈ 0,10 $ pro Pip; Ein 20-Pip-Stop riskiert 1 % von 1000 $ (10 $) → 10 ÷ 0,10 ÷ 20 = 0,05 Lots."},{"h":"Skalieren","t":"Nehmen Sie bei TP1 etwa 50 % Rabatt, um den Rest risikofrei zu machen, und ziehen Sie dann nach. Dadurch wird aus einem guten Trade ein Low-Stress-Runner."},{"h":"Compoundierung vs. fest","t":"Riskieren Sie einen festen Prozentsatz des AKTUELLEN Eigenkapitals (Compounding). Begrenzen Sie Ihr Risiko nicht auf die bisher höchste Kontogröße."},{"h":"Gebühren und Slippage in R","t":"Subtrahieren Sie die Gebühren von R. Eine Gebühr von 0,2 % gegenüber einer Gebühr von 0,5 % kann die Kante verwischen – bevorzugen Sie sauberere Schwünge."},{"h":"Das „No Stop, No Trade“-Gesetz","t":"Wenn Sie keinen logischen Stopp definieren können, kennen Sie Ihr Risiko nicht, es gibt also keine Größe und somit keinen Handel."},{"h":"Anti-Martingal","t":"Verdoppeln Sie niemals nach einer Niederlage. Steigern Sie die Größe erst nach mehreren profitablen, disziplinierten Wochen eines bewährten Prozesses – und selbst dann langsam."},{"h":"Checkliste für die Praxis","t":"① Eigenkapital bekannt ② Risiko % geschrieben ③ Stop definiert ④ Größe ab Stop ⑤ Belohnung ≥ 1,5R ⑥ Täglicher Stop bekannt ⑦ Korrelierte Heat gezählt."}]},{"id":"sl_tp","title":"10 · Stop-Loss- und Take-Profit-Beherrschung","summary":"Platzieren Sie den SL dort, wo der Markt Ihnen das Gegenteil beweist, nehmen Sie schrittweise Gewinne mit und verfolgen Sie den Stop, damit ein Gewinner laufen kann – genau das, was CPE mit Multi-TP und einem nachlaufenden SL macht.","lessons":[{"h":"SL ist eine Entscheidung, keine Zahl","t":"Platzieren Sie den Stopp dort, wo die Idee ungültig ist (unter dem Swing-Tief, dem Docht oder der Struktur), und nicht in einem zufälligen Dollarabstand. Sie kaufen Informationen: Wenn der Preis hier steht, ist meine Begründung falsch."},{"h":"Struktur stoppt","t":"Lang: SL direkt unterhalb des Swing-Low- oder Unterband-Dochts. Kurz: knapp über dem Swing-Hoch. Geben Sie einen kleinen Puffer für Ausbreitungs- und Dochtgeräusche ein, etwa 0,1–0,3 %."},{"h":"Die Volatilität hört auf","t":"Größere Märkte benötigen breitere Stopps. Verwenden Sie ATR oder die Dochtlänge, um die Größe des Stopps zu bestimmen, und verkleinern Sie dann die Position, damit das Dollarrisiko gleich bleibt."},{"h":"Warum ein SL mit festem Dollar scheitert","t":"Ein 10-Dollar-Stopp bei BTC und ein 10-Dollar-Stopp bei EURUSD stellen völlig unterschiedliche Risiken dar. Die Entfernung muss in % gemessen werden, nicht in Dollar."},{"h":"Anti-Stop-Hunt-Puffer","t":"CPE ignoriert eine einzelne Dochtberührung: Es benötigt zwei aufeinanderfolgende Durchbrüche plus einen kleinen Puffer (0,15 %), bevor es geschlossen wird. Das verhindert, dass der Lärm Ihren Stopp verfolgt."},{"h":"Nehmen Sie schrittweise Gewinne mit","t":"Schließen Sie niemals 100 % zu einem Preis ab. Scale-out: TP1 bucht einen Teil, dann TP2/Trail fährt den Rest, so dass sich ein großer Schritt für viele Verlierer auszahlen kann."},{"h":"Multi-TP-Ebenen","t":"Mit CPE können Sie so viele TP-Ebenen hinzufügen, wie Sie benötigen, jede mit ihrem eigenen Abschluss-Prozentsatz. Beispiel: TP1 40 %, TP2 30 %, TP3 30 % – oder nehmen Sie TP1 und folgen Sie dem Rest."},{"h":"Hinter dem Stopp","t":"Nach TP1 den Stopp auf Breakeven verschieben; nach TP2 verschieben Sie es nach TP1. Lassen Sie den Stopp dem Preis folgen, damit der offene Gewinn geschützt ist, während der Läufer weitermacht."},{"h":"Den Weg wählen %","t":"Eine enge Spur sichert den Gewinn schnell, endet aber früh; Ein breiter Weg atmet, gibt aber etwas zurück. Beginnen Sie mit etwa 1–2 % für Krypto und passen Sie es im Bearbeitungsmodalitäten „Positionen“ an."},{"h":"Läufer","t":"Wenn sich der Preis in einem starken Trend entlang des Bandes bewegt, erweitern Sie das Ziel und verfolgen Sie es, anstatt alles bei TP2 zu nehmen. So zahlt sich ein Trade für eine ganze Woche aus."},{"h":"Tasten zum teilweisen Schließen","t":"Verwenden Sie die Schaltflächen „50 %/100 % schließen“ in den Positionen zur manuellen Steuerung oder lassen Sie TP/SL automatisch schließen, indem Sie den Plan verwalten."},{"h":"Die Breakeven-Falle","t":"Bewegen Sie den SL nicht zu früh, vor TP1, auf die Gewinnschwelle – normale Pullbacks werden Sie aus guten Trades ausschließen."},{"h":"Erweitern Sie niemals einen Verluststopp","t":"Wenn man den SL weiter entfernt, um ihm mehr Platz zu verschaffen, werden kleine Verluste zu Kontokillern. Der Stopp, den Sie vor der Einreise festlegen, ist der Stopp."},{"h":"Zeitstopp","t":"Wenn ein Trade für viele Kerzen nichts bewirkt, während sich ein deutlich besseres Setup bildet, ist ein flacher Abschluss und eine Neuverteilung des Risikos ein gültiger Ausstieg."},{"h":"Checkliste für die Praxis","t":"① SL bei Invalidierung, nicht zufällig ② Puffer für Dochte ③ TP1 teilweise geplant ④ Spur nach TP1 ⑤ SL niemals verbreitern ⑥ Einen Gewinner laufen lassen."}]},{"id":"plan_journal","title":"11 · Handelsplan und Journaling","summary":"Ein schriftlicher Plan macht den Handel vom Glücksspiel zum Prozess. Lernen Sie den einseitigen Plan, die Pre-Trade-Checkliste und die Protokollierung kennen, damit Ihre Lecks sichtbar werden.","lessons":[{"h":"Warum einen Plan schreiben?","t":"Wenn es nicht geschrieben steht, ist es keine Regel. Ein Plan macht die Entscheidungsfindung unter Stress überflüssig und macht Ihre Ergebnisse messbar."},{"h":"Der einseitige Plan","t":"Paar, Markt, Setup (BB + RSI + Kerze + Fib-Zone), Richtung, Einstieg, SL, TP1 / TP2, Größe (vom SL) und maximaler täglicher Verlust. Wenn eine Zeile leer ist → kein Handel."},{"h":"Checkliste vor dem Handel","t":"Höhere TF-Voreingenommenheit? · Einrichtung in meiner Zone? · Kerze bestätigen? · RSI stimmt zu? · SL geschrieben? · Risiko %? · Belohnung ≥ 1,5R? · Ruhig? Alles ja → Handel."},{"h":"Routine vor der Sitzung","t":"Überprüfen Sie den höheren Zeitrahmen, die wichtigsten Ebenen und Neuigkeiten. Schreiben Sie die heutigen zwei oder drei Uhrenpaare vor der Sitzung – nicht nachdem die Kerze explodiert ist."},{"h":"Was soll ich tagebuchen?","t":"Symbol, Seite, Eingang, Ausgang, Größe, R, Grund, Zeitrahmen, Sitzung und ein Emotions-Tag. CPE Journal speichert GuV und Gründe automatisch; Fügen Sie Ihre eigenen Notizen hinzu."},{"h":"Tagebuch über das WARUM","t":"Notieren Sie, was Sie gesehen haben (Aufbau) und was Sie gefühlt haben (ruhig / FOMO / gehetzt). Ein Ergebnis ohne Kontext lehrt nichts."},{"h":"Verfolgen Sie R, nicht Siege","t":"Zwei Händler mit der gleichen Gewinnquote können gegensätzliche Ergebnisse erzielen. Das durchschnittliche R und der maximale Drawdown sind wichtiger als der Gewinnprozentsatz."},{"h":"Screenshot-Gewohnheit","t":"Speichern Sie den Chart vor und nach jedem Trade. Die Durchsicht von 20 Screenshots zeigt Ihren Vorsprung und Ihre Lecks schneller als jeder andere Indikator."},{"h":"Wöchentlicher Rückblick","t":"Zählen Sie einmal pro Woche Ihre Trades, den durchschnittlichen R, das beste und schlechteste Setup sowie Regelverstöße. Wählen Sie EIN Leck aus, das Sie nächste Woche beheben möchten."},{"h":"Kennzeichnen Sie die Lecks","t":"Häufige Schlagworte: verspäteter Einstieg, kein SL, übergroß, verschobener SL, Rache, Langeweile. Wenn sich ein Tag wiederholt, machen Sie daraus eine harte Regel."},{"h":"Was Sie nicht protokollieren sollten","t":"Protokollieren Sie nicht nur Gewinner. Verluste sind die Daten. Ein Journal, in dem es nur um Siege geht, ist eine Broschüre, kein Tagebuch."},{"h":"Planen Sie den Schritt DEMO → LIVE","t":"Beweisen Sie den Plan auf DEMO für eine festgelegte Anzahl von Trades mit einem positiven durchschnittlichen R, bevor Sie echtes Geld riskieren – und beginnen Sie dann mit der halben Größe."},{"h":"Checkliste für die Praxis","t":"① Plan vor Eintrag geschrieben ② Checkliste bestanden ③ Tagebucheintrag + Emotion ④ Wöchentliche Überprüfung ⑤ Ein Leck behoben."}]},{"id":"leverage","title":"12 · Hebelwirkung, Marge und Liquidation","summary":"Durch die Hebelwirkung vervielfacht sich der Verlust genauso schnell wie der Gewinn. Erfahren Sie mehr über Margin, Liquidation, isolierte vs. Cross-Margin und die Sicherheitsregeln, die verhindern, dass ein Trade das Konto löscht.","lessons":[{"h":"Was Hebelwirkung ist","t":"Mit der Hebelwirkung können Sie eine größere Position mit weniger Marge kontrollieren. Es erhöht sowohl den Gewinn als auch den Verlust – es erhöht nicht Ihren Vorsprung."},{"h":"Marge vs. Risiko","t":"Die Marge ist die Anzahlung, die die Börse sperrt. Risiko ist Einstieg − Stop × Größe. Der Hebel verändert die Marge, niemals Ihr Dollarrisiko."},{"h":"Liquidation","t":"Wenn Verluste Ihre Marge verschlingen, schließt die Börse die Position zwangsweise (Liquidation), oft zum ungünstigsten Zeitpunkt. Halten Sie Ihren Stop weit vom Liquidationspreis entfernt."},{"h":"Isoliert gegen Kreuz","t":"Isoliert begrenzt den Verlust auf die Marge dieser einen Position. Cross nutzt das gesamte Wallet-Guthaben – gefährlicher für Anfänger. Beim Lernen lieber isoliert sein."},{"h":"Sicherere Hebelwirkung","t":"Eine geringe Hebelwirkung (2–5x) plus einem richtigen Stopp ist weitaus sicherer als 50x ohne Stopp. Der Stop, nicht die Leverage-Zahl, ist Ihr Schutz."},{"h":"Die Liquidations-Distanzregel","t":"Überprüfen Sie, ob Ihr SL gut innerhalb des Liquidationspreises liegt. Wenn sie nahe beieinander liegen, reduzieren Sie die Größe, bis ausreichend Platz vorhanden ist."},{"h":"Durch die Hebelwirkung wird ein schlechter Eintrag nicht behoben","t":"Eine hohe Hebelwirkung bei einem schlechten Einstieg verliert einfach schneller. Korrigieren Sie zuerst das Setup und passen Sie es dann an."},{"h":"Finanzierung und Gebühren","t":"Bei Perpetual Futures fallen im Laufe der Zeit Finanzierungskosten an. Langes Zurückhalten von gehebelten Tätern blutet die Finanzierung aus – ein weiterer Grund, bei der Größe und beim Timing sorgfältig vorzugehen."},{"h":"Spot vs. Futures","t":"Spot kann nicht liquidiert werden (Sie besitzen die Münze). Futures können und können auf Null gehen. Verwenden Sie Futures nur mit einem schriftlichen Plan und einer isolierten Marge."},{"h":"Dimensionierung unter Hebelwirkung","t":"Berechnen Sie die Größe anhand des Stoppabstands und prüfen Sie dann, ob der resultierende Spielraum erschwinglich ist. Wählen Sie niemals zuerst die Hebelwirkung."},{"h":"Der „One Trade“-Test","t":"Bevor Sie eintreten, fragen Sie: Wenn es aufhört, ist es ein Achselzucken oder eine Katastrophe? Wenn es kein Achselzucken ist, ist die Größe zu groß."},{"h":"Checkliste für die Praxis","t":"① Isolierter Satz ② Geringe Hebelwirkung ③ SL innerhalb des Liquidationspreises ④ Größe vom Stop ⑤ Kann ich hier einen vollständigen Verlust überleben? ja → Handel."}]},{"id":"practice","title":"13 · Übungsroutine und Backtesting","summary":"Fertigkeiten werden vor der LIVE-Übung auf der DEMO aufgebaut. Lernen Sie eine wiederholbare Übungsschleife, wie Sie durch Scrollen von Diagrammen „Backtests“ durchführen und wie Sie sicher zu echtem Geld gelangen.","lessons":[{"h":"DEMO ist das Fitnessstudio","t":"Paper/DEMO dient dazu, den Prozess und Ihre Emotionen ohne Risiko zu proben. Wenn Sie die Regeln in DEMO nicht befolgen können, wird LIVE das Problem nicht auf magische Weise beheben."},{"h":"Die Übungsschleife","t":"Wählen Sie ein Setup (zum Beispiel BB Lower + Hammer + RSI Turn). Markieren Sie 20 historische Beispiele in der Tabelle. Eintrag / SL / TP definieren. Notieren Sie das Ergebnis. Wiederholen."},{"h":"Manuelles Backtesting","t":"Scrollen Sie im Chart Lab zurück, blenden Sie die Zukunft aus und markieren Sie jedes Signal von Hand. Es trainiert die Mustererkennung und verhindert, dass Sie sich etwas vormachen."},{"h":"Probengröße","t":"Zehn Trades bedeuten nichts. Streben Sie 30–50 aufgezeichnete Trades eines Setups an, bevor Sie es beurteilen."},{"h":"Vorwärtstest auf DEMO","t":"Führen Sie nach der Handmarkierung das gleiche Setup zwei bis vier Wochen lang live auf der DEMO mit den Signalen der Software aus. Vergleichen Sie echte Füllungen und Emotionen mit dem Backtest."},{"h":"Ein Setup nach dem anderen","t":"Testen Sie nicht fünf Systeme gleichzeitig. Meistern Sie eine Kante und fügen Sie dann eine zweite hinzu."},{"h":"Halten Sie die Routine klein","t":"Eine 20-minütige tägliche Routine (Scannen, Markieren, Tagebuch führen, überprüfen) ist besser als sechs Stunden wahlloses Chart-Blicken."},{"h":"Abschluss zu LIVE","t":"Kriterien: positives durchschnittliches R über 30+ DEMO-Trades, Regeln befolgt, keine Rache-Episoden. Dann LIVE mit halber Größe starten und langsam skalieren."},{"h":"Scale-up-Regel","t":"Steigern Sie Ihre Größe nur nach einer festgelegten Anzahl profitabler, disziplinierter Wochen – niemals nach einem großen Gewinn."},{"h":"Wann man einen Schritt zurücktreten sollte","t":"Erreichen Sie das tägliche oder wöchentliche Verlustlimit oder bemerken Sie wiederholte Regelverstöße → kehren Sie zur DEMO zurück und bauen Sie die Disziplin wieder auf, bevor Sie fortfahren."},{"h":"Verfolgen Sie Prozessmetriken","t":"Protokollieren Sie die Erfolgsquote der Checkliste, Regelverstöße pro Woche und den durchschnittlichen R. Diese prognostizieren das Wachstum besser als eine einzelne GuV-Zahl."},{"h":"CPE-Übungspfad","t":"Lernklasse → Chart Lab (Markierungseinstellungen) → Papierhandel → Zeitschriftenrezension → Signaltische auf DEMO → kleiner LIVE auf dem passenden Plattformschlüssel."},{"h":"Checkliste für die Praxis","t":"① Ein ausgewähltes Setup ② 30 markierte Beispiele ③ DEMO-Vorwärtstest ④ Journal + Rezension ⑤ Positives R → halbe Größe LIVE."}]},{"id":"volatility","title":"14 · Volatilität und Martingal","summary":"Wie man die Marktvolatilität erkennt (warum sich der Preis ändert), wie sie jedem Signal als Begründungslinie hinzugefügt wird und wie die optionale Martingale-Leiter funktioniert – und warum sie bei unachtsamer Verwendung der schnellste Weg ist, ein Konto zu verlieren.","lessons":[{"h":"Was Volatilität bedeutet","t":"Bei der Volatilität geht es darum, wie stark sich der Preis bewegt – nicht in welche Richtung. Hohe Volatilität = breite Kerzen und schnelle Schwankungen. Geringe Volatilität = eine ruhige, enge Spanne. Das gleiche Setup weist jeweils eine sehr unterschiedliche Zuverlässigkeit auf."},{"h":"Der CPE-Volatilitätswert","t":"Jedes Signal misst nun die durchschnittliche Kerzenspanne und die Bollinger-Bandbreite und vergleicht sie dann mit dem aktuellen Normalwert dieses Paares. Sie erhalten NIEDRIG / NORMAL / HOCH / EXTREM plus eine klare Begründungszeile – das „Warum“ für die Marktveränderung, angezeigt mit dem Signal."},{"h":"EXTREME Volatilität = Herabstufung","t":"Wenn das Band EXTREM ist, wird ein neues STARK-Signal auf VORSICHT herabgestuft (der Grund wird angezeigt). Auf einem Whipsaw-Markt scheitert das gleiche Muster weitaus häufiger – Fake-Breaks und Stop-Hunt-Dochte sind die Norm."},{"h":"Was tun bei HIGH / EXTREME?","t":"Kleinere Größe. Breiterer Anschlag. Weniger Trades. Warten Sie auf eine abgeschlossene Kerze statt auf einen Spitzenwert in der Mitte der Kerze. Wenn die Anzeige EXTREM lautet, betrachten Sie die Einrichtung als Lernzone und nicht als Einstieg."},{"h":"Was Martingale ist","t":"Martingale erhöht eine Verlustposition, um den durchschnittlichen Einstieg zu senken: Nach jeder Gegenbewegung fügen Sie eine weitere Order hinzu, normalerweise größer (1x, 2x, 4x …). Es gewinnt oft und verliert dann alles in einem schlechten Lauf."},{"h":"Die CPE-Martingale-Regel","t":"CPE fügt nur dann eine zusätzliche Order hinzu, wenn BEIDE wahr sind: (1) Der Preis hat sich um mindestens Schritt × Sprosse % gegen den Handel bewegt und (2) für dieses Paar steht immer noch ein neues Signal auf der gleichen Seite. Es wird nie etwas hinzugefügt, nur weil der Preis gesunken ist."},{"h":"Die vier Zahlen","t":"Schritt % = Vor jedem Hinzufügen ist eine Gegenbewegung erforderlich. Multiplikator = die Größe jedes Adds im Vergleich zur Basis (1 = flach, 2 = doppelt). Max fügt = festes Limit für zusätzliche Bestellungen hinzu. Leiter-Risikoobergrenze % = das Risiko der gesamten Leiter als Prozentsatz des Eigenkapitals. Alle vier stehen Ihnen zur Auswahl."},{"h":"Die Hartkappe schützt Sie","t":"Selbst bei einem großen Multiplikator und vielen Additionen lehnt CPE den Auftrag ab, sobald das Gesamtrisiko der Leiter Ihren maximalen Prozentsatz des Eigenkapitals überschreiten würde. Es respektiert auch die Mindestgröße des Umtauschs und den täglichen -2 %-Stopp."},{"h":"Wo es läuft","t":"Markieren Sie „Manuell“, um diesen einen Trade zu verwalten, oder „Automatisch“, um die automatischen Trades zu verwalten. Sowohl DEMO als auch LIVE. Im manuellen Modus muss das Paar in der Scan-Liste enthalten sein, damit ein neues Signal auf der gleichen Seite gelesen werden kann."},{"h":"Warum die Obergrenze wichtig ist (Beispiel)","t":"Schritt 1 %, Multiplikator 2, drei Additionen auf einer 1 %-Risikobasis: Risiko steigt 1 % → 2 % → 4 % → 8 %. Ein kompletter Stopp auf der letzten Sprosse löscht viele Gewinner aus. Aus diesem Grund gibt es die Obergrenze und die Standardzahlen sind klein."},{"h":"Anti-Martingal-Alternative","t":"Viele Profis machen das Gegenteil: Addieren Sie nur die Gewinner und reduzieren Sie die Verlierer schnell. Es fühlt sich schlimmer an (mehr kleine Verluste), aber es kann das Konto nicht in einem einzigen Trend gegen Sie in die Luft jagen."},{"h":"Das Risiko wird nicht beseitigt","t":"Durch die Reduzierung des Durchschnitts wird das Risiko nicht beseitigt – es verschiebt das Risiko von „vielen kleinen Verlusten“ in „einen großen Verlust“. Fügen Sie niemals Geld hinzu, das Sie nicht verlieren können, und schalten Sie die Obergrenze niemals ab, um einen verlorenen Trade „wiederzugewinnen“."},{"h":"Übungsweg","t":"Erfahren Sie zuerst die Volatilitätswerte auf DEMO. Probieren Sie Martingale mit maximalen Additionen von 1–2 und einem kleinen Multiplikator auf der DEMO für mehr als 30 Trades aus. Protokollieren Sie jede Leiter und entscheiden Sie dann – die meisten Händler finden die Flat-/Anti-Martingal-Methode sicherer."},{"h":"Volatilität + Martingale-Checkliste","t":"① Lesen Sie zuerst das Volatilitätsniveau ab. ② Überspringen oder schrumpfen Sie in EXTREM. ③ Martingale nur mit einem frischen gleichseitigen Signal. ④ Schritt × Sprosse erreicht. ⑤ Unter der Risikoobergrenze → hinzufügen. Irgendein „nein“ → nein hinzufügen."}]},{"id":"lab_indicators","title":"15 · Chart-Lab-Indikatoren (Stoch · ADX · Ichimoku · VWAP)","summary":"Chart Lab verfügt jetzt über eine vollständige Anzeigeleiste – jede Schaltfläche ist ein Ein-/Aus-Häkchen, das das Diagramm sofort neu zeichnet. Neben BB / RSI / MACD / EMA / SMA50 / Volumen erhalten Sie jetzt Stochastic, ADX/DMI, Ichimoku und VWAP, und die Signal-Engine liest diese auch – nicht nur den Chart.","lessons":[{"h":"Wo die Bar ist","t":"Diagrammlabor → die Schaltflächenreihe „Indikatoren“ unter dem Diagramm. Ein Klick schaltet eine Anzeige ein, der nächste Klick schaltet sie aus; Das Diagramm wird sofort neu gezeichnet. Die Zecken sind sichtbar UND versorgen die Signalmaschine."},{"h":"Stochastisch (14,3,3)","t":"%K / %D-Oszillator unter den Kerzen gezeichnet, Skala 0–100. Über ~80 = überkaufter Bereich, unter ~20 = überverkaufter Bereich. Der Anstieg von %K durch %D im überverkauften Bereich ist eine bullische Studie; Ein Kreuz nach unten an der Spitze ist bärisch. Bei einem starken Trend kann es lange Zeit an einem Ende hängen bleiben – immer mit BB und der Kerze kombinieren."},{"h":"ADX / DMI (14)","t":"ADX misst die Trendstärke, nicht die Richtung. Über ~25 = ein echter Trend läuft; unter ~20 = ein unruhiger Bereich. +DI oben −DI = verantwortliche Käufer; −DI oben +DI = verantwortliche Verkäufer. Verwenden Sie ADX, um zu entscheiden, ob Sie überhaupt einen Trendhandel durchführen oder flach bleiben möchten."},{"h":"Ichimoku-Wolke (9,26,52)","t":"Tenkan (schnelle Linie), Kijun (langsame Linie) und die Senkou-Wolke. Preis über einer steigenden Wolke = bullischer Hintergrund; unter einer fallenden Wolke = bärisch. Eine Tenkan/Kijun-Kreuzung innerhalb der Wolke ist schwach; Ein Kreuz, bei dem der Preis die Wolke verlässt, ist stärker. Der Wolkenrand selbst fungiert oft als Unterstützung/Widerstand."},{"h":"VWAP","t":"Volumengewichteter Durchschnittspreis – der nach Volumen gewichtete Durchschnittspreis, der bei jeder Sitzung zurückgesetzt wird. Große Institutionen orientieren sich daran. Preis über einem steigenden VWAP = Käufer haben die Kontrolle; Eine klare Ablehnung des VWAP während eines Abwärtstrends ist eine kurze Studie. Bei 24/7-Kryptowährungen wird das Zurücksetzen anders durchgeführt als bei Devisen – betrachten Sie es als Richtlinie, nicht als Gesetz."},{"h":"Wie der Motor sie nutzt","t":"Jeder neue Indikator fügt dem Score eine kleine Bestätigung auf der Seite hinzu, auf die er zeigt (Stochastic, Ichimoku, VWAP, ADX, wenn er mit der Richtung übereinstimmt, und Elliott). Es handelt sich um Bestätigungen, nicht um Auslöser – wenn sie mit BB/RSI/der Kerze nicht übereinstimmen, wird die Bewertung einfach uneinheitlicher und Sie erhalten mehr HOLD."},{"h":"Warum VORSICHT strenger wurde","t":"Da es nun mehr Checks im Pool gibt, wurde die VORSICHT-Leiste verschärft: Es sind Punkte ≥ 4 UND mindestens 3 übereinstimmende Checks erforderlich. Dadurch wird verhindert, dass die App Sie mit schwächeren Signalen überflutet, nur weil mehr Tools aktiviert sind."},{"h":"Eine Lesereihenfolge, die funktioniert","t":"① Höhere TF-Richtung (Ichimoku-Wolke + ADX). ② Wo der Preis ist (BB / Fib / VWAP). ③ Momentum (RSI + Stochastik). ④ Kerzenbestätigung. ⑤ Risikoprozentsatz und -niveaus geschrieben → Papier zuerst."},{"h":"Fehler, die es zu vermeiden gilt","t":"Ich schalte jeden Blinker ein und starre auf einen Regenbogen; Verwendung von ADX als Richtung (es ist nur Stärke); Shorting nur, weil die Stochastik innerhalb eines Bullenlaufs >80 ist; Dabei wird ignoriert, dass VWAP bei Krypto und FX unterschiedliche Bedeutungen hat."},{"h":"Checkliste für die Praxis","t":"① Bias aus der Cloud + ADX ② Standort aus BB / Fib / VWAP ③ Momentum aus RSI + Stoch ④ Kerze bestätigt ⑤ SL / TP geschrieben ⑥ Papier, dann Journal."}]},{"id":"elliott","title":"16 · Elliott-Welle (Lichtzahl)","summary":"CPE umfasst einen leichten Elliott-Wave-Zähler. Kreuzen Sie „Elliott“ in der Chart Lab-Indikatorleiste an und es markiert den letzten 0-1-2-3-4-5-Impuls auf den Kerzen und projiziert ein Fibonacci-Wellen-5-Ziel. Es ist ein Lernwerkzeug – keine Kristallkugel.","lessons":[{"h":"Die Idee in einer Zeile","t":"Märkte bewegen sich in Wellen: Impulse (5 Beine in die Trendrichtung) und Korrekturen (3 Beine dagegen). CPE zählt nur den Impuls, also den Teil, der den Trend trägt."},{"h":"Wie CPE es zählt","t":"Es findet die letzten Schwung-Pivots (3-Balken-Fraktale), wechselt hoch/tief und testet die letzten 5–6 Schwünge anhand der Elliott-Regeln. Wenn die Form passt, werden die Beschriftungen 0→5 (die noch laufende Welle in Gelb) und eine W5-Ziellinie gezeichnet, die aus der Länge von Welle 1 × 1,618, gemessen an Welle 4, erstellt wird."},{"h":"Die Regeln, die es überprüft","t":"Welle 2 überschreitet den Beginn von Welle 1 nicht; Welle 4 überschneidet sich nicht mit dem Gebiet von Welle 1; Welle 3 ist nicht die kürzeste von 1 / 3 / 5. Wenn eine Regel fehlschlägt, wird nichts angezeigt – keine erzwungene Zählung."},{"h":"Bullisch vs. bärisch","t":"Ein steigender Wert von 0-1-2-3-4-5 ist ein bullischer Impuls; Das Spiegelbild auf dem Weg nach unten ist bärisch. Die Engine fügt dem Ergebnis auf der Wellenseite eine kleine Bestätigung hinzu."},{"h":"Live vs. vollständig","t":"Eine LIVE-Welle 5 (die noch läuft) gilt als Trendfortsetzung. Ein VOLLSTÄNDIGER Impuls (0–5 abgeschlossen) warnt davor, dass der Trend ermüdend sein könnte – oft folgt eine Korrektur."},{"h":"Die W5-Ziellinie","t":"Eine Fibonacci-Erweiterung von Welle 1 vom Tief/Hoch der Welle 4. Es handelt sich um eine Zielidee, nicht um einen Magneten – der Preis kann darunter stehenbleiben oder darüber hinausschießen."},{"h":"Wie man es benutzt","t":"Betrachten Sie die Zählung als Konfluenz: Bei einer klaren BB/Fib-Zone mit einer Kerze und einem RSI sorgt eine impulsive Zählung für zusätzliche Überzeugung. Für sich genommen ist es nur eine Skizze."},{"h":"Fehler, die es zu vermeiden gilt","t":"Die Wellen erneut zählen, bis sie zu Ihrer Position passen (die klassische Elliott-Sünde); kleine Bewegungen zählen; Ignorieren der höheren Zeitrahmenanzahl; Vergessen Sie, dass sich die Zählung jedes Mal ändert, wenn ein neuer Balken gedruckt wird."},{"h":"Checkliste für die Praxis","t":"① Klare Schwünge ausgewählt ② Regeln erfüllt ③ Zick-Zack stimmt mit BB/Fib überein ④ Kerze bestätigt ⑤ SL jenseits des Welle-4-Ungültigkeitspunkts."}]},{"id":"forecast","title":"17 · 3-Monats-Prognose (das Häkchen „Prognose 3 Monate“)","summary":"Der Langzeithorizont-Projektor: Wie sich dieses Diagramm in den nächsten ca. 3 Monaten voraussichtlich bilden wird, basierend auf dem eigenen Trend, den Zielen und der Volatilität des Signals. Schalten Sie es mit dem Häkchen „Prognose 3M“ im Chart Lab ein oder aus.","lessons":[{"h":"Was es zeichnet","t":"Ein gestrichelter Mittelpfad, der vom analysierten Eintrag zum besten Ziel verläuft, das die Engine bereits kennt (Elliott-Ziel → tp2 → tp1), umhüllt von einem sich erweiternden „Kegel“, der die Spanne plausibler Preise zeigt. Die Monatsmarkierungen M+1 / M+2 / M+3 teilen den Horizont."},{"h":"Warum ein Kegel und keine Linie","t":"Niemand kann einen genauen zukünftigen Preis kennen. Der Kegel weitet sich mit der Quadratwurzel der Zeit und der eigenen Volatilität des Paares aus, sodass ein ruhiges FX-Paar einen schmalen Kegel und ein wilder Altcoin einen sehr breiten Kegel erhält. Diese Breite IST die Botschaft: Je weiter man hinausschaut, desto unsicherer ist der Preis."},{"h":"Woher die Zahlen kommen","t":"Die Drift kommt vom aktuellen Signalziel; Die tägliche Volatilität ergibt sich aus dem ATR-Prozentsatz des Signals, skaliert auf einen Tag, sodass der Kegel auf einem 5-Meter- oder einem 1-Tages-Chart dasselbe bedeutet. EXTREME/HOHE Volatilität weitet es weiter aus."},{"h":"Wie man es liest","t":"Schauen Sie sich die Steigung (in welche Richtung der Weg verläuft) und die Breite (wie viel Zweifel) an. Ein steigender Pfad mit schmalem Kegel = eine stabilere Trendidee; ein flacher Weg mit einem riesigen Kegel = „hier gibt es keine Kante, man muss mit Lärm rechnen“."},{"h":"Ein- und Ausschalten","t":"Die Schaltfläche „Prognose 3M“ befindet sich neben „Zukunftsraum“. Es muss der Zukunftsraum aktiviert sein (der leere Bereich auf der rechten Seite, in den die Projektion eingezeichnet wird). Wenn das Signal HALTEN ist, gibt es keine Richtung, es wird also nichts gezeichnet."},{"h":"Es ist der Trend, nicht der Handel","t":"Die Vorhersage ist eine Gesamtkarte. Die tatsächlichen Handelsniveaus – Einstieg, TP1/TP2, SL und die kurzfristige Prognose – sind immer noch das, was Sie handeln."},{"h":"Ehrliche Grenzen","t":"Nachrichten, Listings, Delistings und Makroverschiebungen sind nicht im Modell enthalten; Der Weg verläuft sanft, sodass die realen Preise weitaus stärker schwanken werden. Ein 3-Monats-Konus ist eine Lernhilfe, niemals ein Versprechen."},{"h":"Analysieren Sie häufig erneut","t":"Wenn neue Kerzen gedruckt werden, werden das Ziel, die Volatilität und damit der gesamte Kegel aktualisiert. Eine Prognose ist eine Momentaufnahme, kein Vertrag."},{"h":"Checkliste für die Praxis","t":"① Lesen Sie die Pfadrichtung ab. ② Überprüfen Sie die Kegelbreite. ③ Vergleichen Sie sie mit der Struktur mit höherer TF. ④ Bestimmen Sie die Position anhand des tatsächlichen SL, niemals anhand des Kegels."}]}],"platforms":{"BINANCE":{"title":"Binance-Handel A → Z","steps":["Konto erstellen → 2FA aktivieren.","API-Management → Schlüssel erstellen → Spot- und/oder Futures-Handel EIN, Auszahlungen AUS.","Fügen Sie Schlüssel + Geheimnis in CPE → API-Schlüssel → Binance → Speichern → Testkonto ein.","Verwenden Sie den Spot Desk-/Futures Desk-Scan (öffentliche Charts funktionieren bereits vor Schlüsseln).","Übung: Manueller Handel → Papierhandel starten (kein Live-Geld).","Live: TP1/TP2/SL + Trailing einstellen → Live-Handel starten (benötigt API).","In Positionen verwalten: Ebenen bearbeiten, teilweise schließen, automatisch abbrechen.","Lizenz: Testversion 7d → 3 Monate oder lebenslang (Besitzerpreise in der App)."]},"BYBIT":{"title":"Bybit-Handel A → Z","steps":["Konto + 2FA.","API-Management → nur Handel, Auszahlungen AUS.","CPE → API-Schlüssel → Bybit → Speichern.","Futures Desk für Tätermentalität; Chart Lab zum Studieren von Kerzen.","Papierhandel zuerst; Lebe, nachdem die Schlüssel funktioniert haben.","Trail TP+SL: KAUFEN ↑ / VERKAUFEN ↓."]},"OKX":{"title":"OKX Trading A → Z","steps":["API-Schlüssel + Geheimnis + Passphrase erforderlich.","Auszahlungen immer AUS.","Speichern Sie alle drei Felder in CPE Keys.","Papierübung → kleine Live-Größe.","Tippfehler bei Passphrasen sind der Fehler Nr. 1 – kopieren Sie sie sorgfältig."]},"KUCOIN":{"title":"KuCoin-Handel A → Z","steps":["Schlüssel + Geheimnis + Passphrase.","Nur Gewerbeerlaubnis.","Papier in CPE → dann lebe klein.","Verwenden Sie Spot/Futures-Pulte für Signale."]},"BITGET":{"title":"Bitget-Handel A → Z","steps":["API nur mit Handel.","Papier dann live.","Futures: Wählen Sie „Cross“ oder „Isolated“ im manuellen Handel.","Verfolgen Sie TP+SL, um Gewinne zu sichern."]},"GATE":{"title":"Gate.io Trading A → Z","steps":["Erstellen Sie API v4-Schlüssel (Handel).","Auszahlungen AUS.","Speichern Sie in CPE → Übungspapier.","Scannen Sie + Chart Lab nach Einträgen, bevor Sie live gehen."]},"MEXC":{"title":"MEXC-Handel A → Z","steps":["Beginnen Sie mit der Spot-Denkweise.","Schlüssel in CPE-API-Schlüsseln.","Papier → live.","Verwenden Sie Trail, um offene Gewinne zu sichern."]},"KRAKEN":{"title":"Kraken-Handel A → Z","steps":["Schlüssel nur mit Gewerbeerlaubnis generieren.","Keine Auszahlungs-/Geldrechte.","Papierpraxis in CPE.","Überprüfen Sie auch jede Live-Bestellung auf Kraken."]},"COINBASE":{"title":"Coinbase Advanced A → Z","steps":["Erweiterte Trade-API-Schlüssel.","Spot-fokussierter Schreibtisch aus CPE.","Papier dann live.","Halten Sie Auszahlungen AUS."]},"FOREX_OANDA":{"title":"Forex (OANDA) A → Z","steps":["Öffnen Sie die OANDA-Demo → Risiko ~1 %.","Persönliches Zugriffstoken + Konto-ID in CPE-Schlüsseln.","Forex Desk Scan + Chart Lab (EURUSD…).","Manueller Handel → Papier mit Forex-Plattform.","Lebe nur nach Demo-Vertrauen."]},"FOREX_FXCM":{"title":"FXCM Forex A → Z","steps":["Anmeldeinformationen für die Broker-API.","Zuerst Papier in CPE.","Sehen Sie sich Sitzungen und Nachrichtenspitzen in London/NY an.","Das Live-After-Training-Tagebuch sieht sauber aus."]},"FOREX_MT5":{"title":"MetaTrader 5 A → Z","steps":["Login + Server + Passwort in CPE Keys.","Wenn möglich, Anleger-(Lese-)Passwort bevorzugen.","Übungsplätze 0,01.","Papier in CPE; Live über Broker, wenn Sie bereit sind."]},"FOREX_DEMO":{"title":"Forex-Demokurse A → Z","steps":["Kein API-Schlüssel erforderlich.","Forex Desk + Chart Lab für kostenlose Charts.","Nur Papierhandel (Praxis).","Wenn Sie bereit für einen echten Broker sind, fügen Sie OANDA-/FXCM-/MT5-Schlüssel live hinzu."]}},"forexAz":{"title":"Forex Trading A → Z (komplette Klasse)","lessons":[{"h":"A – Konto und Risiko","t":"Demo zuerst. Risiko ~0,5–1 % pro Idee. Niemals Rachehandel betreiben."},{"h":"B – Paare","t":"Hauptwährungen (EURUSD, GBPUSD, USDJPY) vor Exoten."},{"h":"C – Kerzen","t":"Lernen Sie Doji, Hammer und Engulfing auf Chart Lab Forex."},{"h":"D – Tägliche Voreingenommenheit","t":"Überprüfen Sie vor 15-m-/30-m-Teilnahmen einen höheren Zeitrahmen."},{"h":"E – Einträge","t":"BB-Lower-Bounce + Kerzenbestätigung ist ein gängiges Praxis-Setup."},{"h":"F – Fib","t":"50 % / 61,8 % Pullbacks werden oft als Übungszonen genutzt."},{"h":"G – Ziele (TP)","t":"TP1 Scale Out, TP2 Runner, Trail SL."},{"h":"H – Stunden","t":"Überschneidung zwischen London und New York = mehr Bewegung."},{"h":"I – Indikatoren","t":"RSI + MACD + BB zusammen; Vermeiden Sie eine Überlastung der Anzeige."},{"h":"J – Tagebuch","t":"Protokollieren Sie jeden Papier-/Live-Handel im CPE Journal."},{"h":"K – Schlüssel","t":"Live-Forex-Broker benötigen API/Token; Demo-Preise brauchen keine."},{"h":"L – Viele","t":"Beginnen Sie mit 0,01 Lots in der Übungsmentalität."},{"h":"M – Denkweise","t":"Prozess über Vorhersage. Überspringen Sie schlechte Tage."},{"h":"N – Nachrichten","t":"Informieren Sie sich vor Großveranstaltungen über Neuigkeiten und Tricks."},{"h":"O – Befehle","t":"Stellen Sie immer SL ein. Trailing schützt den offenen Gewinn."},{"h":"P – Üben","t":"Schaltfläche „Paper Trade“ = Üben ohne Live-API."},{"h":"F – Qualität","t":"Weniger hochwertige Setups schlagen Overtrading."},{"h":"R – Risiko:Ertrag","t":"Zielen Sie auf Setups, bei denen Belohnung ≥ Risiko ist, wenn möglich."},{"h":"S – Sitzungen","t":"Asien ruhiger; London/NY aktiver."},{"h":"T – Trends","t":"Handeln Sie beim Lernen mit einem höheren TF-Trend."},{"h":"U – Aktualisierungen","t":"Sehen Sie sich das CPE-Update-Banner und die Live-Hilfe an."},{"h":"V – Volatilität","t":"Erweitern Sie Ihre Geduld, wenn die ATR ansteigt."},{"h":"W – API zurückziehen","t":"Aktivieren Sie niemals die Auszahlung für einen API-Schlüssel."},{"h":"X – Ausgänge","t":"Teilweise TP + Trail übertrifft das Hoffen."},{"h":"Y – Dein Plan","t":"Regeln schreiben; Folgen Sie ihnen in Manuell/Auto."},{"h":"Z – Keine Eile","t":"Kein FOMO. Üben → dann Live-API."}]}};

window.CPE_LEARN.ru = {"intro":"Сначала потренируйтесь с бумагой/ДЕМО. Изучите свечи, графики, BB/RSI/Fib, деньги, психологию — затем сигналы (что означает КУПИТЬ/ПРОДАТЬ/ДЕРЖАТЬ + что делать) и сигналы Форекс. Live необходим правильный ключ API платформы (вывод средств отключен).","candles":[{"shape":"doji","name":"Доджи","color":"#94a3b8","bias":"Нейтрально/подождите","tip":"Открыть ≈ закрыть — крест или тонкое тело. Нерешительность рынка после движения.","also":"Также учит: не FOMO. Подождите следующую свечу. Рядом с экстремумом BB + Доджи = сжатие мнений; проверьте наклон RSI, прежде чем угадывать направление."},{"shape":"hammer","name":"Молот","color":"#22c55e","bias":"ПОКУПКА","tip":"Маленькое тело сверху, длинный нижний фитиль (≈2 × тело) после падения — покупатели отвергли более низкие цены.","also":"Также: поместите тренировочный SL под низ фитиля. Лучше всего, если BB + RSI растет из-за перепроданности. Психология: терпение, пока фитиль не закончится, не покупайте средний фитиль."},{"shape":"invhammer","name":"Перевернутый молот","color":"#22c55e","bias":"ПОКУПАТЬ (слабый)","tip":"Длинный верхний фитиль внизу. Покупатели нащупали максимум, но закрылись около открытия — необходимо подтверждение следующего зеленого цвета.","also":"А еще: слабее, чем один только Хаммер. Используйте в качестве предупреждения, а не входа. Отскок Фибоначчи 61,8 + Перевернутый молот = зона исследования только до подтверждения свечи."},{"shape":"shooting","name":"Падающая звезда","color":"#ef4444","bias":"ПРОДАВАТЬ предвзятость","tip":"Небольшой низ тела, длинный верхний фитиль после подъема — продавцы отклонили максимумы.","also":"Также: SL выше максимума фитиля. Сильнее вблизи верхнего BB/расширения Фибоначчи/перекупленности RSI. Учит: лунные свечи могут выйти из строя — не гонитесь за последней зеленой."},{"shape":"hanging","name":"Повешенный","color":"#f59e0b","bias":"ПРОДАВАТЬ осторожно","tip":"Выглядит как Хаммер, но появляется после подъема — возможно максимальное истощение.","also":"А еще: контекст решает все (одна и та же форма ≠ та же сделка). Расположение журнала: вверху и внизу. Психология: не разворачивайтесь только потому, что форма совпала — подтвердите следующую свечу + RSI."},{"shape":"engulf_bull","name":"Бычье поглощение","color":"#22c55e","bias":"КУПИТЬ","tip":"Зеленое тело полностью перекрывает предыдущее красное тело — в одном баре контроль взяли на себя покупатели.","also":"Также: сильнее на поддержке/ниже BB/фибо 50–61,8. Размер от поглощения низкий как SL. Совет: широкое охватывающее тело → более широкий SL → меньший размер."},{"shape":"engulf_bear","name":"Медвежье поглощение","color":"#ef4444","bias":"ПРОДАВАТЬ","tip":"Красный кузов полностью перекрывает приорный зеленый — доминируют продавцы.","also":"Также: осторожность при открытии длинных позиций. Рядом с верхним BB + RSI>70 = высокое качество исследования. Учит риску: если уже долго, частичный ТП/след вместо надежды."},{"shape":"morning","name":"Утренняя звезда","color":"#22c55e","bias":"КУПИТЬ","tip":"3 свечи: большая красная → маленькая звезда → большая зеленая. История разворота дна.","also":"А еще: многосвечное терпение. Входите после третьего закрытия; SL ниже звездного минимума. Хорошо сочетается с более низким BB + бычьей дивергенцией RSI."},{"shape":"evening","name":"Вечерняя звезда","color":"#ef4444","bias":"ПРОДАВАТЬ","tip":"3 свечи: большая зеленая → маленькая звезда → большая красная. Лучшая история разворота.","also":"Также: не замыкайте только среднюю звезду. Подождите третьего закрытия. Слияние расширения верхнего BB/фиба. Психология: игнорировать FOMO первого зеленого забега."},{"shape":"maru_bull","name":"Бык Марубозу","color":"#22c55e","bias":"Сильное давление ПОКУПКИ","tip":"Длинное зеленое тело, фитилей почти нет — покупатели контролировали открытие → закрытие.","also":"Также: подсказка о продолжении тренда, не всегда покупка на дне. Возможна прогулка по группе. Риск: погоня за поздним Марубозу без отката к BB мид/фиб."},{"shape":"maru_bear","name":"Медведь Марубозу","color":"#ef4444","bias":"Сильное давление ПРОДАЖ","tip":"Длинный красный корпус, фитилей почти нет — все под контролем.","also":"Также: не ловите падающие ножи. Подождите отскока BB/Fib + Hammer позже. Учит: сильное давление = меньший размер или стоять в стороне."},{"shape":"spin","name":"Волчок","color":"#94a3b8","bias":"Нерешительность","tip":"Маленький корпус, верхние + нижние фитили — боролись обе стороны, никто не выиграл однозначно.","also":"А еще: часто сжимайте внутри ББ. Приостановить торговлю; ожидание перерыва + направление свечи. Урок психологии: рынок «ничего не может сделать» — флэт — правильный выбор."},{"shape":"pierce","name":"Пирсинг Линия","color":"#22c55e","bias":"КУПИТЬ","tip":"Красный, затем зеленый, который открывается ниже, но закрывается выше середины предыдущего красного.","also":"А еще: мягче, чем «Поглощение». Подтвердите поворотом RSI. Хорошее бумажное упражнение для частичного чтения — не все поля одинаковы."},{"shape":"darkcloud","name":"Покров темных облаков","color":"#ef4444","bias":"ПРОДАВАТЬ","tip":"Зеленый, затем красный, который открывается выше, но закрывается ниже середины предыдущего зеленого цвета.","also":"Также: раннее предупреждение перед полным поглощением медведей. Трейл лонг/бери TP1. Обучает масштабированию перед полной реверсивной печатью."},{"shape":"soldiers","name":"Три белых солдата","color":"#22c55e","bias":"ПОКУПАТЬ тренд","tip":"Три восходящих зеленых цвета с более высокими ценами закрытия — устойчивая покупка.","also":"Также: сигнал о сильном восходящем тренде; откаты к уровням Фибоначчи 38–50 или BB Mid являются практическими добавками. Риск чрезмерной самоуверенности после 3-х зеленых — оставьте процент риска фиксированным."},{"shape":"crows","name":"Три Черных Вороны","color":"#ef4444","bias":"ПРОДАВАТЬ тренд","tip":"Три падающих красных с более низким закрытием — устойчивые продажи.","also":"Также: не усредняйте. Структура ожидания. Перепроданность RSI может оставаться перепроданной — правило денег: лимит потерь > надежда."},{"shape":"harami_bull","name":"Бычий Харами","color":"#22c55e","bias":"КУПИТЬ (мягкий)","tip":"Большой красный, затем маленький зеленый внутри предыдущего корпуса — давление продажи снижается.","also":"Также: сигнал ранней паузы. Требуется подтверждение. Сочетается с исследованием бычьей дивергенции RSI. Учит читать «угасание силы», а не только развороты."},{"shape":"harami_bear","name":"Медвежий Харами","color":"#ef4444","bias":"ПРОДАМ (мягкая)","tip":"Большой зеленый, затем маленький красный внутри — давление покупки снижается.","also":"Также: возьмите частичные значения для длинных. Не автоматический короткий. Психология: жадность после большого зеленого часто игнорирует предупреждение Харами."},{"shape":"tweezer_bot","name":"Пинцет снизу","color":"#22c55e","bias":"КУПИТЬ","tip":"Две свечи с совпадающими минимумами — двойной тест поддержки.","also":"Также: отметьте это значение как структуру. SL чуть ниже. Выравнивание Fib/BB помогает. Двоюродный брат графического паттерна «Двойное дно» — тот же урок поддержки."},{"shape":"tweezer_top","name":"Пинцет Топ","color":"#ef4444","bias":"ПРОДАВАТЬ","tip":"Две свечи с совпадающими максимумами — двойной тест сопротивления.","also":"Также: отметьте сопротивление. Двоюродный брат Double Top. Провал RSI на максимумах = слияние. Учит: дважды отвергнута одна и та же цена = уважайте уровень."},{"shape":"longlegged","name":"Длинноногий Доджи","color":"#94a3b8","bias":"Нерешительность","tip":"Очень длинные верхние и нижние фитили с крошечным телом — жестокая двусторонняя драка, закончившаяся там же, где и началась.","also":"А еще: часто следует большое движение, но направление неизвестно — ждите прорыва свечи. Учит: высокая волатильность – это еще не высокая определенность."},{"shape":"dragonfly","name":"Стрекоза Доджи","color":"#22c55e","bias":"ПОКУПКА","tip":"Открытие = закрытие = максимум, с длинным нижним фитилем — продавцы толкали его вниз, а покупатели снова поднимали его вверх.","also":"Также: сильнейший на уровне поддержки/ниже BB после падения. СЛ под хвост фитиля. Учит: отказ – это история, а не гарантия – подтвердите следующую свечу."},{"shape":"gravestone","name":"Надгробный Доджи","color":"#ef4444","bias":"ПРОДАВАТЬ предвзятость","tip":"Открытие = закрытие = минимум, с длинным верхним фитилем — покупатели подтолкнули вверх, а продавцы вернули его к минимуму.","also":"Также: самый сильный на уровне сопротивления/верхнего BB/перекупленности RSI. Зеркало Стрекоза. Учит: резкий максимум, закрывающийся на минимуме, означает неудачный прорыв."},{"shape":"inside_bar","name":"Внутренний бар","color":"#94a3b8","bias":"Намотка / ожидание","tip":"Вторая свеча полностью находится внутри первой — диапазон сжимается, и рынок затаивает дыхание.","also":"А еще: триггером является прорыв материнского бара — торгуйте в направлении прорыва. Сочетается со сквизом BB. Учит: сжатие предшествует расширению."},{"shape":"outside_bar","name":"Внешний бар","color":"#22c55e","bias":"Прорыв/разворот","tip":"Вторая свеча поглощает первую сверху вниз — резкий захват внутри одного бара.","also":"Также: направление = место закрытия внешнего бара. Большой бар означает большой стоп-лосс, поэтому размер меньше. Учит: одна полоска может стереть три последних."},{"shape":"belt_bull","name":"Бычье удержание за пояс","color":"#22c55e","bias":"КУПИТЬ","tip":"Открывается на минимуме, без нижнего фитиля и становится зеленым — покупатели взяли контроль в свои руки с самого первого тика.","also":"Также: самый сильный после гэпа вниз или сразу к поддержке. СЛ под открытым небом. Учит: открывающийся порыв показывает настоящее намерение."},{"shape":"belt_bear","name":"Медвежий захват пояса","color":"#ef4444","bias":"ПРОДАВАТЬ","tip":"Открывается на максимуме без верхнего фитиля и становится красной — продавцы контролировали ее с открытия.","also":"Также: самый сильный после гэпа вверх или на уровне сопротивления. Тропа длинная. Учит: первый ход может задать весь день."},{"shape":"kick_bull","name":"Бычий кикер","color":"#22c55e","bias":"Сильная ПОКУПКА","tip":"Красная свеча, затем разрыв вверх до зеленой свечи — настроение менялось между закрытиями без перекрытия.","also":"А еще: редкий и мощный; зазор обязателен, перекрытие не допускается. Учит: настроения могут меняться, пока рынок спит."},{"shape":"kick_bear","name":"Медвежий кикер","color":"#ef4444","bias":"Сильная ПРОДАЖА","tip":"Зеленая свеча, затем гэп вниз до красной свечи — покупатели исчезли между ценами закрытия.","also":"А еще: выходите из лонгов быстро — кикеры вас не ждут. Учит: гэп – это переоценка рынка в ваше отсутствие."},{"shape":"abandoned","name":"Бычий брошенный ребенок","color":"#22c55e","bias":"Сильная ПОКУПКА","tip":"Красная свеча, доджи с разрывом вниз, затем зеленая свеча с разрывом вверх — одинокий остров нерешительности.","also":"Также: дожи должны отклоняться с ОБЕИХ сторон. Редкая, но качественная нижняя часть. Учит: развороты начинаются там, где все сдаются."},{"shape":"three_inside_up","name":"Три наизнанку","color":"#22c55e","bias":"КУПИТЬ","tip":"Бычий Харами плюс третья зеленая свеча, закрывающаяся выше первой — внутренний бар наконец-то сломался.","also":"Кроме того: подтвержденный Харами намного сильнее, чем голый. СЛ под харами лоу. Учит: подтверждение важнее предсказания."},{"shape":"three_inside_down","name":"Три внутри вниз","color":"#ef4444","bias":"ПРОДАВАТЬ","tip":"Медвежий Харами плюс третья красная свеча, закрывающаяся ниже первой — внутренний бар пробился.","also":"Также: сокращайте длинные позиции, как только закроется третья. Учит: неудавшаяся пауза может просто возобновить старую тенденцию."},{"shape":"three_methods_bull","name":"Три метода роста","color":"#22c55e","bias":"ПОКУПАТЬ тренд","tip":"Длинная зеленая свеча, внутри нее три маленькие красные, затем еще одна длинная зеленая — отдых внутри подъема.","also":"А еще: пауза никогда не выходит за пределы диапазона первой свечи, поэтому тренд спокойный. Торгуйте на прорыве последней свечи. Учит: тенденции покоятся, не нарушаясь."},{"shape":"three_methods_bear","name":"Падение тремя способами","color":"#ef4444","bias":"ПРОДАВАТЬ тренд","tip":"Длинная красная свеча, внутри нее три маленьких зеленых, затем еще одна длинная красная — отдых внутри падения.","also":"Также: зеркало Rising Three Methods. Не покупайте мелкую зелень — она шумит. Учит: откаты внутри диапазона не являются разворотами."},{"shape":"tower_bot","name":"Нижняя часть башни","color":"#22c55e","bias":"КУПИТЬ, разворот","tip":"Длинная красная свеча, группа крошечных свечей, затем длинная зеленая — настроение меняется по плоскому основанию.","also":"А еще: ровная середина – это битва, а последняя свеча объявляет победителя. Учит: основы требуют времени."},{"shape":"tower_top","name":"Верхняя часть башни","color":"#ef4444","bias":"ПРОДАВАТЬ разворот","tip":"Длинная зеленая свеча, группа крошечных свечей, затем длинная красная — покупатели истощаются, а продавцы берут верх.","also":"Также: зеркало Нижней Башни. Возьмите частичные, пока формируется основа. Учит: вершины – это процесс, а не мгновение."}],"chartPatterns":[{"shape":"double_bot","name":"Двойное дно (клавиша W)","color":"#22c55e","bias":"ПОКУПКА","tip":"Два минимума рядом с одной и той же ценой, затем прорыв среднего пика — W-образная форма.","also":"Также: прорыв линии шеи = тренировочный триггер. Измерьте высоту для идеи TP. Связи с пинцетом Bottom + Фибоначчи от пика до минимума. Риск: ложный прорыв — ждите вблизи линии шеи."},{"shape":"double_top","name":"Двойная вершина (М)","color":"#ef4444","bias":"ПРОДАВАТЬ предвзятость","tip":"Два максимума около одной и той же цены, затем прорыв среднего минимума — форма М.","also":"А также: то же, что и Tweezer Top, но в большем масштабе. След продолжается до прорыва линии шеи. Психология: второе место по FOMO стоит дорого — план уже был."},{"shape":"hs_top","name":"Голова и плечи","color":"#ef4444","bias":"ПРОДАВАТЬ предвзятость","tip":"Левое плечо, голова выше, правое плечо; сломать вырез горловины вниз.","also":"Также: классический дистрибутив. Цель ≈ высота головы ниже линии шеи. RSI часто расходится вверху. Учит терпению при нескольких колебаниях, а не торговле по одной свече."},{"shape":"ihs","name":"Обратный H&S","color":"#22c55e","bias":"ПОКУПКА","tip":"Перевернутый H&S внизу — пробой линии шеи.","also":"Также: история накопления. Подтвердите, указав объем/импульс, если таковой имеется. Соедините с Morning Star в зоне правого плеча для изучения слияния."},{"shape":"triangle","name":"Треугольник (сжатие)","color":"#f0b429","bias":"Ожидание прорыва","tip":"Более низкие максимумы + сжатие более высоких минимумов — накопление энергии.","also":"А еще: тот же урок, что и со сжатием BB. Не угадывайте направление внутри. Торговый перерыв + закрытие свечи. Деньги: размер после направления известен."},{"shape":"flag","name":"Бычий флаг","color":"#22c55e","bias":"КУПИТЬ продолжение.","tip":"Резкий подъем (полюс), затем небольшой нисходящий/боковой канал — затем продолжение.","also":"Также: глубина флага Фибоначчи часто невелика (38%). Шест Марубозу + флаг = практика тренда. Не покупайте поздно после полного расширения без отката."},{"shape":"channel","name":"Трендовый канал","color":"#38bdf8","bias":"С тенденцией","tip":"Цена между восходящими (или падающими) параллельными линиями — инструменты свинг-трейдинга.","also":"Также: покупка нижнего канала + Молот в восходящем тренде; продам верхнюю + падающая звезда. ББ мид часто отслеживает канал. Учит «где», а не только «какой свече»."},{"shape":"support_res","name":"Поддержка и сопротивление","color":"#a78bfa","bias":"Контекст прежде всего","tip":"Горизонтальные зоны, где цена неоднократно реагирует — карта под каждой свечой.","also":"Кроме того: каждая модель сильнее на уровне поддержки/сопротивления. Нарисуйте зоны в Chart Lab перед BB/RSI. Психология: уровни > советы; напишите их перед входом."},{"shape":"triple_top","name":"Тройная вершина","color":"#ef4444","bias":"ПРОДАВАТЬ предвзятость","tip":"Три максимума почти по одной и той же цене — покупатели трижды терпят неудачу у одной стены.","also":"А также: сильнее, чем двойная вершина (три отклонения = упорное предложение). Прорыв линии шеи является триггером; цель — высота паттерна. Учит: уровень, а не свеча - босс."},{"shape":"triple_bot","name":"Тройное дно","color":"#22c55e","bias":"ПОКУПКА","tip":"Три минимума почти по одной и той же цене — продавцы трижды терпят неудачу на одном этаже.","also":"Также: зеркало Triple Top. Каждое прикосновение может быть исследованием молотком/пинцетом. Дождитесь прорыва линии шеи + закрытия. Учит терпению во многих колебаниях."},{"shape":"cup_handle","name":"Чашка и ручка","color":"#22c55e","bias":"КУПИТЬ продолжение.","tip":"Округленная буква «У» (чашка), затем небольшой откат (ручка) — продолжение после отдыха.","also":"Также: популярен среди трейдеров, торгующих на пробоях. Ручка должна быть неглубокой и короткой — глубокая ручка означает слабые руки. Вход при прорыве ручки с подтверждением свечи."},{"shape":"rounding_bot","name":"Закругление нижней части","color":"#22c55e","bias":"КУПИТЬ, разворот","tip":"Медленный, плавный минимум «блюдца» — продажи постепенно затухают, затем на смену приходят покупатели.","also":"Также: замедленное двойное дно. Суть в том, что у продавцов закончилась энергия, ни единого всплеска — требуется полное терпение."},{"shape":"rounding_top","name":"Закругленный верх","color":"#ef4444","bias":"ПРОДАВАТЬ разворот","tip":"Плавный максимум «купола» — покупки постепенно затухают, прежде чем цена перевернется.","also":"Также: зеркало Rounding Bottom. Принимайте частичные предложения заранее, пока импульс не утихнет. Учит: вершины – это процесс, а не отдельная свеча."},{"shape":"rising_wedge","name":"Восходящий клин","color":"#ef4444","bias":"ПРОДАВАТЬ предвзятость","tip":"Оба рельса поднимаются, но сходятся вверх — покупатели устают, когда диапазон сужается.","also":"Кроме того: вводит в заблуждение, поскольку цена все еще растет; сужение является настоящей подсказкой. Часто ломается ВНИЗ. Не гонитесь за последним рывком."},{"shape":"falling_wedge","name":"Падающий клин","color":"#22c55e","bias":"ПОКУПКА","tip":"Оба рельса падают, но сходятся вниз — продавцы устают, когда диапазон сужается.","also":"Также: зеркало Rising Wedge. Часто РАСПАЕТСЯ. «Молот в клиновом хвосте» — классический этюд. Дождитесь перерыва + закройте."},{"shape":"asc_triangle","name":"Восходящий треугольник","color":"#f0b429","bias":"ПОКУПКА","tip":"Плоский потолок + поднимающийся пол — покупатели продолжают приближаться к фиксированному сопротивлению.","also":"Кроме того: давление на одну цену возрастает; прорыв – обычное дело. Войдите близко к потолку. Учит: покупатели теряют терпение."},{"shape":"desc_triangle","name":"Нисходящий треугольник","color":"#f0b429","bias":"ПРОДАВАТЬ предвзятость","tip":"Ровный пол + падающий потолок — продавцы продолжают давить на неподвижную опору.","also":"Также: зеркало Восходящего Треугольника. Прорыв вниз является обычным явлением. Войдите чуть ниже пола. Учит: продавцы обретают контроль."},{"shape":"pennant","name":"Вымпел","color":"#22c55e","bias":"Продолжение","tip":"Острый полюс, затем крошечный, узкий треугольник — очень короткий отдых перед возобновлением тренда.","also":"Также: как Флаг, но короче и треугольной формы. Измерьте шест для целевой идеи. Никогда не гадайте внутри крошечной катушки."},{"shape":"flag_bear","name":"Медвежий флаг","color":"#ef4444","bias":"ПРОДАВАТЬ продолжение.","tip":"Резкое падение (полюс), затем небольшой канал вверх/вбок — затем продолжение вниз.","also":"Также: зеркало Bull Flag. Небольшой отскок – это пауза, а не разворот. Догоните флаг и купите по худшей цене — ждите прорыва."},{"shape":"rectangle","name":"Прямоугольник (диапазон)","color":"#f0b429","bias":"Диапазон торговли","tip":"Цена прыгает между плоским потолком и полом — боковая коробка.","also":"Также: выцветайте края внутри, меняйте разрыв снаружи. Сжатие BB обычно находится внутри прямоугольника. Преподает: поуровневую дисциплину."},{"shape":"broadening","name":"Расширение формации","color":"#f0b429","bias":"Внимание","tip":"Более высокие максимумы И более низкие минимумы — диапазон расширяется, а не сжимается.","also":"А еще: хаотичный, эмоциональный рынок. Стопы попадают в обе стороны. Меньший размер или стоять в стороне; это часто заканчивается резким движением в одну сторону."},{"shape":"diamond","name":"Алмаз","color":"#f0b429","bias":"Разворот","tip":"Широкая посередине и узкая с обоих концов — классическая формация «верх/низ».","also":"А еще: треугольник, который трансформируется, а затем не трансформируется. Направление прорыва решает. Редко и медленно, поэтому большинство строк кажутся шумом — наберитесь терпения."},{"shape":"island_rev","name":"Разворот острова","color":"#ef4444","bias":"Разворот","tip":"Цена совершает гэп, торгуется одиноким кластером, затем совершает гэп обратно — «остров».","also":"Также: нужны реальные гэпы (чаще встречаются в акциях/валюте). Остров попал в ловушку покупателей или продавцов. Считайте гэпы сигналом, а не островными свечами."},{"shape":"breakaway_gap","name":"Отрывной разрыв","color":"#22c55e","bias":"Начало тренда","tip":"Выход за пределы диапазона или базы — движение начинается с силы, а не с сжатия.","also":"Кроме того: в отличие от разрыва на истощение, он появляется на ранних этапах хода. Гэпы часто впоследствии выступают в качестве поддержки/сопротивления. Учит: динамика и ценностный разрыв."},{"shape":"v_reversal","name":"V-реверс","color":"#22c55e","bias":"Разворот","tip":"Резкое свободное падение, которое мгновенно возникает без базы — буква «V».","also":"А еще: быстро и страшно; часто основаны на новостях. Трудно поймать, легко преследовать. Вместо покупки на скачке дождитесь небольшого отката + свечи."},{"shape":"harmonic","name":"Гармонический узор","color":"#f0b429","bias":"Разворотные зоны","tip":"Измеренный зигзаг (X-A-B-C-D), где каждая нога имеет соотношение Фибоначчи — карта в стиле «Гартли/Летучая мышь».","also":"Также: продвинутый. Точка D — это зона входа, определяемая отношениями, а не чувствами. Сначала освойте простую Фибоначчи; это Фибо, взятое на один уровень глубже."}],"modules":[{"id":"bb","title":"1 · Полосы Боллинджера (BB)","summary":"Волатильность располагается вокруг скользящей средней. Научитесь сжимать, ходить по полосе, нижнему/верхнему касанию + подтверждение свечой — основная настройка практики CPE.","lessons":[{"h":"Что такое ББ","t":"Полосы Боллинджера = средняя SMA (часто 20) + верхняя/нижняя полосы при N стандартных отклонениях (часто 2). Полосы расширяются, когда волатильность растет, и сжимаются, когда рынок затих."},{"h":"Средняя полоса","t":"Средняя линия является средней. Цена выше середины часто показывает бычье давление; ниже показано медвежье давление. Используйте ее как динамическую линию смещения, а не как волшебную покупку/продажу."},{"h":"Нижняя полоса (практика ПОКУПКИ)","t":"Ценник, отмечающий нижнюю полосу после падения, может означать «растяжку вниз». НЕ покупайте каждое прикосновение. Дождитесь бычьей свечи (Молот, Поглощение) и, в идеале, подъема RSI."},{"h":"Верхняя полоса (ПРОДАТЬ/осторожно)","t":"Отметка цены верхней полосы может означать «растянутость вверх». В восходящем тренде цена может перемещаться по верхней полосе (ходить по полосе). Предпочитайте идеи ПРОДАЖИ только с медвежьей свечой + слабостью более высокого TF."},{"h":"Сжимать","t":"Узкие полосы = низкая волатильность → часто следует прорыв. Не угадывайте направление внутри тесного сжатия; отметьте прорыв и подтвердите свечой + объем, если таковой имеется."},{"h":"Прогулка по группе","t":"При сильном тренде цена охватывает верхнюю (или нижнюю) полосу для многих свечей. Борьба с этим с помощью затухания возврата к среднему — распространенная ошибка новичков."},{"h":"BB + Лаборатория графиков","t":"В CPE Chart Lab/столах изучите ББ со свечами на ДЕМО. Практика: нижняя полоса + Молот → Бумага. Торговля с SL ниже фитиля, TP1 возле средней полосы."},{"h":"Комбинация BB + RSI","t":"Более сильный фильтр практики: нижний BB + перепроданность RSI (или рост от перепроданности) + бычья свеча. Верхний BB + перекупленность RSI + медвежья свеча для короткой практики."},{"h":"Остановить размещение","t":"Длительная практика: SL под минимумом колебания/ниже фитиля нижней полосы. Короткая практика: стоп-лосс выше максимума колебания. Никогда не вступайте в сделку BB без письменного SL."},{"h":"Цели","t":"Общий путь: TP1 в средней полосе, TP2 в направлении противоположной полосы или следа. Масштабируйте — не нужен весь ход."},{"h":"Сроки","t":"Примите решение о смещении в сторону более высокого TF (4H/1D). Вход на BB + свеча 15/30 м. Смешение случайных TF приводит к противоречивым сигналам."},{"h":"Ошибки, которых следует избегать","t":"Покупка каждого касания нижней полосы на падающем рынке; продавать каждое верхнее касание в ходе лунного пробега; нет СЛ; игнорируя всплески новостей, которые резко расширяют полосы."},{"h":"Контрольный список практики","t":"① Более высокое смещение ТФ ② Касание BB или сквиз-брейк ③ Подтверждение свечи ④ Согласие RSI ⑤ Установлен процент риска ⑥ Сначала бумага ⑦ Результат журнала."}]},{"id":"rsi","title":"2 · RSI (индекс относительной силы)","summary":"Осциллятор импульса 0–100. Период по умолчанию 14. Используйте с BB и свечами — никогда не используйте RSI как полную систему.","lessons":[{"h":"Что измеряет RSI","t":"RSI сравнивает среднюю прибыль и убытки за N баров. Высокий RSI = недавний бычий импульс; низкий RSI = недавний медвежий импульс. Это не ситуация «перекупленность = необходимость продавать» каждый раз."},{"h":"Классические зоны","t":"Часто: выше 70 = зона перекупленности, ниже 30 = зона перепроданности. При сильных трендах RSI может оставаться перекупленным/перепроданным в течение длительного времени — это нормально."},{"h":"Средняя линия 50","t":"Пересечение RSI выше 50 может поддержать бычий настрой; ниже 50 медвежий уклон. Многие трейдеры используют 50 в качестве фильтра тренда со средней полосой BB."},{"h":"Дивергенция — бычья","t":"Цена достигает более низкого минимума, RSI достигает более высокого минимума → импульс ослабевает при движении вниз. Все еще ждите свечи + прорыва структуры перед входом в бумагу."},{"h":"Дивергенция — медвежья","t":"Цена выше максимума, RSI ниже максимума → восходящий импульс затухает. Подтвердите с помощью «Падающей звезды» / «Поглощения» вблизи сопротивления или верхней точки BB."},{"h":"Качели неудач","t":"RSI не может повторно протестировать предыдущий экстремум, а затем снова пересекает отметку 50 — ранний сигнал о сдвиге импульса. Объедините со структурой Chart Lab."},{"h":"RSI + BB (стиль CPE)","t":"Практикуйте длинную позицию: цена около нижнего уровня BB, RSI ≤ 35 (или рост от ≤ 30), бычья свеча. Короткая практика: верхний BB, RSI ≥ 65–70, медвежья свеча."},{"h":"Скрытая дивергенция","t":"Подсказка о продолжении тренда (например, цена выше минимума, RSI ниже минимума в восходящем тренде). Продвинутый уровень — сначала освойте классическую дивергенцию на ДЕМО."},{"h":"Настройки","t":"RSI(14) является общим значением по умолчанию. Более короткий RSI = больше шума. Не меняйте настройки, чтобы усилить сигнал."},{"h":"Выход с RSI","t":"Если вы купили перепроданность, разумно получить частичную прибыль, когда RSI достигнет средней/верхней зоны. Следуйте остальным со структурой или BB-мидом."},{"h":"Новости и RSI","t":"Большие новости могут мгновенно поднять RSI. Предпочитайте дождаться завершения первой сильной свечи, прежде чем действовать на экстремумах RSI."},{"h":"Ошибки","t":"Короткая продажа по каждому RSI>70 на бычьем рынке; ожидание каждого RSI<30 при медвежьем падении; нет слияния; возвращение мести, когда RSI «выглядит лучше»."},{"h":"Контрольный список практики","t":"① Обратите внимание на значение RSI + наклон ② Проверьте положение BB ③ Подтвердите свечу ④ Более высокий TF ⑤ Бумага + журнал ⑥ По одной идее за раз."}]},{"id":"fib","title":"3 · Фибоначчи (ретрейсмент и расширение)","summary":"Измеряйте откаты и цели от четкого максимума колебания → минимума колебания (или разворота). Сосредоточьтесь на 38,2 · 50 · 61,8 с слиянием BB/RSI.","lessons":[{"h":"Почему используется Фибо","t":"Многие трейдеры следят за одними и теми же коэффициентами, поэтому ликвидность часто реагирует вблизи них. Фибоначчи — это карта возможных зон, а не гарантия."},{"h":"Точки поворота","t":"Всегда рисуйте от четкого минимума колебания к максимуму (движение вверх) или от максимума к минимуму (движение вниз). Плохие колебания = бесполезные уровни. Попрактикуйтесь в выборе колебаний в ДЕМО-версии Chart Lab."},{"h":"Ключевые ретрейсменты","t":"Общие: 23,6% (поверхностные), 38,2%, 50% (не чистая Фибоначчи, но широко используемые), 61,8% (золотые), 78,6% (глубокие). Глубокие откаты могут сигнализировать о слабости тренда."},{"h":"Покупки на откате (восходящий тренд)","t":"После восходящего импульса ждите отката в зону 38,2–61,8 + бычья свеча + желательно средняя/нижняя поддержка BB или удержание RSI >40–45."},{"h":"Продажи на откате (нисходящий тренд)","t":"После нисходящего импульса поднимитесь до 38,2–61,8 + медвежья свеча + провал RSI ниже 55–60."},{"h":"Расширения/цели","t":"Общие расширения: 127,2%, 161,8% выходят за рамки идей TP2. Используйте со следом — не задавайте точные тики."},{"h":"Слияние = сила","t":"Зоны лучшей практики: Фибоначчи 50/61,8 + средний/нижний BB + предыдущая структура + разворот RSI. Одна только линия Фибоначчи слаба."},{"h":"Фибоначчи + ББ","t":"Если 61,8% находится вблизи нижнего BB в восходящем тренде, это перекрытие является высококачественной зоной исследования Paper. Вход только с подтверждением свечи."},{"h":"Множественные Фибо","t":"Новичкам следует использовать ОДИН чистый удар. Объединение 5 Фибов создает шум на графике и записи FOMO."},{"h":"Аннулирование","t":"Если цена закрывается явно выше 78,6% вопреки вашему предубеждению, тезис об откате часто терпит неудачу — выходите или оставайтесь в стороне."},{"h":"Форекс против криптовалюты","t":"Те же соотношения. Крупные игроки рынка Форекс часто более тщательно соблюдают уровни в ликвидных сессиях; криптовалюта может пройти, а затем повернуть вспять — размер меньше."},{"h":"Ошибки","t":"Рисование Фибоначчи на крошечных колебаниях шума; вход в воздух без свечи; перемещение SL дальше, когда Фибоначчи «почти» держится; игнорируя более высокий TF."},{"h":"Контрольный список практики","t":"① Отметить колебание ② Примечание 38,2/50/61,8 ③ Ждать прибытия цены ④ Свеча + RSI/BB ⑤ Набор рисков ⑥ Бумага → журнал."}]},{"id":"money","title":"4 · Управление капиталом","summary":"Как на самом деле используется метод: рисковать фиксированным процентом, размером от стопа, откладывать часть прибыли и стопом на следующий день после лимита убытков. CPE может применить это к ручным и автоматическим сделкам.","lessons":[{"h":"Цель управления капиталом","t":"Оставайтесь в игре. Одна неудачная сделка никогда не должна стирать счет. Последовательность важнее размера лотереи."},{"h":"Как трейдеры на самом деле используют это","t":"Обычной практикой является риск с фиксированной долей. Вы не выбираете сначала сумму монеты. Вы сначала пишете стоп, решаете, что эта идея может потерять около 1% счета, потом размер выпадает из этого. Широкий стоп получает меньшую позицию. Близкий стоп дает большую позицию, а долларовый риск остается примерно таким же. Это метод, который CPE использует, когда включена галочка управления капиталом."},{"h":"Рабочий пример (тренировочный счет на 1000 долларов США)","t":"Счет 1000$. Риск 1% = 10 долларов США. Въезд 100, остановка 98. Расстояние = 2%. Размер = 10 ÷ 0,02 = условно 500 долларов. Если стоп сработает, потери составят около 10 долларов, а не 500 долларов. Если цена достигнет 103 (риск в 1,5 раза), прибыль составит около 15 долларов. Та же идея для каждой пары: риск доллара остается около 1%, количество монет меняется."},{"h":"Что CPE делает с галочкой","t":"Торгуйте сейчас → Авто: отметьте «Использовать управление капиталом». Сохранить автоматическую конфигурацию. Каждая новая автоматическая сделка затем использует около 1% от тренировочного счета в 1000 долларов плюс закрытые результаты, рассчитанные на основе входа этого сигнала и SL. Соблюдаются спотовые и фьючерсные минимумы: если биржевой минимум будет рисковать более 1%, эта сделка пропускается. Примерно через −2% в календарный день новые автомобили останавливаются до следующего дня. Максимум около 3% подвергается риску по открытым сделкам. Ручная торговля имеет такую ​​же галочку. История сигналов по-прежнему показывает равный тест в 10 долларов, а под ним — размер плана в 1% для счета в 1000 долларов, поэтому вы можете видеть оба."},{"h":"Частичная прибыль и след","t":"Практика состоит в том, чтобы выполнить часть удара по первой мишени (часто около половины), а остальные оставить позади. Когда стоп перемещается вверх, цель тоже может двигаться, поэтому победитель может заплатить больше, чем первая цель. Риск исходной идеи не увеличивается. Сильный сигнал не является поводом рисковать 5%. Используется тот же 1%. След – это то, что позволяет сильному победителю расти."},{"h":"Ежедневная остановка и открытый нагрев","t":"Используемое правило: если за день пропало около 2% счета, прекращайте открывать сделки. Три открытые идеи по 1% каждая — это около 3% тепла. Пять коррелирующих монет — это одна ставка, а не пять. Посчитайте их вместе."},{"h":"От чего отказывается этот метод","t":"Мартингейл (удвоение после проигрыша) не используется. Перемещение стопа дальше, чтобы «дать ему место» после входа, не используется. Ол-ин по сигналу «уверен» не используется. Если нет действующего стопа, нет и размера, поэтому сделка невозможна."},{"h":"Риск на сделку","t":"Общее правило: рискуйте только ~0,5–1% средств на счете по одной идее. В ДЕМО практикуйте ту же процентную привычку, что и в LIVE."},{"h":"Формула размера позиции","t":"Размер ≈ (Счет × Риск%) ÷ (Вход — Стоп-дистанция). Более широкий SL → меньший размер. Никогда не выбирайте сначала размер, а потом SL."},{"h":"Риск: Вознаграждение","t":"При обучении отдавайте предпочтение идеям, в которых потенциальное вознаграждение ≥ риска (например, 1:1,5 или лучше). Выполните масштабирование до уровня TP1, чтобы бегуны были «свободны от риска»."},{"h":"Частичный тейк-профит","t":"Стиль CPE: TP1 фиксирует некоторую прибыль, TP2 / отслеживает остальную часть. Частичные банковские операции уменьшают эмоциональную панику."},{"h":"Трейлинг TP + SL","t":"ПОКУПКА: уровень следа повышается по мере роста цены. ПРОДАВАТЬ: движение вниз. Трейлинг фиксирует открытую прибыль без необходимости идеального выхода."},{"h":"Дневной/еженедельный лимит потерь","t":"Пример правила: прекратить торговлю на следующий день после счета −2%. Сеансы мести после достижения лимита потерь убивают аккаунт."},{"h":"Точечная калибровка","t":"Значения точечных минут имеют значение (например, минуты обмена). По-прежнему применяйте процент риска: если минимальный размер слишком велик для вашего SL, пропустите сделку."},{"h":"Фьючерсы/кредитное плечо","t":"Кредитное плечо умножает как прибыль, так и убыток. Высокое кредитное плечо + широкий SL = просроченный счет. Предпочитаете низкое кредитное плечо во время обучения; Изолированность может ограничить потери на позицию."},{"h":"Корреляция","t":"Открытие 5 коррелирующих альтернатив BTC = одна большая ставка, а не пять. Считайте риск как группу."},{"h":"Комиссии и проскальзывание","t":"Тайтовые скальпы хорошо смотрятся на графике, но комиссии съедают R:R. Отдавайте предпочтение более чистым качелям в ДЕМО, пока не узнаете стоимость."},{"h":"ДЕМО → ЖИВОЙ мост","t":"Практика CPE DEMO (ориентация примерно на 3 месяца): те же правила журнала, тот же процент. Когда LIVE, начните с половины размера DEMO в течение первых недель."},{"h":"Безопасность денег API","t":"Вывод средств ВЫКЛ на каждый ключ. Действуйте только после подтверждения тестового аккаунта на соответствующей платформе. Неверный секрет платформы = неудачная или опасная операция."},{"h":"Ошибки","t":"Мартингейл (удвоение после проигрыша); перемещение SL дальше; олл-ин при «верных» настройках; игнорирование минимального размера по сравнению с процентом риска; торговля без дневного стопа."},{"h":"Контрольный список практики","t":"① Записанный % риска ② Размер от расстояния SL ③ Планируется TP1/TP2/след ④ Максимальный ежедневный убыток известен ⑤ Сначала бумага ⑥ Честно ведите журнал PnL."}]},{"id":"psych","title":"5 · Психология трейдинга","summary":"Образ мышления решает, выживут ли навыки BB/RSI/Fib на реальных экранах. FOMO, месть, чрезмерная самоуверенность, страх — тренируйте их на ДЕМО-подобных индикаторах.","lessons":[{"h":"Почему психология важна","t":"Идеальный план BB+RSI потерпит неудачу, если вы войдете рано, пропустите SL или возьмете сделку. Навык = система × дисциплина."},{"h":"Процесс важнее прогноза","t":"Вам не нужно предсказывать будущее. Вам необходимо выполнить правила: настройка → риск → управление → журнал. Результаты различаются; процесс управляем."},{"h":"ФОМО","t":"Страх упустить выгоду = погоня за зелеными свечами, уже далекими от зоны BB/Fib. Правило: если вы пропустили запись, ждите следующей настройки. У Chart Lab всегда есть еще одна свеча."},{"h":"Торговля местью","t":"После проигрыша желание «отыграть сейчас» уничтожает счета. Обязательное охлаждение: уйти, зафиксировать убыток, следующая сделка только в том случае, если контрольный список чист."},{"h":"Чрезмерная самоуверенность после побед","t":"3 победы подряд ≠ увеличить размер в 5×. Сохраняйте процент риска фиксированным. Победные серии – это когда большинство людей нарушают денежные правила."},{"h":"Страх после потерь","t":"Пропуск каждой допустимой настройки после красного дня также является предвзятостью. Доверяйте письменному плану; При необходимости временно уменьшите размер, не прекращайте процесс."},{"h":"Аналитический паралич","t":"10 показателей не совпадают → заморозить. Придерживайтесь ядра CPE: свечи + BB + RSI (+ зона Фибоначчи). Качество важнее количества инструментов."},{"h":"Наклон и новости","t":"Большие красные свечи в новостях повышают уровень адреналина. Предпочитайте флэт во время важных неизвестных, пока структура не реформируется — эго хочет действий; план требует терпения."},{"h":"Журнал = терапия + данные","t":"Напишите теги эмоций (FOMO, спешка, спокойствие) в журнале CPE. Модели чувств выявляют утечки быстрее, чем один только PnL."},{"h":"Письменные правила","t":"Если это не написано, то это не правило. Пример: «Только BB+свеча+RSI; риск 1%; никаких сделок после дня −2%; ДЕМО до контрольного списка 20 бумаг»."},{"h":"Окружающая среда","t":"Сон, голод и отвлечение телефона меняют решения. Не увеличивайте размер, когда устали. Трейдинг — это спортивное занятие — берегите мозг."},{"h":"Социальный шум","t":"«Сигналы» Telegram и хайп ломают ваш план. Класс обучения CPE + ваш журнал > случайные советы. Фильтруйте новости и хитрости по контексту, а не по заказам."},{"h":"Смена идентичности","t":"Думайте: «Я следую своему контрольному списку», а не «Я должен быть прав». Ошибаться с небольшим риском – это нормально; быть упрямым с большим риском необязательно."},{"h":"ДЕМО как тренажерный зал","t":"Используйте ДЕМО/Бумагу, чтобы безопасно репетировать эмоции. Если вы не можете соблюдать правила в DEMO, LIVE волшебным образом не исправит дисциплину."},{"h":"Контрольный список практики","t":"① Я спокоен? ② Контрольный список завершен? ③ Процент риска не изменился? ④ Не месть? ⑤ Буду ли я вести дневник честно? Если есть НЕТ → торговля невозможна."}]},{"id":"signals","title":"6 · Сигналы CPE — значение и что делать","summary":"Столы спот/фьючерс/форекс показывают ПОКУПКА · ПРОДАВАТЬ · ДЕРЖАТЬ + оценка. Одна и та же идея движка на каждой платформе, но вы торгуете только на той платформе, ключ API которой вы сохранили. Вот что означает каждый сигнал и точные действия после его появления.","lessons":[{"h":"Откуда берутся сигналы","t":"CPE оценивает BB, RSI, Фибоначчи, свечу, пересечение EMA, SMA50, MACD и импульс. Оценка ≥ +3 → КУПИТЬ. Оценка ≤ −3 → ПРОДАВАТЬ. В перерывах → УДЕРЖИВАТЬ. Это рейтинг помощника, а не обещание прибыли."},{"h":"Сигнал ПОКУПКИ — значение","t":"Бычье слияние сейчас сильнее (примеры: отскок нижнего BB, поворот перепроданности RSI, бычья свеча, золотой крест, поддержка Фибоначчи). Рекомендуемые TP1/TP2/SL появляются в строке / Chart Lab / Trade Now."},{"h":"Сигнал SELL — значение","t":"Медвежье слияние сильнее (верхний BB/перекупленность RSI/медвежья свеча/смертельный крест/сопротивление Фибоначчи). На споте ПРОДАВАТЬ обычно означает выход/сокращение длинной или короткой позиции, только если ваш рынок допускает короткие позиции (фьючерсы/Форекс)."},{"h":"Сигнал HOLD — значение","t":"Смешанная или слабая оценка. НЕ принуждайте к сделке. Квартира правильная. Список наблюдения ★ и ждите более четкой ПОКУПКИ/ПРОДАЖИ или кандидата на BB ниже."},{"h":"Число баллов","t":"Высший |балл| = больше согласия между инструментами. BUY +5 сильнее, чем BUY +3 — все равно подтвердите свечи Chart Lab перед размером."},{"h":"BB Нижняя доска","t":"Отдельный список пар с маркировкой нижней полосы Боллинджера — практикуйте кандидатов на покупку. Все еще необходимо подтверждение свечи + RSI; не каждое нижнее касание является входом."},{"h":"Платформа против сигнала (важно)","t":"Математика сигналов аналогична идее на Binance, Bybit, OKX, KuCoin, Bitget, Gate, MEXC, Kraken, Coinbase, OANDA, FXCM, MT5, Forex Demo. Что меняется, так это КУДА вы отправляете заказ: только платформа, выбранная в API-ключах/торговле сейчас. Binance BUY не открывается на Bybit."},{"h":"Крипто-спотовые платформы","t":"Binance Spot, Coinbase и т. д.: КУПИТЬ = купить монету по котировке (например, USDT). SELL = продать активы / получить прибыль. Минимальный размер (например, ~11 долларов США) имеет значение. Никаких рычагов воздействия."},{"h":"Платформы криптофьючерсов","t":"Binance Futures, Bybit, OKX, Bitget…: ПОКУПКА = длинная позиция; ПРОДАВАТЬ = короткая позиция. Выбирайте Cross/Isolated + кредитное плечо осторожно. След: ПОКУПКА тянет TP+SL вверх; ПРОДАВАТЬ движется вниз."},{"h":"Форекс платформы","t":"OANDA / FXCM / MT5 / Демо-версия Forex: те же метки BUY/SELL/HOLD для валютных пар (EURUSD…). КУПИТЬ = купить базовую валюту; ПРОДАВАТЬ = база продажи. Лоты (например, 0,01) вместо количества монет. Сессии и новости имеют большее значение."},{"h":"Когда появится КУПИТЬ — сделайте это","t":"① Откройте ряд → прочитайте «Почему/свеча/RSI». ② Подтверждение картографической лаборатории (15 м–1 ч). ③ Сначала ДЕМО: Торгуйте сейчас → установите TP1/TP2/SL/trail → Запустить демо/бумагу. ④ Только после подтверждения API на этой платформе → маленький LIVE. ⑤ Результат журнала."},{"h":"Когда появится SELL — сделайте это","t":"① Если у вас длинная позиция: рассмотрите TP/частичное закрытие/след — не игнорируйте. ② Если фьючерсы/Форекс и план допускают короткую позицию: подтвердите Chart Lab, затем короткую позицию Paper/Live с SL. ③ Если вчера HOLD был лучше, не мстите за размер флипа."},{"h":"Когда появится HOLD — сделайте это","t":"Нет новой записи вручную. Продолжайте сканирование. Добавить ★ список наблюдения. Учебный класс / Лаборатория диаграмм. Защищайте открытые позиции с помощью следа, только если они уже находятся в сделке."},{"h":"Автоторговля + сигнал","t":"Автоматическая покупка может открыться, когда правила BB более низкий + сильный соответствуют вашей сохраненной автоматической конфигурации. Все-таки сначала ДЕМО-тест Авто. LIVE Auto = реальный риск — Вывод средств ВЫКЛ, небольшой размер."},{"h":"Уведомления","t":"КУПИТЬ Сигнальные тосты соответствуют вашему языку. Относитесь к ним как к сигналу об открытии стола, а не как к рыночным ордерам как таковым."},{"h":"Чего НЕ делать","t":"Не покупайте каждую ПОКУПКУ без графика. Не используйте ключ Binance на Bybit. Не пропускайте SL. Не увеличивайте размер после одного зеленого сигнала. Не торгуйте ДЕРЖАТЬ как «почти ПОКУПАТЬ»."},{"h":"Карточка быстрого действия","t":"Сигнал → Chart Lab → Risk % → TP1/TP2/SL → DEMO Paper → Journal → (позже) LIVE на соответствующем ключе платформы."}]},{"id":"forex_sig","title":"7 · Сигналы Форекс — значение и что делать","summary":"Forex Desk использует один и тот же рейтинг КУПИТЬ/ПРОДАТЬ/ДЕРЖАТЬ для валютных пар. Узнайте, чем сигналы форекс отличаются от криптовалют, а также точные этапы перехода от сигнала → Бумага → живого брокера.","lessons":[{"h":"Сигналы Forex Desk","t":"EURUSD, GBPUSD, USDJPY… получите ПОКУПКУ/ПРОДАЖУ/ДЕРЖАНИЕ + оценку, как криптовалюту. Щелкните строку, чтобы просмотреть диаграмму, текст психологии и предлагаемые уровни."},{"h":"КУПИТЬ на Форексе — смысл","t":"Купите базовую валюту (например, КУПИТЬ EURUSD = купить EUR против USD). Ожидайте повышения цен. Используйте интервал Forex Chart Lab, который вы практикуете (15 м/30 м/1 час)."},{"h":"ПРОДАВАТЬ на Форексе — смысл","t":"Продать базу (закоротить пару). Ожидайте снижения цены. Всегда устанавливайте SL выше структуры/идеи верхней полосы."},{"h":"ДЕРЖАТЬ на Форексе","t":"Нет четкого края — пропускаем. Особенно перед важными новостями (NFP, CPI, центральный банк) предпочитают ДЕРЖАТЬ/флэт."},{"h":"Платформа демо-курсов Форекс","t":"Нет ключа API. Практические таблицы + только бумага. Идеально подходит для обучения на занятиях перед запуском OANDA/FXCM/MT5."},{"h":"Сигнал OANDA → действие","t":"① Служба Форекс КУПИТЬ/ПРОДАТЬ. ② Подтверждение Chart Lab. ③ Ключи API → Токен OANDA + Идентификатор учетной записи → Тест. ④ Сначала ДЕМО-бумага в CPE. ⑤ Маленькие живые лоты (менталитет 0,01) с TP/SL/trail."},{"h":"FXCM / МТ5","t":"То же чтение сигнала. Подключите учетные данные этого брокера в разделе «Ключи API». Signal не выполняет автоматический вход в MT5 до тех пор, пока не будут установлены ключи/мост — практикуйте Paper до тех пор, пока Test OK."},{"h":"Сессии","t":"Перекрытие Лондона и Нью-Йорка часто больше волнует крупные компании. В Азии может быть спокойнее — ДЕРЖАТЬ — это обычное и полезное явление."},{"h":"Распространение и новости","t":"В новостях спреды расширяются – хорошая техническая ПОКУПКА все равно может оказаться плохой покупкой. Проверьте новости и хитрости; дождитесь закрытия свечи после всплеска."},{"h":"Лоты против количества криптовалют","t":"Размер Форекса = лоты, а не условный USDT. % риска по-прежнему действует: более широкий SL → меньшие лоты."},{"h":"BB Нижний на Форексе","t":"Та же идея: пара возле нижней полосы + Молот + повышение RSI = практика длительного изучения. Подтвердите более высокое смещение TF (4 часа/ежедневно)."},{"h":"Когда срабатывает ПОКУПКА на Форексе — шаги","t":"① Прочтите «Почему». ② Более высокое смещение TF, ОК? ③ Отметьте SL за фитилем/конструкцией. ④ Торговля бумагой. ⑤ Если живой брокер готов → маленький размер + след. ⑥ Журнальная сессия (Лондон/Нью-Йорк) + эмоции."},{"h":"Когда срабатывает SELL на Форексе — шаги","t":"① Подтвердите, что всплеск новостей не происходит в середине новостей. ② Медвежья свеча Chart Lab. ③ Бумага короткая или длинная. ④ Если коротко, спускайтесь вниз. ⑤ Не удваивайте партию после промаха."},{"h":"Разница Форекс и криптовалюта","t":"Крипто 24/7; На Форексе есть сессии. Крипто мин $ часто; Лоты Форекс + стоимость пункта. Крипто многие альтернативы коррелируют; Очиститель специальностей Форекс для обучения."},{"h":"Контрольный список практики (FX)","t":"① Пара мажор? ② Сессия в порядке? ③ Новости ясны? ④ Сигнал КУПИТЬ/ПРОДАТЬ не ДЕРЖАТЬ? ⑤ Диаграмма подтверждена? ⑥ % риска? ⑦ Бумага → журнал → ключ живого брокера только тогда, когда он готов."}]},{"id":"fomo","title":"8 · FOMO и эмоциональная дисциплина","summary":"FOMO, месть, жадность и страх — настоящие убийцы аккаунтов, а не индикаторы. Изучите триггеры, признаки тела и точные правила, которые не допускают импульсивных сделок на ваш счет.","lessons":[{"h":"Что такое FOMO на самом деле","t":"FOMO = страх пропустить ход, который уже находится далеко от вашей зоны. Это заставляет вас входить поздно с худшей ценой и без надлежащего SL. Свеча, которую вы «пропустили», — это информация, а не потеря."},{"h":"Три триггера FOMO","t":"① Большая зеленая или красная свеча на графике. ② Сообщение друга или Telegram, показывающее прибыль. ③ Заголовок новостей. Обратите внимание на триггер, прежде чем вы заметите запись."},{"h":"Признаки тела","t":"Учащенное сердцебиение, наклон к экрану, желание нажать «Купить сейчас на рынке», пропустить контрольный список. Если вы это чувствуете, закройте вкладку и подождите одну свечу."},{"h":"Правило «уже побежал»","t":"Если цена переместилась более чем на 1 ATR за пределы запланированного входа, сделка прекращена. Дождитесь отката к BB Mid/Fib или пропустите его. Всегда есть другая установка."},{"h":"Ловушка с зеленой свечой","t":"Марубозу, которого вы не планировали, — это погоня, а не проникновение. Поздние входы имеют худшую награду: риск, потому что стоп окажется далеко."},{"h":"Торговля местью","t":"После проигрыша мозг хочет отыграть его сейчас. Правило: никаких новых записей в течение 15–30 минут после проигрыша и только в том случае, если чек-лист чист. Рынок вам ничего не должен."},{"h":"Страх нажать на курок","t":"Обратная проблема: появляется идеальная настройка и вы зависаете. Используйте крошечный ДЕМО-размер, чтобы проверить процесс, и определите свой размер ДО того, как появится свеча, чтобы решение уже было принято."},{"h":"Жадность после побед","t":"Две зеленые сделки заставляют вас чувствовать себя непобедимым, а затем вы удваиваете размер ставки. Сохраняйте процент риска фиксированным как минимум для 20 сделок; победные серии означают возврат."},{"h":"Торговля от скуки","t":"Флэт – это позиция. Если установки A+ не существует, не делайте ничего. Сделки на скуку — это замаскированное FOMO."},{"h":"Дисциплина перед экраном","t":"Установите два или три окна сканирования в день вместо того, чтобы смотреть на графики. Меньше решений означает меньше импульсивных решений."},{"h":"Эмоциональный журнал","t":"Отметьте каждую сделку спокойствием/спешкой/упущенной удачей/местью. После 20 сделок закономерность ваших утечек становится очевидной."},{"h":"Ритуал сброса","t":"После проигрыша или ошибки FOMO: встаньте, сделайте 10 медленных вдохов, напишите одно предложение о том, что произошло, затем остановитесь на час или продолжайте с половиной обычного риска."},{"h":"Контрольный список практики","t":"① Спокойное тело? ② Триггер замечен? ③ Настройка в моей зоне? ④ SL пишется первым? ⑤ Процент риска не изменился? ⑥ Не месть? Любое НЕТ → нет торговли."}]},{"id":"risk_deep","title":"9 · Управление рисками и капиталом — углубленное","summary":"Математика, которая поддерживает счет на плаву: фиксированный дробный размер, R-кратные, математические расчеты просадки, корреляционный нагрев и дневной стоп. Превратите торговлю в бизнес, управляемый цифрами.","lessons":[{"h":"Фиксированный дробный риск","t":"Рискните фиксированным процентом (0,5–1%) капитала на идею. Размер — это РЕЗУЛЬТАТ стоп-расстояния, который никогда не выбирается первым. Широкий SL → маленький размер; плотный SL → больший размер; долларовый риск остается прежним."},{"h":"Формула определения размера","t":"Размер = (Средства × Риск%) ÷ |Вход − Стоп|. Пример: 1000 долларов США × 1% = риск 10 долларов США. Запись 100, остановка 98 → расстояние 2% → размер 10 ÷ 0,02 = условно 500 долларов."},{"h":"Думайте в R-кратных числах","t":"Риск 1R за сделку. Победитель 2R платит за два поражения. Отслеживайте свой средний R за 20 сделок — это ваше реальное преимущество, а не процент выигрышей."},{"h":"Награда: риск","t":"Перед входом стремитесь к потенциалу не менее 1,5R. Ниже этого пропустите его, если ваш процент выигрышей не очень высок."},{"h":"Математика просадки","t":"Просадка -50% требует +100% для восстановления. Полосы проигрышей — это нормально: даже в системе с винрейтом 60% бывает серия из 5+ поражений. Небольшой риск позволяет этой серии выжить."},{"h":"Ежедневная остановка","t":"Жесткое правило: перестаньте открывать сделки после −2% эквити в день (или 2–3 убытков подряд). Сеансы мести после лимита убивают аккаунт."},{"h":"Еженедельные и ежемесячные лимиты","t":"Также ограничьте неделю (например, −5%) и месяц. При нажатии перейдите к ДЕМО, просмотрите журнал, а затем увеличьте его размер только после чистого запуска."},{"h":"Открытое тепло","t":"Общий риск по всем открытым сделкам должен оставаться на уровне около 3% или меньше. Пять коррелирующих альтернатив — это одна ставка, а не пять — считайте коррелированные воздействия вместе."},{"h":"Точечная калибровка","t":"Спот имеет минимальный номинал. Если биржевой минимум будет рисковать больше, чем ваш 1%, пропустите сделку — никогда не округляйте риск в большую сторону."},{"h":"Определение размера фьючерса","t":"Кредитное плечо меняет маржу, а не риск. Риск по-прежнему равен входу — стопу × размер. Во время обучения используйте низкое кредитное плечо и отдавайте предпочтение изолированной марже."},{"h":"Размер Форекс","t":"Риск = лоты × стоимость пипсов × стоп-пипсы. Решите на лоты. Ориентировочно: лот 0,01 ≈ 0,10 доллара за пипс; стоп на 20 пунктов с риском 1% от $1000 ($10) → 10 ÷ 0,10 ÷ 20 = 0,05 лота."},{"h":"Масштабирование","t":"Возьмите скидку около 50% на TP1, чтобы не рисковать остальным, а затем следуйте дальше. Это превращает хорошую сделку в бег с низким уровнем стресса."},{"h":"Компаундирование против фиксированного","t":"Риск фиксированным процентом от ТЕКУЩЕГО капитала (сложное начисление). Не фиксируйте свой риск на рекордно высоком размере счета."},{"h":"Комиссии и проскальзывание в рублях","t":"Вычтите комиссию из R. Комиссия в размере 0,2% по сравнению со скальпом в 0,5% может свести на нет преимущество — предпочтите более чистые колебания."},{"h":"Закон «Нет остановок – нет торговли»","t":"Если вы не можете определить логический стоп, вы не знаете своего риска, поэтому нет размера и нет сделки."},{"h":"Антимартингейл","t":"Никогда не удваивайте ставки после проигрыша. Увеличивайте размер только после нескольких прибыльных и дисциплинированных недель проверенного процесса — и даже тогда медленно."},{"h":"Контрольный список практики","t":"① Сумма капитала известна ② Процент риска записан ③ Стоп определен ④ Размер от стопа ⑤ Вознаграждение ≥ 1,5R ⑥ Ежедневный стоп известен ⑦ Подсчитано коррелирующее количество очков."}]},{"id":"sl_tp","title":"10 · Мастерство стоп-лосса и тейк-профита","summary":"Разместите SL там, где рынок доказывает вашу неправоту, поэтапно фиксируйте прибыль и перемещайте стоп, чтобы победитель мог двигаться - именно то, что делает CPE с несколькими TP и скользящим SL.","lessons":[{"h":"SL — это решение, а не число","t":"Поместите стоп-ордер там, где идея недействительна (ниже минимума колебания, фитиля или структуры), а не на случайном долларовом расстоянии. Вы покупаете информацию: если цена идет сюда, значит, моя причина неверна."},{"h":"Структурные остановки","t":"Длинная позиция: стоп-лосс чуть ниже минимума колебания или фитиля нижней полосы. Короткая: чуть выше максимума колебания. Обеспечьте небольшой буфер для шума распространения и фитиля, около 0,1–0,3%."},{"h":"Волатильность останавливается","t":"Более широким рынкам нужны более широкие стопы. Используйте ATR или длину фитиля, чтобы определить размер стопа, затем уменьшите позицию, чтобы долларовый риск остался прежним."},{"h":"Почему SL с фиксированным долларом терпит неудачу","t":"Стоп в 10 долларов по BTC и стоп в 10 долларов по EURUSD представляют собой совершенно разные риски. Расстояние должно измеряться в процентах, а не в долларах."},{"h":"Буфер анти-стоп-охоты","t":"CPE игнорирует одно касание фитиля: перед закрытием требуется два последовательных нарушения плюс небольшой буфер (0,15%). Это не позволит шуму охотиться за вашей остановкой."},{"h":"Фиксируйте прибыль поэтапно","t":"Никогда не закрывайте сделку на 100% по одной цене. Масштабирование: TP1 записывает часть, затем TP2 / след обслуживает остальную часть, поэтому большой шаг может окупить многих проигравших."},{"h":"Уровни мульти-TP","t":"CPE позволяет вам добавлять столько уровней TP, сколько вам нужно, каждый со своим собственным процентом закрытия. Пример: ТП1 40%, ТП2 30%, ТП3 30% — или возьмите ТП1 и тяните остальное."},{"h":"Трейлинг стопа","t":"После TP1 переместите стоп в безубыток; после TP2 переместите его в TP1. Пусть стоп следует за ценой, чтобы открытая прибыль была защищена, пока бегун продолжает движение."},{"h":"Выбор следа %","t":"Узкий след быстро фиксирует прибыль, но заканчивается раньше; широкий след дышит, но дает некоторую отдачу. Начните с 1–2% для криптовалюты и настройте его в модальном окне редактирования «Позиции»."},{"h":"бегуны","t":"Когда цена проходит полосу в сильном тренде, расширьте цель и следуйте вместо того, чтобы брать все на уровне TP2. Так одна сделка окупается за целую неделю."},{"h":"Кнопки частичного закрытия","t":"Используйте кнопки закрытия 50%/100% в Позициях для ручного управления или позвольте Auto Close управлять TP/SL по плану."},{"h":"Ловушка безубыточности","t":"Не переводите SL в безубыток слишком рано, до TP1 — обычные откаты выбьют вас из хороших сделок."},{"h":"Никогда не расширяйте проигрышный стоп","t":"Перемещение SL дальше, чтобы дать ему место, — это то, как небольшие потери становятся убийцами счетов. Стоп, который вы установили перед входом, и является стопом."},{"h":"Остановка времени","t":"Если сделка ничего не дает для многих свечей, в то время как формируется явно лучшая установка, закрытие во флэте и перераспределение риска является правильным выходом."},{"h":"Контрольный список практики","t":"① SL при аннулировании, а не случайный ② Буфер для фитилей ③ Частичный план TP1 ④ След после TP1 ⑤ Никогда не расширять SL ⑥ Позвольте победителю бежать."}]},{"id":"plan_journal","title":"11 · Торговый план и ведение журнала","summary":"Письменный план превращает торговлю из азартной игры в процесс. Изучите одностраничный план, контрольный список перед сделкой и то, как вести дневник, чтобы ваши утечки стали видимыми.","lessons":[{"h":"Зачем писать план","t":"Если это не написано, то это не правило. План исключает необходимость принятия решений в условиях стресса и делает ваши результаты измеримыми."},{"h":"Одностраничный план","t":"Пара, рынок, сетап (BB + RSI + свеча + зона Фибо), направление, вход, SL, TP1/TP2, размер (от SL) и максимальный дневной убыток. Если какая-либо строка пуста → сделки нет."},{"h":"Контрольный список перед сделкой","t":"Смещение более высокого TF? · Установка в моей зоне? · Свеча подтверждает? · RSI согласен? · SL написано? · Риск %? · Вознаграждение ≥ 1,5р? · Спокойствие? Все да → торговля."},{"h":"Предсессионная процедура","t":"Проверьте более высокий таймфрейм, ключевые уровни и новости. Напишите сегодняшние две или три пары часов до сессии, а не после того, как взорвется свеча."},{"h":"Что вести дневник","t":"Символ, сторона, вход, выход, размер, R, причина, временной интервал, сеанс и тег эмоции. CPE Journal автоматически сохраняет прибыли/убытки и причины; добавляйте свои собственные заметки."},{"h":"Журнал «ПОЧЕМУ?»","t":"Запишите то, что вы видели (установка) и что вы чувствовали (спокойствие / FOMO / спешка). Результат без контекста ничему не учит."},{"h":"Трек R, а не победы","t":"Два трейдера с одинаковым процентом выигрышей могут иметь противоположные результаты. Средний R и максимальная просадка имеют большее значение, чем процент выигрыша."},{"h":"Привычка делать скриншоты","t":"Сохраняйте график до и после каждой сделки. Просмотр 20 скриншотов показывает ваше преимущество и утечки быстрее, чем любой индикатор."},{"h":"Еженедельный обзор","t":"Раз в неделю подсчитывайте свои сделки, средний R, лучшие и худшие настройки, а также нарушения правил. Выберите ОДНУ утечку и исправьте ее на следующей неделе."},{"h":"Отмечайте утечки","t":"Распространенные теги: поздний вход, отсутствие SL, негабарит, перенесенный SL, месть, скука. Если тег повторяется, превратите его в жесткое правило."},{"h":"Что не регистрировать","t":"Не регистрируйте только победителей. Потери — это данные. Журнал только побед – это брошюра, а не журнал."},{"h":"Спланируйте этап DEMO → LIVE","t":"Прежде чем рисковать реальными деньгами, проверьте план на ДЕМО для определенного количества сделок с положительным средним R, а затем начните с половины размера."},{"h":"Контрольный список практики","t":"① План написан перед записью ② Контрольный список пройден ③ Запись в журнале + эмоции ④ Еженедельный обзор ⑤ Устранена одна утечка."}]},{"id":"leverage","title":"12 · Кредитное плечо, маржа и ликвидация","summary":"Кредитное плечо умножает убытки так же быстро, как и прибыль. Изучите маржу, ликвидацию, изолированную и перекрестную маржу, а также правила безопасности, которые не позволяют одной сделке уничтожить счет.","lessons":[{"h":"Что такое кредитное плечо","t":"Кредитное плечо позволяет вам контролировать более крупную позицию с меньшей маржой. Это увеличивает как прибыль, так и убытки, но не увеличивает ваше преимущество."},{"h":"Маржа против риска","t":"Маржа — это депозит, который фиксирует биржа. Риск — это вход — стоп × размер. Кредитное плечо меняет маржу, а не ваш долларовый риск."},{"h":"Ликвидация","t":"Если убытки съедают вашу маржу, биржа принудительно закрывает позицию (ликвидацию), часто в самый неподходящий момент. Держите стоп подальше от цены ликвидации."},{"h":"Изолированный против Креста","t":"Изолированная позиция ограничивает убытки маржой одной позиции. Cross использует весь баланс кошелька — это более опасно для новичков. Предпочитайте изоляцию во время обучения."},{"h":"Более безопасное кредитное плечо","t":"Низкое кредитное плечо (2–5x) плюс правильный стоп гораздо безопаснее, чем 50x без стопа. Стоп, а не число кредитного плеча, является вашей защитой."},{"h":"Правило ликвидационной дистанции","t":"Убедитесь, что ваш SL находится в пределах цены ликвидации. Если они близко, уменьшите размер, пока не останется комфортное пространство."},{"h":"Кредитное плечо не исправляет плохой вход","t":"Высокое кредитное плечо при плохом входе приводит к более быстрому проигрышу. Сначала исправьте настройку, а затем измените ее размер."},{"h":"Финансирование и сборы","t":"Бессрочные фьючерсы взимают финансирование с течением времени. Длительное удержание заемных преступников приводит к утечке финансирования — еще одна причина тщательно выбирать размер и время."},{"h":"Спот против фьючерсов","t":"Спот не подлежит ликвидации (монета принадлежит вам). Фьючерсы могут и могут упасть до нуля. Используйте фьючерсы только с письменным планом и изолированной маржой."},{"h":"Размер кредитного плеча","t":"Рассчитайте размер на основе стоп-расстояния, а затем убедитесь, что полученный запас является приемлемым. Никогда не выбирайте кредитное плечо первым."},{"h":"Тест «одной сделки»","t":"Прежде чем войти, спросите: если это дойдет до упора, это пожатие плечами или катастрофа? Если это не шраг, значит размер слишком большой."},{"h":"Контрольный список практики","t":"① Изолированный набор ② Низкое кредитное плечо ③ SL внутри цены ликвидации ④ Размер стопа ⑤ Могу ли я здесь пережить полный убыток? да → торговля."}]},{"id":"practice","title":"13 · Практика и тестирование на исторических данных","summary":"Навык строится на DEMO перед LIVE. Изучите повторяемый цикл практики, как «тестировать на исторических данных», прокручивая графики, и как безопасно перейти к реальным деньгам.","lessons":[{"h":"ДЕМО - тренажерный зал","t":"Бумага / ДЕМО существует для того, чтобы отрепетировать процесс и ваши эмоции с нулевым риском. Если вы не можете следовать правилам DEMO, LIVE волшебным образом не исправит это."},{"h":"Цикл практики","t":"Выберите одну настройку (например, нижний BB + Молот + поворот RSI). Отметьте на схеме 20 исторических примеров. Определите вход/SL/TP. Запишите результат. Повторить."},{"h":"Ручное тестирование","t":"Прокрутите назад в Chart Lab, скройте будущее и отметьте каждый сигнал вручную. Это тренирует распознавание образов и не дает вам обманывать себя."},{"h":"Размер выборки","t":"Десять сделок ничего не значат. Прежде чем судить о нем, постарайтесь записать 30–50 сделок по одной настройке."},{"h":"Форвард-тест на ДЕМО","t":"После ручной маркировки запустите ту же настройку в режиме DEMO с сигналами программного обеспечения на две-четыре недели. Сравните реальные исполнения и эмоции с бэктестом."},{"h":"Одна настройка за раз","t":"Не тестируйте пять систем одновременно. Освойте один край, затем добавьте второй."},{"h":"Делайте рутину небольшой","t":"20-минутная ежедневная рутина (сканирование, пометка, журнал, просмотр) заменяет шесть часов случайного просмотра диаграмм."},{"h":"Переходим к ЖИТЬ","t":"Критерии: положительный средний R за 30+ ДЕМО-сделок, соблюдение правил, отсутствие эпизодов мести. Затем запустите LIVE с половинным размером и медленно масштабируйте."},{"h":"Правило масштабирования","t":"Увеличивайте размер только после определенного количества прибыльных и дисциплинированных недель, а не после одной крупной победы."},{"h":"Когда сделать шаг назад","t":"Достигните дневного или еженедельного лимита потерь или заметите повторяющиеся нарушения правил → вернитесь в ДЕМО-версию и восстановите дисциплину, прежде чем продолжить."},{"h":"Отслеживание показателей процесса","t":"Запишите процент прохождения контрольного списка, количество нарушений правил за неделю и средний показатель R. Они предсказывают рост лучше, чем одно число прибылей/убытков."},{"h":"Путь практики CPE","t":"Учебный класс → Лаборатория графиков (настройки отметок) → Бумажная торговля → Обзор журнала → Сигнальные столы в ДЕМО → Маленький LIVE на соответствующем ключе платформы."},{"h":"Контрольный список практики","t":"① Выбрана одна установка ② Отмечено 30 примеров ③ ДЕМО-форвардный тест ④ Журнал + обзор ⑤ Положительный R → LIVE половинного размера."}]},{"id":"volatility","title":"14 · Волатильность и Мартингейл","summary":"Как считывать волатильность рынка (почему цена меняется), как она добавляется к каждому сигналу в качестве линии причины и как работает дополнительная лестница Мартингейла, а также почему это самый быстрый способ потерять счет при неосторожном использовании.","lessons":[{"h":"Что означает волатильность","t":"Волатильность — это то, насколько движется цена, а не в какую сторону. Высокая волатильность = широкие свечи и быстрые колебания. Низкая волатильность = тихий, узкий диапазон. Одна и та же установка имеет очень разную надежность в каждой."},{"h":"Показания волатильности CPE","t":"Каждый сигнал теперь измеряет средний диапазон свечей и ширину полосы Боллинджера, а затем сравнивает их с недавним нормальным значением этой пары. Вы получаете НИЗКИЙ / НОРМАЛЬНЫЙ / ВЫСОКИЙ / ЭКСТРЕМАЛЬНЫЙ плюс понятную линию причины — «почему» изменения рынка, показанную вместе с сигналом."},{"h":"ЧРЕЗВЫЧАЙНАЯ волатильность = понижение рейтинга","t":"Когда лента ЭКСТРЕМАЛЬНАЯ, новый СИЛЬНЫЙ сигнал понижается до уровня ВНИМАНИЕ (указывается причина). На быстроразвивающемся рынке та же модель терпит неудачу гораздо чаще: ложные прорывы и поиск стоп-лоссов являются нормой."},{"h":"Что делать в ВЫСОКОМ/ЭКСТРЕМАЛЬНОМ режиме","t":"Меньший размер. Более широкая остановка. Меньше сделок. Подождите, пока свеча завершится, а не всплеск в середине свечи. Если в показаниях указано ЭКСТРЕМАЛЬНОЕ, рассматривайте установку как зону изучения, а не как вход."},{"h":"Что такое Мартингейл","t":"Мартингейл увеличивает убыточную позицию, чтобы снизить среднюю сумму входа: после каждого неблагоприятного движения вы добавляете еще один ордер, обычно большего размера (1x, 2x, 4x…). Он часто выигрывает, но теряет все за одну неудачную игру."},{"h":"Правило CPE Мартингейла","t":"CPE добавляет дополнительный ордер только тогда, когда ОБА верны: (1) цена переместилась против сделки как минимум на шаг × ступеньку % и (2) для этой пары все еще действует свежий односторонний сигнал. Он никогда не добавляется только потому, что цена упала."},{"h":"Четыре цифры","t":"Шаг % = неблагоприятный ход, необходимый перед каждым добавлением. Множитель = размер каждого дополнения по сравнению с базовым (1 = фиксированный, 2 = двойной). Максимальное количество добавлений = жесткий лимит на дополнительные заказы. Максимальный процент риска лестницы = риск всей лестницы в процентах от капитала. Все четыре на ваш выбор."},{"h":"Жесткая крышка защитит вас","t":"Даже при большом множителе и большом количестве добавлений CPE отклоняет заказ, как только общий риск лестницы превысит ваш верхний предел в процентах от капитала. Он также учитывает минимальный размер обмена и дневной стоп -2%."},{"h":"Где он работает","t":"Установите флажок «Вручную», чтобы управлять этой сделкой, или «Авто-сессия», чтобы управлять ее автоматическими сделками. И ДЕМО, и LIVE. В ручном режиме пара должна быть в списке сканирования, чтобы можно было прочитать свежий сигнал с той же стороны."},{"h":"Почему ограничение имеет значение (пример)","t":"Шаг 1%, множитель 2, три добавляют базовый риск 1%: риск увеличивается 1% → 2% → 4% → 8%. Один полный стоп-аут на последней ступеньке стирает многих победителей. Вот почему существует ограничение и почему значения по умолчанию невелики."},{"h":"Альтернатива антимартингейлу","t":"Многие профессионалы поступают наоборот: добавляют только к победителям и быстро сокращают проигравшие. Чувствуется хуже (более мелкие потери), но он не может взорвать счет в одном тренде против вас."},{"h":"Риск не устранен","t":"Усреднение вниз не устраняет риск — оно перемещает риск из «многих маленьких потерь» в «одну большую потерю». Никогда не добавляйте деньги, которые вы не можете потерять, и никогда не отключайте ограничение, чтобы «восстановить» убыточную сделку."},{"h":"Путь практики","t":"Сначала изучите показания волатильности на ДЕМО. Попробуйте Мартингейл с максимальным добавлением 1–2 и небольшим множителем в ДЕМО-версии для более чем 30 сделок. Запишите каждую лестницу, а затем примите решение: большинство трейдеров считают метод флэта/антимартингейла более безопасным."},{"h":"Контрольный список волатильности + Мартингейла","t":"① Сначала прочитайте уровень волатильности. ② Пропустить или сократить ЭКСТРЕМАЛЬНЫЙ уровень. ③ Мартингейл только со свежим односторонним сигналом. ④ Шаг × ступенька достигнута. ⑤ Под пределом риска → добавить. Любое «нет» → нет доп."}]},{"id":"lab_indicators","title":"15 · Индикаторы Chart Lab (Stoch · ADX · Ichimoku · VWAP)","summary":"Chart Lab теперь имеет полноценную панель индикаторов — каждая кнопка представляет собой галочку включения/выключения, которая мгновенно перерисовывает график. Помимо BB/RSI/MACD/EMA/SMA50/объема теперь вы получаете Stochastic, ADX/DMI, Ichimoku и VWAP, и сигнальный механизм считывает и их, а не только график.","lessons":[{"h":"Где находится бар","t":"Chart Lab → ряд кнопок «Индикаторы» под графиком. Одно нажатие включает индикатор, следующее нажатие выключает его; график немедленно перерисовывается. Тики визуальные И они подают сигнал в механизм обработки сигналов."},{"h":"Стохастик (14,3,3)","t":"Осциллятор %K/%D, нарисованный под свечами, масштаб 0–100. Выше ~80 = зона перекупленности, ниже ~20 = зона перепроданности. Пересечение %K вверх через %D в зоне перепроданности является бычьим индикатором; Крест вниз вверху является медвежьим. В сильном тренде он может оставаться зажатым на одном конце в течение длительного времени — всегда комбинируйте с BB и свечой."},{"h":"ADX/ДМИ (14)","t":"ADX измеряет СИЛУ тренда, а не его направление. Выше ~25 = наблюдается настоящий тренд; ниже ~20 = нестабильный диапазон. +DI выше −DI = ответственные покупатели; −DI выше +DI = ответственные продавцы. Используйте ADX, чтобы решить, стоит ли вообще торговать по тренду или оставаться во флэте."},{"h":"Облако Ишимоку (9,26,52)","t":"Тенкан (быстрая линия), Киджун (медленная линия) и облако Сенкоу. Цена выше восходящего облака = бычий фон; ниже падающего облака = медвежий. Пересечение Тенкан/Киджун внутри облака является слабым; крест с выходом цены из облака сильнее. Сам край облака часто выступает поддержкой/сопротивлением."},{"h":"ВВАП","t":"Volume-Weighted Average Price — средняя цена, взвешенная по объему, сбрасывается каждую сессию. Крупные учреждения ориентируются на него. Цена выше растущего VWAP = контроль принадлежит покупателям; чистый отказ от VWAP во время нисходящего тренда — это короткое исследование. В круглосуточной криптовалюте он сбрасывается иначе, чем в FX — воспринимайте это как ориентир, а не как закон."},{"h":"Как движок их использует","t":"Каждый новый индикатор добавляет небольшое подтверждение к счету на той стороне, на которую он указывает (Стохастик, Ишимоку, VWAP, ADX, когда он согласуется с направлением, и Эллиотта). Они являются подтверждениями, а не триггерами — если они не совпадают с BB/RSI/свечой, счет просто становится более смешанным, и вы получаете больше ДЕРЖАТЬ."},{"h":"Почему CAUTION стал более строгим","t":"Поскольку в пуле теперь больше проверок, планка «ВНИМАНИЕ» была ужесточена: для этого требуется оценка ≥ 4 И как минимум 3 согласующихся проверки. Это не позволяет приложению перегружать вас более слабыми сигналами только потому, что включено больше инструментов."},{"h":"Порядок чтения, который работает","t":"① Направление высшего TF (облако Ишимоку + ADX). ② Цена (BB/Fib/VWAP). ③ Импульс (RSI + Стохастик). ④ Подтверждение свечой. ⑤ Процент и уровни риска записаны → Сначала на бумаге."},{"h":"Ошибки, которых следует избегать","t":"Включаем все индикаторы и смотрим на радугу; использование ADX в качестве направления (это только сила); продавать только потому, что Stochastic >80 в период бычьего роста; игнорирование того, что VWAP означает разные вещи в криптографии и FX."},{"h":"Контрольный список практики","t":"① Смещение от облака + ADX ② Местоположение от BB/Fib/VWAP ③ Моментум от RSI + Stoch ④ Подтверждение свечи ⑤ Написанный SL/TP ⑥ Бумага, затем журнал."}]},{"id":"elliott","title":"16 · Волна Эллиотта (счет света)","summary":"CPE включает в себя легкий счетчик волн Эллиотта. Отметьте «Эллиотт» на панели индикатора Chart Lab, и он отметит последний импульс 0-1-2-3-4-5 на свечах и спроецирует цель волны 5 Фибоначчи. Это инструмент обучения, а не хрустальный шар.","lessons":[{"h":"Идея в одной строке","t":"Рынки движутся волнами: импульсы (5 этапов в направлении тренда) и коррекции (3 этапа против него). CPE учитывает только импульс, который является частью, несущей тренд."},{"h":"Как это рассчитывает CPE","t":"Он находит последние точки разворота (фракталы с тремя барами), чередует максимумы и минимумы и проверяет последние 5–6 колебаний на соответствие правилам Эллиотта. Если форма подходит, она рисует метки 0 → 5 (все еще текущая волна желтого цвета) и целевую линию W5, построенную на основе длины волны 1 × 1,618, измеренной от волны 4."},{"h":"Правила, которые он проверяет","t":"Волна 2 не проходит начало волны 1; волна 4 не перекрывает территорию волны 1; волна 3 не является самой короткой из волн 1/3/5. Когда правило не работает, оно ничего не показывает — никакого принудительного подсчета."},{"h":"Бычий против медвежьего","t":"Восходящий 0-1-2-3-4-5 – бычий импульс; зеркальное отражение на пути вниз является медвежьим. Движок добавляет небольшое подтверждение к счету на стороне волны."},{"h":"Живой или полный","t":"ЖИВАЯ волна 5 (все еще продолжающаяся) считается продолжением тренда. ПОЛНЫЙ импульс (завершенный 0–5) предупреждает, что тренд может утомляться — часто следует коррекция."},{"h":"Целевая линия W5","t":"Расширение Фибоначчи волны 1 от волны 4 минимум/максимум. Это целевая идея, а не магнит — цена может не дойти до нее или перепрыгнуть ее."},{"h":"Как его использовать","t":"Относитесь к подсчету как к слиянию: в четкой зоне BB/Fib со свечой и RSI импульсивный подсчет добавляет убедительности. Само по себе это всего лишь эскиз."},{"h":"Ошибки, которых следует избегать","t":"Пересчитывать волны до тех пор, пока они не совпадут с вашим положением (классический грех Эллиотта); подсчет крошечных покачиваний; игнорирование количества старших таймфреймов; забывая, что счетчик меняется каждый раз, когда печатается новый столбец."},{"h":"Контрольный список практики","t":"① Выбраны четкие колебания ② Правила соблюдены ③ Зигзаг согласуется с BB/Fib ④ Подтверждение свечи ⑤ SL за пределами точки аннулирования волны 4."}]},{"id":"forecast","title":"17 · Прогноз на 3 месяца (Прогноз 3М)","summary":"Проектор дальнего горизонта: как этот график может сформироваться в течение следующих примерно 3 месяцев, построенный на основе собственного тренда, целей и волатильности сигнала. Включите или выключите его галочкой «Прогноз 3М» в Chart Lab.","lessons":[{"h":"Что это рисует","t":"Пунктирная центральная траектория, идущая от анализируемой записи к лучшей цели, уже известной движку (цель Эллиотта → tp2 → tp1), завернутая в расширяющийся «конус», который показывает разброс вероятных цен. Маркеры месяца M+1 / M+2 / M+3 делят горизонт."},{"h":"Почему конус, а не линия","t":"Никто не может знать одну точную будущую цену. Конус расширяется пропорционально квадратному корню времени и собственной волатильности пары, поэтому спокойная валютная пара получает узкий конус, а дикий альткойн — очень широкий. Эта ширина является посланием: чем дальше вы смотрите, тем менее определенна цена."},{"h":"Откуда берутся цифры","t":"Дрейф происходит от текущей цели сигнала; дневная волатильность определяется процентом ATR сигнала, масштабированным до одного дня, поэтому конус означает одно и то же на 5-минутном или 1-дневном графике; ЭКСТРЕМАЛЬНАЯ / ВЫСОКАЯ волатильность еще больше расширяет ее."},{"h":"Как это читать","t":"Посмотрите на НАКЛОН (в какую сторону наклоняется дорога) и ШИРИНУ (сколько сомнений). Восходящая траектория с узким конусом = идея более устойчивого тренда; ровная дорожка с огромным конусом = «здесь нет края, ожидайте шума»."},{"h":"Включение и выключение","t":"Кнопка «Прогноз 3М» находится рядом с «Космос будущего». Для этого необходимо включить пространство будущего (пустая область справа, в которой рисуется проекция). Если сигнал HOLD, направления нет, поэтому ничего не рисуется."},{"h":"Это тенденция, а не торговля","t":"Прогноз представляет собой общую карту. Фактические торговые уровни — вход, TP1/TP2, SL и краткосрочная проекция — по-прежнему являются тем, чем вы торгуете."},{"h":"Честные лимиты","t":"Новости, листинги, исключения из списков и макросдвиги не включены в модель; путь плавный, поэтому реальные цены будут колебаться гораздо сильнее; 3-месячный конус — это учебное пособие, а не обещание."},{"h":"Чаще делайте повторный анализ","t":"По мере появления новых свечей цель, волатильность и, следовательно, весь конус обновляются. Прогноз — это снимок, а не контракт."},{"h":"Контрольный список практики","t":"① Прочтите направление пути. ② Проверьте ширину конуса. ③ Сравните со структурой с более высоким TF. ④ Определите позицию по реальному SL, а не по конусу."}]}],"platforms":{"BINANCE":{"title":"Торговля на Binance А → Я","steps":["Создать учетную запись → включить 2FA.","Управление API → Создать ключ → Спотовая торговля и/или фьючерсная торговля ВКЛ, Снятие средств ВЫКЛ.","Вставьте ключ + секрет в CPE → Ключи API → Binance → Сохранить → Тестовый аккаунт.","Используйте сканирование Spot Desk/Futures Desk (публичные графики работают даже до ключей).","Практика: Ручная торговля → Начать бумажную торговлю (без живых денег).","Live: установите TP1/TP2/SL + Trailing → Начать торговлю в реальном времени (требуется API).","Управление позициями: редактирование уровней, частичное закрытие, отмена авто.","Лицензия: Пробная версия 7 дней → 3 месяца или пожизненная (цены для владельцев указаны в приложении)."]},"BYBIT":{"title":"Байбит Трейдинг А → Я","steps":["Аккаунт + 2ФА.","Управление API → только торговля, вывод средств отключен.","CPE → Ключи API → Bybit → Сохранить.","Отдел фьючерсов для преступников; Chart Lab для изучения свечей.","Бумажная торговля в первую очередь; Живи после того, как ключи сработают.","След TP+SL: BUY↑/SELL↓."]},"OKX":{"title":"OKX Трейдинг А → Я","steps":["Требуется ключ API + секретный код + фраза-пароль.","Вывод средств всегда отключен.","Сохраните все три поля в ключах CPE.","Бумажная практика → маленький живой размер.","Опечатки в парольной фразе — ошибка №1 — копируйте осторожно."]},"KUCOIN":{"title":"KuCoin Торговля А → Я","steps":["Ключ + Секрет + Парольная фраза.","Только разрешение на торговлю.","Бумага в CPE → тогда живите мало.","Используйте столы спот/фьючерс для сигналов."]},"BITGET":{"title":"Битгет Трейдинг А → Я","steps":["API только с торговлей.","Бумага тогда жива.","Фьючерсы: выберите «Кросс» или «Изолированный» в ручной торговле.","Следуйте TP+SL, чтобы зафиксировать прибыль."]},"GATE":{"title":"Gate.io Торговля А → Я","steps":["Создание ключей API v4 (торговля).","Вывод средств ВЫКЛ.","Сохранить в CPE → попрактиковаться в бумаге.","Сканируйте + Chart Lab на предмет записей перед началом трансляции."]},"MEXC":{"title":"MEXC Трейдинг А → Я","steps":["Начните спотовое мышление.","Ключи в ключах CPE API.","Бумага → жить.","Используйте след, чтобы зафиксировать открытую прибыль."]},"KRAKEN":{"title":"Кракен Трейдинг А → Я","steps":["Генерировать ключ только с разрешением на торговлю.","Нет прав на вывод/внесение средств.","Бумажная практика в CPE.","Также проверяйте каждый действующий заказ на Kraken."]},"COINBASE":{"title":"Coinbase Расширенный А → Я","steps":["Ключи расширенного торгового API.","Точечный стол в CPE.","Бумага тогда жива.","Отключите вывод средств."]},"FOREX_OANDA":{"title":"Форекс (ОАНДА) А → Я","steps":["Открыть демо-версию OANDA → риск ~1%.","Токен личного доступа + идентификатор учетной записи в ключах CPE.","Сканирование Forex Desk + Chart Lab (EURUSD…).","Ручная торговля → Бумага с платформой Форекс.","Живите только после демо уверенности."]},"FOREX_FXCM":{"title":"FXCM Форекс А → Я","steps":["Учетные данные API брокера.","Сначала бумага в CPE.","Следите за сессиями в Лондоне и Нью-Йорке и за пиками новостей.","Вживую после тренировки журнал выглядит чистым."]},"FOREX_MT5":{"title":"MetaTrader 5 А → Я","steps":["Логин+сервер+пароль в CPE Keys.","По возможности отдавайте предпочтение инвесторскому (прочитанному) паролю.","Практикуйтесь лотами 0,01.","Бумага в ЦПЭ; живите через брокера, когда будете готовы."]},"FOREX_DEMO":{"title":"Демо-курсы Форекс A → Z","steps":["Ключ API не требуется.","Forex Desk + Chart Lab для бесплатных графиков.","Торги только на бумаге (практика).","Когда вы будете готовы стать настоящим брокером, добавьте ключи OANDA / FXCM / MT5 для работы в реальном времени."]}},"forexAz":{"title":"Торговля на Форекс A → Z (полный класс)","lessons":[{"h":"A — Счет и риск","t":"Сначала демо. Риск ~0,5–1% на идею. Никогда не мстите торговлей."},{"h":"Б — Пары","t":"Основные валюты (EURUSD, GBPUSD, USDJPY) до экзотики."},{"h":"С — Свечи","t":"Изучите Доджи, Молот и Поглощение в Chart Lab Forex."},{"h":"D — Ежедневная погрешность","t":"Проверьте более высокий таймфрейм перед входом на 15-30 минут."},{"h":"Е — Записи","t":"Отскок нижней точки BB + подтверждение свечи — это обычная практика."},{"h":"F — Фибо","t":"Откаты 50%/61,8% часто используются в качестве тренировочных зон."},{"h":"G — Голы (ТП)","t":"TP1 в масштабе, TP2 бегун, трейл SL."},{"h":"Ч — Часы","t":"Перекрытие Лондона и Нью-Йорка = больше движения."},{"h":"Я — Индикаторы","t":"RSI + MACD + BB вместе; избегайте перегрузки индикатора."},{"h":"Дж — Журнал","t":"Регистрируйте каждую бумажную/реальную сделку в CPE Journal."},{"h":"К — Ключи","t":"Живому форекс-брокеру нужен API/токен; демо-ставки не нужны."},{"h":"Л — Лоты","t":"Начните с 0,01 лота на практике."},{"h":"М — Мышление","t":"Процесс важнее прогноза. Пропускайте плохие дни."},{"h":"Н — Новости","t":"Проверяйте новости и хитрости перед важными событиями."},{"h":"О — Заказы","t":"Всегда устанавливайте SL. Трейлинг защищает открытую прибыль."},{"h":"П — Практика","t":"Кнопка Paper Trade = практика без живого API."},{"h":"Вопрос — Качество","t":"Меньшее количество качественных настроек побеждает чрезмерную торговлю."},{"h":"R — Риск: вознаграждение","t":"По возможности стремитесь к таким схемам, в которых вознаграждение ≥ риска."},{"h":"S — Сеансы","t":"Азия тише; Лондон/Нью-Йорк более активен."},{"h":"Т — Тенденции","t":"Во время обучения торгуйте с трендом более высокого TF."},{"h":"У — Обновления","t":"Посмотрите баннер обновления CPE + интерактивная помощь."},{"h":"V — Волатильность","t":"Будьте терпеливее, когда ATR резко возрастает."},{"h":"W — API вывода","t":"Никогда не включайте вывод средств для любого ключа API."},{"h":"X — выходы","t":"Частичный TP + след побеждает надежду."},{"h":"Y — Ваш план","t":"Напишите правила; следуйте за ними в ручном/автоматическом режиме."},{"h":"Z — Ноль спешки","t":"Никакого ФОМО. Практикуйтесь → затем живите API."}]}};

window.CPE_LEARN.ar = {"intro":"تدرب على الورق/العرض التوضيحي أولاً. ادرس الشموع، والرسوم البيانية، وBB/RSI/Fib، والمال، وعلم النفس - ثم الإشارات (ماذا يعني الشراء/البيع/العقد + ما يجب فعله) وإشارات الفوركس. يحتاج البث المباشر إلى مفتاح واجهة برمجة تطبيقات النظام الأساسي الصحيح (إيقاف عمليات السحب).","candles":[{"shape":"doji","name":"دوجي","color":"#94a3b8","bias":"محايد / انتظر","tip":"فتح ≈ إغلاق — جسم متقاطع أو رفيع. تردد السوق بعد هذه الخطوة.","also":"يعلم أيضًا: لا FOMO. انتظر الشمعة القادمة. بالقرب من BB Extreme + Doji = ضغط الآراء؛ تحقق من منحدر مؤشر القوة النسبية (RSI) قبل تخمين الاتجاه."},{"shape":"hammer","name":"مطرقة","color":"#22c55e","bias":"شراء التحيز","tip":"جسم صغير في الأعلى، وفتيل سفلي طويل (≈2× الجسم) بعد الهبوط - رفض المشترون الأسعار المنخفضة.","also":"أيضًا: ضع تمرين SL أسفل الفتيل المنخفض. الأفضل مع ارتفاع مؤشر BB + مؤشر القوة النسبية (RSI) من منطقة ذروة البيع. علم النفس: الصبر حتى ينتهي الفتيل، لا تشتري منتصفه."},{"shape":"invhammer","name":"المطرقة المقلوبة","color":"#22c55e","bias":"شراء (ضعيف)","tip":"الفتيل العلوي الطويل في الأسفل. دقق المشترون في الارتفاع لكنهم أغلقوا بالقرب من الافتتاح - يحتاج إلى تأكيد اللون الأخضر التالي.","also":"وأيضاً: أضعف من المطرقة وحدها. استخدم كتنبيه، وليس دخول. ارتداد فيبوناتشي 61.8 + المطرقة المقلوبة = منطقة الدراسة فقط حتى تأكيد الشمعة."},{"shape":"shooting","name":"نجم الرماية","color":"#ef4444","bias":"بيع التحيز","tip":"قاع جسم صغير، وفتيل علوي طويل بعد الارتفاع - رفض البائعون الارتفاعات.","also":"أيضًا: SL فوق ارتفاع الفتيل. أقوى بالقرب من امتداد BB / فيب العلوي / ذروة الشراء لمؤشر القوة النسبية. يعلمك: شموع القمر يمكن أن تفشل، لا تطارد اللون الأخضر الأخير."},{"shape":"hanging","name":"الرجل المشنوق","color":"#f59e0b","bias":"بيع الحذر","tip":"يبدو مثل المطرقة ولكنه يظهر بعد الارتفاع - من المحتمل حدوث إرهاق في القمة.","also":"وأيضًا: السياق هو كل شيء (نفس الشكل ≠ نفس التجارة). موقع المجلة: الأعلى مقابل الأسفل. علم النفس: لا تتراجع لمجرد أن الشكل مطابق، بل قم بالتأكيد باستخدام الشمعة التالية + مؤشر القوة النسبية."},{"shape":"engulf_bull","name":"الابتلاع الصاعد","color":"#22c55e","bias":"شراء","tip":"يغطي الجسم الأخضر الجسم الأحمر السابق بالكامل — وقد سيطر المشترون على شريط واحد.","also":"أيضًا: أقوى عند الدعم / BB السفلي / فيب 50–61.8. حجم من تجتاح منخفضة مثل SL. نصيحة مالية: جسم عريض ← SL أوسع ← حجم أصغر."},{"shape":"engulf_bear","name":"الابتلاع الهبوطي","color":"#ef4444","bias":"بيع","tip":"يغطي الجسم الأحمر بالكامل اللون الأخضر السابق - ويهيمن البائعون.","also":"أيضا: الحذر على صفقات الشراء المفتوحة. بالقرب من BB العلوي + مؤشر القوة النسبية> 70 = جودة دراسة عالية. يعلمك المخاطرة: إذا كانت طويلة بالفعل، TP / مسار جزئي بدلاً من الأمل."},{"shape":"morning","name":"نجمة الصباح","color":"#22c55e","bias":"شراء","tip":"3 شموع: أحمر كبير → نجمة صغيرة → أخضر كبير. قصة عكس القاع.","also":"وأيضاً: الصبر المتعدد الشموع. أدخل بعد الإغلاق الثالث؛ SL تحت مستوى النجوم المنخفض. يتحد بشكل جيد مع BB السفلي + تباعد مؤشر القوة النسبية الصعودي."},{"shape":"evening","name":"نجمة المساء","color":"#ef4444","bias":"بيع","tip":"3 شموع: خضراء كبيرة → نجمة صغيرة → حمراء كبيرة. قصة الانعكاس الأعلى.","also":"وأيضاً: لا تقصر النجمة الوسطى وحدها. انتظر الإغلاق الثالث. التقاء تمديد BB / Fib العلوي. علم النفس: تجاهل FOMO من الجولة الخضراء الأولى."},{"shape":"maru_bull","name":"الثور ماروبوزو","color":"#22c55e","bias":"ضغط شراء قوي","tip":"جسم أخضر طويل، بدون فتائل تقريبًا - يتحكم المشترون في الفتح → الإغلاق.","also":"أيضًا: دليل استمرار الاتجاه، وليس دائمًا شراء القاع. المشي على الفرقة ممكن. المخاطرة: مطاردة Marubozu المتأخر دون التراجع إلى منتصف BB / Fib."},{"shape":"maru_bear","name":"الدب ماروبوزو","color":"#ef4444","bias":"ضغط بيع قوي","tip":"جسم أحمر طويل، بدون فتائل تقريبًا - البائعون هم المسيطرون.","also":"وأيضاً: لا تلتقط السكاكين المتساقطة. انتظر ارتداد BB/Fib + Hammer لاحقًا. يعلم: الضغط القوي = حجم أصغر أو الوقوف جانباً."},{"shape":"spin","name":"الغزل الأعلى","color":"#94a3b8","bias":"التردد","tip":"جسم صغير، فتائل علوية + سفلية - قاتل كلا الجانبين، ولم يفز أحد بشكل واضح.","also":"أيضا: داخل BB الضغط في كثير من الأحيان. وقفة التداول؛ انتظر الاستراحة + شمعة الاتجاه. درس في علم النفس: السوق لا تستطيع \"فعل أي شيء\" - فالسعر المسطح خيار صالح."},{"shape":"pierce","name":"خط الثقب","color":"#22c55e","bias":"شراء","tip":"الأحمر ثم الأخضر الذي يفتح على مستوى أدنى ولكنه يغلق فوق نقطة منتصف اللون الأحمر السابق.","also":"وأيضا: أخف من الإبتلاع. تأكيد مع بدوره مؤشر القوة النسبية. مثقاب ورقي جيد لقراءة القوة الجزئية - ليست كل الألوان الخضراء متساوية."},{"shape":"darkcloud","name":"غطاء السحابة المظلمة","color":"#ef4444","bias":"بيع","tip":"الأخضر ثم الأحمر الذي يفتح أعلى ولكنه يغلق تحت نقطة منتصف اللون الأخضر السابق.","also":"أيضًا: إنذار مبكر قبل اجتياح الدب الكامل. مسارات طويلة / خذ TP1. يعلم القياس قبل طباعة الانعكاس الكامل."},{"shape":"soldiers","name":"ثلاثة جنود البيض","color":"#22c55e","bias":"شراء الاتجاه","tip":"ثلاثة مستويات خضراء صاعدة مع إغلاقات أعلى - شراء ثابت.","also":"وأيضاً: إشارة قوية للاتجاه الصعودي؛ تعتبر عمليات التراجع إلى Fib 38–50 أو BB mid بمثابة إضافات تدريبية. مخاطر الثقة المفرطة بعد 3 خضروات - حافظ على نسبة المخاطر ثابتة."},{"shape":"crows","name":"ثلاثة الغربان السوداء","color":"#ef4444","bias":"بيع الاتجاه","tip":"ثلاثة ألوان حمراء هابطة مع إغلاق منخفض - بيع ثابت.","also":"وأيضاً: لا تخفض المتوسط. هيكل الانتظار. يمكن أن يظل مؤشر القوة النسبية في منطقة ذروة البيع - قاعدة المال: حد الخسارة> الأمل."},{"shape":"harami_bull","name":"الحرامي الصاعد","color":"#22c55e","bias":"شراء (ناعم)","tip":"أحمر كبير، ثم أخضر صغير داخل الجسم السابق - يتقلص ضغط البيع.","also":"أيضًا: إشارة الإيقاف المبكر. تأكيد الاحتياجات. أزواج مع دراسة التباعد الصعودي لمؤشر القوة النسبية (RSI). يعلم القراءة \"تلاشي القوة\" وليس الانتكاسات فقط."},{"shape":"harami_bear","name":"الحرامي الهابط","color":"#ef4444","bias":"بيع (ناعم)","tip":"اللون الأخضر الكبير، ثم اللون الأحمر الصغير في الداخل - يتقلص ضغط الشراء.","also":"وأيضا: خذ أجزاء من الأطوال. ليس قصيرًا تلقائيًا. علم النفس: الجشع بعد اللون الأخضر الكبير غالبًا ما يتجاهل تحذير الحرمي."},{"shape":"tweezer_bot","name":"الملقط السفلي","color":"#22c55e","bias":"شراء","tip":"شمعتان مع قيعان متطابقة — اختبار مزدوج للدعم.","also":"أيضًا: ضع علامة على هذا المستوى المنخفض كهيكل. SL أقل بقليل. تساعد محاذاة Fib/BB. نموذج الرسم البياني ابن عم Double Bottom - نفس درس الدعم."},{"shape":"tweezer_top","name":"الملقط الأعلى","color":"#ef4444","bias":"بيع","tip":"شمعتان لهما أعلى مستويات متطابقة — اختبار مزدوج للمقاومة.","also":"وأيضاً: علامة المقاومة. ابن عم مزدوج الأعلى. فشل مؤشر القوة النسبية عند أعلى مستوياته = التقاء. يعلم: رفض نفس السعر مرتين = احترام المستوى."},{"shape":"longlegged","name":"دوجي ذو الأرجل الطويلة","color":"#94a3b8","bias":"التردد","tip":"فتائل علوية وسفلية طويلة جدًا بجسم صغير - معركة عنيفة في اتجاهين انتهت حيث بدأت.","also":"أيضًا: غالبًا ما يتبع ذلك تحرك كبير، لكن الاتجاه غير معروف - انتظر حتى تنكسر الشمعة. يعلم: التقلبات العالية ليست عالية اليقين."},{"shape":"dragonfly","name":"اليعسوب دوجي","color":"#22c55e","bias":"شراء التحيز","tip":"الافتتاح = الإغلاق = الارتفاع، مع فتيل سفلي طويل - يدفع البائعون إلى الأسفل ويدفعه المشترون مباشرة إلى الأعلى.","also":"أيضًا: الأقوى عند الدعم / انخفاض BB بعد الانخفاض. SL تحت ذيل الفتيل. يعلمنا أن الرفض قصة وليس ضمانًا - أكد الشمعة التالية."},{"shape":"gravestone","name":"شاهد القبر دوجي","color":"#ef4444","bias":"بيع التحيز","tip":"الافتتاح = الإغلاق = الانخفاض، مع وجود فتيل علوي طويل - حيث يدفع المشترون للأعلى ويسحبه البائعون مرة أخرى إلى القاع.","also":"أيضًا: الأقوى عند المقاومة / BB العلوي / ذروة الشراء لمؤشر القوة النسبية. مرآة اليعسوب. يعلمنا أن الارتفاع المرتفع الذي يغلق عند القاع هو اختراق فاشل."},{"shape":"inside_bar","name":"داخل بار","color":"#94a3b8","bias":"اللف / الانتظار","tip":"تقع الشمعة الثانية تمامًا داخل الشمعة الأولى — حيث ينضغط النطاق ويحبس السوق أنفاسه.","also":"أيضًا: اختراق العمود الأم هو عامل التحفيز — قم بالتداول في اتجاه الاختراق. أزواج مع ضغط BB. يعلم: الانكماش يأتي قبل التمدد."},{"shape":"outside_bar","name":"بار خارجي","color":"#22c55e","bias":"الاختراق / الانعكاس","tip":"تبتلع الشمعة الثانية الشمعة الأولى من الأعلى إلى الأسفل - وهي عملية استحواذ عنيفة داخل شريط واحد.","also":"أيضًا: الاتجاه = حيث يغلق الشريط الخارجي. الشريط الكبير يعني SL كبير، لذا الحجم أصغر. يعلم: شريط واحد يمكن أن يمحو الثلاثة الأخيرة."},{"shape":"belt_bull","name":"عقد الحزام الصاعد","color":"#22c55e","bias":"شراء","tip":"يفتح عند القاع دون وجود فتيل أقل ويتحول إلى اللون الأخضر - سيطر المشترون على العلامة منذ أول علامة.","also":"أيضًا: أقوى بعد وجود فجوة للأسفل أو مباشرة إلى الدعم. SL تحت العراء. يعلم: محرك فتح يظهر النية الحقيقية."},{"shape":"belt_bear","name":"عقد الحزام الهبوطي","color":"#ef4444","bias":"بيع","tip":"يفتح عند الأعلى بدون فتيل علوي ويتحول إلى اللون الأحمر - حيث سيطر عليه البائعون من الفتح.","also":"أيضًا: الأقوى بعد وجود فجوة لأعلى أو عند المقاومة. الدرب يطول. يعلم: الخطوة الأولى يمكن أن تحدد اليوم كله."},{"shape":"kick_bull","name":"كيكر الصاعد","color":"#22c55e","bias":"شراء قوي","tip":"شمعة حمراء، ثم فجوة لأعلى إلى شمعة خضراء - يتقلب المزاج بين فترات الإغلاق دون أي تداخل.","also":"وأيضاً: نادر وقوي؛ الفجوة مطلوبة، لا يسمح بالتداخل. يعلمنا: المشاعر يمكن أن تنقلب بينما السوق نائم."},{"shape":"kick_bear","name":"كيكر الهبوطي","color":"#ef4444","bias":"بيع قوي","tip":"شمعة خضراء، ثم فجوة للأسفل إلى شمعة حمراء - اختفى المشترون بين الإغلاق.","also":"أيضًا: الخروج من صفقات الشراء بسرعة — لا ينتظرك اللاعبون. يعلمنا: الفجوة هي إعادة تسعير السوق عندما تكون بعيدًا."},{"shape":"abandoned","name":"الطفل المهجور الصاعد","color":"#22c55e","bias":"شراء قوي","tip":"شمعة حمراء، ثم شمعة دوجي ذات فجوات، ثم شمعة خضراء ذات فجوات - جزيرة وحيدة من التردد.","also":"أيضًا: يجب أن تنفصل دوجي عن كلا الجانبين. نادرة ولكن ذات جودة عالية في القيعان. يعلمنا أن الإنتكاسات تبدأ حيث يستسلم الجميع."},{"shape":"three_inside_up","name":"ثلاثة من الداخل لأعلى","color":"#22c55e","bias":"شراء","tip":"Harami الصعودي بالإضافة إلى الشمعة الخضراء الثالثة التي تغلق فوق الشمعة الأولى - انهار الشريط الداخلي أخيرًا.","also":"وأيضاً: الحرامي المؤكد أقوى بكثير من الحرامي العاري. SL تحت الحرامي المنخفض. يعلم: التأكيد يتفوق على التنبؤ."},{"shape":"three_inside_down","name":"ثلاثة بالداخل للأسفل","color":"#ef4444","bias":"بيع","tip":"Harami الهبوطي بالإضافة إلى شمعة حمراء ثالثة تغلق أسفل الشمعة الأولى - انهار الشريط الداخلي.","also":"وأيضًا: قطع الصفقات بمجرد إغلاق الثالثة. يعلمنا أن التوقف المؤقت الفاشل يمكن ببساطة استئناف الاتجاه القديم."},{"shape":"three_methods_bull","name":"ارتفاع ثلاث طرق","color":"#22c55e","bias":"شراء الاتجاه","tip":"شمعة خضراء طويلة، بداخلها ثلاثة ألوان حمراء صغيرة، ثم شمعة خضراء طويلة أخرى - راحة داخل الارتفاع.","also":"وأيضًا: الوقفة لا تترك نطاق الشمعة الأولى أبدًا، لذا فإن الاتجاه هادئ. تداول كسر الشمعة الأخيرة. يعلم: الاتجاهات تستقر دون انقطاع."},{"shape":"three_methods_bear","name":"السقوط بثلاث طرق","color":"#ef4444","bias":"بيع الاتجاه","tip":"شمعة حمراء طويلة، بداخلها ثلاث قطع صغيرة من اللون الأخضر، ثم شمعة حمراء طويلة أخرى - راحة داخل السقوط.","also":"أيضًا: مرآة الطرق الثلاثة الصاعدة. لا تشتري الخضر الصغيرة - فهي ضجيج. يعلم: التراجعات داخل النطاق ليست انعكاسات."},{"shape":"tower_bot","name":"أسفل البرج","color":"#22c55e","bias":"شراء عكس","tip":"شمعة حمراء طويلة، ومجموعة من الشموع الصغيرة، ثم شمعة خضراء طويلة، يتغير المزاج عبر قاعدة مسطحة.","also":"وأيضًا: الوسط المسطح هو المعركة والشمعة الأخيرة تعلن الفائز. يعلم: القواعد تستغرق وقتا."},{"shape":"tower_top","name":"برج الأعلى","color":"#ef4444","bias":"بيع العكس","tip":"شمعة خضراء طويلة، ومجموعة من الشموع الصغيرة، ثم شمعة حمراء طويلة - يستنفد المشترون ويتولى البائعون المسؤولية.","also":"أيضًا: مرآة قاع البرج. خذ الأجزاء الجزئية بينما تتشكل القاعدة. يعلم: القمم هي عملية، وليس لحظة."}],"chartPatterns":[{"shape":"double_bot","name":"قاع مزدوج (ث)","color":"#22c55e","bias":"شراء التحيز","tip":"قاعين بالقرب من نفس السعر، ثم كسر القمة الوسطى – على شكل W.","also":"أيضًا: كسر خط العنق = الزناد التدريبي. قياس الارتفاع لفكرة TP. روابط إلى Tweezer Bottom + Fib من الذروة → low. المخاطرة: اختراق كاذب — الانتظار بالقرب من خط العنق."},{"shape":"double_top","name":"قمة مزدوجة (M)","color":"#ef4444","bias":"بيع التحيز","tip":"قمتان بالقرب من نفس السعر، ثم كسر القاع الأوسط — شكل M.","also":"أيضًا: نفس Tweezer Top على نطاق أوسع. درب طويل قبل كسر خط العنق. علم النفس: ثاني أعلى FOMO باهظ الثمن - كانت الخطة موجودة بالفعل."},{"shape":"hs_top","name":"الرأس والكتفين","color":"#ef4444","bias":"بيع التحيز","tip":"الكتف الأيسر، الرأس الأعلى، الكتف الأيمن؛ كسر خط العنق إلى أسفل.","also":"أيضا: التوزيع الكلاسيكي. الهدف ≈ ارتفاع الرأس تحت خط العنق. غالبًا ما يتباعد مؤشر القوة النسبية عند الرأس. يعلم الصبر متعدد التأرجح - وليس التداول بشمعة واحدة."},{"shape":"ihs","name":"معكوس H&S","color":"#22c55e","bias":"شراء التحيز","tip":"رأسا على عقب H&S في القيعان - انفصال خط العنق إلى الأعلى.","also":"وأيضاً: قصة التراكم. قم بالتأكيد بالحجم/الزخم إذا كان متاحًا. ارتديه مع Morning Star في منطقة الكتف اليمنى لدراسة التقاء."},{"shape":"triangle","name":"مثلث (ضغط)","color":"#f0b429","bias":"انتظار الاختراق","tip":"الارتفاعات المنخفضة + الضغط على المستويات المنخفضة الأعلى - بناء الطاقة.","also":"أيضًا: نفس درس ضغط BB. لا تخمن الاتجاه في الداخل. استراحة التجارة + إغلاق الشمعة. المال: حجمه بعد الاتجاه المعلوم."},{"shape":"flag","name":"علم الثور","color":"#22c55e","bias":"شراء تابع.","tip":"ارتفاع حاد (القطب) ثم قناة صغيرة هابطة/جانبية — ثم استمرار.","also":"أيضًا: غالبًا ما يكون عمق علم Fib ضحلًا (38٪). عمود ماروبوزو + علم = ممارسة الاتجاه. لا تشترِ متأخرًا بعد التمديد الكامل دون التراجع."},{"shape":"channel","name":"قناة الاتجاه","color":"#38bdf8","bias":"مع الاتجاه","tip":"السعر بين الخطوط المتوازية الصاعدة (أو الهابطة) — أدوات التجارة المتأرجحة.","also":"أيضًا: شراء قناة سفلية + مطرقة في الاتجاه الصعودي؛ بيع العلوي + شهاب ستار. BB منتصف غالبا ما يتتبع القناة. يعلم \"أين\" وليس فقط \"أي شمعة\"."},{"shape":"support_res","name":"الدعم والمقاومة","color":"#a78bfa","bias":"السياق أولاً","tip":"المناطق الأفقية التي يتفاعل فيها السعر بشكل متكرر — الخريطة الموجودة أسفل كل شمعة.","also":"أيضًا: كل نمط يكون أقوى عند مستويات الدعم/المقاومة. ارسم المناطق على Chart Lab قبل BB/RSI. علم النفس: المستويات > النصائح؛ اكتبهم قبل الدخول"},{"shape":"triple_top","name":"قمة ثلاثية","color":"#ef4444","bias":"بيع التحيز","tip":"ثلاثة ارتفاعات بنفس السعر تقريبًا - يفشل المشترون ثلاث مرات عند جدار واحد.","also":"أيضًا: أقوى من القمة المزدوجة (ثلاثة رفضات = عرض عنيد). كسر خط العنق هو الزناد. الهدف ≈ ارتفاع النمط. يعلم: المستوى، وليس الشمعة، هو الرئيس."},{"shape":"triple_bot","name":"القاع الثلاثي","color":"#22c55e","bias":"شراء التحيز","tip":"ثلاثة مستويات منخفضة بنفس السعر تقريبًا - يفشل البائعون ثلاث مرات في طابق واحد.","also":"أيضًا: مرآة ثلاثية القمة. يمكن أن تكون كل لمسة بمثابة دراسة للمطرقة/الملقط. انتظر كسر خط العنق + الإغلاق. يعلم الصبر عبر العديد من التقلبات."},{"shape":"cup_handle","name":"كوب ومقبض","color":"#22c55e","bias":"شراء تابع.","tip":"شكل \"U\" (كوب) مستدير ثم تراجع صغير (المقبض) - استمرار بعد الراحة.","also":"أيضًا: شائع لدى المتداولين الاختراقيين. يجب أن يكون المقبض سطحيًا وقصيرًا، فالمقبض العميق يعني ضعف الأيدي. أدخل عند كسر المقبض مع تأكيد الشمعة."},{"shape":"rounding_bot","name":"تقريب القاع","color":"#22c55e","bias":"شراء عكس","tip":"انخفاض بطيء وسلس - يتلاشى البيع تدريجيًا، ثم يتولى المشترون زمام الأمور.","also":"أيضًا: قاع مزدوج بطيء الحركة. الرسالة هي أن البائعين استنفدوا طاقتهم، ولم يحدث ارتفاع واحد - فالصبر الكامل مطلوب."},{"shape":"rounding_top","name":"تقريب الأعلى","color":"#ef4444","bias":"بيع العكس","tip":"ارتفاع \"القبة\" السلس - يتلاشى الشراء تدريجيًا قبل أن يتراجع السعر.","also":"وأيضاً: مرآة تقريب القاع. خذ الأجزاء مبكرًا بينما يموت الزخم. يعلم: القمم هي عملية، وليس شمعة واحدة."},{"shape":"rising_wedge","name":"الوتد الصاعد","color":"#ef4444","bias":"بيع التحيز","tip":"يرتفع كلا السكة، لكنهما يتقاربان للأعلى، حيث يتعب المشترون مع ضيق النطاق.","also":"وأيضا: مضلل لأن السعر لا يزال يرتفع؛ التضييق هو الدليل الحقيقي. في كثير من الأحيان ينهار. لا تطارد الدفعة الأخيرة."},{"shape":"falling_wedge","name":"إسفين السقوط","color":"#22c55e","bias":"شراء التحيز","tip":"يسقط كلا القضبان، لكنهما يتقاربان للأسفل - يتعب البائعون مع ضيق النطاق.","also":"وأيضا: مرآة الوتد الصاعد. في كثير من الأحيان ينكسر. المطرقة في ذيل الإسفين هي دراسة كلاسيكية. انتظر الاستراحة + الإغلاق."},{"shape":"asc_triangle","name":"المثلث الصاعد","color":"#f0b429","bias":"شراء التحيز","tip":"سقف مسطح + أرضية مرتفعة - يستمر المشترون في الصعود إلى مقاومة ثابتة.","also":"وأيضاً: يتزايد الضغط على سعر واحد؛ الاختراق شائع. أدخل عند الإغلاق فوق السقف. يعلم: المشترين ينفد صبرهم."},{"shape":"desc_triangle","name":"المثلث الهابط","color":"#f0b429","bias":"بيع التحيز","tip":"أرضية مسطحة + سقف هابط - يستمر البائعون في الدفع نحو دعم ثابت.","also":"وأيضاً: مرآة المثلث الصاعد. الاختراق إلى أسفل أمر شائع. أدخل عند الإغلاق أسفل الأرضية. يعلم: البائعون يكتسبون السيطرة."},{"shape":"pennant","name":"راية","color":"#22c55e","bias":"استمرار","tip":"عمود حاد ثم مثلث ضيق وصغير - فترة راحة قصيرة جدًا قبل استئناف الاتجاه.","also":"وأيضاً: كالعلم ولكنه أقصر ومثلث. قياس القطب لفكرة الهدف. لا تخمن أبدًا ما بداخل الملف الصغير."},{"shape":"flag_bear","name":"تحمل العلم","color":"#ef4444","bias":"بيع تابع.","tip":"هبوط حاد (قطب) ثم قناة صغيرة صاعدة/جانبية — ثم الاستمرار للأسفل.","also":"وأيضاً: مرآة علم الثور. الارتداد الصغير هو توقف مؤقت، وليس انعكاسًا. طارد العلم وستشتري بأسوأ سعر - انتظر الاستراحة."},{"shape":"rectangle","name":"مستطيل (المدى)","color":"#f0b429","bias":"تجارة المدى","tip":"يرتد السعر بين السقف المسطح والأرضية — صندوق جانبي.","also":"أيضًا: قم بتلاشي الحواف من الداخل، وتداول الكسر في الخارج. عادةً ما يتم ضغط BB داخل مستطيل. يعلم: الانضباط من مستوى إلى مستوى."},{"shape":"broadening","name":"توسيع التشكيل","color":"#f0b429","bias":"الحذر","tip":"ارتفاعات أعلى وأدنى مستويات منخفضة - يتم إبعاد النطاق بدلاً من الضغط عليه.","also":"أيضًا: سوق فوضوي وعاطفي. يتم ضرب نقاط التوقف في كلا الاتجاهين. حجم أصغر أو الوقوف جانبا. غالبًا ما ينتهي بحركة عنيفة في اتجاه واحد."},{"shape":"diamond","name":"الماس","color":"#f0b429","bias":"عكس","tip":"واسعة من المنتصف، وضيقة من كلا الطرفين - تشكيل كلاسيكي للقمة/القاع.","also":"وأيضًا: المثلث الذي يتحول ثم لا يتحول. اتجاه الاختراق يقرر. نادر وبطيء، لذا تبدو معظم الصفوف وكأنها ضوضاء - تحلى بالصبر."},{"shape":"island_rev","name":"عكس الجزيرة","color":"#ef4444","bias":"عكس","tip":"فجوات الأسعار بعيدة، ويتم التداول في مجموعة وحيدة، ثم تعود الفجوات إلى الوراء - \"جزيرة\".","also":"أيضًا: يحتاج إلى فجوات حقيقية (أكثر شيوعًا في الأسهم/الفوركس). الجزيرة محاصرة المشترين أو البائعين. تعامل مع الفجوات كإشارة، وليس شموع الجزيرة."},{"shape":"breakaway_gap","name":"الفجوة الانفصالية","color":"#22c55e","bias":"بداية الاتجاه","tip":"فجوة خارج نطاق أو قاعدة — تبدأ الحركة بالقوة، وليس بالضغط.","also":"وأيضًا: على عكس فجوة الإرهاق، تظهر في وقت مبكر من الحركة. غالبًا ما تعمل الفجوات كدعم/مقاومة لاحقًا. يعلمنا: الزخم مقابل فجوات القيمة."},{"shape":"v_reversal","name":"عكس V","color":"#22c55e","bias":"عكس","tip":"سقوط حر حاد يظهر على الفور بدون قاعدة - حرف \"V\".","also":"وأيضاً: سريع ومخيف؛ غالبًا ما تكون مدفوعة بالأخبار. من الصعب الإمساك به، ومن السهل مطاردته. انتظر تراجعًا صغيرًا + شمعة بدلاً من شراء السنبلة."},{"shape":"harmonic","name":"النمط التوافقي","color":"#f0b429","bias":"مناطق الانعكاس","tip":"شكل متعرج مُقاس (X-A-B-C-D) حيث تحتوي كل ساق على نسبة فيبوناتشي - خريطة نمط \"Gartley/Bat\".","also":"وأيضاً: المتقدم. النقطة D هي منطقة الدخول، التي تحددها النسب، وليس المشاعر. سيد عادي فيب أولا؛ هذا هو مستوى فيبوناتشي أعمق."}],"modules":[{"id":"bb","title":"1 · بولينجر باند (BB)","summary":"نطاقات التقلب حول المتوسط المتحرك. تعلم الضغط، والمشي على النطاق، واللمس السفلي/العلوي + تأكيد الشمعة - الإعداد التدريبي الأساسي لـ CPE.","lessons":[{"h":"ما هو BB","t":"خطوط بولينجر = المتوسط المتحرك البسيط (SMA) المتوسط (غالبًا 20) + النطاقات العلوية/السفلية عند الانحرافات المعيارية N (غالبًا 2). تتسع النطاقات عندما ترتفع التقلبات وتضغط عندما يكون السوق هادئًا."},{"h":"الفرقة الوسطى","t":"الخط الأوسط هو المتوسط. السعر فوق المتوسط ​​غالبا ما يظهر ضغطا صعوديا. يظهر أدناه الضغط الهبوطي. استخدمه كخط متحيز ديناميكي، وليس كخط شراء/بيع سحري."},{"h":"النطاق السفلي (ممارسة الشراء)","t":"يمكن أن تعني علامة السعر على النطاق السفلي بعد الانخفاض \"امتدت للأسفل\". لا تشتري كل لمسة. انتظر حتى تظهر الشمعة الصاعدة (Hammer، Engulfing) ومن الأفضل ظهور مؤشر القوة النسبية (RSI)."},{"h":"النطاق العلوي (بيع / تحذير)","t":"يمكن أن تعني علامة السعر على النطاق العلوي \"ممدودًا\". في الاتجاه الصعودي، يمكن للسعر ركوب النطاق العلوي (المشي على النطاق). تفضل أفكار البيع فقط مع الشمعة الهابطة + ضعف TF العالي."},{"h":"ضغط","t":"النطاقات الضيقة = تقلبات منخفضة ← غالبًا ما يتبع ذلك الاختراق. لا تخمن الاتجاه داخل الضغط المحكم؛ قم بتمييز الاختراق والتأكيد باستخدام الشمعة + الحجم إذا كان ذلك متاحًا."},{"h":"المشي الفرقة","t":"في الاتجاه القوي، يعانق السعر النطاق العلوي (أو السفلي) للعديد من الشموع. إن محاربة ذلك من خلال تلاشي الارتداد المتوسط ​​هو خطأ شائع للمبتدئين."},{"h":"BB + مختبر الرسم البياني","t":"في مكاتب/مختبرات الرسم البياني CPE، ادرس BB بالشموع على العرض التوضيحي. التدريب: النطاق السفلي + المطرقة ← تجارة الورق مع SL أسفل الفتيل، TP1 بالقرب من النطاق الأوسط."},{"h":"مجموعة BB+RSI","t":"مرشح تدريبي أقوى: انخفاض مستوى BB + مؤشر القوة النسبية (RSI) في منطقة ذروة البيع (أو الارتفاع من منطقة ذروة البيع) + شمعة صعودية. BB العلوي + مؤشر القوة النسبية في منطقة ذروة الشراء + شمعة هبوطية للتمرين القصير."},{"h":"وقف التنسيب","t":"تدريب طويل: SL تحت التأرجح المنخفض / أسفل فتيلة النطاق السفلي. تدريب قصير: SL فوق قمة التأرجح. لا تدخل أبدًا في تجارة BB بدون SL مكتوب."},{"h":"الأهداف","t":"المسار المشترك: TP1 عند النطاق الأوسط، TP2 باتجاه النطاق أو المسار المقابل. قم بالتوسيع - لا تحتاج إلى الخطوة بأكملها."},{"h":"الأطر الزمنية","t":"تقرر التحيز على ارتفاع TF (4H/1D). أدخل على 15 م / 30 م BB + شمعة. يؤدي خلط TFs العشوائي إلى ظهور إشارات متضاربة."},{"h":"أخطاء يجب تجنبها","t":"شراء كل لمسة نطاق منخفض في سوق متدهور؛ بيع كل لمسة علوية في سباق القمر؛ لا سي؛ تجاهل طفرات الأخبار التي توسع النطاقات بعنف."},{"h":"قائمة مراجعة الممارسة","t":"① انحياز TF أعلى ② لمسة BB أو كسر الضغط ③ تأكيد الشمعة ④ موافقة مؤشر القوة النسبية ⑤ مجموعة المخاطر٪ ⑥ الورقة الأولى ⑦ نتيجة المجلة."}]},{"id":"rsi","title":"2 · مؤشر القوة النسبية (مؤشر القوة النسبية)","summary":"مذبذب الزخم 0-100. الافتراضي 14 فترة. استخدم مع BB والشموع - لا تستخدم مؤشر القوة النسبية (RSI) بمفرده كنظام كامل.","lessons":[{"h":"ما يقيسه مؤشر القوة النسبية","t":"يقارن مؤشر القوة النسبية متوسط المكاسب مقابل الخسائر على أشرطة N. مؤشر القوة النسبية المرتفع = الزخم الصعودي الأخير؛ مؤشر القوة النسبية المنخفض = الزخم الهبوطي الأخير. إنها ليست \"ذروة الشراء = يجب البيع\" في كل مرة."},{"h":"المناطق الكلاسيكية","t":"في كثير من الأحيان: فوق 70 = منطقة ذروة الشراء، أقل من 30 = منطقة ذروة البيع. في الاتجاهات القوية، يمكن أن يظل مؤشر القوة النسبية في منطقة ذروة الشراء/ذروة البيع لفترة طويلة - وهذا أمر طبيعي."},{"h":"خط الوسط 50","t":"عبور مؤشر القوة النسبية فوق 50 يمكن أن يدعم التحيز الصعودي؛ أقل من 50 ميل هبوطي. يستخدم العديد من المتداولين 50 كمرشح للاتجاه مع النطاق الأوسط BB."},{"h":"الاختلاف - الصعودي","t":"السعر يشكل قاعًا أدنى، ومؤشر القوة النسبية يشكل قاعًا أعلى ← يضعف الزخم على الجانب الهبوطي. لا تزال تنتظر حتى تنكسر الشمعة + الهيكل قبل إدخال الورق."},{"h":"الاختلاف - هبوطي","t":"السعر مرتفع، ومؤشر القوة النسبية أقل ارتفاعًا → يتلاشى الزخم الصعودي. قم بالتأكيد باستخدام Shooting Star / الابتلاع بالقرب من المقاومة أو BB العلوي."},{"h":"تقلبات الفشل","t":"يفشل مؤشر القوة النسبية في إعادة اختبار الحد الأقصى السابق ثم يعبر عائداً عبر المستوى 50 - وهو دليل على تحول الزخم المبكر. ادمجها مع بنية Chart Lab."},{"h":"مؤشر القوة النسبية + BB (نمط CPE)","t":"تدرب على الشراء: السعر بالقرب من BB السفلي، مؤشر القوة النسبية ≥ 35 (أو يرتفع من ≥ 30)، الشمعة الصعودية. تمرين قصير: BB العلوي، مؤشر القوة النسبية ≥ 65–70، الشمعة الهبوطية."},{"h":"الاختلاف الخفي","t":"دليل استمرار الاتجاه (على سبيل المثال، انخفاض السعر، انخفاض مؤشر القوة النسبية في الاتجاه الصعودي). متقدم - إتقان الاختلاف الكلاسيكي أولاً على العرض التوضيحي."},{"h":"الإعدادات","t":"مؤشر القوة النسبية (14) هو الافتراضي الشائع. مؤشر القوة النسبية الأقصر = المزيد من الضوضاء. لا تستمر في تغيير الإعدادات لفرض إشارة."},{"h":"يخرج مع مؤشر القوة النسبية","t":"إذا قمت بالشراء في منطقة ذروة البيع، فإن جني ربح جزئي عندما يصل مؤشر القوة النسبية إلى المنطقة الوسطى/العليا أمر معقول. قم بتتبع الباقي باستخدام الهيكل أو وسط BB."},{"h":"الأخبار ومؤشر القوة النسبية","t":"الأخبار الكبيرة يمكن أن تؤدي إلى ارتفاع مؤشر القوة النسبية على الفور. تفضل الانتظار حتى تنتهي الشمعة العنيفة الأولى قبل التصرف على مؤشر القوة النسبية (RSI) المتطرف."},{"h":"أخطاء","t":"تقصير كل مؤشر القوة النسبية > 70 في السوق الصاعدة؛ شوق كل مؤشر القوة النسبية <30 في حادث تحطم الدب. لا التقاء. العودة الانتقامية عندما يبدو مؤشر القوة النسبية \"أفضل\"."},{"h":"قائمة مراجعة الممارسة","t":"① لاحظ قيمة مؤشر القوة النسبية + المنحدر ② تحقق من موقع BB ③ تأكيد الشمعة ④ TF أعلى ⑤ الورق + المجلة ⑥ فكرة واحدة في كل مرة."}]},{"id":"fib","title":"3 · فيبوناتشي (الارتداد والامتداد)","summary":"قم بقياس التراجعات والأهداف من أعلى مستوى تأرجح واضح → تأرجح منخفض (أو عكسي). ركز على 38.2 · 50 · 61.8 مع التقاء BB/RSI.","lessons":[{"h":"لماذا يتم استخدام فيب","t":"ويراقب العديد من المتداولين نفس النسب، لذلك تتفاعل السيولة غالبًا بالقرب منها. Fib عبارة عن خريطة للمناطق المحتملة — وليست ضمانًا."},{"h":"نقاط التأرجح","t":"اسحب دائمًا من تأرجح منخفض واضح إلى تأرجح عالي (حركة لأعلى) أو من أعلى إلى منخفض (حركة لأسفل). تقلبات سيئة = مستويات عديمة الفائدة. تدرب على اختيار التقلبات في Chart Lab DEMO."},{"h":"التراجعات الرئيسية","t":"شائع: 23.6% (سطحي)، 38.2%، 50% (ليس نقيًا ولكنه مستخدم على نطاق واسع)، 61.8% (ذهبي)، 78.6% (عميق). يمكن أن تشير التصحيحات العميقة إلى ضعف الاتجاه."},{"h":"عمليات الشراء التراجعية (الاتجاه الصعودي)","t":"بعد الاندفاع للأعلى، انتظر التراجع إلى منطقة 38.2-61.8 + الشمعة الصعودية + ويفضل الدعم المتوسط/الأدنى لـ BB أو ثبات مؤشر القوة النسبية > 40-45."},{"h":"عمليات البيع التراجعية (الاتجاه الهبوطي)","t":"بعد الاندفاع الهبوطي، ارتفع إلى 38.2-61.8 + شمعة هبوطية + فشل مؤشر القوة النسبية تحت 55-60."},{"h":"ملحقات / أهداف","t":"الامتدادات الشائعة: 127.2%، 161.8% تتجاوز التأرجح لأفكار TP2. استخدم مع المسار - لا تفرض علامات التجزئة الدقيقة."},{"h":"التقاء = قوة","t":"مناطق أفضل الممارسات: Fib 50/61.8 + BB الأوسط/الأدنى + الهيكل السابق + مؤشر القوة النسبية RSI. خط فيبوناتشي واحد فقط ضعيف."},{"h":"فيب + بي بي","t":"إذا كان 61.8% يقع بالقرب من نطاق BB السفلي في اتجاه صعودي، فإن هذا التداخل يعد منطقة دراسة ورقية عالية الجودة. أدخل فقط مع تأكيد الشمعة."},{"h":"ألياف متعددة","t":"يجب على المبتدئين استخدام أرجوحة واحدة نظيفة. يؤدي تكديس 5 Fibs إلى إنشاء ضجيج في الرسم البياني وإدخالات FOMO."},{"h":"البطلان","t":"إذا أغلق السعر بشكل واضح فوق مستوى 78.6% ضد تحيزك، فغالبًا ما تفشل فرضية التراجع – قم بالخروج أو الوقوف جانبًا."},{"h":"الفوركس مقابل التشفير","t":"نفس النسب . غالبًا ما تحترم شركات الفوركس المستويات بشكل أكثر نظافة في الجلسات السائلة؛ يمكن للعملات المشفرة أن تخترق ثم تنعكس – حجم أصغر."},{"h":"أخطاء","t":"رسم Fib على تقلبات الضوضاء الصغيرة؛ الدخول في الهواء بدون شمعة؛ تحريك SL أبعد عندما يصمد مستوى Fib \"تقريبًا\"؛ تجاهل ارتفاع TF."},{"h":"قائمة مراجعة الممارسة","t":"① علامة التأرجح ② الملاحظة 38.2/50/61.8 ③ انتظر وصول السعر ④ الشمعة + مؤشر القوة النسبية RSI/BB ⑤ مجموعة المخاطر ⑥ الورق → المجلة."}]},{"id":"money","title":"4 · إدارة الأموال","summary":"كيف يتم استخدام الطريقة فعليًا: نسبة المخاطرة ثابتة، الحجم من التوقف، جزء البنك من الربح، والتوقف لليوم التالي لحد الخسارة. يمكن لـ CPE تطبيق ذلك على التداولات اليدوية والسيارات.","lessons":[{"h":"الهدف من إدارة الأموال","t":"البقاء في اللعبة. لا ينبغي أبدا أن تؤدي التجارة السيئة إلى مسح الحساب. الاتساق يتفوق على تحجيم اليانصيب."},{"h":"كيف يستخدمه المتداولون فعليًا","t":"الممارسة الشائعة هي المخاطر الجزئية الثابتة. لا تقم باختيار مبلغ العملة أولاً. تكتب الإيقاف أولاً، وتقرر أن هذه الفكرة قد تخسر حوالي 1% من الحساب، ثم ينخفض ​​الحجم من ذلك. نقطة التوقف الواسعة تحصل على مركز أصغر. نقطة الوقف الضيقة تحصل على مركز أكبر، ويظل خطر الدولار على حاله تقريبًا. هذه هي الطريقة التي يستخدمها CPE عندما تكون علامة إدارة الأموال قيد التشغيل."},{"h":"مثال عملي (حساب تدريبي بقيمة 1000 دولار)","t":"الحساب 1000 دولار. المخاطرة 1% = 10 دولارات. دخول 100، توقف 98. المسافة = 2%. الحجم = 10 ÷ 0.02 = 500 دولار افتراضي. إذا تم الوصول إلى نقطة الإيقاف، فستكون الخسارة حوالي 10 دولارات، وليس 500 دولار. إذا وصل السعر إلى 103 (1.5 ضعف المخاطرة)، فإن الربح يبلغ حوالي 15 دولارًا. نفس الفكرة في كل زوج: تبقى الدولارات المعرضة للخطر بالقرب من 1%، وتتغير كمية العملة."},{"h":"ما يفعله CPE مع القراد","t":"التجارة الآن → تلقائي: حدد \"استخدام إدارة الأموال\". حفظ التكوين التلقائي. تستخدم كل تجارة سيارات جديدة بعد ذلك حوالي 1٪ من حساب تدريبي بقيمة 1000 دولار بالإضافة إلى النتائج المغلقة، بحجم دخول تلك الإشارة وإيقاف الخسارة. يتم احترام الحد الأدنى للعقود الفورية والآجلة: إذا كان الحد الأدنى للصرف سيخاطر بأكثر من 1٪، فسيتم تخطي هذه الصفقة. بعد حوالي -2% في يوم التقويم، تتوقف السيارات الجديدة حتى اليوم التالي. على الأكثر، يكون حوالي 3% معرضًا للخطر عبر الصفقات المفتوحة. التجارة اليدوية لها نفس العلامة. لا يزال سجل الإشارة يعرض اختبار 10 دولارات مساويًا، وتحته حجم الخطة 1% لحساب 1000 دولار، حتى تتمكن من رؤية كليهما."},{"h":"الربح الجزئي والدرب","t":"الممارسة هي أن تشارك في الهدف الأول (غالبًا حوالي النصف) وتترك الباقي يتتبع. عندما يتحرك أمر الإيقاف لأعلى، يمكن للهدف أن يتحرك أيضًا، وبالتالي يمكن للفائز أن يدفع أكثر من الهدف الأول. المخاطر على الفكرة الأصلية لا تزيد. الإشارة القوية ليست سببًا للمخاطرة بنسبة 5٪. يتم استخدام نفس 1٪. المسار هو ما يسمح للفائز القوي بالنمو."},{"h":"التوقف اليومي والحرارة المفتوحة","t":"القاعدة المستخدمة: إذا انخفض اليوم بنسبة 2% تقريبًا من الحساب، توقف عن فتح الصفقات. ثلاث أفكار مفتوحة بنسبة 1% لكل منها حوالي 3% حرارة. خمس عملات مترابطة هي رهان واحد، وليس خمسة. عدهم معا."},{"h":"ما ترفضه هذه الطريقة","t":"لا يتم استخدام مارتينجال (المضاعفة بعد الخسارة). لا يتم استخدام نقل نقطة التوقف لمسافة أبعد \"لإفساح المجال\" بعد الدخول. لا يتم استخدام الكل في إشارة \"مؤكدة\". إذا لم يكن هناك توقف صالح، فلن يكون هناك حجم، وبالتالي لن يكون هناك تداول."},{"h":"المخاطر لكل التجارة","t":"القاعدة الشائعة: المخاطرة بنسبة تتراوح بين 0.5 إلى 1% فقط من حقوق ملكية الحساب عند فكرة واحدة. في العرض التجريبي، مارس نفس النسبة المئوية للعادة التي تمارسها في البث المباشر."},{"h":"صيغة حجم الموقف","t":"الحجم ≈ (الحساب × المخاطرة%) ÷ (مسافة الدخول − التوقف). أوسع SL → حجم أصغر. لا تختار أبدًا الحجم أولاً وSL ثانيًا."},{"h":"المخاطرة: المكافأة","t":"تفضيل الأفكار التي تكون فيها المكافأة المحتملة ≥ المخاطرة (على سبيل المثال 1: 1.5 أو أفضل) عند التعلم. قم بالتوسيع إلى TP1 بحيث يكون العدائون \"خاليين من المخاطر\"."},{"h":"أخذ الربح الجزئي","t":"نمط CPE: TP1 يقفل بعض الأرباح، TP2 / المسار للباقي. الجزئيات المصرفية تقلل من الذعر العاطفي."},{"h":"زائدة TP + SL","t":"شراء: مستويات المسار ترتفع مع ارتفاع الأسعار. بيع: درب إلى أسفل. الأقفال الزائدة تفتح الربح دون الحاجة إلى مكالمة خروج مثالية."},{"h":"حد الخسارة اليومي / الأسبوعي","t":"مثال للقاعدة: إيقاف التداول لليوم التالي لحساب -2%. جلسات الانتقام بعد حد الخسارة هي قتلة للحساب."},{"h":"تحجيم البقعة","t":"إن القيمة الاسمية للدقيقة الفورية مهمة (على سبيل المثال، دقائق الصرف). استمر في تطبيق نسبة المخاطرة: إذا كان الحد الأدنى للحجم ينطوي على مخاطر كبيرة جدًا مقابل وقف الخسارة الخاص بك، فقم بتخطي الصفقة."},{"h":"العقود الآجلة / الرافعة المالية","t":"الرافعة المالية تضاعف الربح والخسارة. الرافعة المالية العالية + SL الواسع = الحساب المنفوخ. تفضل الرافعة المالية المنخفضة أثناء التعلم؛ معزولة يمكن أن تحد من الخسارة لكل موقف."},{"h":"الارتباط","t":"فتح 5 عملات BTC بديلة مرتبطة = رهان كبير واحد، وليس خمسة. عد المخاطر كمجموعة."},{"h":"الرسوم والانزلاق","t":"تبدو فروة الرأس الضيقة جيدة على الرسم البياني ولكن الرسوم تأكل R:R. تفضل التقلبات الأنظف على العرض التجريبي حتى تعرف التكاليف."},{"h":"العرض التوضيحي → الجسر المباشر","t":"الممارسة التجريبية لـ CPE (عقلية 3 أشهر تقريبًا): نفس قواعد المجلة، نفس النسبة المئوية. عند البث المباشر، ابدأ بنصف الحجم التجريبي للأسابيع الأولى."},{"h":"سلامة الأموال API","t":"عمليات السحب مغلقة على كل مفتاح. يمكنك العيش فقط بعد اختبار موافقتك على الحساب على النظام الأساسي المطابق. سر النظام الأساسي الخاطئ = عمليات فاشلة أو خطيرة."},{"h":"أخطاء","t":"مارتينجال (مزدوج بعد الخسارة)؛ تحريك SL أبعد؛ الكل في الإعدادات \"المؤكدة\" ؛ تجاهل الحد الأدنى للحجم مقابل المخاطر٪؛ التداول دون توقف يومي."},{"h":"قائمة مراجعة الممارسة","t":"① نسبة المخاطر المكتوبة ② الحجم من مسافة SL ③ TP1/TP2/المسار المخطط ④ الحد الأقصى للخسارة اليومية المعروفة ⑤ الورقة أولاً ⑥ دفتر اليومية PnL بأمانة."}]},{"id":"psych","title":"5 · علم نفس التداول","summary":"تقرر شركة Mindset ما إذا كانت مهارات BB/RSI/Fib ستنجو من الشاشات الحقيقية. FOMO، والانتقام، والثقة المفرطة، والخوف - قم بتدريبهم على المؤشرات الشبيهة بالعرض التجريبي.","lessons":[{"h":"لماذا يهم علم النفس","t":"تفشل خطة BB+RSI المثالية إذا دخلت مبكرًا، أو تخطيت وقف الخسارة، أو التجارة الانتقامية. المهارة = النظام × الانضباط."},{"h":"عملية أكثر من التنبؤ","t":"لا تحتاج إلى التنبؤ بالمستقبل. تحتاج إلى تنفيذ القواعد: الإعداد → المخاطر → الإدارة → المجلة. تختلف النتائج. يمكن السيطرة على العملية."},{"h":"فومو","t":"الخوف من الضياع = مطاردة الشموع الخضراء بعيدًا عن منطقة BB/Fib. القاعدة: إذا فاتك الإدخال، انتظر الإعداد التالي. لدى Chart Lab دائمًا شمعة أخرى."},{"h":"التجارة الانتقامية","t":"بعد الخسارة، الرغبة في \"استعادتها الآن\" تدمر الحسابات. التهدئة الإلزامية: ابتعد، وسجل الخسارة، وقم بالتداول التالي فقط إذا كانت القائمة المرجعية نظيفة."},{"h":"الثقة المفرطة بعد الانتصارات","t":"3 انتصارات متتالية ≠ زيادة الحجم 5×. حافظ على نسبة المخاطر ثابتة. تحدث فترات الفوز عندما يكسر معظم الناس قواعد المال."},{"h":"الخوف بعد الخسارة","t":"يعد تخطي كل إعداد صالح بعد يوم أحمر بمثابة تحيز أيضًا. ثق بالخطة المكتوبة؛ قلل الحجم مؤقتًا إذا لزم الأمر، ولا تتخلى عن العملية."},{"h":"شلل التحليل","t":"10 مؤشرات لا توافق ← تجميد. التزم بأساسيات CPE: الشموع + BB + RSI (+ منطقة فيبوناتشي). الجودة أكثر من كمية الأدوات."},{"h":"الميل والأخبار","t":"شموع حمراء كبيرة على الأخبار ترتفع الأدرينالين. أفضّل البقاء ثابتًا أثناء المجهول الكبير حتى إصلاحات الهيكل - الأنا تريد العمل؛ الخطة تريد الصبر."},{"h":"مجلة = العلاج + البيانات","t":"اكتب علامات المشاعر (FOMO، الاندفاع، الهدوء) في مجلة CPE Journal. تكشف أنماط المشاعر عن التسريبات بشكل أسرع من الربح والخسارة وحده."},{"h":"قواعد مكتوبة","t":"إذا لم تكن مكتوبة، فهي ليست قاعدة. مثال: \"فقط BB+candle+RSI؛ المخاطرة 1%؛ لا يوجد تداول بعد يوم -2%؛ العرض التجريبي حتى قائمة المراجعة 20 ورقة.\""},{"h":"البيئة","t":"النوم والجوع وتشتت انتباه الهاتف يغير القرارات. لا تحجم عندما تستنفد. التداول رياضي – حماية الدماغ."},{"h":"الضوضاء الاجتماعية","t":"\"إشارات\" Telegram والضجيج يكسران خطتك. فئة التعلم CPE + مجلتك > نصائح عشوائية. تصفية الأخبار والحيل كسياق، وليس أوامر."},{"h":"تحول الهوية","t":"فكر في \"أنا أتبع قائمة المراجعة الخاصة بي\" وليس \"يجب أن أكون على حق\". إن الخطأ في المخاطرة الصغيرة أمر طبيعي؛ أن تكون عنيدًا مع وجود مخاطر كبيرة أمر اختياري."},{"h":"العرض التوضيحي كصالة ألعاب رياضية","t":"استخدم العرض التوضيحي/الورقة للتدرب على المشاعر بأمان. إذا لم تتمكن من اتباع القواعد في العرض التوضيحي، فلن يقوم البث المباشر بإصلاح الانضباط بطريقة سحرية."},{"h":"قائمة مراجعة الممارسة","t":"① هل أنا هادئ؟ ② القائمة المرجعية كاملة؟ ③٪ المخاطر دون تغيير؟ ④ لا الانتقام؟ ⑤ هل سأقوم بمجلة بأمانة؟ إن وجدت لا → لا تجارة."}]},{"id":"signals","title":"6 · إشارات CPE - المعنى وماذا تفعل","summary":"تظهر مكاتب التداول الفوري / العقود الآجلة / الفوركس شراء · بيع · عقد + النتيجة. نفس فكرة المحرك على كل منصة - لكنك تتداول فقط على المنصة التي قمت بحفظ مفتاح API الخاص بها. إليك ما تعنيه كل إشارة والخطوات الدقيقة بعد ظهورها.","lessons":[{"h":"من أين تأتي الإشارات","t":"يسجل مؤشر CPE نقاط BB وRSI وFibonacci وعصا الشمعة وتقاطع EMA وSMA50 وMACD والزخم. النتيجة ≥ +3 → شراء. النتيجة ≥ −3 → بيع. بين → عقد. هذا تصنيف مساعد — وليس وعدًا بالربح."},{"h":"إشارة الشراء - المعنى","t":"التقاء صعودي أقوى في الوقت الحالي (أمثلة: ارتداد BB السفلي، وتحول ذروة البيع لمؤشر القوة النسبية RSI، والشمعة الصعودية، والتقاطع الذهبي، ودعم فيبوناتشي). تظهر TP1 / TP2 / SL المقترحة في الصف / Chart Lab / Trade Now."},{"h":"إشارة البيع - المعنى","t":"التقاء هبوطي أقوى (نطاق BB العلوي / مؤشر القوة النسبية في منطقة ذروة الشراء / الشمعة الهبوطية / تقاطع الموت / مقاومة فيبوناتشي). في السعر الفوري، يعني البيع عادةً الخروج/التخفيض من مراكز الشراء أو البيع فقط إذا كان السوق الخاص بك يسمح بصفقات البيع (العقود الآجلة/الفوركس)."},{"h":"عقد الإشارة - المعنى","t":"درجة مختلطة أو ضعيفة. لا تجبر التجارة. شقة صحيحة. قائمة المراقبة ★ وانتظر الشراء/البيع الأكثر وضوحًا أو مرشح BB الأدنى."},{"h":"رقم النتيجة","t":"أعلى |درجة| = مزيد من الاتفاق بين الأدوات. الشراء +5 أقوى من الشراء +3 - لا يزال يتم التأكيد على شموع Chart Lab قبل الحجم."},{"h":"BB المجلس السفلي","t":"قائمة منفصلة للأزواج التي تحمل علامات النطاق السفلي لبولينجر - تدرب على المرشحين الطويلين. لا تزال هناك حاجة إلى تأكيد الشمعة + مؤشر القوة النسبية؛ فليست كل لمسة سفلية مدخلاً."},{"h":"المنصة مقابل الإشارة (مهم)","t":"رياضيات الإشارة هي نفس الفكرة على Binance وBybit وOKX وKuCoin وBitget وGate وMEXC وKraken وCoinbase وOANDA وFXCM وMT5 وForex Demo. ما هي التغييرات التي يتم إجراؤها على مكان إرسال الطلب: فقط النظام الأساسي المحدد في API Keys / Trade Now. لا يتم فتح Binance BUY على Bybit."},{"h":"منصات كريبتو سبوت","t":"Binance Spot وCoinbase وما إلى ذلك: BUY = شراء العملة بسعر معقول (مثل USDT). بيع = بيع الممتلكات / جني الأرباح. الحد الأدنى للحجم (على سبيل المثال ~ 11 دولارًا) مهم. لا نفوذ."},{"h":"منصات العقود الآجلة للعملات المشفرة","t":"العقود الآجلة لـ Binance، وBybit، وOKX، وBitget...: BUY = long؛ بيع = قصير. اختر الرافعة المالية المتقاطعة/ المعزولة + بعناية. المسار: شراء المسارات TP+SL للأعلى؛ بيع مسارات إلى أسفل."},{"h":"منصات الفوركس","t":"OANDA / FXCM / MT5 / Forex Demo: نفس ملصقات الشراء/البيع/الحجز على أزواج العملات الأجنبية (EURUSD...). شراء = شراء العملة الأساسية؛ بيع = قاعدة بيع. الكثير (على سبيل المثال 0.01) بدلاً من كمية العملة. الجلسات والأخبار مهمة أكثر."},{"h":"عندما يظهر أمر الشراء - افعل هذا","t":"① افتح الصف → اقرأ لماذا / الشمعة / مؤشر القوة النسبية. ② تأكيد معمل الرسم البياني (15 دقيقة - ساعة واحدة). ③ العرض التوضيحي أولاً: التداول الآن → تعيين TP1/TP2/SL/trail → بدء العرض التوضيحي/الورق. ④ فقط بعد اختبار واجهة برمجة التطبيقات (API) على تلك المنصة → بث مباشر صغير. ⑤ نتيجة المجلة."},{"h":"عندما يظهر أمر بيع – افعل هذا","t":"① إذا كنت في مركز شراء: ضع في اعتبارك TP / الإغلاق الجزئي / المسار - لا تتجاهل. ② إذا كانت العقود الآجلة/الفوركس والخطة تسمح بالبيع القصير: قم بتأكيد Chart Lab ثم البيع الورقي/المباشر مع وقف الخسارة. ③ إذا كان HOLD أفضل بالأمس، فلا تنتقم من حجم الوجه."},{"h":"عندما يظهر HOLD - افعل هذا","t":"لا يوجد إدخال يدوي جديد. استمر في المسح. إضافة ★ قائمة المراقبة. دراسة الفصل الدراسي / معمل الرسم البياني. قم بحماية المراكز المفتوحة باستخدام المسار فقط إذا كانت في تداول بالفعل."},{"h":"تجارة السيارات + إشارة","t":"يمكن فتح الشراء التلقائي عندما تتطابق قواعد النتيجة القوية BB Lower + مع التكوين التلقائي المحفوظ. لا يزال الاختبار التجريبي التلقائي أولاً. LIVE Auto = خطر حقيقي — إيقاف عمليات السحب، حجم صغير."},{"h":"الإخطارات","t":"شراء نخب الإشارة تتبع لغتك. تعامل معها على أنها تنبيهات لفتح المكتب، وليس كأوامر سوق بحد ذاتها."},{"h":"ما لا يجب فعله","t":"لا تشتري كل عملية شراء بدون رسم بياني. لا تستخدم مفتاح Binance على Bybit. لا تخطي SL. لا ترفع الحجم بعد إشارة خضراء واحدة. لا تتداول عقد \"HOLD\" على أنه \"على وشك الشراء\"."},{"h":"بطاقة العمل السريع","t":"الإشارة ← معمل الرسم البياني ← نسبة المخاطرة ← TP1/TP2/SL ← ورقة تجريبية ← المجلة ← (لاحقًا) مباشرة على مفتاح النظام الأساسي المطابق."}]},{"id":"forex_sig","title":"7 · إشارات الفوركس – المعنى وماذا تفعل","summary":"يستخدم Forex Desk نفس تصنيف الشراء/البيع/الاحتفاظ على أزواج العملات الأجنبية. تعرف على كيفية اختلاف إشارات الفوركس عن العملات المشفرة، والخطوات الدقيقة من الإشارة → الورق → الوسيط المباشر.","lessons":[{"h":"إشارات مكتب الفوركس","t":"اليورو مقابل الدولار الأميركي، الجنيه الاسترليني مقابل الدولار الأميركي، الدولار الأميركي مقابل الين الياباني... احصل على شراء / بيع / تعليق + نقاط مثل العملات المشفرة. انقر فوق صف للحصول على مخطط ونص علم النفس والمستويات المقترحة."},{"h":"الشراء في الفوركس — المعنى","t":"قم بشراء العملة الأساسية (على سبيل المثال، شراء EURUSD = شراء EUR مقابل USD). توقع ارتفاع السعر. استخدم الفاصل الزمني لـ Chart Lab Forex الذي تمارسه (15 دقيقة/30 دقيقة/ساعة واحدة)."},{"h":"البيع على الفوركس - المعنى","t":"بيع القاعدة (اختصار الزوج). توقع انخفاض السعر. قم دائمًا بتعيين SL فوق فكرة الهيكل/النطاق العلوي."},{"h":"عقد على الفوركس","t":"لا توجد حافة واضحة – تخطي. وخاصة قبل الأخبار الكبيرة (NFP، CPI، البنك المركزي) يفضلون الاحتفاظ بالسعر الثابت/الثابت."},{"h":"منصة أسعار الفوركس التجريبية","t":"لا يوجد مفتاح API. مخططات التدريب + الورق فقط. مثالية للتدريبات التعليمية قبل بث OANDA/FXCM/MT5."},{"h":"إشارة OANDA → الإجراء","t":"① مكتب الفوركس شراء/بيع. ② تأكيد معمل الرسم البياني. ③ مفاتيح واجهة برمجة التطبيقات ← رمز OANDA المميز + معرف الحساب ← اختبار. ④ ورقة العرض التوضيحي في CPE أولاً. ⑤ عقود حية صغيرة (عقلية 0.01) مع TP/SL/trail."},{"h":"اف اكس سي ام / MT5","t":"نفس قراءة الإشارة قم بتوصيل بيانات اعتماد هذا الوسيط ضمن مفاتيح API. لا يقوم تطبيق Signal بتسجيل الدخول تلقائيًا إلى MT5 حتى يتم تعيين المفاتيح/الجسر - تدرب على الورق حتى يتم اختبار موافق."},{"h":"الجلسات","t":"غالبًا ما يؤدي التداخل بين لندن ونيويورك إلى تحريك التخصصات بشكل أكبر. قد تكون آسيا أكثر هدوءًا — يعتبر HOLD أمرًا شائعًا وصحيًا."},{"h":"انتشار وأخبار","t":"حول الأخبار، تتسع فروق الأسعار - لا يزال الشراء الفني الجيد بمثابة ملء سيئ. تحقق من الأخبار والحيل. انتظر حتى تغلق الشمعة بعد الارتفاع."},{"h":"الكثير مقابل الكمية المشفرة","t":"حجم الفوركس = الكثير، وليس USDT الافتراضي بنفس الطريقة. نسبة المخاطر لا تزال هي السائدة: وقف الخسارة الأوسع ← عقود أصغر."},{"h":"BB أقل في الفوركس","t":"نفس الفكرة: الزوج بالقرب من النطاق السفلي + المطرقة + ارتفاع مؤشر القوة النسبية = ممارسة دراسة طويلة. تأكيد ارتفاع تحيز TF (4H/يوميًا)."},{"h":"عندما ينطلق شراء الفوركس — خطوات","t":"① اقرأ لماذا. ② انحياز TF العالي، حسنًا؟ ③ ضع علامة SL خارج الفتيل/الهيكل. ④ تجارة الورق. ⑤ إذا كان الوسيط المباشر جاهزًا → حجم صغير + أثر. ⑥ جلسة المجلة (لندن/نيويورك) + العاطفة."},{"h":"عندما ينطلق بيع الفوركس — خطوات","t":"① تأكيد عدم ارتفاع منتصف الأخبار. ② الشمعة الهبوطية لمختبر الرسم البياني. ③ ورقة قصيرة أو قريبة طويلة. ④ اتبع المسار للأسفل إذا كان قصيرًا. ⑤ لا تضاعف الكمية بعد الخسارة."},{"h":"الفرق بين الفوركس والتشفير","t":"التشفير 24/7؛ الفوركس لديه جلسات. الحد الأدنى للتشفير $ غالبًا؛ عقود الفوركس + قيمة النقطة. العديد من العملات المشفرة مرتبطة ببعضها البعض؛ شركات الفوركس منظفة للتعلم."},{"h":"قائمة مراجعة الممارسة (FX)","t":"① زوج رئيسي؟ ② الجلسة موافق؟ ③ أخبار واضحة؟ ④ عدم تعليق إشارة الشراء/البيع؟ ⑤ تأكيد الرسم البياني؟ ⑥ نسبة المخاطرة؟ ⑦ الورق → المجلة → مفتاح الوسيط المباشر فقط عندما يكون جاهزًا."}]},{"id":"fomo","title":"8 · FOMO والانضباط العاطفي","summary":"الخوف من الخوف والانتقام والجشع والخوف هم القتلة الحقيقيون للحسابات - وليس المؤشرات. تعرف على المحفزات، وعلامات الجسم، والقواعد الدقيقة التي تمنع التداولات الاندفاعية من حسابك.","lessons":[{"h":"ما هو FOMO حقا","t":"FOMO = الخوف من فقدان حركة بعيدة بالفعل عن منطقتك. يجعلك تدخل متأخرًا بسعر أسوأ ولا يوجد ترخيص اشتراك مناسب. الشمعة التي \"فاتتك\" هي معلومة وليست خسارة."},{"h":"مشغلات FOMO الثلاثة","t":"① شمعة خضراء أو حمراء كبيرة على الرسم البياني. ② منشور صديق أو Telegram يظهر الربح. ③ عنوان إخباري. لاحظ المشغل قبل أن تلاحظ الإدخال."},{"h":"علامات الجسم","t":"نبضات قلب سريعة، وانحناء نحو الشاشة، ورغبة ملحة في النقر على \"شراء السوق الآن\"، وتخطي قائمة المراجعة الخاصة بك. إذا شعرت بذلك، أغلق علامة التبويب وانتظر شمعة واحدة."},{"h":"قاعدة \"تم تشغيلها بالفعل\".","t":"إذا تحرك السعر بأكثر من 1 ATR تقريبًا بعد الدخول المخطط له، فستنتهي الصفقة. انتظر التراجع إلى BB mid / Fib أو قم بتخطيه. هناك دائما إعداد آخر."},{"h":"مصيدة الشمعة الخضراء","t":"Marubozu الذي لم تخطط له هو مطاردة وليس دخولًا. الإدخالات المتأخرة لها أسوأ مكافأة: المخاطرة لأن أمر التوقف ينتهي بعيدًا."},{"h":"التجارة الانتقامية","t":"بعد الخسارة، يريد الدماغ استعادتها الآن. القاعدة: لا يوجد إدخال جديد لمدة 15-30 دقيقة بعد الخسارة، وفقط إذا كانت القائمة المرجعية نظيفة. السوق لا يدين لك بشيء."},{"h":"الخوف من الضغط على الزناد","t":"المشكلة المعاكسة: يظهر الإعداد المثالي وتتجمد. استخدم حجمًا تجريبيًا صغيرًا لإثبات العملية، وحدد حجمك قبل ظهور الشمعة، وبذلك يكون القرار قد تم اتخاذه بالفعل."},{"h":"الجشع بعد الانتصارات","t":"صفقتان أخضرتان تجعلك تشعر أنك لا تقهر، ثم تضاعف حجمك. حافظ على نسبة المخاطرة ثابتة لمدة 20 صفقة على الأقل؛ شرائط الفوز تعني العودة."},{"h":"تجارة الملل","t":"شقة هي الموقف. في حالة عدم وجود إعداد A+، لا تقم بإجراء شيء ما. صفقات الملل هي FOMO مقنعة."},{"h":"الانضباط في وقت الشاشة","t":"قم بتعيين نوافذ مسح ضوئي مرتين أو ثلاث يوميًا بدلاً من التحديق في الرسوم البيانية. قرارات أقل تعني قرارات أقل اندفاعًا."},{"h":"مجلة عاطفية","t":"ضع علامة على كل صفقة هادئة / متسرعة / FOMO / انتقام. بعد 20 عملية تداول، يصبح نمط التسريبات لديك واضحًا."},{"h":"إعادة ضبط الطقوس","t":"بعد خسارة أو زلة FOMO: قف، خذ 10 أنفاس بطيئة، اكتب جملة واحدة حول ما حدث، ثم توقف لمدة ساعة أو واصل العمل بنصف الخطر الطبيعي."},{"h":"قائمة مراجعة الممارسة","t":"① جسم هادئ؟ ② هل لاحظت الزناد؟ ③ الإعداد في منطقتي؟ ④ SL مكتوبة أولا؟ ⑤ نسبة المخاطرة دون تغيير؟ ⑥ لا الانتقام؟ أي لا → لا تجارة."}]},{"id":"risk_deep","title":"9 · إدارة المخاطر والأموال – عميق","summary":"الرياضيات التي تحافظ على حيوية الحساب: التحجيم الكسري الثابت، ومضاعفات R، ورياضيات السحب، وحرارة الارتباط، والتوقف اليومي. تحويل التداول إلى عمل تجاري تديره الأرقام.","lessons":[{"h":"المخاطر الجزئية الثابتة","t":"المخاطرة بنسبة ثابتة (0.5-1%) من رأس المال لكل فكرة. الحجم هو نتيجة مسافة التوقف، ولم يتم اختياره أولاً. واسعة SL → حجم صغير؛ ضيق SL → حجم أكبر؛ وتبقى مخاطر الدولار على حالها."},{"h":"صيغة التحجيم","t":"الحجم = (رأس المال × المخاطرة%) ÷ |الدخول − الإيقاف|. مثال: 1000 دولار × 1% = مخاطرة 10 دولارات. الإدخال 100، التوقف 98 ← المسافة 2% ← الحجم 10 ÷ 0.02 = 500 دولار افتراضي."},{"h":"فكر في مضاعفات R","t":"خطر 1R لكل التجارة. الفائز 2R يدفع ثمن خسارتين. تتبع متوسط ​​R الخاص بك خلال 20 صفقة - هذه هي الميزة الحقيقية لديك، وليس معدل الفوز."},{"h":"المكافأة: المخاطرة","t":"تهدف إلى ما لا يقل عن 1.5R من الإمكانات قبل الدخول. أدناه، قم بتخطيها إلا إذا كان معدل فوزك مرتفعًا جدًا."},{"h":"الرياضيات السحب","t":"يحتاج السحب بنسبة -50% إلى +100% للتعافي. تعتبر فترات الخسارة أمرًا طبيعيًا: فحتى نظام معدل الفوز بنسبة 60٪ لديه أكثر من 5 خسائر. المخاطرة الصغيرة تحافظ على استمرارية الخط."},{"h":"التوقف اليومي","t":"القاعدة الصعبة: توقف عن فتح الصفقات بعد -2% من رأس المال في يوم واحد (أو 2-3 خسائر متتالية). جلسات الانتقام بعد الحد هي قتلة للحساب."},{"h":"الحدود الأسبوعية والشهرية","t":"ضع أيضًا حدًا أقصى للأسبوع (على سبيل المثال −5%) والشهر. عند النقر، انتقل إلى العرض التوضيحي، وراجع المجلة، ثم قم بتعديل الحجم مرة أخرى فقط بعد التشغيل النظيف."},{"h":"حرارة مفتوحة","t":"يجب أن يظل إجمالي المخاطر في جميع الصفقات المفتوحة حوالي 3٪ أو أقل. خمسة بدائل مترابطة هي رهان واحد، وليس خمسة - احسب التعرض المرتبط معًا."},{"h":"تحجيم البقعة","t":"بقعة لديها الحد الأدنى النظري. إذا كان الحد الأدنى للصرف سيخاطر بأكثر من 1%، فتخطى التداول - ولا تقم أبدًا بتقريب المخاطر إلى أعلى."},{"h":"تحجيم العقود الآجلة","t":"الرافعة المالية تغير الهامش، وليس المخاطر. لا تزال المخاطرة عند الدخول - الإيقاف × الحجم. استخدم رافعة مالية منخفضة أثناء التعلم وفضل الهامش المعزول."},{"h":"تحجيم الفوركس","t":"المخاطرة = اللوت × قيمة النقطة × نقاط التوقف. حل للكثير. دليل تقريبي: 0.01 لوت ≈ 0.10 دولار لكل نقطة؛ توقف بمقدار 20 نقطة يخاطر بـ 1% من 1000 دولار (10 دولارات) → 10 ÷ 0.10 ÷ 20 = 0.05 لوت."},{"h":"التوسع","t":"احصل على خصم 50% تقريبًا على TP1 لتجعل الباقي خاليًا من المخاطر، ثم تابع. وهذا يحول التجارة الجيدة إلى عداء منخفض الضغط."},{"h":"يضاعف مقابل ثابت","t":"المخاطرة بنسبة ثابتة من رأس المال الحالي (مضاعف). لا تقم بإصلاح المخاطر الخاصة بك عند حجم الحساب الأعلى على الإطلاق."},{"h":"الرسوم والانزلاق في R","t":"اطرح الرسوم من R. رسم بنسبة 0.2% مقابل 0.5% لفروة الرأس يمكن أن يمحو الحافة - تفضل التقلبات الأنظف."},{"h":"قانون \"لا توقف لا تجارة\".","t":"إذا لم تتمكن من تحديد نقطة توقف منطقية، فأنت لا تعرف المخاطر الخاصة بك، لذلك لا يوجد حجم، وبالتالي لا يوجد تداول."},{"h":"مكافحة مارتينجال","t":"لا تضاعف أبدًا بعد الخسارة. قم بزيادة الحجم فقط بعد عدة أسابيع مربحة ومنضبطة من عملية مجربة - وحتى ذلك الحين ببطء."},{"h":"قائمة مراجعة الممارسة","t":"① الأسهم المعروفة ② نسبة المخاطر المكتوبة ③ الإيقاف المحدد ④ الحجم من الإيقاف ⑤ المكافأة ≥ 1.5R ⑥ التوقف اليومي المعروف ⑦ حساب الحرارة المرتبطة."}]},{"id":"sl_tp","title":"10 · إتقان إيقاف الخسارة وجني الأرباح","summary":"ضع وقف الخسارة حيث يثبت السوق أنك مخطئ، وجني الأرباح على خطوات، وتتبع أمر التوقف حتى يتمكن الفائز من الجري - وهو بالضبط ما يفعله CPE مع جني الربح المتعدد ووقف الخسارة المتحرك.","lessons":[{"h":"SL هو قرار وليس رقمًا","t":"ضع نقطة التوقف حيث يتم إبطال الفكرة (تحت قاع التأرجح، أو الفتيل، أو الهيكل)، وليس على مسافة دولارية عشوائية. أنت تشتري معلومات: إذا وصل السعر إلى هنا، فإن سببي خاطئ."},{"h":"يتوقف الهيكل","t":"طويل: SL أسفل فتيل التأرجح المنخفض أو النطاق السفلي مباشرةً. قصير: فوق قمة التأرجح مباشرة. أعطِ حاجزًا صغيرًا للانتشار وفتيل الضوضاء، حوالي 0.1-0.3%."},{"h":"توقف التقلب","t":"الأسواق الأوسع تحتاج إلى نقاط توقف أوسع. استخدم ATR أو طول الفتيل لتحديد حجم نقطة الإيقاف، ثم قم بتقليص المركز بحيث تظل مخاطرة الدولار كما هي."},{"h":"لماذا يفشل SL بالدولار الثابت","t":"يعتبر التوقف بقيمة 10 دولارات على BTC والتوقف بقيمة 10 دولارات على اليورو مقابل الدولار الأميركي بمثابة مخاطرة مختلفة تمامًا. المسافة يجب أن تقاس بالنسبة المئوية، وليس بالدولار."},{"h":"مكافحة وقف الصيد العازلة","t":"يتجاهل CPE لمسة فتيل واحدة: فهو يحتاج إلى اختراقين متتاليين بالإضافة إلى حاجز صغير (0.15%) قبل الإغلاق. وهذا يمنع الضوضاء من مطاردة محطتك."},{"h":"جني الربح في خطوات","t":"لا تغلق أبدًا 100٪ بسعر واحد. التوسع: جزء من كتب TP1، ثم TP2 / Trail يركب الباقي، لذا فإن خطوة كبيرة يمكن أن تدفع للعديد من الخاسرين."},{"h":"مستويات متعددة TP","t":"يتيح لك CPE إضافة أي عدد تريده من مستويات TP، كل منها له نسبة إغلاق خاصة به. على سبيل المثال: TP1 40%، TP2 30%، TP3 30% — أو خذ TP1 وتتبع الباقي."},{"h":"زائدة التوقف","t":"بعد TP1، قم بتحريك نقطة الوقف إلى نقطة التعادل؛ بعد TP2 انقله إلى TP1. دع وقف الخسارة يتبع السعر حتى يتم حماية الربح المفتوح بينما يستمر العداء."},{"h":"اختيار المسار٪","t":"المسار الضيق يحقق الربح بسرعة ولكنه يخرج مبكرًا؛ درب واسع يتنفس لكنه يعطي بعض الظهر. ابدأ بنحو 1-2% للعملات المشفرة وقم بضبطها في نموذج تحرير المراكز."},{"h":"العدائين","t":"عندما يسير السعر في النطاق في اتجاه قوي، قم بتوسيع الهدف والمسار بدلاً من أخذ كل شيء عند TP2. هذه هي الطريقة التي تدفع بها التجارة الواحدة لمدة أسبوع كامل."},{"h":"أزرار الإغلاق الجزئي","t":"استخدم أزرار الإغلاق بنسبة 50% / 100% في المواضع للتحكم اليدوي، أو اسمح للإغلاق التلقائي بإدارة TP / SL وفقًا للخطة."},{"h":"فخ التعادل","t":"لا تقم بتحريك حد إيقاف الخسارة إلى نقطة التعادل في وقت مبكر جدًا، قبل TP1 - فعمليات التراجع العادية ستخرجك من التداولات الجيدة."},{"h":"لا تقم أبدًا بتوسيع نقطة التوقف الخاسرة","t":"إن نقل SL بعيدًا لإفساح المجال له هو كيف تصبح الخسائر الصغيرة قاتلة للحسابات. نقطة التوقف التي قمت بتعيينها قبل الدخول هي نقطة التوقف."},{"h":"توقف الوقت","t":"إذا لم تفعل التجارة شيئًا للعديد من الشموع بينما يتشكل إعداد أفضل بشكل واضح، فإن الإغلاق بشكل مسطح وإعادة توزيع المخاطر يعد خروجًا صالحًا."},{"h":"قائمة مراجعة الممارسة","t":"① SL عند الإبطال، وليس عشوائيًا ② مخزن مؤقت للفتائل ③ TP1 مخطط جزئيًا ④ المسار بعد TP1 ⑤ لا تقم أبدًا بتوسيع SL ⑥ دع الفائز يركض."}]},{"id":"plan_journal","title":"11 · خطة التجارة واليوميات","summary":"خطة مكتوبة تحول التداول من المقامرة إلى عملية. تعرف على خطة الصفحة الواحدة، وقائمة مراجعة ما قبل التجارة، وكيفية تدوين يومياتك حتى تصبح التسريبات مرئية.","lessons":[{"h":"لماذا كتابة الخطة","t":"إذا لم يكتب فهو ليس قاعدة. تعمل الخطة على إزالة عملية اتخاذ القرار المباشرة تحت الضغط وتجعل نتائجك قابلة للقياس."},{"h":"خطة الصفحة الواحدة","t":"الزوج، السوق، الإعداد (BB + RSI + الشمعة + منطقة فيبوناتشي)، الاتجاه، الدخول، SL، TP1 / TP2، الحجم (من SL) والحد الأقصى للخسارة اليومية. إذا كان أي سطر فارغًا → لا توجد تجارة."},{"h":"قائمة مراجعة ما قبل التجارة","t":"التحيز العالي TF؟ · الإعداد في منطقتي؟ · تأكيد الشمعة؟ · مؤشر القوة النسبية توافق؟ · سي مكتوب؟ · مخاطرة ٪؟ · المكافأة ≥ 1.5R؟ · هادئ؟ كل نعم → التجارة."},{"h":"روتين ما قبل الجلسة","t":"تحقق من الإطار الزمني الأعلى والمستويات الرئيسية والأخبار. اكتب زوجين أو ثلاثة أزواج من الساعات اليوم قبل الجلسة - وليس بعد انفجار الشمعة."},{"h":"ماذا مجلة","t":"الرمز، الجانب، الدخول، الخروج، الحجم، R، السبب، الإطار الزمني، الجلسة وعلامة العاطفة. تقوم مجلة CPE بحفظ الربح/الخسارة والأسباب تلقائيًا؛ إضافة الملاحظات الخاصة بك."},{"h":"مجلة لماذا","t":"سجل ما رأيته (الإعداد) وما شعرت به (الهدوء / FOMO / الاندفاع). النتيجة بدون سياق لا تعلم شيئا."},{"h":"المسار R، لا يفوز","t":"من الممكن أن يكون للمتداولين اللذين لهما نفس معدل الربح نتائج معاكسة. متوسط ​​R والحد الأقصى للسحب يهم أكثر من نسبة الفوز."},{"h":"عادة لقطة الشاشة","t":"احفظ الرسم البياني قبل وبعد كل صفقة. تُظهر مراجعة 20 لقطة شاشة تفوقك وتسريباتك بشكل أسرع من أي مؤشر."},{"h":"مراجعة أسبوعية","t":"مرة واحدة في الأسبوع، قم بحساب تداولاتك، ومتوسط R، وأفضل وأسوأ إعداد، وفواصل القواعد. اختر تسربًا واحدًا لإصلاحه الأسبوع المقبل."},{"h":"ضع علامة على التسريبات","t":"العلامات الشائعة: الدخول المتأخر، بدون SL، كبير الحجم، SL متحرك، الانتقام، الملل. عندما تتكرر العلامة، قم بتحويلها إلى قاعدة صارمة."},{"h":"ما لا لتسجيل","t":"لا تقم بتسجيل الفائزين فقط. الخسائر هي البيانات. مجلة الانتصارات فقط هي كتيب، وليست مجلة."},{"h":"قم بالتخطيط للخطوة التجريبية → المباشرة","t":"أثبت الخطة على العرض التجريبي لعدد محدد من الصفقات بمتوسط R إيجابي قبل المخاطرة بأموال حقيقية — ثم ابدأ بنصف الحجم."},{"h":"قائمة مراجعة الممارسة","t":"① الخطة مكتوبة قبل الإدخال ② تم اجتياز قائمة المراجعة ③ إدخال دفتر اليومية + العاطفة ④ المراجعة الأسبوعية ⑤ تم إصلاح تسرب واحد."}]},{"id":"leverage","title":"12 · الرافعة المالية والهامش والتصفية","summary":"الرافعة المالية تضاعف الخسارة بنفس سرعة الربح. تعرف على الهامش، والتصفية، والهامش المعزول مقابل الهامش المتقاطع، وقواعد السلامة التي تمنع إحدى الصفقات من مسح الحساب.","lessons":[{"h":"ما هي النفوذ","t":"تتيح لك الرافعة المالية التحكم في مركز أكبر بهامش أقل. إنه يزيد من الربح والخسارة – ولا يزيد من تفوقك."},{"h":"الهامش مقابل المخاطر","t":"الهامش هو إيداع أقفال الصرف. الخطر هو الدخول − الإيقاف × الحجم. الرافعة المالية تغير الهامش، ولا تتعرض لخطر الدولار أبدًا."},{"h":"التصفية","t":"إذا أكلت الخسائر الهامش الخاص بك، فإن قوة الصرف تغلق المركز (التصفية)، غالبًا في أسوأ الأوقات. أبقِ نقطة توقفك بعيدة عن سعر التصفية."},{"h":"معزولة مقابل الصليب","t":"معزولة تحد من الخسارة في هامش ذلك المركز الواحد. يستخدم Cross رصيد المحفظة بالكامل، وهو أمر أكثر خطورة بالنسبة للمبتدئين. يفضل العزلة أثناء التعلم."},{"h":"نفوذ أكثر أمانا","t":"تعتبر الرافعة المالية المنخفضة (2-5x) بالإضافة إلى التوقف المناسب أكثر أمانًا بكثير من 50x بدون توقف. إن أمر التوقف، وليس رقم الرافعة المالية، هو حمايتك."},{"h":"قاعدة مسافة التصفية","t":"تأكد من أن وقف الخسارة الخاص بك يتناسب بشكل جيد مع سعر التصفية. إذا كانت قريبة، قم بتقليل الحجم حتى تتوفر مساحة مريحة."},{"h":"الرافعة المالية لا تصلح الإدخال السيئ","t":"الرافعة المالية العالية عند الدخول السيئ تفقد بشكل أسرع. قم بإصلاح الإعداد أولاً، ثم قم بتغيير حجمه."},{"h":"التمويل والرسوم","t":"العقود الآجلة الدائمة تفرض رسومًا على التمويل بمرور الوقت. إن عمليات الاحتفاظ الطويلة بالأموال ذات الرافعة المالية تستنزف التمويل - وهو سبب آخر للحجم والوقت بعناية."},{"h":"بقعة مقابل العقود الآجلة","t":"لا يمكن تصفية البقعة (أنت تمتلك العملة المعدنية). يمكن للعقود الآجلة أن تصل إلى الصفر. استخدم العقود الآجلة فقط مع خطة مكتوبة وهامش معزول."},{"h":"التحجيم تحت الرافعة المالية","t":"قم بحساب الحجم من مسافة التوقف، ثم تأكد من أن الهامش الناتج في المتناول. لا تختار الرافعة المالية أولاً."},{"h":"اختبار \"التجارة الواحدة\".","t":"قبل الدخول اسأل: إذا وصل هذا إلى نقطة التوقف، فهل يعد ذلك استهزاءً أم كارثة؟ إذا لم يكن الأمر مستهجنًا، فهذا يعني أن الحجم كبير جدًا."},{"h":"قائمة مراجعة الممارسة","t":"① مجموعة معزولة ② رافعة مالية منخفضة ③ SL داخل سعر التصفية ④ الحجم من التوقف ⑤ هل يمكنني النجاة من الخسارة الكاملة هنا؟ نعم → التجارة."}]},{"id":"practice","title":"13 · ممارسة الروتين والاختبار الخلفي","summary":"يتم بناء المهارة على العرض التجريبي قبل البث المباشر. تعلم حلقة تدريب قابلة للتكرار، وكيفية \"الاختبار الخلفي\" من خلال تمرير الرسوم البيانية، وكيفية التدرج في الحصول على أموال حقيقية بأمان.","lessons":[{"h":"DEMO هي صالة الألعاب الرياضية","t":"الورق / العرض التوضيحي موجود للتدرب على العملية وعواطفك دون أي مخاطر. إذا لم تتمكن من اتباع القواعد الموجودة في العرض التوضيحي، فلن يقوم البث المباشر بإصلاحه بطريقة سحرية."},{"h":"حلقة الممارسة","t":"اختر إعدادًا واحدًا (على سبيل المثال BB Lower + Hammer + RSI). ضع علامة على 20 مثالًا تاريخيًا على الرسم البياني. تحديد الدخول / SL / TP. سجل النتيجة. يكرر."},{"h":"الاختبار الخلفي اليدوي","t":"قم بالتمرير للخلف في Chart Lab، وقم بإخفاء المستقبل، وقم بوضع علامة على كل إشارة يدويًا. إنه يدرب التعرف على الأنماط ويمنعك من خداع نفسك."},{"h":"حجم العينة","t":"عشر صفقات لا تعني شيئًا. اهدف إلى إجراء ما بين 30 إلى 50 صفقة مسجلة لإعداد واحد قبل الحكم عليها."},{"h":"اختبار إلى الأمام على DEMO","t":"بعد وضع العلامات اليدوية، قم بتشغيل نفس الإعداد مباشرة على العرض التوضيحي باستخدام إشارات البرنامج لمدة أسبوعين إلى أربعة أسابيع. قارن عمليات التعبئة والعواطف الحقيقية مع الاختبار الخلفي."},{"h":"إعداد واحد في كل مرة","t":"لا تختبر خمسة أنظمة في وقت واحد. أتقن حافة واحدة، ثم أضف حافة ثانية."},{"h":"حافظ على الروتين صغيرًا","t":"روتين يومي مدته 20 دقيقة (المسح الضوئي، ووضع العلامات، والمجلة، والمراجعة) يتفوق على ست ساعات من التحديق العشوائي في المخططات."},{"h":"التخرج للعيش","t":"المعايير: متوسط R إيجابي أكثر من 30+ من الصفقات التجريبية، القواعد المتبعة، لا توجد حلقات انتقامية. ثم ابدأ البث المباشر بنصف الحجم ثم قم بالقياس ببطء."},{"h":"قاعدة التوسع","t":"قم بزيادة الحجم فقط بعد عدد محدد من الأسابيع المربحة والمنضبطة - وليس بعد فوز كبير واحد."},{"h":"متى تتراجع","t":"حدد حد الخسارة اليومي أو الأسبوعي، أو لاحظ تكرار فواصل القواعد ← ارجع إلى العرض التوضيحي وأعد بناء الانضباط قبل المتابعة."},{"h":"تتبع مقاييس العملية","t":"سجل معدل النجاح في القائمة المرجعية، وكسر القواعد في الأسبوع، ومتوسط R. وتتنبأ هذه بالنمو بشكل أفضل من رقم الربح/الخسارة الفردي."},{"h":"مسار ممارسة CPE","t":"فصل تعليمي ← مختبر الرسم البياني (إعدادات العلامة) ← تجارة الورق ← مراجعة دفتر اليومية ← مكاتب الإشارة في العرض التوضيحي ← بث مباشر صغير على مفتاح النظام الأساسي المطابق."},{"h":"قائمة مراجعة الممارسة","t":"① تم اختيار إعداد واحد ② تم وضع علامة على 30 مثالًا ③ اختبار DEMO الأمامي ④ المجلة + المراجعة ⑤ Positive R → نصف الحجم LIVE."}]},{"id":"volatility","title":"14 · التقلبات ومارتينجال","summary":"كيفية قراءة تقلبات السوق (لماذا يتغير السعر)، وكيف يتم إضافتها إلى كل إشارة كخط سبب، وكيف يعمل سلم مارتينجال الاختياري - بالإضافة إلى سبب كونه أسرع طريقة لخسارة الحساب عند استخدامه بلا مبالاة.","lessons":[{"h":"ماذا يعني التقلب","t":"التقلب هو مقدار تحرك السعر - وليس الاتجاه. تقلبات عالية = شموع واسعة وتقلبات سريعة. تقلب منخفض = نطاق هادئ وضيق. نفس الإعداد له موثوقية مختلفة جدًا في كل منهما."},{"h":"قراءة تقلب CPE","t":"تقيس كل إشارة الآن متوسط نطاق الشمعة وعرض نطاق بولينجر، ثم تقارنهما بالمستوى الطبيعي الأخير لهذا الزوج. تحصل على LOW / NORMAL / HIGH / EXTREME بالإضافة إلى خط سبب واضح - \"لماذا\" تغير السوق، كما هو موضح مع الإشارة."},{"h":"التقلبات الشديدة = تخفيض التصنيف","t":"عندما يكون الشريط شديدًا، يتم تخفيض إشارة قوية جديدة إلى تنبيه (يظهر السبب). في السوق المتقلبة، يفشل نفس النمط في كثير من الأحيان - الفواصل الوهمية وفتائل الإيقاف هي القاعدة."},{"h":"ما يجب القيام به في عالية / المتطرفة","t":"حجم أصغر. توقف أوسع. صفقات أقل. انتظر حتى تكتمل الشمعة بدلًا من ارتفاع منتصف الشمعة. إذا كانت القراءة تقول EXTREME، فتعامل مع الإعداد كمنطقة دراسة، وليس كمدخل."},{"h":"ما هو مارتينجال","t":"يضيف مارتينجال إلى المركز الخاسر لخفض متوسط الدخول: بعد كل حركة عكسية، يمكنك إضافة أمر آخر، عادة ما يكون أكبر (1x، 2x، 4x …). يفوز كثيرًا، ثم يخسر كل شيء في جولة واحدة سيئة."},{"h":"قاعدة CPE مارتينجال","t":"يضيف CPE أمرًا إضافيًا فقط عندما يكون كلاهما صحيحًا: (1) تحرك السعر ضد التداول بمقدار خطوة × درجة٪ على الأقل، و(2) لا تزال إشارة جديدة من نفس الجانب قائمة لهذا الزوج. لا يضيف أبدًا لمجرد انخفاض السعر."},{"h":"الأرقام الأربعة","t":"الخطوة % = الحركة المعاكسة المطلوبة قبل كل إضافة. المضاعف = حجم كل إضافة مقابل القاعدة (1 = مسطح، 2 = مزدوج). ماكس يضيف = حد صارم على الطلبات الإضافية. سقف مخاطر السلم % = مخاطر السلم بالكامل كنسبة مئوية من حقوق الملكية. كل أربعة لك أن تختار."},{"h":"الغطاء الصلب يحميك","t":"حتى مع وجود مضاعف كبير والعديد من الإضافات، يرفض CPE الأمر بمجرد أن يتجاوز إجمالي مخاطر السلم الحد الأقصى لنسبة الأسهم الخاصة بك. كما أنها تحترم الحد الأدنى لحجم الصرف وتوقف التداول اليومي بنسبة −2%."},{"h":"حيث يتم تشغيله","t":"حدده على يدوي لإدارة تلك الصفقة الواحدة، أو على جلسة تلقائية لإدارة تداولاتها التلقائية. كلا التجريبي والعيش. في الوضع اليدوي، يجب أن يكون الزوج موجودًا في قائمة المسح حتى يمكن قراءة إشارة جديدة من نفس الجانب."},{"h":"لماذا يهم الحد الأقصى (مثال)","t":"الخطوة 1%، المضاعف 2، ثلاثة تضيف على قاعدة مخاطرة 1%: المخاطرة تتراوح من 1% → 2% → 4% → 8%. يؤدي التوقف الكامل في الدرجة الأخيرة إلى محو العديد من الفائزين. وهذا هو سبب وجود الحد الأقصى ولماذا تكون الأرقام الافتراضية صغيرة."},{"h":"بديل مضاد مارتينجال","t":"العديد من المحترفين يفعلون العكس: أضف فقط إلى الفائزين وتخلص من الخاسرين بسرعة. يبدو الأمر أسوأ (المزيد من الخسائر الصغيرة) لكنه لا يمكن أن يفجر الحساب في اتجاه واحد ضدك."},{"h":"لا تتم إزالة المخاطر","t":"إن تحديد المتوسط ​​الأسفل لا يزيل المخاطر - فهو ينقل المخاطر من \"العديد من الخسائر الصغيرة\" إلى \"خسارة واحدة كبيرة\". لا تضيف أبدًا أموالًا لا يمكنك خسارتها، ولا تقم أبدًا بإلغاء الحد الأقصى \"لاسترداد\" صفقة خاسرة."},{"h":"مسار الممارسة","t":"تعلم قراءة التقلبات على DEMO أولاً. جرب مارتينجال بحد أقصى يضيف 1-2 ومضاعف صغير على العرض التجريبي لأكثر من 30 صفقة. قم بتدوين كل سلم، ثم قرر - يجد معظم المتداولين أن الطريقة المسطحة / المضادة للمارتينجال أكثر أمانًا."},{"h":"التقلب + قائمة مراجعة مارتينجال","t":"① اقرأ مستوى التقلب أولاً ② تخطي أو تقلص إلى أقصى حد ③ مارتينجال فقط مع إشارة جديدة من نفس الجانب ④ تم الوصول إلى الخطوة × الدرجة ⑤ تحت سقف المخاطر → إضافة. أي \"لا\" → لا إضافة."}]},{"id":"lab_indicators","title":"15 · مؤشرات معمل الرسم البياني (Stoch · ADX · Ichimoku · VWAP)","summary":"يحتوي Chart Lab الآن على شريط مؤشرات كامل — كل زر عبارة عن علامة تشغيل/إيقاف تعمل على إعادة رسم المخطط على الفور. إلى جانب BB / RSI / MACD / EMA / SMA50 / Volume، يمكنك الآن الحصول على Stochastic وADX/DMI وIchimoku وVWAP، ويقرأها محرك الإشارة أيضًا - وليس الرسم البياني فقط.","lessons":[{"h":"أين يوجد البار","t":"معمل الرسم البياني → صف الأزرار \"المؤشرات\" الموجود أسفل الرسم البياني. نقرة واحدة تضيء المؤشر، والنقرة التالية تطفئه؛ يتم إعادة رسم المخطط على الفور. القراد مرئية وتغذي محرك الإشارة."},{"h":"مؤشر ستوكاستيك (14،3،3)","t":"مذبذب %K / %D المرسوم تحت الشموع بمقياس 0-100. فوق ~ 80 = منطقة ذروة الشراء، تحت ~ 20 = منطقة ذروة البيع. يعد عبور %K عبر %D في منطقة ذروة البيع بمثابة دراسة صعودية؛ التقاطع للأسفل في الأعلى هبوطي. في الاتجاه القوي، يمكن أن يظل مثبتًا عند أحد الأطراف لفترة طويلة - دائمًا ما يتم دمجه مع BB والشمعة."},{"h":"أدكس / دمي (14)","t":"يقيس ADX قوة الاتجاه، وليس الاتجاه. أعلى من ~25 = هناك اتجاه حقيقي قيد التنفيذ؛ أقل من ~20 = نطاق متقطع. + DI أعلى −DI = المشترين المسؤولين؛ −DI فوق +DI = البائعون المسؤولون. استخدم ADX لتقرر ما إذا كنت تريد التداول بالاتجاه على الإطلاق أو البقاء ثابتًا."},{"h":"سحابة إيشيموكو (9,26,52)","t":"تينكان (الخط السريع)، كيجون (الخط البطيء) وسحابة سينكو. السعر فوق السحابة الصاعدة = خلفية صعودية؛ تحت السحابة المتساقطة = هبوطي. تقاطع Tenkan/Kijun داخل السحابة ضعيف؛ التقاطع مع خروج السعر من السحابة أقوى. غالبًا ما تعمل حافة السحابة نفسها كدعم/مقاومة."},{"h":"VWAP","t":"متوسط السعر المرجح بالحجم — متوسط السعر المرجح بالحجم، يتم إعادة تعيينه في كل جلسة. المؤسسات الكبرى تقيس عمليات التعبئة لديها. السعر فوق VWAP المرتفع = المشترين المسيطرين؛ يعتبر الرفض النظيف لـ VWAP خلال الاتجاه الهبوطي بمثابة دراسة قصيرة. في العملات المشفرة التي تعمل على مدار 24 ساعة طوال أيام الأسبوع، يتم إعادة ضبطها بشكل مختلف عن العملات الأجنبية - تعامل معها كخط إرشادي، وليس كقانون."},{"h":"كيف يستخدمها المحرك","t":"يضيف كل مؤشر جديد تأكيدًا صغيرًا على النتيجة على نفس الجانب الذي يشير إليه (مؤشر ستوكاستيك، إيشيموكو، VWAP، ADX عندما يتفق مع الاتجاه، وإليوت). إنها تأكيدات، وليست محفزات - إذا اختلفوا مع BB / RSI / الشمعة، فإن النتيجة ببساطة تصبح أكثر تباينًا وتحصل على المزيد من الثبات."},{"h":"لماذا أصبح الحذر أكثر صرامة","t":"نظرًا لوجود المزيد من عمليات التحقق في المجموعة الآن، تم تشديد شريط التنبيه: فهو يحتاج إلى درجة ≥ 4 وما لا يقل عن 3 عمليات فحص موافقة. وهذا يمنع التطبيق من إغراقك بإشارات أضعف لمجرد وجود المزيد من الأدوات قيد التشغيل."},{"h":"أمر القراءة الذي يعمل","t":"① اتجاه TF العالي (سحابة إيشيموكو + ADX). ② حيث يكون السعر (BB / Fib / VWAP). ③ الزخم (مؤشر القوة النسبية + مؤشر ستوكاستيك). ④ تأكيد الشمعة. ⑤ نسبة المخاطر والمستويات المكتوبة ← الورقة أولاً."},{"h":"أخطاء يجب تجنبها","t":"تشغيل كل مؤشر والتحديق في قوس قزح؛ استخدام ADX كإتجاه (إنه قوة فقط)؛ البيع على المكشوف فقط لأن مؤشر ستوكاستيك >80 داخل موجة صعودية؛ تجاهل أن VWAP يعني أشياء مختلفة بين العملات المشفرة مقابل العملات الأجنبية."},{"h":"قائمة مراجعة الممارسة","t":"① الانحياز من السحابة + ADX ② الموقع من BB / Fib / VWAP ③ الزخم من RSI + Stoch ④ تأكيد الشمعة ⑤ SL / TP مكتوب ⑥ ورقة، ثم مجلة."}]},{"id":"elliott","title":"16 · موجة إليوت (عدد الضوء)","summary":"يشتمل CPE على عداد Elliott Wave خفيف الوزن. ضع علامة \"Elliott\" في شريط مؤشر Chart Lab وهو يحدد آخر موجة دافعة 0-1-2-3-4-5 على الشموع ويعرض هدف الموجة 5 فيبوناتشي. إنها أداة دراسة - وليست كرة بلورية.","lessons":[{"h":"الفكرة في سطر واحد","t":"تتحرك الأسواق في موجات: نبضات (5 أرجل في اتجاه الاتجاه) وتصحيحات (3 أرجل ضدها). يحسب CPE الدافع فقط، وهو الجزء الذي يحمل الاتجاه."},{"h":"كيف يحسبها CPE","t":"فهو يجد آخر محاور التأرجح (فركتلات 3 أشرطة)، ويتناوب بين الارتفاع والانخفاض، ويختبر آخر 5-6 تأرجحات وفقًا لقواعد إليوت. إذا كان الشكل مناسبًا، فإنه يرسم العلامات 0 → 5 (الموجة المستمرة باللون الأصفر) وخط الهدف W5 المبني من طول الموجة 1 × 1.618 المقاسة من الموجة 4."},{"h":"القواعد التي يتحقق منها","t":"الموجة 2 لا تتجاوز بداية الموجة 1؛ الموجة 4 لا تتداخل مع منطقة الموجة 1؛ الموجة 3 ليست الأقصر من 1 / 3 / 5. عندما تفشل القاعدة، فإنها لا تظهر شيئًا — لا يوجد عدد قسري."},{"h":"الصعودي مقابل الهبوطي","t":"ارتفاع 0-1-2-3-4-5 هو دفعة صعودية. الصورة المرآة في الطريق للأسفل هبوطية. يضيف المحرك تأكيدًا صغيرًا للنتيجة على جانب الموجة."},{"h":"مباشر مقابل كامل","t":"تُقرأ الموجة المباشرة 5 (التي لا تزال قيد التشغيل) على أنها استمرار للاتجاه. تحذر الموجة الدافعة الكاملة (من 0 إلى 5) من أن الاتجاه قد يكون مرهقًا - وغالبًا ما يتبعه تصحيح."},{"h":"خط الهدف W5","t":"امتداد فيبوناتشي للموجة 1 من الموجة 4 المنخفضة / المرتفعة. إنها فكرة مستهدفة، وليست مغناطيسًا - يمكن للسعر أن يتوقف عن الوصول إليها أو يتجاوزها."},{"h":"كيفية استخدامه","t":"تعامل مع العد على أنه نقطة التقاء: عند منطقة BB/Fib واضحة مع الشمعة ومؤشر القوة النسبية، يضيف العد المندفع قناعة. في حد ذاته هو مجرد رسم."},{"h":"أخطاء يجب تجنبها","t":"إعادة حساب الموجات حتى تناسب موقعك (خطيئة إليوت الكلاسيكية)؛ عد التذبذبات الصغيرة. تجاهل عدد الأطر الزمنية الأعلى؛ نسيان العدد يتغير في كل مرة يتم فيها طباعة شريط جديد."},{"h":"قائمة مراجعة الممارسة","t":"① تم اختيار تقلبات واضحة ② تمرير القواعد ③ يوافق Zig-zag مع BB / Fib ④ تأكيد الشمعة ⑤ SL بعد نقطة إبطال الموجة 4."}]},{"id":"forecast","title":"17 · توقعات لمدة 3 أشهر (علامة التنبؤ لمدة 3 أشهر)","summary":"جهاز عرض الأفق الطويل: كيف من المحتمل أن يتشكل هذا الرسم البياني خلال الأشهر الثلاثة القادمة تقريبًا، بناءً على اتجاه الإشارة وأهدافها وتقلباتها. قم بتشغيله أو إيقاف تشغيله باستخدام علامة \"Forecast 3M\" في Chart Lab.","lessons":[{"h":"ما يرسم","t":"مسار مركزي متقطع يمتد من المدخل الذي تم تحليله نحو أفضل هدف يعرفه المحرك بالفعل (هدف إليوت → tp2 → tp1)، ملفوف في \"مخروط\" متسع يوضح انتشار الأسعار المعقولة. علامات الشهر M+1 / M+2 / M+3 تقسم الأفق."},{"h":"لماذا مخروط وليس خط","t":"لا أحد يستطيع أن يعرف سعرًا محددًا في المستقبل. يتسع المخروط مع الجذر التربيعي للوقت وتقلب الزوج، لذلك يحصل زوج العملات الأجنبية الهادئ على مخروط ضيق والعملة البديلة الجامحة على مخروط واسع جدًا. هذا العرض هو الرسالة: كلما نظرت بعيدًا، كلما كان السعر أقل يقينًا."},{"h":"من أين تأتي الأرقام","t":"يأتي الانجراف من هدف الإشارة الحالي؛ يأتي التقلب اليومي من نسبة ATR٪ للإشارة والتي تم قياسها إلى يوم واحد، وبالتالي فإن المخروط يعني نفس الشيء على الرسم البياني 5 أمتار أو 1 دي؛ التقلبات الشديدة / العالية توسعها بشكل أكبر."},{"h":"كيفية قراءتها","t":"انظر إلى المنحدر (في أي اتجاه يميل المسار) والعرض (كم من الشك). مسار صاعد بمخروط ضيق = فكرة اتجاه أكثر ثباتًا؛ مسار مسطح بمخروط ضخم = \"لا توجد حافة هنا، توقع الضوضاء\"."},{"h":"تشغيله وإيقافه","t":"يوجد زر \"Forecast 3M\" بجوار \"Future space\". يحتاج إلى تشغيل مساحة المستقبل (المنطقة الفارغة على اليمين التي تم رسم الإسقاط فيها). إذا تم تعليق الإشارة فلا يوجد اتجاه، لذلك لا يتم رسم أي شيء."},{"h":"هذا هو الاتجاه، وليس التجارة","t":"التوقعات هي خريطة الصورة الكبيرة. مستويات التداول الفعلية - الدخول، TP1 / TP2، SL والتوقعات قصيرة المدى - لا تزال هي ما تتداول عليه."},{"h":"حدود صادقة","t":"الأخبار، والقوائم، والشطب، والتحولات الكلية ليست في النموذج؛ فالمسار عبارة عن انجراف سلس، لذا فإن الأسعار الحقيقية سوف تهتز بدرجة أكبر كثيرا؛ مخروط لمدة 3 أشهر هو وسيلة مساعدة للدراسة، وليس وعدًا أبدًا."},{"h":"إعادة التحليل في كثير من الأحيان","t":"مع ظهور شموع جديدة، يتم تحديث الهدف والتقلب وبالتالي المخروط بأكمله. التوقعات هي لقطة وليست عقدًا."},{"h":"قائمة مراجعة الممارسة","t":"① اقرأ اتجاه المسار ② تحقق من عرض المخروط ③ قارن مع هيكل TF الأعلى ④ قم بقياس الموضع من SL الحقيقي، وليس من المخروط أبدًا."}]}],"platforms":{"BINANCE":{"title":"تجارة بينانس أ → ي","steps":["إنشاء حساب → تمكين 2FA.","إدارة واجهة برمجة التطبيقات (API) → إنشاء مفتاح → تشغيل التداول الفوري و/أو العقود الآجلة، وإيقاف عمليات السحب.","الصق المفتاح + السر في CPE → مفاتيح API → Binance → حفظ → حساب تجريبي.","استخدم فحص Spot Desk / Futures Desk (تعمل المخططات العامة حتى قبل المفاتيح).","الممارسة: التجارة اليدوية → ابدأ تجارة الورق (بدون أموال حية).","مباشر: قم بتعيين TP1/TP2/SL + Trailing → بدء التداول المباشر (يحتاج إلى API).","إدارة المراكز: تعديل المستويات، الإغلاق الجزئي، الإلغاء التلقائي.","الترخيص: الإصدار التجريبي 7d → 3 أشهر أو مدى الحياة (أسعار المالك في التطبيق)."]},"BYBIT":{"title":"تجارة بايبيت أ → ي","steps":["الحساب + 2FA.","إدارة API → التداول فقط، إيقاف عمليات السحب.","CPE → مفاتيح API → Bybit → حفظ.","مكتب العقود الآجلة لعقلية الجناة. معمل الرسم البياني لدراسة الشموع.","تجارة الورق أولاً؛ العيش بعد عمل المفاتيح.","تريل TP + SL: شراء ↑ / بيع ↓."]},"OKX":{"title":"تجارة OKX أ → Z","steps":["مطلوب مفتاح واجهة برمجة التطبيقات + السر + عبارة المرور.","عمليات السحب مغلقة دائما.","احفظ الحقول الثلاثة في مفاتيح CPE.","ممارسة الورق → حجم حي صغير.","الأخطاء المطبعية في عبارة المرور هي الخطأ الأول - انسخها بعناية."]},"KUCOIN":{"title":"تجارة KuCoin أ → Z","steps":["المفتاح + السر + عبارة المرور.","إذن التجارة فقط.","الورق في CPE → ثم يعيش صغيرًا.","استخدم مكاتب Spot/Futures للإشارات."]},"BITGET":{"title":"تجارة Bitget أ → Z","steps":["API مع التجارة فقط.","ورقة ثم العيش.","العقود الآجلة: اختر الصليب أو المعزول في التجارة اليدوية.","Trail TP+SL لتأمين الأرباح."]},"GATE":{"title":"Gate.io Trading أ → Z","steps":["إنشاء مفاتيح API v4 (التجارة).","عمليات السحب معطلة.","احفظ في CPE → ورقة التدريب.","مسح + Chart Lab للإدخالات قبل البث المباشر."]},"MEXC":{"title":"تجارة MEXC أ → Z","steps":["ابدأ بعقلية Spot.","المفاتيح في مفاتيح واجهة برمجة تطبيقات CPE.","ورق → مباشر.","استخدم المسار لتأمين الربح المفتوح."]},"KRAKEN":{"title":"تجارة كراكن أ → ي","steps":["قم بإنشاء المفتاح بإذن تجاري فقط.","لا توجد حقوق سحب/أموال.","الممارسة الورقية في CPE.","تحقق من كل طلب مباشر على Kraken أيضًا."]},"COINBASE":{"title":"Coinbase المتقدم أ → Z","steps":["مفاتيح API للتجارة المتقدمة.","مكتب يركز على البقعة في CPE.","ورقة ثم العيش.","أبقِ عمليات السحب مغلقة."]},"FOREX_OANDA":{"title":"الفوركس (OANDA) أ → Z","steps":["افتح العرض التوضيحي لـ OANDA → المخاطرة ~1%.","رمز الوصول الشخصي + معرف الحساب في مفاتيح CPE.","فحص مكتب الفوركس + مختبر الرسم البياني (EURUSD...).","التجارة اليدوية → الورق مع منصة الفوركس.","عش فقط بعد الثقة التجريبية."]},"FOREX_FXCM":{"title":"FXCM فوركس أ → Z","steps":["بيانات اعتماد وسيط API.","الورق في CPE أولاً.","شاهد جلسات لندن/نيويورك وارتفاعات الأخبار.","تبدو مجلة Live بعد الممارسة نظيفة."]},"FOREX_MT5":{"title":"← أ → ي","steps":["تسجيل الدخول + الخادم + كلمة المرور في مفاتيح CPE.","تفضل (قراءة) كلمة مرور المستثمر حيثما أمكن ذلك.","ممارسة الكثير 0.01.","الورق في CPE؛ العيش عبر وسيط عندما تكون جاهزة."]},"FOREX_DEMO":{"title":"أسعار الفوركس التجريبية A → Z","steps":["لا يوجد مفتاح API مطلوب.","Forex Desk + Chart Lab للحصول على رسوم بيانية مجانية.","تجارة الورق فقط (ممارسة).","عندما تكون جاهزًا لوسيط حقيقي، قم بإضافة مفاتيح OANDA / FXCM / MT5 للبث المباشر."]}},"forexAz":{"title":"تجارة الفوركس من الألف إلى الياء (فئة كاملة)","lessons":[{"h":"أ - الحساب والمخاطر","t":"التجريبي أولا. المخاطرة ~ 0.5-1% لكل فكرة. لا تنتقم أبدًا من التجارة."},{"h":"ب – أزواج","t":"العملات الرئيسية (EURUSD، GBPUSD، USDJPY) قبل العملات النادرة."},{"h":"ج – الشموع","t":"تعلم دوجي، المطرقة، الانغماس في الرسم البياني مختبر الفوركس."},{"h":"د- التحيز اليومي","t":"تحقق من الإطار الزمني الأعلى قبل إدخالات 15 م/30 م."},{"h":"ه - الإدخالات","t":"يعتبر الارتداد السفلي لـ BB + تأكيد الشمعة من الممارسات الشائعة."},{"h":"ف - فيب","t":"غالبًا ما تستخدم عمليات التراجع بنسبة 50% / 61.8% كمناطق تدريب."},{"h":"G — الأهداف (TP)","t":"مقياس TP1، عداء TP2، مسار SL."},{"h":"ح – ساعات","t":"تداخل لندن-نيويورك = المزيد من الحركة."},{"h":"أنا - المؤشرات","t":"مؤشر القوة النسبية + MACD + BB معًا؛ تجنب الحمل الزائد للمؤشر."},{"h":"ي – مجلة","t":"قم بتسجيل كل ورقة/تداول مباشر في مجلة CPE."},{"h":"ك – المفاتيح","t":"يحتاج وسيط الفوركس المباشر إلى واجهة برمجة التطبيقات/الرمز المميز؛ المعدلات التجريبية لا تحتاج إلى أي شيء."},{"h":"ل – الكثير","t":"ابدأ بـ 0.01 لوت من خلال عقلية الممارسة."},{"h":"م – العقلية","t":"عملية أكثر من التنبؤ. تخطي الأيام السيئة."},{"h":"ن – أخبار","t":"تحقق من الأخبار والحيل قبل الأحداث الكبيرة."},{"h":"س – الأوامر","t":"قم دائمًا بتعيين SL. زائدة تحمي الربح المفتوح."},{"h":"ف - الممارسة","t":"زر تجارة الورق = التدريب بدون واجهة برمجة التطبيقات المباشرة."},{"h":"س - الجودة","t":"عدد أقل من الإعدادات عالية الجودة يتغلب على الإفراط في التداول."},{"h":"R - المخاطرة: المكافأة","t":"تهدف الأجهزة حيث المكافأة ≥ المخاطر عندما يكون ذلك ممكنا."},{"h":"س – الجلسات","t":"آسيا أكثر هدوءا؛ لندن/نيويورك أكثر نشاطا."},{"h":"تي - الاتجاهات","t":"تداول مع اتجاه TF الأعلى عند التعلم."},{"h":"ش - التحديثات","t":"شاهد شعار تحديث CPE + المساعدة المباشرة."},{"h":"الخامس - التقلب","t":"قم بتوسيع نطاق الصبر عندما يرتفع ATR."},{"h":"W — سحب واجهة برمجة التطبيقات (API).","t":"لا تقم مطلقًا بتمكين السحب على أي مفتاح API."},{"h":"X - يخرج","t":"درب TP + جزئي يدق على أمل."},{"h":"ص - خطتك","t":"كتابة القواعد؛ اتبعهم في يدوي/تلقائي."},{"h":"Z - الاندفاع صفر","t":"لا FOMO. تدرب → ثم واجهة برمجة التطبيقات المباشرة."}]}};
